#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// ADS1115 I2C address
#define ADS1115_ADDR 0x48

// ADS1115 register addresses
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERT 0x00

// Configuration register values
#define CONFIG_SINGLE_SHOT 0x8000  // Start single conversion
#define CONFIG_MUX_AIN0_GND 0x4000 // AIN0, GND
#define CONFIG_PGA_4_096V 0x0200   // +/- 4.096V
#define CONFIG_DR_128SPS 0x0080    // 128 SPS
#define CONFIG_MODE_SINGLE 0x0100  // Single-shot mode
#define CONFIG_OS_SINGLE 0x8000

// Sensitivity of MLX91219 (example value, check datasheet)
#define MLX91219_SENSITIVITY 0.1 // Amperes per Volt

// Global variable for I2C handle
int i2c_handle;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("\nCtrl+C pressed. Cleaning up and exiting...\n");
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

// Function to read current from MLX91219
float read_mlx91219_current() {
    uint16_t config;
    int16_t conversion;
    float current;

    // Configure ADS1115 for single-shot conversion
    config = CONFIG_SINGLE_SHOT | CONFIG_MUX_AIN0_GND | CONFIG_PGA_4_096V | CONFIG_DR_128SPS | CONFIG_MODE_SINGLE;

    // Write configuration to ADS1115
    char buf[3];
    buf[0] = ADS1115_REG_CONFIG;
    buf[1] = (config >> 8) & 0xFF; // MSB
    buf[2] = config & 0xFF;        // LSB

    if (i2cWriteDevice(i2c_handle, buf, 3) != 0) {
        fprintf(stderr, "Error writing to ADS1115 configuration register.\n");
        return -1.0; // Indicate error
    }

    // Wait for conversion to complete (at least 8ms for 128 SPS)
    gpioDelay(10000); // 10 ms

    // Read conversion result from ADS1115
    char read_buf[2];
    if (i2cReadDevice(i2c_handle, read_buf, 2) != 2) {
        fprintf(stderr, "Error reading from ADS1115 conversion register.\n");
        return -1.0; // Indicate error
    }

    // Combine MSB and LSB to get 16-bit conversion result
    conversion = (read_buf[0] << 8) | read_buf[1];

    // Convert to amperes
    current = (float)conversion * MLX91219_SENSITIVITY / 32768.0; // 32768 is the max value for 16-bit signed integer

    return current;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        float current = read_mlx91219_current();

        if (current >= 0) {
            printf("Current: %.3f A\n", current);
        } else {
            fprintf(stderr, "Error reading current.\n");
        }

        gpioDelay(500000); // 500 ms
    }

    // The following lines will never be reached because of the infinite loop.
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

