#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define FLAME_SENSOR_PIN 4
#define MCP3008_CE0 8

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz

// Global variables
int spi_handle;
FILE *fp;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_flame_sensor();
int read_mcp3008(int channel);
float calculate_temperature(int adc_value);
void log_data(int flame_detected, float temperature);
void signal_handler(int signal);
int initialize();
void cleanup();

// Structure to hold configuration data
typedef struct {
    int flame_pin;
    int mcp3008_ce;
    int spi_channel;
    int spi_baud;
    char *log_file;
} Config;

Config config = {FLAME_SENSOR_PIN, MCP3008_CE0, SPI_CHANNEL, SPI_BAUD, "flame_data.csv"};

// Function to initialize the pigpio library and SPI
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(config.flame_pin, PI_INPUT);
    gpioSetMode(config.mcp3008_ce, PI_OUTPUT);
    gpioWrite(config.mcp3008_ce, 1); // Ensure CE0 is initially high

    spi_handle = spiOpen(config.spi_channel, config.spi_baud, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    fp = fopen(config.log_file, "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Function to read the flame sensor's digital output
int read_flame_sensor() {
    return gpioRead(config.flame_pin);
}

// Function to read the MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel\n");
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel selection
    tx_buffer[2] = 0x00;

    gpioWrite(config.mcp3008_ce, 0); // Select MCP3008
    spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    gpioWrite(config.mcp3008_ce, 1); // Deselect MCP3008

    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to calculate temperature from ADC value (linear approximation)
float calculate_temperature(int adc_value) {
    // Assuming a linear relationship between ADC value and temperature.
    // This is a simplified example and may need calibration for your specific setup.
    // The formula is: temperature = (adc_value / max_adc_value) * max_temperature
    // You'll need to determine max_adc_value and max_temperature based on your sensor.
    float max_adc_value = 1023.0; // Assuming 10-bit ADC
    float max_temperature = 50.0;  // Example: 0-50 degrees Celsius
    return (adc_value / max_adc_value) * max_temperature;
}

// Function to log data to a CSV file
void log_data(int flame_detected, float temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s,%d,%.2f\n", timestamp, flame_detected, temperature);
    fflush(fp); // Ensure data is written to file immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Function to cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (fp != NULL) {
        fclose(fp);
    }
    gpioTerminate();
}

int main() {
    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    if (initialize()) {
        return 1;
    }

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int flame_detected = read_flame_sensor();
        int adc_value = read_mcp3008(0);
        float temperature = calculate_temperature(adc_value);

        if (adc_value == -1) {
            fprintf(stderr, "Error reading MCP3008, skipping entry\n");
        } else {
            log_data(flame_detected, temperature);
        }

        gpioDelay(1000); // Wait for 1 second
    }

    cleanup();
    return 0;
}

