#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <wiringPi.h>
#include <wiringPiI2C.h>

// Constants
#define FLAME_SENSOR_PIN 4
#define BUZZER_PIN 27
#define ADS1115_I2C_ADDR 0x48
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERT 0x00
#define TEMP_THRESHOLD 60.0
#define LOG_FILE "fire_log.txt"

// Global variables
volatile sig_atomic_t running = 1;
int i2c_fd;
FILE *log_file;

// Function prototypes
int init_gpio();
int init_i2c();
int init_ads1115();
int read_temperature();
bool is_fire_detected(int flame_state, int temp_state);
void activate_buzzer();
void log_event(const char *message);
void signal_handler(int signal);
void cleanup();

// Function to initialize GPIO pins
int init_gpio() {
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "Error initializing wiringPi: %s\n", strerror(errno));
        return -1;
    }

    pinMode(FLAME_SENSOR_PIN, INPUT);
    pinMode(BUZZER_PIN, OUTPUT);
    digitalWrite(BUZZER_PIN, LOW); // Ensure buzzer is off initially
    return 0;
}

// Function to initialize I2C communication
int init_i2c() {
    i2c_fd = wiringPiI2CSetup(ADS1115_I2C_ADDR);
    if (i2c_fd == -1) {
        fprintf(stderr, "Error initializing I2C: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to initialize ADS1115
