#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_SPEED 1000000 // 1 MHz
#define FAN_GPIO 18
#define CURRENT_THRESHOLD 1000 // Example threshold
#define LOG_FILE "current_log.txt"

// Global variables
int spi_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_init(const char *device, int mode, int speed);
int spi_transfer(int fd, unsigned char *tx_buf, unsigned char *rx_buf, int len);
int read_mcp3008(int fd, int channel);
float adc_to_current(int adc_value);
int gpio_init(int gpio_pin);
int gpio_set_output(int gpio_pin, int value);
int log_current(float current);
void signal_handler(int signal);

// SPI Initialization
int spi_init(const char *device, int mode, int speed) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Set SPI mode
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    // Set SPI speed
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Error setting SPI speed");
        close(fd);
        return -1;
    }

    return fd;
}

// SPI Transfer
int spi_transfer(int fd, unsigned char *tx_buf, unsigned char *rx_buf, int len) {
    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = len,
        .speed_hz = SPI_SPEED,
        .delay_usecs = 0,
        .bits_per_word = 8,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &transfer) < 0) {
        perror("Error during SPI transfer");
        return -1;
    }

    return 0;
}

// Read MCP3008 Channel
int read_mcp3008(int fd, int channel) {
    unsigned char tx_buf[3];
    unsigned char rx_buf[3];

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel << 4)); // Single-ended mode, channel select
    tx_buf[2] = 0x00; // Don't care

    if (spi_transfer(fd, tx_buf, rx_buf, 3) < 0) {
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// ADC to Current Conversion
float adc_to_current(int adc_value) {
    // Assuming a linear relationship between ADC value and current
    // and a known current sensitivity (e.g., 10mV per Ampere)
    // This is a placeholder; replace with the actual sensor characteristics
    float current = (float)adc_value * 0.01; // Example conversion
    return current;
}

// GPIO Initialization
int gpio_init(int gpio_pin) {
    if (gpioSetMode(gpio_pin, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", gpio_pin);
        return -1;
    }
    return 0;
}

// GPIO Set Output
int gpio_set_output(int gpio_pin, int value) {
    if (gpioWrite(gpio_pin, value) != 0) {
        fprintf(stderr, "Error setting GPIO %d to value %d\n", gpio_pin, value);
        return -1;
    }
    return 0;
}

// Log Current Reading
int log_current(float current) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, %.2f\n", timestamp, current);
        fflush(log_file); // Ensure data is written to disk
        return 0;
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }
}

// Signal Handler
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize SPI
    spi_fd = spi_init(SPI_DEVICE, SPI_MODE, SPI_SPEED);
    if (spi_fd < 0) {
        fprintf(stderr, "SPI initialization failed. Exiting.\n");
        return 1;
    }

    // Initialize GPIO
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed. Exiting.\n");
        close(spi_fd);
        return 1;
    }

    if (gpio_init(FAN_GPIO) < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        close(spi_fd);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(spi_fd);
        gpioTerminate();
        return 1;
    }

    printf("Current monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(spi_fd, 0); // Channel 0
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value. Retrying...\n");
            sleep(1); // Wait before retrying
            continue;
        }

        // Check for sensor absence condition
        if (adc_value == 0 || adc_value == 1023) {
            fprintf(stderr, "Sensor absent or damaged. ADC value: %d\n", adc_value);
            log_current(-999.0); // Log a special value
        } else {
            // Convert ADC value to current
            float current = adc_to_current(adc_value);

            // Log current reading
            if (log_current(current) != 0) {
                fprintf(stderr, "Error logging current reading.\n");
            }

            // Control fan based on current threshold
            if (current > CURRENT_THRESHOLD) {
                gpio_set_output(FAN_GPIO, 1); // Turn fan ON
            } else {
                gpio_set_output(FAN_GPIO, 0); // Turn fan OFF
            }
        }

        sleep(1); // Sample every 1 second
    }

    // Cleanup
    printf("Cleaning up...\n");
    if (spi_fd != -1) {
        close(spi_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpio_set_output(FAN_GPIO, 0); // Ensure fan is OFF
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

