            float current = adc_to_current(adc_value);

            // Log current reading
            if (log_current(current) != 0) {
                fprintf(stderr, "Error logging current reading.\n");
            }

            // Control fan based on current threshold
            if (current > CURRENT_THRESHOLD) {
                gpio_set_output(FAN_GPIO, 1); // Turn fan ON
            } else {
                gpio_set_output(FAN_GPIO, 0); // Turn fan OFF
            }
        }

        sleep(1); // Sample every 1 second
    }

