// Constants
#define I2C_BUS 1
#define I2C_ADDR 0x48 // ADS1115 address
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERT 0x00
#define ADS1115_CONFIG_DEFAULT 0x4003 // Single-shot mode, AIN0, +/-4.096V, 128 SPS
#define ADC_RESOLUTION 16384.0 // 2^14
#define LOG_FILE "co_log.txt"

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure for calibration data
typedef struct {
    float slope;
    float intercept;
} CalibrationData;

// Function prototypes
int initialize_i2c();
int read_adc(int i2c_handle);
float convert_to_resistance(int raw_value);
float calculate_ppm(float resistance);
int log_ppm(float ppm);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// I2C initialization function
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read ADC value from ADS1115
int read_adc(int i2c_handle) {
    char config[3];
    char data[2];
    int16_t raw_value;

    // Configure ADS1115 for single conversion
    config[0] = ADS1115_REG_CONFIG;
    config[1] = (ADS1115_CONFIG_DEFAULT >> 8) & 0xFF;
    config[2] = ADS1115_CONFIG_DEFAULT & 0xFF;

    if (i2cWriteDevice(i2c_handle, config, 3) != 0) {
        fprintf(stderr, "Error writing to I2C device\n");
        return -1;
    }

    // Wait for conversion to complete (at least 8ms for 128 SPS)
    gpioDelay(10000); // 10ms

    // Read conversion result
    config[0] = ADS1115_REG_CONVERT;
    if (i2cWriteDevice(i2c_handle, config, 1) != 0) {
        fprintf(stderr, "Error writing to I2C device\n");
        return -1;
    }

    if (i2cReadDevice(i2c_handle, data, 2) != 2) {
        fprintf(stderr, "Error reading from I2C device\n");
        return -1;
    }

    raw_value = (data[0] << 8) | data[1];
    return raw_value;
}

