float calculate_ppm(float resistance) {
    // Logarithmic calibration curve (example)
    // You'll need to calibrate this based on your sensor's datasheet
    // and experimental data.
    float log_ppm = 0.5 * log10(resistance / 1000.0) + 1.0; // Example curve
    return pow(10, log_ppm);
}

