int log_ppm(float ppm) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file\n");
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char s[64];
    strftime(s, sizeof(s), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, %.2f ppm\n", s, ppm);
    fclose(fp);
    return 0;
}

// Cleanup function to release resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        cleanup();
        return 1;
    }

    printf("CO sensor monitoring started...\n");

    while (!terminate) {
        // Read ADC value
        int raw_value = read_adc(i2c_handle);
        if (raw_value < 0) {
            fprintf(stderr, "Error reading ADC value\n");
            continue; // Skip to the next iteration
        }

        // Convert to resistance
        float resistance = convert_to_resistance(raw_value);

        // Calculate CO concentration
        float ppm = calculate_ppm(resistance);

        // Log CO concentration
        if (log_ppm(ppm) != 0) {
            fprintf(stderr, "Error logging CO concentration\n");
        }

        printf("CO concentration: %.2f ppm\n", ppm);

        // Wait for 5 seconds
        sleep(5);
    }

    // Cleanup and exit
    cleanup();
    printf("CO sensor monitoring stopped.\n");
    return 0;
}

