#define MCP3008_SCLK 11
#define MCP3008_MOSI 10
#define MCP3008_MISO 9

// Define SPI channel
#define SPI_CHANNEL 0

// Define SPI speed
#define SPI_SPEED 1000000 // 1 MHz

// Define MCP3008 channel for temperature sensor
#define MCP3008_TEMP_CHANNEL 0

// Global variables
int spi_handle;
FILE *fp;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_flame_sensor();
int read_mcp3008(int channel);
float convert_to_temperature(int adc_value);
int log_data(int flame_detected, float temperature);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read the flame sensor
int read_flame_sensor() {
    return gpioRead(FLAME_SENSOR_PIN);
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char spi_tx_buf[3];
    char spi_rx_buf[3];

    // Construct SPI message
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    // Transfer SPI data
    int spi_result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (spi_result != 0) {
        fprintf(stderr, "Error: SPI transfer failed with code %d\n", spi_result);
        return -1;
    }

    // Extract ADC value
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];
    return adc_value;
}

// Function to convert ADC value to temperature (Celsius)
float convert_to_temperature(int adc_value) {
    // Assuming a linear relationship between ADC value and temperature
    // This is a placeholder; you'll need to calibrate your sensor
    // and determine the correct conversion formula.
    // Example: 0 ADC = 0°C, 1023 ADC = 100°C
    float temperature = (adc_value / 1023.0) * 100.0;
    return temperature;
}

