    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT);
    gpioSetMode(MCP3008_CE0, PI_OUTPUT);
    gpioSetMode(MCP3008_SCLK, PI_OUTPUT);
    gpioSetMode(MCP3008_MOSI, PI_OUTPUT);
    gpioSetMode(MCP3008_MISO, PI_INPUT);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // SPI channel 0, 1MHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed with code %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open CSV file for logging
    fp = fopen("flame_data.csv", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Failed to open flame_data.csv for writing\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Flame sensor and temperature logging started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read flame sensor
        int flame_detected = read_flame_sensor();

        // Read temperature sensor
        int adc_value = read_mcp3008(MCP3008_TEMP_CHANNEL);
        if (adc_value == -1) {
            fprintf(stderr, "Error: Failed to read temperature sensor\n");
            continue; // Skip to the next iteration
        }

        // Convert ADC value to temperature
        float temperature = convert_to_temperature(adc_value);

        // Log data
        if (log_data(flame_detected, temperature) != 0) {
            fprintf(stderr, "Error: Failed to log data\n");
        }

        // Wait for 1 second
        gpioDelay(1000); // pigpio's delay function
    }

    // Close SPI channel and CSV file
    spiClose(spi_handle);
    fclose(fp);

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

