// Define GPIO pins for the microphones
#define MIC1_GPIO 2
#define MIC2_GPIO 3

// Define the log file name
#define LOG_FILE "audio_log.txt"

// Global variables for signal handling
volatile sig_atomic_t program_running = 1;
FILE *log_file = NULL;

// Structure to hold microphone data
typedef struct {
    int gpio;
    float (*read_level)(int gpio);
} Microphone;

// Function prototypes
float read_microphone_level(int gpio);
float calculate_average_level(float mic1_level, float mic2_level);
void log_data(float average_level);
void signal_handler(int signal);

// Function to read the analog level from a microphone
float read_microphone_level(int gpio) {
    // Read the digital value from the GPIO pin
    int digital_value = gpioRead(gpio);

    // Convert the digital value to a voltage (assuming 3.3V reference)
    float voltage = (float)digital_value * 3.3;

    // Convert the voltage to a sound pressure level (dB)
    // This is a simplified conversion; a real implementation would require
    // a calibration curve specific to the IMP23ABSU microphone.
    float level = 20 * log10(voltage / 0.00002); // Example conversion

    return level;
}

// Function to calculate the average sound pressure level
float calculate_average_level(float mic1_level, float mic2_level) {
    return (mic1_level + mic2_level) / 2.0;
}

// Function to log the data to a file
void log_data(float average_level) {
    // Get the current time
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    // Open the log file in append mode
    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            perror("Error opening log file");
            return;
        }
    }

    // Write the timestamp and average level to the log file
    fprintf(log_file, "%s, %.2f dB\n", timestamp, average_level);

    // Close the log file
    fclose(log_file);
    log_file = NULL; // Reset the global pointer
}

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);

    // Close the log file if it's open
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate the pigpio library
    gpioTerminate();

    exit(0);
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set the GPIO pins as inputs
    gpioSetMode(MIC1_GPIO, PI_INPUT);
    gpioSetMode(MIC2_GPIO, PI_INPUT);

    // Register the signal handler functions
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Create microphone objects
    Microphone mic1 = {MIC1_GPIO, read_microphone_level};
    Microphone mic2 = {MIC2_GPIO, read_microphone_level};

    // Main loop
    while (program_running) {
        // Read the sound pressure levels from the microphones
        float mic1_level = mic1.read_level(mic1.gpio);
        float mic2_level = mic2.read_level(mic2.gpio);

        // Calculate the average level
        float average_level = calculate_average_level(mic1_level, mic2_level);

        // Log the data
        log_data(average_level);

        // Wait for 100 milliseconds
        gpioDelay(100000); // 100 ms = 100000 microseconds
    }

    // Terminate the pigpio library
    gpioTerminate();

    return 0;
}

