#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define LED_PIN 27
#define SPI_CE0 8
#define SPI_CE1 9

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz

// Define RMS threshold
#define RMS_THRESHOLD 500

// Define sampling window
#define SAMPLE_WINDOW_MS 100
#define SAMPLE_RATE 1000 // Hz
#define NUM_SAMPLES (SAMPLE_WINDOW_MS * SAMPLE_RATE) / 1000

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Structure to hold microphone data
typedef struct {
    int mic1_data[NUM_SAMPLES];
    int mic2_data[NUM_SAMPLES];
    int index;
} MicrophoneData;

MicrophoneData microphone_data = {{0}, {0}, 0};

// Function prototypes
int initialize_spi();
int read_mcp3008(int channel);
double calculate_rms(int *data, int num_samples);
void log_data(double mic1_rms, double mic2_rms);
void control_led(double mic1_rms, double mic2_rms);
void signal_handler(int signal);
void cleanup();

// Function to initialize SPI
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00;

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) != 0) {
        fprintf(stderr, "SPI transfer error\n");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to calculate RMS
double calculate_rms(int *data, int num_samples) {
    double sum_of_squares = 0.0;
    for (int i = 0; i < num_samples; i++) {
        sum_of_squares += (double)data[i] * data[i];
    }
    double mean_square = sum_of_squares / num_samples;
    return sqrt(mean_square);
}

// Function to log data to file
void log_data(double mic1_rms, double mic2_rms) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, mic1_rms, mic2_rms);
    fflush(log_file); // Ensure data is written to file immediately
}

// Function to control LED based on RMS threshold
void control_led(double mic1_rms, double mic2_rms) {
    if (mic1_rms > RMS_THRESHOLD || mic2_rms > RMS_THRESHOLD) {
        gpioWrite(LED_PIN, 1); // Turn LED on
        gpioDelay(500);        // Wait 500ms
        gpioWrite(LED_PIN, 0); // Turn LED off
    }
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(LED_PIN, 0); // Turn LED off
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set LED pin as output
    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0); // Initially turn LED off

    // Initialize SPI
    if (initialize_spi() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("audio_events.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return 1;
    }

    // Write header to log file if it's a new file
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Mic1_RMS,Mic2_RMS\n");
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Audio monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read microphone data
        int mic1_value = read_mcp3008(0);
        int mic2_value = read_mcp3008(1);

        if (mic1_value < 0 || mic2_value < 0) {
            fprintf(stderr, "Error reading microphone data\n");
            continue; // Skip to the next iteration
        }

        // Store data in circular buffer
        microphone_data.mic1_data[microphone_data.index] = mic1_value;
        microphone_data.mic2_data[microphone_data.index] = mic2_value;
        microphone_data.index = (microphone_data.index + 1) % NUM_SAMPLES;

        // Calculate RMS if we have enough samples
        if (microphone_data.index == 0) {
            double mic1_rms = calculate_rms(microphone_data.mic1_data, NUM_SAMPLES);
            double mic2_rms = calculate_rms(microphone_data.mic2_data, NUM_SAMPLES);

            // Log data
            log_data(mic1_rms, mic2_rms);

            // Control LED
            control_led(mic1_rms, mic2_rms);
        }

        gpioDelay(1); // Sample every 1 ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

