#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// TCS34725 I2C address
#define TCS34725_ADDRESS 0x29

// TCS34725 registers
#define TCS34725_ENABLE 0x80
#define TCS34725_ATIME 0x81
#define TCS34725_ID 0x12
#define TCS34725_CDATA 0x90
#define TCS34725_RDATA 0x92
#define TCS34725_GDATA 0x94
#define TCS34725_BDATA 0x96

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_sensor();
int read_color_data(unsigned int *clear, unsigned int *red, unsigned int *green, unsigned int *blue);
int log_data(unsigned int clear, unsigned int red, unsigned int green, unsigned int blue);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Signal received, cleaning up...\n");
}

// Function to initialize the TCS34725 sensor
int initialize_sensor() {
    // Enable the sensor (power on and enable RGBC)
    if (i2cWriteByteData(i2c_handle, TCS34725_ENABLE, 0x03) < 0) {
        fprintf(stderr, "Error: Failed to enable sensor\n");
        return -1;
    }

    // Set integration time (ATIME) - adjust as needed
    if (i2cWriteByteData(i2c_handle, TCS34725_ATIME, 0xD5) < 0) { // 101ms integration time
        fprintf(stderr, "Error: Failed to set integration time\n");
        return -1;
    }

    // Verify sensor ID
    int sensor_id = i2cReadByteData(i2c_handle, TCS34725_ID);
    if (sensor_id < 0) {
        fprintf(stderr, "Error: Failed to read sensor ID\n");
        return -1;
    }
    if (sensor_id != 0x44) {
        fprintf(stderr, "Error: Incorrect sensor ID: 0x%02X\n", sensor_id);
        return -1;
    }

    return 0;
}

// Function to read color data from the sensor
int read_color_data(unsigned int *clear, unsigned int *red, unsigned int *green, unsigned int *blue) {
    unsigned char data[8];
    int result;

    result = i2cReadI2CBlockData(i2c_handle, TCS34725_CDATA, (char *)data, 8);
    if (result < 0) {
        fprintf(stderr, "Error: Failed to read color data\n");
        return -1;
    }

    *clear = (data[1] << 8) | data[0];
    *red   = (data[3] << 8) | data[2];
    *green = (data[5] << 8) | data[4];
    *blue  = (data[7] << 8) | data[6];

    return 0;
}

// Function to log data to a CSV file
int log_data(unsigned int clear, unsigned int red, unsigned int green, unsigned int blue) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%u,%u,%u,%u\n", timestamp, clear, red, green, blue);
    fflush(log_file);

    return 0;
}

// Function to cleanup resources
void cleanup() {
    printf("Cleaning up resources...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(1, TCS34725_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device\n");
        cleanup();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor() != 0) {
        fprintf(stderr, "Error: Sensor initialization failed\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("color_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        cleanup();
        return 1;
    }

    // Write header row if the file is new
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,clear,red,green,blue\n");
    }
    rewind(log_file);

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    unsigned int clear, red, green, blue;
    int consecutive_failures = 0;

    // Main loop
    while (!terminate) {
        if (read_color_data(&clear, &red, &green, &blue) == 0) {
            log_data(clear, red, green, blue);
            consecutive_failures = 0; // Reset failure count
        } else {
            fprintf(stderr, "Error: Failed to read color data, retrying...\n");
            consecutive_failures++;
            if (consecutive_failures >= 3) {
                fprintf(stderr, "Error: Too many consecutive I2C failures, exiting\n");
                break;
            }
        }

        // Non-blocking sleep for 1 second
        struct timespec req, rem;
        req.tv_sec = 1;
        req.tv_nsec = 0;
        nanosleep(&req, &rem);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

