    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f\n", timestamp, current);
    fflush(log_file); // Ensure data is written to disk immediately
}

void check_overcurrent(float current) {
    if (current > config.current_threshold) {
        printf("Overcurrent detected: %.2f A\n", current);
        time_t rawtime;
        struct tm *timeinfo;
        char timestamp[20];

        time(&rawtime);
        timeinfo = localtime(&rawtime);

        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        fprintf(log_file, "%s,Overcurrent: %.2f A\n", timestamp, current);
        fflush(log_file);

        gpioWrite(config.motor_gpio, 0); // Disable motor
        sleep(1);
        gpioWrite(config.motor_gpio, 1); // Re-enable motor
    }
}

void signal_handler(int signal) {
    printf("Signal received (%d). Terminating...\n", signal);
    terminate = 1;
}

