#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define MLX90817_ADDR 0x60
#define PRESSURE_REG 0x00 // Example register address
#define LOG_FILE "pressure_log.csv"
#define RETRY_COUNT 3

// Global variables
int i2c_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure for sensor data
typedef struct {
    double pressure_kPa;
    char timestamp[32];
} sensor_data_t;

// Function prototypes
int init_i2c();
int read_pressure(double *pressure);
int log_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, MLX90817_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read pressure from the sensor
int read_pressure(double *pressure) {
    char buf[2];
    int result;
    int retries = 0;

    while (retries < RETRY_COUNT) {
        result = i2cReadI2CBlockData(i2c_handle, PRESSURE_REG, buf, 2);
        if (result == 2) {
            // Convert raw data to pressure (example conversion)
            *pressure = (double)((buf[0] << 8) | buf[1]) * 0.1; // kPa
            return 0; // Success
        } else {
            fprintf(stderr, "Error reading pressure (attempt %d): %d\n", retries + 1, result);
            retries++;
            gpioDelay(10000); // 10ms delay
        }
    }

    fprintf(stderr, "Failed to read pressure after %d retries.\n", RETRY_COUNT);
    return -1; // Failure
}

// Function to log data to a file
int log_data(sensor_data_t data) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s,%.2f\n", data.timestamp, data.pressure_kPa);
    fflush(log_file); // Flush the buffer to ensure data is written
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function to close resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        fprintf(stderr, "I2C handle closed.\n");
    }
    if (log_file != NULL) {
        fclose(log_file);
        fprintf(stderr, "Log file closed.\n");
    }
    gpioTerminate();
    fprintf(stderr, "pigpio terminated.\n");
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        cleanup();
        return 1;
    }

    // Write the header row if the file is new
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,pressure_kPa\n");
        fflush(log_file);
    }

    // Main loop
    while (!terminate) {
        sensor_data_t data;
        double pressure;

        // Read pressure
        if (read_pressure(&pressure) == 0) {
            // Get current timestamp
            time_t rawtime;
            struct tm *timeinfo;
            time(&rawtime);
            timeinfo = gmtime(&rawtime);
            strftime(data.timestamp, sizeof(data.timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

            // Store pressure data
            data.pressure_kPa = pressure;

            // Log the data
            if (log_data(data) != 0) {
                fprintf(stderr, "Error logging data.\n");
            }
        } else {
            fprintf(stderr, "Failed to read pressure.\n");
        }

        sleep(1); // Wait for 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

