int init_i2c() {
    i2c_handle = i2cOpen(1, ADS1115_ADDR, 0); // Bus 1, address 0x48, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }

    // Configure ADS1115 for single-ended mode, AIN0 and AIN1, 4.096V, 128 SPS
    uint16_t config = 0x4003; // Single shot mode, AIN0, +/-4.096V, 128 SPS
    char buf[3];
    buf[0] = ADS1115_CONFIG_REG;
    buf[1] = (config >> 8) & 0xFF;
    buf[2] = config & 0xFF;

    int result = i2cWriteDevice(i2c_handle, buf, 3);
    if (result != 0) {
