#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0
#define MOTOR_CONTROL_PIN 27
#define OVERCURRENT_THRESHOLD 10.0 // Amperes
#define ADC_MAX_VALUE 1023.0
#define VREF 3.3 // Volts
#define SENSITIVITY 0.004 // Amperes/Volt (example value, check datasheet)
#define LOG_FILE "current_log.txt"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float adc_to_current(int adc_value);
void log_current(float current);
void control_motor(float current);
void signal_handler(int signal);
int initialize();
void cleanup();

// Structure for configuration (optional)
typedef struct {
    int spi_channel;
    int spi_speed;
    int spi_mode;
    int motor_pin;
    float overcurrent_threshold;
} Config;

Config config = {SPI_CHANNEL, SPI_SPEED, SPI_MODE, MOTOR_CONTROL_PIN, OVERCURRENT_THRESHOLD};

int main() {
    if (initialize() != 0) {
        fprintf(stderr, "Initialization failed. Exiting.\n");
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (!terminate) {
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value. Retrying.\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        float current = adc_to_current(adc_value);
        log_current(current);
        control_motor(current);

        gpioDelay(100); // Sample every 100 ms
    }

    cleanup();
    return 0;
}

int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(config.motor_pin, PI_OUTPUT);
    gpioWrite(config.motor_pin, 0); // Initially off

    spi_handle = spiOpen(config.spi_channel, config.spi_speed, config.spi_mode);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    return 0;
}

void cleanup() {
    printf("Cleaning up...\n");
    gpioWrite(config.motor_pin, 0); // Turn off motor
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();
}

int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel\n");
        return -1;
    }

    unsigned char spi_data[3];
    spi_data[0] = 0x01; // Start bit
    spi_data[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_data[2] = 0x00;

    char rx_buffer[3];

    int result = spiXfer(spi_handle, spi_data, rx_buffer, 3);
    if (result != 3) {
        fprintf(stderr, "SPI transfer failed: %d\n", result);
        return -1;
    }

    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

float adc_to_current(int adc_value) {
    if (adc_value < 0 || adc_value > 1023) {
        fprintf(stderr, "Invalid ADC value: %d\n", adc_value);
        return 0.0; // Or some other error value
    }

    float voltage = (float)adc_value / ADC_MAX_VALUE * VREF;
    float current = voltage / SENSITIVITY;
    return current;
}

void log_current(float current) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Current: %.2f A\n", timestamp, current);
    fflush(log_file); // Ensure data is written to file immediately
}

void control_motor(float current) {
    if (current > config.overcurrent_threshold) {
        time_t rawtime;
        struct tm *timeinfo;
        char timestamp[80];

        time(&rawtime);
        timeinfo = localtime(&rawtime);

        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        fprintf(log_file, "%s, OVERCURRENT: %.2f A\n", timestamp, current);
        fflush(log_file);
        fprintf(stderr, "OVERCURRENT: %.2f A\n", current);

        gpioWrite(config.motor_pin, 0); // Turn off motor
        terminate = 1; // Stop the main loop
    } else {
        gpioWrite(config.motor_pin, 1); // Turn on motor
    }
}

void signal_handler(int signal) {
    printf("Signal received (%d). Terminating...\n", signal);
    terminate = 1;
}

