#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define ADS1115_CONFIG_REG 0x01
#define ADS1115_CONVERSION_REG 0x00
#define ADS1115_FULL_SCALE_VOLTAGE 4.096 // +/- 4.096V
#define ADS1115_SAMPLE_RATE 1 // Hz
#define PRESSURE_MIN 0.0
#define PRESSURE_MAX 100.0
#define LOG_FILE "pressure_log.txt"

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int16_t read_adc();
float convert_to_pressure(int16_t adc_value);
int validate_pressure(float pressure);
int log_pressure(float pressure);
void signal_handler(int signal);

// Structure for ADS1115 configuration
typedef struct {
    uint16_t config;
} ads1115_config_t;

// Function to initialize the I2C bus
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }

    // Configure ADS1115 for single-ended AIN0, +/-4.096V, 128 SPS, single-shot mode
    ads1115_config_t config;
    config.config = 0x4003; // 0b0100000000000011
    char buf[3];
    buf[0] = ADS1115_CONFIG_REG;
    buf[1] = (config.config >> 8) & 0xFF;
    buf[2] = config.config & 0xFF;

    int result = i2cWriteDevice(i2c_handle, buf, 3);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        i2cClose(i2c_handle);
        return -1;
    }

    return 0;
}

// Function to read the ADC value from the ADS1115
int16_t read_adc() {
    char buf[1];
    buf[0] = ADS1115_CONVERSION_REG;

    int result = i2cWriteDevice(i2c_handle, buf, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C device (conversion reg select): %d\n", result);
        return -1;
    }

    char read_buf[2];
    result = i2cReadDevice(i2c_handle, read_buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1;
    }

    int16_t adc_value = (read_buf[0] << 8) | read_buf[1];
    return adc_value;
}

// Function to convert the ADC value to pressure (kPa)
float convert_to_pressure(int16_t adc_value) {
    float voltage = (float)adc_value * ADS1115_FULL_SCALE_VOLTAGE / 32768.0;
    float pressure = (voltage / 4.096) * 100.0; // Assuming 100kPa range
    return pressure;
}

// Function to validate the pressure reading
int validate_pressure(float pressure) {
    return (pressure >= PRESSURE_MIN && pressure <= PRESSURE_MAX) ? 0 : -1;
}

// Function to log the pressure reading to a file
int log_pressure(float pressure) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return -1;
    }

    fprintf(fp, "%s, %.2f kPa\n", timestamp, pressure);
    fclose(fp);

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read ADC value
        int16_t adc_value = read_adc();
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value, retrying...\n");
            gpioDelay(1000); // Wait 1 second before retrying
            continue;
        }

        // Convert to pressure
        float pressure = convert_to_pressure(adc_value);

        // Validate pressure
        if (validate_pressure(pressure) == 0) {
            // Log pressure
            if (log_pressure(pressure) != 0) {
                fprintf(stderr, "Error logging pressure value\n");
            }
        } else {
            fprintf(stderr, "Invalid pressure reading: %.2f kPa\n", pressure);
        }

        // Wait for 1 second
        gpioDelay(1000);
    }

    // Close I2C bus
    i2cClose(i2c_handle);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

