#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SI1172_ADDR 0x49
#define LOG_FILE "biometric_log.csv"
#define SAMPLE_RATE_HZ 1
#define SAMPLE_PERIOD_US (1000000 / SAMPLE_RATE_HZ)

// Si1172 Register Addresses (Example - Refer to Si1172 datasheet for actual values)
#define REG_PART_ID 0x00
#define REG_HW_ID 0x01
#define REG_SEQ_ID 0x02
#define REG_INT_CFG 0x03
#define REG_INT_EN 0x04
#define REG_RSP0_CFG 0x07
#define REG_RSP1_CFG 0x08
#define REG_RSP2_CFG 0x09
#define REG_RSP3_CFG 0x0A
#define REG_RSP0_DATA0 0x10
#define REG_RSP0_DATA1 0x11
#define REG_RSP1_DATA0 0x12
#define REG_RSP1_DATA1 0x13
#define REG_RSP2_DATA0 0x14
#define REG_RSP2_DATA1 0x15
#define REG_RSP3_DATA0 0x16
#define REG_RSP3_DATA1 0x17
#define REG_MEAS_RATE0 0x08
#define REG_MEAS_RATE1 0x09
#define REG_LED1_A 0x1E
#define REG_LED2_A 0x1F
#define REG_LED3_A 0x20
#define REG_LED1_D 0x21
#define REG_LED2_D 0x22
#define REG_LED3_D 0x23
#define REG_FIFO_CONFIG 0x24
#define REG_FIFO_DATA 0x25
#define REG_FIFO_READ 0x26
#define REG_FIFO_WRITE 0x27
#define REG_FIFO_STATUS 0x28
#define REG_IRQ_STATUS 0x29
#define REG_IRQ_ENABLE 0x2A
#define REG_ALS_IR_ADCMUX 0x30
#define REG_ALS_RED_ADCMUX 0x31
#define REG_ALS_IR_ADC_GAIN 0x32
#define REG_ALS_RED_ADC_GAIN 0x33
#define REG_ALS_IR_ADC_MISC 0x34
#define REG_ALS_RED_ADC_MISC 0x35
#define REG_ALS_IR_ADC_OFFSET 0x36
#define REG_ALS_RED_ADC_OFFSET 0x37
#define REG_ALS_IR_ADC_CALIB 0x38
#define REG_ALS_RED_ADC_CALIB 0x39
#define REG_ALS_IR_ADC_STATUS 0x3A
#define REG_ALS_RED_ADC_STATUS 0x3B
#define REG_ALS_IR_ADC_DATA0 0x3C
#define REG_ALS_IR_ADC_DATA1 0x3D
#define REG_ALS_RED_ADC_DATA0 0x3E
#define REG_ALS_RED_ADC_DATA1 0x3F

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int16_t ir_value;
    int16_t red_value;
} sensor_data_t;

// Function prototypes
int initialize_sensor();
sensor_data_t read_sensor_data();
void log_data(time_t timestamp, int16_t ir_value, int16_t red_value, int error_flag);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

// Initialize the Si1172 sensor
int initialize_sensor() {
    // Example initialization sequence (Refer to Si1172 datasheet for correct sequence)
    // This is a placeholder and needs to be replaced with the actual initialization sequence
    // for the Si1172-A30-GMR sensor.

    // Reset the device
    if (i2cWriteByteData(i2c_handle, REG_INT_CFG, 0x00) < 0) {
        fprintf(stderr, "Error writing to REG_INT_CFG during reset.\n");
        return -1;
    }
    gpioDelay(10); // Delay after reset

    // Configure LED drive strength (example values)
    if (i2cWriteByteData(i2c_handle, REG_LED1_A, 0x7F) < 0) {
        fprintf(stderr, "Error writing to REG_LED1_A.\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, REG_LED2_A, 0x7F) < 0) {
        fprintf(stderr, "Error writing to REG_LED2_A.\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, REG_LED3_A, 0x7F) < 0) {
        fprintf(stderr, "Error writing to REG_LED3_A.\n");
        return -1;
    }

    // Configure measurement rate
    if (i2cWriteByteData(i2c_handle, REG_MEAS_RATE0, 0x0A) < 0) {
        fprintf(stderr, "Error writing to REG_MEAS_RATE0.\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, REG_MEAS_RATE1, 0x00) < 0) {
        fprintf(stderr, "Error writing to REG_MEAS_RATE1.\n");
        return -1;
    }

    // Enable interrupt on every sample
    if (i2cWriteByteData(i2c_handle, REG_INT_EN, 0x01) < 0) {
        fprintf(stderr, "Error writing to REG_INT_EN.\n");
        return -1;
    }

    // Enable FIFO
    if (i2cWriteByteData(i2c_handle, REG_FIFO_CONFIG, 0x07) < 0) {
        fprintf(stderr, "Error writing to REG_FIFO_CONFIG.\n");
        return -1;
    }

    // Enable sensor (example)
    if (i2cWriteByteData(i2c_handle, REG_INT_CFG, 0x01) < 0) {
        fprintf(stderr, "Error writing to REG_INT_CFG to enable sensor.\n");
        return -1;
    }

    gpioDelay(10); // Delay after enabling sensor

    return 0;
}

// Read raw sensor data from the Si1172
sensor_data_t read_sensor_data() {
    sensor_data_t data;
    int result;

    // Read IR value
    result = i2cReadWordData(i2c_handle, REG_ALS_IR_ADC_DATA0);
    if (result < 0) {
        fprintf(stderr, "Error reading IR data: %d\n", result);
        data.ir_value = -1; // Indicate error
    } else {
        data.ir_value = (int16_t)result;
    }

    // Read RED value
    result = i2cReadWordData(i2c_handle, REG_ALS_RED_ADC_DATA0);
    if (result < 0) {
        fprintf(stderr, "Error reading RED data: %d\n", result);
        data.red_value = -1; // Indicate error
    } else {
        data.red_value = (int16_t)result;
    }

    return data;
}

// Log data to the CSV file
void log_data(time_t timestamp, int16_t ir_value, int16_t red_value, int error_flag) {
    struct tm *timeinfo;
    char timestamp_str[20];

    timeinfo = localtime(&timestamp);
    strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%d,%d,%d\n", timestamp_str, ir_value, red_value, error_flag);
    fflush(log_file); // Ensure data is written to disk immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SI1172_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write the header row if the file is new
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,HR (bpm),SpO2 (%),Error Flag\n");
    }
    fflush(log_file);

    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        time_t current_time = time(NULL);
        sensor_data_t sensor_values = read_sensor_data();

        int error_flag = 0;
        if (sensor_values.ir_value == -1 || sensor_values.red_value == -1) {
            error_flag = 1; // I2C read error
        }

        log_data(current_time, sensor_values.ir_value, sensor_values.red_value, error_flag);

        gpioDelay(SAMPLE_PERIOD_US); // Sample at 1 Hz
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

