    gpioTerminate();
}

// Initialize the Si1172 sensor
int initialize_sensor() {
    // Example initialization sequence (Refer to Si1172 datasheet for correct sequence)
    // This is a placeholder and needs to be replaced with the actual initialization sequence
    // for the Si1172-A30-GMR sensor.

    // Reset the device
    if (i2cWriteByteData(i2c_handle, REG_INT_CFG, 0x00) < 0) {
        fprintf(stderr, "Error writing to REG_INT_CFG during reset.\n");
        return -1;
    }
    gpioDelay(10); // Delay after reset

    // Configure LED drive strength (example values)
    if (i2cWriteByteData(i2c_handle, REG_LED1_A, 0x7F) < 0) {
        fprintf(stderr, "Error writing to REG_LED1_A.\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, REG_LED2_A, 0x7F) < 0) {
        fprintf(stderr, "Error writing to REG_LED2_A.\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, REG_LED3_A, 0x7F) < 0) {
        fprintf(stderr, "Error writing to REG_LED3_A.\n");
        return -1;
    }

    // Configure measurement rate
    if (i2cWriteByteData(i2c_handle, REG_MEAS_RATE0, 0x0A) < 0) {
        fprintf(stderr, "Error writing to REG_MEAS_RATE0.\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, REG_MEAS_RATE1, 0x00) < 0) {
        fprintf(stderr, "Error writing to REG_MEAS_RATE1.\n");
        return -1;
    }

    // Enable interrupt on every sample
    if (i2cWriteByteData(i2c_handle, REG_INT_EN, 0x01) < 0) {
        fprintf(stderr, "Error writing to REG_INT_EN.\n");
        return -1;
    }

    // Enable FIFO
    if (i2cWriteByteData(i2c_handle, REG_FIFO_CONFIG, 0x07) < 0) {
        fprintf(stderr, "Error writing to REG_FIFO_CONFIG.\n");
        return -1;
    }

    // Enable sensor (example)
    if (i2cWriteByteData(i2c_handle, REG_INT_CFG, 0x01) < 0) {
        fprintf(stderr, "Error writing to REG_INT_CFG to enable sensor.\n");
        return -1;
    }

    gpioDelay(10); // Delay after enabling sensor

    return 0;
}

// Read raw sensor data from the Si1172
sensor_data_t read_sensor_data() {
    sensor_data_t data;
    int result;

    // Read IR value
    result = i2cReadWordData(i2c_handle, REG_ALS_IR_ADC_DATA0);
    if (result < 0) {
        fprintf(stderr, "Error reading IR data: %d\n", result);
        data.ir_value = -1; // Indicate error
    } else {
        data.ir_value = (int16_t)result;
    }

    // Read RED value
    result = i2cReadWordData(i2c_handle, REG_ALS_RED_ADC_DATA0);
    if (result < 0) {
        fprintf(stderr, "Error reading RED data: %d\n", result);
        data.red_value = -1; // Indicate error
    } else {
        data.red_value = (int16_t)result;
    }

    return data;
}

// Log data to the CSV file
void log_data(time_t timestamp, int16_t ir_value, int16_t red_value, int error_flag) {
    struct tm *timeinfo;
    char timestamp_str[20];

    timeinfo = localtime(&timestamp);
    strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%d,%d,%d\n", timestamp_str, ir_value, red_value, error_flag);
    fflush(log_file); // Ensure data is written to disk immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SI1172_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write the header row if the file is new
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,HR (bpm),SpO2 (%),Error Flag\n");
    }
    fflush(log_file);

    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        time_t current_time = time(NULL);
        sensor_data_t sensor_values = read_sensor_data();

        int error_flag = 0;
        if (sensor_values.ir_value == -1 || sensor_values.red_value == -1) {
            error_flag = 1; // I2C read error
        }

        log_data(current_time, sensor_values.ir_value, sensor_values.red_value, error_flag);

        gpioDelay(SAMPLE_PERIOD_US); // Sample at 1 Hz
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

