#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// ICP-10125 I2C address
#define ICP10125_ADDR 0x69

// ICP-10125 Commands
#define ICP10125_MEASURE_CMD 0x06

// Calibration data registers (example, adjust based on datasheet)
#define ICP10125_CALIB_START 0x10 // Example start address
#define ICP10125_CALIB_LENGTH 20  // Example length

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Calibration parameters (example, adjust based on datasheet)
double c0, c1, c00, c10, c01, c11, c20, c21, c30;

// Structure to hold raw sensor data
typedef struct {
    int32_t pressure;
    int32_t temperature;
} raw_data_t;

// Structure to hold calibrated sensor data
typedef struct {
    double temperature;
    double pressure;
} calibrated_data_t;

// Function prototypes
int init_i2c();
int read_calibration_data();
int trigger_measurement();
int read_sensor_data(raw_data_t *data);
calibrated_data_t calibrate_sensor(raw_data_t raw_data);
int log_data(calibrated_data_t data);
void display_data(calibrated_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C bus
int init_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(1, ICP10125_ADDR, 0); // I2C bus 1, address 0x69, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Read calibration data from the sensor
int read_calibration_data() {
    char buffer[ICP10125_CALIB_LENGTH];
    int result = i2cReadI2CBlockData(i2c_handle, ICP10125_CALIB_START, buffer, ICP10125_CALIB_LENGTH);

    if (result < 0) {
        fprintf(stderr, "Failed to read calibration data: %s\n", strerror(errno));
        return -1;
    }

    // Example calibration parameter extraction (adjust based on datasheet)
    c0 = (double)((int16_t)((buffer[0] << 8) | buffer[1]));
    c1 = (double)((int16_t)((buffer[2] << 8) | buffer[3]));
    c00 = (double)((int16_t)((buffer[4] << 8) | buffer[5]));
    c10 = (double)((int16_t)((buffer[6] << 8) | buffer[7]));
    c01 = (double)((int16_t)((buffer[8] << 8) | buffer[9]));
    c11 = (double)((int16_t)((buffer[10] << 8) | buffer[11]));
    c20 = (double)((int16_t)((buffer[12] << 8) | buffer[13]));
    c21 = (double)((int16_t)((buffer[14] << 8) | buffer[15]));
    c30 = (double)((int16_t)((buffer[16] << 8) | buffer[17]));

    printf("Calibration data read successfully.\n");
    return 0;
}

// Trigger a measurement
int trigger_measurement() {
    char cmd = ICP10125_MEASURE_CMD;
    int result = i2cWriteByteData(i2c_handle, 0x00, cmd); // Write to register 0x00
    if (result < 0) {
        fprintf(stderr, "Failed to trigger measurement: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Read sensor data
int read_sensor_data(raw_data_t *data) {
    char buffer[6];
    int result = i2cReadI2CBlockData(i2c_handle, 0x00, buffer, 6); // Read from register 0x00

    if (result < 0) {
        fprintf(stderr, "Failed to read sensor data: %s\n", strerror(errno));
        return -1;
    }

    data->pressure = (int32_t)((buffer[0] << 16) | (buffer[1] << 8) | buffer[2]);
    data->temperature = (int32_t)((buffer[3] << 16) | (buffer[4] << 8) | buffer[5]);

    return 0;
}

// Calibrate sensor data
calibrated_data_t calibrate_sensor(raw_data_t raw_data) {
    calibrated_data_t calibrated_data;

    // Example calibration formulas (adjust based on datasheet)
    calibrated_data.temperature = c0 + c1 * raw_data.temperature;
    calibrated_data.pressure = c00 + c10 * raw_data.temperature + c01 * raw_data.pressure + c11 * raw_data.temperature * raw_data.pressure + c20 * raw_data.pressure * raw_data.pressure + c21 * raw_data.temperature * raw_data.pressure * raw_data.pressure + c30 * raw_data.temperature * raw_data.temperature * raw_data.pressure * raw_data.pressure;

    return calibrated_data;
}

// Log data to file
int log_data(calibrated_data_t data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, data.temperature, data.pressure);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Display data on console
void display_data(calibrated_data_t data) {
    printf("Temperature: %.2f °C, Pressure: %.2f Pa\n", data.temperature, data.pressure);
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() < 0) {
        return 1;
    }

    // Read calibration data
    if (read_calibration_data() < 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("environmental_data.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    // Main loop
    raw_data_t raw_data;
    calibrated_data_t calibrated_data;
    while (!terminate) {
        // Trigger measurement
        if (trigger_measurement() < 0) {
            fprintf(stderr, "Retrying in 5 seconds...\n");
            gpioDelay(5000000); // 5 seconds
            continue;
        }

        // Wait for conversion (adjust based on datasheet)
        gpioDelay(100000); // 100 ms

        // Read sensor data
        if (read_sensor_data(&raw_data) < 0) {
            fprintf(stderr, "Retrying in 5 seconds...\n");
            gpioDelay(5000000); // 5 seconds
            continue;
        }

        // Calibrate sensor data
        calibrated_data = calibrate_sensor(raw_data);

        // Log data
        log_data(calibrated_data);

        // Display data
        display_data(calibrated_data);

        // Wait 5 seconds
        gpioDelay(5000000);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

