// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0

// Define MCP3008 channel numbers
#define MIC1_CHANNEL 0
#define MIC2_CHANNEL 1

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold program configuration
typedef struct {
    float gain1;
    float gain2;
} ProgramConfig;

// Function prototypes
int initialize_pigpio();
int initialize_spi();
int read_mcp3008(int channel);
float apply_noise_cancellation(int mic1_sample, int mic2_sample, float gain1, float gain2);
void print_csv(float sample1, float sample2);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Initialize SPI interface
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI initialisation failed: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Read data from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    // Construct SPI message (MCP3008 datasheet)
    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result != 3) {
        fprintf(stderr, "SPI transfer failed: %d\n", result);
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];
    return adc_value;
}

// Apply noise cancellation algorithm
float apply_noise_cancellation(int mic1_sample, int mic2_sample, float gain1, float gain2) {
    return (float)mic1_sample - gain1 * (float)mic2_sample - gain2 * (float)mic1_sample;
}

// Print audio samples to terminal in CSV format
void print_csv(float sample1, float sample2) {
    printf("%.2f,%.2f\n", sample1, sample2);
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    spiClose(spi_handle);
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Parse command-line arguments
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <gain1> <gain2>\n", argv[0]);
        return 1;
    }

    ProgramConfig config;
    config.gain1 = atof(argv[1]);
    config.gain2 = atof(argv[2]);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Initialize SPI
    if (initialize_spi() != 0) {
        cleanup();
        return 1;
    }

    printf("Audio sampling started. Press Ctrl+C to terminate.\n");

    // Main loop
    while (!terminate) {
        // Read audio samples from microphones
        int mic1_sample = read_mcp3008(MIC1_CHANNEL);
        int mic2_sample = read_mcp3008(MIC2_CHANNEL);

        if (mic1_sample == -1 || mic2_sample == -1) {
            fprintf(stderr, "Error reading microphone data. Retrying...\n");
            gpioDelay(100000); // 100ms delay
            continue;
        }

        // Apply noise cancellation
        float cancelled_sample = apply_noise_cancellation(mic1_sample, mic2_sample, config.gain1, config.gain2);

        // Print audio samples to terminal
        print_csv(cancelled_sample, (float)mic2_sample); // Print both for verification

        // Delay to control sampling rate
        gpioDelay(1000); // 1 ms delay
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

