// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define BUZZER_GPIO 18
#define LOG_FILE "flame_log.txt"
#define AMBIENT_TEMP_FILE "ambient_temp.txt"
#define RETRY_COUNT 3
#define SAMPLE_INTERVAL_MS 500

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float compensate_voltage(int raw_adc, float temperature);
int read_ambient_temperature();
void log_data(int raw_adc, float voltage, float compensated_voltage, float temperature, int flame_detected);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel selection
    tx_buffer[2] = 0x00; // Dummy byte

    // Perform SPI transaction
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed (error code: %d)\n", result);
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to compensate voltage with temperature
float compensate_voltage(int raw_adc, float temperature) {
    // Simple linear compensation (adjust as needed)
    return (float)raw_adc * (5.0 + temperature) / 1023.0;
}

// Function to read ambient temperature from file
int read_ambient_temperature() {
    FILE *fp = fopen(AMBIENT_TEMP_FILE, "r");
    if (fp == NULL) {
        fprintf(stderr, "Warning: Could not open ambient temperature file. Using default temperature (25.0°C).\n");
        return 2500; // Default temperature in hundredths of degrees Celsius
    }

    int temperature;
    if (fscanf(fp, "%d", &temperature) != 1) {
        fprintf(stderr, "Warning: Could not read temperature from file. Using default temperature (25.0°C).\n");
        fclose(fp);
        return 2500; // Default temperature in hundredths of degrees Celsius
    }

    fclose(fp);
    return temperature;
}

// Function to log data to file
void log_data(int raw_adc, float voltage, float compensated_voltage, float temperature, int flame_detected) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s,%d,%.2f,%.2f,%.2f,%d\n", timestamp, raw_adc, voltage, compensated_voltage, temperature, flame_detected);
    fflush(log_file); // Ensure data is written to disk immediately
}

