#define SAMPLE_INTERVAL_MS 5000
#define SLEEP_INTERVAL_MS 100

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_mcp3008(int channel);
float calculate_water_level(int adc_value);
char *format_json(float water_level);
void log_data(const char *json_string);
void signal_handler(int signal);
int initialize();
void cleanup();

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    char spi_tx_buf[3];
    char spi_rx_buf[3];

    // Construct SPI message (MCP3008 datasheet)
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result < 0) {
        fprintf(stderr, "Error: SPI transfer failed (%d)\n", result);
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

// Function to calculate water level percentage
float calculate_water_level(int adc_value) {
    // Assuming 0 ADC value is 0% and 1023 is 100%
    return (float)adc_value / 1023.0 * 100.0;
}

// Function to format data as JSON
char *format_json(float water_level) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];
    static char json_string[100]; // Static to persist across calls

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);
    snprintf(json_string, sizeof(json_string), "{\"timestamp\": \"%s\", \"water_level\": %.2f}", timestamp, water_level);

    return json_string;
}

// Function to log data to file
void log_data(const char *json_string) {
    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open\n");
        return;
    }

    fprintf(log_file, "%s\n", json_string);
    fflush(log_file); // Ensure data is written immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Received signal %d, shutting down...\n", signal);
}

// Initialization function
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (%d)\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0); // Initially off

    // Open log file
    log_file = fopen("water_levels.json", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write opening bracket for JSON array
    fprintf(log_file, "[\n");
    fflush(log_file);

    return 0;
}

// Cleanup function
void cleanup() {
    // Close SPI channel
    spiClose(spi_handle);

    // Turn off LED
    gpioWrite(LED_GPIO, 0);

    // Terminate pigpio
    gpioTerminate();

    // Close log file
    if (log_file != NULL) {
        // Write closing bracket for JSON array
        fseek(log_file, -2, SEEK_END); // Remove the last comma and newline
        fprintf(log_file, "\n]");
        fclose(log_file);
    }

    printf("Cleanup complete. Exiting.\n");
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (initialize()) {
        return 1;
    }

    int led_state = 0; // 0 = off, 1 = on
    float water_level;
    int adc_value;
    char *json_string;

    while (program_running) {
        // Read ADC value
        adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            sleep(SLEEP_INTERVAL_MS / 1000.0); // Sleep for a short time before retrying
            continue;
        }

        // Calculate water level
        water_level = calculate_water_level(adc_value);

        // Format as JSON
        json_string = format_json(water_level);

        // Log data
        log_data(json_string);

        // Control LED with hysteresis
        if (water_level > WATER_LEVEL_THRESHOLD_HIGH && led_state == 0) {
            gpioWrite(LED_GPIO, 1);
            led_state = 1;
            printf("Water level above %.2f%%, LED ON\n", WATER_LEVEL_THRESHOLD_HIGH);
        } else if (water_level < WATER_LEVEL_THRESHOLD_LOW && led_state == 1) {
            gpioWrite(LED_GPIO, 0);
            led_state = 0;
            printf("Water level below %.2f%%, LED OFF\n", WATER_LEVEL_THRESHOLD_LOW);
        }

        printf("Water level: %.2f%%\n", water_level);

        // Sleep for the specified interval
        sleep(SAMPLE_INTERVAL_MS / 1000.0);
    }

    cleanup();

    return 0;
}

