void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating program...\n");
    terminate = 1;
}

// Function to read configuration from command line arguments
int read_config(int argc, char *argv[], Config *config) {
    if (argc != 8) {
        fprintf(stderr, "Usage: %s <spi_channel> <adc_channel> <min_adc_value> <max_adc_value> <moisture_threshold> <logging_interval> <email_address> <msmtp_config_path>\n", argv[0]);
        return 1;
    }

    config->spi_channel = atoi(argv[1]);
    config->adc_channel = atoi(argv[2]);
    config->min_adc_value = atoi(argv[3]);
    config->max_adc_value = atoi(argv[4]);
    config->moisture_threshold = atof(argv[5]);
    config->logging_interval = atoi(argv[6]);
    config->email_address = argv[7];
    config->msmtp_config_path = argv[8];

    return 0;
}

// Function to initialize the SPI interface
int initialize_spi(int channel) {
    spi_handle = spiOpen(channel, 500000, 0); // CE0, 500kHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI channel %d: %d\n", channel, spi_handle);
        return 1;
    }
    return 0;
}

