        int adc_value = read_adc(config.adc_channel);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value, retrying...\n");
            sleep(1); // Wait before retrying
            continue;
        }

        float moisture_percentage = calculate_moisture_percentage(adc_value, config.min_adc_value, config.max_adc_value);

        if (log_data(moisture_percentage) != 0) {
            fprintf(stderr, "Failed to log data\n");
        }

        if (moisture_percentage < config.moisture_threshold) {
            if (send_email_alert(moisture_percentage) != 0) {
                fprintf(stderr, "Failed to send email alert\n");
            }
        }

        sleep(config.logging_interval);
    }

    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

