#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <errno.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_SPEED 1000000 // 1 MHz
#define LOG_FILE "soil_moisture.log"
#define ADC_MIN 0
#define ADC_MAX 1023
#define MOISTURE_MIN 0.0
#define MOISTURE_MAX 100.0

// Global variables
int spi_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_init(const char *device, int mode, int speed);
int read_adc(int channel);
float calculate_moisture(int adc_value);
int log_data(const char *timestamp, int adc_value, float moisture_percentage);
void signal_handler(int signal);
void cleanup();

// SPI Initialization function
int spi_init(const char *device, int mode, int speed) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Set SPI mode
    int mode_set = mode;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode_set) == -1) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    // Set SPI speed
    int speed_set = speed;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed_set) == -1) {
        perror("Error setting SPI speed");
        close(fd);
        return -1;
    }

    return fd;
}

// ADC Reading function
int read_adc(int channel) {
    unsigned char tx_buf[3];
    unsigned char rx_buf[3];
    struct spi_ioc_transfer transfer[1];

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel << 4)) << 4; // Single-ended mode, channel selection
    tx_buf[2] = 0x00; // Don't care

    memset(transfer, 0, sizeof(transfer));

    transfer[0].tx_buf = (unsigned long)tx_buf;
    transfer[0].rx_buf = (unsigned long)rx_buf;
    transfer[0].len = 3;
    transfer[0].speed_hz = SPI_SPEED;
    transfer[0].bits_per_word = 8;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), transfer) < 0) {
        perror("Error during SPI transfer");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// Moisture Calculation function
float calculate_moisture(int adc_value) {
    float moisture_percentage = ((float)(adc_value - ADC_MIN) / (ADC_MAX - ADC_MIN)) * (MOISTURE_MAX - MOISTURE_MIN) + MOISTURE_MIN;
    return moisture_percentage;
}

// Logging function
int log_data(const char *timestamp, int adc_value, float moisture_percentage) {
    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s, %d, %.2f\n", timestamp, adc_value, moisture_percentage);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function
void cleanup() {
    if (spi_fd != -1) {
        close(spi_fd);
        printf("SPI device closed.\n");
    }
    if (log_file != NULL) {
        fclose(log_file);
        printf("Log file closed.\n");
    }
}

int main(int argc, char *argv[]) {
    int sample_interval = 1; // Default interval: 1 second

    // Parse command-line argument for sample interval
    if (argc > 1) {
        sample_interval = atoi(argv[1]);
        if (sample_interval <= 0) {
            fprintf(stderr, "Invalid sample interval. Using default value of 1 second.\n");
            sample_interval = 1;
        }
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize SPI
    spi_fd = spi_init(SPI_DEVICE, SPI_MODE, SPI_SPEED);
    if (spi_fd < 0) {
        fprintf(stderr, "SPI initialization failed. Exiting.\n");
        return 1;
    }
    printf("SPI initialized successfully.\n");

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }
    printf("Log file opened successfully.\n");

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_adc(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value. Retrying in %d seconds.\n", sample_interval);
            sleep(sample_interval);
            continue;
        }

        // Calculate moisture percentage
        float moisture_percentage = calculate_moisture(adc_value);

        // Get current timestamp
        time_t rawtime;
        struct tm *timeinfo;
        char timestamp[30];

        time(&rawtime);
        timeinfo = gmtime(&rawtime);

        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

        // Log data
        if (log_data(timestamp, adc_value, moisture_percentage) != 0) {
            fprintf(stderr, "Error logging data. Retrying in %d seconds.\n", sample_interval);
        }

        printf("Timestamp: %s, ADC Value: %d, Moisture: %.2f%%\n", timestamp, adc_value, moisture_percentage);

        // Wait for the specified interval
        sleep(sample_interval);
    }

    // Cleanup and exit
    cleanup();
    printf("Program terminated.\n");
    return 0;
}

