// Define constants
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define ADC_CHANNEL 0
#define VREF 3.3
#define MIN_VOLTAGE 0.0
#define MAX_VOLTAGE 3.3
#define MIN_PRESSURE 0.0
#define MAX_PRESSURE 100.0 // kPa
#define SAMPLE_INTERVAL 1 // seconds

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_adc(int channel);
float adc_to_voltage(int adc_value);
float voltage_to_pressure(float voltage);
void log_data(float pressure);
void signal_handler(int signal);
int initialize();
void cleanup();

// Structure for configuration (optional)
typedef struct {
    int spi_channel;
    int spi_baud;
    int adc_channel;
    float vref;
    float min_voltage;
    float max_voltage;
    float min_pressure;
    float max_pressure;
    int sample_interval;
} config_t;

config_t config = {
    SPI_CHANNEL,
    SPI_BAUD,
    ADC_CHANNEL,
    VREF,
    MIN_VOLTAGE,
    MAX_VOLTAGE,
    MIN_PRESSURE,
    MAX_PRESSURE,
    SAMPLE_INTERVAL
};

int main() {
    // Initialize
    if (initialize() != 0) {
        fprintf(stderr, "Initialization failed. Exiting.\n");
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_adc(config.adc_channel);

        // Validate ADC value
        if (adc_value < 0 || adc_value > 1023) {
            fprintf(stderr, "Error: Invalid ADC value: %d\n", adc_value);
            continue; // Skip to the next iteration
        }

        // Convert ADC value to voltage
        float voltage = adc_to_voltage(adc_value);

        // Validate voltage
        if (voltage < config.min_voltage || voltage > config.max_voltage) {
            fprintf(stderr, "Error: Voltage out of range: %.2f V\n", voltage);
            continue; // Skip to the next iteration
        }

        // Convert voltage to pressure
        float pressure = voltage_to_pressure(voltage);

        // Log data
        log_data(pressure);

        // Wait for the next sample
        gpioDelay(config.sample_interval * 1000000); // microseconds
    }

    // Cleanup
    cleanup();

    return 0;
}

// Function to initialize the pigpio library and SPI
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(config.spi_channel, config.spi_baud, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Function to read from the MCP3008 ADC
int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel: %d\n", channel);
        return -1;
    }

    // Construct SPI message (MCP3008 datasheet)
    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result != 3) {
        fprintf(stderr, "SPI transfer failed: %d\n", result);
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

// Function to convert ADC value to voltage
float adc_to_voltage(int adc_value) {
    return ((float)adc_value / 1023.0) * config.vref;
}

// Function to convert voltage to pressure
float voltage_to_pressure(float voltage) {
    // Linear conversion (adjust as needed for your sensor)
    return (voltage / config.vref) * (config.max_pressure - config.min_pressure) + config.min_pressure;
}

// Function to log data with ISO-8601 timestamp
void log_data(float pressure) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    printf("%s Pressure: %.2f kPa\n", timestamp, pressure);
}

// Signal handler function
void signal_handler(int signal) {
    printf("Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Function to cleanup resources
void cleanup() {
    spiClose(spi_handle);
    gpioTerminate();
    printf("Cleanup complete. Exiting.\n");
}

