#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <wiringPi.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define ADS1115_ADDR 0x48
#define ADS1115_CONFIG_REG 0x01
#define ADS1115_CONVERSION_REG 0x00
#define GPIO_RELAY 17
#define GPIO_DOOR_SENSOR 27
#define LOG_FILE "/var/log/door_events.log"
#define CALIBRATION_SAMPLES 10
#define CALIBRATION_DELAY_MS 50
#define SAMPLE_DELAY_MS 200
#define RELAY_ON_TIME_MS 3000

// Global variables
static int i2c_fd = -1;
static FILE *log_fp = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_init(const char *bus);
int ads1115_read_adc(int fd);
float adc_to_voltage(int adc_value);
float calibrate_sensor(int fd);
bool is_distance_below_threshold(float voltage, float threshold);
void control_relay(int gpio_pin, int state);
bool is_door_open(int gpio_pin);
void log_event(const char *message);
void signal_handler(int sig);
void cleanup();

// I2C initialization function
int i2c_init(const char *bus) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// ADS1115 read ADC function
int ads1115_read_adc(int fd) {
    uint8_t config[3];
    uint8_t data[2];
    int16_t adc_value;

    // Configure ADS1115 for single-ended A0, 4.096V range, continuous conversion, 128 SPS
    config[0] = ADS1115_CONFIG_REG;
    config[1] = 0x43; // Single-ended A0, 128 SPS
    config[2] = 0x83; // 4.096V, Single-shot mode

    if (write(fd, config, 3) != 3) {
        perror("Error writing to I2C device");
        return -1;
    }

    // Wait for conversion to complete (at least 8ms for 128 SPS)
    usleep(10000); // 10ms

    // Read conversion register
    config[0] = ADS1115_CONVERSION_REG;
    if (write(fd, config, 1) != 1) {
        perror("Error writing to I2C device");
        return -1;
    }

    if (read(fd, data, 2) != 2) {
        perror("Error reading from I2C device");
        return -1;
    }

    adc_value = (data[0] << 8) | data[1];
    return adc_value;
}

// ADC to voltage conversion function
float adc_to_voltage(int adc_value) {
    return (float)adc_value * 4.096 / 32767.0;
}

// Sensor calibration function
float calibrate_sensor(int fd) {
    float sum = 0.0;
    for (int i = 0; i < CALIBRATION_SAMPLES; i++) {
        int adc_value = ads1115_read_adc(fd);
        if (adc_value < 0) {
            log_event("Error reading ADC during calibration, using default threshold.");
            return 2.0; // Default threshold
        }
        sum += adc_to_voltage(adc_value);
        usleep(CALIBRATION_DELAY_MS * 1000); // Delay between samples
    }
    return sum / CALIBRATION_SAMPLES;
}

// Distance threshold check function
bool is_distance_below_threshold(float voltage, float threshold) {
    return voltage < threshold;
}

// Relay control function
void control_relay(int gpio_pin, int state) {
    digitalWrite(gpio_pin, state);
}

// Door sensor check function
bool is_door_open(int gpio_pin) {
    return digitalRead(gpio_pin) == LOW;
}

// Logging function
void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_fp, "%s: %s\n", timestamp, message);
    fflush(log_fp);
}

// Signal handler function
void signal_handler(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        printf("Received signal %d, terminating...\n", sig);
        terminate = 1;
    }
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_fp != NULL) {
        fclose(log_fp);
    }
    control_relay(GPIO_RELAY, LOW); // De-energize relay
    wiringPiSetupGpio(); // Reinitialize wiringPi to avoid issues
    pinMode(GPIO_RELAY, OUTPUT);
    digitalWrite(GPIO_RELAY, LOW);
    pinMode(GPIO_DOOR_SENSOR, INPUT);
    pullUpDnControl(GPIO_DOOR_SENSOR, PUD_UP);
}

int main() {
    // Initialize WiringPi
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "WiringPi initialization failed: %s\n", strerror(errno));
        return 1;
    }

    // Set GPIO modes
    pinMode(GPIO_RELAY, OUTPUT);
    pinMode(GPIO_DOOR_SENSOR, INPUT);
    pullUpDnControl(GPIO_DOOR_SENSOR, PUD_UP);

    // Initialize I2C
    i2c_fd = i2c_init(I2C_BUS);
    if (i2c_fd < 0) {
        return 1;
    }

    // Open log file
    log_fp = fopen(LOG_FILE, "a");
    if (log_fp == NULL) {
        perror("Error opening log file");
        close(i2c_fd);
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Calibrate sensor
    float threshold = calibrate_sensor(i2c_fd);
    printf("Calibration complete. Threshold: %.2f V\n", threshold);

    // Main loop
    while (!terminate) {
        int adc_value = ads1115_read_adc(i2c_fd);
        if (adc_value < 0) {
            log_event("Error reading ADC, retrying...");
            usleep(SAMPLE_DELAY_MS * 1000); // Wait before retrying
            continue;
        }

        float voltage = adc_to_voltage(adc_value);

        if (is_distance_below_threshold(voltage, threshold)) {
            printf("Distance below threshold (%.2f V < %.2f V)\n", voltage, threshold);
            control_relay(GPIO_RELAY, HIGH); // Energize relay
            log_event("Door unlocking...");
            usleep(RELAY_ON_TIME_MS * 1000); // Keep relay on for 3 seconds
            control_relay(GPIO_RELAY, LOW);  // De-energize relay
            log_event("Door locking...");

            // Check door sensor
            if (is_door_open(GPIO_DOOR_SENSOR)) {
                log_event("door opened");
            } else {
                log_event("door not opened");
            }
        }

        usleep(SAMPLE_DELAY_MS * 1000); // Sample every 200ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

