            log_event("Error reading ADC during calibration, using default threshold.");
            return 2.0; // Default threshold
        }
        sum += adc_to_voltage(adc_value);
        usleep(CALIBRATION_DELAY_MS * 1000); // Delay between samples
    }
    return sum / CALIBRATION_SAMPLES;
}

// Distance threshold check function
bool is_distance_below_threshold(float voltage, float threshold) {
    return voltage < threshold;
}

// Relay control function
void control_relay(int gpio_pin, int state) {
    digitalWrite(gpio_pin, state);
}

// Door sensor check function
bool is_door_open(int gpio_pin) {
    return digitalRead(gpio_pin) == LOW;
}

// Logging function
void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_fp, "%s: %s\n", timestamp, message);
    fflush(log_fp);
}

// Signal handler function
void signal_handler(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        printf("Received signal %d, terminating...\n", sig);
        terminate = 1;
    }
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_fp != NULL) {
        fclose(log_fp);
    }
    control_relay(GPIO_RELAY, LOW); // De-energize relay
    wiringPiSetupGpio(); // Reinitialize wiringPi to avoid issues
    pinMode(GPIO_RELAY, OUTPUT);
    digitalWrite(GPIO_RELAY, LOW);
    pinMode(GPIO_DOOR_SENSOR, INPUT);
    pullUpDnControl(GPIO_DOOR_SENSOR, PUD_UP);
}

int main() {
    // Initialize WiringPi
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "WiringPi initialization failed: %s\n", strerror(errno));
        return 1;
    }

    // Set GPIO modes
    pinMode(GPIO_RELAY, OUTPUT);
    pinMode(GPIO_DOOR_SENSOR, INPUT);
    pullUpDnControl(GPIO_DOOR_SENSOR, PUD_UP);

    // Initialize I2C
    i2c_fd = i2c_init(I2C_BUS);
    if (i2c_fd < 0) {
        return 1;
    }

    // Open log file
    log_fp = fopen(LOG_FILE, "a");
    if (log_fp == NULL) {
        perror("Error opening log file");
        close(i2c_fd);
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Calibrate sensor
    float threshold = calibrate_sensor(i2c_fd);
    printf("Calibration complete. Threshold: %.2f V\n", threshold);

    // Main loop
    while (!terminate) {
        int adc_value = ads1115_read_adc(i2c_fd);
        if (adc_value < 0) {
            log_event("Error reading ADC, retrying...");
            usleep(SAMPLE_DELAY_MS * 1000); // Wait before retrying
            continue;
        }

        float voltage = adc_to_voltage(adc_value);

        if (is_distance_below_threshold(voltage, threshold)) {
            printf("Distance below threshold (%.2f V < %.2f V)\n", voltage, threshold);
            control_relay(GPIO_RELAY, HIGH); // Energize relay
            log_event("Door unlocking...");
            usleep(RELAY_ON_TIME_MS * 1000); // Keep relay on for 3 seconds
            control_relay(GPIO_RELAY, LOW);  // De-energize relay
            log_event("Door locking...");

            // Check door sensor
            if (is_door_open(GPIO_DOOR_SENSOR)) {
                log_event("door opened");
            } else {
                log_event("door not opened");
            }
        }

        usleep(SAMPLE_DELAY_MS * 1000); // Sample every 200ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

