    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed with code %d\n", result);
        return -1;
    }

    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to calculate moisture level as a percentage
int calculate_moisture_level(int adc_value) {
    // Assuming 0-3V range corresponds to 0-1023 ADC values
    // and 0% moisture corresponds to 1023 (dry) and 100% corresponds to 0 (saturated)
    return 100 - (int)(((float)adc_value / 1023.0) * 100.0);
}

// Function to control the water pump
void control_pump(int state) {
    gpioWrite(PUMP_GPIO, state);
    log_event(state ? "Pump ON" : "Pump OFF");
}

// Function to log events to a file
void log_event(const char *message) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fflush(log_file);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    log_event("Received signal, shutting down...");
    control_pump(0); // Turn off the pump
    spiClose(spi_handle);
    gpioTerminate();
    fclose(log_file);
    exit(0);
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    int opt;
    while ((opt = getopt(argc, argv, "t:d:s:")) != -1) {
        switch (opt) {
            case 't':
                threshold = atoi(optarg);
                break;
            case 'd':
                duration = atoi(optarg);
                break;
            case 's':
                sleep_interval = atoi(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold] [-d duration] [-s sleep_interval]\n", argv[0]);
                exit(EXIT_FAILURE);
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set pump GPIO as output
    gpioSetMode(PUMP_GPIO, PI_OUTPUT);

    // Open log file
    log_file = fopen("irrigation.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_event("System started");

    // Main loop
    while (1) {
        int adc_value = -1;
        int retries = 0;
        while (adc_value == -1 && retries < 3) {
            adc_value = read_mcp3008(0);
            if (adc_value == -1) {
                fprintf(stderr, "Error: ADC read failed, retrying (%d/3)\n", retries + 1);
                retries++;
                gpioDelay(100); // Wait 100ms before retrying
            }
        }

        if (adc_value == -1) {
            log_event("Error: ADC read failed after multiple retries, skipping irrigation cycle");
            gpioDelay(sleep_interval * 1000); // Sleep for the configured interval
            continue;
        }

        int moisture_level = calculate_moisture_level(adc_value);
        char log_message[100];
        snprintf(log_message, sizeof(log_message), "Moisture level: %d%% (ADC: %d)", moisture_level, adc_value);
        log_event(log_message);

        if (moisture_level < threshold) {
            log_event("Moisture level below threshold, activating pump");
            control_pump(1); // Turn on the pump
            gpioDelay(duration * 1000); // Wait for the specified duration
            control_pump(0); // Turn off the pump
        }

        gpioDelay(sleep_interval * 1000); // Sleep for the configured interval
    }

    return 0;
}

