#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define the I2C address of the PCF8591
#define PCF8591_ADDR 0x48

// Define the I2C bus number (usually 1 on Raspberry Pi)
#define I2C_BUS 1

// Global variable to store the I2C file descriptor
int i2c_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    if (i2c_fd != -1) {
        i2cClose(i2c_fd);
    }
    gpioTerminate();
    exit(0);
}

int main() {
    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open the I2C device
    i2c_fd = i2cOpen(I2C_BUS, PCF8591_ADDR, 0);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_fd);
        gpioTerminate();
        return 1;
    }

    printf("I2C device opened successfully with fd: %d\n", i2c_fd);

    // Main loop to continuously read the ADC value
    while (1) {
        // Perform a dummy read to discard the previous conversion result
        char dummy_read[1];
        int bytes_read = i2cReadDevice(i2c_fd, dummy_read, 1);
        if (bytes_read != 1) {
            fprintf(stderr, "Error during dummy read: %d\n", bytes_read);
            i2cClose(i2c_fd);
            gpioTerminate();
            return 1;
        }

        // Read the ADC value from channel AIN0
        char adc_value[1];
        bytes_read = i2cReadDevice(i2c_fd, adc_value, 1);
        if (bytes_read != 1) {
            fprintf(stderr, "Error reading ADC value: %d\n", bytes_read);
            i2cClose(i2c_fd);
            gpioTerminate();
            return 1;
        }

        // Print the ADC value to stdout
        printf("ADC Value: %d\n", adc_value[0]);

        // Wait for 100 milliseconds
        gpioDelay(100000); // 100 ms = 100000 microseconds
    }

    // The program should never reach here due to the infinite loop
    return 0;
}

