#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

// Configuration
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define ADS1115_CONFIG_REG 0x01
#define ADS1115_CONVERSION_REG 0x00
#define GPIO_PIN 27
#define SAMPLE_RATE_HZ 1
#define BUFFER_SIZE 100
#define THRESHOLD_GAUSS 500.0
#define VOLTAGE_RANGE 3.3
#define VOLTAGE_REF 4.096 // ADS1115 VREF
#define SS49E_SENSITIVITY 0.002 // 2mV/Gauss

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Circular buffer
float magnetic_field_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int initialize_i2c();
int read_ads1115(int *raw_value);
float convert_to_voltage(int raw_value);
float convert_to_magnetic_field(float voltage);
float calculate_rolling_average();
void check_threshold(float magnetic_field);
void set_gpio_high();
void set_gpio_low();
void signal_handler(int signal);
void log_message(int priority, const char *message);

// Function to initialize I2C
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        log_message(LOG_ERR, "Failed to open I2C bus");
        return -1;
    }

    // Configure ADS1115 for single-ended AIN0, 4.096V range, continuous conversion, 128 SPS
    uint16_t config = 0x4003; // Single-ended AIN0, 4.096V, Continuous, 128 SPS
    char buf[3];
    buf[0] = ADS1115_CONFIG_REG;
    buf[1] = (config >> 8) & 0xFF;
    buf[2] = config & 0xFF;

    if (i2cWriteDevice(i2c_handle, buf, 3) != 0) {
        log_message(LOG_ERR, "Failed to configure ADS1115");
        i2cClose(i2c_handle);
        return -1;
    }

    return 0;
}

// Function to read from ADS1115
int read_ads1115(int *raw_value) {
    char buf[1];
    buf[0] = ADS1115_CONVERSION_REG;

    if (i2cWriteDevice(i2c_handle, buf, 1) != 0) {
        log_message(LOG_ERR, "Failed to write to ADS1115 conversion register");
        return -1;
    }

    char read_buf[2];
    if (i2cReadDevice(i2c_handle, read_buf, 2) != 2) {
        log_message(LOG_ERR, "Failed to read from ADS1115 conversion register");
        return -1;
    }

    *raw_value = (read_buf[0] << 8) | read_buf[1];
    return 0;
}

// Function to convert raw ADC value to voltage
float convert_to_voltage(int raw_value) {
    // ADS1115 is a 16-bit ADC, signed two's complement
    int16_t signed_raw = (int16_t)raw_value;
    return (float)signed_raw * VOLTAGE_REF / 32768.0;
}

// Function to convert voltage to magnetic field strength (Gauss)
float convert_to_magnetic_field(float voltage) {
    return voltage / SS49E_SENSITIVITY;
}

// Function to calculate rolling average
float calculate_rolling_average() {
    float sum = 0.0;
    for (int i = 0; i < BUFFER_SIZE; i++) {
        sum += magnetic_field_buffer[i];
    }
    return sum / BUFFER_SIZE;
}

// Function to check threshold
void check_threshold(float magnetic_field) {
    if (magnetic_field > THRESHOLD_GAUSS) {
        log_message(LOG_WARNING, "Threshold exceeded!");
        set_gpio_high();
    }
}

// Function to set GPIO pin HIGH
void set_gpio_high() {
    gpioWrite(GPIO_PIN, 1);
}

// Function to set GPIO pin LOW
void set_gpio_low() {
    gpioWrite(GPIO_PIN, 0);
}

// Signal handler
void signal_handler(int signal) {
    log_message(LOG_INFO, "Signal received, terminating...");
    terminate = 1;
}

// Function to log messages to syslog
void log_message(int priority, const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    char log_message[256];
    snprintf(log_message, sizeof(log_message), "%s: %s", timestamp, message);
    syslog(priority, "%s", log_message);
}

int main() {
    // Initialize syslog
    openlog("magnetic_sensor", LOG_PID | LOG_CONS, LOG_USER);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        log_message(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    // Set GPIO pin as output
    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    set_gpio_low(); // Ensure it starts LOW

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        closelog();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_message(LOG_INFO, "Application started");

    int raw_value;
    float voltage, magnetic_field;

    while (!terminate) {
        // Read ADC value
        if (read_ads1115(&raw_value) == 0) {
            // Convert to voltage
            voltage = convert_to_voltage(raw_value);

            // Validate voltage range
            if (voltage >= 0.0 && voltage <= VOLTAGE_RANGE) {
                // Convert to magnetic field strength
                magnetic_field = convert_to_magnetic_field(voltage);

                // Store in circular buffer
                magnetic_field_buffer[buffer_index] = magnetic_field;
                buffer_index = (buffer_index + 1) % BUFFER_SIZE;

                // Calculate rolling average
                float rolling_average = calculate_rolling_average();

                // Check threshold
                check_threshold(magnetic_field);

                // Log data
                char log_buffer[256];
                snprintf(log_buffer, sizeof(log_buffer), "Raw: %d, Voltage: %.3fV, Magnetic Field: %.3fG, Rolling Average: %.3fG",
                         raw_value, voltage, magnetic_field, rolling_average);
                log_message(LOG_INFO, log_buffer);
            } else {
                log_message(LOG_WARNING, "Voltage out of range");
            }
        } else {
            log_message(LOG_ERR, "Failed to read ADC value");
        }

        // Delay for 1 second
        gpioDelay(1000); // pigpio's delay function
    }

    // Cleanup
    i2cClose(i2c_handle);
    set_gpio_low();
    gpioTerminate();
    closelog();

    return 0;
}

