// Define GPIO pins
#define MOTOR_PIN 18
#define SPI_CE 8

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0

// Define PWM parameters
#define PWM_FREQUENCY 1000
#define PWM_RANGE 1024

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
