#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <math.h>

// Constants
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define ADS1115_CONFIG_REG 0x01
#define ADS1115_CONVERSION_REG 0x00
#define GPIO_LED 17
#define DEFAULT_THRESHOLD 100.0
#define BLINK_DURATION_MS 1000
#define BLINK_PERIOD_MS 100

// Global variables
int i2c_handle;
double threshold = DEFAULT_THRESHOLD;

// Function prototypes
int init_i2c();
int16_t read_adc();
double calculate_gauss(int16_t adc_value);
void blink_led(int duration_ms, int period_ms);
void signal_handler(int signal);

// Structure for ADS1115 configuration
typedef struct {
    uint16_t config;
} ads1115_config_t;

// Function to initialize the I2C bus
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }

    // Configure ADS1115 for single-ended AIN0, 4.096V PGA, continuous conversion
    ads1115_config_t config;
    config.config = 0x4003; // 0b0100000000000011
    char buf[3];
    buf[0] = ADS1115_CONFIG_REG;
    buf[1] = (config.config >> 8) & 0xFF;
    buf[2] = config.config & 0xFF;

    int result = i2cWriteDevice(i2c_handle, buf, 3);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        i2cClose(i2c_handle);
        return -1;
    }

    return 0;
}

// Function to read the ADC value from the ADS1115
int16_t read_adc() {
    char buf[1];
    buf[0] = ADS1115_CONVERSION_REG;

    int result = i2cWriteDevice(i2c_handle, buf, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C device (conversion reg select): %d\n", result);
        return -1;
    }

    char read_buf[2];
    result = i2cReadDevice(i2c_handle, read_buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1;
    }

    int16_t adc_value = (read_buf[0] << 8) | read_buf[1];
    return adc_value;
}

// Function to calculate the magnetic field strength in Gauss
double calculate_gauss(int16_t adc_value) {
    // Sensitivity for ADS1115 with 4.096V PGA is approximately 0.125 mV/Gauss
    // Assuming Vref = 4.096V, and ADC resolution is 16 bits (2^15)
    double voltage = (adc_value * 4.096) / 32768.0; // Convert ADC value to voltage
    double gauss = voltage / 0.000125; // Convert voltage to Gauss
    return gauss;
}

// Function to blink the LED
void blink_led(int duration_ms, int period_ms) {
    int num_blinks = duration_ms / period_ms;
    for (int i = 0; i < num_blinks; ++i) {
        gpioWrite(GPIO_LED, 1); // Turn LED on
        gpioDelay(period_ms / 2); // Wait for half the period
        gpioWrite(GPIO_LED, 0); // Turn LED off
        gpioDelay(period_ms / 2); // Wait for half the period
    }
}

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    gpioWrite(GPIO_LED, 0); // Turn off LED
    i2cClose(i2c_handle); // Close I2C connection
    gpioTerminate(); // Terminate pigpio
    exit(0);
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    if (argc > 1) {
        threshold = atof(argv[1]);
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO17 as output
    gpioSetMode(GPIO_LED, PI_OUTPUT);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        int16_t adc_value = read_adc();
        if (adc_value == -1) {
            fprintf(stderr, "Error reading ADC value, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        double gauss = calculate_gauss(adc_value);
        printf("Magnetic field strength: %.2f Gauss\n", gauss);

        if (fabs(gauss) > threshold) {
            printf("Threshold exceeded! Blinking LED...\n");
            blink_led(BLINK_DURATION_MS, BLINK_PERIOD_MS);
        }

        gpioDelay(100); // Wait 100ms
    }

    return 0;
}

