#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <time.h>
#include <pigpio.h>
#include <mosquitto.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define PUMP_GPIO 17
#define MOISTURE_THRESHOLD_LOW 30
#define MOISTURE_THRESHOLD_HIGH 35
#define MQTT_BROKER "localhost" // Replace with your MQTT broker address
#define MQTT_PORT 1883
#define MQTT_TOPIC "soil_moisture"
#define MQTT_PUMP_CONTROL_TOPIC "pump_control"
#define PUMP_ON_COMMAND "pump_on"
#define PUMP_OFF_COMMAND "pump_off"
#define PUMP_ON_DELAY 5 // seconds
#define PUMP_OFF_DELAY 5 // seconds

// Global variables
int spi_handle;
struct mosquitto *mosq = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float calculate_moisture_percentage(int adc_value);
void control_pump(int state);
void publish_moisture(float moisture_percentage);
void subscribe_pump_control();
void on_connect(struct mosquitto *mosq, void *userdata, int result);
void on_message(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message);
void signal_handler(int signum);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        syslog(LOG_ERR, "Invalid MCP3008 channel: %d", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00;

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) != 0) {
        syslog(LOG_ERR, "SPI transfer failed");
        return -1;
    }

    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to calculate moisture percentage
float calculate_moisture_percentage(int adc_value) {
    if (adc_value < 0 || adc_value > 1023) {
        syslog(LOG_ERR, "ADC value out of range: %d", adc_value);
        return -1.0;
    }

    // Linear mapping: 0 ADC = 100% moisture, 1023 ADC = 0% moisture
    float moisture_percentage = 100.0 - ((float)adc_value / 1023.0) * 100.0;
    return moisture_percentage;
}

// Function to control the pump
void control_pump(int state) {
    if (gpioWrite(PUMP_GPIO, state) != 0) {
        syslog(LOG_ERR, "Failed to write to GPIO %d", PUMP_GPIO);
    } else {
        syslog(LOG_INFO, "Pump set to state: %d", state);
    }
}

// Function to publish moisture data to MQTT
void publish_moisture(float moisture_percentage) {
    char payload[20];
    snprintf(payload, sizeof(payload), "%.2f", moisture_percentage);

    int ret = mosquitto_publish(mosq, NULL, MQTT_TOPIC, strlen(payload), payload, 0, false);
    if (ret != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "Failed to publish message: %s", mosquitto_strerror(ret));
    } else {
        syslog(LOG_INFO, "Published moisture: %.2f to topic: %s", moisture_percentage, MQTT_TOPIC);
    }
}

// Function to subscribe to pump control commands
void subscribe_pump_control() {
    int ret = mosquitto_subscribe(mosq, NULL, MQTT_PUMP_CONTROL_TOPIC, 0);
    if (ret != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "Failed to subscribe to topic: %s", MQTT_PUMP_CONTROL_TOPIC);
    } else {
        syslog(LOG_INFO, "Subscribed to topic: %s", MQTT_PUMP_CONTROL_TOPIC);
    }
}

// MQTT callbacks
void on_connect(struct mosquitto *mosq, void *userdata, int result) {
    if (result == MOSQ_ERR_SUCCESS) {
        syslog(LOG_INFO, "MQTT connected to broker");
        subscribe_pump_control();
    } else {
        syslog(LOG_ERR, "MQTT connection error: %s", mosquitto_connack_string(result));
    }
}

void on_message(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message) {
    if (message->payloadlen > 0) {
        syslog(LOG_INFO, "Received message on topic: %s, payload: %s", message->topic, (char *)message->payload);

        if (strcmp(message->topic, MQTT_PUMP_CONTROL_TOPIC) == 0) {
            if (strcmp((char *)message->payload, PUMP_ON_COMMAND) == 0) {
                control_pump(1);
                sleep(PUMP_ON_DELAY);
                control_pump(0);
            } else if (strcmp((char *)message->payload, PUMP_OFF_COMMAND) == 0) {
                control_pump(0);
                sleep(PUMP_OFF_DELAY);
                control_pump(1);
            }
        }
    }
}

// Signal handler
void signal_handler(int signum) {
    syslog(LOG_INFO, "Signal received: %d, terminating...", signum);
    terminate = 1;
}

int main() {
    // Initialize syslog
    openlog("soil_monitor", LOG_PID | LOG_CONS, LOG_USER);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    // Set pump GPIO as output
    gpioSetMode(PUMP_GPIO, PI_OUTPUT);
    control_pump(0); // Ensure pump is off at startup

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 1MHz, Mode 0
    if (spi_handle < 0) {
        syslog(LOG_ERR, "SPI open failed");
        gpioTerminate();
        closelog();
        return 1;
    }

    // Initialize MQTT
    mosquitto_lib_init();
    mosq = mosquitto_new(NULL, true, NULL);
    if (!mosq) {
        syslog(LOG_ERR, "Failed to create mosquitto instance");
        spiClose(spi_handle);
        gpioTerminate();
        closelog();
        return 1;
    }

    mosquitto_connect_callback_set(mosq, on_connect);
    mosquitto_message_callback_set(mosq, on_message);

    int ret = mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, 60);
    if (ret != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "Failed to connect to MQTT broker: %s", mosquitto_strerror(ret));
        mosquitto_destroy(mosq);
        spiClose(spi_handle);
        gpioTerminate();
        mosquitto_lib_cleanup();
        closelog();
        return 1;
    }

    mosquitto_loop_start(mosq);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        int adc_value = read_mcp3008(0);
        if (adc_value >= 0) {
            float moisture_percentage = calculate_moisture_percentage(adc_value);
            if (moisture_percentage >= 0) {
                publish_moisture(moisture_percentage);

                // Hysteresis control
                static int pump_state = 0; // 0 = off, 1 = on
                if (moisture_percentage < MOISTURE_THRESHOLD_LOW && pump_state == 0) {
                    control_pump(1);
                    pump_state = 1;
                    syslog(LOG_INFO, "Moisture below threshold, turning pump ON");
                } else if (moisture_percentage > MOISTURE_THRESHOLD_HIGH && pump_state == 1) {
                    control_pump(0);
                    pump_state = 0;
                    syslog(LOG_INFO, "Moisture above threshold, turning pump OFF");
                }
            } else {
                syslog(LOG_ERR, "Invalid moisture percentage");
            }
        } else {
            syslog(LOG_ERR, "Failed to read ADC value");
        }

        sleep(60);
    }

    // Cleanup
    mosquitto_loop_stop(mosq, false);
    mosquitto_disconnect(mosq);
    mosquitto_destroy(mosq);
    mosquitto_lib_cleanup();
    spiClose(spi_handle);
    control_pump(0);
    gpioTerminate();
    closelog();

    return 0;
}

