#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// SPI device file descriptor
int spi_fd = -1;

// Function to handle SIGINT (Ctrl+C)
void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, cleaning up...\n", sig);
    if (spi_fd != -1) {
        close(spi_fd);
    }
    exit(0);
}

// Function to read from MCP3008 channel
int read_mcp3008(int channel) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];
    struct spi_ioc_transfer transfer[1];

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel << 4)); // Single-ended mode, channel selection
    tx_buf[2] = 0x00; // Don't care

    // Configure SPI transfer
    transfer[0].tx_buf = (unsigned long)tx_buf;
    transfer[0].rx_buf = (unsigned long)rx_buf;
    transfer[0].len = 3;
    transfer[0].speed_hz = 1000000; // 1 MHz
    transfer[0].bits_per_word = 8;
    transfer[0].delay_usecs = 0;

    // Perform SPI transfer
    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), transfer) < 0) {
        fprintf(stderr, "Error: SPI_IOC_MESSAGE failed: %s\n", strerror(errno));
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buf[1] & 0x03) << 8) | rx_buf[2];

    return adc_value;
}

int main() {
    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Open SPI device
    spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Error: Could not open SPI device: %s\n", strerror(errno));
        return 1;
    }

    // Configure SPI mode
    uint8_t mode = 0; // SPI mode 0
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error: Could not set SPI mode: %s\n", strerror(errno));
        close(spi_fd);
        return 1;
    }

    // Configure bits per word
    uint8_t bits = 8;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error: Could not set bits per word: %s\n", strerror(errno));
        close(spi_fd);
        return 1;
    }

    // Configure max speed
    uint32_t speed = 1000000; // 1 MHz
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error: Could not set max speed: %s\n", strerror(errno));
        close(spi_fd);
        return 1;
    }

    // Main loop
    while (1) {
        // Read ADC value from channel 0
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            close(spi_fd);
            return 1;
        }

        // Calculate voltage
        float voltage = (adc_value / 1023.0) * 3.3;

        // Print raw value and voltage
        printf("Raw: %d, Voltage: %.2f V\n", adc_value, voltage);

        // Wait 500 ms
        usleep(500000);
    }

    // Close SPI device (should not reach here in normal execution)
    close(spi_fd);
    return 0;
}

