#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <math.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define BH1750_ADDR 0x23
#define BH1750_CONTINUOUS_HIGH_RES_MODE 0x10
#define LOG_FILE "tamper_log.csv"
#define SAMPLE_INTERVAL 5 // seconds

// Global variables
int spi_handle;
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_sound_level();
int read_light_level();
void log_data(int sound_level_db, float light_level_lux, int error_code);
void signal_handler(int signal);
int initialize();
void cleanup();

// Function to initialize the system
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(1, BH1750_ADDR, 0); // Bus 1, address 0x23, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C open failed: %d\n", i2c_handle);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Configure BH1750 for continuous high-resolution mode
    if (i2cWriteByteData(i2c_handle, 0x00, BH1750_CONTINUOUS_HIGH_RES_MODE) < 0) {
        fprintf(stderr, "I2C write failed\n");
        i2cClose(i2c_handle);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,sound_level_db,light_level_lux,error_code\n");
    }

    return 0;
}

// Function to read sound level from MCP3008
int read_sound_level() {
    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];
    int adc_value;

    // MCP3008 configuration: single-ended, channel 0
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = 0x80; // Single-ended, channel 0 (0b10000000)
    spi_tx_buf[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3) < 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1; // Indicate error
    }

    // Extract ADC value (10 bits)
    adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    // Convert ADC value to voltage (assuming 3.3V reference)
    float voltage = (float)adc_value * 3.3 / 1024.0;

    // Convert voltage to sound level (dB) - Example formula, adjust as needed
    // This is a simplified example.  A proper dB calculation requires calibration.
    int sound_level_db = (int)(20 * log10(voltage / 0.00002)); // Example: Assuming 20uV is the reference

    return sound_level_db;
}

// Function to read light level from BH1750
int read_light_level() {
    unsigned char data[2];
    int lux;

    // Read 2 bytes from BH1750
    if (i2cReadI2CBlockData(i2c_handle, 0x00, (char *)data, 2) != 2) {
        fprintf(stderr, "I2C read failed\n");
        return -1; // Indicate error
    }

    // Combine the two bytes to form the lux value
    lux = (data[0] << 8) | data[1];

    return lux;
}

// Function to log data to CSV file
void log_data(int sound_level_db, float light_level_lux, int error_code) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%d,%.2f,%d\n", timestamp, sound_level_db, light_level_lux, error_code);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Function to cleanup resources
void cleanup() {
    printf("Cleaning up resources...\n");
    if (spi_handle >= 0) spiClose(spi_handle);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    if (log_file != NULL) fclose(log_file);
    gpioTerminate();
    printf("Cleanup complete. Exiting.\n");
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the system
    if (initialize()) {
        fprintf(stderr, "Initialization failed, exiting\n");
        return 1;
    }

    printf("Tamper detection system started. Logging data to %s\n", LOG_FILE);

    // Main loop
    while (!terminate) {
        int sound_level_db = read_sound_level();
        int light_level_lux = read_light_level();
        int error_code = 0;

        if (sound_level_db < 0) {
            error_code |= 1; // ADC read error
        }
        if (light_level_lux < 0) {
            error_code |= 2; // I2C read error
        }

        log_data(sound_level_db, (float)light_level_lux, error_code);

        sleep(SAMPLE_INTERVAL);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

