    gpioSetMode(RELAY_GPIO, PI_OUTPUT);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    printf("Door monitoring system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            continue; // Try again
        }

        float distance = adc_to_distance(adc_value);

        if (distance < DISTANCE_THRESHOLD) {
            control_relay(1); // Activate relay
            log_event(distance);
            gpioDelay(DEBOUNCE_DELAY * 1000000); // Debounce delay (microseconds)
            control_relay(0); // Deactivate relay
        }

        gpioDelay(100000); // Poll every 100ms (microseconds)
    }

    // Cleanup
    spiClose(spi_handle);
    gpioWrite(RELAY_GPIO, 0); // Ensure relay is off
    fclose(log_file);
    gpioTerminate();

    printf("Door monitoring system stopped.\n");
    return 0;
}

