        }

        // Calculate average
        int average = calculate_average(samples, NUM_SAMPLES);

        // Set valve position
        int duty_cycle = 0;
        if (average >= 0) {
            // Map average to duty cycle (0-10000) - Example mapping
            duty_cycle = (int)(((float)average / 1023.0) * PWM_RANGE); // Assuming 10-bit ADC
            if (duty_cycle < 0) duty_cycle = 0;
            if (duty_cycle > PWM_RANGE) duty_cycle = PWM_RANGE;
            set_valve_position(duty_cycle);
        }

        // Log data
        log_data(samples[0], samples[1], samples[2], average, duty_cycle);

        gpioDelay(LOG_INTERVAL_S * 1000000); // Delay between log entries
    }

    // Shutdown sequence
    printf("Shutting down...\n");
    set_valve_position(0); // Close valve
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    printf("Irrigation system stopped.\n");
    return 0;
}

