// Structure for configuration (optional)
typedef struct {
    int spi_channel;
    int spi_speed;
    int spi_mode;
    int cs_pin;
    int retry_count;
    int backoff_base;
    char log_file[64];
} config_t;

config_t config = {
    SPI_CHANNEL,
    SPI_SPEED,
    SPI_MODE,
    CS_PIN,
    RETRY_COUNT,
    BACKOFF_BASE,
    LOG_FILE
};

int main() {
    if (initialize() != 0) {
        fprintf(stderr, "Initialization failed. Exiting.\n");
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (!terminate) {
        int adc_value = read_mcp3008(0);
        if (adc_value >= 0) {
            float moisture_percentage = convert_to_moisture_percentage(adc_value);
            log_data(moisture_percentage);
        } else {
            fprintf(stderr, "Failed to read ADC value. Skipping.\n");
        }
        sleep(5);
    }

    cleanup();
    return 0;
}

int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(config.cs_pin, PI_OUTPUT);
    gpioWrite(config.cs_pin, 1); // Ensure CS is initially high

    spi_handle = spiOpen(config.spi_channel, config.spi_speed, config.spi_mode);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    return 0;
}

