    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid channel number: %d\n", channel);
        return -1;
    }

    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    // Construct SPI message
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel selection
    spi_tx_buf[2] = 0x00; // Don't care

    for (int i = 0; i < config.retry_count; ++i) {
        gpioWrite(config.cs_pin, 0); // Select the MCP3008
        int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
        gpioWrite(config.cs_pin, 1); // Deselect the MCP3008

        if (result == 3) {
            // Extract ADC value (10 bits)
            int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];
            return adc_value;
        } else {
            fprintf(stderr, "SPI transfer failed (attempt %d): %d\n", i + 1, result);
            usleep(config.backoff_base * (1 << i)); // Exponential backoff
        }
    }

    fprintf(stderr, "SPI communication failed after %d retries.\n", config.retry_count);
    return -1; // Indicate failure
}

