#include <pigpio.h>
#include <math.h>

// Define GPIO pins
#define TRIG_PIN 23
#define ECHO_PIN 24
#define LDR_PIN 10 // MCP3008 channel 0

// Define PWM parameters
#define PWM_GPIO 18
#define PWM_FREQUENCY 440
#define PWM_RANGE 1000

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz

// Define calibration file
#define CALIBRATION_FILE "theremin_config.txt"

// Define error value for sensor readings
#define ERROR_VALUE -1.0

// Global variables
static volatile int running = 1;
static float last_valid_distance = 0.0;
static int last_valid_volume = 0;
static int spi_handle;
static float distance_offset = 0.0;
static float distance_scale = 1.0;
static int volume_offset = 0;
static int volume_scale = 100;

// Function prototypes
void signal_handler(int signal);
float get_distance();
int get_ldr_value();
void set_frequency(float frequency);
void set_volume(int volume);
void log_data(float distance, int volume);
void load_calibration();
void save_calibration();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
    gpioPWM(PWM_GPIO, 0); // Stop PWM
    gpioTerminate();       // Terminate pigpio
    exit(0);
}

// Function to measure distance using HC-SR04
float get_distance() {
    gpioWrite(TRIG_PIN, 1);
    gpioDelay(10); // 10us trigger pulse
    gpioWrite(TRIG_PIN, 0);

    long long start_tick = 0, end_tick = 0;

    // Wait for echo to start
    int timeout = 10000; // 10ms timeout
    while (gpioRead(ECHO_PIN) == 0 && timeout > 0) {
        timeout--;
        gpioDelay(1); // Check every 1 us
    }

    if (timeout <= 0) {
        fprintf(stderr, "Error: Echo start timeout\n");
        return ERROR_VALUE;
    }

    start_tick = gpioTick();

    // Wait for echo to end
    timeout = 10000; // 10ms timeout
    while (gpioRead(ECHO_PIN) == 1 && timeout > 0) {
        timeout--;
        gpioDelay(1); // Check every 1 us
    }

    if (timeout <= 0) {
        fprintf(stderr, "Error: Echo end timeout\n");
        return ERROR_VALUE;
    }

    end_tick = gpioTick();

    double diff = (double)(end_tick - start_tick);
    float distance = (diff / 2.0) / 29.1; // Speed of sound: 29.1 us/cm

    return distance;
}

