int get_ldr_value() {
    unsigned char spi_data[3];
    int adc_value;

    // MCP3008 command to read channel 0 (single-ended)
    spi_data[0] = 0x01; // Start bit
    spi_data[1] = 0x80; // Single-ended, channel 0
    spi_data[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, spi_data, spi_data, 3) != 0) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1;
