// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0
#define FAN_GPIO 18
#define LOG_FILE "air_quality.log"
#define NUM_SENSORS 3
#define MAX_RETRIES 3
#define RETRY_DELAY 1 // seconds

// Sensor Calibration Data (Example - Replace with your sensor's calibration data)
