float sensor_calibration[NUM_SENSORS][2] = {
    {0.1, 50.0},   // Sensor 0: Slope, Intercept
    {0.15, 60.0},  // Sensor 1: Slope, Intercept
    {0.2, 70.0}    // Sensor 2: Slope, Intercept
};

// Global Variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function Prototypes
int read_mcp3008(int channel);
float calculate_aqi(int adc_value, int sensor_index);
void log_data(int sensor_index, float aqi);
void control_fan(float aqi);
void signal_handler(int signal);
int initialize_spi();
void cleanup();

// Function to read data from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char spi_tx_buf[3];
    char spi_rx_buf[3];

    // Construct SPI message (MCP3008 datasheet)
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    int retries = 0;
    int result;

    while (retries < MAX_RETRIES) {
        result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
        if (result == 0) {
            // Extract ADC value (10 bits)
            int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];
            return adc_value;
        } else {
            fprintf(stderr, "SPI communication error (attempt %d): %d\n", retries + 1, result);
            gpioDelay(RETRY_DELAY * 1000); // Delay in milliseconds
            retries++;
        }
    }

    fprintf(stderr, "Failed to read MCP3008 after %d retries. Re-initializing SPI.\n", MAX_RETRIES);
    cleanup(); // Close existing SPI
    if (initialize_spi() != 0) {
        fprintf(stderr, "Failed to re-initialize SPI. Exiting.\n");
        return -1; // Indicate failure
    }
    return -1; // Indicate failure
}

// Function to calculate AQI from ADC value (Placeholder - Replace with actual AQI calculation)
float calculate_aqi(int adc_value, int sensor_index) {
    // This is a placeholder.  You MUST implement the correct AQI calculation
    // based on the sensor's datasheet and calibration data.
    // The following is a linear approximation for demonstration purposes.
    float slope = sensor_calibration[sensor_index][0];
    float intercept = sensor_calibration[sensor_index][1];
    float aqi = slope * adc_value + intercept;

    // Ensure AQI is within a reasonable range (e.g., 0-500)
    if (aqi < 0) aqi = 0;
    if (aqi > 500) aqi = 500;

    return aqi;
}

// Function to log data to file
void log_data(int sensor_index, float aqi) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Sensor %d, AQI: %.2f\n", timestamp, sensor_index, aqi);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Function to control the ventilation fan
void control_fan(float aqi) {
    if (aqi > 100) {
        gpioWrite(FAN_GPIO, 1); // Turn fan ON
        printf("Fan ON (AQI: %.2f)\n", aqi);
    } else {
        gpioWrite(FAN_GPIO, 0); // Turn fan OFF
        printf("Fan OFF (AQI: %.2f)\n", aqi);
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Received signal %d. Shutting down...\n", signal);
    program_running = 0;
}

// Function to initialize SPI
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: Could not open SPI channel %d: %d\n", SPI_CHANNEL, spi_handle);
        return -1;
    }
    return 0;
}

// Function to cleanup resources
void cleanup() {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioWrite(FAN_GPIO, 0); // Ensure fan is OFF
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set FAN_GPIO as output
    gpioSetMode(FAN_GPIO, PI_OUTPUT);
    gpioWrite(FAN_GPIO, 0); // Initially turn the fan OFF

    // Initialize SPI
    if (initialize_spi() != 0) {
        fprintf(stderr, "Failed to initialize SPI. Exiting.\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file %s\n", LOG_FILE);
        cleanup();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Air quality monitoring started. Press Ctrl+C to exit.\n");

    while (program_running) {
        for (int i = 0; i < NUM_SENSORS; i++) {
            int adc_value = read_mcp3008(i);
            if (adc_value >= 0) {
                float aqi = calculate_aqi(adc_value, i);
                log_data(i, aqi);
                control_fan(aqi);
            } else {
                fprintf(stderr, "Error reading sensor %d\n", i);
            }
        }
        gpioDelay(5000); // Wait 5 seconds
    }

    // Cleanup and exit
    cleanup();
    printf("Air quality monitoring stopped.\n");
    return 0;
}

