        // Wait for 1 second
        gpioDelay(1000);
    }

    // Close log file
    fclose(log_file);

    // Close SPI channel
    spiClose(spi_handle);

    // Terminate pigpio library
    gpioTerminate();

    printf("Program terminated gracefully.\n");
