void log_data(int moisture_value, int pump_state) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    const char *pump_status = (pump_state == 1) ? "ON" : "OFF";

    fprintf(log_file, "%s - Moisture: %d, Pump: %s\n", timestamp, moisture_value, pump_status);
    fflush(log_file); // Ensure data is written to disk immediately
}

