        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI interface
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // SPI channel 0, 1MHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set pump GPIO as output
    gpioSetMode(PUMP_GPIO, PI_OUTPUT);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Soil Moisture Monitoring and Irrigation System started.\n");

    // Main loop
    while (!terminate) {
        // Read moisture value from sensor
        int moisture_value = read_mcp3008(0);
        if (moisture_value < 0) {
            fprintf(stderr, "Error: Failed to read moisture value\n");
            fprintf(log_file, "Error: Failed to read moisture value\n");
            fflush(log_file);
        } else {
            // Control pump based on moisture threshold
            int pump_state = (moisture_value < MOISTURE_THRESHOLD) ? 1 : 0;
            control_pump(pump_state);

            // Log data
            log_data(moisture_value, pump_state);

            printf("Moisture: %d, Pump: %s\n", moisture_value, (pump_state == 1) ? "ON" : "OFF");
        }

        // Wait for 60 seconds
        gpioDelay(60000); // pigpio's delay function in milliseconds
    }

    // Cleanup
    printf("Cleaning up...\n");
    control_pump(0); // Turn off pump
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

