#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define MOTOR1_DIR 23
#define MOTOR2_DIR 25
#define MOTOR1_PWM 18
#define MOTOR2_PWM 24
#define SPI_CE0 8
#define SPI_MOSI 10
#define SPI_MISO 9
#define SPI_SCLK 11

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0

// Define motor speed range
#define MIN_SPEED 0
#define MAX_SPEED 255

// Define acceleration/deceleration parameters
#define ACCELERATION_STEPS 100
#define DECELERATION_STEPS 100
#define ACCELERATION_DELAY_US 1000 // 1 ms
#define DECELERATION_DELAY_US 1000 // 1 ms

// Define speed hold time
#define SPEED_HOLD_TIME_S 2

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
int map_potentiometer_to_speed(int potentiometer_value);
void set_motor_speed(int motor_pin, int speed);
void accelerate_motor(int motor_pin, int target_speed);
void decelerate_motor(int motor_pin, int target_speed);
void reverse_motor_direction(int motor1_dir_pin, int motor2_dir_pin);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    terminate = 1;
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed with code %d\n", result);
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to map potentiometer value to motor speed
int map_potentiometer_to_speed(int potentiometer_value) {
    // Ensure potentiometer value is within valid range
    if (potentiometer_value < 0) potentiometer_value = 0;
    if (potentiometer_value > 1023) potentiometer_value = 1023;

    // Map potentiometer value (0-1023) to speed (0-255)
    int speed = (int)(((float)potentiometer_value / 1023.0) * 255.0);

    return speed;
}

// Function to set motor speed using PWM
void set_motor_speed(int motor_pin, int speed) {
    gpioPWM(motor_pin, speed);
}

// Function to accelerate motor
void accelerate_motor(int motor_pin, int target_speed) {
    int current_speed = 0;
    for (int i = 0; i < ACCELERATION_STEPS; i++) {
        current_speed = (int)(((float)i / ACCELERATION_STEPS) * target_speed);
        set_motor_speed(motor_pin, current_speed);
        gpioDelay(ACCELERATION_DELAY_US);
    }
    set_motor_speed(motor_pin, target_speed);
}

// Function to decelerate motor
void decelerate_motor(int motor_pin, int target_speed) {
    int current_speed = target_speed;
    for (int i = 0; i < DECELERATION_STEPS; i++) {
        current_speed = (int)(((float)i / DECELERATION_STEPS) * target_speed);
        set_motor_speed(motor_pin, current_speed);
        gpioDelay(DECELERATION_DELAY_US);
    }
    set_motor_speed(motor_pin, 0);
}

// Function to reverse motor direction
void reverse_motor_direction(int motor1_dir_pin, int motor2_dir_pin) {
    gpioWrite(motor1_dir_pin, 1); // Motor 1 forward
    gpioWrite(motor2_dir_pin, 0); // Motor 2 backward
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Configure GPIO pins for motor control
    gpioSetMode(MOTOR1_DIR, PI_OUTPUT);
    gpioSetMode(MOTOR2_DIR, PI_OUTPUT);
    gpioSetMode(MOTOR1_PWM, PI_OUTPUT);
    gpioSetMode(MOTOR2_PWM, PI_OUTPUT);

    // Configure SPI interface
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
