    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Calibrate noise level
    int noise_level = calibrate_noise_level(5);
    if (noise_level == -1) {
        fprintf(stderr, "Error: Noise calibration failed.\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Sound level monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        int adc_value = read_mcp3008(0);
        if (adc_value == -1) {
            fprintf(stderr, "Error: Failed to read ADC value.\n");
            continue; // Try again
        }

        int sound_exceeds_threshold = check_sound_level(adc_value, noise_level);

        if (sound_exceeds_threshold) {
            gpioWrite(LED_PIN, 1); // Turn on LED
            gpioDelay(DEBOUNCE_TIME); // Debounce
            gpioWrite(LED_PIN, 0); // Turn off LED
        }

        gpioDelay(10); // Check every 10ms
    }

    return 0;
}

