#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define ADC_CHANNEL 0
#define VREF 3.3
#define LOG_FILE "airflow_log.txt"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Calibration curve data (example)
const int num_calibration_points = 5;
const float voltage_values[] = {0.5, 1.0, 1.5, 2.0, 2.5};
const float airflow_values[] = {0.0, 20.0, 40.0, 60.0, 80.0};

// Function prototypes
int read_adc(int channel);
float voltage_to_airflow(float voltage);
char* get_timestamp();
void log_data(float airflow);
void signal_handler(int signal);
int initialize();
void cleanup();

// Function to read ADC value from MCP3008
int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "ERROR: Invalid ADC channel %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message (MCP3008 datasheet)
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) != 0) {
        fprintf(stderr, "ERROR: SPI transfer failed\n");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to convert voltage to airflow (linear interpolation)
float voltage_to_airflow(float voltage) {
    if (voltage <= voltage_values[0]) {
        return airflow_values[0];
    }
    if (voltage >= voltage_values[num_calibration_points - 1]) {
        return airflow_values[num_calibration_points - 1];
    }

    for (int i = 0; i < num_calibration_points - 1; i++) {
        if (voltage >= voltage_values[i] && voltage <= voltage_values[i + 1]) {
            float fraction = (voltage - voltage_values[i]) / (voltage_values[i + 1] - voltage_values[i]);
            return airflow_values[i] + fraction * (airflow_values[i + 1] - airflow_values[i]);
        }
    }

    return -1.0; // Should not reach here
}

// Function to get current timestamp
char* get_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    static char timestamp[20]; //YYYY-MM-DD HH:MM:SS\0

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    return timestamp;
}

// Function to log data to file
void log_data(float airflow) {
    char *timestamp = get_timestamp();
    fprintf(log_file, "%s, %.2f\n", timestamp, airflow);
    fflush(log_file); // Ensure data is written immediately
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialization function
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "ERROR: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // SPI channel 0, 1MHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "ERROR: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "ERROR: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize
    if (initialize()) {
        return 1;
    }

    printf("Airflow monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        int adc_value = read_adc(ADC_CHANNEL);
        if (adc_value >= 0) {
            float voltage = (float)adc_value * VREF / 1023.0;
            float airflow = voltage_to_airflow(voltage);

            if (airflow >= 0.0) {
                log_data(airflow);
                printf("Airflow: %.2f\n", airflow);
            } else {
                fprintf(stderr, "ERROR: Invalid airflow value\n");
            }
        } else {
            fprintf(stderr, "ERROR: ADC read failed\n");
        }

        gpioDelay(100); // 100 ms delay
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

