        return -1;
    }

    if (write(fd, value ? "1" : "0", 1) < 0) {
        perror("Error writing to GPIO value file");
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

// GPIO Unexport
int gpio_unexport(int pin) {
    char buffer[3];
    ssize_t bytes_written;
    int fd = open("/sys/class/gpio/unexport", O_WRONLY);
    if (fd < 0) {
        perror("Error opening /sys/class/gpio/unexport");
        return -1;
    }

    int len = snprintf(buffer, sizeof(buffer), "%d", pin);
    bytes_written = write(fd, buffer, len);
    close(fd);
    if (bytes_written < 0) {
        perror("Error writing to /sys/class/gpio/unexport");
        return -1;
    }
    return 0;
}

// Log Data
int log_data(FILE *fp, uint64_t timestamp_ns, int adc_value) {
    if (fprintf(fp, "%llu|%d\n", timestamp_ns, adc_value) < 0) {
        perror("Error writing to log file");
        return -1;
    }
    fflush(fp);
    return 0;
}

// Signal Handler
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    struct timespec req, rem;
    struct timespec ts;
    uint64_t timestamp_ns;
    int adc_value;
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];
    int i;

    // Signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // SPI Initialization
    spi_fd = spi_init(SPI_DEVICE);
    if (spi_fd < 0) {
        fprintf(stderr, "SPI initialization failed. Exiting.\n");
        return 1;
    }

    // GPIO Initialization
    if (gpio_export(GPIO_PIN) < 0) {
        fprintf(stderr, "GPIO export failed. Exiting.\n");
        close(spi_fd);
        return 1;
    }
    if (gpio_set_direction(GPIO_PIN, "out") < 0) {
        fprintf(stderr, "GPIO set direction failed. Exiting.\n");
        gpio_unexport(GPIO_PIN);
        close(spi_fd);
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpio_unexport(GPIO_PIN);
        close(spi_fd);
        return 1;
    }

    // Main loop
    req.tv_sec = 0;
    req.tv_nsec = SAMPLE_PERIOD_NS;

    while (!terminate) {
        // Toggle chip select
        if (gpio_set_value(GPIO_PIN, 0) < 0) {
            fprintf(stderr, "Error setting GPIO value low. Exiting.\n");
            break;
        }
        usleep(1); // Small delay for CS to settle

        // MCP3008 Command: Start bit (1), Single-ended mode (1), Channel 0 (000), Don't care (0)
        tx_buf[0] = 0x01; // Start bit
        tx_buf[1] = 0x80; // Single-ended, channel 0
        tx_buf[2] = 0x00; // Don't care

        // SPI Transfer
        if (spi_transfer(spi_fd, tx_buf, rx_buf, 3) < 0) {
            fprintf(stderr, "SPI transfer failed. Exiting.\n");
            break;
        }

        // Extract ADC value (10 bits)
        adc_value = ((rx_buf[1] & 0x03) << 8) | rx_buf[2];

        // Toggle chip select
        if (gpio_set_value(GPIO_PIN, 1) < 0) {
            fprintf(stderr, "Error setting GPIO value high. Exiting.\n");
            break;
        }
        usleep(1); // Small delay for CS to settle

        // Get timestamp
        if (clock_gettime(CLOCK_MONOTONIC_RAW, &ts) < 0) {
            perror("Error getting timestamp");
            break;
        }
        timestamp_ns = (uint64_t)ts.tv_sec * 1000000000ULL + (uint64_t)ts.tv_nsec;

        // Log data
        if (log_data(log_file, timestamp_ns, adc_value) < 0) {
            fprintf(stderr, "Logging failed. Exiting.\n");
            break;
        }

        // Sleep until next sample
        if (nanosleep(&req, &rem) < 0) {
            if (errno == EINTR) {
                fprintf(stderr, "Sleep interrupted by signal.\n");
            } else {
                perror("nanosleep failed");
                break;
            }
        }
    }

    // Cleanup
    if (log_file) fclose(log_file);
    if (spi_fd >= 0) close(spi_fd);
    if (gpio_unexport(GPIO_PIN) < 0) {
        fprintf(stderr, "GPIO unexport failed.\n");
    }

    return 0;
}

