#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL 0
#define VREF 3.3
#define LOG_FILE "gas_log.txt"

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float voltage_to_ppm(float voltage);
void log_data(float voltage, float ppm);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message (MCP3008 datasheet)
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    // Perform SPI transaction
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transaction failed (error code: %d)\n", result);
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to convert voltage to PPM (placeholder)
float voltage_to_ppm(float voltage) {
    // Replace with actual calibration curve from datasheet
    // This is a placeholder linear conversion
    return voltage * 1000.0; // Example: 1V = 1000 PPM
}

// Function to log data to file
void log_data(float voltage, float ppm) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open log file %s\n", LOG_FILE);
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, %.3f, %.3f\n", timestamp, voltage, ppm);
    fclose(fp);
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 1MHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (error code: %d)\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Gas sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int adc_value = -1;
        int retries = 0;
        while (adc_value == -1 && retries < 3) {
            adc_value = read_mcp3008(MCP3008_CHANNEL);
            if (adc_value == -1) {
                fprintf(stderr, "Error: ADC read failed, retrying (%d/3)\n", retries + 1);
                gpioDelay(100); // 100 ms delay
                retries++;
            }
        }

        if (adc_value != -1) {
            float voltage = (float)adc_value * VREF / 1024.0;
            float ppm = voltage_to_ppm(voltage);

            printf("Voltage: %.3f V, PPM: %.3f\n", voltage, ppm);
            log_data(voltage, ppm);
        } else {
            fprintf(stderr, "Error: Failed to read ADC after multiple retries.\n");
        }

        gpioDelay(1000); // 1 second delay
    }

    // Clean up
    spiClose(spi_handle);
    gpioTerminate();

    printf("Gas sensor monitoring stopped.\n");

    return 0;
}

