#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <math.h>

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define SPI_FLAGS 0       // SPI mode 0

// Define MCP3008 channel assignments
#define X_CHANNEL 0
#define Y_CHANNEL 1
#define Z_CHANNEL 2

// Define reference voltage
#define VREF 3.3

// Define Kalman filter parameters
#define PROCESS_NOISE 0.01
#define MEASUREMENT_NOISE 0.1

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Kalman filter state
float x_state = 0.0;
float y_state = 0.0;
float z_state = 0.0;

// Kalman filter covariance
float x_covariance = 1.0;
float y_covariance = 1.0;
float z_covariance = 1.0;

// Function prototypes
int initialize_spi();
int read_mcp3008(int channel);
float adc_to_voltage(int adc_value);
float voltage_to_g(float voltage);
float kalman_filter(float measurement, float *state, float *covariance);
void print_acceleration(float x, float y, float z);
void signal_handler(int signal);

// Function to initialize SPI
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Function to read from MCP3008 channel
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    // Construct SPI message (MCP3008 datasheet)
    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    spi_tx_buf[0] = 0x01;                           // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4;          // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00;                           // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result != 3) {
        fprintf(stderr, "SPI transfer error: %d\n", result);
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

