    return (voltage - 1.65) / 0.3;
}

// Function to apply Kalman filter
float kalman_filter(float measurement, float *state, float *covariance) {
    // Prediction step
    float process_noise = PROCESS_NOISE;
    *state += 0.0; // No process model
    *covariance += process_noise;

    // Update step
    float measurement_noise = MEASUREMENT_NOISE;
    float kalman_gain = *covariance / (*covariance + measurement_noise);
    *state += kalman_gain * (measurement - *state);
    *covariance = (1 - kalman_gain) * *covariance;

    return *state;
}

// Function to print acceleration values
void print_acceleration(float x, float y, float z) {
    printf("X: %.2f g, Y: %.2f g, Z: %.2f g\n", x, y, z);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

