    signal(SIGTERM, signal_handler);

    // Initialize SPI
    if (initialize_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read ADC values from MCP3008 channels
        int x_adc = read_mcp3008(X_CHANNEL);
        int y_adc = read_mcp3008(Y_CHANNEL);
        int z_adc = read_mcp3008(Z_CHANNEL);

        if (x_adc < 0 || y_adc < 0 || z_adc < 0) {
            fprintf(stderr, "Error reading ADC values, retrying...\n");
            gpioDelay(100000); // 100ms delay
            continue;
        }

        // Convert ADC values to voltages
        float x_voltage = adc_to_voltage(x_adc);
        float y_voltage = adc_to_voltage(y_adc);
        float z_voltage = adc_to_voltage(z_adc);

        // Convert voltages to acceleration in g
        float x_g = voltage_to_g(x_voltage);
        float y_g = voltage_to_g(y_voltage);
        float z_g = voltage_to_g(z_voltage);

        // Apply Kalman filter
        x_g = kalman_filter(x_g, &x_state, &x_covariance);
        y_g = kalman_filter(y_g, &y_state, &y_covariance);
        z_g = kalman_filter(z_g, &z_state, &z_covariance);

        // Print acceleration values
        print_acceleration(x_g, y_g, z_g);

        // Delay for 100ms (10 Hz sampling rate)
        gpioDelay(100000);
    }

    // Close SPI
    spiClose(spi_handle);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

