#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <string.h>

// Define GPIO pins for the sensors
#define SENSOR1_GPIO 4
#define SENSOR2_GPIO 17
#define SENSOR3_GPIO 27

// Define the log file name
#define LOG_FILE "magnetic_log.txt"

// Define the magnetic field range
#define MIN_MAGNETIC_FIELD -100.0
#define MAX_MAGNETIC_FIELD 100.0

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    if (signal == SIGINT) {
        program_running = 0;
        fprintf(stderr, "\nCaught SIGINT, exiting gracefully...\n");
    }
}

// Function to read the sensor value from a GPIO pin
int read_sensor(int gpio_pin) {
    int value = gpioRead(gpio_pin);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d: %d\n", gpio_pin, value);
        return -1; // Indicate an error
    }
    return value;
}

// Function to convert the sensor value to magnetic field strength in millitesla
double convert_to_magnetic_field(int sensor_value) {
    return (sensor_value == 1) ? 3.3 : 0.0;
}

// Function to log the magnetic field values to a file
int log_magnetic_field(double sensor1_mT, double sensor2_mT, double sensor3_mT) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file %s\n", LOG_FILE);
        return -1;
    }

    fprintf(fp, "%.2f,%.2f,%.2f\n", sensor1_mT, sensor2_mT, sensor3_mT);
    fflush(fp); // Flush the buffer to ensure data is written to the file

    if (ferror(fp)) {
        fprintf(stderr, "Error writing to log file %s\n", LOG_FILE);
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs
    gpioSetMode(SENSOR1_GPIO, PI_INPUT);
    gpioSetMode(SENSOR2_GPIO, PI_INPUT);
    gpioSetMode(SENSOR3_GPIO, PI_INPUT);

    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        // Read sensor values
        int sensor1_value = read_sensor(SENSOR1_GPIO);
        int sensor2_value = read_sensor(SENSOR2_GPIO);
        int sensor3_value = read_sensor(SENSOR3_GPIO);

        // Check for errors during sensor reading
        if (sensor1_value == -1 || sensor2_value == -1 || sensor3_value == -1) {
            fprintf(stderr, "Error reading sensor values, skipping logging.\n");
            gpioDelay(100); // Wait 100ms before next iteration
            continue;
        }

        // Convert sensor values to magnetic field strengths
        double sensor1_mT = convert_to_magnetic_field(sensor1_value);
        double sensor2_mT = convert_to_magnetic_field(sensor2_value);
        double sensor3_mT = convert_to_magnetic_field(sensor3_value);

        // Validate magnetic field values
        if (sensor1_mT < MIN_MAGNETIC_FIELD || sensor1_mT > MAX_MAGNETIC_FIELD) {
            fprintf(stderr, "Warning: sensor1_mT (%.2f mT) out of range\n", sensor1_mT);
        }
        if (sensor2_mT < MIN_MAGNETIC_FIELD || sensor2_mT > MAX_MAGNETIC_FIELD) {
            fprintf(stderr, "Warning: sensor2_mT (%.2f mT) out of range\n", sensor2_mT);
        }
        if (sensor3_mT < MIN_MAGNETIC_FIELD || sensor3_mT > MAX_MAGNETIC_FIELD) {
            fprintf(stderr, "Warning: sensor3_mT (%.2f mT) out of range\n", sensor3_mT);
        }

        // Log the magnetic field values
        if (log_magnetic_field(sensor1_mT, sensor2_mT, sensor3_mT) != 0) {
            fprintf(stderr, "Error logging magnetic field values.\n");
        }

        // Wait for 100 milliseconds
        gpioDelay(100);
    }

    // Terminate the pigpio library
    gpioTerminate();

    return 0;
}

