#include <jansson.h>
#include <pigpio.h>

// Configuration
#define MQTT_BROKER "mqtt.eclipseprojects.io"
#define MQTT_PORT 1883
#define MQTT_TOPIC "home/led_control"
#define MQTT_CLIENT_ID "rpi_led_control"
#define GPIO_PIN 17
#define MAX_RECONNECT_DELAY 60 // seconds

// Global variables
static struct mosquitto *mosq = NULL;
static volatile int running = 1;
static int reconnect_delay = 1; // Initial reconnect delay in seconds

// Function prototypes
void signal_handler(int signum);
int connect_mqtt();
void on_connect(struct mosquitto *mosq, void *userdata, int result);
void on_message(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message);
int parse_json(const char *payload, int *led_state);
void set_led_state(int led_state);
void log_error(const char *message);

// Signal handler
void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        printf("Received signal %d, shutting down...\n", signum);
        running = 0;
    }
}

// Connect to MQTT broker with exponential backoff
int connect_mqtt() {
    int rc = mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, 60);
    if (rc != MOSQ_ERR_SUCCESS) {
        log_error("Failed to connect to MQTT broker");
        fprintf(stderr, "Error connecting to MQTT broker: %s\n", mosquitto_strerror(rc));
        reconnect_delay *= 2;
        if (reconnect_delay > MAX_RECONNECT_DELAY) {
            reconnect_delay = MAX_RECONNECT_DELAY;
        }
        return -1;
    }
    return 0;
}

// MQTT on_connect callback
void on_connect(struct mosquitto *mosq, void *userdata, int result) {
    if (result == MOSQ_ERR_SUCCESS) {
        printf("Connected to MQTT broker\n");
        mosquitto_subscribe(mosq, NULL, MQTT_TOPIC, 0);
    } else {
        log_error("MQTT connection failed");
        fprintf(stderr, "MQTT connection failed: %s\n", mosquitto_connack_string(result));
    }
}

// MQTT on_message callback
void on_message(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message) {
    if (message->payloadlen) {
        int led_state;
        if (parse_json(message->payload, &led_state) == 0) {
            set_led_state(led_state);
        } else {
            log_error("Failed to parse JSON payload");
        }
    } else {
        log_error("Empty MQTT message received");
    }
}

// Parse JSON payload
int parse_json(const char *payload, int *led_state) {
    json_error_t error;
    json_t *root = json_loads(payload, 0, &error);

    if (!root) {
        fprintf(stderr, "Error parsing JSON: %s\n", error.text);
        return -1;
    }

    json_t *led_state_json = json_object_get(root, "led_state");
    if (!led_state_json) {
        fprintf(stderr, "Key 'led_state' not found in JSON\n");
        json_decref(root);
        return -1;
    }

    if (!json_is_boolean(led_state_json)) {
        fprintf(stderr, "Value of 'led_state' is not a boolean\n");
        json_decref(root);
        return -1;
    }

    *led_state = json_boolean_value(led_state_json);
    json_decref(root);
    return 0;
}

