// Define GPIO pins
#define SOUND_SENSOR_PIN 17
#define ALARM_LED_PIN 18

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up and exiting...\n", signal);
    program_running = 0;
}

// Function to read the sound sensor
int read_sound_sensor() {
    int value = gpioRead(SOUND_SENSOR_PIN);
    if (value < 0) {
        fprintf(stderr, "Error reading sound sensor: %d\n", value);
        return -1; // Indicate an error
    }
    return value;
}

// Function to trigger the alarm
void trigger_alarm() {
    gpioWrite(ALARM_LED_PIN, 1); // Turn LED on
    gpioDelay(1000);             // Wait for 1 second
    gpioWrite(ALARM_LED_PIN, 0); // Turn LED off
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    if (gpioSetMode(SOUND_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", SOUND_SENSOR_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(ALARM_LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", ALARM_LED_PIN);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Sound sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        int sound_level = read_sound_sensor();
        if (sound_level == 0) {
            trigger_alarm();
        } else if (sound_level < 0) {
            // Error already printed in read_sound_sensor
            program_running = 0; // Exit on error
        }
        gpioDelay(100); // Delay for 100ms
    }

    // Cleanup GPIO lines
    gpioWrite(ALARM_LED_PIN, 0); // Ensure LED is off
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

