#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/gpio.h>
#include <linux/gpio_event.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_LINE 17
#define LOG_FILE "/var/log/vibration_shutdown.log"

// Global flag to signal program termination
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to get current timestamp
char* get_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    static char timestamp[20]; //YYYY-MM-DD HH:MM:SS\0

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    return timestamp;
}

// Function to log message to file
int log_message(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1;
    }

    fprintf(fp, "%s: %s\n", get_timestamp(), message);
    if (ferror(fp)) {
        perror("Error writing to log file");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

// Function to execute shutdown command
int execute_shutdown() {
    int status = system("sudo shutdown -h now");
    if (status == -1) {
        perror("Error executing shutdown command");
        return -1;
    }
    return 0;
}

int main() {
    int gpio_fd, event_fd;
    struct gpio_line_request line_req;
    struct gpio_event event;
    char buffer[sizeof(struct gpio_event)];

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open GPIO chip
    gpio_fd = open(GPIO_CHIP, O_RDWR);
    if (gpio_fd < 0) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Request GPIO line
    memset(&line_req, 0, sizeof(line_req));
    line_req.lineoffset = GPIO_LINE;
    line_req.consumer = "vibration-monitor";
    line_req.request_type = GPIO_LINE_REQUEST_DIRECTION_INPUT;

    if (ioctl(gpio_fd, GPIO_GET_LINEINFO_IOCTL, &line_req.lineinfo) < 0) {
        perror("Error getting line info");
        close(gpio_fd);
        return 1;
    }

    if (ioctl(gpio_fd, GPIO_GET_LINEHANDLE_IOCTL, &line_req) < 0) {
        perror("Error requesting GPIO line");
        close(gpio_fd);
        return 1;
    }

    // Open event file descriptor
    char event_path[64];
    snprintf(event_path, sizeof(event_path), "/dev/gpiochip0/event%d", GPIO_LINE);
    event_fd = open(event_path, O_RDONLY);
    if (event_fd < 0) {
        perror("Error opening GPIO event file");
        close(gpio_fd);
        close(line_req.fd);
        return 1;
    }

    // Configure falling edge detection
    if (ioctl(line_req.fd, GPIO_GET_LINEEVENT_IOCTL, &line_req.eventinfo) < 0) {
        perror("Error getting line event info");
        close(gpio_fd);
        close(line_req.fd);
        close(event_fd);
        return 1;
    }

    // Main loop
    while (program_running) {
        // Read event
        ssize_t bytes_read = read(event_fd, buffer, sizeof(buffer));
        if (bytes_read < 0) {
            if (errno == EINTR) {
                // Interrupted by signal, exit loop
                break;
            }
            perror("Error reading GPIO event");
            break;
        } else if (bytes_read == 0) {
            // No event available, continue
            continue;
        }

        // Process event
        memcpy(&event, buffer, sizeof(event));
        if (event.event_type == GPIO_EVENT_FALLING_EDGE) {
            // Log message
            char message[128];
            snprintf(message, sizeof(message), "Vibration detected at %s", get_timestamp());
            if (log_message(message) != 0) {
                fprintf(stderr, "Error logging message.\n");
            }

            // Print message to stdout
            printf("%s\n", message);

            // Execute shutdown
            if (execute_shutdown() != 0) {
                fprintf(stderr, "Error executing shutdown.\n");
            }

            // Exit loop after shutdown
            break;
        }
    }

    // Cleanup
    close(gpio_fd);
    close(line_req.fd);
    close(event_fd);

    return 0;
}

