#define SAMPLE_INTERVAL 5 // seconds

// Global variables
int spi_handle;
float temperature_buffer[BUFFER_SIZE];
int buffer_index = 0;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize();
int read_mcp3008(int channel);
float convert_to_celsius(int adc_value);
void store_temperature(float temperature);
void print_temperature(float temperature);
void log_temperatures();
void signal_handler(int signal);
void cleanup();

// Function to initialize the pigpio library and SPI interface
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // CE0, 1MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Function to read from the MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel\n");
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message (MCP3008 datasheet)
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) != 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to convert ADC value to Celsius
float convert_to_celsius(int adc_value) {
    return (adc_value * 3.3 / 1024) * 100;
}

// Function to store temperature in the circular buffer
void store_temperature(float temperature) {
    temperature_buffer[buffer_index] = temperature;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Function to print the temperature
void print_temperature(float temperature) {
    printf("Temperature: %.2f °C\n", temperature);
}

// Function to log temperatures to a file
void log_temperatures() {
    if (log_file == NULL) {
        log_file = fopen("temp_log.dat", "wb+");
        if (log_file == NULL) {
            fprintf(stderr, "Failed to open log file\n");
            return;
        }
    }

    // Write the entire buffer to the file
    if (fwrite(temperature_buffer, sizeof(float), BUFFER_SIZE, log_file) != BUFFER_SIZE) {
        fprintf(stderr, "Failed to write to log file\n");
    }
    fflush(log_file); // Ensure data is written to disk
}

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function to close SPI and terminate pigpio
void cleanup() {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize
    if (initialize()) {
        return 1;
    }

    // Main loop
    while (!terminate) {
        int adc_value = read_mcp3008(0);
        if (adc_value >= 0) {
            float temperature = convert_to_celsius(adc_value);
            store_temperature(temperature);
            print_temperature(temperature);
            log_temperatures();
        } else {
            fprintf(stderr, "Failed to read ADC value\n");
        }

        sleep(SAMPLE_INTERVAL);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

