// Constants
#define BH1750_ADDR 0x23
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz
#define LOG_FILE "environmental_log.txt"
#define SAMPLE_INTERVAL_SEC 1

// Global variables
static volatile int keep_running = 1;
static int i2c_fd = -1;
static int spi_fd = -1;
static FILE *log_file = NULL;

// Function prototypes
int init_i2c(int address);
int init_spi(int spi_device);
int read_bh1750(int fd);
int read_mcp3008(int spi_fd, int channel);
float convert_adc_to_db(int adc_value);
char* get_timestamp();
int log_data(const char *timestamp, int light_level, float sound_level);
void signal_handler(int sig);

// I2C initialization function
int init_i2c(int address) {
    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, address) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// SPI initialization function
int init_spi(int spi_device) {
    int fd = open(spi_device, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Set SPI mode
    int mode = SPI_MODE;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    // Set bits per word
    int bits = SPI_BITS_PER_WORD;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Error setting SPI bits per word");
        close(fd);
        return -1;
    }

    // Set SPI speed
    int speed = SPI_SPEED;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Error setting SPI speed");
        close(fd);
        return -1;
    }

    return fd;
}

// BH1750 reading function
int read_bh1750(int fd) {
    unsigned char config[1] = {0x10}; // Continuous high-resolution mode
    if (write(fd, config, 1) != 1) {
        perror("Error writing to BH1750");
        return -1;
    }

    usleep(180000); // Wait for measurement (at least 180ms)

    unsigned char data[2];
    if (read(fd, data, 2) != 2) {
        perror("Error reading from BH1750");
        return -1;
    }

    unsigned int raw_value = (data[0] << 8) | data[1];
    return raw_value;
}

// MCP3008 reading function
int read_mcp3008(int spi_fd, int channel) {
    unsigned char tx_buf[3];
    unsigned char rx_buf[3];

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel selection
    tx_buf[2] = 0x00; // Don't care

    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &transfer) < 0) {
        perror("Error sending SPI message");
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buf[1] & 0x03) << 8) | rx_buf[2];
    return adc_value;
}

// ADC to dB conversion function
float convert_adc_to_db(int adc_value) {
    // Simple linear conversion (adjust as needed)
    float db_value = (float)adc_value / 1023.0 * 100.0; // Assuming 0-100 dB range
    return db_value;
}

// Timestamp generation function
char* get_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    static char buffer[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", timeinfo);
    return buffer;
}

// Data logging function
int log_data(const char *timestamp, int light_level, float sound_level) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s, Light: %d, Sound: %.2f\n", timestamp, light_level, sound_level);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler function
void signal_handler(int sig) {
    printf("Caught signal %d, exiting gracefully...\n", sig);
    keep_running = 0;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_fd = init_i2c(BH1750_ADDR);
    if (i2c_fd < 0) {
        fprintf(stderr, "I2C initialization failed. Exiting.\n");
        return 1;
    }

    // Initialize SPI
    spi_fd = init_spi(SPI_DEVICE);
    if (spi_fd < 0) {
        fprintf(stderr, "SPI initialization failed. Exiting.\n");
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(i2c_fd);
        close(spi_fd);
        return 1;
    }

    printf("Environmental monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (keep_running) {
        // Read sensor data
        int light_level = read_bh1750(i2c_fd);
        int adc_value = read_mcp3008(spi_fd, 0);
        float sound_level = convert_adc_to_db(adc_value);

        // Get timestamp
        char *timestamp = get_timestamp();

        // Log data
        if (light_level >= 0 && adc_value >= 0) {
            if (log_data(timestamp, light_level, sound_level) != 0) {
                fprintf(stderr, "Error logging data.\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data. Skipping logging.\n");
        }

        // Wait for the next sample
        sleep(SAMPLE_INTERVAL_SEC);
    }

    // Cleanup
    printf("Cleaning up...\n");
    if (i2c_fd != -1) close(i2c_fd);
    if (spi_fd != -1) close(spi_fd);
    if (log_file != NULL) fclose(log_file);

    printf("Exiting.\n");
    return 0;
}

