#define SPI_DEVICE "/dev/spidev0.0"
#define I2C_DEVICE "/dev/i2c-1"
#define MCP4725_ADDR 0x60
#define LOG_FILE "temperature_log.txt"
#define SAMPLE_INTERVAL_SEC 0.5
#define SPI_SPEED 500000 // 500 kHz
#define MAX_RETRIES 3

// Global variables
static int spi_fd = -1;
static int i2c_fd = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_init(const char *device, uint32_t speed);
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, size_t len);
int spi_read_adc(int fd, int channel);
