// Function prototypes
int initialize_gpio();
void activate_relay(int pin);
void deactivate_relay(int pin);
void cleanup_gpio();
void signal_handler(int signal);

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

int main() {
    // Register the signal handler for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the pigpio library and GPIO pins
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Failed to initialize GPIO. Exiting.\n");
        return 1;
    }

    // Main loop to sequentially activate and deactivate the relays
    while (program_running) {
        activate_relay(RELAY1_PIN);
        sleep(1);
        deactivate_relay(RELAY1_PIN);
        sleep(1);

        activate_relay(RELAY2_PIN);
        sleep(1);
        deactivate_relay(RELAY2_PIN);
        sleep(1);

        activate_relay(RELAY3_PIN);
        sleep(1);
        deactivate_relay(RELAY3_PIN);
        sleep(1);

        activate_relay(RELAY4_PIN);
        sleep(1);
        deactivate_relay(RELAY4_PIN);
        sleep(1);
    }

    // Cleanup GPIO before exiting
    cleanup_gpio();

    return 0;
}

// Function to initialize the pigpio library and set GPIO pins as outputs
