#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define RAIN_THRESHOLD 5
#define MOTOR_FORWARD 1
#define MOTOR_REVERSE 0
#define MOTOR_STOP 2
#define PWM_DUTY 150
#define PWM_RANGE 255

// GPIO Pins
#define MOTOR_IN1 17
#define MOTOR_IN2 18
#define MOTOR_ENA 27

// Global Variables
static volatile int running = 1;
static int spi_handle;
static FILE *log_file;

// Function Prototypes
int read_rain_sensor(int spi_handle);
int log_rain_data(FILE *log_file, int rain_level);
int control_motor(int motor_direction, int spi_handle);
void signal_handler(int signal);

// Function to read the rain sensor value from MCP3008
int read_rain_sensor(int spi_handle) {
    char tx_buf[3];
    char rx_buf[3];

    // MCP3008 configuration: single-ended channel 0
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = 0x80; // Single-ended, channel 0
    tx_buf[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, tx_buf, rx_buf, 3) != 0) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1; // Indicate error
    }

    // Extract the 10-bit ADC value from the response
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// Function to log the rain data to a file
int log_rain_data(FILE *log_file, int rain_level) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(log_file, "%s, Rain Level: %d\n", timestamp, rain_level) < 0) {
        fprintf(stderr, "Error: Failed to write to log file\n");
        return -1; // Indicate error
    }

    fflush(log_file); // Flush the buffer to ensure data is written to the file
    return 0;
}

// Function to control the DC motor
int control_motor(int motor_direction, int spi_handle) {
    switch (motor_direction) {
        case MOTOR_FORWARD:
            gpioWrite(MOTOR_IN1, 1);
            gpioWrite(MOTOR_IN2, 0);
            gpioPWM(MOTOR_ENA, PWM_DUTY);
            break;
        case MOTOR_REVERSE:
            gpioWrite(MOTOR_IN1, 0);
            gpioWrite(MOTOR_IN2, 1);
            gpioPWM(MOTOR_ENA, PWM_DUTY);
            break;
        case MOTOR_STOP:
            gpioWrite(MOTOR_IN1, 0);
            gpioWrite(MOTOR_IN2, 0);
            gpioPWM(MOTOR_ENA, 0);
            break;
        default:
            fprintf(stderr, "Error: Invalid motor direction\n");
            return -1; // Indicate error
    }
    return 0;
}

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    printf("Caught signal %d, stopping...\n", signal);
    running = 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("rain_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO pins as output
    gpioSetMode(MOTOR_IN1, PI_OUTPUT);
    gpioSetMode(MOTOR_IN2, PI_OUTPUT);
    gpioSetMode(MOTOR_ENA, PI_OUTPUT);

    // Set PWM range
    gpioSetPWMrange(MOTOR_ENA, PWM_RANGE);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Rain sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        // Read rain sensor value
        int rain_level = read_rain_sensor(spi_handle);
        if (rain_level < 0) {
            fprintf(stderr, "Error: Failed to read rain sensor\n");
            break; // Exit loop on error
        }

        // Log rain data
        if (log_rain_data(log_file, rain_level) != 0) {
            fprintf(stderr, "Error: Failed to log rain data\n");
            break; // Exit loop on error
        }

        // Control motor based on rain level
        if (rain_level > RAIN_THRESHOLD) {
            printf("Rain detected! Closing window.\n");
            if (control_motor(MOTOR_FORWARD, spi_handle) != 0) {
                fprintf(stderr, "Error: Failed to control motor forward\n");
                break;
            }
            sleep(3);
            if (control_motor(MOTOR_STOP, spi_handle) != 0) {
                fprintf(stderr, "Error: Failed to stop motor\n");
                break;
            }
        } else {
            printf("No rain detected. Opening window.\n");
            if (control_motor(MOTOR_REVERSE, spi_handle) != 0) {
                fprintf(stderr, "Error: Failed to control motor reverse\n");
                break;
            }
            sleep(3);
            if (control_motor(MOTOR_STOP, spi_handle) != 0) {
                fprintf(stderr, "Error: Failed to stop motor\n");
                break;
            }
        }

        sleep(1); // Poll every second
    }

    // Cleanup
    printf("Cleaning up...\n");
    control_motor(MOTOR_STOP, spi_handle);
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

