#define LED_PIN 16

// Define constants
#define NUM_SAMPLES 100
#define CLAP_THRESHOLD 500
#define DEBOUNCE_INTERVAL_MS 50
#define LED_ON_TIME_MS 500

// Global variables
volatile sig_atomic_t program_running = 1;
int last_clap_time = 0;

// Function prototypes
int initialize_gpio();
int read_adc();
int detect_clap(int adc_value);
void control_led(int on);
void print_timestamped_message(const char *message);
void signal_handler(int signal);

// Structure to hold GPIO configuration
typedef struct {
    int clk_pin;
    int data_pin;
    int led_pin;
} gpio_config_t;

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(ADC_CLK_PIN, PI_OUTPUT);
    gpioSetMode(ADC_DATA_PIN, PI_INPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);

    return 0;
}

// Function to read ADC value using bit-banging
int read_adc() {
    int adc_value = 0;

    for (int i = 0; i < NUM_SAMPLES; i++) {
        gpioWrite(ADC_CLK_PIN, 1);
        gpioDelay(1); // Small delay for clock high time
        adc_value <<= 1; // Shift previous bits to the left
        adc_value |= gpioRead(ADC_DATA_PIN); // Read data bit
        gpioWrite(ADC_CLK_PIN, 0);
        gpioDelay(1); // Small delay for clock low time
    }

    return adc_value;
}

// Function to detect a clap event
int detect_clap(int adc_value) {
    return (adc_value > CLAP_THRESHOLD);
}

// Function to control the LED
void control_led(int on) {
    gpioWrite(LED_PIN, on);
}

// Function to print a timestamped message
void print_timestamped_message(const char *message) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    printf("[%s] %s\n", timestamp, message);
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    program_running = 0;
    print_timestamped_message("Ctrl+C pressed. Exiting...");
    control_led(0); // Turn off LED
    gpioTerminate(); // Release GPIO resources
    exit(0);
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    print_timestamped_message("Program started. Press Ctrl+C to exit.");

    while (program_running) {
        int adc_value = read_adc();
        int clap_detected = detect_clap(adc_value);

        if (clap_detected) {
            int current_time = gpioTick();

            // Debounce logic
            if (current_time - last_clap_time > DEBOUNCE_INTERVAL_MS * 1000) {
                print_timestamped_message("Clap detected!");
                control_led(1); // Turn on LED
                gpioDelay(LED_ON_TIME_MS); // Keep LED on for 500ms
                control_led(0); // Turn off LED
                last_clap_time = current_time;
            }
        }

        gpioDelay(10); // Small delay to avoid busy-waiting
    }

    return 0;
}

