#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>

#define GPIO_PIN 17
#define GPIO_PATH "/sys/class/gpio/gpio17"
#define GPIO_EXPORT_PATH "/sys/class/gpio/export"
#define GPIO_UNEXPORT_PATH "/sys/class/gpio/unexport"
#define GPIO_DIRECTION_PATH GPIO_PATH "/direction"
#define GPIO_VALUE_PATH GPIO_PATH "/value"
#define LOG_FILE "distance_log.txt"

volatile sig_atomic_t program_running = 1;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully.\n", signal);
}

// Function to export the GPIO pin
int export_gpio(int pin) {
    int fd;
    char buf[3];

    fd = open(GPIO_EXPORT_PATH, O_WRONLY);
    if (fd < 0) {
        perror("Failed to open GPIO export file");
        return -1;
    }

    int len = snprintf(buf, sizeof(buf), "%d", pin);
    if (write(fd, buf, len) != len) {
        perror("Failed to write to GPIO export file");
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

// Function to unexport the GPIO pin
int unexport_gpio(int pin) {
    int fd;
    char buf[3];

    fd = open(GPIO_UNEXPORT_PATH, O_WRONLY);
    if (fd < 0) {
        perror("Failed to open GPIO unexport file");
        return -1;
    }

    int len = snprintf(buf, sizeof(buf), "%d", pin);
    if (write(fd, buf, len) != len) {
        perror("Failed to write to GPIO unexport file");
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

// Function to set the GPIO direction (in or out)
int set_gpio_direction(int pin, const char *direction) {
    int fd;
    char path[64];

    snprintf(path, sizeof(path), GPIO_DIRECTION_PATH);
    fd = open(path, O_WRONLY);
    if (fd < 0) {
        perror("Failed to open GPIO direction file");
        return -1;
    }

    if (write(fd, direction, strlen(direction)) != strlen(direction)) {
        perror("Failed to write to GPIO direction file");
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

// Function to read the GPIO value
int read_gpio_value(int pin) {
    int fd;
    char path[64];
    char value_str[3];

    snprintf(path, sizeof(path), GPIO_VALUE_PATH);
    fd = open(path, O_RDONLY);
    if (fd < 0) {
        perror("Failed to open GPIO value file");
        return -1;
    }

    if (read(fd, value_str, 3) < 0) {
        perror("Failed to read GPIO value file");
        close(fd);
        return -1;
    }

    close(fd);
    return atoi(value_str);
}

// Function to log the distance to a file
int log_distance(const char *timestamp, int distance) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Failed to open log file");
        return -1;
    }

    fprintf(fp, "%s, %d\n", timestamp, distance);
    fclose(fp);
    return 0;
}

// Function to get the current timestamp
int get_timestamp(char *timestamp) {
    time_t rawtime;
    struct tm *timeinfo;

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    if (strftime(timestamp, 20, "%Y-%m-%d %H:%M:%S", timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }
    return 0;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Export GPIO pin
    if (export_gpio(GPIO_PIN) != 0) {
        fprintf(stderr, "Failed to export GPIO %d. Exiting.\n", GPIO_PIN);
        return 1;
    }

    // Set GPIO direction to input
    if (set_gpio_direction(GPIO_PIN, "in") != 0) {
        fprintf(stderr, "Failed to set GPIO %d direction to input. Exiting.\n", GPIO_PIN);
        unexport_gpio(GPIO_PIN);
        return 1;
    }

    printf("Distance sensor monitoring started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int distance = read_gpio_value(GPIO_PIN);
        if (distance < 0) {
            fprintf(stderr, "Failed to read GPIO value. Retrying in 1 second.\n");
            sleep(1);
            continue;
        }

        char timestamp[20];
        if (get_timestamp(timestamp) != 0) {
            fprintf(stderr, "Failed to get timestamp. Using default timestamp.\n");
            strcpy(timestamp, "YYYY-MM-DD HH:MM:SS");
        }

        if (log_distance(timestamp, distance) != 0) {
            fprintf(stderr, "Failed to log distance. \n");
        }

        if (distance == 0) {
            printf("Feeder Activated\n");
        } else {
            printf("Feeder Idle\n");
        }

        sleep(1);
    }

    // Unexport GPIO pin before exiting
    if (unexport_gpio(GPIO_PIN) != 0) {
        fprintf(stderr, "Failed to unexport GPIO %d.\n", GPIO_PIN);
    }

    printf("Distance sensor monitoring stopped.\n");

    return 0;
}

