#include <pigpio.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0
#define MCP3008_CHANNEL 0
#define VREF 3.3
#define SENSITIVITY 0.002 // 2 mV/Gauss
#define ZERO_FIELD_OUTPUT 1.65 // V
#define LOG_FILE "magnetic_log.txt"

// Global variables
int spi_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure to hold SPI configuration
typedef struct {
    int fd;
    uint8_t mode;
    uint32_t speed;
} spi_config_t;

// Function prototypes
int spi_init(spi_config_t *config);
int read_mcp3008(int channel);
float adc_to_voltage(int adc_value, float vref);
float voltage_to_magnetic_field(float voltage, float sensitivity, float zero_field_output);
int log_data(time_t timestamp, float magnetic_field);
void signal_handler(int signal);
void cleanup();

// SPI initialization function
int spi_init(spi_config_t *config) {
    int ret = 0;
    uint8_t mode = config->mode;
    uint32_t speed = config->speed;

    config->fd = open(SPI_DEVICE, O_RDWR);
    if (config->fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    ret = ioctl(config->fd, SPI_IOC_WR_MODE, &mode);
    if (ret == -1) {
        perror("Error setting SPI mode");
        close(config->fd);
        return -1;
    }

    ret = ioctl(config->fd, SPI_IOC_RD_MODE, &mode);
    if (ret == -1) {
        perror("Error getting SPI mode");
        close(config->fd);
        return -1;
    }

    ret = ioctl(config->fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed);
    if (ret == -1) {
        perror("Error setting SPI speed");
        close(config->fd);
        return -1;
    }

    ret = ioctl(config->fd, SPI_IOC_RD_MAX_SPEED_HZ, &speed);
    if (ret == -1) {
        perror("Error getting SPI speed");
        close(config->fd);
        return -1;
    }

    return 0;
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];
    struct spi_ioc_transfer transfer[1];

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel << 4)) << 4; // Single-ended mode, channel selection
    tx_buf[2] = 0x00; // Don't care

    memset(transfer, 0, sizeof(transfer));

    transfer[0].tx_buf = (unsigned long)tx_buf;
    transfer[0].rx_buf = (unsigned long)rx_buf;
    transfer[0].len = 3;
    transfer[0].speed_hz = SPI_SPEED;
    transfer[0].bits_per_word = 8;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), transfer) < 0) {
        perror("SPI transfer failed");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

