    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    if (spi_fd != -1) {
        close(spi_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    spi_config_t spi_config = {
        .fd = -1,
        .mode = SPI_MODE,
        .speed = SPI_SPEED
    };

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize SPI
    if (spi_init(&spi_config) != 0) {
        fprintf(stderr, "SPI initialization failed\n");
        cleanup();
        return 1;
    }
    spi_fd = spi_config.fd; // Assign the file descriptor

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Magnetic field monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value\n");
            sleep(0.5); // Wait before retrying
            continue;
        }

        // Convert ADC value to voltage
        float voltage = adc_to_voltage(adc_value, VREF);

        // Convert voltage to magnetic field strength
        float magnetic_field = voltage_to_magnetic_field(voltage, SENSITIVITY, ZERO_FIELD_OUTPUT);

        // Get current timestamp
        time_t current_time = time(NULL);

        // Log data
        if (log_data(current_time, magnetic_field) != 0) {
            fprintf(stderr, "Failed to log data\n");
        }

        // Print magnetic field strength
        printf("Magnetic Field: %.2f Gauss\n", magnetic_field);

        // Wait for 500 ms
        gpioDelay(500); // Using pigpio's delay function
    }

    // Cleanup and exit
    cleanup();
    printf("Program terminated.\n");
    return 0;
}

