        // Wait 100 ms
        gpioDelay(100000); // 100 ms
    }

    // Cleanup
    printf("Cleaning up...\n");
    fclose(log_file);
    spiClose(spi_handle);
    gpioWrite(LED_GPIO, 0); // Turn LED off
    gpioTerminate();

