#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <errno.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define GPIO_PIN 17
#define LOG_FILE "current_log.txt"
#define VREF 5.0  // Reference voltage for ADC
#define SENSITIVITY 0.1 // 100mV/A = 0.1V/A
#define MAX_RETRIES 3

// Global variables (to be minimized, but needed for signal handlers)
static int spi_fd = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int gpio_export(int pin);
int gpio_unexport(int pin);
int gpio_set_direction(int pin, const char *direction);
int gpio_write(int pin, int value);
int read_mcp3008(int channel);
float adc_to_current(int adc_value);
int log_current(float current);
void signal_handler(int signal);
int spi_transfer(int fd, unsigned char *tx_buf, unsigned char *rx_buf, int len);

// GPIO functions
int gpio_export(int pin) {
    char buffer[64];
    int fd;

    fd = open("/sys/class/gpio/export", O_WRONLY);
    if (fd < 0) {
        perror("gpio/export");
        return -1;
    }
    snprintf(buffer, sizeof(buffer), "%d", pin);
    if (write(fd, buffer, strlen(buffer)) < 0) {
        perror("gpio/export");
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

int gpio_unexport(int pin) {
    char buffer[64];
    int fd;

    fd = open("/sys/class/gpio/unexport", O_WRONLY);
    if (fd < 0) {
        perror("gpio/unexport");
        return -1;
    }
    snprintf(buffer, sizeof(buffer), "%d", pin);
    if (write(fd, buffer, strlen(buffer)) < 0) {
        perror("gpio/unexport");
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

int gpio_set_direction(int pin, const char *direction) {
    char path[64];
    int fd;

    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/direction", pin);
    fd = open(path, O_WRONLY);
    if (fd < 0) {
        perror("gpio/direction");
        return -1;
    }
    if (write(fd, direction, strlen(direction)) < 0) {
        perror("gpio/direction");
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

int gpio_write(int pin, int value) {
    char path[64];
    int fd;

    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/value", pin);
    fd = open(path, O_WRONLY);
    if (fd < 0) {
        perror("gpio/value");
        return -1;
    }
    if (value != 0 && value != 1) {
        fprintf(stderr, "Invalid GPIO value: %d.  Must be 0 or 1.\n", value);
        close(fd);
        return -1;
    }
    char val_str[2];
    snprintf(val_str, sizeof(val_str), "%d", value);
    if (write(fd, val_str, 1) < 0) {
        perror("gpio/value");
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

// SPI functions
int spi_transfer(int fd, unsigned char *tx_buf, unsigned char *rx_buf, int len) {
    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = len,
        .speed_hz = 1000000, // 1 MHz
        .bits_per_word = 8,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &transfer) < 0) {
        perror("SPI transfer failed");
        return -1;
    }
    return 0;
}

int read_mcp3008(int channel) {
    unsigned char tx_buf[3];
    unsigned char rx_buf[3];
    int adc_value;

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel << 4)); // Single-ended mode, channel selection
    tx_buf[2] = 0x00; // Don't care

    // Retry mechanism
    int retries = 0;
    while (retries < MAX_RETRIES) {
        if (spi_transfer(spi_fd, tx_buf, rx_buf, 3) == 0) {
            // Extract ADC value
            adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
            return adc_value;
        } else {
            fprintf(stderr, "SPI transfer failed, retrying (%d/%d)\n", retries + 1, MAX_RETRIES);
            retries++;
            usleep(10000); // 10ms delay
        }
    }

    fprintf(stderr, "Failed to read MCP3008 after %d retries\n", MAX_RETRIES);
    return -1; // Indicate failure
}

// Current sensor functions
float adc_to_current(int adc_value) {
    float voltage = (float)adc_value / 1023.0 * VREF;
    return voltage / SENSITIVITY;
}

// Logging function
int log_current(float current) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s,%.3f\n", timestamp, current);
        fflush(log_file); // Ensure data is written to disk
        return 0;
    } else {
        fprintf(stderr, "Log file is not open.\n");
        return -1;
    }
}

// Signal handler
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // GPIO initialization
    if (gpio_export(GPIO_PIN) < 0) {
        fprintf(stderr, "Failed to export GPIO %d\n", GPIO_PIN);
        return 1;
    }
    if (gpio_set_direction(GPIO_PIN, "out") < 0) {
        fprintf(stderr, "Failed to set GPIO %d direction to output\n", GPIO_PIN);
        gpio_unexport(GPIO_PIN);
        return 1;
    }

    // SPI initialization
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        gpio_unexport(GPIO_PIN);
        return 1;
    }

    // Log file initialization
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(spi_fd);
        gpio_unexport(GPIO_PIN);
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Power on the sensor
        if (gpio_write(GPIO_PIN, 1) < 0) {
            fprintf(stderr, "Failed to power on sensor\n");
            break;
        }
        usleep(100000); // 100ms delay

        // Read ADC value
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value\n");
            break;
        }

        // Convert ADC value to current
        float current = adc_to_current(adc_value);

        // Log current
        if (log_current(current) < 0) {
            fprintf(stderr, "Failed to log current\n");
            break;
        }

        // Power off the sensor
        if (gpio_write(GPIO_PIN, 0) < 0) {
            fprintf(stderr, "Failed to power off sensor\n");
            break;
        }

        printf("Current: %.3f A\n", current);

        sleep(1); // Sample every second
    }

    // Cleanup
    printf("Cleaning up...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (spi_fd != -1) {
        close(spi_fd);
    }
    gpio_unexport(GPIO_PIN);

    return 0;
}

