    }

    if (fprintf(log_file, "%s", log_entry) < 0) {
        fprintf(stderr, "Error: Failed to write to log file\n");
        return -1;
    }

    fflush(log_file); // Flush to ensure data is written immediately
    return 0;
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Received SIGINT. Terminating program...\n");
        terminate = 1;
    }
}

