#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for the sensors
#define SENSOR_1_GPIO 4
#define SENSOR_2_GPIO 17

// Debounce parameters
#define DEBOUNCE_READINGS 5
#define DEBOUNCE_DELAY_MS 2

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to read a sensor with debouncing
int read_sensor(int gpio_pin) {
    int readings[DEBOUNCE_READINGS];
    int i, object_detected = 0;

    // Read the sensor multiple times with a delay
    for (i = 0; i < DEBOUNCE_READINGS; i++) {
        readings[i] = gpioRead(gpio_pin);
        gpioDelay(DEBOUNCE_DELAY_MS * 1000); // Delay in microseconds
    }

    // Determine the majority value
    for (i = 0; i < DEBOUNCE_READINGS; i++) {
        if (readings[i] == 0) { // Assuming 0 means object detected (active low)
            object_detected++;
        }
    }

    // Return 0 if object detected, 1 otherwise
    return (object_detected >= (DEBOUNCE_READINGS / 2) + 1) ? 0 : 1;
}

// Function to log the sensor state
void log_sensor_state(int sensor1_state, int sensor2_state) {
    printf("Sensor 1: %d, Sensor 2: %d\n", sensor1_state, sensor2_state);
}

// Function to check for simultaneous object detection
void check_alert(int sensor1_state, int sensor2_state) {
    if (sensor1_state == 0 && sensor2_state == 0) {
        printf("ALERT: Both sensors detect object\n");
    }
}

int main() {
    int result;

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs with pull-up resistors
    gpioSetMode(SENSOR_1_GPIO, PI_INPUT);
    gpioSetPullUpDown(SENSOR_1_GPIO, PI_PUD_UP);
    gpioSetMode(SENSOR_2_GPIO, PI_INPUT);
    gpioSetPullUpDown(SENSOR_2_GPIO, PI_PUD_UP);

    // Install signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        int sensor1_state = read_sensor(SENSOR_1_GPIO);
        int sensor2_state = read_sensor(SENSOR_2_GPIO);

        log_sensor_state(sensor1_state, sensor2_state);
        check_alert(sensor1_state, sensor2_state);

        gpioDelay(1000000); // Delay for 1 second (1000000 microseconds)
    }

    // Release GPIO resources before exiting
    gpioTerminate();

    return 0;
}

