#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/videodev2.h>
#include <errno.h>
#include <signal.h>
#include <time.h>

#define DEFAULT_DEVICE "/dev/video0"
#define IMAGE_WIDTH 640
#define IMAGE_HEIGHT 480
#define NUM_BUFFERS 1

typedef struct {
    int fd;
    void *buffer;
    size_t buffer_size;
    int image_number;
} camera_context_t;

static volatile int keep_running = 1;

void signal_handler(int sig) {
    fprintf(stderr, "Signal received, stopping...\n");
    keep_running = 0;
}

int open_device(const char *device_name) {
    int fd = open(device_name, O_RDWR | O_NONBLOCK, 0);
    if (fd < 0) {
        fprintf(stderr, "Error opening device %s: %s\n", device_name, strerror(errno));
        return -1;
    }
    return fd;
}

int init_device(int fd) {
    struct v4l2_capability cap;
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        fprintf(stderr, "Error querying capabilities: %s\n", strerror(errno));
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture\n");
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device does not support streaming\n");
        return -1;
    }

    struct v4l2_format fmt;
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = IMAGE_WIDTH;
    fmt.fmt.pix.height = IMAGE_HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_GREY;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        fprintf(stderr, "Error setting format: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int req_buffers(int fd, int num_buffers) {
    struct v4l2_requestbuffers req;
    memset(&req, 0, sizeof(req));
    req.count = num_buffers;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        fprintf(stderr, "Error requesting buffers: %s\n", strerror(errno));
        return -1;
    }

    if (req.count < num_buffers) {
        fprintf(stderr, "Insufficient buffer memory\n");
        return -1;
    }

    return 0;
}

int map_buffer(int fd, void **buffer, size_t *buffer_size) {
    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (ioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
        fprintf(stderr, "Error querying buffer: %s\n", strerror(errno));
        return -1;
    }

    *buffer_size = buf.length;
    *buffer = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
    if (*buffer == MAP_FAILED) {
        fprintf(stderr, "Error mapping buffer: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int enqueue_buffer(int fd, void *buffer, size_t buffer_size) {
    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.m.offset = (unsigned long)buffer % (unsigned long)buffer_size; // Corrected line
    buf.index = 0;

    if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        fprintf(stderr, "Error enqueueing buffer: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int dequeue_buffer(int fd, void **buffer, size_t *buffer_size) {
    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    fd_set fds;
    struct timeval tv;
    int r;

    FD_ZERO(&fds);
    FD_SET(fd, &fds);

    tv.tv_sec = 2; // Timeout of 2 seconds
    tv.tv_usec = 0;

    r = select(fd + 1, &fds, NULL, NULL, &tv);

    if (r == -1) {
        fprintf(stderr, "Error during select: %s\n", strerror(errno));
        return -1;
    }

    if (r == 0) {
        fprintf(stderr, "Timeout waiting for buffer\n");
        return -1;
    }

    if (ioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
        if (errno == EAGAIN) {
            fprintf(stderr, "EAGAIN error during dequeue\n");
            return -1;
        }
        fprintf(stderr, "Error dequeueing buffer: %s\n", strerror(errno));
        return -1;
    }

    *buffer = mmap(NULL, *buffer_size, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
    if (*buffer == MAP_FAILED) {
        fprintf(stderr, "Error mapping buffer: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int save_image(const char *filename, const void *data, size_t size) {
    FILE *fp = fopen(filename, "wb");
    if (!fp) {
        fprintf(stderr, "Error opening file %s: %s\n", filename, strerror(errno));
        return -1;
    }

    fprintf(fp, "P5\n%d %d\n255\n", IMAGE_WIDTH, IMAGE_HEIGHT);
    fwrite(data, 1, size, fp);

    fclose(fp);
    return 0;
}

int unmap_buffer(int fd, void *buffer, size_t buffer_size) {
    if (munmap(buffer, buffer_size) < 0) {
        fprintf(stderr, "Error unmapping buffer: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int close_device(int fd) {
    if (close(fd) < 0) {
        fprintf(stderr, "Error closing device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(int argc, char *argv[]) {
    const char *device_name = DEFAULT_DEVICE;
    if (argc > 1) {
        device_name = argv[1];
    }

    camera_context_t context;
    context.fd = open_device(device_name);
    if (context.fd < 0) {
        return EXIT_FAILURE;
    }

    if (init_device(context.fd) < 0) {
        close_device(context.fd);
        return EXIT_FAILURE;
    }

    if (req_buffers(context.fd, NUM_BUFFERS) < 0) {
        close_device(context.fd);
        return EXIT_FAILURE;
    }

    if (map_buffer(context.fd, &context.buffer, &context.buffer_size) < 0) {
        close_device(context.fd);
        return EXIT_FAILURE;
    }

    if (enqueue_buffer(context.fd, context.buffer, context.buffer_size) < 0) {
        unmap_buffer(context.fd, context.buffer, context.buffer_size);
        close_device(context.fd);
        return EXIT_FAILURE;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    context.image_number = 1;

    while (keep_running) {
        void *dequeued_buffer = NULL;
        size_t dequeued_buffer_size = 0;

        if (dequeue_buffer(context.fd, &dequeued_buffer, &dequeued_buffer_size) == 0) {
            char filename[50];
            snprintf(filename, sizeof(filename), "image_%04d.pgm", context.image_number);
            if (save_image(filename, dequeued_buffer, IMAGE_WIDTH * IMAGE_HEIGHT) < 0) {
                fprintf(stderr, "Error saving image %s\n", filename);
            } else {
                printf("Saved image %s\n", filename);
            }

            context.image_number++;

            if (enqueue_buffer(context.fd, context.buffer, context.buffer_size) < 0) {
                fprintf(stderr, "Error re-enqueueing buffer\n");
                break;
            }
        } else {
            // Handle EAGAIN or timeout
            //fprintf(stderr, "Dequeue failed, retrying...\n");
        }
    }

    unmap_buffer(context.fd, context.buffer, context.buffer_size);
    close_device(context.fd);

    return EXIT_SUCCESS;
}

