#include <time.h>
#include <signal.h>
#include <errno.h>

#define DEVICE_NAME "/dev/video0"
#define FRAME_LOG_FILE "frame_log.txt"
#define NUM_BUFFERS 4

// Structure to hold buffer information
struct buffer {
    void   *start;
    size_t  length;
};

// Global variables
int fd = -1; // File descriptor for the video device
struct buffer *buffers = NULL; // Array of buffer structures
unsigned int n_buffers = 0; // Number of buffers
FILE *log_file = NULL; // File pointer for the log file
volatile sig_atomic_t stop_flag = 0; // Flag to signal program termination

// Function prototypes
int open_device(const char *device_name);
int init_device(int fd);
int start_capturing(int fd);
int stop_capturing(int fd);
int close_device(int fd);
int uninit_device(int fd);
int read_frame(int fd);
void log_timestamp(FILE *log_file);
void signal_handler(int signum);

// Function to open the video device
int open_device(const char *device_name) {
    int fd = open(device_name, O_RDWR | O_NONBLOCK, 0);
    if (fd == -1) {
        perror("Error opening device");
        return -1;
    }
    return fd;
}

// Function to initialize the video device
int init_device(int fd) {
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    unsigned int i;

    // Check device capabilities
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) == -1) {
        perror("Error querying capabilities");
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Error: %s is not a video capture device\n", DEVICE_NAME);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Error: %s does not support streaming I/O\n", DEVICE_NAME);
        return -1;
    }

    // Set video format to MJPEG
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = 640; // Set desired width
    fmt.fmt.pix.height = 480; // Set desired height
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_MJPEG;
    fmt.fmt.pix.field = V4L2_FIELD_INTERLACED;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) == -1) {
        perror("Error setting format");
        return -1;
    }

    // Request buffers
    memset(&req, 0, sizeof(req));
    req.count = NUM_BUFFERS;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) == -1) {
        perror("Error requesting buffers");
        return -1;
    }

    if (req.count < 2) {
        fprintf(stderr, "Error: Insufficient buffer memory\n");
        return -1;
    }

    n_buffers = req.count;
    buffers = calloc(n_buffers, sizeof(*buffers));
    if (!buffers) {
        perror("Error allocating buffers");
        return -1;
    }

    // Map the buffers
    for (i = 0; i < n_buffers; ++i) {
        struct v4l2_buffer buf;

        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(fd, VIDIOC_QUERYBUF, &buf) == -1) {
            perror("Error querying buffer");
            return -1;
        }

        buffers[i].length = buf.length;
        buffers[i].start = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);

        if (buffers[i].start == MAP_FAILED) {
            perror("Error mapping buffer");
            return -1;
        }
    }

    return 0;
}

// Function to start capturing
int start_capturing(int fd) {
    unsigned int i;
    struct v4l2_buffer buf;

    for (i = 0; i < n_buffers; ++i) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(fd, VIDIOC_QBUF, &buf) == -1) {
            perror("Error queuing buffer");
            return -1;
        }
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMON, &type) == -1) {
        perror("Error starting stream");
        return -1;
    }

    return 0;
}

// Function to stop capturing
int stop_capturing(int fd) {
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMOFF, &type) == -1) {
        perror("Error stopping stream");
        return -1;
    }
    return 0;
}

// Function to close the video device
int close_device(int fd) {
    if (fd != -1) {
        close(fd);
    }
    return 0;
}

// Function to uninitialize the device
int uninit_device(int fd) {
    unsigned int i;

    for (i = 0; i < n_buffers; ++i) {
        if (munmap(buffers[i].start, buffers[i].length) == -1) {
            perror("Error unmapping buffer");
            return -1;
        }
    }

    free(buffers);
    buffers = NULL;
    n_buffers = 0;
    return 0;
}

// Function to read a frame from the device
int read_frame(int fd) {
    struct v4l2_buffer buf;
    fd_set fds;
    struct timeval tv;
    int r;

    FD_ZERO(&fds);
    FD_SET(fd, &fds);

    tv.tv_sec = 2; // Timeout of 2 seconds
    tv.tv_usec = 0;

    r = select(fd + 1, &fds, NULL, NULL, &tv);

    if (r == -1) {
        perror("Error during select");
        return -1;
    }

    if (r == 0) {
        fprintf(stderr, "Error: select timeout\n");
        return -1;
    }

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_DQBUF, &buf) == -1) {
        perror("Error dequeuing buffer");
        return -1;
    }

    log_timestamp(log_file);

    if (ioctl(fd, VIDIOC_QBUF, &buf) == -1) {
        perror("Error queuing buffer");
        return -1;
    }

    return 0;
}

// Function to log the timestamp to a file
void log_timestamp(FILE *log_file) {
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
        perror("Error getting time");
        return;
    }
    fprintf(log_file, "%ld.%09ld\n", ts.tv_sec, ts.tv_nsec);
    fflush(log_file); // Ensure the data is written to the file immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signum) {
    if (signum == SIGINT) {
        printf("Received SIGINT, stopping...\n");
        stop_flag = 1;
    }
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Open the device
    fd = open_device(DEVICE_NAME);
    if (fd == -1) {
        return EXIT_FAILURE;
    }

    // Initialize the device
    if (init_device(fd) == -1) {
        close_device(fd);
        return EXIT_FAILURE;
    }

    // Open the log file
    log_file = fopen(FRAME_LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        uninit_device(fd);
        close_device(fd);
        return EXIT_FAILURE;
    }

    // Start capturing
    if (start_capturing(fd) == -1) {
        fclose(log_file);
        uninit_device(fd);
        close_device(fd);
        return EXIT_FAILURE;
    }

    printf("Capturing frames... Press Ctrl+C to stop.\n");

    // Main loop to read frames
    while (!stop_flag) {
        if (read_frame(fd) == -1) {
            break; // Exit loop on error
        }
    }

    // Stop capturing and close the device
    stop_capturing(fd);
    uninit_device(fd);
    close_device(fd);

    // Close the log file
    fclose(log_file);

    printf("Stopped capturing.\n");

    return EXIT_SUCCESS;
}

