// Function to initialize the video device
int init_device(int fd, int width, int height) {
    struct v4l2_capability cap;
    struct v4l2_format fmt;

    // Check device capabilities
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) == -1) {
        log_error("Error querying capabilities");
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture\n");
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device does not support streaming\n");
        return -1;
    }

    // Set video format
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = width;
    fmt.fmt.pix.height = height;
    fmt.fmt.pix.pixelformat = YUYV_FORMAT;
    fmt.fmt.pix.field = V4L2_FIELD_INTERLACED;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) == -1) {
        log_error("Error setting format");
        return -1;
    }

    // Check if the format was accepted
    if (fmt.fmt.pix.pixelformat != YUYV_FORMAT) {
        fprintf(stderr, "Device did not accept YUYV format\n");
        return -1;
    }

    return 0;
}

// Function to start capturing
int start_capturing(int fd) {
    struct v4l2_requestbuffers req;

    memset(&req, 0, sizeof(req));
    req.count = 4; // Number of buffers
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) == -1) {
        log_error("Error requesting buffers");
        return -1;
    }

    // Map the buffers
    for (int i = 0; i < req.count; i++) {
        struct v4l2_buffer buf;
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(fd, VIDIOC_QUERYBUF, &buf) == -1) {
            log_error("Error querying buffer");
            return -1;
        }

        void *buffer = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
        if (buffer == MAP_FAILED) {
            log_error("Error mapping buffer");
            return -1;
        }

        if (ioctl(fd, VIDIOC_QBUF, &buf) == -1) {
            log_error("Error queuing buffer");
            return -1;
        }
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMON, &type) == -1) {
        log_error("Error starting stream");
        return -1;
    }

    return 0;
}

// Function to stop capturing
int stop_capturing(int fd) {
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMOFF, &type) == -1) {
        log_error("Error stopping stream");
        return -1;
    }
    return 0;
}

// Function to close the device
int close_device(int fd) {
    if (close(fd) == -1) {
        log_error("Error closing device");
        return -1;
    }
    return 0;
}

// Function to map the buffer
