#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/videodev2.h>
#include <signal.h>
#include <errno.h>

#define DEVICE_NAME "/dev/video0"
#define IMAGE_WIDTH 192
#define IMAGE_HEIGHT 144
#define NUM_BUFFERS 4

typedef struct {
    void   *start;
    size_t  length;
} buffer_t;

static int fd = -1;
static buffer_t *buffers = NULL;
static int buffer_count = 0;
static FILE *image_file = NULL;
static volatile sig_atomic_t keep_running = 1;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, cleaning up...\n");
    keep_running = 0;
}

// Function to initialize the camera device
int init_device() {
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;
    enum v4l2_buf_type type;

    // Check device capabilities
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("VIDIOC_QUERYCAP failed");
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture\n");
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device does not support streaming\n");
        return -1;
    }

    // Set pixel format
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = IMAGE_WIDTH;
    fmt.fmt.pix.height = IMAGE_HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_MJPEG;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("VIDIOC_S_FMT failed");
        return -1;
    }

    // Request buffers
    memset(&req, 0, sizeof(req));
    req.count = NUM_BUFFERS;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("VIDIOC_REQBUFS failed");
        return -1;
    }

    if (req.count < NUM_BUFFERS) {
        fprintf(stderr, "Insufficient buffer memory\n");
        return -1;
    }

    // Allocate buffers
    buffers = calloc(req.count, sizeof(buffer_t));
    if (!buffers) {
        perror("Failed to allocate buffers");
        return -1;
    }

    buffer_count = req.count;

    for (int i = 0; i < buffer_count; ++i) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
            perror("VIDIOC_QUERYBUF failed");
            return -1;
        }

        buffers[i].length = buf.length;
        buffers[i].start = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);

        if (buffers[i].start == MAP_FAILED) {
            perror("mmap failed");
            return -1;
        }
    }

    return 0;
}

// Function to start streaming
int start_streaming() {
    struct v4l2_buffer buf;
    enum v4l2_buf_type type;

    for (int i = 0; i < buffer_count; ++i) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
            perror("VIDIOC_QBUF failed");
            return -1;
        }
    }

    type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        perror("VIDIOC_STREAMON failed");
        return -1;
    }

    return 0;
}

// Function to capture a single frame
int capture_frame() {
    struct v4l2_buffer buf;

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
        perror("VIDIOC_DQBUF failed");
        return -1;
    }

    if (buf.bytesused <= 0) {
        fprintf(stderr, "Captured frame has no data (bytesused = %zu)\n", buf.bytesused);
        return -1;
    }

    return buf.index;
}

// Function to write the captured frame to a file
int write_frame_to_file(int buffer_index) {
    if (fwrite(buffers[buffer_index].start, 1, buffers[buffer_index].length, image_file) != buffers[buffer_index].length) {
        perror("fwrite failed");
        return -1;
    }
    return 0;
}

// Function to stop streaming
int stop_streaming() {
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMOFF, &type) < 0) {
        perror("VIDIOC_STREAMOFF failed");
        return -1;
    }
    return 0;
}

// Function to unmap buffers
int unmap_buffers() {
    for (int i = 0; i < buffer_count; ++i) {
        if (munmap(buffers[i].start, buffers[i].length) < 0) {
            perror("munmap failed");
            return -1;
        }
    }
    return 0;
}

// Function to free buffers
int free_buffers() {
    free(buffers);
    buffers = NULL;
    buffer_count = 0;
    return 0;
}

// Function to close the device
int close_device() {
    if (fd != -1) {
        close(fd);
        fd = -1;
    }
    return 0;
}

// Function to close the image file
int close_image_file() {
    if (image_file != NULL) {
        fclose(image_file);
        image_file = NULL;
    }
    return 0;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the device
    fd = open(DEVICE_NAME, O_RDWR);
    if (fd < 0) {
        perror("Failed to open device");
        return EXIT_FAILURE;
    }

    // Initialize the device
    if (init_device() < 0) {
        close_device();
        return EXIT_FAILURE;
    }

    // Start streaming
    if (start_streaming() < 0) {
        unmap_buffers();
        free_buffers();
        close_device();
        return EXIT_FAILURE;
    }

    // Open the image file
    image_file = fopen("image.jpg", "wb");
    if (image_file == NULL) {
        perror("Failed to open image file");
        stop_streaming();
        unmap_buffers();
        free_buffers();
        close_device();
        return EXIT_FAILURE;
    }

    // Capture a frame
    int captured_buffer_index = capture_frame();
    if (captured_buffer_index < 0) {
        stop_streaming();
        unmap_buffers();
        free_buffers();
        close_device();
        close_image_file();
        return EXIT_FAILURE;
    }

    // Write the frame to the file
    if (write_frame_to_file(captured_buffer_index) < 0) {
        stop_streaming();
        unmap_buffers();
        free_buffers();
        close_device();
        close_image_file();
        return EXIT_FAILURE;
    }

    // Stop streaming
    if (stop_streaming() < 0) {
        unmap_buffers();
        free_buffers();
        close_device();
        close_image_file();
        return EXIT_FAILURE;
    }

    // Unmap buffers
    if (unmap_buffers() < 0) {
        free_buffers();
        close_device();
        close_image_file();
        return EXIT_FAILURE;
    }

    // Free buffers
