#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define PAN_PIN 4
#define TILT_PIN 5
#define TILT_UP_PIN 6
#define TILT_DOWN_PIN 7
#define PAN_LEFT_PIN 8
#define PAN_RIGHT_PIN 9

// Define PWM parameters
#define PWM_FREQUENCY 50
#define PWM_RANGE 1000
#define PWM_DUTY_MIN 50
#define PWM_DUTY_MAX 100

// Define servo positions
#define SERVO_MID 75
#define SERVO_MIN 25
#define SERVO_MAX 125

// Global variables
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int set_servo_position(int pin, int position);
int read_button_state(int pin);
int adjust_servo_position(int pin, int current_position, int increment);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Caught SIGINT, exiting gracefully.\n");
        program_running = 0;
    }
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    // Set GPIO modes
    gpioSetMode(PAN_PIN, PI_OUTPUT);
    gpioSetMode(TILT_PIN, PI_OUTPUT);
    gpioSetMode(TILT_UP_PIN, PI_INPUT);
    gpioSetMode(TILT_DOWN_PIN, PI_INPUT);
    gpioSetMode(PAN_LEFT_PIN, PI_INPUT);
    gpioSetMode(PAN_RIGHT_PIN, PI_INPUT);

    // Set pull-up resistors for button pins
    gpioSetPullUpDown(TILT_UP_PIN, PI_PUD_UP);
    gpioSetPullUpDown(TILT_DOWN_PIN, PI_PUD_UP);
    gpioSetPullUpDown(PAN_LEFT_PIN, PI_PUD_UP);
    gpioSetPullUpDown(PAN_RIGHT_PIN, PI_PUD_UP);

    // Set PWM frequency and range
    gpioSetPWMfrequency(PAN_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(TILT_PIN, PWM_FREQUENCY);
    gpioSetPWMrange(PAN_PIN, PWM_RANGE);
    gpioSetPWMrange(TILT_PIN, PWM_RANGE);

    // Initialize servos to mid-position
    if (set_servo_position(PAN_PIN, SERVO_MID) != 0) return -1;
    if (set_servo_position(TILT_PIN, SERVO_MID) != 0) return -1;

    return 0;
}

// Set servo position
int set_servo_position(int pin, int position) {
    if (position < SERVO_MIN || position > SERVO_MAX) {
        fprintf(stderr, "Invalid servo position: %d\n", position);
        return -1;
    }

    int duty_cycle = (int)(((float)(position - 25) / 100.0) * 50.0 + 50.0);
    if (gpioPWM(pin, duty_cycle) != 0) {
        fprintf(stderr, "Failed to set PWM for pin %d\n", pin);
        return -1;
    }
    return 0;
}

// Read button state
int read_button_state(int pin) {
    return !gpioRead(pin); // Active low
}

// Adjust servo position
int adjust_servo_position(int pin, int current_position, int increment) {
    int new_position = current_position + increment;
    if (new_position < SERVO_MIN) {
        new_position = SERVO_MIN;
    } else if (new_position > SERVO_MAX) {
        new_position = SERVO_MAX;
    }
    return new_position;
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    int pan_position = SERVO_MID;
    int tilt_position = SERVO_MID;

    // Main loop
    while (program_running) {
        // Read button states
        int tilt_up_pressed = read_button_state(TILT_UP_PIN);
        int tilt_down_pressed = read_button_state(TILT_DOWN_PIN);
        int pan_left_pressed = read_button_state(PAN_LEFT_PIN);
        int pan_right_pressed = read_button_state(PAN_RIGHT_PIN);

        // Adjust servo positions
        if (tilt_up_pressed) {
            tilt_position = adjust_servo_position(TILT_PIN, tilt_position, 5);
        }
        if (tilt_down_pressed) {
            tilt_position = adjust_servo_position(TILT_PIN, tilt_position, -5);
        }
        if (pan_left_pressed) {
            pan_position = adjust_servo_position(PAN_PIN, pan_position, 5);
        }
        if (pan_right_pressed) {
            pan_position = adjust_servo_position(PAN_PIN, pan_position, -5);
        }

        // Set servo positions
        if (set_servo_position(PAN_PIN, pan_position) != 0) {
            program_running = 0; // Exit on error
        }
        if (set_servo_position(TILT_PIN, tilt_position) != 0) {
            program_running = 0; // Exit on error
        }

        // Delay
        gpioDelay(50000); // 50ms
    }

    // Clean up
    gpioTerminate();
    return 0;
}

