    memset(&frmsize, 0, sizeof(frmsize));
    frmsize.index = 0;
    frmsize.pixel_format = V4L2_PIX_FMT_YUYV; // Assuming YUYV format

    printf("\nSupported Frame Sizes:\n");
    while (ioctl(fd, VIDIOC_ENUM_FRAMESIZES, &frmsize) == 0) {
        printf("  %dx%d\n", frmsize.discrete.width, frmsize.discrete.height);
        frmsize.index++;
    }

    if (errno != EINVAL) {
        perror("Error enumerating frame sizes");
        return -1;
    }

    return 0;
}

// Function to enumerate frame intervals
int enum_frame_intervals(int fd, int width, int height) {
    struct v4l2_frmivalenum frmival;
    memset(&frmival, 0, sizeof(frmival));
    frmival.index = 0;
    frmival.pixel_format = V4L2_PIX_FMT_YUYV; // Assuming YUYV format
    frmival.width = width;
    frmival.height = height;

    printf("    Supported Frame Intervals for %dx%d:\n", width, height);
    while (ioctl(fd, VIDIOC_ENUM_FRAMEINTERVALS, &frmival) == 0) {
        if (frmival.type == V4L2_FRMIVAL_TYPE_DISCRETE) {
            printf("      %d/%d\n", frmival.discrete.numerator, frmival.discrete.denominator);
        } else if (frmival.type == V4L2_FRMIVAL_TYPE_CONTINUOUS) {
            printf("      Continuous\n");
        } else if (frmival.type == V4L2_FRMIVAL_TYPE_STEPWISE) {
            printf("      Stepwise\n");
        }
        frmival.index++;
    }

    if (errno != EINVAL) {
        perror("Error enumerating frame intervals");
        return -1;
    }

    return 0;
}

// Function to query focus control
int query_focus_control(int fd) {
    struct v4l2_queryctrl queryctrl;
    memset(&queryctrl, 0, sizeof(queryctrl));
    queryctrl.id = V4L2_CID_FOCUS_AUTO;

    if (ioctl(fd, VIDIOC_QUERYCTRL, &queryctrl) == 0) {
        printf("\nAutofocus Supported: %s\n", queryctrl.flags & V4L2_CTRL_FLAG_DISABLED ? "No" : "Yes");
    } else {
        if (errno == ENOENT) {
            printf("\nAutofocus Supported: No (Control not found)\n");
        } else {
            perror("Error querying focus control");
            return -1;
        }
    }
    return 0;
}

int main() {
    int fd;

    // Check if the device exists
    if (!file_exists(DEVICE_NAME)) {
        fprintf(stderr, "Error: Device %s does not exist\n", DEVICE_NAME);
        return 1;
    }

    // Open the device
    fd = open_device(DEVICE_NAME);
    if (fd == -1) {
        return 1;
    }

    // Query device capabilities
    if (query_capabilities(fd) == -1) {
        close(fd);
        return 1;
    }

    // Enumerate frame sizes
    if (enum_frame_sizes(fd) == -1) {
        close(fd);
        return 1;
    }

    // Enumerate frame intervals for each supported size
    struct v4l2_frmsizeenum frmsize;
    memset(&frmsize, 0, sizeof(frmsize));
    frmsize.index = 0;
    frmsize.pixel_format = V4L2_PIX_FMT_YUYV; // Assuming YUYV format

    while (ioctl(fd, VIDIOC_ENUM_FRAMESIZES, &frmsize) == 0) {
        if (enum_frame_intervals(fd, frmsize.discrete.width, frmsize.discrete.height) == -1) {
            break; // Exit loop on error
        }
        frmsize.index++;
    }

    if (errno != EINVAL) {
        perror("Error enumerating frame intervals for all sizes");
        close(fd);
        return 1;
    }

    // Query focus control
    if (query_focus_control(fd) == -1) {
        close(fd);
        return 1;
    }

    // Close the device
    close(fd);

    return 0;
}

