#define RIGHT_BUTTON_PIN 9

// Define servo pulse width limits (microseconds)
#define SERVO_MIN_PULSE_WIDTH 1000
#define SERVO_MAX_PULSE_WIDTH 2000
#define SERVO_CENTER_PULSE_WIDTH 1500

// Define PWM frequency (Hz)
#define PWM_FREQUENCY 50

// Global variables for servo pulse widths
int pan_pulse_width = SERVO_CENTER_PULSE_WIDTH;
int tilt_pulse_width = SERVO_CENTER_PULSE_WIDTH;

// Function prototypes
int initialize_gpio();
void set_servo_pulse_width(int pin, int pulse_width);
void update_servo_position();
void button_interrupt_handler(int gpio, int level, uint32_t tick, void *user_data);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    set_servo_pulse_width(PAN_SERVO_PIN, SERVO_CENTER_PULSE_WIDTH);
    set_servo_pulse_width(TILT_SERVO_PIN, SERVO_CENTER_PULSE_WIDTH);
    gpioTerminate();
    exit(0);
}

// Function to initialize GPIO
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    // Set GPIO modes
    gpioSetMode(PAN_SERVO_PIN, PI_OUTPUT);
    gpioSetMode(TILT_SERVO_PIN, PI_OUTPUT);
    gpioSetMode(UP_BUTTON_PIN, PI_INPUT);
    gpioSetMode(DOWN_BUTTON_PIN, PI_INPUT);
    gpioSetMode(LEFT_BUTTON_PIN, PI_INPUT);
    gpioSetMode(RIGHT_BUTTON_PIN, PI_INPUT);

    // Enable pull-up resistors on button pins
    gpioSetPullUpDown(UP_BUTTON_PIN, PI_PUD_UP);
    gpioSetPullUpDown(DOWN_BUTTON_PIN, PI_PUD_UP);
    gpioSetPullUpDown(LEFT_BUTTON_PIN, PI_PUD_UP);
    gpioSetPullUpDown(RIGHT_BUTTON_PIN, PI_PUD_UP);

    // Set PWM frequency
    gpioSetPWMfrequency(PAN_SERVO_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(TILT_SERVO_PIN, PWM_FREQUENCY);

    return 0; // Indicate success
}

