void button_interrupt_handler(int gpio, int level, uint32_t tick, void *user_data) {
    // This function is not used in the main loop, but can be connected to the buttons for debouncing or other purposes.
    // For example, you could use it to trigger a function that reads the button state and updates the servo position.
    // However, in this example, we are using a simple loop to check the button states.
    (void)gpio;  // unused
    (void)level; // unused
    (void)tick;  // unused
    (void)user_data; // unused
}

int main() {
    // Install signal handler for Ctrl+C
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Camera Pan-Tilt Control\n");
    printf("Pan Servo: GPIO %d\n", PAN_SERVO_PIN);
    printf("Tilt Servo: GPIO %d\n", TILT_SERVO_PIN);
    printf("UP Button: GPIO %d\n", UP_BUTTON_PIN);
    printf("DOWN Button: GPIO %d\n", DOWN_BUTTON_PIN);
    printf("LEFT Button: GPIO %d\n", LEFT_BUTTON_PIN);
    printf("RIGHT Button: GPIO %d\n", RIGHT_BUTTON_PIN);
    printf("Center Position: Pan=%d, Tilt=%d\n", SERVO_CENTER_PULSE_WIDTH, SERVO_CENTER_PULSE_WIDTH);

    // Set initial servo positions
    set_servo_pulse_width(PAN_SERVO_PIN, SERVO_CENTER_PULSE_WIDTH);
    set_servo_pulse_width(TILT_SERVO_PIN, SERVO_CENTER_PULSE_WIDTH);

    // Main loop
    while (1) {
        update_servo_position();
    }

    return 0;
}

