    fprintf(stderr, "malloc() failed\n");
    exit(EXIT_FAILURE);
  }
  s->ptr[0] = '\0';
}

size_t writefunc(void *ptr, size_t size, size_t nmemb, struct string *s)
{
  size_t new_len = s->len + size*nmemb;
  s->ptr = realloc(s->ptr, new_len+1);
  if (s->ptr == NULL) {
    fprintf(stderr, "realloc() failed\n");
    exit(EXIT_FAILURE);
  }
  memcpy(s->ptr+s->len, ptr, size*nmemb);
  s->ptr[new_len] = '\0';
  s->len = new_len;

  return size*nmemb;
}

// Function to get current timestamp in ISO 8601 format with microseconds
char* get_iso8601_timestamp() {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);

    char *timestamp = malloc(30 * sizeof(char)); // Allocate enough space
    if (timestamp == NULL) {
        perror("malloc failed");
        return NULL;
    }

    strftime(timestamp, 26, "%Y-%m-%dT%H:%M:%S", &tm_info);
    snprintf(timestamp + 26, 6, ".%06ldZ", ts.tv_nsec / 1000); // Add microseconds

    return timestamp;
}

// Function to capture a JPEG snapshot using libcamera-still
int capture_jpeg(const char *filename) {
    char command[256];
    snprintf(command, sizeof(command), "libcamera-still -o %s -q %d --nopreview", filename, JPEG_QUALITY);
    int status = system(command);
    if (status == -1) {
        perror("system() failed");
        return -1;
    }
    return status;
}

// Function to create the motion_captures directory if it doesn't exist
int create_directory(const char *dirname) {
    struct stat st = {0};
    if (stat(dirname, &st) == -1) {
        if (mkdir(dirname, 0777) == -1) {
            perror("mkdir failed");
            return -1;
        }
    }
    return 0;
}

// Function to read the PIR sensor value
int read_pir_sensor(int gpio_pin) {
    return gpioRead(gpio_pin);
}

// Function to debounce the PIR sensor
int debounce(int gpio_pin, int duration_seconds) {
    int start_time = time(NULL);
    while (time(NULL) - start_time < duration_seconds) {
        if (read_pir_sensor(gpio_pin) == 0) {
            return 0; // Motion stopped during debounce
        }
        gpioDelay(100); // Check every 100ms
    }
    return 1; // Motion still detected after debounce
}

// Function to create the JSON payload
char* create_json_payload(const char *filename, const char *timestamp, int motion_status, int gpio_pin) {
    char *json_string = malloc(512 * sizeof(char)); // Allocate enough space
    if (json_string == NULL) {
        perror("malloc failed");
        return NULL;
    }
    snprintf(json_string, 512, 
             "{\"filename\": \"%s\", \"timestamp\": \"%s\", \"motion\": %d, \"gpio_pin\": %d}",
             filename, timestamp, motion_status, gpio_pin);
    return json_string;
}

// Function to post the data to the HTTP endpoint
int post_data(const char *json_payload, const char *filename) {
    CURL *curl;
    CURLcode res;
    struct curl_slist *headers = NULL;
    struct string s;

    init_string(&s);

    curl_global_init(CURL_GLOBAL_ALL);
    curl = curl_easy_init();
    if (curl) {
        curl_easy_setopt(curl, CURLOPT_URL, HTTP_ENDPOINT);
        curl_easy_setopt(curl, CURLOPT_POST, 1L);
        curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json_payload);
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, writefunc);
        curl_easy_setopt(curl, CURLOPT_WRITEDATA, &s);

        // Set content type to application/json
        headers = curl_slist_append(headers, "Content-Type: application/json");
        curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);

        res = curl_easy_perform(curl);
        if (res != CURLE_OK) {
            fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
        } else {
            printf("HTTP POST successful. Response: %s\n", s.ptr);
        }

        curl_easy_cleanup(curl);
        curl_slist_free_all(headers);
        free(s.ptr);
    } else {
        fprintf(stderr, "curl_easy_init() failed\n");
        curl_global_cleanup();
        return -1;
    }
    curl_global_cleanup();
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

int main(int argc, char *argv[]) {
    const char *ip_address = "localhost"; // Default IP
    int port = 8080; // Default port

    // Parse command-line arguments
    if (argc > 1) {
        ip_address = argv[1];
    }
    if (argc > 2) {
        port = atoi(argv[2]);
    }

    // Construct the HTTP endpoint URL
    char endpoint_url[256];
    snprintf(endpoint_url, sizeof(endpoint_url), "http://%s:%d/upload", ip_address, port);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Configure GPIO17 as input with pull-down resistor
    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN);

    // Create the motion_captures directory
    if (create_directory(MOTION_CAPTURE_DIR) != 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize libcurl
    curl_global_init(CURL_GLOBAL_ALL);
    http_initialized = 1;

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Motion detection started. Press Ctrl+C to exit.\n");

    while (running) {
        int motion_detected = read_pir_sensor(GPIO_PIN);

        if (motion_detected == 1) {
            printf("Motion detected!\n");
            char *timestamp = get_iso8601_timestamp();
            if (timestamp == NULL) {
                fprintf(stderr, "Failed to get timestamp\n");
                continue;
            }

            char filename[256];
            snprintf(filename, sizeof(filename), "%s/motion_%s.jpg", MOTION_CAPTURE_DIR, timestamp);

            if (capture_jpeg(filename) == 0) {
                printf("JPEG captured: %s\n", filename);
                char *json_payload = create_json_payload(filename, timestamp, 1, GPIO_PIN);
                if (json_payload != NULL) {
                    printf("JSON payload: %s\n", json_payload);
                    if (post_data(json_payload, filename) != 0) {
                        fprintf(stderr, "Failed to post data\n");
                    }
                    free(json_payload);
                } else {
                    fprintf(stderr, "Failed to create JSON payload\n");
                }
            } else {
                fprintf(stderr, "Failed to capture JPEG\n");
            }
            free(timestamp);

            // Debounce the sensor
            if (!debounce(GPIO_PIN, DEBOUNCE_TIME)) {
                printf("Motion stopped during debounce.\n");
            }
        }

        gpioDelay(POLLING_INTERVAL); // Poll every 100ms
    }

    // Cleanup
    printf("Cleaning up...\n");
    gpioTerminate();

    if (http_initialized) {
        curl_global_cleanup();
    }

    printf("Exiting.\n");
    return 0;
}

