#include <sys/stat.h>
#include <sys/types.h>
#include <errno.h>
#include <syslog.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define IMAGE_DIR "/home/pi/images"
#define LOG_FILE "/home/pi/motion_capture.log"
#define DEBOUNCE_MS 50
#define CAPTURE_TIMEOUT 2000 // milliseconds

static volatile int running = 1;
static int log_fd = -1;

// Function to generate a timestamped filename
char* generate_filename() {
    time_t rawtime;
    struct tm *timeinfo;
    char *filename = (char*)malloc(30 * sizeof(char)); // Allocate memory for the filename
    if (filename == NULL) {
        perror("Failed to allocate memory for filename");
        return NULL;
    }

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(filename, 30, "%Y%m%d_%H%M%S_%3d.jpg", timeinfo);
    return filename;
}

// Function to capture an image using raspistill
int capture_image(const char* filename) {
    char command[200];
    snprintf(command, sizeof(command), "raspistill -o %s/%s --width 640 --height 480 -q 85 --timeout %d --nopreview", IMAGE_DIR, filename, CAPTURE_TIMEOUT);

    int status = system(command);
    if (status == -1) {
        syslog(LOG_ERR, "Failed to execute raspistill command: %s", strerror(errno));
        return -1;
    } else if (WIFEXITED(status) && WEXITSTATUS(status) != 0) {
        syslog(LOG_ERR, "raspistill command failed with exit status: %d", WEXITSTATUS(status));
        return -1;
    }
    return 0;
}

// Function to log an event to the log file
void log_event(const char* message) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_fd != -1) {
        dprintf(log_fd, "%s: %s\n", timestamp, message);
        fsync(log_fd); // Ensure the log is written immediately
    } else {
        syslog(LOG_ERR, "Log file not open, cannot log: %s", message);
    }
}

// Function to handle motion detection
void motion_detected() {
    char* filename = generate_filename();
    if (filename == NULL) {
        log_event("Failed to generate filename");
        return;
    }

    if (capture_image(filename) == 0) {
        char log_message[100];
        snprintf(log_message, sizeof(log_message), "Captured image: %s", filename);
        log_event(log_message);
    } else {
        char log_message[100];
        snprintf(log_message, sizeof(log_message), "Failed to capture image: %s", filename);
        log_event(log_message);
    }
    free(filename);
}

// Callback function for GPIO alerts
void gpio_callback(int gpio, int level, uint32_t tick) {
    if (level == 0) { // Falling edge detected
        motion_detected();
    }
}

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    syslog(LOG_INFO, "Received signal %d, shutting down...", signal);
    running = 0;
}

int main() {
    openlog("motion_capture", LOG_PID | LOG_CONS, LOG_USER);

    // Open the log file
    log_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_fd == -1) {
        syslog(LOG_ERR, "Failed to open log file: %s", strerror(errno));
        return 1;
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        close(log_fd);
        closelog();
        return 1;
    }

    // Set GPIO17 as input
    gpioSetMode(GPIO_PIN, PI_INPUT);

    // Set alert function for falling edge detection
    gpioSetAlertFunc(GPIO_PIN, gpio_callback);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    syslog(LOG_INFO, "Motion capture service started");

    // Main loop
    while (running) {
        sleep(1); // Reduce CPU usage
    }

    // Cleanup
    syslog(LOG_INFO, "Cleaning up...");
    gpioSetAlertFunc(GPIO_PIN, NULL); // Disable callback
    gpioTerminate(); // Terminate pigpio
    close(log_fd); // Close log file
    closelog(); // Close syslog

    return 0;
}

