    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;
    void *buffer;
    FILE *output_file;
} camera_config_t;

// Function to handle errors
void error_exit(const char *message) {
    perror(message);
    exit(EXIT_FAILURE);
}

// Function to initialize the camera
int init_camera(camera_config_t *config) {
    config->fd = open(DEVICE_NAME, O_RDWR | O_NONBLOCK, 0);
    if (config->fd < 0) {
        error_exit("Failed to open device");
    }

    if (ioctl(config->fd, VIDIOC_QUERYCAP, &config->cap) < 0) {
        error_exit("VIDIOC_QUERYCAP failed");
    }

    if (!(config->cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture\n");
        close(config->fd);
        return -1;
    }

    if (!(config->cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device does not support streaming\n");
        close(config->fd);
        return -1;
    }

    config->fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    config->fmt.fmt.pix.width = 640; // Example width
    config->fmt.fmt.pix.height = 480; // Example height
    config->fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    config->fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (ioctl(config->fd, VIDIOC_S_FMT, &config->fmt) < 0) {
        error_exit("VIDIOC_S_FMT failed");
    }

    config->req.count = 1; // Request only one buffer
    config->req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    config->req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(config->fd, VIDIOC_REQBUFS, &config->req) < 0) {
        error_exit("VIDIOC_REQBUFS failed");
    }

    config->buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    config->buf.memory = V4L2_MEMORY_MMAP;
    config->buf.index = 0;

    if (ioctl(config->fd, VIDIOC_QUERYBUF, &config->buf) < 0) {
        error_exit("VIDIOC_QUERYBUF failed");
    }

    config->buffer = mmap(NULL, config->buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, config->fd, config->buf.m.offset);
    if (config->buffer == MAP_FAILED) {
        error_exit("mmap failed");
    }

    if (ioctl(config->fd, VIDIOC_QBUF, &config->buf) < 0) {
        error_exit("VIDIOC_QBUF failed");
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(config->fd, VIDIOC_STREAMON, &type) < 0) {
        error_exit("VIDIOC_STREAMON failed");
    }

    return 0;
}

// Function to capture a frame
int capture_frame(camera_config_t *config) {
    fd_set fds;
    struct timeval tv;
    int r;

    FD_ZERO(&fds);
    FD_SET(config->fd, &fds);

    tv.tv_sec = 2; // Timeout of 2 seconds
    tv.tv_usec = 0;

    r = select(config->fd + 1, &fds, NULL, NULL, &tv);

    if (r == -1) {
        if (errno == EINTR) {
            return -1; // Interrupted by signal
        }
        error_exit("select failed");
    }

    if (r == 0) {
        fprintf(stderr, "select timeout\n");
        return -1; // Timeout
    }

    if (ioctl(config->fd, VIDIOC_DQBUF, &config->buf) < 0) {
        error_exit("VIDIOC_DQBUF failed");
    }

    return 0;
}

// Function to process the frame
void process_frame(camera_config_t *config) {
    unsigned char *src = (unsigned char *)config->buffer;
    unsigned char *dst = (unsigned char *)malloc(CROPPED_WIDTH * CROPPED_HEIGHT * 2);
    if (!dst) {
        error_exit("Failed to allocate memory for cropped frame");
    }

    // Copy YUYV macroblocks to avoid color corruption
    for (int i = 0; i < config->fmt.fmt.pix.height; i += 2) {
        for (int j = 0; j < config->fmt.fmt.pix.width; j += 2) {
            int src_index = (i * config->fmt.fmt.pix.width + j) * 2;
            int dst_index = ((i / 2) * CROPPED_WIDTH + (j / 2)) * 2;

            dst[dst_index] = src[src_index];       // Y0
            dst[dst_index + 1] = src[src_index + 1]; // U
            dst[dst_index + 2] = src[src_index + 2]; // Y1
            dst[dst_index + 3] = src[src_index + 3]; // V
        }
    }

    // Crop the frame
    unsigned char *cropped_data = (unsigned char *)malloc(CROPPED_WIDTH * CROPPED_HEIGHT * 2);
    if (!cropped_data) {
        error_exit("Failed to allocate memory for cropped data");
    }

    for (int i = 0; i < CROPPED_HEIGHT; i++) {
        for (int j = 0; j < CROPPED_WIDTH; j++) {
            int src_index = ((i + 100) * config->fmt.fmt.pix.width + (j + 50)) * 2; // Crop from 50,100 to 250,200
            int dst_index = i * CROPPED_WIDTH + j;
            cropped_data[dst_index] = dst[src_index];
            cropped_data[dst_index + 1] = dst[src_index + 1];
        }
    }

    // Write the cropped frame to a file
    config->output_file = fopen("cropped.yuv", "wb");
    if (!config->output_file) {
        error_exit("Failed to open output file");
    }

    size_t bytes_written = fwrite(cropped_data, 1, CROPPED_WIDTH * CROPPED_HEIGHT * 2, config->output_file);
    if (bytes_written != CROPPED_WIDTH * CROPPED_HEIGHT * 2) {
        fprintf(stderr, "Error writing to file: %s\n", strerror(errno));
    }

    fclose(config->output_file);
    free(cropped_data);
    free(dst);
}

// Function to stop streaming
void stop_streaming(camera_config_t *config) {
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(config->fd, VIDIOC_STREAMOFF, &type) < 0) {
        fprintf(stderr, "VIDIOC_STREAMOFF failed: %s\n", strerror(errno));
    }
}

// Function to unmap the buffer
void unmap_buffer(camera_config_t *config) {
    if (munmap(config->buffer, config->buf.length) < 0) {
        fprintf(stderr, "munmap failed: %s\n", strerror(errno));
    }
}

// Function to close the device
void close_device(camera_config_t *config) {
    close(config->fd);
}

// Signal handler
void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        printf("Received signal %d, stopping...\n", signum);
        // Assuming config is a global variable or passed to the handler
        // For this example, we'll just exit.
        exit(0);
    }
}

int main() {
    camera_config_t config;

    // Install signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (init_camera(&config) != 0) {
        return EXIT_FAILURE;
    }

    if (capture_frame(&config) == 0) {
        process_frame(&config);
    } else {
        fprintf(stderr, "Failed to capture frame\n");
    }

    stop_streaming(&config);
    unmap_buffer(&config);
    close_device(&config);

    return EXIT_SUCCESS;
}

