#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for pan and tilt servos
#define PAN_GPIO 17
#define TILT_GPIO 18

// Define PWM frequency
#define PWM_FREQUENCY 50

// Define pulse width limits for SG90 servo (microseconds)
#define MIN_PULSE_WIDTH 500
#define MAX_PULSE_WIDTH 2500

// Define angle limits (degrees)
#define MIN_ANGLE 0
#define MAX_ANGLE 180

// Global variables for pan and tilt angles
int pan_angle = 90;
int tilt_angle = 90;

// Function prototypes
int initialize_gpio();
void set_servo_angle(int gpio, int angle);
void handle_input();
void cleanup_gpio();
void signal_handler(int signal);

// Function to initialize the pigpio library and set GPIO modes
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(PAN_GPIO, PI_OUTPUT);
    gpioSetMode(TILT_GPIO, PI_OUTPUT);

    // Set PWM frequency for both servos
    gpioSetPWMfrequency(PAN_GPIO, PWM_FREQUENCY);
    gpioSetPWMfrequency(TILT_GPIO, PWM_FREQUENCY);

    return 0;
}

// Function to set the servo angle using PWM
void set_servo_angle(int gpio, int angle) {
    // Calculate pulse width based on angle
    int pulse_width = MIN_PULSE_WIDTH + (int)(((float)(angle) / MAX_ANGLE) * (MAX_PULSE_WIDTH - MIN_PULSE_WIDTH));

    // Set PWM duty cycle
    gpioPWM(gpio, pulse_width);

    // Error handling for PWM failure
    if (gpioGetPWMdutycycle(gpio) != pulse_width) {
        fprintf(stderr, "Error setting PWM for GPIO %d\n", gpio);
    }
}

// Function to handle user input and update servo angles
void handle_input() {
    int input = getchar();

    switch (input) {
        case 'a': // Pan left
            pan_angle -= 5;
            if (pan_angle < MIN_ANGLE) {
                fprintf(stderr, "Error: Pan angle out of range (minimum)\n");
                pan_angle = MIN_ANGLE;
            }
            break;
        case 'd': // Pan right
            pan_angle += 5;
            if (pan_angle > MAX_ANGLE) {
                fprintf(stderr, "Error: Pan angle out of range (maximum)\n");
                pan_angle = MAX_ANGLE;
            }
            break;
        case 'w': // Tilt up
            tilt_angle += 5;
            if (tilt_angle > MAX_ANGLE) {
                fprintf(stderr, "Error: Tilt angle out of range (maximum)\n");
                tilt_angle = MAX_ANGLE;
            }
            break;
        case 's': // Tilt down
            tilt_angle -= 5;
            if (tilt_angle < MIN_ANGLE) {
                fprintf(stderr, "Error: Tilt angle out of range (minimum)\n");
                tilt_angle = MIN_ANGLE;
            }
            break;
        case 'q': // Quit
            return;
        default:
            fprintf(stderr, "Invalid input\n");
            return;
    }

    // Set servo angles
    set_servo_angle(PAN_GPIO, pan_angle);
    set_servo_angle(TILT_GPIO, tilt_angle);

    // Delay for 100ms
    usleep(100000);
}

// Function to cleanup GPIO and terminate pigpio
void cleanup_gpio() {
    // Set servos to neutral position
    set_servo_angle(PAN_GPIO, 90);
    set_servo_angle(TILT_GPIO, 90);

    // Terminate pigpio
    gpioTerminate();
    printf("GPIO cleanup complete. Exiting.\n");
}

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    printf("Caught signal %d\n", signal);
    cleanup_gpio();
    exit(0);
}

int main() {
    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Servo control program. Press 'a', 'd', 'w', 's' to control pan and tilt, 'q' to quit.\n");

    // Main loop to handle user input
    while (1) {
        handle_input();
    }

    return 0;
}

