    if (i2c_handle < 0) {
        log_error("Failed to open I2C device");
        return -1;
    }

    // Initialization sequence (SSD1306 datasheet)
    char init_sequence[] = {
        0xAE,       // Display off
        0xD5, 0x80, // Clock divide ratio (0x80 = 100 fps)
        0xA8, 0x3F, // Multiplex ratio (63 = 64 rows)
        0xD3, 0x00, // Display offset (0 offset)
        0x40,       // Start line (0)
        0x8D, 0x14, // Charge pump setting (0x14 = enable)
        0x20, 0x00, // Memory addressing mode (0x00 = horizontal)
        0xA1,       // Segment remap (A1 = column address 127 is mapped to SEG0)
        0xC8,       // COM output scan direction (C8 = scan from COM[N-1] to COM0)
        0xDA, 0x12, // COM pins hardware configuration (12 = alternative)
        0x81, 0xCF, // Contrast control (0xCF = max contrast)
        0xD9, 0xF1, // Precharge period (F1 = 1.5 * VCC)
        0xDB, 0x40, // VCOM deselect level (40 = 0.83 * VCC)
        0xA4,       // Entire display ON (A4 = normal display)
        0xA6,       // Normal / inverse display (A6 = normal)
        0xAF        // Display on
    };

    for (int i = 0; i < sizeof(init_sequence); i++) {
        if (i2cWriteByteData(i2c_handle, init_sequence[i], 0) < 0) {
            log_error("Failed to write initialization command");
            i2cClose(i2c_handle);
            return -1;
        }
    }

    return 0;
}

// Function to clear the OLED display
int oled_clear() {
    char buffer[1025]; // 128 columns * 8 rows / 8 bits per byte + 1 for command
    buffer[0] = 0x40; // Data command

    for (int i = 1; i < 1025; i++) {
        buffer[i] = 0x00; // Clear the display buffer
    }

    if (i2cWriteI2CBlockData(i2c_handle, 0x40, buffer + 1, 1024) < 0) {
        log_error("Failed to clear display");
        return -1;
    }
    return 0;
}

// Function to draw a string on the OLED display
int oled_draw_string(int x, int y, const char *str) {
    int i, j;
    unsigned char c;
    unsigned char line[128]; // Buffer for the current line

    // Clear the line buffer
    for (i = 0; i < OLED_WIDTH; i++) {
        line[i] = 0x00;
    }

    // Iterate through the string
    for (i = 0; str[i] != '\0'; i++) {
        c = str[i];

        // Check if the character is within the font range
        if (c < 32 || c > 126) {
            continue; // Skip characters outside the font range
        }

        // Calculate the index of the character in the font data
        int index = (c - 32) * 5;

        // Copy the character data to the line buffer
        for (j = 0; j < 5; j++) {
            line[x + j] |= (font5x7[index + j] << y);
        }

        // Move to the next character position
        x += 6; // Character width + 1 pixel spacing
    }

    // Send the line buffer to the display
    char buffer[129]; // 128 columns + 1 for command
    buffer[0] = 0x40; // Data command
    memcpy(buffer + 1, line, OLED_WIDTH);

    if (i2cWriteI2CBlockData(i2c_handle, 0x40, buffer + 1, OLED_WIDTH) < 0) {
        log_error("Failed to write string data");
        return -1;
    }

    return 0;
}

