    if (i2cReadI2CBlockData(i2c_handle, 0x40, buffer + 1, 1024) < 0) {
        log_error("Failed to read display data");
        return -1;
    }

    // Write the buffer back to the display (to refresh it)
    if (i2cWriteI2CBlockData(i2c_handle, 0x40, buffer + 1, 1024) < 0) {
