        return -1; // Indicate failure
    }
    return atoi(buffer) / 1000; // Convert to degrees Celsius
}

// Function to read CPU usage
int read_cpu_usage() {
    FILE *fp;
    unsigned long long user, nice, system, idle, iowait, irq, softirq, steal, guest, guest_nice;
    unsigned long long prev_user, prev_nice, prev_system, prev_idle, prev_iowait, prev_irq, prev_softirq, prev_steal, prev_guest, prev_guest_nice;
    unsigned long long diff_user, diff_nice, diff_system, diff_idle, diff_iowait, diff_irq, diff_softirq, diff_steal, diff_guest, diff_guest_nice;
    float cpu_usage;

    fp = fopen("/proc/stat", "r");
    if (fp == NULL) {
        return -1; // Indicate failure
    }

    // Read the first line of /proc/stat
    if (fscanf(fp, "cpu  %llu %llu %llu %llu %llu %llu %llu %llu %llu %llu",
               &user, &nice, &system, &idle, &iowait, &irq, &softirq, &steal, &guest, &guest_nice) != 10) {
        fclose(fp);
        return -1; // Indicate failure
    }

    fclose(fp);

    // Read the previous values from a file (or initialize if the file doesn't exist)
    FILE *prev_fp = fopen("prev_cpu_stats.txt", "r");
    if (prev_fp == NULL) {
        // Initialize previous values to 0 if the file doesn't exist
        prev_user = 0; prev_nice = 0; prev_system = 0; prev_idle = 0; prev_iowait = 0; prev_irq = 0; prev_softirq = 0; prev_steal = 0; prev_guest = 0; prev_guest_nice = 0;
    } else {
        if (fscanf(prev_fp, "%llu %llu %llu %llu %llu %llu %llu %llu %llu %llu",
                   &prev_user, &prev_nice, &prev_system, &prev_idle, &prev_iowait, &prev_irq, &prev_softirq, &prev_steal, &prev_guest, &prev_guest_nice) != 10) {
            fclose(prev_fp);
            // Initialize previous values to 0 if reading fails
            prev_user = 0; prev_nice = 0; prev_system = 0; prev_idle = 0; prev_iowait = 0; prev_irq = 0; prev_softirq = 0; prev_steal = 0; prev_guest = 0; prev_guest_nice = 0;
        } else {
            fclose(prev_fp);
        }
    }

    // Calculate the differences
    diff_user = user - prev_user;
    diff_nice = nice - prev_nice;
    diff_system = system - prev_system;
    diff_idle = idle - prev_idle;
    diff_iowait = iowait - prev_iowait;
    diff_irq = irq - prev_irq;
    diff_softirq = softirq - prev_softirq;
    diff_steal = steal - prev_steal;
    diff_guest = guest - prev_guest;
    diff_guest_nice = guest_nice - prev_guest_nice;

    // Calculate the total time
    unsigned long long total = diff_user + diff_nice + diff_system + diff_idle + diff_iowait + diff_irq + diff_softirq + diff_steal + diff_guest + diff_guest_nice;

    // Calculate the idle time
    unsigned long long idle_time = diff_idle + diff_iowait;

    // Calculate the CPU usage
    if (total > 0) {
        cpu_usage = 100.0 * (1.0 - (float)idle_time / (float)total);
    } else {
        cpu_usage = 0.0;
    }

    // Write the current values to the file
    prev_fp = fopen("prev_cpu_stats.txt", "w");
    if (prev_fp == NULL) {
        return -1; // Indicate failure
    }
    fprintf(prev_fp, "%llu %llu %llu %llu %llu %llu %llu %llu %llu %llu",
            user, nice, system, idle, iowait, irq, softirq, steal, guest, guest_nice);
    fclose(prev_fp);

    return (int)cpu_usage;
}

// Function to read disk usage
int read_disk_usage() {
    FILE *fp;
    char buffer[1024];
    unsigned long long total, used, free;

    fp = fopen("/proc/partitions", "r");
    if (fp == NULL) {
        return -1; // Indicate failure
    }

    // Skip the first two lines
    fgets(buffer, sizeof(buffer), fp);
    fgets(buffer, sizeof(buffer), fp);

    // Read the third line
    if (fscanf(fp, "%*s %*s %*s %llu %llu %llu", &total, &used, &free) != 3) {
        fclose(fp);
        return -1; // Indicate failure
    }

    fclose(fp);

    return (int)(((float)used / (float)total) * 100.0);
}

// Function to read memory usage
int read_memory_usage() {
    FILE *fp;
    unsigned long long mem_total, mem_free, mem_available;

    fp = fopen("/proc/meminfo", "r");
    if (fp == NULL) {
        return -1; // Indicate failure
    }

    // Read the relevant lines
    char buffer[1024];
    while (fgets(buffer, sizeof(buffer), fp) != NULL) {
        if (strncmp(buffer, "MemTotal:", 9) == 0) {
            sscanf(buffer, "MemTotal: %llu kB", &mem_total);
        } else if (strncmp(buffer, "MemFree:", 8) == 0) {
            sscanf(buffer, "MemFree: %llu kB", &mem_free);
        } else if (strncmp(buffer, "MemAvailable:", 13) == 0) {
            sscanf(buffer, "MemAvailable: %llu kB", &mem_available);
        }
    }

    fclose(fp);

    return (int)(((float)(mem_total - mem_available) / (float)mem_total) * 100.0);
}

// Function to read network usage
int read_network_usage() {
    FILE *fp;
    unsigned long long rx_bytes, tx_bytes;
    static unsigned long long prev_rx_bytes = 0, prev_tx_bytes = 0;
    unsigned long long diff_rx_bytes, diff_tx_bytes;
    float rx_rate, tx_rate;

    fp = fopen("/proc/net/dev", "r");
    if (fp == NULL) {
        return -1; // Indicate failure
    }

    // Skip the first two lines
    fgets(buffer, sizeof(buffer), fp);
    fgets(buffer, sizeof(buffer), fp);

    // Read the second line (eth0)
    if (fscanf(fp, "eth0: %llu %*u %*u %*u %*u %*u %*u %*u %llu", &rx_bytes, &tx_bytes) != 2) {
        fclose(fp);
        return -1; // Indicate failure
    }

    fclose(fp);

    // Calculate the differences
    diff_rx_bytes = rx_bytes - prev_rx_bytes;
    diff_tx_bytes = tx_bytes - prev_tx_bytes;

    // Update the previous values
    prev_rx_bytes = rx_bytes;
    prev_tx_bytes = tx_bytes;

    // Calculate the rates (bytes per second)
    rx_rate = (float)diff_rx_bytes;
    tx_rate = (float)diff_tx_bytes;

    return (int)(rx_rate + tx_rate); // Return the sum of receive and transmit rates
}

