        perror("Error creating socket");
        gpioTerminate();
        return 1;
    }

    // Configure server address
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(server_port);
    if (inet_pton(AF_INET, server_ip, &server_addr.sin_addr) <= 0) {
        perror("Invalid address/ Address not supported");
        close(sockfd);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        // Calculate flow rate and total volume every 10 seconds
        double current_flow_rate = calculate_flow_rate(pulse_count);
        total_volume = calculate_total_volume(current_flow_rate, PULSES_PER_LITER);
        pulse_count = 0; // Reset pulse count

        // Log data to the console
        log_data(current_flow_rate, total_volume);

        // Send data to the server
        send_data_to_server(current_flow_rate, total_volume);

        // Update LCD display every 10 seconds
        lcd_clear();
        char lcd_buffer[20];
        snprintf(lcd_buffer, sizeof(lcd_buffer), "Flow: %.2f L/s", current_flow_rate);
        lcd_string(lcd_buffer);
        lcd_set_cursor(0, 1);
        snprintf(lcd_buffer, sizeof(lcd_buffer), "Vol: %.2f L", total_volume);
        lcd_string(lcd_buffer);

        sleep(10);
    }

    return 0;
}

