#include <wiringPiSPI.h>
#include <wiringPiI2C.h>

// Constants
#define ANEMOMETER_PIN 17
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define I2C_ADDRESS 0x27
#define LCD_WIDTH 16
#define LCD_HEIGHT 2
#define PULSES_PER_REVOLUTION 1.0 // Adjust based on anemometer
#define MAX_PULSES 10000
#define MIN_PULSES 0
#define MAX_ADC_VALUE 1023
#define MIN_ADC_VALUE 0
#define MAX_WIND_SPEED 50.0 // m/s
#define MIN_WIND_SPEED 0.0  // m/s

// Global variables
volatile int pulse_count = 0;
int spi_fd;
int i2c_fd;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
void anemometer_interrupt(void);
int read_wind_direction(void);
float calculate_wind_speed(int pulse_count);
void lcd_init(void);
void lcd_clear(void);
void lcd_set_cursor(int row, int col);
void lcd_print(const char *text);
void lcd_send_command(unsigned char command);
void lcd_send_data(unsigned char data);
void log_message(const char *message);
void signal_handler(int signal);
int initialize(void);

// LCD Backlight Control
#define LCD_BACKLIGHT 0x08
#define LCD_NOBACKLIGHT 0x00

// LCD Flags
#define LCD_EN 0b00000100  // Enable bit
#define LCD_RW 0b00000010  // Read/Write bit (not used here, always write)
#define LCD_RS 0b00000001  // Register select bit

// LCD Commands
#define LCD_CLEARDISPLAY 0x01
#define LCD_RETURNHOME 0x02
#define LCD_ENTRYMODESET 0x04
#define LCD_DISPLAYCONTROL 0x08
#define LCD_CURSORSHIFT 0x10
#define LCD_FUNCTIONSET 0x20

// LCD Entry Mode Flags
#define LCD_ENTRYRIGHT 0x00
#define LCD_ENTRYLEFT 0x02
#define LCD_ENTRYSHIFTINCREMENT 0x01
#define LCD_ENTRYSHIFTDECREMENT 0x00

// LCD Control Flags
#define LCD_DISPLAYON 0x04
#define LCD_DISPLAYOFF 0x00
#define LCD_CURSORON 0x02
#define LCD_CURSOROFF 0x00
#define LCD_BLINKON 0x01
#define LCD_BLINKOFF 0x00

// LCD Function Set Flags
#define LCD_8BITMODE 0x10
#define LCD_4BITMODE 0x00
#define LCD_2LINE 0x08
#define LCD_1LINE 0x00
#define LCD_5x10DOTS 0x04
#define LCD_5x8DOTS 0x00

// Function to send a command to the LCD
void lcd_send_command(unsigned char command) {
    unsigned char data_u, data_l;
    unsigned char data[4];
    data_u = (command & 0xF0);
    data_l = ((command << 4) & 0xF0);

    data[0] = data_u | LCD_BACKLIGHT;
    data[1] = data_u | LCD_EN | LCD_BACKLIGHT;
    data[2] = data_u | LCD_BACKLIGHT;
    data[3] = data_l | LCD_BACKLIGHT;

    for (int i = 0; i < 4; i++) {
        wiringPiSPIDataRW(SPI_CHANNEL, data, 1);
        delayMicroseconds(500); // Delay for enable pulse
    }
}

// Function to send data to the LCD
void lcd_send_data(unsigned char data) {
    unsigned char data_u, data_l;
    unsigned char data_buf[4];
    data_u = (data & 0xF0);
    data_l = ((data << 4) & 0xF0);

    data_buf[0] = data_u | LCD_RS | LCD_BACKLIGHT;
    data_buf[1] = data_u | LCD_EN | LCD_RS | LCD_BACKLIGHT;
    data_buf[2] = data_u | LCD_RS | LCD_BACKLIGHT;
    data_buf[3] = data_l | LCD_RS | LCD_BACKLIGHT;

    for (int i = 0; i < 4; i++) {
        wiringPiSPIDataRW(SPI_CHANNEL, data_buf, 1);
        delayMicroseconds(500); // Delay for enable pulse
    }
}

// Function to initialize the LCD
void lcd_init(void) {
    delay(50); // Wait for LCD to power up
    lcd_send_command(0x33); // Initialize
    lcd_send_command(0x32); // Initialize
    lcd_send_command(LCD_FUNCTIONSET | LCD_4BITMODE | LCD_2LINE | LCD_5x8DOTS);
    lcd_send_command(LCD_DISPLAYCONTROL | LCD_DISPLAYON | LCD_CURSOROFF | LCD_BLINKOFF);
    lcd_clear();
    lcd_send_command(LCD_ENTRYMODESET | LCD_ENTRYLEFT | LCD_ENTRYSHIFTDECREMENT);
}

// Function to clear the LCD
void lcd_clear(void) {
    lcd_send_command(LCD_CLEARDISPLAY);
    delayMicroseconds(2000); // This command takes a long time!
}

// Function to set the cursor position
void lcd_set_cursor(int row, int col) {
    int addr;
    if (row == 0) {
        addr = 0x00 + col;
    } else {
        addr = 0x40 + col;
    }
    lcd_send_command(0x80 + addr);
}

// Function to print text to the LCD
void lcd_print(const char *text) {
    for (int i = 0; text[i] != '\0'; i++) {
        lcd_send_data(text[i]);
    }
}

// Anemometer interrupt handler
void anemometer_interrupt(void) {
    pulse_count++;
}

// Function to read wind direction from MCP3008
int read_wind_direction(void) {
    unsigned char buffer[3];
    int adc_value;

    buffer[0] = 0x01; // Start bit
    buffer[1] = (0x08 | (SPI_CHANNEL << 1)) << 4; // Single-ended mode, channel 0
    buffer[2] = 0x00;

    if (wiringPiSPIDataRW(SPI_CHANNEL, buffer, 3) == -1) {
        log_message("SPI read failed");
        return -1; // Indicate error
    }

    adc_value = ((buffer[1] & 0x03) << 8) + buffer[2];

    if (adc_value < MIN_ADC_VALUE || adc_value > MAX_ADC_VALUE) {
        log_message("ADC value out of range");
        return -1; // Indicate error
    }

    return adc_value;
}

// Function to calculate wind speed
float calculate_wind_speed(int pulse_count) {
    float revolutions_per_second = (float)pulse_count / 0.5; // 500ms sample window
    float wind_speed = revolutions_per_second / PULSES_PER_REVOLUTION * 2.0 * M_PI * 0.5; // m/s
    return wind_speed;
}

// Function to log messages to a file
void log_message(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] %s\n",
            t->tm_year + 1900, t->tm_mon + 1, t->tm_mday, t->tm_hour, t->tm_min, t->tm_sec, message);
    fflush(log_file);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    log_message("Received signal, shutting down...");
}

// Initialization function
int initialize(void) {
    // Initialize wiringPi
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "wiringPiSetupGpio failed: %s\n", strerror(errno));
        return -1;
    }

    // Initialize anemometer interrupt
    pinMode(ANEMOMETER_PIN, INPUT);
    pullUpDnControl(ANEMOMETER_PIN, PUD_UP); // Enable pull-up resistor
    if (wiringPiISR(ANEMOMETER_PIN, INT_EDGE_RISING, &anemometer_interrupt) < 0) {
        fprintf(stderr, "Unable to setup ISR: %s\n", strerror(errno));
        return -1;
    }

    // Initialize SPI
    spi_fd = wiringPiSPISetup(SPI_CHANNEL, SPI_SPEED);
    if (spi_fd == -1) {
        fprintf(stderr, "wiringPiSPISetup failed: %s\n", strerror(errno));
        return -1;
    }

    // Initialize I2C
    i2c_fd = wiringPiI2CSetup(I2C_ADDRESS);
    if (i2c_fd == -1) {
        fprintf(stderr, "wiringPiI2CSetup failed: %s\n", strerror(errno));
        return -1;
    }

    // Initialize LCD
    lcd_init();

    // Open log file
    log_file = fopen("wind_monitor.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void) {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize
    if (initialize() == -1) {
        fprintf(stderr, "Initialization failed, exiting.\n");
        return 1;
    }

    log_message("Program started");

    while (program_running) {
        // Reset pulse count
        pulse_count = 0;

        // Wait for 500ms
        delay(500);

        // Read wind direction
        int adc_value = read_wind_direction();
        if (adc_value == -1) {
            log_message("Failed to read wind direction");
            continue; // Skip to the next iteration
        }

        // Calculate wind speed
        float wind_speed = calculate_wind_speed(pulse_count);

        // Convert ADC value to degrees (example, adjust based on your wind vane)
        float wind_direction = (float)adc_value / MAX_ADC_VALUE * 360.0;

        // Format data for LCD
        char speed_str[20];
        char direction_str[20];
        snprintf(speed_str, sizeof(speed_str), "Speed: %.2f m/s", wind_speed);
        snprintf(direction_str, sizeof(direction_str), "Dir: %.0f deg", wind_direction);

        // Display data on LCD
        lcd_clear();
        lcd_set_cursor(0, 0);
        lcd_print(speed_str);
        lcd_set_cursor(1, 0);
        lcd_print(direction_str);

        // Log data
        char log_str[50];
        snprintf(log_str, sizeof(log_str), "Speed: %.2f m/s, Direction: %.0f deg", wind_speed, wind_direction);
        log_message(log_str);
    }

    // Cleanup
    lcd_clear();
    fclose(log_file);

    log_message("Program finished");

    return 0;
}

