#define LCD_I2C_ADDR 0x27 // Adjust if needed
#define LCD_WIDTH 16
#define PULSES_PER_LITER 450.0 // YF-S201 sensor calibration
#define PULSE_TIMEOUT_SEC 5

// Global variables
volatile int pulse_count = 0;
int lcd_fd;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
void pulse_callback(int gpio, int level, uint32_t tick, void *user_data);
float calculate_flow_rate(int pulses);
