void log_message(const char *message);
void signal_handler(int signal);

// Pulse callback function
void pulse_callback(int gpio, int level, uint32_t tick, void *user_data) {
    if (level == PI_HIGH) {
        pulse_count++;
    }
}

// Calculate flow rate in L/min
float calculate_flow_rate(int pulses) {
    return (float)pulses / PULSES_PER_LITER * 60.0;
}

// LCD initialization
void lcd_init() {
    lcd_fd = wiringPiI2CSetup(LCD_I2C_ADDR);
    if (lcd_fd == -1) {
        fprintf(stderr, "Error: Failed to initialize LCD I2C.\n");
        log_message("Error: Failed to initialize LCD I2C.");
        exit(EXIT_FAILURE);
    }

    // Initialize LCD (4-bit mode)
    usleep(50000); // Wait for more than 40 ms after VCC rises to 4.5V
    wiringPiI2CWriteReg8(lcd_fd, 0x00, 0x30); // Function set: 8-bit interface
    usleep(5000);  // Wait for more than 4.1 ms
    wiringPiI2CWriteReg8(lcd_fd, 0x00, 0x30); // Function set: 8-bit interface
    usleep(100);   // Wait for more than 100 us
    wiringPiI2CWriteReg8(lcd_fd, 0x00, 0x30); // Function set: 8-bit interface
    usleep(100000); // Wait for more than 100 us
    wiringPiI2CWriteReg8(lcd_fd, 0x00, 0x20); // Function set: 4-bit interface

    wiringPiI2CWriteReg8(lcd_fd, 0x00, 0x28); // Function set: 4-bit, 2 lines, 5x8 font
    wiringPiI2CWriteReg8(lcd_fd, 0x00, 0x08); // Display off
    wiringPiI2CWriteReg8(lcd_fd, 0x00, 0x01); // Clear display
    usleep(2000);   // Wait for more than 1.53 ms
    wiringPiI2CWriteReg8(lcd_fd, 0x00, 0x06); // Entry mode set: increment cursor, no shift
    wiringPiI2CWriteReg8(lcd_fd, 0x00, 0x0C); // Display on, no cursor, no blink
}

// Clear LCD display
void lcd_clear() {
    wiringPiI2CWriteReg8(lcd_fd, 0x00, 0x01); // Clear display
    usleep(2000);   // Wait for more than 1.53 ms
}

