void lcd_set_cursor(int row, int col) {
    int addr;
    if (row == 0) {
        addr = 0x80 + col;
    } else {
        addr = 0xC0 + col;
    }
    wiringPiI2CWriteReg8(lcd_fd, 0x00, addr);
}

// Print text to LCD
void lcd_print(const char *text) {
    for (int i = 0; text[i] != '\0'; i++) {
        wiringPiI2CWriteReg8(lcd_fd, 0x01, text[i]);
    }
}

// Log message to file
void log_message(const char *message) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fflush(log_file);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
    log_message("Program terminated by signal.");
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    // Set GPIO mode for flow sensor
    gpioSetMode(FLOW_SENSOR_GPIO, PI_INPUT);
    gpioSetPullUpDown(FLOW_SENSOR_GPIO, PI_PUD_UP); // Enable pull-up resistor

    // Initialize wiringPi I2C
    if (wiringPiSetup() == -1) {
        fprintf(stderr, "Error: wiringPi initialisation failed.\n");
        gpioTerminate();
        return 1;
    }

    // Initialize LCD
    lcd_init();

    // Open log file
    log_file = fopen("flow_sensor.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file.\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up interrupt on falling edge of the pulse
    gpioSetAlertFuncEx(FLOW_SENSOR_GPIO, pulse_callback, NULL);

    time_t last_pulse_time = time(NULL);
    int consecutive_no_pulse_count = 0;

    // Main loop
    while (program_running) {
        // Reset pulse count
        pulse_count = 0;

        // Wait for 1 second
        sleep(1);

        // Calculate flow rate
        float flow_rate = calculate_flow_rate(pulse_count);

        // Display on LCD
        lcd_clear();
        lcd_set_cursor(0, 0);
        lcd_print("Flow Rate:");
        char flow_rate_str[17];
        snprintf(flow_rate_str, sizeof(flow_rate_str), "%.2f L/min", flow_rate);
        lcd_set_cursor(1, 0);
        lcd_print(flow_rate_str);

        // Log data
        time_t now = time(NULL);
        struct tm tm = *localtime(&now);
        char log_entry[100];
        snprintf(log_entry, sizeof(log_entry), "Flow Rate: %.2f L/min, Pulses: %d", flow_rate, pulse_count);
        log_message(log_entry);

        // Sensor absence detection
        if (pulse_count == 0) {
            consecutive_no_pulse_count++;
            if (consecutive_no_pulse_count >= PULSE_TIMEOUT_SEC) {
                lcd_clear();
                lcd_print("Sensor Absent!");
                log_message("Warning: Sensor may be absent.");
                consecutive_no_pulse_count = 0; // Reset counter to avoid repeated messages
            }
        } else {
            consecutive_no_pulse_count = 0; // Reset counter if pulses are detected
        }
    }

    // Cleanup
    gpioSetAlertFuncEx(FLOW_SENSOR_GPIO, NULL, NULL); // Disable callback
    gpioTerminate();
    fclose(log_file);

    return 0;
}

