        for (int col = 0; col < NUM_COLS; col++) {
            if (frame[row * NUM_COLS + col] == 0) {
                gpioWrite(cols[col], 0); // Turn off LED
            } else {
                gpioWrite(cols[col], 1); // Turn on LED
            }
        }
        gpioDelay(800); // 800 us delay
        gpioWrite(rows[row], 0); // Disable row
    }
}

// Function to generate a wave-like pattern
void generate_wave(unsigned char *frame, int direction, int offset) {
    for (int row = 0; row < NUM_ROWS; row++) {
        for (int col = 0; col < NUM_COLS; col++) {
            int index = (col + offset + NUM_COLS) % NUM_COLS; // Ensure index is within bounds
            if (direction == 1) { // Left to right
                frame[row * NUM_COLS + col] = (abs(col - index) < 3) ? 1 : 0; // Simple wave pattern
            } else { // Right to left
                frame[row * NUM_COLS + (NUM_COLS - 1 - col) + offset] = (abs(col - index) < 3) ? 1 : 0; // Simple wave pattern
            }
        }
    }
}

