    unsigned char *frame = (unsigned char *)malloc(NUM_ROWS * NUM_COLS * sizeof(unsigned char));
    if (frame == NULL) {
        fprintf(stderr, "Failed to allocate memory for frame buffer\n");
        gpioTerminate();
        return 1;
