        // Render frame
        render_frame(frame);

        // Update offset and direction
        offset = (offset + 1) % NUM_COLS; // Increment offset
        if (offset == 0) {
            direction *= -1; // Reverse direction every full cycle
        }

        // Delay
        usleep(100000); // 100 ms delay
    }

    // Cleanup
    free(frame);
    clear_matrix(); // Turn off all LEDs
    gpioTerminate();

    return 0;
}

