#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Si1145 I2C address
#define SI1145_ADDR 0x60

// Si1145 register addresses
#define SI1145_REG_PARTID 0x00
#define SI1145_REG_REVID 0x01
#define SI1145_REG_SEQID 0x02

#define SI1145_REG_UCOEF0 0x13
#define SI1145_REG_UCOEF1 0x14
#define SI1145_REG_UCOEF2 0x15
#define SI1145_REG_UCOEF3 0x16

#define SI1145_REG_PARAM_WR 0x17
#define SI1145_REG_COMMAND 0x18
#define SI1145_REG_RESPONSE0 0x20
#define SI1145_REG_RESPONSE1 0x21
#define SI1145_REG_RESPONSE2 0x22
#define SI1145_REG_RESPONSE3 0x23

#define SI1145_REG_IRQ_ENABLE 0x03
#define SI1145_REG_IRQ_MODE1 0x04
#define SI1145_REG_HW_KEY 0x07
#define SI1145_REG_MEAS_RATE0 0x08
#define SI1145_REG_MEAS_RATE1 0x09

#define SI1145_REG_ALS_VIS_DATA0 0x22
#define SI1145_REG_ALS_VIS_DATA1 0x23
#define SI1145_REG_PS1_DATA0 0x24
#define SI1145_REG_PS1_DATA1 0x25

#define SI1145_HW_KEY_VAL 0x17
#define SI1145_RESET_CMD 0x01

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_sensor();
int read_sensor_data(int *proximity, int *ambient_light);
void log_data(int proximity, int ambient_light);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
    }
    gpioTerminate();
}

// Function to initialize the Si1145 sensor
int initialize_sensor() {
    // Reset the sensor
    if (i2cWriteByteData(i2c_handle, SI1145_REG_COMMAND, SI1145_RESET_CMD) < 0) {
        fprintf(stderr, "Error: Failed to reset Si1145 sensor.\n");
        return -1;
    }
    gpioDelay(10); // Wait for reset to complete

    // Configure the sensor (example configuration)
    if (i2cWriteByteData(i2c_handle, SI1145_REG_MEAS_RATE0, 0x08) < 0) {
        fprintf(stderr, "Error: Failed to write MEAS_RATE0.\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, SI1145_REG_MEAS_RATE1, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to write MEAS_RATE1.\n");
        return -1;
    }

    if (i2cWriteByteData(i2c_handle, SI1145_REG_HW_KEY, SI1145_HW_KEY_VAL) < 0) {
        fprintf(stderr, "Error: Failed to write HW_KEY.\n");
        return -1;
    }

    if (i2cWriteByteData(i2c_handle, SI1145_REG_IRQ_ENABLE, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to write IRQ_ENABLE.\n");
        return -1;
    }

    if (i2cWriteByteData(i2c_handle, SI1145_REG_IRQ_MODE1, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to write IRQ_MODE1.\n");
        return -1;
    }

    if (i2cWriteByteData(i2c_handle, SI1145_REG_UCOEF0, 0x7B) < 0) {
        fprintf(stderr, "Error: Failed to write UCOEF0.\n");
        return -1;
    }

    if (i2cWriteByteData(i2c_handle, SI1145_REG_UCOEF1, 0x6B) < 0) {
        fprintf(stderr, "Error: Failed to write UCOEF1.\n");
        return -1;
    }

    if (i2cWriteByteData(i2c_handle, SI1145_REG_UCOEF2, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to write UCOEF2.\n");
        return -1;
    }

    if (i2cWriteByteData(i2c_handle, SI1145_REG_UCOEF3, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to write UCOEF3.\n");
        return -1;
    }

    // Start measurements
    if (i2cWriteByteData(i2c_handle, SI1145_REG_COMMAND, 0x07) < 0) {
        fprintf(stderr, "Error: Failed to start measurements.\n");
        return -1;
    }

    return 0;
}

// Function to read proximity and ambient light data from the sensor
int read_sensor_data(int *proximity, int *ambient_light) {
    int vis_low, vis_high, prox_low, prox_high;

    vis_low = i2cReadByteData(i2c_handle, SI1145_REG_ALS_VIS_DATA0);
    vis_high = i2cReadByteData(i2c_handle, SI1145_REG_ALS_VIS_DATA1);
    prox_low = i2cReadByteData(i2c_handle, SI1145_REG_PS1_DATA0);
    prox_high = i2cReadByteData(i2c_handle, SI1145_REG_PS1_DATA1);

    if (vis_low < 0 || vis_high < 0 || prox_low < 0 || prox_high < 0) {
        fprintf(stderr, "Error: Failed to read sensor data.\n");
        return -1;
    }

    *ambient_light = (vis_high << 8) | vis_low;
    *proximity = (prox_high << 8) | prox_low;

    return 0;
}

// Function to log the data to a file
void log_data(int proximity, int ambient_light) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];
    char log_entry[100];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    snprintf(log_entry, sizeof(log_entry), "%s, Proximity: %d, Ambient Light: %d\n", timestamp, proximity, ambient_light);

    if (log_file != NULL) {
        fprintf(log_file, "%s", log_entry);
        fflush(log_file);
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

int main() {
    int proximity, ambient_light;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, SI1145_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus. %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor() != 0) {
        fprintf(stderr, "Error: Sensor initialization failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open the log file
    log_file = fopen("biometric_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        if (read_sensor_data(&proximity, &ambient_light) == 0) {
            log_data(proximity, ambient_light);
        } else {
            fprintf(stderr, "Error: Failed to read sensor data. Retrying...\n");
        }
        gpioDelay(500); // Sample every 500 ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

