        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        cleanup();
        return 1;
    }

    int previous_state = 1; // Initialize to HIGH (no object detected)
    int current_state;

    printf("Proximity sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        current_state = read_sensor();

        if (detect_falling_edge(previous_state, current_state)) {
            printf("Object detected!\n");
            if (log_entry() != 0) {
                fprintf(stderr, "Error logging entry.\n");
            }
            if (blink_led() != 0) {
                fprintf(stderr, "Error blinking LED.\n");
            }
        }

        previous_state = current_state;
        gpioDelay(100); // Poll every 100ms
    }

    cleanup();
    return 0;
}

