// Si1145 I2C address
#define SI1145_ADDR 0x60

// Si1145 register addresses
#define SI1145_REG_PART_ID 0x00
#define SI1145_REG_ALS_VIS_DATA0 0x22
#define SI1145_REG_PS1_DATA0 0x24

// I2C handle
int i2c_handle;

// File pointer for logging
FILE *log_file;

// Function prototypes
int read_si1145_register(int handle, int reg);
int write_si1145_register(int handle, int reg, int value);
int read_proximity(int handle);
int read_ambient_light(int handle);
void log_data(FILE *fp, int proximity, int ambient_light);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

// Function to read a single byte from a Si1145 register
int read_si1145_register(int handle, int reg) {
    int value = i2cReadByteData(handle, reg);
    if (value < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, value);
        return -1;
    }
    return value;
}

// Function to write a single byte to a Si1145 register
int write_si1145_register(int handle, int reg, int value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Function to read the proximity value from the Si1145
int read_proximity(int handle) {
    int low = read_si1145_register(handle, SI1145_REG_PS1_DATA0);
    int high = read_si1145_register(handle, SI1145_REG_PS1_DATA0 + 1);

    if (low < 0 || high < 0) {
        return -1;
    }

    return (high << 8) | low;
}

// Function to read the ambient light value from the Si1145
int read_ambient_light(int handle) {
    int low = read_si1145_register(handle, SI1145_REG_ALS_VIS_DATA0);
    int high = read_si1145_register(handle, SI1145_REG_ALS_VIS_DATA0 + 1);

    if (low < 0 || high < 0) {
        return -1;
    }

    return (high << 8) | low;
}

// Function to log the data to a file
void log_data(FILE *fp, int proximity, int ambient_light) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &tm);

    fprintf(fp, "%s,%d,%d\n", timestamp, proximity, ambient_light);
    fflush(fp); // Ensure data is written to disk immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, SI1145_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Verify Si1145 PART_ID
    int part_id = read_si1145_register(i2c_handle, SI1145_REG_PART_ID);
    if (part_id != 0x45) {
        fprintf(stderr, "Error: Si1145 not found (PART_ID = 0x%02X)\n", part_id);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("biometric_data.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Install signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        int proximity = read_proximity(i2c_handle);
        int ambient_light = read_ambient_light(i2c_handle);

        if (proximity >= 0 && ambient_light >= 0) {
            log_data(log_file, proximity, ambient_light);
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        gpioDelay(1000); // Wait for 1 second
    }

    return 0;
}

