#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 27

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define MIN_DISTANCE 2.0       // Minimum acceptable distance (cm)
#define MAX_DISTANCE 400.0     // Maximum acceptable distance (cm)
#define WATERING_THRESHOLD 15.0  // Distance threshold for watering (cm)
#define TIMEOUT_US 30000         // Timeout in microseconds (30ms)
#define TRIGGER_PULSE_US 10      // Trigger pulse duration in microseconds (10us)

// Global variables
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
void triggerSensor();
long getPulseWidth();
double calculateDistance(long pulseWidth);
void logDistance(double distance);
void signalHandler(int signal);

// Signal handler function
void signalHandler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

// Function to trigger the ultrasonic sensor
void triggerSensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(TRIGGER_PULSE_US);
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to measure the pulse width of the echo signal
long getPulseWidth() {
    long startTime = 0, endTime = 0;
    int timeout = 0;

    // Wait for the echo pin to go high
    while (gpioRead(ECHO_PIN) == 0) {
        startTime = gpioTick();
        if (startTime != 0) {
            timeout++;
            if (timeout > TIMEOUT_US) {
                return -1; // Timeout occurred
            }
        }
        gpioDelay(1); // Small delay to avoid busy-waiting
    }

    // Measure the pulse width
    startTime = gpioTick();
    while (gpioRead(ECHO_PIN) == 1) {
        endTime = gpioTick();
        if (endTime != 0) {
            timeout = 0; // Reset timeout counter
        } else {
            return -1; // Error reading GPIO
        }
        gpioDelay(1); // Small delay to avoid busy-waiting
    }

    return endTime - startTime;
}

// Function to calculate the distance in centimeters
double calculateDistance(long pulseWidth) {
    return (double)pulseWidth * SPEED_OF_SOUND / 2000000.0; // Divide by 1000000.0 to convert us to s, and by 2 for one-way distance
}

// Function to log the distance to a file
void logDistance(double distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (distance < 0) {
        fprintf(log_file, "%s - Error: Timeout or sensor failure\n", timestamp);
    } else if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
        fprintf(log_file, "%s - Error: Distance out of range (%.2f cm)\n", timestamp, distance);
    } else {
        fprintf(log_file, "%s - Distance: %.2f cm\n", timestamp, distance);
        if (distance < WATERING_THRESHOLD) {
            fprintf(log_file, "%s - Time to water the plant!\n", timestamp);
        }
    }
    fflush(log_file); // Ensure data is written to the file immediately
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Open the log file
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signalHandler);
    signal(SIGTERM, signalHandler);

    printf("Ultrasonic sensor program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        triggerSensor();
        long pulseWidth = getPulseWidth();

        if (pulseWidth > 0) {
            double distance = calculateDistance(pulseWidth);
            logDistance(distance);
        } else {
            logDistance(-1.0); // Log error
        }

        gpioDelay(100000); // Wait 100ms before next reading
    }

    // Cleanup (should not reach here if signal handler works correctly)
    fclose(log_file);
    gpioTerminate();

    return 0;
}

