#define APDS9960_PTIME 0x82
#define APDS9960_WTIME 0x83
#define APDS9960_PPULSE 0x8E
#define APDS9960_CONTROL 0x8F
#define APDS9960_CONFIG1 0x90
#define APDS9960_ID 0x92
#define APDS9960_STATUS 0x93
#define APDS9960_CDATAL 0x94
#define APDS9960_CDATAH 0x95
#define APDS9960_RDATAL 0x96
#define APDS9960_RDATAH 0x97
#define APDS9960_GDATAL 0x98
#define APDS9960_GDATAH 0x99
#define APDS9960_BDATAL 0x9A
#define APDS9960_BDATAH 0x9B
#define APDS9960_PDATAL 0x9C
#define APDS9960_PDATAH 0x9D

// Enable bits
#define APDS9960_PON 0b00000001
#define APDS9960_AEN 0b00000010
#define APDS9960_PEN 0b00000100
#define APDS9960_WEN 0b00001000

// Proximity threshold
#define PROXIMITY_THRESHOLD 200

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int apds9960_init();
int apds9960_read_proximity(uint16_t *proximity);
int apds9960_read_rgb(uint16_t *red, uint16_t *green, uint16_t *blue);
void log_data(uint16_t red, uint16_t green, uint16_t blue, uint16_t proximity);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize the APDS9960 sensor
int apds9960_init() {
    // Enable power, ALS, proximity, and wait
    if (i2cWriteByteData(i2c_handle, APDS9960_ENABLE, APDS9960_PON | APDS9960_AEN | APDS9960_PEN | APDS9960_WEN) < 0) {
        fprintf(stderr, "Error writing to enable register\n");
        return -1;
    }

    // Set ALS integration time
    if (i2cWriteByteData(i2c_handle, APDS9960_ATIME, 0xDB) < 0) { // 2.78ms
        fprintf(stderr, "Error writing to ALS integration time register\n");
        return -1;
    }

    // Set proximity integration time
    if (i2cWriteByteData(i2c_handle, APDS9960_PTIME, 0xFF) < 0) { // 1.05ms
        fprintf(stderr, "Error writing to proximity integration time register\n");
        return -1;
    }

    // Set wait time
    if (i2cWriteByteData(i2c_handle, APDS9960_WTIME, 0xFF) < 0) { // 2.78ms
        fprintf(stderr, "Error writing to wait time register\n");
        return -1;
    }

    // Set proximity pulse length and number of pulses
    if (i2cWriteByteData(i2c_handle, APDS9960_PPULSE, 0x87) < 0) { // 8 pulses, 16us pulse length
        fprintf(stderr, "Error writing to proximity pulse register\n");
        return -1;
    }

    // Set control register (PSLED12EN = 1, ALSIR = 0b000)
    if (i2cWriteByteData(i2c_handle, APDS9960_CONTROL, 0x01) < 0) {
        fprintf(stderr, "Error writing to control register\n");
        return -1;
    }

    // Set config1 register (PPULSE = 0b000)
    if (i2cWriteByteData(i2c_handle, APDS9960_CONFIG1, 0x00) < 0) {
        fprintf(stderr, "Error writing to config1 register\n");
        return -1;
    }

    return 0;
}

// Read proximity value from the APDS9960 sensor
int apds9960_read_proximity(uint16_t *proximity) {
    char data[2];
    if (i2cReadI2CBlockData(i2c_handle, APDS9960_PDATAL, data, 2) < 0) {
        fprintf(stderr, "Error reading proximity data\n");
        return -1;
    }
    *proximity = (data[1] << 8) | data[0];
    return 0;
}

// Read RGB color values from the APDS9960 sensor
int apds9960_read_rgb(uint16_t *red, uint16_t *green, uint16_t *blue) {
    char data[6];
    if (i2cReadI2CBlockData(i2c_handle, APDS9960_CDATAL, data, 6) < 0) {
        fprintf(stderr, "Error reading RGB data\n");
        return -1;
    }
    *red = (data[1] << 8) | data[0];
    *green = (data[3] << 8) | data[2];
    *blue = (data[5] << 8) | data[4];
    return 0;
}

// Log data to CSV file
void log_data(uint16_t red, uint16_t green, uint16_t blue, uint16_t proximity) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%u,%u,%u,%u\n", timestamp, red, green, blue, proximity);
    fflush(log_file); // Ensure data is written to file immediately
}

