    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uint16_t red, green, blue, proximity;

    // Main loop
    while (!terminate) {
        // Read proximity value
        if (apds9960_read_proximity(&proximity) == 0) {
