#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define SI1182_ADDR 0x60
#define PROX_DATA_REG 0x08
#define SAMPLE_INTERVAL_MS 100
#define CSV_FILENAME "heartrate.csv"

// Global variables
int i2c_fd = -1;
FILE *csv_file = NULL;
volatile sig_atomic_t running = 1;

// Function prototypes
int init_i2c();
int read_proximity();
float calculate_bpm(int proximity_value);
char* get_iso8601_timestamp();
int write_to_csv(const char *timestamp, float bpm);
void signal_handler(int signal);
void cleanup();

// Structure for sensor configuration (example)
typedef struct {
    uint8_t led_drive_strength;
    uint8_t measurement_rate;
} sensor_config_t;

// Function to initialize the I2C connection
int init_i2c() {
    i2c_fd = i2cOpen(I2C_BUS, SI1182_ADDR, 0);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read proximity data from the sensor
int read_proximity() {
    int proximity_value = i2cReadWordData(i2c_fd, PROX_DATA_REG);
    if (proximity_value < 0) {
        fprintf(stderr, "Error reading proximity data: %s\n", strerror(errno));
        return -1;
    }
    return proximity_value;
}

// Function to calculate BPM from proximity data
float calculate_bpm(int proximity_value) {
    // Simple linear mapping for demonstration purposes
    // In a real application, this would be replaced with a more complex algorithm
    // based on the sensor's datasheet.
    return (float)proximity_value * 0.5; // Example: 0-1000 proximity -> 0-500 BPM
}

// Function to get the current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp string

    if (timestamp == NULL) {
        fprintf(stderr, "Error allocating memory for timestamp\n");
        return NULL;
    }

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Function to write data to the CSV file
int write_to_csv(const char *timestamp, float bpm) {
    if (csv_file == NULL) {
        fprintf(stderr, "CSV file is not open\n");
        return -1;
    }

    fprintf(csv_file, "%s,%.2f\n", timestamp, bpm);
    fflush(csv_file); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Received signal %d, shutting down...\n", signal);
}

// Cleanup function to close resources
void cleanup() {
    if (i2c_fd != -1) {
        i2cClose(i2c_fd);
    }
    if (csv_file != NULL) {
        fclose(csv_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open CSV file for appending
    csv_file = fopen(CSV_FILENAME, "a");
    if (csv_file == NULL) {
        fprintf(stderr, "Error opening CSV file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Heart rate monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        // Read proximity data
        int proximity_value = read_proximity();
        if (proximity_value < 0) {
            fprintf(stderr, "Error reading proximity, skipping sample\n");
            gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Delay before next sample
            continue;
        }

        // Calculate BPM
        float bpm = calculate_bpm(proximity_value);

        // Get timestamp
        char *timestamp = get_iso8601_timestamp();
        if (timestamp == NULL) {
            fprintf(stderr, "Error getting timestamp, skipping sample\n");
            gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Delay before next sample
            continue;
        }

        // Write to CSV file
        if (write_to_csv(timestamp, bpm) != 0) {
            fprintf(stderr, "Error writing to CSV file, skipping sample\n");
        }

        free(timestamp); // Free the allocated memory

        // Delay for the specified sample interval
        gpioDelay(SAMPLE_INTERVAL_MS * 1000);
    }

    // Cleanup and exit
    cleanup();
    printf("Heart rate monitoring stopped.\n");
    return 0;
}

