#define GPIO_TRIGGER 17
#define DISTANCE_LOG_FILE "distance_log.txt"
#define TIMEOUT_MS 100

// VL53L0X Register Addresses
#define VL53L0X_REG_IDENTIFICATION_MODEL_ID 0x00c0
#define VL53L0X_REG_IDENTIFICATION_REVISION_ID 0x00c2
#define VL53L0X_REG_SYSRANGE_START 0x0040
#define VL53L0X_REG_RESULT_INTERRUPT_STATUS 0x0083
#define VL53L0X_REG_RESULT_RANGE_STATUS 0x0089
#define VL53L0X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0096

// Global Variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function Prototypes
int init_vl53l0x();
int read_distance(int *distance);
void log_distance(int distance);
void signal_handler(int signal);
int check_sensor_presence();

// Signal Handler
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Check Sensor Presence
int check_sensor_presence() {
    int model_id, revision_id;

    model_id = i2cReadByteData(i2c_handle, VL53L0X_REG_IDENTIFICATION_MODEL_ID);
    if (model_id < 0) {
        fprintf(stderr, "Error reading model ID: %s\n", strerror(errno));
        return 0;
    }

    revision_id = i2cReadByteData(i2c_handle, VL53L0X_REG_IDENTIFICATION_REVISION_ID);
    if (revision_id < 0) {
        fprintf(stderr, "Error reading revision ID: %s\n", strerror(errno));
        return 0;
    }

    if (model_id != 0xEE) {
        fprintf(stderr, "VL53L0X sensor not found. Model ID: 0x%02X\n", model_id);
        return 0;
    }

    printf("VL53L0X sensor found. Model ID: 0x%02X, Revision ID: 0x%02X\n", model_id, revision_id);
    return 1;
}

