#define CH101_ADDR 0x70
#define TRIGGER_REG 0x00
#define DISTANCE_REG 0x01
#define SAMPLE_INTERVAL_MS 200
#define TRIGGER_DELAY_MS 50

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int trigger_sensor();
int read_distance(int *distance);
int log_data(int distance);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, CH101_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Trigger the sensor
int trigger_sensor() {
    int result = i2cWriteByteData(i2c_handle, TRIGGER_REG, 0x01);
    if (result < 0) {
        fprintf(stderr, "Error writing to trigger register: %d\n", result);
        return -1;
    }
    gpioDelay(TRIGGER_DELAY_MS * 1000); // Delay in microseconds
    return 0;
}

// Read distance from the sensor
int read_distance(int *distance) {
    int result = i2cReadWordData(i2c_handle, DISTANCE_REG);
    if (result < 0) {
        fprintf(stderr, "Error reading distance data: %d\n", result);
        return -1;
    }
    *distance = result; // Distance is in mm
    return 0;
}

// Log data to file
int log_data(int distance) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s, %d\n", timestamp, distance);
    fflush(log_file); // Ensure data is written to disk
    printf("%s, %d\n", timestamp, distance);
    return 0;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    int distance;
    // Main loop
    while (!terminate) {
        if (trigger_sensor() == 0) {
            if (read_distance(&distance) == 0) {
                log_data(distance);
            }
        }
        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Delay in microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

