int read_distance(int *distance) {
    char buf[1];
    char data[2];
    int result;
    int retry = 0;

    while (retry < I2C_RETRY_COUNT) {
        // Read distance high byte
        buf[0] = ICU20201_REG_DISTANCE_HIGH;
        result = i2cWriteDevice(i2c_handle, buf, 1);
        if (result != 0) {
            fprintf(stderr, "Error writing to I2C device (high byte): %d\n", result);
            gpioDelay(1000); // Wait 1ms before retry
            retry++;
            continue;
        }

        result = i2cReadDevice(i2c_handle, data, 1);
        if (result != 1) {
            fprintf(stderr, "Error reading from I2C device (high byte): %d\n", result);
            gpioDelay(1000); // Wait 1ms before retry
            retry++;
            continue;
        }

        // Read distance low byte
        buf[0] = ICU20201_REG_DISTANCE_LOW;
        result = i2cWriteDevice(i2c_handle, buf, 1);
        if (result != 0) {
            fprintf(stderr, "Error writing to I2C device (low byte): %d\n", result);
            gpioDelay(1000); // Wait 1ms before retry
            retry++;
            continue;
        }

        result = i2cReadDevice(i2c_handle, data + 1, 1);
        if (result != 1) {
            fprintf(stderr, "Error reading from I2C device (low byte): %d\n", result);
            gpioDelay(1000); // Wait 1ms before retry
            retry++;
            continue;
        }

        *distance = (data[0] << 8) | data[1]; // Combine high and low bytes
