    if (who_am_i != WHO_AM_I_VALUE) {
        fprintf(stderr, "WHO_AM_I register value mismatch: 0x%02X (expected 0x%02X)\n", who_am_i, WHO_AM_I_VALUE);
        return -1;
    }
    return 0;
}

// Read distance from the sensor
int read_distance(int *distance) {
    int raw_distance = i2cReadWordData(i2c_handle, DISTANCE_REG);
    if (raw_distance < 0) {
        fprintf(stderr, "Error reading distance data: %d\n", raw_distance);
        return -1;
    }
    *distance = raw_distance; // Assuming raw value is directly the distance in mm
    return 0;
}

// Control the LED based on distance and threshold
void control_led(int distance, int threshold) {
    if (distance < threshold) {
        gpioWrite(LED_GPIO, 1); // Turn LED on
    } else {
        gpioWrite(LED_GPIO, 0); // Turn LED off
    }
}

// Log data to file
void log_data(int distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Distance: %d mm\n", timestamp, distance);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioWrite(LED_GPIO, 0); // Turn off LED
    gpioSetMode(LED_GPIO, PI_INPUT); // Reset GPIO mode
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    int threshold = DEFAULT_THRESHOLD;
    int distance;

    // Parse command-line arguments
    if (argc > 1) {
        threshold = atoi(argv[1]);
        if (threshold <= 0) {
            fprintf(stderr, "Invalid threshold value. Using default: %d mm\n", DEFAULT_THRESHOLD);
            threshold = DEFAULT_THRESHOLD;
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Open log file
    log_file = fopen("tof_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Verify sensor
    if (verify_sensor() != 0) {
        cleanup();
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    printf("Program started. Threshold: %d mm. Press Ctrl+C to exit.\n", threshold);

    // Main loop
    while (program_running) {
        if (read_distance(&distance) == 0) {
            control_led(distance, threshold);
            log_data(distance);
        } else {
            fprintf(stderr, "Error reading distance. Retrying...\n");
        }
        gpioDelay(POLLING_INTERVAL_MS * 1000); // Delay in microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

