#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Define constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x50
#define COMMAND_FRAME {0x01, 0x02, 0x03, 0x04}
#define HEADER_VALUE 0x02
#define DISTANCE_OFFSET 11
#define DISTANCE_LENGTH 2
#define THRESHOLD 1000 // mm
#define SAMPLE_RATE_MS 100
#define NUM_SAMPLES 10

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure for command frame
typedef struct {
    uint8_t frame[4];
} command_frame_t;

// Function prototypes
int initialize_i2c();
int send_command(int handle, const command_frame_t *command);
int read_data(int handle, uint8_t *data, int count);
int verify_header(const uint8_t *data);
int extract_distance(const uint8_t *data);
float calculate_average_distance(int distances[], int num_samples);
int log_intrusion(float average_distance);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C
int initialize_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Send command to the sensor
int send_command(int handle, const command_frame_t *command) {
    int result = i2cWriteDevice(handle, (char *)command->frame, 4);
    if (result != 4) {
        fprintf(stderr, "Failed to send command: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Read data from the sensor
int read_data(int handle, uint8_t *data, int count) {
    int result = i2cReadDevice(handle, (char *)data, count);
    if (result != count) {
        fprintf(stderr, "Failed to read data: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Verify the header byte
int verify_header(const uint8_t *data) {
    return (data[0] == HEADER_VALUE) ? 0 : -1;
}

// Extract the distance value
int extract_distance(const uint8_t *data) {
    uint16_t distance = (data[DISTANCE_OFFSET] << 8) | data[DISTANCE_OFFSET + 1];
    return (int)distance;
}

// Calculate the average distance
float calculate_average_distance(int distances[], int num_samples) {
    float sum = 0.0;
    for (int i = 0; i < num_samples; i++) {
        sum += distances[i];
    }
    return sum / num_samples;
}

// Log intrusion event
int log_intrusion(float average_distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    log_file = fopen("intrusion_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return -1;
    }

    fprintf(log_file, "%s, %.2f\n", timestamp, average_distance);
    fclose(log_file);

    return 0;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        return 1;
    }

    // Command frame
    command_frame_t command = {COMMAND_FRAME};

    // Main loop
    while (!terminate) {
        int distances[NUM_SAMPLES];
        int valid_readings = 0;

        // Sample the sensor multiple times
        for (int i = 0; i < NUM_SAMPLES; i++) {
            // Send command
            if (send_command(i2c_handle, &command) != 0) {
                fprintf(stderr, "Error sending command, retrying...\n");
                gpioDelay(SAMPLE_RATE_MS); // Wait before retrying
                continue;
            }

            // Wait for response
            gpioDelay(10); // 10 ms delay

            uint8_t data[15];

            // Read data
            if (read_data(i2c_handle, data, 15) == 0) {
                // Verify header
                if (verify_header(data) == 0) {
                    // Extract distance
                    int distance = extract_distance(data);
                    distances[valid_readings++] = distance;
                } else {
                    fprintf(stderr, "Invalid header received\n");
                }
            } else {
                fprintf(stderr, "Error reading data, retrying...\n");
            }

            gpioDelay(SAMPLE_RATE_MS); // 100 ms delay
        }

        // Calculate average distance if enough valid readings
        if (valid_readings > 0) {
            float average_distance = calculate_average_distance(distances, valid_readings);

            // Check for intrusion
            if (average_distance < THRESHOLD) {
                printf("Intrusion detected! Average distance: %.2f mm\n", average_distance);
                if (log_intrusion(average_distance) != 0) {
                    fprintf(stderr, "Error logging intrusion\n");
                }
            }
        } else {
            fprintf(stderr, "No valid readings received\n");
        }

        gpioDelay(SAMPLE_RATE_MS); // 100 ms delay
    }

    // Cleanup resources
    cleanup();

    return 0;
}

