#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <pigpio.h>

// VL53L0X I2C address
#define VL53L0X_ADDR 0x29

// VL53L0X register addresses
#define VL53L0X_REG_IDENTIFICATION_MODEL_ID 0x00c0
#define VL53L0X_REG_RESULT_INTERRUPT_STATUS 0x0013
#define VL53L0X_REG_RESULT_RANGE_STATUS 0x0014
#define VL53L0X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0050

// Expected model ID
#define VL53L0X_EXPECTED_MODEL_ID 0xea

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_vl53l0x();
int read_distance(int *distance);
void print_distance(int distance);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Initialize the VL53L0X sensor
int init_vl53l0x() {
    int model_id;

    // Read the model ID register
    model_id = i2cReadByteData(i2c_handle, VL53L0X_REG_IDENTIFICATION_MODEL_ID);
    if (model_id < 0) {
        fprintf(stderr, "Error reading model ID: %s\n", strerror(errno));
        return -1;
    }

    // Verify the model ID
    if (model_id != VL53L0X_EXPECTED_MODEL_ID) {
        fprintf(stderr, "Error: Invalid model ID (0x%02x, expected 0x%02x)\n", model_id, VL53L0X_EXPECTED_MODEL_ID);
        return -1;
    }

    // Start continuous ranging
    if (i2cWriteByteData(i2c_handle, 0x002d, 0x04) < 0) {
        fprintf(stderr, "Error writing to register 0x002d: %s\n", strerror(errno));
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x002e, 0x01) < 0) {
        fprintf(stderr, "Error writing to register 0x002e: %s\n", strerror(errno));
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x0000, 0x00) < 0) {
        fprintf(stderr, "Error writing to register 0x0000: %s\n", strerror(errno));
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x0001, 0x00) < 0) {
        fprintf(stderr, "Error writing to register 0x0001: %s\n", strerror(errno));
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x0002, 0x00) < 0) {
        fprintf(stderr, "Error writing to register 0x0002: %s\n", strerror(errno));
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x0003, 0x00) < 0) {
        fprintf(stderr, "Error writing to register 0x0003: %s\n", strerror(errno));
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x0010, 0x00) < 0) {
        fprintf(stderr, "Error writing to register 0x0010: %s\n", strerror(errno));
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x0011, 0x00) < 0) {
        fprintf(stderr, "Error writing to register 0x0011: %s\n", strerror(errno));
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x0024, 0x01) < 0) {
        fprintf(stderr, "Error writing to register 0x0024: %s\n", strerror(errno));
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x0025, 0xff) < 0) {
        fprintf(stderr, "Error writing to register 0x0025: %s\n", strerror(errno));
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x0075, 0x00) < 0) {
        fprintf(stderr, "Error writing to register 0x0075: %s\n", strerror(errno));
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x00fe, 0x01) < 0) {
        fprintf(stderr, "Error writing to register 0x00fe: %s\n", strerror(errno));
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x00ff, 0x00) < 0) {
        fprintf(stderr, "Error writing to register 0x00ff: %s\n", strerror(errno));
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x0000, 0x01) < 0) {
        fprintf(stderr, "Error writing to register 0x0000: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Read the distance from the VL53L0X sensor
int read_distance(int *distance) {
    int interrupt_status;
    int range_status;
    int range;

    // Read the interrupt status register
    interrupt_status = i2cReadByteData(i2c_handle, VL53L0X_REG_RESULT_INTERRUPT_STATUS);
    if (interrupt_status < 0) {
        fprintf(stderr, "Error reading interrupt status: %s\n", strerror(errno));
        return -1;
    }

    // Check if a measurement is ready
    if ((interrupt_status & 0x01) == 0) {
        return -1; // No new data available
    }

    // Read the range status register
    range_status = i2cReadByteData(i2c_handle, VL53L0X_REG_RESULT_RANGE_STATUS);
    if (range_status < 0) {
        fprintf(stderr, "Error reading range status: %s\n", strerror(errno));
        return -1;
    }

    // Read the distance data
    range = i2cReadWordData(i2c_handle, VL53L0X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0);
    if (range < 0) {
        fprintf(stderr, "Error reading distance: %s\n", strerror(errno));
        return -1;
    }

    // Clear interrupt
    if (i2cWriteByteData(i2c_handle, VL53L0X_REG_RESULT_INTERRUPT_STATUS, 0x07) < 0) {
        fprintf(stderr, "Error clearing interrupt: %s\n", strerror(errno));
        return -1;
    }

    *distance = range;
    return 0;
}

// Print the distance with timestamp
void print_distance(int distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s Distance: %d mm\n", timestamp, distance);
}

int main() {
    int distance;
    int status;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, VL53L0X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L0X sensor
    if (init_vl53l0x() < 0) {
        fprintf(stderr, "VL53L0X initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        status = read_distance(&distance);
        if (status == 0) {
            print_distance(distance);
        } else if (status < 0) {
            fprintf(stderr, "Error reading distance, retrying...\n");
        }

        gpioDelay(500); // Wait 500ms
    }

    // Close I2C bus and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

