        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x0001, 0x00) < 0) {
        fprintf(stderr, "Error writing to register 0x0001: %s\n", strerror(errno));
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x0002, 0x00) < 0) {
        fprintf(stderr, "Error writing to register 0x0002: %s\n", strerror(errno));
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x0003, 0x00) < 0) {
        fprintf(stderr, "Error writing to register 0x0003: %s\n", strerror(errno));
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x0010, 0x00) < 0) {
        fprintf(stderr, "Error writing to register 0x0010: %s\n", strerror(errno));
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x0011, 0x00) < 0) {
        fprintf(stderr, "Error writing to register 0x0011: %s\n", strerror(errno));
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x0024, 0x01) < 0) {
        fprintf(stderr, "Error writing to register 0x0024: %s\n", strerror(errno));
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x0025, 0xff) < 0) {
