#define REG_PS1_DATA0 0x12
#define REG_PS1_DATA1 0x13

// I2C handle
int i2c_handle;

// Signal handler flag
volatile sig_atomic_t terminate = 0;

// Signal handler function
void sigint_handler(int signal)
{
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Function to read a register from the Si1182
int read_register(int handle, int reg)
{
    int value = i2cReadByteData(handle, reg);
    if (value < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, value);
        return -1;
    }
    return value;
}

// Function to write a register to the Si1182
int write_register(int handle, int reg, int value)
{
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Function to read proximity data from the Si1182
int read_proximity(int handle)
{
    int low = read_register(handle, REG_PS1_DATA0);
    int high = read_register(handle, REG_PS1_DATA1);

    if (low < 0 || high < 0) {
        return -1; // Indicate error
    }

    return (high << 8) | low;
}

