    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Install signal handler
    signal(SIGINT, sigint_handler);

    // Main loop
    while (!terminate) {
        // Read proximity data
        int proximity = read_proximity(i2c_handle);

        if (proximity >= 0) {
            // Log the data
