#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// Define the I2C bus and address
#define I2C_BUS "/dev/i2c-1"
#define MLX75030_ADDR 0x4C

// Define the register address for distance measurement
#define DISTANCE_REG 0x00

// Global variable for the I2C file descriptor
int i2c_fd = -1;

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to initialize the I2C bus
int init_i2c(const char *bus) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening I2C bus %s: %s\n", bus, strerror(errno));
        return -1;
    }
    return fd;
}

// Function to set the I2C slave address
int set_i2c_slave(int fd, int addr) {
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", addr, strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read the distance from the sensor
int read_distance(int fd) {
    unsigned char buffer[2];
    int result;

    // Write the register address to be read
    result = write(fd, &DISTANCE_REG, 1);
    if (result != 1) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }

    // Read two bytes from the sensor
    result = read(fd, buffer, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        return -1;
    }

    // Combine the two bytes to form the distance value
    int distance = (buffer[0] << 8) | buffer[1];
    return distance;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the I2C bus
    i2c_fd = init_i2c(I2C_BUS);
    if (i2c_fd < 0) {
        return 1;
    }

    // Set the I2C slave address
    if (set_i2c_slave(i2c_fd, MLX75030_ADDR) < 0) {
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        // Read the distance from the sensor
        int distance = read_distance(i2c_fd);

        // Print the distance to stdout
        if (distance >= 0) {
            printf("Distance: %d mm\n", distance);
        } else {
            fprintf(stderr, "Failed to read distance\n");
        }

        // Wait for 500 ms
        struct timespec sleep_time;
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = 500000000; // 500 ms
        nanosleep(&sleep_time, NULL);
    }

    return 0;
}

