int read_opt3101(sensor_data_t *data) {
    char buf[6]; // 2 bytes distance, 2 bytes ambient, 1 byte error flags
    int result = i2cReadDevice(i2c_handle, buf, sizeof(buf));

    if (result != sizeof(buf)) {
        fprintf(stderr, "Error reading from OPT3101: %d\n", result);
        return -1;
    }

    data->distance = (buf[0] << 8) | buf[1];
    data->ambient = (buf[2] << 8) | buf[3];
    data->error_flags = buf[4];

    return 0;
}

// Function to log sensor data with timestamp
void log_data(const sensor_data_t *data) {
    struct timeval tv;
    gettimeofday(&tv, NULL);
    time_t nowtime = tv.tv_sec;
    struct tm *nowtm = localtime(&nowtime);
    char tmbuf[64], buf[64];
    strftime(tmbuf, sizeof(tmbuf), "%Y-%m-%d %H:%M:%S", nowtm);
    snprintf(buf, sizeof(buf), "%s.%06ld", tmbuf, tv.tv_usec);

