#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <pigpio.h>
#include <errno.h>

// Configuration
#define UART_DEVICE "/dev/serial0"
#define BAUD_RATE 115200
#define MAGIC_WORD {0x02, 0x01, 0x04, 0x03, 0x06, 0x05, 0x08, 0x07}
#define DISTANCE_THRESHOLD 1.0 // meters
#define LED_GPIO 17
#define RANGE_PROFILE_SIZE 128
#define DISTANCE_BINS 64
#define ALERT_DURATION 2 // seconds

// Global variables
int uart_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Magic word
const unsigned char magic_word[8] = MAGIC_WORD;

// Function prototypes
int initialize_uart(const char *device, int baud_rate);
int read_uart_data(int fd, unsigned char *buffer, int size);
int decode_range_profile(const unsigned char *buffer, int size, short *range_profile);
int check_for_intrusion(const short *range_profile, int size, float threshold);
void log_intrusion(float distance);
void activate_alert_led(int gpio_pin, int duration);
void signal_handler(int signal);

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
}

// Initialize UART
int initialize_uart(const char *device, int baud_rate) {
    int fd = open(device, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd == -1) {
        perror("Error opening UART");
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("Error getting termios attributes");
        close(fd);
        return -1;
    }

    cfsetospeed(&tty, baud_rate);
    cfsetispeed(&tty, baud_rate);

    tty.c_cflag |= (CLOCAL | CREAD);    /* ignore modem controls */
    tty.c_cflag &= ~CSIZE;             /* mask the character size bits */
    tty.c_cflag |= CS8;              /* 8-bit data */
    tty.c_cflag &= ~(PARENB | PARODD); /* no parity */
    tty.c_cflag &= ~CSTOPB;            /* 1 stop bit */
    tty.c_cflag &= ~CRTSCTS;           /* no hardware flowcontrol */

    tty.c_iflag &= ~(IGNBRK | BRKINT | PARMRK | ISTRIP | INLCR | IGNCR | ICRNL | IXON);
    tty.c_lflag &= ~(ECHO | ECHONL | ICANON | ISIG | IEXTEN);
    tty.c_oflag &= ~OPOST;

    tty.c_cc[VMIN] = 0;  // read doesn't block
    tty.c_cc[VTIME] = 5; // 0.5 seconds read timeout

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("Error setting termios attributes");
        close(fd);
        return -1;
    }

    return fd;
}

// Read data from UART
int read_uart_data(int fd, unsigned char *buffer, int size) {
    ssize_t bytes_read = read(fd, buffer, size);
    if (bytes_read == -1) {
        perror("Error reading from UART");
        return -1;
    } else if (bytes_read != size) {
        fprintf(stderr, "Warning: Read %zd bytes, expected %d\n", bytes_read, size);
    }
    return (int)bytes_read;
}

// Decode range profile
int decode_range_profile(const unsigned char *buffer, int size, short *range_profile) {
    if (size != RANGE_PROFILE_SIZE) {
        fprintf(stderr, "Error: Invalid range profile size: %d\n", size);
        return -1;
    }

    for (int i = 0; i < DISTANCE_BINS; i++) {
        range_profile[i] = (short)((buffer[2 * i] & 0xFF) | ((buffer[2 * i + 1] & 0xFF) << 8));
    }
    return 0;
}

// Check for intrusion
int check_for_intrusion(const short *range_profile, int size, float threshold) {
    for (int i = 0; i < DISTANCE_BINS; i++) {
        // Assuming range_profile[i] is in millimeters
        float distance = (float)range_profile[i] / 1000.0; // Convert to meters
        if (distance < threshold) {
            return 1; // Intrusion detected
        }
    }
    return 0; // No intrusion detected
}

// Log intrusion
void log_intrusion(float distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s,%.2f\n", timestamp, distance);
    fflush(log_file); // Ensure data is written to file immediately
}

// Activate alert LED
void activate_alert_led(int gpio_pin, int duration) {
    gpioWrite(gpio_pin, 1); // Turn LED on
    gpioDelay(duration * 1000000); // Delay for duration seconds
    gpioWrite(gpio_pin, 0); // Turn LED off
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Initialize UART
    uart_fd = initialize_uart(UART_DEVICE, BAUD_RATE);
    if (uart_fd == -1) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("intrusion_log.csv", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(uart_fd);
        gpioTerminate();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,distance_m\n");
    }
    rewind(log_file);

    unsigned char buffer[RANGE_PROFILE_SIZE + 8];
    short range_profile[DISTANCE_BINS];
    int magic_word_found = 0;

    fprintf(stderr, "Starting intrusion detection...\n");

    while (!terminate) {
        // Read data from UART
        int bytes_read = read_uart_data(uart_fd, buffer, sizeof(buffer));
        if (bytes_read == -1) {
            continue; // Try again
        }

        // Check for magic word
        if (!magic_word_found) {
            if (memcmp(buffer, magic_word, 8) == 0) {
                magic_word_found = 1;
                fprintf(stderr, "Magic word found!\n");
            } else {
                fprintf(stderr, "Waiting for magic word...\n");
                continue; // Wait for magic word
            }
        }

        // Decode range profile
        if (decode_range_profile(buffer + 8, RANGE_PROFILE_SIZE, range_profile) == 0) {
            // Check for intrusion
            if (check_for_intrusion(range_profile, DISTANCE_BINS, DISTANCE_THRESHOLD)) {
                // Find the closest target distance
                float min_distance = 999.0; // Initialize with a large value
                for (int i = 0; i < DISTANCE_BINS; i++) {
                    float distance = (float)range_profile[i] / 1000.0; // Convert to meters
                    if (distance < min_distance && distance < DISTANCE_THRESHOLD) {
                        min_distance = distance;
                    }
                }

                // Log intrusion
                log_intrusion(min_distance);

                // Activate alert LED
                activate_alert_led(LED_GPIO, ALERT_DURATION);

                fprintf(stderr, "Intrusion detected! Distance: %.2f meters\n", min_distance);
            }
        }

        magic_word_found = 0; // Reset magic word flag for next frame
    }

    // Cleanup
    fprintf(stderr, "Cleaning up...\n");
    if (uart_fd != -1) {
        close(uart_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(LED_GPIO, 0); // Turn off LED
    gpioTerminate();

    fprintf(stderr, "Exiting.\n");
    return 0;
}

