#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define ICU20201_ADDR 0x6A
#define DISTANCE_REG 0x00 // Example register address, check datasheet
#define ALERT_GPIO 17
#define DISTANCE_THRESHOLD 10.0 // cm
#define I2C_RETRY_COUNT 3

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_distance();
void log_distance(double distance);
void check_distance(double distance);
void signal_handler(int signal);
int initialize();
void cleanup();

// Structure for sensor configuration (example)
typedef struct {
    int i2c_bus;
    int i2c_address;
    int alert_pin;
    double distance_threshold;
} sensor_config_t;

// Function to initialize the sensor and GPIO
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, ICU20201_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    // Set GPIO pin as output
    gpioSetMode(ALERT_GPIO, PI_OUTPUT);

    // Open log file
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to read distance from the sensor
int read_distance() {
    int distance = -1; // Default to error value
    int retries = I2C_RETRY_COUNT;

    while (retries > 0) {
        distance = i2cReadWordData(i2c_handle, DISTANCE_REG);
        if (distance >= 0) {
            // Success, break out of the retry loop
            break;
        } else {
            fprintf(stderr, "I2C read failed, retrying... (%d retries left)\n", retries - 1);
            gpioDelay(10); // Small delay before retrying
            retries--;
        }
    }

    if (distance < 0) {
        fprintf(stderr, "Failed to read distance after multiple retries\n");
        return -1; // Indicate failure
    }

    return distance;
}

// Function to log distance to file
void log_distance(double distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s, %.2f\n", timestamp, distance);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Function to check distance and trigger alert
void check_distance(double distance) {
    if (distance < DISTANCE_THRESHOLD) {
        gpioWrite(ALERT_GPIO, 1); // Set GPIO HIGH
        gpioDelay(1000);          // Wait for 1 second
        gpioWrite(ALERT_GPIO, 0); // Set GPIO LOW
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Function to cleanup resources
void cleanup() {
    printf("Cleaning up resources...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(ALERT_GPIO, 0); // Ensure GPIO is LOW
    gpioTerminate();
    printf("Cleanup complete. Exiting.\n");
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize
    if (initialize() != 0) {
        fprintf(stderr, "Initialization failed, exiting\n");
        return 1;
    }

    printf("Program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int raw_distance = read_distance();
        if (raw_distance >= 0) {
            double distance = (double)raw_distance / 10.0; // Example conversion, check datasheet
            log_distance(distance);
            check_distance(distance);
        } else {
            fprintf(stderr, "Failed to read distance, skipping logging and alert\n");
        }

        gpioDelay(100); // 100ms delay
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

