#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define CH201_ADDR 0x40
#define LED_GPIO 18
#define DISTANCE_REG 0x00 // Example register address, check datasheet
#define BLINK_FREQUENCY_MAX 10.0 // Hz
#define BLINK_FREQUENCY_MIN 0.1  // Hz
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_distance(uint16_t *distance);
float calculate_frequency(uint16_t distance);
void control_led(float frequency);
void log_data(uint16_t distance, float frequency);
void signal_handler(int signal);
void cleanup();

// Structure to hold sensor data
typedef struct {
    uint16_t distance;
    float frequency;
    struct timespec timestamp;
} sensor_data_t;

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, CH201_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read distance from the sensor with retries
int read_distance(uint16_t *distance) {
    char buf[2];
    int result, retries = 0;

    while (retries < RETRY_COUNT) {
        result = i2cReadI2CBlockData(i2c_handle, DISTANCE_REG, buf, 2);
        if (result == 2) {
            *distance = (buf[0] << 8) | buf[1];
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read error (attempt %d): %d\n", retries + 1, result);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries++;
        }
    }
    fprintf(stderr, "Failed to read distance after %d retries.\n", RETRY_COUNT);
    return -1; // Failure
}

// Calculate LED blink frequency based on distance
float calculate_frequency(uint16_t distance) {
    // Map distance (0-1000mm) to frequency (0.1-10Hz)
    float frequency = BLINK_FREQUENCY_MIN + (float)distance / 1000.0 * (BLINK_FREQUENCY_MAX - BLINK_FREQUENCY_MIN);
    return frequency;
}

// Control the LED to blink at the calculated frequency
void control_led(float frequency) {
    if (frequency <= 0.0) {
        gpioWrite(LED_GPIO, 0); // Turn off LED if frequency is zero or negative
        return;
    }

    // Calculate on/off times in microseconds
    float period = 1.0 / frequency; // Period in seconds
    int on_time_us = (int)(period / 2.0 * 1000000); // On time in microseconds
    int off_time_us = (int)(period / 2.0 * 1000000); // Off time in microseconds

    gpioWrite(LED_GPIO, 1); // Turn on LED
    gpioDelay(on_time_us);  // Wait for on time
    gpioWrite(LED_GPIO, 0); // Turn off LED
    gpioDelay(off_time_us); // Wait for off time
}

// Log sensor data to stdout
void log_data(uint16_t distance, float frequency) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    printf("%ld.%09ld, Distance: %u mm, Frequency: %.2f Hz\n", ts.tv_sec, ts.tv_nsec, distance, frequency);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources before exiting
void cleanup() {
    gpioWrite(LED_GPIO, 0); // Turn off LED
    i2cClose(i2c_handle);    // Close I2C handle
    gpioTerminate();         // Terminate pigpio
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uint16_t distance;
    float frequency;

    // Main loop
    while (!terminate) {
        // Read distance from sensor
        if (read_distance(&distance) == 0) {
            // Calculate blink frequency
            frequency = calculate_frequency(distance);

            // Control LED
            control_led(frequency);

            // Log data
            log_data(distance, frequency);
        } else {
            fprintf(stderr, "Failed to read distance. Retrying I2C initialization.\n");
            i2cClose(i2c_handle);
            if (init_i2c() != 0) {
                fprintf(stderr, "Failed to re-initialize I2C. Exiting.\n");
                terminate = 1; // Exit loop if re-initialization fails
            }
        }

        // Delay for 100ms
        gpioDelay(100000); // 100ms = 100000 microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

