#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define MLX75030_ADDR 0x4C
#define MEASURE_CMD 0x01
#define DISTANCE_REG 0x00 // Example register address, adjust as needed
#define DISTANCE_REG_SIZE 2
#define SAMPLE_INTERVAL_MS 100
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure for sensor configuration
typedef struct {
    int i2c_bus;
    int i2c_address;
    int sample_interval_ms;
} sensor_config_t;

// Function prototypes
int init_i2c(int bus, int addr);
int read_distance(int handle, int *distance);
int log_data(FILE *fp, long long timestamp, int distance);
void signal_handler(int signal);
void cleanup(int handle, FILE *fp);

// Signal handler for graceful termination
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C communication
int init_i2c(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", handle);
        return -1;
    }
    return handle;
}

// Read distance from the sensor
int read_distance(int handle, int *distance) {
    char cmd = MEASURE_CMD;
    char buffer[2];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (i2cWriteDevice(handle, &cmd, 1) != 1) {
            fprintf(stderr, "Error writing to I2C device (retry %d): %d\n", retries + 1, errno);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries++;
            continue;
        }

        gpioDelay(10000); // 10ms delay for measurement

        if (i2cReadDevice(handle, buffer, DISTANCE_REG_SIZE) != DISTANCE_REG_SIZE) {
            fprintf(stderr, "Error reading from I2C device (retry %d): %d\n", retries + 1, errno);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries++;
            continue;
        }

        *distance = (buffer[0] << 8) | buffer[1]; // Combine bytes
        return 0; // Success
    }

    fprintf(stderr, "Failed to read distance after %d retries.\n", MAX_RETRIES);
    return -1; // Failure
}

// Log data to file
int log_data(FILE *fp, long long timestamp, int distance) {
    if (fprintf(fp, "%lld,%d\n", timestamp, distance) < 0) {
        fprintf(stderr, "Error writing to log file: %d\n", errno);
        return -1;
    }
    return 0;
}

// Cleanup resources
void cleanup(int handle, FILE *fp) {
    if (handle >= 0) {
        i2cClose(handle);
    }
    if (fp != NULL) {
        fclose(fp);
    }
    gpioTerminate();
}

int main() {
    sensor_config_t config = {I2C_BUS, MLX75030_ADDR, SAMPLE_INTERVAL_MS};
    int distance;
    long long timestamp;
    struct timespec ts;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    i2c_handle = init_i2c(config.i2c_bus, config.i2c_address);
    if (i2c_handle < 0) {
        cleanup(-1, NULL);
        return 1;
    }

    // Open log file
    log_file = fopen("distance_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %d\n", errno);
        cleanup(i2c_handle, NULL);
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Get timestamp
        if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
            fprintf(stderr, "Error getting timestamp: %d\n", errno);
            break;
        }
        timestamp = (long long)ts.tv_sec * 1000000000LL + (long long)ts.tv_nsec;

        // Read distance
        if (read_distance(i2c_handle, &distance) == 0) {
            // Log data
            if (log_data(log_file, timestamp, distance) != 0) {
                break;
            }
            fflush(log_file); // Flush to ensure data is written
        } else {
            fprintf(stderr, "Failed to read distance.\n");
        }

        // Delay
        gpioDelay(config.sample_interval_ms * 1000); // Delay in microseconds
    }

    // Cleanup
    cleanup(i2c_handle, log_file);

    return 0;
}

