#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Define GPIO pins for the sensors
#define SENSOR_1_GPIO 17
#define SENSOR_2_GPIO 27

// Debounce time in milliseconds
#define DEBOUNCE_TIME 50

// Log file name
#define LOG_FILE "proximity_log.txt"

// Global variables
FILE *log_file = NULL;
int running = 1;

// Function prototypes
int read_sensor(int gpio);
int debounce_sensor(int gpio, int sensor_id);
void log_event(int sensor_id, const char *event_type);
void signal_handler(int signal);

// Function to read the state of a sensor
int read_sensor(int gpio) {
    int value = gpioRead(gpio);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d: %d\n", gpio, value);
        return -1; // Indicate an error
    }
    return value;
}

// Function to debounce a sensor
int debounce_sensor(int gpio, int sensor_id) {
    int i;
    int high_count = 0;
    int low_count = 0;

    // Read the sensor multiple times to determine the stable state
    for (i = 0; i < 10; i++) {
        int value = read_sensor(gpio);
        if (value < 0) return -1; // Propagate error
        if (value == 1) {
            high_count++;
        } else {
            low_count++;
        }
        gpioDelay(5); // Small delay for reading stability
    }

    // Determine the stable state
    if (high_count > low_count) {
        // Sensor is HIGH
        return 1;
    } else {
        // Sensor is LOW
        return 0;
    }
}

// Function to log an event to the log file
void log_event(int sensor_id, const char *event_type) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, Sensor %d, %s\n", timestamp, sensor_id, event_type);
        fflush(log_file); // Ensure the log is written immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

int main() {
    int sensor1_state = 1; // Initialize to no obstacle
    int sensor2_state = 1; // Initialize to no obstacle
    int debounced_sensor1_state = 1;
    int debounced_sensor2_state = 1;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs
    gpioSetMode(SENSOR_1_GPIO, PI_INPUT);
    gpioSetMode(SENSOR_2_GPIO, PI_INPUT);

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        gpioTerminate();
        return 1;
    }

    printf("Proximity sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        // Read and debounce sensor 1
        int raw_sensor1_value = read_sensor(SENSOR_1_GPIO);
        if (raw_sensor1_value >= 0) {
            debounced_sensor1_state = debounce_sensor(SENSOR_1_GPIO, 1);
            if (debounced_sensor1_state < 0) {
                fprintf(stderr, "Error debouncing sensor 1\n");
            } else {
                if (debounced_sensor1_state == 0 && sensor1_state == 1) {
                    log_event(1, "DETECTED");
                    sensor1_state = 0;
                } else if (debounced_sensor1_state == 1 && sensor1_state == 0) {
                    log_event(1, "CLEARED");
                    sensor1_state = 1;
                }
            }
        }

        // Read and debounce sensor 2
        int raw_sensor2_value = read_sensor(SENSOR_2_GPIO);
        if (raw_sensor2_value >= 0) {
            debounced_sensor2_state = debounce_sensor(SENSOR_2_GPIO, 2);
            if (debounced_sensor2_state < 0) {
                fprintf(stderr, "Error debouncing sensor 2\n");
            } else {
                if (debounced_sensor2_state == 0 && sensor2_state == 1) {
                    log_event(2, "DETECTED");
                    sensor2_state = 0;
                } else if (debounced_sensor2_state == 1 && sensor2_state == 0) {
                    log_event(2, "CLEARED");
                    sensor2_state = 1;
                }
            }
        }

        gpioDelay(10); // Poll every 10 ms
    }

    // Close the log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    printf("Proximity sensor monitoring stopped.\n");

    return 0;
}

