#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define CH101_ADDR 0x50
#define MEAS_STATUS_REG 0x00
#define DISTANCE_HIGH_REG 0x01
#define DISTANCE_LOW_REG 0x02
#define TIMEOUT_MS 50
#define SAMPLE_INTERVAL_MS 500
#define CSV_FILENAME "distance_log.csv"

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;

// Function prototypes
int i2c_open(const char *bus);
int i2c_set_slave_address(int fd, int addr);
int i2c_write(int fd, uint8_t reg, uint8_t value);
int i2c_read(int fd, uint8_t reg, uint8_t *value);
int i2c_close(int fd);
int ch101_read_distance(int fd, int *distance);
int log_distance(const char *timestamp, int distance);
void signal_handler(int signum);

// I2C open function
int i2c_open(const char *bus) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening I2C bus %s: %s\n", bus, strerror(errno));
        return -1;
    }
    return fd;
}

// I2C set slave address function
int i2c_set_slave_address(int fd, int addr) {
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02x: %s\n", addr, strerror(errno));
        return -1;
    }
    return 0;
}

// I2C write function
int i2c_write(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "Error writing to I2C: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// I2C read function
int i2c_read(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error writing register address for read: %s\n", strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "Error reading from I2C: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// I2C close function
int i2c_close(int fd) {
    if (close(fd) < 0) {
        fprintf(stderr, "Error closing I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// CH101 read distance function
int ch101_read_distance(int fd, int *distance) {
    uint8_t status, high_byte, low_byte;
    struct timespec ts_start, ts_current;
    long elapsed_ms;

    // Poll MEAS_STATUS register for valid data
    clock_gettime(CLOCK_MONOTONIC, &ts_start);
    do {
        if (i2c_read(fd, MEAS_STATUS_REG, &status) < 0) {
            fprintf(stderr, "Error reading MEAS_STATUS register\n");
            return -1;
        }
        if (status & 0x01) { // Check VALID bit (bit 0)
            break;
        }
        clock_gettime(CLOCK_MONOTONIC, &ts_current);
        elapsed_ms = (ts_current.tv_sec - ts_start.tv_sec) * 1000 + (ts_current.tv_nsec - ts_start.tv_nsec) / 1000000;
        if (elapsed_ms > TIMEOUT_MS) {
            fprintf(stderr, "Timeout waiting for valid data\n");
            return -1;
        }
        usleep(1000); // Wait 1ms
    } while (1);

    // Read distance data
    if (i2c_read(fd, DISTANCE_HIGH_REG, &high_byte) < 0) {
        fprintf(stderr, "Error reading distance high byte\n");
        return -1;
    }
    if (i2c_read(fd, DISTANCE_LOW_REG, &low_byte) < 0) {
        fprintf(stderr, "Error reading distance low byte\n");
        return -1;
    }

    *distance = (high_byte << 8) | low_byte;
    return 0;
}

// Log distance function
int log_distance(const char *timestamp, int distance) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open\n");
        return -1;
    }

    if (fprintf(log_file, "%s,%d\n", timestamp, distance) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }
    fflush(log_file); // Ensure data is written to disk
    return 0;
}

// Signal handler function
void signal_handler(int signum) {
    printf("Caught signal %d, cleaning up...\n", signum);

    if (i2c_fd != -1) {
        i2c_close(i2c_fd);
    }

    if (log_file != NULL) {
        fclose(log_file);
    }

    exit(0);
}

int main() {
    int distance;
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30]; // ISO 8601 timestamp
    struct timespec sleep_time;
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = SAMPLE_INTERVAL_MS * 1000000; // 500ms

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = i2c_open(I2C_BUS);
    if (i2c_fd < 0) {
        return 1;
    }

    // Set I2C slave address
    if (i2c_set_slave_address(i2c_fd, CH101_ADDR) < 0) {
        i2c_close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen(CSV_FILENAME, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2c_close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        // Read distance
        if (ch101_read_distance(i2c_fd, &distance) == 0) {
            // Get current time
            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

            // Log distance
            if (log_distance(timestamp, distance) < 0) {
                fprintf(stderr, "Error logging distance\n");
            }
        } else {
            fprintf(stderr, "Error reading distance\n");
        }

        // Wait for next sample
        nanosleep(&sleep_time, NULL);
    }

    return 0;
}

