#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <string.h>

// Define the I2C bus and address
#define I2C_BUS "/dev/i2c-1"
#define VL53L5CX_ADDR 0x29

// Define the number of zones
#define NUM_ZONES 64

// Define the I2C register addresses (Example - Replace with actual addresses)
#define VL53L5CX_REG_IDENTIFICATION_MODEL_ID 0x0000
#define VL53L5CX_REG_SYSTEM_START 0x0008
#define VL53L5CX_REG_RESULT_RANGE_STATUS 0x0014
#define VL53L5CX_REG_RESULT_SPAD_NB 0x0022
#define VL53L5CX_REG_RESULT_SIGNAL_RATE 0x001E
#define VL53L5CX_REG_RESULT_AMBIENT_RATE 0x0020
#define VL53L5CX_REG_RESULT_DISTANCE 0x001A

// Global variable for I2C file descriptor
int i2c_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to write a byte to an I2C register
int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("Failed to write to I2C device");
        return -1;
    }
    return 0;
}

// Function to read a byte from an I2C register
int i2c_read_byte(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address for read");
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        perror("Failed to read from I2C device");
        return -1;
    }
    return 0;
}

// Function to read a word (2 bytes) from an I2C register
int i2c_read_word(int fd, uint8_t reg, uint16_t *value) {
    uint8_t buf[1];
    uint8_t data[2];

    buf[0] = reg;
    if (write(fd, buf, 1) != 1) {
        perror("Failed to write register address for read");
        return -1;
    }

    if (read(fd, data, 2) != 2) {
        perror("Failed to read from I2C device");
        return -1;
    }

    *value = (data[0] << 8) | data[1];
    return 0;
}

// Function to initialize the VL53L5CX sensor
int init_vl53l5cx(int fd) {
    uint8_t model_id;

    // Check sensor ID (Example - Replace with actual ID)
    if (i2c_read_byte(fd, VL53L5CX_REG_IDENTIFICATION_MODEL_ID, &model_id) != 0) {
        fprintf(stderr, "Error reading sensor ID\n");
        return -1;
    }

    if (model_id != 0xE1) { // Example ID - Replace with actual ID
        fprintf(stderr, "Incorrect sensor ID: 0x%02X\n", model_id);
        return -1;
    }

    // Configure for 8x8 zone grid (Example - Replace with actual configuration)
    if (i2c_write_byte(fd, 0x002D, 0x01) != 0) return -1; // Example register
    if (i2c_write_byte(fd, 0x002E, 0x02) != 0) return -1; // Example register
    if (i2c_write_byte(fd, 0x002F, 0x03) != 0) return -1; // Example register

    // Start the sensor
    if (i2c_write_byte(fd, VL53L5CX_REG_SYSTEM_START, 0x01) != 0) {
        fprintf(stderr, "Error starting sensor\n");
        return -1;
    }

    return 0;
}

// Function to read distance data from all 64 zones
int read_zone_distances(int fd, uint16_t *distances) {
    uint8_t range_status;
    uint16_t distance;

    for (int i = 0; i < NUM_ZONES; i++) {
        // Read range status (Example - Replace with actual register)
        if (i2c_read_byte(fd, VL53L5CX_REG_RESULT_RANGE_STATUS, &range_status) != 0) {
            fprintf(stderr, "Error reading range status for zone %d\n", i);
            return -1;
        }

        // Read distance (Example - Replace with actual register)
        if (i2c_read_word(fd, VL53L5CX_REG_RESULT_DISTANCE, &distance) != 0) {
            fprintf(stderr, "Error reading distance for zone %d\n", i);
            return -1;
        }

        distances[i] = distance;
    }

    return 0;
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, VL53L5CX_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Initialize the sensor
    if (init_vl53l5cx(i2c_fd) != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        uint16_t distances[NUM_ZONES];

        // Read zone distances
        if (read_zone_distances(i2c_fd, distances) == 0) {
            // Print the distances
            printf("Zone Distances:\n");
            for (int i = 0; i < NUM_ZONES; i++) {
                printf("Zone %d: %d mm\n", i, distances[i]);
            }
            printf("\n");
        } else {
            fprintf(stderr, "Failed to read zone distances\n");
        }

        // Wait 500 ms
        struct timespec ts;
        ts.tv_sec = 0;
        ts.tv_nsec = 500000000; // 500 ms
        nanosleep(&ts, NULL);
    }

    // Close I2C bus (This will not be reached in the infinite loop)
    close(i2c_fd);

    return 0;
}

