#define DISTANCE_REG 0x00

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data and configuration
typedef struct {
    int i2c_bus;
    int i2c_address;
    int i2c_handle;
} sensor_config_t;

// Function prototypes
int init_i2c(sensor_config_t *config);
int read_distance(int i2c_handle);
void log_data(int distance);
void signal_handler(int signal);
void cleanup(sensor_config_t *config);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize I2C communication
int init_i2c(sensor_config_t *config) {
    config->i2c_handle = i2cOpen(config->i2c_bus, config->i2c_address, 0);
    if (config->i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", config->i2c_handle);
        return -1;
    }
    return 0;
}

// Read distance from the sensor with retries
int read_distance(int i2c_handle) {
    int distance = -1;
    int retries = 3;
    int result;

    while (retries > 0) {
        result = i2cReadWordData(i2c_handle, DISTANCE_REG);
        if (result >= 0) {
            distance = result;
            return distance;
        } else {
            fprintf(stderr, "I2C read error: %d, retries remaining: %d\n", result, retries);
            gpioDelay(10); // 10 ms delay
            retries--;
        }
    }

    fprintf(stderr, "Failed to read distance after multiple retries.\n");
    return -1; // Indicate failure
}

// Log the distance data with a timestamp
void log_data(int distance) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    long timestamp_ms = (ts.tv_sec * 1000) + (ts.tv_nsec / 1000000);
    printf("Timestamp: %ld ms, Distance: %d mm\n", timestamp_ms, distance);
}

// Cleanup resources before exiting
void cleanup(sensor_config_t *config) {
    if (config->i2c_handle >= 0) {
        i2cClose(config->i2c_handle);
    }
    gpioTerminate();
}

int main() {
    sensor_config_t sensor_config = {
        .i2c_bus = I2C_BUS,
        .i2c_address = MLX75030_ADDR,
        .i2c_handle = -1 // Initialize to an invalid value
    };

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c(&sensor_config) != 0) {
        gpioTerminate();
        return 1;
    }

