#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// VL53L4CX I2C address
#define VL53L4CX_ADDR 0x29

// VL53L4CX register addresses
#define VL53L4CX_REG_IDENTIFICATION_MODEL_ID 0x0000
#define VL53L4CX_REG_IDENTIFICATION_REVISION_ID 0x0001
#define VL53L4CX_REG_PRE_RANGE_CONFIG_TIMEOUT_MACROP_HI 0x0050
#define VL53L4CX_REG_FINAL_RANGE_CONFIG_TIMEOUT_MACROP_HI 0x0070
#define VL53L4CX_REG_SYSTEM_INTERRUPT_CLEAR 0x0086
#define VL53L4CX_REG_RESULT_INTERRUPT_STATUS 0x0087
#define VL53L4CX_REG_RESULT_RANGE_STATUS 0x0089
#define VL53L4CX_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0096

// Interrupt status bit
#define VL53L4CX_INTERRUPT_STATUS_BIT 0x01

// I2C handle
int i2c_handle;

// Flag to indicate program termination
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int sig)
{
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
    terminate = 1;
}

// Function to read a register from the VL53L4CX
int read_register(int handle, uint16_t reg, uint8_t *data, int len)
{
    if (i2cWriteByteData(handle, reg >> 8, reg & 0xFF) != 0) {
        fprintf(stderr, "Error writing register address: %s\n", strerror(errno));
        return -1;
    }
    if (i2cReadI2CBlockData(handle, reg >> 8, (char *)data, len) != len) {
        fprintf(stderr, "Error reading register data: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to write a register to the VL53L4CX
int write_register(int handle, uint16_t reg, uint8_t data)
{
    if (i2cWriteByteData(handle, reg >> 8, reg & 0xFF) != 0) {
        fprintf(stderr, "Error writing register address: %s\n", strerror(errno));
        return -1;
    }
    if (i2cWriteByteData(handle, reg >> 8, data) != 0) {
        fprintf(stderr, "Error writing register data: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to initialize the VL53L4CX sensor
int init_sensor(int handle)
{
    uint8_t model_id, revision_id;

    // Check sensor ID
    if (read_register(handle, VL53L4CX_REG_IDENTIFICATION_MODEL_ID, &model_id, 1) != 0) {
        fprintf(stderr, "Error reading model ID\n");
        return -1;
    }
    if (read_register(handle, VL53L4CX_REG_IDENTIFICATION_REVISION_ID, &revision_id, 1) != 0) {
        fprintf(stderr, "Error reading revision ID\n");
        return -1;
    }

    if (model_id != 0xE1) {
        fprintf(stderr, "Incorrect model ID: 0x%02X\n", model_id);
        return -1;
    }

    // Configure sensor (example configuration - adjust as needed)
    if (write_register(handle, 0x02D8, 0x01) != 0) return -1; // Example register write
    if (write_register(handle, 0x02D9, 0x02) != 0) return -1; // Example register write
    if (write_register(handle, VL53L4CX_REG_PRE_RANGE_CONFIG_TIMEOUT_MACROP_HI, 0x00) != 0) return -1;
    if (write_register(handle, VL53L4CX_REG_FINAL_RANGE_CONFIG_TIMEOUT_MACROP_HI, 0x00) != 0) return -1;

    return 0;
}

// Function to read distance data from the VL53L4CX
int read_distance(int handle, int *distance)
{
    uint8_t interrupt_status;
    uint8_t range_status;
    uint8_t data[2];

    // Read interrupt status
    if (read_register(handle, VL53L4CX_REG_RESULT_INTERRUPT_STATUS, &interrupt_status, 1) != 0) {
        fprintf(stderr, "Error reading interrupt status\n");
        return -1;
    }

    // Check if interrupt is set
    if (!(interrupt_status & VL53L4CX_INTERRUPT_STATUS_BIT)) {
        return 0; // No new data available
    }

    // Clear interrupt
    if (write_register(handle, VL53L4CX_REG_SYSTEM_INTERRUPT_CLEAR, 0x01) != 0) {
        fprintf(stderr, "Error clearing interrupt\n");
        return -1;
    }

    // Read range status
    if (read_register(handle, VL53L4CX_REG_RESULT_RANGE_STATUS, &range_status, 1) != 0) {
        fprintf(stderr, "Error reading range status\n");
        return -1;
    }

    // Read distance data
    if (read_register(handle, VL53L4CX_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0, data, 2) != 0) {
        fprintf(stderr, "Error reading distance data\n");
        return -1;
    }

    *distance = (data[0] << 8) | data[1];

    return 0;
}

int main()
{
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, VL53L4CX_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Initialize sensor
    if (init_sensor(i2c_handle) != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        int distance;
        struct timespec ts;
        char timestamp[30];

        // Read distance data
        if (read_distance(i2c_handle, &distance) == 0) {
            // Get timestamp
            if (clock_gettime(CLOCK_REALTIME, &ts) == 0) {
                // Format timestamp
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));
                snprintf(timestamp + strlen(timestamp), sizeof(timestamp) - strlen(timestamp), ".%06ld", ts.tv_nsec / 1000);

                // Print distance data
                printf("Timestamp: %s, Distance: %d mm\n", timestamp, distance);
            } else {
                fprintf(stderr, "Error getting timestamp: %s\n", strerror(errno));
            }
        }

        // Wait 500ms
        gpioDelay(500000); // 500ms = 500000 microseconds
    }

    // Close I2C bus and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

