        return -1;
    }

    // Configure for continuous ranging mode (Example - adjust based on datasheet)
    char ranging_mode = 0x02; // Continuous mode
    if (i2cWriteI2CBlockData(i2c_handle, VL53L1X_REG_RANGING_MODE, &ranging_mode, 1) != 1) {
