#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <string.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define SERVO_PIN 17

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define MIN_DISTANCE 2.0       // Minimum measurable distance (cm)
#define MAX_DISTANCE 400.0     // Maximum measurable distance (cm)
#define MIN_ANGLE -90.0        // Minimum servo angle (degrees)
#define MAX_ANGLE 90.0         // Maximum servo angle (degrees)
#define TIMEOUT_US 50000        // Timeout in microseconds (50ms)
#define TRIGGER_PULSE_US 10     // Trigger pulse duration in microseconds

// Global variables
FILE *log_file = NULL;
int running = 1;

// Function prototypes
float measure_distance();
float distance_to_angle(float distance);
void set_servo_angle(float angle);
void log_data(float distance, float angle);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    running = 0;
    set_servo_angle(0.0); // Stop the servo
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

// Function to measure distance using the HC-SR04 sensor
float measure_distance() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(TRIGGER_PULSE_US);
    gpioWrite(TRIGGER_PIN, 0);

    uint32_t start_tick = 0;
    uint32_t end_tick = 0;

    // Wait for echo to go high
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < TIMEOUT_US) {
        count++;
        gpioDelay(1); // Small delay to avoid busy-waiting
    }

    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Timeout waiting for echo high\n");
        return -1.0; // Timeout error
    }

    start_tick = gpioTick();

    // Wait for echo to go low
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < TIMEOUT_US) {
        count++;
        gpioDelay(1);
    }

    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Timeout waiting for echo low\n");
        return -1.0; // Timeout error
    }

    end_tick = gpioTick();

    uint32_t diff = end_tick - start_tick;

    // Calculate distance in centimeters
    float distance = (float)diff * SPEED_OF_SOUND / 2000000.0; // Divide by 1000000.0 to convert us to s, and by 2 for one-way distance

    return distance;
}

// Function to map distance to servo angle
float distance_to_angle(float distance) {
    // Clamp distance to the valid range
    if (distance < MIN_DISTANCE) {
        distance = MIN_DISTANCE;
    } else if (distance > MAX_DISTANCE) {
        distance = MAX_DISTANCE;
    }

    // Linear mapping
    float angle = (distance - MIN_DISTANCE) / (MAX_DISTANCE - MIN_DISTANCE) * (MAX_ANGLE - MIN_ANGLE) + MIN_ANGLE;
    return angle;
}

// Function to set the servo angle
void set_servo_angle(float angle) {
    // Clamp angle to the valid range
    if (angle < MIN_ANGLE) {
        angle = MIN_ANGLE;
    } else if (angle > MAX_ANGLE) {
        angle = MAX_ANGLE;
    }

    // Convert angle to pulse width (500-2500 us)
    int pulse_width = (int)(angle / 180.0 * 2000.0 + 500.0);

    gpioServo(SERVO_PIN, pulse_width);
}

// Function to log data to a file
void log_data(float distance, float angle) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Distance: %.2f cm, Angle: %.2f degrees\n", timestamp, distance, angle);
    fflush(log_file); // Ensure data is written to file immediately
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Open log file
    log_file = fopen("sensor_data.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        gpioTerminate();
        return 1;
    }

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Parking assist system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        float distance = measure_distance();

        if (distance > 0) {
            float angle = distance_to_angle(distance);
            set_servo_angle(angle);
            log_data(distance, angle);
            printf("Distance: %.2f cm, Angle: %.2f degrees\n", distance, angle);
        } else {
            fprintf(stderr, "Error: Invalid distance measurement\n");
        }

        gpioDelay(200); // Wait 200ms
    }

    // Cleanup (should not reach here if signal handler works correctly)
    set_servo_angle(0.0);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

