#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 27
#define BUZZER_PIN 22

// Constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define TIMEOUT_US 500000       // 0.5 seconds timeout in microseconds
#define MIN_DISTANCE 2.0        // Minimum valid distance in cm
#define MAX_DISTANCE 400.0      // Maximum valid distance in cm
#define BUZZER_THRESHOLD 30.0   // Distance threshold for buzzer in cm

// Global variables
volatile unsigned int start_tick = 0;
volatile unsigned int end_tick = 0;
volatile int echo_received = 0;
volatile int timeout_flag = 0;

// Function prototypes
void trigger_pulse();
void echo_callback(int gpio, int level, unsigned int tick);
float calculate_distance(unsigned int pulse_width);
void control_buzzer(float distance);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    gpioWrite(BUZZER_PIN, 0); // Turn off buzzer
    gpioTerminate();           // Terminate pigpio
    exit(0);
}

// Function to generate a 10us trigger pulse
void trigger_pulse() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 microseconds
    gpioWrite(TRIGGER_PIN, 0);
}

// Callback function for echo pin interrupt
void echo_callback(int gpio, int level, unsigned int tick) {
    if (level == 1) {
        // Rising edge
        start_tick = tick;
        echo_received = 1; // Indicate that rising edge has been received
        timeout_flag = 0;  // Reset timeout flag
    } else if (level == 0 && echo_received == 1) {
        // Falling edge
        end_tick = tick;
        echo_received = 0; // Reset echo_received flag
    } else if (level == 0 && echo_received == 0) {
        // Spurious interrupt (falling edge without rising edge)
        timeout_flag = 1; // Set timeout flag
    }
}

// Function to calculate distance in centimeters
float calculate_distance(unsigned int pulse_width) {
    return (pulse_width / 1000000.0) * SPEED_OF_SOUND / 2.0;
}

// Function to control the buzzer
void control_buzzer(float distance) {
    if (distance < BUZZER_THRESHOLD) {
        gpioWrite(BUZZER_PIN, 1); // Turn on buzzer
    } else {
        gpioWrite(BUZZER_PIN, 0); // Turn off buzzer
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    // Register interrupt handler for echo pin
    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set alert function for ECHO_PIN\n");
        gpioTerminate();
        return 1;
    }

    // Set signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Parking sensor started. Press Ctrl+C to exit.\n");

    while (1) {
        // Trigger the sensor
        trigger_pulse();
        echo_received = 0; // Reset echo_received flag
        timeout_flag = 0;  // Reset timeout flag

        // Wait for echo or timeout
        int timeout_count = 0;
        while (echo_received == 0 && timeout_flag == 0 && timeout_count < 100) {
            gpioDelay(5000); // Wait 5ms
            timeout_count++;
        }

        if (timeout_flag == 1) {
            fprintf(stderr, "Timeout: No echo received\n");
            gpioWrite(BUZZER_PIN, 0); // Turn off buzzer
            printf("Distance: Timeout\n");
        } else {
            // Calculate pulse width
            unsigned int pulse_width = end_tick - start_tick;

            // Calculate distance
            float distance = calculate_distance(pulse_width);

            // Validate distance
            if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
                fprintf(stderr, "Invalid distance: %.2f cm\n", distance);
                gpioWrite(BUZZER_PIN, 0); // Turn off buzzer
                printf("Distance: Invalid\n");
            } else {
                // Control buzzer
                control_buzzer(distance);

                // Print distance
                printf("Distance: %.2f cm\n", distance);
            }
        }

        gpioDelay(100000); // 100ms delay
    }

    return 0;
}

