#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define SERVO_PIN 18
#define DISTANCE_THRESHOLD 200 // mm
#define SERVO_OPEN_PULSE 2000  // us
#define SERVO_CLOSE_PULSE 1000 // us
#define SERVO_NEUTRAL_PULSE 1500 // us
#define PWM_FREQUENCY 50 // Hz
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int init_i2c();
int init_vl53l1x();
int read_distance();
void open_gate();
void close_gate();
void neutral_gate();
void log_event(const char *event);
void signal_handler(int signal);
void v2_callback(const char *command);

// VL53L1X register addresses (Example - adjust based on datasheet)
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID  0x00c0
#define VL53L1X_REG_IDENTIFICATION_REVISION_ID 0x00c2
#define VL53L1X_REG_PRE_RANGE_CONFIG_MMC_ENABLE 0x0011
#define VL53L1X_REG_FINAL_RANGE_CONFIG_MIN_COUNT_RATE_RTN_LIMIT 0x0014
#define VL53L1X_REG_SYSTEM_SEQUENCE_CONFIG 0x0081
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0014
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0050

// Function to write a byte to a VL53L1X register
int write_register(int handle, uint16_t reg, uint8_t value) {
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF; // MSB of register address
    buf[1] = reg & 0xFF;      // LSB of register address
    buf[2] = value;
    int result = i2cWriteDevice(handle, buf, 3);
    if (result != 0) {
        fprintf(stderr, "Error writing to register 0x%04X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Function to read a byte from a VL53L1X register
int read_register(int handle, uint16_t reg, uint8_t *value) {
    char reg_buf[2];
    reg_buf[0] = (reg >> 8) & 0xFF; // MSB of register address
    reg_buf[1] = reg & 0xFF;      // LSB of register address

    int result = i2cWriteDevice(handle, reg_buf, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing register address for read 0x%04X: %d\n", reg, result);
        return -1;
    }

    char data_buf[1];
    result = i2cReadDevice(handle, data_buf, 1);
    if (result != 0) {
        fprintf(stderr, "Error reading from register 0x%04X: %d\n", reg, result);
        return -1;
    }

    *value = data_buf[0];
    return 0;
}

// Function to write a word (2 bytes) to a VL53L1X register
int write_register_word(int handle, uint16_t reg, uint16_t value) {
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF; // MSB of register address
    buf[1] = reg & 0xFF;      // LSB of register address
    buf[2] = value & 0xFF;      // LSB of value
    int result = i2cWriteDevice(handle, buf, 3);
    if (result != 0) {
        fprintf(stderr, "Error writing word to register 0x%04X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Function to read a word (2 bytes) from a VL53L1X register
int read_register_word(int handle, uint16_t reg, uint16_t *value) {
    char reg_buf[2];
    reg_buf[0] = (reg >> 8) & 0xFF; // MSB of register address
    reg_buf[1] = reg & 0xFF;      // LSB of register address

    int result = i2cWriteDevice(handle, reg_buf, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing register address for read word 0x%04X: %d\n", reg, result);
        return -1;
    }

    char data_buf[2];
    result = i2cReadDevice(handle, data_buf, 2);
    if (result != 0) {
        fprintf(stderr, "Error reading word from register 0x%04X: %d\n", reg, result);
        return -1;
    }

    *value = (data_buf[0] << 8) | data_buf[1];
    return 0;
}

// Function to initialize the I2C bus
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to initialize the VL53L1X sensor
int init_vl53l1x() {
    // Software reset
    if (write_register(i2c_handle, 0x0000, 0x00) != 0) return -1;
    gpioDelay(2); // Wait for reset

    // Mandatory : private registers
    if (write_register(i2c_handle, 0x002d, 0x04) != 0) return -1; // set bit 2
    if (write_register(i2c_handle, 0x002e, 0x01) != 0) return -1; // set bit 0
