#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIG_PIN 23
#define ECHO_PIN 24

// Define constants
#define TRIGGER_PULSE_WIDTH 10 // microseconds
#define TRIGGER_FREQUENCY 5    // Hz
#define TIMEOUT_DURATION 60    // milliseconds
#define MIN_PULSE_WIDTH 100    // microseconds
#define MAX_PULSE_WIDTH 30000  // microseconds

// Global variables
static volatile uint32_t rising_tick = 0;
static volatile uint32_t falling_tick = 0;
static volatile int echo_received = 0;
static FILE *log_file = NULL;
static volatile int running = 1;

// Function prototypes
void trigger_pulse();
void echo_callback(int gpio, int level, uint32_t tick);
char *get_iso8601_timestamp();
void log_distance(char *timestamp, float distance);
void signal_handler(int signal);

// Function to generate a trigger pulse
void trigger_pulse() {
    gpioWrite(TRIG_PIN, 1);
    gpioDelay(TRIGGER_PULSE_WIDTH);
    gpioWrite(TRIG_PIN, 0);
}

// Callback function for echo pin
void echo_callback(int gpio, int level, uint32_t tick) {
    if (gpio == ECHO_PIN) {
        if (level == 1) {
            rising_tick = tick;
            echo_received = 1; // Reset timeout flag
        } else if (level == 0) {
            falling_tick = tick;
            echo_received = 1; // Reset timeout flag
        }
    }
}

// Function to get the current timestamp in ISO 8601 format
char *get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char *)malloc(25 * sizeof(char)); // Allocate memory for the timestamp

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    return timestamp;
}

// Function to log the distance to stdout and a file
void log_distance(char *timestamp, float distance) {
    printf("%s, Distance: %.2f cm\n", timestamp, distance);

    if (log_file != NULL) {
        fprintf(log_file, "%s, Distance: %.2f cm\n", timestamp, distance);
        fflush(log_file); // Ensure data is written to the file immediately
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIG_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN);

    // Open log file
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set alert function for echo pin
    gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL);

    uint32_t last_trigger_time = 0;

    while (running) {
        // Generate trigger pulse
        uint32_t current_time = gpioTick();
        if (current_time - last_trigger_time > (1000000 / TRIGGER_FREQUENCY)) {
            trigger_pulse();
            last_trigger_time = current_time;

            // Measure pulse duration
            uint32_t start_time = gpioTick();
            while (echo_received == 0 && (gpioTick() - start_time) < (TIMEOUT_DURATION * 1000)) {
                gpioDelay(1); // Small delay to avoid busy-waiting
            }

            if (echo_received == 1) {
                echo_received = 0; // Reset flag for next measurement

                // Calculate pulse duration
                uint32_t pulse_duration = falling_tick - rising_tick;
                if (pulse_duration > 0xFFFFFFFF) {
                    pulse_duration -= 0x100000000; // Handle wraparound
                }

                // Validate pulse duration
                if (pulse_duration < MIN_PULSE_WIDTH || pulse_duration > MAX_PULSE_WIDTH) {
                    char *timestamp = get_iso8601_timestamp();
                    fprintf(stderr, "Warning: Invalid pulse width: %u us\n", pulse_duration);
                    if (log_file != NULL) {
                        fprintf(log_file, "Warning: Invalid pulse width: %u us\n", pulse_duration);
                        fflush(log_file);
                    }
                    free(timestamp);
                } else {
                    // Calculate distance
                    float distance = (float)pulse_duration * 0.0343 / 2.0;

                    // Get timestamp
                    char *timestamp = get_iso8601_timestamp();

                    // Log distance
                    log_distance(timestamp, distance);

                    free(timestamp);
                }
            } else {
                // Timeout occurred
                char *timestamp = get_iso8601_timestamp();
                fprintf(stderr, "Warning: Timeout waiting for echo\n");
                if (log_file != NULL) {
                    fprintf(log_file, "Warning: Timeout waiting for echo\n");
                    fflush(log_file);
                }
                free(timestamp);
            }
        } else {
            gpioDelay(1); // Small delay to avoid busy-waiting
        }
    }

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Release GPIO resources
    gpioTerminate();

    return 0;
}

