        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        distance = read_distance();
        if (distance < 0) {
            fprintf(stderr, "Error reading distance, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        if (distance < DISTANCE_THRESHOLD_OPEN) {
            open_gate();
        } else if (distance > DISTANCE_THRESHOLD_CLOSE) {
            close_gate();
        }

        gpioDelay(100); // Delay to avoid excessive CPU usage
    }

    return 0;
}

