#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Define constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define GPIO_OPEN 18
#define GPIO_CLOSE 19
#define DISTANCE_THRESHOLD 200 // mm
#define TIMING_BUDGET 50000 // us
#define LOG_FILE "gate_events.log"

// VL53L1X register addresses (Example - adjust based on datasheet)
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x00c0
#define VL53L1X_REG_IDENTIFICATION_REVISION_ID 0x00c2
#define VL53L1X_REG_SYSRANGE_START 0x0040
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0014
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0050

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int init_vl53l1x();
int read_distance(uint16_t *distance);
void control_gate(int open);
void log_event(const char *event);
void signal_handler(int signal);
int vl53l1x_write_byte(int handle, uint16_t reg, uint8_t data);
int vl53l1x_read_byte(int handle, uint16_t reg, uint8_t *data);
int vl53l1x_write_word(int handle, uint16_t reg, uint16_t data);
int vl53l1x_read_word(int handle, uint16_t reg, uint16_t *data);

// Function to write a byte to a VL53L1X register
int vl53l1x_write_byte(int handle, uint16_t reg, uint8_t data) {
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF; // MSB of register address
    buf[1] = reg & 0xFF;        // LSB of register address
    buf[2] = data;
    if (i2cWriteDevice(handle, buf, 3) != 3) {
        fprintf(stderr, "Error writing to VL53L1X register 0x%04X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read a byte from a VL53L1X register
int vl53l1x_read_byte(int handle, uint16_t reg, uint8_t *data) {
    char reg_buf[2];
    char data_buf[1];
    reg_buf[0] = (reg >> 8) & 0xFF; // MSB of register address
    reg_buf[1] = reg & 0xFF;        // LSB of register address

    if (i2cWriteDevice(handle, reg_buf, 2) != 2) {
        fprintf(stderr, "Error writing register address for read 0x%04X: %s\n", reg, strerror(errno));
        return -1;
    }

    if (i2cReadDevice(handle, data_buf, 1) != 1) {
        fprintf(stderr, "Error reading from VL53L1X register 0x%04X: %s\n", reg, strerror(errno));
        return -1;
    }

    *data = data_buf[0];
    return 0;
}

// Function to write a word (2 bytes) to a VL53L1X register
int vl53l1x_write_word(int handle, uint16_t reg, uint16_t data) {
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF; // MSB of register address
    buf[1] = reg & 0xFF;        // LSB of register address
    buf[2] = data & 0xFF;       // LSB of data
    if (i2cWriteDevice(handle, buf, 3) != 3) {
        fprintf(stderr, "Error writing to VL53L1X register 0x%04X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read a word (2 bytes) from a VL53L1X register
int vl53l1x_read_word(int handle, uint16_t reg, uint16_t *data) {
    char reg_buf[2];
    char data_buf[2];
    reg_buf[0] = (reg >> 8) & 0xFF; // MSB of register address
    reg_buf[1] = reg & 0xFF;        // LSB of register address

    if (i2cWriteDevice(handle, reg_buf, 2) != 2) {
        fprintf(stderr, "Error writing register address for read 0x%04X: %s\n", reg, strerror(errno));
        return -1;
    }

    if (i2cReadDevice(handle, data_buf, 2) != 2) {
        fprintf(stderr, "Error reading from VL53L1X register 0x%04X: %s\n", reg, strerror(errno));
        return -1;
    }

    *data = (data_buf[0] << 8) | data_buf[1];
    return 0;
}

// Function to initialize the VL53L1X sensor
int init_vl53l1x() {
    uint8_t model_id, revision_id;

    // Check sensor ID
    if (vl53l1x_read_byte(i2c_handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID, &model_id) != 0) {
        fprintf(stderr, "Error reading model ID\n");
        return -1;
    }
    if (vl53l1x_read_byte(i2c_handle, VL53L1X_REG_IDENTIFICATION_REVISION_ID, &revision_id) != 0) {
        fprintf(stderr, "Error reading revision ID\n");
        return -1;
    }

    if (model_id != 0xEACC) {
        fprintf(stderr, "Incorrect model ID: 0x%02X\n", model_id);
        return -1;
    }

    // Soft reset
    if (vl53l1x_write_byte(i2c_handle, 0x0000, 0x01) != 0) {
        fprintf(stderr, "Error writing soft reset command\n");
        return -1;
    }
    gpioDelay(10000); // Wait for reset to complete

    // Configure timing budget (example - adjust as needed)
    if (vl53l1x_write_word(i2c_handle, 0x001E, TIMING_BUDGET) != 0) {
        fprintf(stderr, "Error writing timing budget\n");
        return -1;
    }

    // Start ranging
    if (vl53l1x_write_byte(i2c_handle, VL53L1X_REG_SYSRANGE_START, 0x01) != 0) {
        fprintf(stderr, "Error starting ranging\n");
        return -1;
    }

    return 0;
}

// Function to read the distance from the VL53L1X sensor
int read_distance(uint16_t *distance) {
    uint8_t range_status;
    uint16_t range;

    // Read range status
    if (vl53l1x_read_byte(i2c_handle, VL53L1X_REG_RESULT_RANGE_STATUS, &range_status) != 0) {
        fprintf(stderr, "Error reading range status\n");
        return -1;
    }

    // Read distance
    if (vl53l1x_read_word(i2c_handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0, &range) != 0) {
        fprintf(stderr, "Error reading distance\n");
        return -1;
    }

    *distance = range;
    return 0;
}

// Function to control the gate (open/close)
void control_gate(int open) {
    gpioWrite(GPIO_OPEN, open);
    gpioWrite(GPIO_CLOSE, !open);
}

// Function to log events to a file
void log_event(const char *event) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s: %s\n", timestamp, event);
    fflush(log_file); // Ensure immediate write to file
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

int main() {
    uint16_t distance;
    int init_result;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(GPIO_OPEN, PI_OUTPUT);
    gpioSetMode(GPIO_CLOSE, PI_OUTPUT);

    // Initialize VL53L1X sensor
    init_result = init_vl53l1x();
    if (init_result != 0) {
        fprintf(stderr, "VL53L1X initialization failed\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (program_running) {
        if (read_distance(&distance) == 0) {
            if (distance < DISTANCE_THRESHOLD) {
                control_gate(1); // Open gate
                log_event("Gate opened");
            } else {
                control_gate(0); // Close gate
                log_event("Gate closed");
            }
        } else {
            fprintf(stderr, "Error reading distance\n");
        }

        gpioDelay(500000); // 500 ms
    }

    // Cleanup
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioWrite(GPIO_OPEN, 0); // Ensure gate is closed on exit
    gpioWrite(GPIO_CLOSE, 1);
