// Define constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define MOTOR_FORWARD_GPIO 17
#define MOTOR_BACKWARD_GPIO 18
#define DISTANCE_THRESHOLD_CLOSE 100
#define DISTANCE_THRESHOLD_FAR 300
#define DISTANCE_THRESHOLD_STOP 150
#define DISTANCE_THRESHOLD_STOP_FAR 250
#define DISTANCE_READ_PIN 24
#define MAX_RETRIES 3
#define BASE_DELAY_US 1000 // 1ms

// VL53L1X register addresses
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x00c0
#define VL53L1X_REG_IDENTIFICATION_REVISION_ID 0x00c2
#define VL53L1X_REG_PRE_RANGE_CONFIG_TIMEOUT_MACROP_HI 0x0050
#define VL53L1X_REG_FINAL_RANGE_CONFIG_TIMEOUT_MACROP_HI 0x0070
#define VL53L1X_REG_SYSTEM_SEQUENCE_CONFIG 0x0081
#define VL53L1X_REG_SYSRANGE_START 0x000
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0014
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0058

// Global variables
int i2c_handle;
volatile int running = 1;

// Function prototypes
int vl53l1x_init();
int vl53l1x_read_distance(uint16_t *distance);
void motor_forward();
void motor_backward();
void motor_stop();
void distance_read_isr(int gpio, int level, uint32_t tick, void *user_data);
void signal_handler(int signal);

// Function to write a byte to a VL53L1X register with retry
int vl53l1x_write_byte(int handle, uint16_t reg, uint8_t data) {
    int retries = 0;
    int result;
    char buf[3];

    buf[0] = (reg >> 8) & 0xFF; // MSB of register address
    buf[1] = reg & 0xFF;        // LSB of register address
    buf[2] = data;

    while (retries < MAX_RETRIES) {
        result = i2cWriteDevice(handle, buf, 3);
        if (result == 0) {
            return 0; // Success
        }
        fprintf(stderr, "I2C write error (reg 0x%04X, data 0x%02X), retry %d\n", reg, data, retries + 1);
        gpioDelay(BASE_DELAY_US * (1 << retries));
        retries++;
    }
    fprintf(stderr, "I2C write failed after %d retries (reg 0x%04X, data 0x%02X)\n", MAX_RETRIES, reg, data);
    return -1; // Failure
}

// Function to read a byte from a VL53L1X register with retry
int vl53l1x_read_byte(int handle, uint16_t reg, uint8_t *data) {
    int retries = 0;
    int result;
    char buf[2];
    char read_buf[1];

    buf[0] = (reg >> 8) & 0xFF; // MSB of register address
    buf[1] = reg & 0xFF;        // LSB of register address

    while (retries < MAX_RETRIES) {
        result = i2cWriteDevice(handle, buf, 2);
        if (result != 0) {
            fprintf(stderr, "I2C write (address) error (reg 0x%04X), retry %d\n", reg, retries + 1);
            gpioDelay(BASE_DELAY_US * (1 << retries));
            retries++;
            continue;
        }

        result = i2cReadDevice(handle, read_buf, 1);
        if (result == 0) {
            *data = read_buf[0];
            return 0; // Success
        }
        fprintf(stderr, "I2C read error (reg 0x%04X), retry %d\n", reg, retries + 1);
        gpioDelay(BASE_DELAY_US * (1 << retries));
        retries++;
    }
    fprintf(stderr, "I2C read failed after %d retries (reg 0x%04X)\n", MAX_RETRIES, reg);
    return -1; // Failure
}

// Function to read a 16-bit word from a VL53L1X register with retry
int vl53l1x_read_word(int handle, uint16_t reg, uint16_t *data) {
    int retries = 0;
    int result;
    char buf[2];
    char read_buf[2];

    buf[0] = (reg >> 8) & 0xFF; // MSB of register address
    buf[1] = reg & 0xFF;        // LSB of register address

    while (retries < MAX_RETRIES) {
        result = i2cWriteDevice(handle, buf, 2);
        if (result != 0) {
            fprintf(stderr, "I2C write (address) error (reg 0x%04X), retry %d\n", reg, retries + 1);
            gpioDelay(BASE_DELAY_US * (1 << retries));
            retries++;
            continue;
        }

        result = i2cReadDevice(handle, read_buf, 2);
        if (result == 0) {
            *data = (read_buf[0] << 8) | read_buf[1];
            return 0; // Success
        }
        fprintf(stderr, "I2C read error (reg 0x%04X), retry %d\n", reg, retries + 1);
        gpioDelay(BASE_DELAY_US * (1 << retries));
        retries++;
    }
    fprintf(stderr, "I2C read failed after %d retries (reg 0x%04X)\n", MAX_RETRIES, reg);
    return -1; // Failure
}

