#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Define MPR121 I2C address
#define MPR121_ADDR 0x5A

// Define MPR121 registers
#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_ELECTRODE_CONFIG 0x5E
#define MPR121_SOFT_RESET 0x80

// Define GPIO pins for LEDs
#define LED0 17
#define LED1 18
#define LED2 27
#define LED3 22

// Define LED patterns
const uint8_t led_patterns[12] = {
    0x01, 0x02, 0x04, 0x08, 0x10, 0x20, 0x40, 0x80, 0x03, 0x0C, 0x30, 0xC0
};

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int mpr121_init();
int read_touch_status(uint16_t *touch_status);
void set_led_pattern(uint8_t pattern);
void log_event(int electrode);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// MPR121 initialization function
int mpr121_init() {
    // Soft reset
    if (i2cWriteByteData(i2c_handle, MPR121_SOFT_RESET, 0x63) < 0) {
        fprintf(stderr, "Error: Failed to reset MPR121: %s\n", strerror(errno));
        return -1;
    }
    gpioDelay(100); // Wait for reset to complete

    // Configure electrode sensitivity (example values)
    if (i2cWriteByteData(i2c_handle, 0x41, 0x0A) < 0) { // Touch Threshold
        fprintf(stderr, "Error: Failed to write touch threshold: %s\n", strerror(errno));
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x42, 0x05) < 0) { // Release Threshold
        fprintf(stderr, "Error: Failed to write release threshold: %s\n", strerror(errno));
        return -1;
    }

    // Enable all electrodes
    if (i2cWriteByteData(i2c_handle, MPR121_ELECTRODE_CONFIG, 0x0C) < 0) {
        fprintf(stderr, "Error: Failed to enable electrodes: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Function to read touch status from MPR121
int read_touch_status(uint16_t *touch_status) {
    char buf[2];
    if (i2cReadI2CBlockData(i2c_handle, MPR121_TOUCHSTATUS_L, buf, 2) != 2) {
        fprintf(stderr, "Error: Failed to read touch status: %s\n", strerror(errno));
        return -1;
    }

    *touch_status = (buf[1] << 8) | buf[0];
    return 0;
}

// Function to set LED pattern
void set_led_pattern(uint8_t pattern) {
    gpioWrite(LED0, (pattern >> 0) & 0x01);
    gpioWrite(LED1, (pattern >> 1) & 0x01);
    gpioWrite(LED2, (pattern >> 2) & 0x01);
    gpioWrite(LED3, (pattern >> 3) & 0x01);
}

// Function to log event
void log_event(int electrode) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s - Electrode %d touched\n", timestamp, electrode);
    fflush(log_file); // Ensure immediate write to file
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Initialize MPR121
    if (mpr121_init() < 0) {
        fprintf(stderr, "Error: MPR121 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(LED0, PI_OUTPUT);
    gpioSetMode(LED1, PI_OUTPUT);
    gpioSetMode(LED2, PI_OUTPUT);
    gpioSetMode(LED3, PI_OUTPUT);

    // Open log file
    log_file = fopen("art_installation.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uint16_t touch_status;
    int electrode;

    // Main loop
    while (program_running) {
        if (read_touch_status(&touch_status) == 0) {
            for (electrode = 0; electrode < 12; electrode++) {
                if (touch_status & (1 << electrode)) {
                    set_led_pattern(led_patterns[electrode]);
                    log_event(electrode);
                }
            }
        } else {
            fprintf(stderr, "Error: Failed to read touch status, retrying...\n");
        }

        gpioDelay(50); // Poll every 50ms
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

