    if (i2cWriteByteData(i2c_handle, MPR121_ESSR47, 0x0C) < 0) return -1;
    if (i2cWriteByteData(i2c_handle, MPR121_ESSR48, 0x0C) < 0) return -1;
    if (i2cWriteByteData(i2c_handle, MPR121_ESSR49, 0x0C) < 0) return -1;
    if (i2cWriteByteData(i2c_handle, MPR121_ESSR50, 0x0C) < 0) return -1;
    if (i2cWriteByteData(i2c_handle, MPR121_ESSR51, 0x0C) < 0) return -1;
    if (i2cWriteByteData(i2c_handle, MPR121_ESSR52, 0x0C) < 0) return -1;
    if (i2cWriteByteData(i2c_handle, MPR121_ESSR53, 0x0C) < 0) return -1;
    if (i2cWriteByteData(i2c_handle, MPR121_ESSR54, 0x0C) < 0) return -1;
    if (i2cWriteByteData(i2c_handle, MPR121_ESSR55, 0x0C) < 0) return -1;
    if (i2cWriteByteData(i2c_handle, MPR121_ESSR56, 0x0C) < 0) return -1;
    if (i2cWriteByteData(i2c_handle, MPR121_ESSR57, 0x0C) < 0) return -1;
    if (i2cWriteByteData(i2c_handle, MPR121_ESSR58, 0x0C) < 0) return -1;
    if (i2cWriteByteData(i2c_handle, MPR121_ESSR59, 0x0C) < 0) return -1;
    if (i2cWriteByteData(i2c_handle, MPR121_ESSR60, 0x0C) < 0) return -1;
    if (i2cWriteByteData(i2c_handle, MPR121_ESSR61, 0x0C) < 0) return -1;
    if (i2cWriteByteData(i2c_handle, MPR121_ESSR62, 0x0C) < 0) return -1;
    if (i2cWriteByteData(i2c_handle, MPR121_ESSR63, 0x0C) < 0) return -1;

    // Enable all electrodes
    if (i2cWriteByteData(i2c_handle, MPR121_ECR, 0x8F) < 0) {
        fprintf(stderr, "Error: Could not enable electrodes: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Function to read the touch status from the MPR121
int read_touch_status(uint16_t *touch_status) {
    char buf[2];
    if (i2cReadI2CBlockData(i2c_handle, MPR121_TOUCHSTATUS_L, buf, 2) != 2) {
        fprintf(stderr, "Error: Could not read touch status: %s\n", strerror(errno));
        return -1;
    }
    *touch_status = ((uint16_t)buf[1] << 8) | (uint16_t)buf[0];
    return 0;
}

// Function to log a proximity event to a file
int log_proximity_event() {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    log_file = fopen("proximity.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open proximity.log: %s\n", strerror(errno));
        return -1;
    }

    fprintf(log_file, "%s: Proximity event detected\n", timestamp);
    fclose(log_file);
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Initialize MPR121
    if (mpr121_init() < 0) {
        fprintf(stderr, "Error: MPR121 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set LED pin as output
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uint16_t touch_status = 0;
    int proximity_detected = 0;

    // Main loop
    while (1) {
        // Read touch status
        if (read_touch_status(&touch_status) < 0) {
            fprintf(stderr, "Error: Could not read touch status, retrying...\n");
            gpioDelay(100000); // 100ms delay
            continue;
        }

        // Check for proximity event
        if (touch_status > 0 && !proximity_detected) {
            printf("Proximity event detected!\n");
            proximity_detected = 1;

            // Turn on LED
            gpioWrite(LED_PIN, 1);

            // Log proximity event
            if (log_proximity_event() < 0) {
                fprintf(stderr, "Error: Could not log proximity event\n");
            }

            // Wait for 1 second
            gpioDelay(1000000);

            // Turn off LED
            gpioWrite(LED_PIN, 0);
        } else if (touch_status == 0 && proximity_detected) {
            proximity_detected = 0;
        }

        gpioDelay(50000); // 50ms delay
    }

    // Cleanup (should not reach here in normal operation due to the signal handler)
    i2cClose(i2c_handle);
    gpioWrite(LED_PIN, 0);
    gpioSetMode(LED_PIN, PI_INPUT); // Set back to input
    gpioTerminate();
    return 0;
}

