#include <string.h>
#include <unistd.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define MIN_DISTANCE 2.0       // cm
#define MAX_DISTANCE 400.0     // cm
#define TIMEOUT_US 30000        // 30ms
#define TRIGGER_PULSE_US 10     // 10us trigger pulse
#define TRIGGER_LOW_US 5        // 5us trigger low pulse

// Global variables
volatile sig_atomic_t program_running = 1;
FILE *log_file = NULL;

// Function prototypes
void triggerSensor();
long measurePulseWidth();
double calculateDistance(long pulseWidth);
void logDistance(double distance);
void signalHandler(int signal);
int setup();
void cleanup();

// Signal handler function
void signalHandler(int signal) {
    if (signal == SIGINT) {
        printf("Caught SIGINT, exiting gracefully.\n");
        program_running = 0;
    }
}

// Function to trigger the ultrasonic sensor
void triggerSensor() {
    gpioWrite(TRIGGER_PIN, 0); // Low for 5us
    gpioDelay(TRIGGER_LOW_US);
    gpioWrite(TRIGGER_PIN, 1); // High for 10us
    gpioDelay(TRIGGER_PULSE_US);
    gpioWrite(TRIGGER_PIN, 0); // Back to low
}

// Function to measure the pulse width of the echo signal
long measurePulseWidth() {
    long startTime = 0, endTime = 0;
    int timeout = 0;

    // Wait for the echo pin to go high
    while (gpioRead(ECHO_PIN) == 0) {
        startTime = gpioTick();
        if (startTime != 0) {
            timeout++;
            if (timeout > TIMEOUT_US) {
                fprintf(stderr, "Error: Echo pulse timeout (rising edge).\n");
                return -1; // Timeout error
            }
        }
        gpioDelay(1); // Small delay to avoid busy-waiting
    }

    // Measure the pulse width
    startTime = gpioTick();
    timeout = 0;
    while (gpioRead(ECHO_PIN) == 1) {
        endTime = gpioTick();
        if (endTime != 0) {
            timeout++;
            if (timeout > TIMEOUT_US) {
                fprintf(stderr, "Error: Echo pulse timeout (falling edge).\n");
                return -1; // Timeout error
            }
        }
        gpioDelay(1); // Small delay to avoid busy-waiting
    }
    endTime = gpioTick();

    return endTime - startTime;
}

// Function to calculate the distance in centimeters
double calculateDistance(long pulseWidth) {
    return (double)pulseWidth * SPEED_OF_SOUND / 2000000.0; // Divide by 2 for one-way distance
}

// Function to log the distance to a file
void logDistance(double distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s,%.2f\n", timestamp, distance);
        fflush(log_file); // Flush the buffer to ensure data is written
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Setup function to initialize pigpio and open the log file
int setup() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1; // Indicate failure
    }

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file.\n");
        gpioTerminate(); // Clean up pigpio before exiting
        return 1; // Indicate failure
    }

    return 0; // Indicate success
}

// Cleanup function to release resources
void cleanup() {
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Install signal handler
    signal(SIGINT, signalHandler);

    // Initialize pigpio and open log file
    if (setup() != 0) {
        return 1; // Exit if setup fails
    }

    printf("Ultrasonic distance measurement started. Press Ctrl+C to exit.\n");

    while (program_running) {
        triggerSensor();
        long pulseWidth = measurePulseWidth();

        if (pulseWidth > 0) {
            double distance = calculateDistance(pulseWidth);

            if (distance >= MIN_DISTANCE && distance <= MAX_DISTANCE) {
                logDistance(distance);
                printf("Distance: %.2f cm\n", distance);
            } else {
                fprintf(stderr, "Error: Distance out of range (%.2f cm).\n", distance);
                fprintf(log_file, "Error: Distance out of range (%.2f cm).\n", distance);
                fflush(log_file);
            }
        } else {
            fprintf(stderr, "Error: Could not measure pulse width.\n");
        }

        sleep(1); // Wait for 1 second
    }

    // Cleanup and exit
    cleanup();
    printf("Program terminated.\n");
    return 0;
}

