void trigger_pulse();
void echo_callback(int gpio, int level, unsigned int tick);
double calculate_distance(unsigned int pulse_width);
void log_distance(double distance);
void signal_handler(int signal);

// Function to generate a 10 us trigger pulse
void trigger_pulse() {
    gpioWrite(TRIG_PIN, 1);
    gpioDelay(10); // 10 us
    gpioWrite(TRIG_PIN, 0);
}

// Callback function for echo pin changes
void echo_callback(int gpio, int level, unsigned int tick) {
    if (level == 1) {
        // Rising edge
        start_tick = tick;
        echo_active = 1;
    } else if (level == 0 && echo_active) {
        // Falling edge
        end_tick = tick;
        echo_active = 0;

        // Calculate pulse width
        unsigned int pulse_width = end_tick - start_tick;
        if (pulse_width > 0) {
            // Calculate distance
            double distance = calculate_distance(pulse_width);

            // Log distance
            log_distance(distance);
        }
    }
}

// Function to calculate distance in meters
double calculate_distance(unsigned int pulse_width) {
    // Convert pulse width to microseconds
    double pulse_width_us = (double)pulse_width / 1000.0;

    // Calculate distance in meters
    double distance = (pulse_width_us * SPEED_OF_SOUND) / 2000000.0; // Divide by 2 for one-way distance

    return distance;
}

// Function to log distance with timestamp
void log_distance(double distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, %.4f\n", timestamp, distance);
        fflush(log_file); // Ensure data is written to file immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Signal handler for graceful shutdown
