#include <string.h>

// Constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define GPIO_GATE 24
#define DISTANCE_THRESHOLD 20 // cm
#define I2C_RETRY_COUNT 3

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_vl53l1x();
int read_distance();
void control_gate(int distance);
void log_message(const char *message);
void signal_handler(int signal);

// VL53L1X register addresses (Example - adjust based on datasheet)
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID  0x00c0
#define VL53L1X_REG_IDENTIFICATION_REVISION_ID 0x00c2
#define VL53L1X_REG_SYSRANGE_START 0x0040
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0014
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0050

// Function to write a byte to a VL53L1X register
int write_register(int handle, uint8_t reg, uint8_t value) {
    char buf[2];
    buf[0] = reg;
    buf[1] = value;
    int result = i2cWriteDevice(handle, buf, 2);
    if (result != 0) {
        char error_message[100];
        snprintf(error_message, sizeof(error_message), "I2C write error: reg=0x%02x, value=0x%02x, result=%d", reg, value, result);
        log_message(error_message);
        return -1;
    }
    return 0;
}

// Function to read a byte from a VL53L1X register
int read_register(int handle, uint8_t reg, uint8_t *value) {
    int result = i2cWriteDevice(handle, &reg, 1);
    if (result != 0) {
        char error_message[100];
        snprintf(error_message, sizeof(error_message), "I2C write (address) error: reg=0x%02x, result=%d", reg, result);
        log_message(error_message);
        return -1;
    }
    result = i2cReadDevice(handle, value, 1);
    if (result != 0) {
        char error_message[100];
        snprintf(error_message, sizeof(error_message), "I2C read error: reg=0x%02x, result=%d", reg, result);
        log_message(error_message);
        return -1;
    }
    return 0;
}

// Function to read a 16-bit word from a VL53L1X register
int read_word(int handle, uint8_t reg, uint16_t *value) {
    char buf[1];
    buf[0] = reg;
    int result = i2cWriteDevice(handle, buf, 1);
    if (result != 0) {
        char error_message[100];
        snprintf(error_message, sizeof(error_message), "I2C write (address) error: reg=0x%02x, result=%d", reg, result);
        log_message(error_message);
        return -1;
    }
    char data[2];
    result = i2cReadDevice(handle, data, 2);
    if (result != 0) {
        char error_message[100];
        snprintf(error_message, sizeof(error_message), "I2C read error: reg=0x%02x, result=%d", reg, result);
        log_message(error_message);
        return -1;
    }
    *value = (data[0] << 8) | data[1];
    return 0;
}

// Function to initialize the VL53L1X sensor
