    uint8_t model_id, revision_id;

    // Check sensor ID
    if (read_register(i2c_handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID, &model_id) != 0) {
        log_message("Failed to read VL53L1X model ID.");
        return -1;
    }
    if (read_register(i2c_handle, VL53L1X_REG_IDENTIFICATION_REVISION_ID, &revision_id) != 0) {
        log_message("Failed to read VL53L1X revision ID.");
        return -1;
