#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <string.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define SERVO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define TIMEOUT_US 30000       // 30 ms timeout
#define MIN_DISTANCE 2.0      // Minimum valid distance (cm)
#define MAX_DISTANCE 400.0    // Maximum valid distance (cm)
#define SERVO_MIN_PULSE_WIDTH 1000 // Minimum pulse width (us)
#define SERVO_MAX_PULSE_WIDTH 2000 // Maximum pulse width (us)
#define SERVO_RANGE (SERVO_MAX_PULSE_WIDTH - SERVO_MIN_PULSE_WIDTH)
#define SERVO_NEUTRAL_ANGLE 90.0 // Neutral angle (degrees)

// Global variables
volatile unsigned int pulse_width = 0;
volatile int new_pulse = 0;
volatile sig_atomic_t program_running = 1;

// Function prototypes
void trigger_pulse();
void echo_callback(int gpio, int level, uint32_t tick, void *user_data);
float calculate_distance(unsigned int pulse_width);
float moving_average(float new_value, float *buffer, int buffer_size, int *index);
int set_servo_angle(float angle);
int log_data(float distance, float angle);
void signal_handler(int signal);

// Function to generate a 10us trigger pulse
void trigger_pulse() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us
    gpioWrite(TRIGGER_PIN, 0);
}

// Callback function for echo pin
void echo_callback(int gpio, int level, uint32_t tick, void *user_data) {
    static uint32_t start_tick = 0;
    static uint32_t end_tick = 0;

    if (level == 1) {
        start_tick = tick;
    } else if (level == 0) {
        end_tick = tick;

        // Calculate pulse width
        pulse_width = end_tick - start_tick;

        // Handle tick counter wrap-around
        if (end_tick < start_tick) {
            pulse_width = (0xFFFFFFFF - start_tick) + end_tick;
        }

        new_pulse = 1; // Set the flag to indicate a new pulse
    }
}

// Function to calculate distance in centimeters
float calculate_distance(unsigned int pulse_width) {
    return (pulse_width * SPEED_OF_SOUND) / 2000000.0; // Divide by 2 for one-way distance
}

// Function to implement a 5-sample moving average filter
float moving_average(float new_value, float *buffer, int buffer_size, int *index) {
    buffer[*index] = new_value;
    *index = (*index + 1) % buffer_size;

    float sum = 0.0;
    for (int i = 0; i < buffer_size; i++) {
        sum += buffer[i];
    }
    return sum / buffer_size;
}

// Function to set the servo angle using pigpio
int set_servo_angle(float angle) {
    if (angle < 0.0 || angle > 180.0) {
        fprintf(stderr, "Error: Invalid angle. Angle must be between 0 and 180 degrees.\n");
        return -1;
    }

    // Map angle (0-180) to pulse width (1000-2000)
    int pulse_width = SERVO_MIN_PULSE_WIDTH + (int)((angle / 180.0) * SERVO_RANGE);

    int result = gpioServo(SERVO_PIN, pulse_width);
    if (result != 0) {
        fprintf(stderr, "Error: gpioServo failed with code %d\n", result);
        return -1;
    }
    return 0;
}

// Function to log data to a CSV file
int log_data(float distance, float angle) {
    FILE *fp = fopen("distance_log.csv", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open distance_log.csv for writing\n");
        return -1;
    }

    // Get current timestamp
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    // Write data to file
    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, distance, angle);

    // Flush the buffer to ensure data is written immediately
    fflush(fp);

    fclose(fp);
    return 0;
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Set PWM frequency for servo (optional, but recommended)
    gpioSetPWMfrequency(SERVO_PIN, 50); // 50 Hz

    // Initialize trigger pin to low
    gpioWrite(TRIGGER_PIN, 0);

    // Register callback function for echo pin
    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) != 0) {
        fprintf(stderr, "Error: gpioSetAlertFuncEx failed\n");
        gpioTerminate();
        return 1;
    }

    // Initialize servo to neutral position
    if (set_servo_angle(SERVO_NEUTRAL_ANGLE) != 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize moving average buffer
    float distance_buffer[5] = {0.0};
    int buffer_index = 0;

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        // Generate trigger pulse
        trigger_pulse();

        // Wait for a short period to allow the echo pulse to be measured
        gpioDelay(50); // 50 ms

        // Check if a new pulse has been received
        if (new_pulse) {
            new_pulse = 0; // Clear the flag

            // Calculate distance
            float distance = calculate_distance(pulse_width);

            // Validate distance
            if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
                distance = -1.0; // Invalid distance
                if (set_servo_angle(SERVO_NEUTRAL_ANGLE) != 0) {
                    fprintf(stderr, "Error setting servo to neutral angle after invalid distance.\n");
                }
            }

            // Apply moving average filter
            float filtered_distance = moving_average(distance, distance_buffer, 5, &buffer_index);

            // Calculate servo angle (linear mapping)
            float angle = 0.0;
            if (distance != -1.0) {
                angle = (distance - MIN_DISTANCE) / (MAX_DISTANCE - MIN_DISTANCE) * 180.0;
            }

            // Set servo angle
            if (set_servo_angle(angle) != 0) {
                fprintf(stderr, "Error setting servo angle.\n");
            }

            // Log data
            if (log_data(distance, angle) != 0) {
                fprintf(stderr, "Error logging data.\n");
            }
        } else {
            // No echo received, set servo to neutral and log -1.0
            if (set_servo_angle(SERVO_NEUTRAL_ANGLE) != 0) {
                fprintf(stderr, "Error setting servo to neutral angle after timeout.\n");
            }
            if (log_data(-1.0, SERVO_NEUTRAL_ANGLE) != 0) {
                fprintf(stderr, "Error logging data after timeout.\n");
            }
        }

        // Delay before next measurement
        gpioDelay(100); // 100 ms
    }

    // Stop the servo
    gpioServo(SERVO_PIN, 0);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

