#define VL53L1X_REG_PRE_RANGE_CONFIG_MMC_ENABLE 0x0010
#define VL53L1X_REG_FINAL_RANGE_CONFIG_MIN_COUNT_RATE_RTN_LIMIT 0x0014
#define VL53L1X_REG_SYSTEM_SEQUENCE_CONFIG 0x0081
#define VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR 0x0086
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0089
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0096

// Global Variables
int i2c_handle;
volatile sig_atomic_t program_running = 1;

// Circular Buffer Structure
typedef struct {
    int buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

// Function Prototypes
int init_vl53l1x();
int read_distance();
void add_to_buffer(CircularBuffer *cb, int value);
int get_average_distance(const CircularBuffer *cb);
void control_led(int state);
