#include <pigpio.h>
#include <stdbool.h>

// Constants
#define DEFAULT_I2C_ADDRESS 0x60
#define DEFAULT_THRESHOLD 1000
#define GPIO_PIN 27
#define I2C_BUS 1
#define PROXIMITY_REG 0x08 // Example register, adjust as needed
#define INTERRUPT_REG 0x02 // Example register, adjust as needed
#define LOG_FILE "proximity.log"

// Global variables
int i2c_handle;
FILE *log_file;
bool running = true;
int threshold = DEFAULT_THRESHOLD;
int i2c_address = DEFAULT_I2C_ADDRESS;

// Function prototypes
int initialize_i2c(int address);
int configure_sensor(int i2c_handle);
int read_proximity(int i2c_handle);
void handle_interrupt(int gpio, int level, uint32_t tick, void *user_data);
void log_data(int proximity_value, const char *status);
void signal_handler(int signal);
void cleanup();

// Function to initialize I2C
int initialize_i2c(int address) {
    i2c_handle = i2cOpen(I2C_BUS, address, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to configure the sensor
int configure_sensor(int i2c_handle) {
    // Example configuration: Enable interrupt on rising edge
    // Adjust register addresses and values as needed for Si1102
    if (i2cWriteByteData(i2c_handle, INTERRUPT_REG, 0x01) < 0) { // Example: Enable interrupt
        fprintf(stderr, "Error configuring sensor: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read proximity data
int read_proximity(int i2c_handle) {
    int proximity_value = i2cReadWordData(i2c_handle, PROXIMITY_REG);
    if (proximity_value < 0) {
        fprintf(stderr, "Error reading proximity data: %d\n", i2c_handle);
        return -1;
    }
    return proximity_value;
}

// Interrupt handler function
void handle_interrupt(int gpio, int level, uint32_t tick, void *user_data) {
    int proximity_value = read_proximity(i2c_handle);
    if (proximity_value >= 0) {
        const char *status = (proximity_value <= threshold) ? "SAFE" : "ALERT";
        log_data(proximity_value, status);
    }
}

// Function to log data to file
void log_data(int proximity_value, const char *status) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %d, %s\n", timestamp, proximity_value, status);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = false;
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    int opt;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "a:t:")) != -1) {
        switch (opt) {
            case 'a':
                i2c_address = strtol(optarg, NULL, 0); // Allow hex or decimal
                break;
            case 't':
                threshold = atoi(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-a i2c_address] [-t threshold]\n", argv[0]);
                return 1;
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c(i2c_address) != 0) {
        cleanup();
        return 1;
    }

    // Configure sensor
    if (configure_sensor(i2c_handle) != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return 1;
    }

    // Set GPIO mode and register interrupt handler
    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetAlertFuncEx(GPIO_PIN, handle_interrupt, NULL);

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Proximity sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        sleep(1); // Reduce CPU usage
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

