#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <math.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define PWM_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define MIN_DISTANCE 2.0       // Minimum measurable distance (cm)
#define MAX_DISTANCE 200.0     // Maximum measurable distance (cm)
#define MIN_FREQUENCY 200.0    // Minimum frequency (Hz)
#define MAX_FREQUENCY 2000.0   // Maximum frequency (Hz)
#define TIMEOUT_US 200000       // Timeout in microseconds (200ms)

// Global variables
static volatile int running = 1;
static double current_frequency = 0.0;

// Function prototypes
double measure_distance();
double distance_to_frequency(double distance);
void set_pwm_frequency(double frequency);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    running = 0;
    set_pwm_frequency(0.0); // Stop PWM
    gpioTerminate();       // Terminate pigpio
    exit(0);
}

// Function to measure distance using HC-SR04
double measure_distance() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);

    uint32_t start_tick = 0;
    uint32_t end_tick = 0;

    // Wait for echo to start (with timeout)
    int timeout_count = 0;
    while (gpioRead(ECHO_PIN) == 0 && timeout_count < TIMEOUT_US) {
        timeout_count++;
        gpioDelay(1); // Check every microsecond
    }

    if (timeout_count >= TIMEOUT_US) {
        fprintf(stderr, "Error: Echo start timeout\n");
        return -1.0; // Indicate timeout error
    }

    start_tick = gpioTick();

    // Wait for echo to end (with timeout)
    timeout_count = 0;
    while (gpioRead(ECHO_PIN) == 1 && timeout_count < TIMEOUT_US) {
        timeout_count++;
        gpioDelay(1);
    }

    if (timeout_count >= TIMEOUT_US) {
        fprintf(stderr, "Error: Echo end timeout\n");
        return -1.0; // Indicate timeout error
    }

    end_tick = gpioTick();

    uint32_t diff = end_tick - start_tick;

    // Calculate distance in centimeters
    double time_taken = (double)diff / 1000000.0; // Time in seconds
    double distance = (time_taken * SPEED_OF_SOUND) / 2.0;

    return distance;
}

// Function to convert distance to frequency
double distance_to_frequency(double distance) {
    // Clamp distance to the defined range
    if (distance < MIN_DISTANCE) {
        distance = MIN_DISTANCE;
    } else if (distance > MAX_DISTANCE) {
        distance = MAX_DISTANCE;
    }

    // Logarithmic mapping
    double frequency = MIN_FREQUENCY * pow((distance / MIN_DISTANCE), (MAX_FREQUENCY / MIN_FREQUENCY));

    return frequency;
}

// Function to set PWM frequency
void set_pwm_frequency(double frequency) {
    if (frequency > 0.0) {
        int range = 1000000 / frequency; // Calculate range for 50% duty cycle
        gpioSetPWMfrequency(PWM_PIN, (int)frequency);
        gpioSetPWMrange(PWM_PIN, range);
        gpioPWM(PWM_PIN, range / 2); // 50% duty cycle
    } else {
        gpioPWM(PWM_PIN, 0); // Stop PWM
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(PWM_PIN, PI_OUTPUT);

    // Set PWM range and frequency (initial values)
