#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Define constants
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000
#define CS_PIN 8
#define DISTANCE_MIN 200
#define DISTANCE_MAX 5000

// ICU-20201 Register Addresses (Example - Refer to datasheet for actual values)
#define WHO_AM_I 0x00
#define DISTANCE_MSB 0x01
#define DISTANCE_LSB 0x02
#define CONFIG_REG 0x03

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor configuration
typedef struct {
    int spi_channel;
    int spi_baud;
    int cs_pin;
    int distance_min;
    int distance_max;
} sensor_config_t;

// Function prototypes
int spi_read_register(int handle, uint8_t reg);
int spi_write_register(int handle, uint8_t reg, uint8_t value);
int read_distance(int handle);
int validate_distance(int distance);
int log_data(FILE *fp, int distance);
void signal_handler(int signal);
int initialize_sensor(int handle);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Function to read a register via SPI
int spi_read_register(int handle, uint8_t reg) {
    char tx[2], rx[2];
    tx[0] = reg | 0x80; // Set MSB for read operation
    tx[1] = 0x00;       // Dummy byte for reading

    if (spiXfer(handle, tx, rx, 2) != 0) {
        fprintf(stderr, "Error: SPI read failed for register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }

    return rx[1];
}

// Function to write a register via SPI
int spi_write_register(int handle, uint8_t reg, uint8_t value) {
    char tx[2], rx[2];
    tx[0] = reg & 0x7F; // Clear MSB for write operation
    tx[1] = value;

    if (spiXfer(handle, tx, rx, 2) != 0) {
        fprintf(stderr, "Error: SPI write failed for register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }

    return 0;
}

// Function to read the distance from the sensor
int read_distance(int handle) {
    int msb, lsb;

    msb = spi_read_register(handle, DISTANCE_MSB);
    if (msb < 0) return -1;

    lsb = spi_read_register(handle, DISTANCE_LSB);
    if (lsb < 0) return -1;

    return (msb << 8) | lsb;
}

// Function to validate the distance reading
int validate_distance(int distance) {
    if (distance < DISTANCE_MIN || distance > DISTANCE_MAX) {
        fprintf(stderr, "Error: Distance out of range: %d mm\n", distance);
        return -1;
    }
    return 0;
}

// Function to log the data to a file
int log_data(FILE *fp, int distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(fp, "%s,%d\n", timestamp, distance) < 0) {
        fprintf(stderr, "Error: Failed to write to log file: %s\n", strerror(errno));
        return -1;
    }
    fflush(fp); // Ensure data is written to disk immediately
    return 0;
}

// Function to initialize the sensor
int initialize_sensor(int handle) {
    // Example initialization sequence (Refer to datasheet for correct sequence)
    if (spi_write_register(handle, CONFIG_REG, 0x01) != 0) {
        fprintf(stderr, "Error: Failed to write to config register.\n");
        return -1;
    }
    gpioDelay(100000); // 100ms delay

    // Verify sensor ID (Example)
    int who_am_i = spi_read_register(handle, WHO_AM_I);
    if (who_am_i < 0) {
        fprintf(stderr, "Error: Failed to read WHO_AM_I register.\n");
        return -1;
    }
    if (who_am_i != 0x41) { // Expected value for ICU-20201
        fprintf(stderr, "Error: Incorrect WHO_AM_I value: 0x%02X\n", who_am_i);
        return -1;
    }

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed: %s\n", strerror(errno));
        return 1;
    }

    // Open SPI channel
