// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Function to read a register via SPI
int spi_read_register(int handle, uint8_t reg) {
    char tx[2], rx[2];
    tx[0] = reg | 0x80; // Set MSB for read operation
    tx[1] = 0x00;       // Dummy byte for reading

    if (spiXfer(handle, tx, rx, 2) != 0) {
        fprintf(stderr, "Error: SPI read failed for register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }

    return rx[1];
}

// Function to write a register via SPI
int spi_write_register(int handle, uint8_t reg, uint8_t value) {
    char tx[2], rx[2];
    tx[0] = reg & 0x7F; // Clear MSB for write operation
    tx[1] = value;

    if (spiXfer(handle, tx, rx, 2) != 0) {
        fprintf(stderr, "Error: SPI write failed for register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }

    return 0;
}

