#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SI1175_ADDR 0x60
#define ALS_VISIBLE_REG 0x22
#define LOG_FILE "proximity_log.csv"

// Global variables
int i2c_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_als_visible(uint16_t *als_visible);
int log_data(const char *timestamp, uint16_t als_visible);
void signal_handler(int signal);
char* get_iso8601_timestamp();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SI1175_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read ALS Visible value
int read_als_visible(uint16_t *als_visible) {
    char buf[2];
    int result = i2cReadI2CBlockData(i2c_handle, ALS_VISIBLE_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading ALS Visible: %d\n", result);
        return -1;
    }
    *als_visible = (buf[1] << 8) | buf[0];
    return 0;
}

// Log data to file
int log_data(const char *timestamp, uint16_t als_visible) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s,%u\n", timestamp, als_visible);
    fflush(log_file); // Ensure data is written immediately
    return 0;
}

// Get ISO 8601 timestamp
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    static char buffer[80];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(buffer, sizeof(buffer), "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return buffer;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,als_visible\n");
    }
    rewind(log_file);

    // Main loop
    while (!terminate) {
        uint16_t als_visible;
        if (read_als_visible(&als_visible) == 0) {
            char *timestamp = get_iso8601_timestamp();
            if (log_data(timestamp, als_visible) != 0) {
                fprintf(stderr, "Error logging data.\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data.\n");
        }

        sleep(5);
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

