#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Si1120 I2C address
#define SI1120_ADDR 0x60

// Si1120 register addresses
#define SI1120_REG_PART_ID 0x00
#define SI1120_REG_ALS_VIS_DATA0 0x10
#define SI1120_REG_PS1_DATA0 0x18
#define SI1120_REG_RESET 0x07
#define SI1120_REG_COMMAND 0x08

// Si1120 commands
#define SI1120_CMD_RESET 0x01

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int si1120_init();
int si1120_read_data(uint16_t *als, uint16_t *prox);
void log_data(uint16_t als, uint16_t prox);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        fprintf(stderr, "\nCaught SIGINT, exiting gracefully...\n");
        terminate = 1;
    }
}

// Function to initialize the Si1120 sensor
int si1120_init() {
    int retries = 3;
    int status;

    // Reset the sensor
    while (retries > 0) {
        status = i2cWriteByteData(i2c_handle, SI1120_REG_RESET, SI1120_CMD_RESET);
        if (status >= 0) break;
        fprintf(stderr, "Error resetting Si1120, retrying...\n");
        gpioDelay(10000); // 10ms delay
        retries--;
    }
    if (retries == 0) {
        fprintf(stderr, "Failed to reset Si1120 after multiple retries.\n");
        return -1;
    }
    gpioDelay(10000); // Wait for reset to complete

    // Verify Part ID
    retries = 3;
    while (retries > 0) {
        int part_id = i2cReadByteData(i2c_handle, SI1120_REG_PART_ID);
        if (part_id >= 0) {
            if (part_id == 0x20) {
                fprintf(stderr, "Si1120 Part ID verified (0x20).\n");
                return 0; // Initialization successful
            } else {
                fprintf(stderr, "Incorrect Part ID: 0x%02X\n", part_id);
                return -1;
            }
        } else {
            fprintf(stderr, "Error reading Part ID, retrying...\n");
            gpioDelay(10000); // 10ms delay
            retries--;
        }
    }
    fprintf(stderr, "Failed to read Part ID after multiple retries.\n");
    return -1;
}

// Function to read ALS and proximity data from the Si1120 sensor
int si1120_read_data(uint16_t *als, uint16_t *prox) {
    int retries = 3;
    int status;

    // Read ALS data
    while (retries > 0) {
        int als_low = i2cReadByteData(i2c_handle, SI1120_REG_ALS_VIS_DATA0);
        int als_high = i2cReadByteData(i2c_handle, SI1120_REG_ALS_VIS_DATA0 + 1);

        if (als_low >= 0 && als_high >= 0) {
            *als = (uint16_t)((als_high << 8) | als_low);
            break;
        } else {
            fprintf(stderr, "Error reading ALS data, retrying...\n");
            gpioDelay(10000); // 10ms delay
            retries--;
        }
    }
    if (retries == 0) {
        fprintf(stderr, "Failed to read ALS data after multiple retries.\n");
        return -1;
    }

    // Read proximity data
    retries = 3;
    while (retries > 0) {
        int prox_low = i2cReadByteData(i2c_handle, SI1120_REG_PS1_DATA0);
        int prox_high = i2cReadByteData(i2c_handle, SI1120_REG_PS1_DATA0 + 1);

        if (prox_low >= 0 && prox_high >= 0) {
            *prox = (uint16_t)((prox_high << 8) | prox_low);
            break;
        } else {
            fprintf(stderr, "Error reading proximity data, retrying...\n");
            gpioDelay(10000); // 10ms delay
            retries--;
        }
    }
    if (retries == 0) {
        fprintf(stderr, "Failed to read proximity data after multiple retries.\n");
        return -1;
    }

    return 0;
}

// Function to log data to a file
void log_data(uint16_t als, uint16_t prox) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, ALS: %u, Proximity: %u\n", timestamp, als, prox);
    fflush(log_file); // Ensure data is written to file immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, SI1120_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("si1120_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize Si1120 sensor
    if (si1120_init() != 0) {
        fprintf(stderr, "Si1120 initialization failed\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    uint16_t als, prox;

    // Main loop
    while (!terminate) {
        if (si1120_read_data(&als, &prox) == 0) {
            log_data(als, prox);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        gpioDelay(500000); // 500ms delay
    }

    // Close log file and I2C bus
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

