        int prox_high = i2cReadByteData(i2c_handle, SI1120_REG_PS1_DATA0 + 1);

        if (prox_low >= 0 && prox_high >= 0) {
            *prox = (uint16_t)((prox_high << 8) | prox_low);
            break;
        } else {
            fprintf(stderr, "Error reading proximity data, retrying...\n");
            gpioDelay(10000); // 10ms delay
            retries--;
        }
    }
    if (retries == 0) {
        fprintf(stderr, "Failed to read proximity data after multiple retries.\n");
        return -1;
    }

    return 0;
}

// Function to log data to a file
void log_data(uint16_t als, uint16_t prox) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, ALS: %u, Proximity: %u\n", timestamp, als, prox);
    fflush(log_file); // Ensure data is written to file immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, SI1120_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("si1120_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize Si1120 sensor
    if (si1120_init() != 0) {
        fprintf(stderr, "Si1120 initialization failed\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    uint16_t als, prox;

    // Main loop
    while (!terminate) {
        if (si1120_read_data(&als, &prox) == 0) {
            log_data(als, prox);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        gpioDelay(500000); // 500ms delay
    }

    // Close log file and I2C bus
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

