// Define the I2C device address and registers
#define I2C_DEVICE_ADDRESS 0x60
#define SI1182_PART_ID_REG 0x00
#define SI1182_MEAS_RATE_REG 0x08
#define SI1182_ALS_DATA_REG 0x22
#define SI1182_PS_DATA_REG 0x24

// Define the expected part ID value
#define SI1182_EXPECTED_PART_ID 0x82

// Global variables for I2C file descriptor and log file
int i2c_fd = -1;
FILE *log_file = NULL;

// Function prototypes
int i2c_write_byte(int fd, uint8_t reg, uint8_t value);
int i2c_read_byte(int fd, uint8_t reg, uint8_t *value);
int i2c_read_block(int fd, uint8_t reg, uint8_t *data, int len);
int si1182_init(int fd);
int read_sensor_data(int fd, float *lux, uint16_t *proximity);
void log_data(FILE *fp, float lux, uint16_t proximity);
void signal_handler(int signum);

// I2C write function
int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

// I2C read function
int i2c_read_byte(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        perror("I2C write (register select) failed");
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        perror("I2C read failed");
        return -1;
    }
    return 0;
}

// I2C read block function
int i2c_read_block(int fd, uint8_t reg, uint8_t *data, int len) {
    if (write(fd, &reg, 1) != 1) {
        perror("I2C write (register select) failed");
        return -1;
    }
    if (read(fd, data, len) != len) {
        perror("I2C read block failed");
        return -1;
    }
    return 0;
}

// Si1182 initialization function
int si1182_init(int fd) {
    uint8_t part_id;

    // Verify the sensor part ID
    if (i2c_read_byte(fd, SI1182_PART_ID_REG, &part_id) != 0) {
        fprintf(stderr, "Error reading part ID\n");
        return -1;
    }

    if (part_id != SI1182_EXPECTED_PART_ID) {
        fprintf(stderr, "Incorrect part ID: 0x%02X (expected 0x%02X)\n", part_id, SI1182_EXPECTED_PART_ID);
        return -1;
    }

    // Configure the measurement rate register
    if (i2c_write_byte(fd, SI1182_MEAS_RATE_REG, 0x0A) != 0) {
        fprintf(stderr, "Error writing to measurement rate register\n");
        return -1;
    }

    return 0;
}

