    uint8_t als_data[2];
    uint8_t ps_data[2];

    // Read ambient light data
    if (i2c_read_block(fd, SI1182_ALS_DATA_REG, als_data, 2) != 0) {
        fprintf(stderr, "Error reading ALS data\n");
        return -1;
    }

    // Read proximity data
    if (i2c_read_block(fd, SI1182_PS_DATA_REG, ps_data, 2) != 0) {
        fprintf(stderr, "Error reading proximity data\n");
        return -1;
    }

    // Convert the raw data to lux and proximity values
    *lux = (float)((als_data[1] << 8) | als_data[0]) / 100.0; // Example conversion, adjust as needed
    *proximity = (uint16_t)((ps_data[1] << 8) | ps_data[0]);

    return 0;
}

