    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    // Log to file
    fprintf(fp, "%s,%.2f,%u\n", timestamp, lux, proximity);
    fflush(fp); // Ensure data is written to disk immediately

    // Print to stdout
    printf("%s,%.2f,%u\n", timestamp, lux, proximity);
}

// Signal handler function
void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        printf("Received signal %d, closing resources...\n", signum);

        // Close I2C file descriptor
        if (i2c_fd != -1) {
            close(i2c_fd);
        }

        // Close log file
        if (log_file != NULL) {
            fclose(log_file);
        }

        exit(0);
    }
}

int main() {
    float lux;
    uint16_t proximity;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set the I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_DEVICE_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Initialize the Si1182 sensor
    if (si1182_init(i2c_fd) != 0) {
        fprintf(stderr, "Si1182 initialization failed\n");
        close(i2c_fd);
        return 1;
    }

    // Open the log file
    log_file = fopen("biometric_log.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        // Read sensor data
