            // Log the data
            log_data(log_file, lux, proximity);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        // Wait for 100ms
        usleep(100000); // 100ms = 100000 microseconds
    }

    return 0;
}

