#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define BUZZER_PIN 27

// Constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define DISTANCE_THRESHOLD 20.0 // Distance threshold in cm
#define TRIGGER_PULSE_WIDTH 10 // Trigger pulse width in microseconds

// Global variables
volatile uint32_t start_tick = 0;
volatile uint32_t end_tick = 0;
volatile int echo_received = 0;
volatile double distance = 0.0;

// Function prototypes
void trigger_pulse();
void echo_callback(int gpio, int level, uint32_t tick);
double calculate_distance(uint32_t pulse_width);
void set_buzzer_state(int state);
void print_distance();
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    gpioTerminate();
    exit(0);
}

// Function to generate a trigger pulse
void trigger_pulse() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(TRIGGER_PULSE_WIDTH);
    gpioWrite(TRIGGER_PIN, 0);
}

// Callback function for echo pin
void echo_callback(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        // Rising edge
        start_tick = tick;
        echo_received = 1; // Indicate that a rising edge has been received
    } else if (level == 0 && echo_received == 1) {
        // Falling edge
        end_tick = tick;
        echo_received = 0; // Reset the flag

        // Calculate pulse width
        uint32_t pulse_width = end_tick - start_tick;

        // Calculate distance
        distance = calculate_distance(pulse_width);
    }
}

// Function to calculate distance from pulse width
double calculate_distance(uint32_t pulse_width) {
    return (double)pulse_width * SPEED_OF_SOUND / 2000000.0; // Convert pulse_width to seconds and divide by 2
}

// Function to set the buzzer state
void set_buzzer_state(int state) {
    gpioWrite(BUZZER_PIN, state);
}

// Function to print the distance
void print_distance() {
    printf("Distance: %.2f cm\n", distance);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    // Set pull-down resistor for echo pin
    gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN);

    // Set alert function for echo pin
    gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL);

    // Set signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        // Generate trigger pulse
        trigger_pulse();

        // Wait for a short period
        gpioDelay(50000); // 50ms

        // Calculate distance in cm
        double distance_cm = distance;

        // Set buzzer state based on distance
        if (distance_cm < DISTANCE_THRESHOLD) {
            set_buzzer_state(1); // Turn buzzer on
        } else {
            set_buzzer_state(0); // Turn buzzer off
        }

        // Print distance
        print_distance();
    }

    // This point will not be reached due to the infinite loop
    gpioTerminate();
    return 0;
}

