#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 4
#define ECHO_PIN 17
#define SERVO_PIN 18

// Constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define TIMEOUT_US 50000        // 50ms timeout for echo pulse

// Global variable for graceful shutdown
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    printf("\nCaught signal, exiting gracefully...\n");
}

// Function to measure distance using HC-SR04
float measure_distance() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);

    uint32_t start_tick = 0;
    uint32_t end_tick = 0;

    // Wait for echo to start (rising edge)
    int timeout = 0;
    while (gpioRead(ECHO_PIN) == 0 && timeout < TIMEOUT_US) {
        timeout++;
        gpioDelay(1); // Check every microsecond
    }

    if (timeout >= TIMEOUT_US) {
        fprintf(stderr, "Error: Echo pulse timeout (rising edge)\n");
        return -1.0; // Indicate timeout error
    }

    start_tick = gpioTick();

    // Wait for echo to end (falling edge)
    timeout = 0;
    while (gpioRead(ECHO_PIN) == 1 && timeout < TIMEOUT_US) {
        timeout++;
        gpioDelay(1); // Check every microsecond
    }

    if (timeout >= TIMEOUT_US) {
        fprintf(stderr, "Error: Echo pulse timeout (falling edge)\n");
        return -1.0; // Indicate timeout error
    }

    end_tick = gpioTick();

    uint32_t pulse_width = end_tick - start_tick;

    // Calculate distance in centimeters
    float distance = (pulse_width / 1000000.0) * SPEED_OF_SOUND / 2.0;

    return distance;
}

// Function to set servo angle
void set_servo_angle(int angle) {
    if (angle < 0) angle = 0;
    if (angle > 180) angle = 180;

