// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int init_vl53l1x();
int read_distance();
void set_servo_pulse_width(int pulse_width);
void log_event(const char *event);
void signal_handler(int signal);

// Signal handler
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize VL53L1X sensor
int init_vl53l1x() {
    // Example initialization sequence (replace with actual sequence from datasheet)
    if (i2cWriteByteData(i2c_handle, 0x00, 0x01) < 0) { // Example register and value
        fprintf(stderr, "Error writing to VL53L1X: %s\n", strerror(errno));
        return -1;
    }
    gpioDelay(1000); // Delay in microseconds

    if (i2cWriteByteData(i2c_handle, 0x01, 0x02) < 0) { // Example register and value
        fprintf(stderr, "Error writing to VL53L1X: %s\n", strerror(errno));
        return -1;
    }
    gpioDelay(1000); // Delay in microseconds

    // Verify model ID (example)
    int model_id = i2cReadByteData(i2c_handle, 0xC0); // Example register
    if (model_id < 0) {
        fprintf(stderr, "Error reading model ID from VL53L1X: %s\n", strerror(errno));
        return -1;
    }
    if (model_id != 0xEACC) { // Expected model ID (example)
        fprintf(stderr, "Incorrect model ID: 0x%X\n", model_id);
        return -1;
    }

    // Set timing budget (example)
    if (i2cWriteByteData(i2c_handle, 0x08, 0x0A) < 0) { // Example register and value
        fprintf(stderr, "Error writing timing budget to VL53L1X: %s\n", strerror(errno));
        return -1;
    }
    gpioDelay(1000); // Delay in microseconds

    return 0;
}

// Read distance from VL53L1X sensor
int read_distance() {
    int distance = i2cReadWordData(i2c_handle, DISTANCE_REG);
    if (distance < 0) {
        fprintf(stderr, "Error reading distance from VL53L1X: %s\n", strerror(errno));
        return -1;
    }
    return distance;
}

