        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (init_vl53l1x() != 0) {
        fprintf(stderr, "VL53L1X initialization failed\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set servo pin as output
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Set PWM range and frequency
    gpioSetPWMrange(SERVO_PIN, PWM_RANGE);
    gpioSetPWMfrequency(SERVO_PIN, PWM_FREQUENCY);

    // Register signal handler
    signal(SIGINT, signal_handler);

    int distance;
    int pulse_width = 1500; // Initial pulse width
    int last_pulse_width = 1500;

    // Main loop
    while (program_running) {
        distance = read_distance();
        if (distance > 0) {
            if (distance > DISTANCE_THRESHOLD_OPEN) {
                pulse_width = 2000;
                log_event("Gate opened");
            } else if (distance < DISTANCE_THRESHOLD_CLOSE) {
                pulse_width = 1000;
                log_event("Gate closed");
            } else {
                // Smooth transition
                if (distance > DISTANCE_THRESHOLD_CLOSE + 50) {
                    pulse_width = 1500 + (2000 - 1500) * (distance - DISTANCE_THRESHOLD_CLOSE) / (DISTANCE_THRESHOLD_OPEN - DISTANCE_THRESHOLD_CLOSE);
                } else if (distance < DISTANCE_THRESHOLD_CLOSE - 50) {
                    pulse_width = 1500 + (1000 - 1500) * (distance - DISTANCE_THRESHOLD_OPEN) / (DISTANCE_THRESHOLD_CLOSE - DISTANCE_THRESHOLD_OPEN);
                } else {
                    pulse_width = 1500;
                }
            }

            // Set servo pulse width
            set_servo_pulse_width(pulse_width);

            // Hysteresis
            if (pulse_width != last_pulse_width) {
                gpioDelay(50000); // 50ms delay
                last_pulse_width = pulse_width;
            }
        } else {
            fprintf(stderr, "Failed to read distance. Retrying...\n");
        }

        gpioDelay(100000); // 100ms delay
    }

    // Cleanup
    set_servo_pulse_width(1500); // Set to neutral position
    gpioDelay(500000); // 500ms delay
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

