#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <time.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define SERVO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define MIN_DISTANCE 2.0       // cm
#define MAX_DISTANCE 400.0     // cm
#define MIN_PULSE_WIDTH 500.0  // us
#define MAX_PULSE_WIDTH 2500.0 // us
#define MIN_ANGLE 0.0
#define MAX_ANGLE 180.0

// Global variables
volatile sig_atomic_t program_running = 1;

// Function prototypes
void triggerSensor();
long pulseIn(int pin, int level, int timeout);
float calculateDistance(long pulseWidth);
float mapDistanceToAngle(float distance);
void setServoAngle(float angle);
void signalHandler(int signal);

// Signal handler function
void signalHandler(int signal) {
    if (signal == SIGINT) {
        printf("\nCtrl+C detected. Stopping servo and exiting.\n");
        program_running = 0;
        setServoAngle(0.0); // Stop the servo
        gpioTerminate();     // Terminate pigpio
        exit(0);
    }
}

// Function to trigger the ultrasonic sensor
void triggerSensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to measure the pulse width on the echo pin
long pulseIn(int pin, int level, int timeout) {
    long startTime = 0, endTime = 0;
    long pulseWidth = 0;
    int count = 0;

    // Wait for the pulse to start
    while (gpioRead(pin) != level) {
        startTime = time_time();
        if (startTime < 0) return -1; // Error getting time
        if (startTime > timeout) return -1; // Timeout
        count++;
        if (count > 100000) return -1; // Avoid infinite loop
    }

    startTime = time_time();
    if (startTime < 0) return -1; // Error getting time

    // Wait for the pulse to end
    while (gpioRead(pin) == level) {
        endTime = time_time();
        if (endTime < 0) return -1; // Error getting time
        if (endTime - startTime > timeout) return -1; // Timeout
        count++;
        if (count > 100000) return -1; // Avoid infinite loop
    }

    endTime = time_time();
    if (endTime < 0) return -1; // Error getting time

    pulseWidth = endTime - startTime;
    return pulseWidth;
}

// Function to calculate the distance in centimeters
float calculateDistance(long pulseWidth) {
    if (pulseWidth < 0) return -1.0; // Timeout
    if (pulseWidth == 0) return 0.0;  // Avoid division by zero
    return (float)pulseWidth * SPEED_OF_SOUND / 2000000.0; // cm
}

// Function to map the distance to a servo angle
float mapDistanceToAngle(float distance) {
    if (distance < MIN_DISTANCE) {
        return MIN_ANGLE;
    } else if (distance > MAX_DISTANCE) {
        return MAX_ANGLE;
    } else {
        return MIN_ANGLE + (distance - MIN_DISTANCE) * (MAX_ANGLE - MIN_ANGLE) / (MAX_DISTANCE - MIN_DISTANCE);
    }
}

// Function to set the servo angle using pigpio
void setServoAngle(float angle) {
    if (angle < MIN_ANGLE) {
        angle = MIN_ANGLE;
    } else if (angle > MAX_ANGLE) {
        angle = MAX_ANGLE;
    }

    float pulseWidth = MIN_PULSE_WIDTH + (angle - MIN_ANGLE) * (MAX_PULSE_WIDTH - MIN_PULSE_WIDTH) / (MAX_ANGLE - MIN_ANGLE);
    gpioServo(SERVO_PIN, (int)pulseWidth);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Set signal handler for Ctrl+C
    signal(SIGINT, signalHandler);

    printf("Ultrasonic sensor and servo control program\n");
    printf("Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Trigger the sensor
        triggerSensor();

        // Measure the pulse width
        long pulseWidth = pulseIn(ECHO_PIN, 1, 50000); // 50 ms timeout

        // Calculate the distance
        float distance = calculateDistance(pulseWidth);

        // Map the distance to a servo angle
        float angle = mapDistanceToAngle(distance);

        // Set the servo angle
        setServoAngle(angle);

        // Print the distance and angle
        printf("Distance: %.2f cm, Angle: %.2f degrees\n", distance, angle);

        // Wait 100 ms
        gpioDelay(100000);
    }

    // Clean up
    gpioTerminate();
    return 0;
}

