#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>

// Si7005 I2C address
#define SI7005_ADDR 0x40

// Si7005 register addresses
#define SI7005_TEMP_REG 0x00
#define SI7005_HUMID_REG 0x01
#define SI7005_CONFIG_REG 0x06

// I2C bus
#define I2C_BUS 1

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_sensor_data(float *temperature, float *humidity);
void log_data(float temperature, float humidity);
void signal_handler(int signal);
void cleanup();

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Function to initialize the I2C bus
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SI7005_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read temperature and humidity data from the sensor
int read_sensor_data(float *temperature, float *humidity) {
    char buf[2];
    int result;

    // Write CONFIG register (e.g., 0x00 for default settings)
    result = i2cWriteByteData(i2c_handle, SI7005_CONFIG_REG, 0x00);
    if (result < 0) {
        fprintf(stderr, "Error writing to CONFIG register: %d\n", result);
        return -1;
    }
    gpioDelay(10); // Wait 10ms

    // Read temperature data
    result = i2cReadI2CBlockData(i2c_handle, SI7005_TEMP_REG, buf, 2);
    if (result < 0) {
        fprintf(stderr, "Error reading temperature data: %d\n", result);
        return -1;
    }
    uint16_t raw_temp = (buf[0] << 8) | buf[1];
    *temperature = (175.72 * raw_temp / 65536.0) - 46.85;

    // Write HUMIDITY register
    result = i2cWriteByteData(i2c_handle, SI7005_HUMID_REG, 0x00);
    if (result < 0) {
        fprintf(stderr, "Error writing to HUMIDITY register: %d\n", result);
        return -1;
    }
    gpioDelay(10); // Wait 10ms

    // Read humidity data
    result = i2cReadI2CBlockData(i2c_handle, SI7005_HUMID_REG, buf, 2);
    if (result < 0) {
        fprintf(stderr, "Error reading humidity data: %d\n", result);
        return -1;
    }
    uint16_t raw_humidity = (buf[0] << 8) | buf[1];
    *humidity = (125.0 * raw_humidity / 65536.0) - 6.0;

    return 0;
}

// Function to log the temperature and humidity data
void log_data(float temperature, float humidity) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s - Temperature: %.2f C, Humidity: %.2f %%\n", timestamp, temperature, humidity);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function to close I2C and terminate pigpio
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        if (read_sensor_data(&sensor_data.temperature, &sensor_data.humidity) == 0) {
            log_data(sensor_data.temperature, sensor_data.humidity);
        } else {
            fprintf(stderr, "Error reading sensor data, attempting to re-initialize I2C...\n");
            i2cClose(i2c_handle);
            if (init_i2c() != 0) {
                fprintf(stderr, "Failed to re-initialize I2C, exiting.\n");
                terminate = 1; // Exit loop if re-initialization fails
            }
        }

        gpioDelay(2000); // Wait 2 seconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

