#include <pigpio.h>

// MPU6050 I2C address
#define MPU6050_ADDR 0x68

// MPU6050 registers
#define MPU6050_WHO_AM_I 0x75
#define MPU6050_ACCEL_XOUT_H 0x3B
#define MPU6050_GYRO_XOUT_H 0x43

// Sensitivity scales
#define ACCEL_SCALE 16384.0f // +/- 2g
#define GYRO_SCALE 131.0f    // +/- 250 deg/s

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    terminate = 1;
}

// Function to read a single byte from an I2C register
int read_register(int handle, uint8_t reg) {
    int value = i2cReadByteData(handle, reg);
    if (value < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, value);
        return -1;
    }
    return value;
}

// Function to write a single byte to an I2C register
int write_register(int handle, uint8_t reg, uint8_t value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Function to read raw sensor data
int read_sensor_data(int handle, int16_t *accel_x, int16_t *accel_y, int16_t *accel_z, int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z) {
    char buffer[14];
    int result = i2cReadI2CBlockData(handle, MPU6050_ACCEL_XOUT_H, buffer, 14);
    if (result < 0) {
        fprintf(stderr, "Error reading sensor data: %d\n", result);
        return -1;
    }

    *accel_x = (int16_t)((buffer[0] << 8) | buffer[1]);
    *accel_y = (int16_t)((buffer[2] << 8) | buffer[3]);
    *accel_z = (int16_t)((buffer[4] << 8) | buffer[5]);
    *gyro_x = (int16_t)((buffer[8] << 8) | buffer[9]);
    *gyro_y = (int16_t)((buffer[10] << 8) | buffer[11]);
    *gyro_z = (int16_t)((buffer[12] << 8) | buffer[13]);

    return 0;
}

// Function to convert raw data to physical units
void convert_data(int16_t accel_x, int16_t accel_y, int16_t accel_z, int16_t gyro_x, int16_t gyro_y, int16_t gyro_z, float *accel_x_g, float *accel_y_g, float *accel_z_g, float *gyro_x_dps, float *gyro_y_dps, float *gyro_z_dps) {
    *accel_x_g = (float)accel_x / ACCEL_SCALE;
    *accel_y_g = (float)accel_y / ACCEL_SCALE;
    *accel_z_g = (float)accel_z / ACCEL_SCALE;
    *gyro_x_dps = (float)gyro_x / GYRO_SCALE;
    *gyro_y_dps = (float)gyro_y / GYRO_SCALE;
    *gyro_z_dps = (float)gyro_z / GYRO_SCALE;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Verify sensor presence
    int who_am_i = read_register(i2c_handle, MPU6050_WHO_AM_I);
    if (who_am_i != 0x68) {
        fprintf(stderr, "MPU6050 not found. WHO_AM_I returned 0x%02X\n", who_am_i);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("MPU6050 sensor data logger started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int16_t accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z;
        float accel_x_g, accel_y_g, accel_z_g, gyro_x_dps, gyro_y_dps, gyro_z_dps;

        if (read_sensor_data(i2c_handle, &accel_x, &accel_y, &accel_z, &gyro_x, &gyro_y, &gyro_z) == 0) {
            convert_data(accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z, &accel_x_g, &accel_y_g, &accel_z_g, &gyro_x_dps, &gyro_y_dps, &gyro_z_dps);

            printf("Accel: X=%.2f g, Y=%.2f g, Z=%.2f g | Gyro: X=%.2f deg/s, Y=%.2f deg/s, Z=%.2f deg/s\n",
                   accel_x_g, accel_y_g, accel_z_g, gyro_x_dps, gyro_y_dps, gyro_z_dps);
        } else {
            fprintf(stderr, "Failed to read sensor data. Retrying...\n");
        }

        gpioDelay(100); // 100ms delay
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();

    printf("MPU6050 sensor data logger stopped.\n");

    return 0;
}

