#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <string.h>

// SHT40 I2C address
#define SHT40_ADDR 0x44

// Measurement command (High Repeatability)
#define MEASURE_CMD 0xFD

// CRC-8 polynomial
#define CRC8_POLYNOMIAL 0x31

// CRC-8 initial value
#define CRC8_INIT 0xFF

// I2C bus
#define I2C_BUS 1

// Global variables for graceful shutdown
static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

// CRC-8 lookup table
static uint8_t crc8_table[256];

// Function prototypes
int init_crc8();
uint8_t calculate_crc8(const uint8_t *data, size_t len);
int read_sht40(int i2c_handle, float *temperature, float *humidity);
void log_data(float temperature, float humidity);
void signal_handler(int signal);

// CRC-8 initialization function
int init_crc8() {
    for (int i = 0; i < 256; i++) {
        uint8_t crc = i;
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
        crc8_table[i] = crc;
    }
    return 0;
}

// CRC-8 calculation function
uint8_t calculate_crc8(const uint8_t *data, size_t len) {
    uint8_t crc = CRC8_INIT;
    for (size_t i = 0; i < len; i++) {
        crc = crc8_table[crc ^ data[i]];
    }
    return crc;
}

// Function to read temperature and humidity from SHT40
int read_sht40(int i2c_handle, float *temperature, float *humidity) {
    uint8_t cmd = MEASURE_CMD;
    uint8_t data[6];

    // Send measurement command
    if (i2cWriteDevice(i2c_handle, &cmd, 1) != 0) {
