FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_sensor_data(float *ambient_temp, float *object_temp);
int log_data(float ambient_temp, float object_temp);
void signal_handler(int signal);

