int log_data(float ambient_temp, float object_temp) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        return -1;
    }

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, ambient_temp, object_temp);
    fclose(log_file);

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    float ambient_temp, object_temp;

    // Main loop
    while (!terminate) {
        if (read_sensor_data(&ambient_temp, &object_temp) == 0) {
            if (log_data(ambient_temp, object_temp) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        gpioSleep(PI_TIME_RELATIVE, 5, 0); // Sleep for 5 seconds
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

