#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define STS30_ADDR 0x4A
#define MEASURE_CMD 0x2C06
#define LOG_FILE "enclosure_temp_log.txt"
#define ERROR_LOG_FILE "error_log.txt"
#define SAMPLE_INTERVAL_SEC 5

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
float read_temperature();
void log_temperature(float temperature);
void log_error(const char *message);
void signal_handler(int signal);
int setup();
void cleanup();

// Structure to hold sensor data (optional)
typedef struct {
    float temperature;
    time_t timestamp;
} sensor_data_t;

// Function to read temperature from the sensor
float read_temperature() {
    char cmd[2] = {(MEASURE_CMD >> 8) & 0xFF, MEASURE_CMD & 0xFF};
    char buffer[6];
    int result;

    result = i2cWriteDevice(i2c_handle, cmd, 2);
    if (result != 0) {
        log_error("Failed to write measurement command to I2C.");
        return -1000.0; // Indicate error
    }

    gpioDelay(10); // Wait for measurement (datasheet specifies 10ms)

    result = i2cReadDevice(i2c_handle, buffer, 6);
    if (result != 6) {
        log_error("Failed to read temperature data from I2C.");
        return -1000.0; // Indicate error
    }

    // Convert raw data to temperature (Celsius)
    unsigned int raw_temperature = (buffer[0] << 8) | buffer[1];
    float temperature = -45.0 + (175.0 * raw_temperature) / 65535.0;

    return temperature;
}

// Function to log temperature to a file
void log_temperature(float temperature) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        log_error("Failed to open log file.");
        return;
    }

    fprintf(fp, "%s, %.2f\n", timestamp, temperature);
    fclose(fp);
}

// Function to log errors to a file
void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    FILE *fp = fopen(ERROR_LOG_FILE, "a");
    if (fp == NULL) {
        perror("Failed to open error log file"); // Use perror for system errors
        return;
    }

    fprintf(fp, "%s, %s\n", timestamp, message);
    fclose(fp);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Setup function to initialize pigpio and I2C
int setup() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, STS30_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Cleanup function to close I2C and terminate pigpio
void cleanup() {
    i2cClose(i2c_handle);
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (setup() != 0) {
        return 1;
    }

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        float temperature = read_temperature();

        if (temperature > -999.0) { // Check for valid temperature reading
            log_temperature(temperature);
            printf("Temperature: %.2f °C\n", temperature);
        } else {
            log_error("Failed to read temperature.");
        }

        sleep(SAMPLE_INTERVAL_SEC);
    }

    cleanup();
    printf("Temperature monitoring stopped.\n");
    return 0;
}

