int configure_sensor();
int read_sensor_data(uint8_t *data);
uint8_t calculate_crc8(const uint8_t *data, size_t len);
int validate_crc8(const uint8_t *data, size_t len);
int convert_data(const uint8_t *data, sensor_data_t *sensor_data);
int log_data(const sensor_data_t *sensor_data);
void signal_handler(int signal);
void cleanup();

// CRC-8 calculation function
uint8_t calculate_crc8(const uint8_t *data, size_t len) {
    uint8_t crc = CRC8_INIT;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// CRC-8 validation function
int validate_crc8(const uint8_t *data, size_t len) {
    uint8_t crc = calculate_crc8(data, len - 1);
    return (crc == data[len - 1]);
}

