    struct tm *info;
    char timestamp[30];
    time(&rawtime);
    info = gmtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", info);

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, sensor_data->pressure, sensor_data->temperature);
    fclose(fp);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources
