// Constants
#define I2C_BUS 1
#define SHT40_ADDR 0x44
#define MEASURE_HIGH_REPEATABILITY 0xFD
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INITIAL_VALUE 0xFF
#define LOG_FILE "sht40_log.txt"
#define MEASUREMENT_DELAY_MS 10
#define LOG_INTERVAL_S 5

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_sensor_data(uint16_t *temperature, uint16_t *humidity);
uint8_t calculate_crc(const uint8_t *data, size_t len);
int validate_data(const uint8_t *data);
int log_data(float temperature, float humidity);
void signal_handler(int signal);
void cleanup();

// CRC-8 calculation function
uint8_t calculate_crc(const uint8_t *data, size_t len) {
    uint8_t crc = CRC8_INITIAL_VALUE;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Data validation function
int validate_data(const uint8_t *data) {
    uint8_t temp_crc = calculate_crc(data, 2);
    uint8_t hum_crc = calculate_crc(data + 3, 2);

    if (temp_crc != data[2] || hum_crc != data[5]) {
        fprintf(stderr, "CRC validation failed!\n");
        return -1;
    }
    return 0;
}

// I2C initialization function
int init_i2c() {
    i2c_fd = i2cOpen(I2C_BUS, SHT40_ADDR, 0);
