        fprintf(stderr, "Error opening I2C device: %d\n", i2c_fd);
        return -1;
    }
    return 0;
}

// Function to read sensor data
int read_sensor_data(uint16_t *temperature, uint16_t *humidity) {
    char cmd = MEASURE_HIGH_REPEATABILITY;
    char buffer[6];

    if (i2cWriteDevice(i2c_fd, &cmd, 1) != 0) {
        fprintf(stderr, "Error writing to I2C device\n");
        return -1;
    }

    gpioDelay(MEASUREMENT_DELAY_MS * 1000); // Delay in microseconds

    if (i2cReadDevice(i2c_fd, buffer, 6) != 6) {
        fprintf(stderr, "Error reading from I2C device\n");
        return -1;
    }

    *temperature = (buffer[0] << 8) | buffer[1];
    *humidity = (buffer[3] << 8) | buffer[4];

    return 0;
