    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    uint16_t raw_temperature, raw_humidity;
    float temperature, humidity;

    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&raw_temperature, &raw_humidity) == 0) {
            // Convert raw data to temperature and humidity
            temperature = -45.0 + 175.0 * (float)raw_temperature / 65535.0;
            humidity = -6.0 + 125.0 * (float)raw_humidity / 65535.0;

            // Validate data
            if (validate_data((uint8_t *)&raw_temperature) == 0 && validate_data((uint8_t *)&raw_humidity + 3) == 0) {
                // Log data
                if (log_data(temperature, humidity) != 0) {
                    fprintf(stderr, "Error logging data\n");
                }
            } else {
                fprintf(stderr, "Data validation failed, skipping logging\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        sleep(LOG_INTERVAL_S);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

