#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <fcntl.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define SDP800_I2C_ADDRESS 0x25
#define MEASURE_COMMAND 0x362F
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INITIAL_VALUE 0xFF
#define DATA_BUFFER_SIZE 9
#define SLEEP_MS 100
#define RETRY_COUNT 3

// Global variables
static int i2c_fd = -1;
static FILE *data_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int16_t pressure;
    int16_t temperature;
    int16_t scale_factor;
} sensor_data_t;

// Function prototypes
int i2c_init(const char *bus, int address);
int i2c_write(int fd, uint16_t command);
int i2c_read(int fd, uint8_t *data, int len);
uint8_t crc8(const uint8_t *data, int len);
int validate_crc(const uint8_t *data, int len);
int read_sensor_data(int fd, sensor_data_t *data);
float convert_pressure(int16_t raw_pressure, int16_t scale_factor);
float convert_temperature(int16_t raw_temperature, int16_t scale_factor);
int log_data(FILE *fp, float pressure, float temperature);
void signal_handler(int sig);
void cleanup();

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = CRC8_INITIAL_VALUE;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// CRC-8 validation function
int validate_crc(const uint8_t *data, int len) {
    uint8_t crc = crc8(data, len - 1);
    return (crc == data[len - 1]);
}

// I2C initialization function
int i2c_init(const char *bus, int address) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, address) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// I2C write function
int i2c_write(int fd, uint16_t command) {
    uint8_t data[2];
    data[0] = (command >> 8) & 0xFF;
    data[1] = command & 0xFF;

    if (write(fd, data, 2) != 2) {
        perror("Error writing to I2C device");
        return -1;
    }

    return 0;
}

// I2C read function
int i2c_read(int fd, uint8_t *data, int len) {
    if (read(fd, data, len) != len) {
        perror("Error reading from I2C device");
        return -1;
    }

    return 0;
}

// Read sensor data function
int read_sensor_data(int fd, sensor_data_t *data) {
    uint8_t buffer[DATA_BUFFER_SIZE];

    if (i2c_read(fd, buffer, DATA_BUFFER_SIZE) != 0) {
        return -1;
    }

    if (!validate_crc(buffer, 3) || !validate_crc(buffer + 3, 3) || !validate_crc(buffer + 6, 3)) {
        fprintf(stderr, "CRC validation failed\n");
        return -1;
    }

    data->pressure = (int16_t)((buffer[0] << 8) | buffer[1]);
    data->temperature = (int16_t)((buffer[3] << 8) | buffer[4]);
    data->scale_factor = (int16_t)((buffer[6] << 8) | buffer[7]);

    return 0;
}

// Convert raw pressure to Pascal
float convert_pressure(int16_t raw_pressure, int16_t scale_factor) {
    return (float)raw_pressure / scale_factor;
}

// Convert raw temperature to Celsius
float convert_temperature(int16_t raw_temperature, int16_t scale_factor) {
    return (float)raw_temperature / scale_factor;
}

// Log data to file function
int log_data(FILE *fp, float pressure, float temperature) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(fp, "%s,%.2f,%.2f\n", timestamp, pressure, temperature) < 0) {
        perror("Error writing to data file");
        return -1;
    }

    return 0;
}

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received (%d). Terminating...\n", sig);
    terminate = 1;
}

// Cleanup function
void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (data_file != NULL) {
        fclose(data_file);
    }
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_fd = i2c_init(I2C_BUS, SDP800_I2C_ADDRESS);
    if (i2c_fd < 0) {
        fprintf(stderr, "I2C initialization failed. Exiting.\n");
        return 1;
    }

    // Send measurement command
    if (i2c_write(i2c_fd, MEASURE_COMMAND) != 0) {
        fprintf(stderr, "Failed to send measurement command. Exiting.\n");
        cleanup();
        return 1;
    }

    // Open data file
    data_file = fopen("airflow_data.txt", "a");
    if (data_file == NULL) {
        perror("Error opening data file");
        cleanup();
        return 1;
    }

    // Write header if the file is newly created
    fseek(data_file, 0, SEEK_END);
    long file_size = ftell(data_file);
    if (file_size == 0) {
        fprintf(data_file, "Timestamp,Pressure(Pa),Temperature(C)\n");
    }
    rewind(data_file);

    sensor_data_t sensor_data;
    float pressure, temperature;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(i2c_fd, &sensor_data) == 0) {
            // Convert data
            pressure = convert_pressure(sensor_data.pressure, sensor_data.scale_factor);
            temperature = convert_temperature(sensor_data.temperature, sensor_data.scale_factor);

            // Log data
            if (log_data(data_file, pressure, temperature) != 0) {
                fprintf(stderr, "Failed to log data.\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data.\n");
        }

        // Sleep for 100ms
        usleep(SLEEP_MS * 1000); // Convert milliseconds to microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

