#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SHT40_ADDR 0x44
#define MEASURE_HIGH_REPEATABILITY 0xFD
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INITIAL_VALUE 0xFF
#define LOG_FILE "sht40_log.txt"
#define MEASUREMENT_DELAY_MS 8
#define LOG_INTERVAL_S 5

// Global variables
int i2c_fd = -1;
FILE *log_fp = NULL;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} SensorData;

// Function prototypes
int init_i2c();
int read_sensor_data(uint8_t *data);
uint8_t calculate_crc(const uint8_t *data, size_t len);
int validate_crc(const uint8_t *data, size_t len);
int convert_data_to_float(const uint8_t *data, SensorData *sensor_data);
int log_data(const SensorData *sensor_data);
void signal_handler(int signal);
void cleanup();

// CRC-8 calculation function
uint8_t calculate_crc(const uint8_t *data, size_t len) {
    uint8_t crc = CRC8_INITIAL_VALUE;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// CRC-8 validation function
int validate_crc(const uint8_t *data, size_t len) {
    uint8_t crc_calculated = calculate_crc(data, len - 1);
    return (crc_calculated == data[len - 1]);
}

// Function to initialize I2C
int init_i2c() {
    i2c_fd = i2cOpen(I2C_BUS, SHT40_ADDR, 0);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_fd);
        return -1;
    }
    return 0;
}

// Function to read sensor data
int read_sensor_data(uint8_t *data) {
    if (i2cWriteByte(i2c_fd, MEASURE_HIGH_REPEATABILITY) != 0) {
        fprintf(stderr, "Error writing measurement command\n");
        return -1;
    }
    gpioDelay(MEASUREMENT_DELAY_MS * 1000); // Delay in microseconds

    if (i2cReadDevice(i2c_fd, (char *)data, 6) != 6) {
        fprintf(stderr, "Error reading sensor data\n");
        return -1;
    }
    return 0;
}

// Function to convert raw data to temperature and humidity
int convert_data_to_float(const uint8_t *data, SensorData *sensor_data) {
    uint16_t temp_raw = (data[0] << 8) | data[1];
    uint16_t humidity_raw = (data[3] << 8) | data[4];

    sensor_data->temperature = -45.0 + 175.0 * (float)temp_raw / 65535.0;
    sensor_data->humidity = 100.0 * (float)humidity_raw / 65535.0;

    return 0;
}

// Function to log data to file
int log_data(const SensorData *sensor_data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_fp == NULL) {
        log_fp = fopen(LOG_FILE, "a");
        if (log_fp == NULL) {
            fprintf(stderr, "Error opening log file\n");
            return -1;
        }
    }

    fprintf(log_fp, "%s, Temperature: %.2f C, Humidity: %.2f %%\n", timestamp, sensor_data->temperature, sensor_data->humidity);
    fflush(log_fp); // Ensure data is written to disk
    return 0;
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Cleanup function to close I2C and log file
void cleanup() {
    if (i2c_fd != -1) {
        i2cClose(i2c_fd);
    }
    if (log_fp != NULL) {
        fclose(log_fp);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    uint8_t sensor_data[6];
    SensorData float_data;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(sensor_data) == 0) {
            // Validate CRC
            if (validate_crc(sensor_data, 6)) {
                // Convert data to float
                if (convert_data_to_float(sensor_data, &float_data) == 0) {
                    // Log data
                    if (log_data(&float_data) != 0) {
                        fprintf(stderr, "Error logging data\n");
                    }
                } else {
                    fprintf(stderr, "Error converting data to float\n");
                }
            } else {
                fprintf(stderr, "CRC validation failed\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        sleep(LOG_INTERVAL_S);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

