// Constants
#define I2C_BUS 1
#define SDP800_ADDRESS 0x25
#define MEASURE_COMMAND 0x362F
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INITIAL_VALUE 0xFF
#define DATA_FILE "airflow_data.txt"
#define ERROR_FILE "error_log.txt"

// Global variables
int i2c_handle = -1;
FILE *data_file = NULL;
FILE *error_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int init_i2c();
int start_measurement();
int read_sensor_data(uint8_t *data);
uint8_t calculate_crc(const uint8_t *data, int len);
int validate_crc(const uint8_t *data);
float convert_pressure(int16_t raw_pressure);
float convert_temperature(int16_t raw_temperature);
int log_data(float pressure, float temperature);
void log_error(const char *message);
void signal_handler(int signal);

// CRC-8 calculation function
uint8_t calculate_crc(const uint8_t *data, int len) {
    uint8_t crc = CRC8_INITIAL_VALUE;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// CRC-8 validation function
int validate_crc(const uint8_t *data) {
    uint8_t crc_pressure = calculate_crc(data, 2);
    uint8_t crc_temperature = calculate_crc(data + 3, 2);

    if (crc_pressure != data[2] || crc_temperature != data[5]) {
        return 0; // CRC validation failed
    }
    return 1; // CRC validation passed
}

// Initialize I2C
int init_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SDP800_ADDRESS, 0);
    if (i2c_handle < 0) {
