    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    error_file = fopen(ERROR_FILE, "a");
    if (error_file == NULL) {
        fprintf(stderr, "Failed to open error file for writing\n");
        return;
    }

    fprintf(error_file, "%s: %s\n", timestamp, message);
    fclose(error_file);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        log_error("I2C initialization failed");
        return 1;
    }

    // Start measurement
    if (start_measurement() != 0) {
        log_error("Failed to start measurement");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    uint8_t sensor_data[6];
    int retry_count = 0;
    const int max_retries = 3;

    while (program_running) {
        // Read sensor data with retry mechanism
        retry_count = 0;
        while (retry_count < max_retries) {
            if (read_sensor_data(sensor_data) == 0) {
                break; // Success, exit retry loop
            } else {
                log_error("Failed to read sensor data, retrying...");
                retry_count++;
                gpioDelay(10); // Wait before retrying
            }
        }

        if (retry_count == max_retries) {
            log_error("Failed to read sensor data after multiple retries");
            break; // Exit main loop if retries exhausted
        }

        // Validate CRC
        if (validate_crc(sensor_data)) {
            // Convert raw data
            int16_t raw_pressure = (sensor_data[0] << 8) | sensor_data[1];
            int16_t raw_temperature = (sensor_data[3] << 8) | sensor_data[4];

