#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define SI7021_ADDR 0x40
#define TEMP_CMD 0xE3
#define FAN_GPIO 18
#define TEMP_THRESHOLD_ON 28.0
#define TEMP_THRESHOLD_OFF 27.0
#define BUFFER_SIZE 60
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10
#define FAN_ON_DELAY_MS 10

// Global variables
int i2c_handle;
volatile sig_atomic_t program_running = 1;

// Circular buffer structure
typedef struct {
    time_t timestamp;
    float temperature;
    float humidity;
} Reading;

Reading buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int read_sensor(float *temperature, float *humidity);
void control_fan(float temperature);
void add_to_buffer(float temperature, float humidity);
void print_buffer();
void signal_handler(int signal);

// Function to read temperature and humidity from the sensor
int read_sensor(float *temperature, float *humidity) {
    int raw_temperature, raw_humidity;
    int result;
    int retries = 0;

    while (retries < RETRY_COUNT) {
        result = i2cWriteByte(i2c_handle, TEMP_CMD);
        if (result != 0) {
            fprintf(stderr, "Error writing to I2C: %d\n", result);
            retries++;
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            continue;
        }

        gpioDelay(25000); // Wait for measurement (25ms)

        raw_temperature = i2cReadWordData(i2c_handle, 0);
        if (raw_temperature < 0) {
            fprintf(stderr, "Error reading temperature: %d\n", raw_temperature);
            retries++;
            gpioDelay(RETRY_DELAY_MS * 1000);
            continue;
        }

        raw_humidity = i2cReadWordData(i2c_handle, 0);
        if (raw_humidity < 0) {
            fprintf(stderr, "Error reading humidity: %d\n", raw_humidity);
            retries++;
            gpioDelay(RETRY_DELAY_MS * 1000);
            continue;
        }

        // Convert raw values to temperature and humidity (datasheet formulas)
        *temperature = (175.72 * raw_temperature / 65536.0) - 46.85;
        *humidity = (125.0 * raw_humidity / 65536.0) - 6.0;

        return 0; // Success
    }

    fprintf(stderr, "Failed to read sensor after %d retries.\n", RETRY_COUNT);
    return -1; // Failure
}

// Function to control the cooling fan
void control_fan(float temperature) {
    static int fan_on = 0;

    if (temperature > TEMP_THRESHOLD_ON && !fan_on) {
        gpioWrite(FAN_GPIO, 1); // Turn fan on
        gpioDelay(FAN_ON_DELAY_MS * 1000); // Delay in microseconds
        fan_on = 1;
        printf("Fan turned ON\n");
    } else if (temperature < TEMP_THRESHOLD_OFF && fan_on) {
        gpioWrite(FAN_GPIO, 0); // Turn fan off
        fan_on = 0;
        printf("Fan turned OFF\n");
    }
}

// Function to add a reading to the circular buffer
void add_to_buffer(float temperature, float humidity) {
    time(&buffer[buffer_index].timestamp);
    buffer[buffer_index].temperature = temperature;
    buffer[buffer_index].humidity = humidity;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Function to print the contents of the circular buffer
void print_buffer() {
    printf("\n--- Sensor Readings ---\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        struct tm *timeinfo = localtime(&buffer[i].timestamp);
        char timestamp_str[20];
        strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", timeinfo);
        printf("[%s] Temperature: %.2f C, Humidity: %.2f %%\n", timestamp_str, buffer[i].temperature, buffer[i].humidity);
    }
    printf("-----------------------\n");
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    program_running = 0;
    gpioWrite(FAN_GPIO, 0); // Turn fan off
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

int main() {
    float temperature, humidity;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SI7021_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO18 as output for fan control
    gpioSetMode(FAN_GPIO, PI_OUTPUT);
    gpioWrite(FAN_GPIO, 0); // Ensure fan is off initially

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        if (read_sensor(&temperature, &humidity) == 0) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
            control_fan(temperature);
            add_to_buffer(temperature, humidity);
        } else {
            fprintf(stderr, "Failed to read sensor data.\n");
        }

        print_buffer();
        sleep(2); // Read every 2 seconds
    }

    return 0;
}

