#define CMD_READ_MEASUREMENT 0xec05
#define CMD_STOP_PERIODIC_MEASUREMENT 0x3f86

// CRC polynomial
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INIT 0xFF

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    uint16_t co2;
    uint16_t temperature;
    uint16_t humidity;
} sensor_data_t;

// Function prototypes
int init_pigpio();
int open_i2c_bus();
int send_command(uint16_t command);
int read_data(uint8_t *data, int count);
uint8_t calculate_crc(const uint8_t *data, int len);
int verify_crc(const uint8_t *data, int len);
int read_sensor_data(sensor_data_t *data);
int log_data(sensor_data_t data);
void stop_periodic_measurement();
void signal_handler(int signal);

// CRC-8 calculation function
uint8_t calculate_crc(const uint8_t *data, int len) {
    uint8_t crc = CRC8_INIT;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// CRC verification function
int verify_crc(const uint8_t *data, int len) {
    uint8_t crc_calculated = calculate_crc(data, len - 1);
    return (crc_calculated == data[len - 1]);
}

// Initialize pigpio library
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Open I2C bus
int open_i2c_bus() {
    i2c_handle = i2cOpen(1, SCD40_ADDR, 0); // Bus 1, address 0x62, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Send a command to the SCD40
int send_command(uint16_t command) {
    uint8_t buf[2];
    buf[0] = command >> 8;
    buf[1] = command & 0xFF;
    int result = i2cWriteDevice(i2c_handle, (char *)buf, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to send command 0x%04X: %d\n", command, result);
        return -1;
    }
    return 0;
}

