int log_data(sensor_data_t data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%d,%d,%d\n", timestamp, data.co2, data.temperature, data.humidity);
    fflush(log_file);

    return 0;
}

// Stop periodic measurement
void stop_periodic_measurement() {
    if (send_command(CMD_STOP_PERIODIC_MEASUREMENT) != 0) {
        fprintf(stderr, "Failed to send stop periodic measurement command\n");
    }
    gpioDelay(100); // Wait for the command to complete
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Open I2C bus
    if (open_i2c_bus() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("air_quality.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Start periodic measurement
    if (send_command(CMD_START_PERIODIC_MEASUREMENT) != 0) {
        fprintf(stderr, "Failed to start periodic measurement\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    gpioDelay(1000); // Wait for the first measurement

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        if (read_sensor_data(&sensor_data) == 0) {
            log_data(sensor_data);
        } else {
            fprintf(stderr, "Failed to read sensor data, retrying...\n");
            gpioDelay(1000); // Wait before retrying
            continue;
        }

        gpioDelay(5000); // Wait 5 seconds
    }

    // Stop periodic measurement
    stop_periodic_measurement();

    // Close I2C bus
    i2cClose(i2c_handle);

    // Close log file
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

