#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <string.h>

// SCD40 I2C address
#define SCD40_ADDR 0x62

// SCD40 commands
#define CMD_START_PERIODIC_MEASUREMENT 0x21b1
#define CMD_READ_MEASUREMENT 0xec05
#define CMD_STOP_PERIODIC_MEASUREMENT 0x3f86

// GPIO pin for CO2 warning LED
#define CO2_LED_PIN 17

// Circular buffer size
#define BUFFER_SIZE 20

// Structure to hold sensor data
typedef struct {
    uint16_t co2;
    uint16_t temperature;
    uint16_t humidity;
    time_t timestamp;
} sensor_data_t;

// Circular buffer
sensor_data_t circular_buffer[BUFFER_SIZE];
int buffer_index = 0;

// I2C handle
int i2c_handle;

// Function prototypes
int init_scd40();
int read_scd40_data(uint16_t *co2, uint16_t *temperature, uint16_t *humidity);
void store_data(uint16_t co2, uint16_t temperature, uint16_t humidity);
void print_data(uint16_t co2, uint16_t temperature, uint16_t humidity);
void control_led(uint16_t co2);
void signal_handler(int signal);

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Initialize SCD40 sensor
int init_scd40() {
    uint8_t cmd[2] = {(CMD_START_PERIODIC_MEASUREMENT >> 8) & 0xFF, CMD_START_PERIODIC_MEASUREMENT & 0xFF};
    int result = i2cWriteDevice(i2c_handle, (char *)cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Error starting periodic measurement: %d\n", result);
        return -1;
    }
    gpioDelay(100000); // 100ms delay
    return 0;
}

// Read data from SCD40 sensor
int read_scd40_data(uint16_t *co2, uint16_t *temperature, uint16_t *humidity) {
    uint8_t cmd[2] = {(CMD_READ_MEASUREMENT >> 8) & 0xFF, CMD_READ_MEASUREMENT & 0xFF};
    uint8_t data[9];
    int result;

    result = i2cWriteDevice(i2c_handle, (char *)cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing read measurement command: %d\n", result);
        return -1;
    }
    gpioDelay(1000); // 1ms delay

    result = i2cReadDevice(i2c_handle, (char *)data, 9);
    if (result != 9) {
        fprintf(stderr, "Error reading data: %d\n", result);
        return -1;
    }

    // CRC validation
    if (crc8(data, 2) != data[2] || crc8(data + 3, 2) != data[5] || crc8(data + 6, 2) != data[8]) {
        fprintf(stderr, "CRC validation failed\n");
        return -1;
    }

    *co2 = (data[0] << 8) | data[1];
    *temperature = (data[3] << 8) | data[4];
    *humidity = (data[6] << 8) | data[7];

    return 0;
}

// Store data in circular buffer
void store_data(uint16_t co2, uint16_t temperature, uint16_t humidity) {
    circular_buffer[buffer_index].co2 = co2;
    circular_buffer[buffer_index].temperature = temperature;
    circular_buffer[buffer_index].humidity = humidity;
    circular_buffer[buffer_index].timestamp = time(NULL);
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Print data to stdout
void print_data(uint16_t co2, uint16_t temperature, uint16_t humidity) {
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%d.%X", tstruct);

    printf("%s - CO2: %d ppm, Temperature: %.2f °C, Humidity: %.2f %%RH\n",
           buf, co2, (float)temperature / 65536.0 * 175.0 - 45.0, (float)humidity / 65536.0 * 100.0);
}

// Control CO2 warning LED
void control_led(uint16_t co2) {
    if (co2 > 1000) {
        gpioWrite(CO2_LED_PIN, 1); // Turn LED on
    } else {
        gpioWrite(CO2_LED_PIN, 0); // Turn LED off
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    i2cWriteDevice(i2c_handle, (char *)&CMD_STOP_PERIODIC_MEASUREMENT, 2);
    gpioDelay(100000); // 100ms delay
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, SCD40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize SCD40 sensor
    if (init_scd40() != 0) {
        fprintf(stderr, "SCD40 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO17 as output for LED control
    gpioSetMode(CO2_LED_PIN, PI_OUTPUT);

    // Install signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uint16_t co2, temperature, humidity;
    int read_result;

    // Main loop
    while (1) {
        read_result = read_scd40_data(&co2, &temperature, &humidity);
        if (read_result == 0) {
            store_data(co2, temperature, humidity);
            print_data(co2, temperature, humidity);
            control_led(co2);
        } else {
            fprintf(stderr, "Failed to read sensor data. Retrying in 5 seconds.\n");
        }

        gpioDelay(5000000); // 5 seconds
    }

    return 0;
}

