#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_PIN 4
#define LOG_FILE "temperature_log.txt"
#define TIMEOUT_US 50000
#define SAMPLE_INTERVAL_S 5
#define TL_MIN 1000  // Minimum TL value to avoid division by zero
#define TEMP_MIN -40.0
#define TEMP_MAX 150.0

// Structure to hold pulse width measurements
typedef struct {
    unsigned int high_pulse_width;
    unsigned int total_cycle_width;
} PulseWidths;

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
PulseWidths measure_pulse_widths();
double calculate_temperature(PulseWidths pulse_widths);
int log_temperature(double temperature);
void signal_handler(int signal);
void cleanup();

// Function to initialize the pigpio library and configure GPIO
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);
    return 0;
}

// Function to measure the high pulse width and total cycle width
PulseWidths measure_pulse_widths() {
    PulseWidths pulse_widths = {0, 0};
    int start_time, end_time;
    int level;

    // Measure high pulse width
    start_time = gpioTick();
    while ((level = gpioRead(GPIO_PIN)) == 0 && pulse_widths.high_pulse_width < TIMEOUT_US) {
        pulse_widths.high_pulse_width = gpioTick() - start_time;
        if (pulse_widths.high_pulse_width < 0) pulse_widths.high_pulse_width = 0; // Handle tick rollover
    }
    if (level == 0) {
        fprintf(stderr, "Timeout waiting for rising edge\n");
        pulse_widths.high_pulse_width = 0; // Indicate timeout
    }

    // Measure total cycle width
    start_time = gpioTick();
    while ((level = gpioRead(GPIO_PIN)) == 1 && pulse_widths.total_cycle_width < TIMEOUT_US) {
        pulse_widths.total_cycle_width = gpioTick() - start_time;
        if (pulse_widths.total_cycle_width < 0) pulse_widths.total_cycle_width = 0; // Handle tick rollover
    }
    if (level == 1) {
        fprintf(stderr, "Timeout waiting for falling edge\n");
        pulse_widths.total_cycle_width = 0; // Indicate timeout
    }

    return pulse_widths;
}

// Function to calculate the temperature from pulse widths
double calculate_temperature(PulseWidths pulse_widths) {
    if (pulse_widths.total_cycle_width == 0) {
        return -999.0; // Indicate error
    }

    double tl = (double)pulse_widths.total_cycle_width - (double)pulse_widths.high_pulse_width;
    if (tl <= 0) {
        return -999.0; // Indicate error
    }

    return 25.0 + (100.0 * (double)pulse_widths.high_pulse_width / (double)tl);
}

// Function to log the temperature to a file
int log_temperature(double temperature) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    if (temperature < TEMP_MIN || temperature > TEMP_MAX) {
        fprintf(log_file, "%s ERROR: Temperature out of range: %.2f\n", timestamp, temperature);
        fflush(log_file);
        return -1;
    }

    fprintf(log_file, "%s %.2f\n", timestamp, temperature);
    fflush(log_file);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

// Cleanup function to release resources
void cleanup() {
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        cleanup();
        return 1;
    }

    int consecutive_failures = 0;

    while (running) {
        PulseWidths pulse_widths = measure_pulse_widths();
        double temperature = calculate_temperature(pulse_widths);

        if (temperature == -999.0) {
            consecutive_failures++;
            if (consecutive_failures >= 3) {
                time_t now = time(NULL);
                struct tm *t = localtime(&now);
                char timestamp[32];
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);
                fprintf(log_file, "%s SENSOR MALFUNCTION\n", timestamp);
                fflush(log_file);
                consecutive_failures = 0; // Reset after logging
            }
        } else {
            consecutive_failures = 0; // Reset on successful reading
            if (log_temperature(temperature) != 0) {
                fprintf(stderr, "Error logging temperature\n");
            }
        }

        sleep(SAMPLE_INTERVAL_S);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

