#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SHT35_ADDR 0x44
#define MEASUREMENT_COMMAND 0x2400
#define CRC_POLYNOMIAL 0x31
#define LOG_FILE "environmental_data.txt"
#define RETRY_COUNT 3
#define RETRY_DELAY 1 // seconds
#define OFFSET_PERIOD 3600 // seconds (1 hour)
#define TEMPERATURE_OFFSET_AMPLITUDE 2.0
#define HUMIDITY_OFFSET_AMPLITUDE 5.0

// Global variables
int i2c_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} SensorData;

// Function prototypes
int initialize_i2c();
int read_sensor_data(uint8_t *data);
uint8_t calculate_crc(const uint8_t *data, int len);
int validate_crc(const uint8_t *data, int len);
float convert_temperature(uint16_t raw_temperature);
float convert_humidity(uint16_t raw_humidity);
float apply_temperature_offset(float temperature, float time_offset);
float apply_humidity_offset(float humidity, float time_offset);
int log_data(float temperature, float humidity);
void signal_handler(int signal);
void cleanup();

// Function to initialize the I2C bus
int initialize_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SHT35_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to read sensor data with retries
int read_sensor_data(uint8_t *data) {
    int retries = 0;
    int result;

    while (retries < RETRY_COUNT) {
        result = i2cWriteWordData(i2c_handle, MEASUREMENT_COMMAND, 0); // Send measurement command
        if (result >= 0) {
            gpioDelay(20); // Wait for measurement (datasheet says 15ms, but be generous)
            result = i2cReadI2CBlockData(i2c_handle, 0, (char *)data, 6);
            if (result == 6) {
                return 0; // Success
            } else {
                fprintf(stderr, "I2C read failed (attempt %d): %d\n", retries + 1, result);
            }
        } else {
            fprintf(stderr, "I2C write failed (attempt %d): %d\n", retries + 1, result);
        }
        retries++;
        sleep(RETRY_DELAY);
    }

    return -1; // All retries failed
}

// Function to calculate CRC checksum
uint8_t calculate_crc(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to validate CRC checksum
int validate_crc(const uint8_t *data, int len) {
    uint8_t crc_calculated = calculate_crc(data, len - 1);
    return (crc_calculated == data[len - 1]);
}

// Function to convert raw temperature to Celsius
float convert_temperature(uint16_t raw_temperature) {
    return -45.0 + (175.0 * (float)raw_temperature / 65535.0);
}

// Function to convert raw humidity to percent relative humidity
float convert_humidity(uint16_t raw_humidity) {
    return 100.0 * (float)raw_humidity / 65535.0;
}

// Function to apply temperature offset
float apply_temperature_offset(float temperature, float time_offset) {
    return temperature + TEMPERATURE_OFFSET_AMPLITUDE * sin(2 * M_PI * time_offset / OFFSET_PERIOD);
}

// Function to apply humidity offset
float apply_humidity_offset(float humidity, float time_offset) {
    return humidity + HUMIDITY_OFFSET_AMPLITUDE * sin(2 * M_PI * time_offset / OFFSET_PERIOD);
}

// Function to log data to file
int log_data(float temperature, float humidity) {
    time_t now = time(NULL);
    struct tm *utc_time = gmtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", utc_time);

    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            fprintf(stderr, "Failed to open log file\n");
            return -1;
        }
    }

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
    fflush(log_file); // Ensure data is written immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function to close resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        return 1;
    }

    uint8_t sensor_data[6];
    float temperature, humidity;
    time_t start_time = time(NULL);

    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(sensor_data) == 0) {
            // Validate CRC
            if (validate_crc(sensor_data, 6)) {
                // Convert raw data to temperature and humidity
                uint16_t raw_temperature = (sensor_data[0] << 8) | sensor_data[1];
                uint16_t raw_humidity = (sensor_data[3] << 8) | sensor_data[4];

                temperature = convert_temperature(raw_temperature);
                humidity = convert_humidity(raw_humidity);

                // Apply sinusoidal offsets
                float time_offset = (time(NULL) - start_time) % OFFSET_PERIOD;
                temperature = apply_temperature_offset(temperature, time_offset);
                humidity = apply_humidity_offset(humidity, time_offset);

                // Log data
                if (log_data(temperature, humidity) != 0) {
                    fprintf(stderr, "Failed to log data\n");
                }
            } else {
                fprintf(stderr, "CRC validation failed\n");
                if (log_data(NAN, NAN) != 0) {
                    fprintf(stderr, "Failed to log data with NaN values\n");
                }
            }
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
            if (log_data(NAN, NAN) != 0) {
                fprintf(stderr, "Failed to log data with NaN values\n");
            }
        }

        sleep(5);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

