#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SHT35_ADDR 0x44
#define MEASUREMENT_COMMAND 0x2400
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INITIAL_VALUE 0xFF
#define SAMPLE_INTERVAL 5 // seconds

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} SensorData;

// Function prototypes
int initialize_i2c();
int read_sensor_data(SensorData *data);
unsigned char calculate_crc(unsigned char data[], int nbrOfBytes);
int validate_checksum(unsigned char data[], int nbrOfBytes);
int log_data(SensorData data);
void signal_handler(int signal);
void cleanup();

// Function to initialize the I2C bus
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SHT35_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read sensor data
int read_sensor_data(SensorData *data) {
    unsigned char command[2] = {(MEASUREMENT_COMMAND >> 8) & 0xFF, MEASUREMENT_COMMAND & 0xFF};
    unsigned char buffer[6];

    if (i2cWriteDevice(i2c_handle, (char *)command, 2) != 2) {
        fprintf(stderr, "Error writing to I2C device\n");
        return -1;
    }

    gpioDelay(15); // Wait for measurement (at least 15ms)

    if (i2cReadDevice(i2c_handle, (char *)buffer, 6) != 6) {
        fprintf(stderr, "Error reading from I2C device\n");
        return -1;
    }

    // CRC validation
    if (validate_checksum(buffer, 2) != 0 || validate_checksum(buffer + 3, 2) != 0) {
        fprintf(stderr, "CRC validation failed\n");
        return -1;
    }

    // Convert data
    int temperature_raw = (buffer[0] << 8) | buffer[1];
    int humidity_raw = (buffer[3] << 8) | buffer[4];

    data->temperature = -45.0 + (175.0 * temperature_raw) / 65535.0;
    data->humidity = (100.0 * humidity_raw) / 65535.0;

    return 0;
}

// Function to calculate CRC8 checksum
unsigned char calculate_crc(unsigned char data[], int nbrOfBytes) {
    unsigned char crc = CRC8_INITIAL_VALUE;
    for (int i = 0; i < nbrOfBytes; i++) {
        crc ^= data[i];
        for (int bit = 8; bit > 0; --bit) {
            if (crc & 0x80)
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            else
                crc = (crc << 1);
        }
    }
    return crc;
}

// Function to validate checksum
int validate_checksum(unsigned char data[], int nbrOfBytes) {
    unsigned char crc = calculate_crc(data, nbrOfBytes - 1);
    if (crc != data[nbrOfBytes - 1]) {
        return -1;
    }
    return 0;
}

// Function to log data to CSV file
int log_data(SensorData data) {
    FILE *fp = fopen("environment.csv", "a+");
    if (fp == NULL) {
        fprintf(stderr, "Error opening CSV file\n");
        return -1;
    }

    // Check if the file is empty or has a header
    fseek(fp, 0, SEEK_END);
    long file_size = ftell(fp);
    if (file_size == 0) {
        fprintf(fp, "timestamp,temperature,humidity\n");
    } else {
        // Check if the first line contains a comma (indicating a header)
        fseek(fp, 0, SEEK_SET);
        char first_char = fgetc(fp);
        if (first_char != 't') { // Basic check for header
            fprintf(stderr, "CSV file format is incorrect.  Expected header.\n");
            fclose(fp);
            return -1;
        }
        fseek(fp, 0, SEEK_END);
    }

    // Get current timestamp in ISO 8601 format
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];
    time(&rawtime);
    timeinfo = gmtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, data.temperature, data.humidity);
    fclose(fp);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function to close I2C and terminate pigpio
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        cleanup();
        return 1;
    }

    SensorData sensor_data;

    // Main loop
    while (!terminate) {
        if (read_sensor_data(&sensor_data) == 0) {
            if (log_data(sensor_data) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        gpioDelay(SAMPLE_INTERVAL * 1000); // Delay for 5 seconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

