int read_sensor_data(int handle, unsigned char command, unsigned char *data, int data_len);
float calculate_temperature(unsigned char msb, unsigned char lsb, unsigned char crc);
float calculate_humidity(unsigned char msb, unsigned char lsb, unsigned char crc);
int verify_crc(unsigned char data[], int len, unsigned char crc);
void log_data(float temperature, float humidity);
void signal_handler(int signal);
int initialize_i2c();
void cleanup_i2c();

// CRC-8 calculation function
unsigned char crc8(const unsigned char *data, int len) {
    unsigned char crc = CRC8_INIT;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read sensor data with timeout
int read_sensor_data(int handle, unsigned char command, unsigned char *data, int data_len) {
    int result;
    unsigned char buf[1];
    buf[0] = command;

    result = i2cWriteDevice(handle, buf, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing command to sensor: %d\n", result);
        return -1;
    }

    gpioDelay(10); // Wait for measurement

    int bytes_read = 0;
    int start_time = gpioTick();
    while (bytes_read < data_len) {
        result = i2cReadDevice(handle, data + bytes_read, data_len - bytes_read);
        if (result > 0) {
            bytes_read += result;
        } else if (result < 0) {
            fprintf(stderr, "Error reading from sensor: %d\n", result);
            return -1;
        }
        if (gpioTick() - start_time > TIMEOUT_MS * 1000) {
            fprintf(stderr, "Timeout reading from sensor\n");
            return -1;
        }
    }

    return 0;
}

