float calculate_temperature(unsigned char msb, unsigned char lsb, unsigned char crc) {
    unsigned char data[2] = {msb, lsb};
    if (verify_crc(data, 2, crc) != 0) {
        return -1000.0; // Indicate error
    }
    unsigned int raw_temp = (msb << 8) | lsb;
    return (175.72 * raw_temp / 65536.0) - 46.85;
}

// Function to calculate humidity
float calculate_humidity(unsigned char msb, unsigned char lsb, unsigned char crc) {
    unsigned char data[2] = {msb, lsb};
    if (verify_crc(data, 2, crc) != 0) {
