#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define SDP810_ADDR 0x25
#define MEASURE_CMD 0x362F
#define CRC8_POLYNOMIAL 0x31
#define SCALE_FACTOR_SIZE 3
#define DATA_SIZE 9

// Global variables
int i2c_handle = -1;
FILE *fp = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int init_sdp810();
int read_sdp810(float *pressure, float *temperature);
uint8_t calculate_crc(const uint8_t *data, int len);
int validate_crc(const uint8_t *data, int len);
int log_data(float pressure, float temperature);
void signal_handler(int signal);
void cleanup();

// Structure to hold sensor data
typedef struct {
    float pressure;
    float temperature;
} sensor_data_t;

// CRC-8 calculation function
uint8_t calculate_crc(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// CRC-8 validation function
int validate_crc(const uint8_t *data, int len) {
    uint8_t crc_calculated = calculate_crc(data, len - 1);
    return (crc_calculated == data[len - 1]);
}

// Initialize I2C
int init_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SDP810_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Initialize SDP810 sensor
int init_sdp810() {
    uint8_t cmd[2] = {(MEASURE_CMD >> 8) & 0xFF, MEASURE_CMD & 0xFF};
    int result = i2cWriteDevice(i2c_handle, (char *)cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to write measurement command: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Read data from SDP810 sensor
int read_sdp810(float *pressure, float *temperature) {
    uint8_t buffer[DATA_SIZE];
    int result = i2cReadDevice(i2c_handle, (char *)buffer, DATA_SIZE);
    if (result != DATA_SIZE) {
        fprintf(stderr, "Failed to read data: %s\n", strerror(errno));
        return -1;
    }

    if (!validate_crc(buffer, 3) || !validate_crc(buffer + 3, 3)) {
        fprintf(stderr, "CRC validation failed\n");
        return -1;
    }

    int16_t raw_pressure = (buffer[0] << 8) | buffer[1];
    int16_t raw_temperature = (buffer[3] << 8) | buffer[4];

    *pressure = (float)raw_pressure / 240.0; // Scale factor from datasheet
    *temperature = (float)raw_temperature / 200.0; // Scale factor from datasheet

    return 0;
}

// Log data to file
int log_data(float pressure, float temperature) {
    if (fwrite(&pressure, sizeof(float), 1, fp) != 1) {
        fprintf(stderr, "Failed to write pressure to file: %s\n", strerror(errno));
        return -1;
    }
    if (fwrite(&temperature, sizeof(float), 1, fp) != 1) {
        fprintf(stderr, "Failed to write temperature to file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Signal handler
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    if (fp != NULL) {
        fclose(fp);
    }
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        return 1;
    }

    // Initialize SDP810 sensor
    if (init_sdp810() != 0) {
        cleanup();
        return 1;
    }

    // Open data file
    fp = fopen("airflow.dat", "wb");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open data file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sdp810(&sensor_data.pressure, &sensor_data.temperature) == 0) {
            // Log data to file
            if (log_data(sensor_data.pressure, sensor_data.temperature) != 0) {
                break; // Exit loop on file write error
            }
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        // Wait for 1 second
        sleep(1);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

