#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_ADDR 0x28
#define FAN_GPIO 18
#define PWM_FREQ 25000
#define SAMPLE_INTERVAL_MS 100
#define LOG_FILE "flow_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_pressure(int i2c_handle);
float calculate_flow_rate(int raw_pressure);
void set_fan_speed(int gpio_pin, float flow_rate);
void log_data(FILE *log_file, float pressure);
void signal_handler(int signal);
int initialize();
void cleanup();

// Structure for sensor calibration (example)
typedef struct {
    float zero_offset;
    float sensitivity;
} sensor_calibration_t;

sensor_calibration_t calibration = {0.0, 1.0}; // Default calibration

// Function to initialize the system
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(1, I2C_ADDR, 0); // Bus 1, address 0x28, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return -1;
    }

    // Configure GPIO18 as PWM output
    gpioSetMode(FAN_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(FAN_GPIO, PWM_FREQ);
    gpioSetPWMrange(FAN_GPIO, 1000); // Set PWM range (0-1000)

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return -1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    return 0;
}

// Function to read pressure from the sensor
int read_pressure(int i2c_handle) {
    char buf[2];
    int bytes_read = i2cReadDevice(i2c_handle, buf, 2);

    if (bytes_read != 2) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1; // Indicate error
    }

    // Combine the two bytes into a 16-bit value
    int raw_pressure = (buf[0] << 8) | buf[1];

    return raw_pressure;
}

// Function to calculate flow rate from raw pressure
float calculate_flow_rate(int raw_pressure) {
    // Apply calibration (example linear conversion)
    float pressure_Pa = (float)raw_pressure * calibration.sensitivity + calibration.zero_offset;
    float flow_rate = pressure_Pa; // Assuming flow rate is directly proportional to pressure
    return flow_rate;
}

// Function to set fan speed based on flow rate
void set_fan_speed(int gpio_pin, float flow_rate) {
    // Map flow rate to PWM duty cycle (0-1000)
    int duty_cycle = (int)(flow_rate * 10); // Example mapping
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > 1000) duty_cycle = 1000;

    gpioPWM(gpio_pin, duty_cycle);
}

// Function to log data to file
void log_data(FILE *log_file, float pressure) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f\n", timestamp, pressure);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Function to clean up resources
void cleanup() {
    // Turn off the fan
    gpioPWM(FAN_GPIO, 0);

    // Close I2C connection
    i2cClose(i2c_handle);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    fprintf(stderr, "Cleanup complete. Exiting.\n");
}

int main() {
    if (initialize() != 0) {
        return 1;
    }

    while (!terminate) {
        int raw_pressure = read_pressure(i2c_handle);
        if (raw_pressure >= 0) {
            float flow_rate = calculate_flow_rate(raw_pressure);
            set_fan_speed(FAN_GPIO, flow_rate);
            log_data(log_file, flow_rate);
        } else {
            fprintf(stderr, "Failed to read pressure, retrying...\n");
        }

        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Delay for 100ms
    }

    cleanup();
    return 0;
}

