#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// LPS33HW I2C address
#define LPS33HW_ADDR 0x5C

// LPS33HW register addresses
#define CTRL_REG1 0x20
#define PRESS_OUT_XL 0x28
#define PRESS_OUT_L 0x29
#define PRESS_OUT_H 0x2A
#define TEMP_OUT_L 0x2B
#define TEMP_OUT_H 0x2C

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_lps33hw();
int read_pressure(float *pressure);
int read_temperature(float *temperature);
int log_data(float pressure, float temperature);
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    float pressure;
    float temperature;
} sensor_data_t;

// Function to initialize the LPS33HW sensor
int init_lps33hw() {
    // Enable continuous data acquisition (ODR = 10 Hz)
    if (i2cWriteByteData(i2c_handle, CTRL_REG1, 0xB0) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1\n");
        return -1;
    }
    return 0;
}

// Function to read pressure data from the LPS33HW
int read_pressure(float *pressure) {
    char buffer[3];
    int32_t raw_pressure;

    if (i2cReadI2CBlockData(i2c_handle, PRESS_OUT_XL, buffer, 3) != 3) {
        fprintf(stderr, "Error reading pressure data\n");
        return -1;
    }

    raw_pressure = (int32_t)buffer[0] | ((int32_t)buffer[1] << 8) | ((int32_t)buffer[2] << 16);
    *pressure = (float)raw_pressure / 4096.0; // Convert to hPa
    return 0;
}

// Function to read temperature data from the LPS33HW
int read_temperature(float *temperature) {
    char buffer[2];
    int16_t raw_temperature;

    if (i2cReadI2CBlockData(i2c_handle, TEMP_OUT_L, buffer, 2) != 2) {
        fprintf(stderr, "Error reading temperature data\n");
        return -1;
    }

    raw_temperature = (int16_t)buffer[0] | ((int16_t)buffer[1] << 8);
    *temperature = (float)raw_temperature / 100.0; // Convert to degrees Celsius
    return 0;
}

// Function to log data to a file
int log_data(float pressure, float temperature) {
    time_t now = time(NULL);
    struct tm timeinfo;
    char timestamp[20];

    localtime_r(&now, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    fprintf(log_file, "%s, Pressure: %.2f hPa, Temperature: %.2f °C\n", timestamp, pressure, temperature);
    fflush(log_file);
    return 0;
}

// Signal handler for graceful termination
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, LPS33HW_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("environmental_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (init_lps33hw() < 0) {
        fprintf(stderr, "Error initializing LPS33HW sensor\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for SIGINT
    signal(SIGINT, signal_handler);

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        // Read pressure and temperature
        if (read_pressure(&sensor_data.pressure) == 0 && read_temperature(&sensor_data.temperature) == 0) {
            // Log the data
            log_data(sensor_data.pressure, sensor_data.temperature);
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        // Wait for 1 second
        gpioDelay(1000000); // 1 second = 1000000 microseconds
    }

    // Cleanup
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

