// Constants
#define I2C_ADDR 0x48
#define GPIO_LED 17
#define BUFFER_SIZE 10
#define TEMP_THRESHOLD 28.0
#define TEMP_SCALE 0.5
#define TEMP_OFFSET -40.0

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Circular buffer
float temperature_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
float read_temperature();
void update_circular_buffer(float temperature);
float calculate_average_temperature();
void control_led(float average_temperature);
void signal_handler(int signal);

// Function to read temperature from the sensor
float read_temperature() {
    int raw_temperature;
    float temperature;

    raw_temperature = i2cReadWordData(i2c_handle, 0x00);
    if (raw_temperature < 0) {
        fprintf(stderr, "Error reading temperature: %d\n", raw_temperature);
        return -1000.0; // Indicate an error
    }

    // Convert raw temperature to Celsius
    temperature = (float)((short)raw_temperature) * TEMP_SCALE + TEMP_OFFSET;
    return temperature;
}

// Function to update the circular buffer
void update_circular_buffer(float temperature) {
    temperature_buffer[buffer_index] = temperature;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Function to calculate the average temperature
float calculate_average_temperature() {
    float sum = 0.0;
    for (int i = 0; i < BUFFER_SIZE; i++) {
        sum += temperature_buffer[i];
    }
    return sum / BUFFER_SIZE;
}

// Function to control the LED
void control_led(float average_temperature) {
    if (average_temperature > TEMP_THRESHOLD) {
        gpioWrite(GPIO_LED, 1); // Turn LED on
    } else {
        gpioWrite(GPIO_LED, 0); // Turn LED off
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO17 as output
    gpioSetMode(GPIO_LED, PI_OUTPUT);

    // Initialize circular buffer with 0s
    for (int i = 0; i < BUFFER_SIZE; i++) {
        temperature_buffer[i] = 0.0;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        float temperature = read_temperature();
        if (temperature > -999.0) { // Check for valid temperature reading
            update_circular_buffer(temperature);
            float average_temperature = calculate_average_temperature();
            control_led(average_temperature);
            printf("Temperature: %.2f°C, Average Temperature: %.2f°C\n", temperature, average_temperature);
        } else {
            fprintf(stderr, "Failed to read temperature, skipping iteration.\n");
        }

        sleep(1);
    }

    // Cleanup
    gpioWrite(GPIO_LED, 0); // Turn LED off
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

