#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// SCD30 I2C address
#define SCD30_I2C_ADDR 0x61

// SCD30 commands
#define SCD30_CMD_START_PERIODIC_MEASUREMENT 0x0010
#define SCD30_CMD_READ_MEASUREMENT 0x0300
#define SCD30_CMD_GET_DATA_READY 0x0202
#define SCD30_CMD_STOP_PERIODIC_MEASUREMENT 0x0104

// Global variables
int i2c_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_scd30();
int read_scd30_data(float *co2, float *temperature, float *humidity);
void control_ventilation(float co2);
void log_data(float co2, float temperature, float humidity);
void signal_handler(int signal);
void cleanup();

// CRC8 calculation function
unsigned char crc8(const unsigned char *data, int len) {
    unsigned char crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to initialize the SCD30 sensor
int initialize_scd30() {
    unsigned char cmd[2];
    unsigned char data[2];

    // Start periodic measurement
    cmd[0] = (SCD30_CMD_START_PERIODIC_MEASUREMENT >> 8) & 0xFF;
    cmd[1] = SCD30_CMD_START_PERIODIC_MEASUREMENT & 0xFF;
    if (i2cWriteDevice(i2c_handle, (char *)cmd, 2) != 0) {
        fprintf(stderr, "Error: Failed to start periodic measurement\n");
        return -1;
    }
    gpioDelay(100000); // Wait 100ms

    return 0;
}

// Function to read data from the SCD30 sensor
int read_scd30_data(float *co2, float *temperature, float *humidity) {
    unsigned char cmd[2];
    unsigned char data[18];
    unsigned char crc;

    // Read measurement command
    cmd[0] = (SCD30_CMD_READ_MEASUREMENT >> 8) & 0xFF;
    cmd[1] = SCD30_CMD_READ_MEASUREMENT & 0xFF;
    if (i2cWriteDevice(i2c_handle, (char *)cmd, 2) != 0) {
        fprintf(stderr, "Error: Failed to send read measurement command\n");
        return -1;
    }

    gpioDelay(10000); // Wait 10ms

    // Read 18 bytes of data
    if (i2cReadDevice(i2c_handle, (char *)data, 18) != 18) {
        fprintf(stderr, "Error: Failed to read measurement data\n");
        return -1;
    }

    // CRC check for CO2
    crc = crc8(data, 2);
    if (crc != data[2]) {
        fprintf(stderr, "Error: CO2 CRC mismatch\n");
        return -1;
    }

    // CRC check for temperature
    crc = crc8(data + 3, 2);
    if (crc != data[5]) {
        fprintf(stderr, "Error: Temperature CRC mismatch\n");
        return -1;
    }

    // CRC check for humidity
    crc = crc8(data + 6, 2);
    if (crc != data[8]) {
        fprintf(stderr, "Error: Humidity CRC mismatch\n");
        return -1;
    }

    // Convert data to float values
    *co2 = *((float *)data);
    *temperature = *((float *)(data + 6));
    *humidity = *((float *)(data + 12));

    return 0;
}

// Function to control ventilation based on CO2 level
void control_ventilation(float co2) {
    if (co2 < 800.0) {
        printf("Ventilation: OFF\n");
    } else if (co2 >= 800.0 && co2 <= 1199.0) {
        printf("Ventilation: LOW\n");
    } else {
        printf("Ventilation: HIGH\n");
    }
}

// Function to log data to a file
void log_data(float co2, float temperature, float humidity) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f\n", timestamp, co2, temperature, humidity);
    fflush(log_file);
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    program_running = 0;
}

// Cleanup function
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    float co2, temperature, humidity;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, SCD30_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("air_quality.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        cleanup();
        return 1;
    }

    // Initialize SCD30 sensor
    if (initialize_scd30() != 0) {
        fprintf(stderr, "Error: SCD30 initialization failed\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (program_running) {
        // Read data from SCD30
        if (read_scd30_data(&co2, &temperature, &humidity) == 0) {
            // Log data
            log_data(co2, temperature, humidity);

            // Control ventilation
            control_ventilation(co2);
        } else {
            fprintf(stderr, "Error: Failed to read SCD30 data\n");
        }

        sleep(5);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

