#include <errno.h>
#include <string.h>

// HDC1000 I2C address
#define HDC1000_ADDR 0x40

// HDC1000 register addresses
#define TEMPERATURE_REG 0x00
#define HUMIDITY_REG 0x01
#define CONFIGURATION_REG 0x02

// Global variable for I2C handle
int i2c_handle = -1;

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    exit(0);
}

// Function to initialize the HDC1000 sensor
int init_hdc1000() {
    // Configure the sensor for temperature and humidity measurement
    // 14-bit resolution, temperature first, no heater
    uint16_t config_value = 0x0000; // Reset value
    char buf[3];
    buf[0] = CONFIGURATION_REG;
    buf[1] = (config_value >> 8) & 0xFF;
    buf[2] = config_value & 0xFF;

    int result = i2cWriteDevice(i2c_handle, buf, 3);
    if (result != 0) {
        fprintf(stderr, "Error writing to configuration register: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Function to read temperature and humidity from the HDC1000 sensor
int read_hdc1000(float *temperature, float *humidity) {
    // Trigger temperature and humidity measurement
    if (i2cWriteByteData(i2c_handle, TEMPERATURE_REG, 0x00) != 0) {
        fprintf(stderr, "Error triggering measurement: %s\n", strerror(errno));
        return -1;
    }

    // Wait for at least 20 ms for conversion
    gpioDelay(20000); // 20 ms

    // Read temperature data
    char temp_data[2];
    if (i2cReadDevice(i2c_handle, temp_data, 2) != 2) {
        fprintf(stderr, "Error reading temperature data: %s\n", strerror(errno));
        return -1;
    }
    uint16_t raw_temperature = (temp_data[0] << 8) | temp_data[1];
    *temperature = ((float)raw_temperature / 65536.0) * 165.0 - 40.0;

    // Read humidity data
    char humidity_data[2];
    if (i2cReadDevice(i2c_handle, humidity_data, 2) != 2) {
        fprintf(stderr, "Error reading humidity data: %s\n", strerror(errno));
        return -1;
    }
    uint16_t raw_humidity = (humidity_data[0] << 8) | humidity_data[1];
    *humidity = ((float)raw_humidity / 65536.0) * 100.0;

    return 0;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, HDC1000_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Initialize the HDC1000 sensor
    if (init_hdc1000() != 0) {
        fprintf(stderr, "HDC1000 initialization failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    float temperature, humidity;
    while (1) {
        if (read_hdc1000(&temperature, &humidity) == 0) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
        } else {
            fprintf(stderr, "Failed to read sensor data.\n");
        }

        gpioDelay(5000000); // 5 seconds
    }

    // The following lines will never be reached due to the infinite loop
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

