        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return 1;
    }

    uint8_t data[9];
    SensorData sensor_data;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(data) == 0) {
            // Validate CRC8
            if (validate_crc8(data, 9)) {
                // Convert data
                if (convert_data(data, &sensor_data) == 0) {
