#define LOG_FILE "environmental_data.log"
#define LOG_SIZE_LIMIT 1048576 // 1MB

int i2c_handle;
volatile sig_atomic_t program_running = 1;

// Function to handle signals (e.g., Ctrl+C)
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to get the current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp string

    if (timestamp == NULL) {
        perror("Failed to allocate memory for timestamp");
        return NULL;
    }

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Function to read data from the HIH6130 sensor
int read_hih6130(float *temperature, float *humidity) {
    unsigned char buffer[4];
    int result;

    // Trigger measurement
    result = i2cWriteByte(i2c_handle, 0x00);
    if (result != 0) {
        fprintf(stderr, "Error triggering measurement: %d\n", result);
        return -1;
    }

    // Wait for measurement to complete (at least 40ms)
    gpioDelay(40000); // 40ms

    // Read 4 bytes of data
    result = i2cReadDevice(i2c_handle, buffer, 4);
    if (result != 4) {
        fprintf(stderr, "Error reading data: %d\n", result);
        return -1;
    }

    // Check status bits
    int status = (buffer[0] >> 6) & 0x03;
    if (status != 0) {
        fprintf(stderr, "Error: Sensor status indicates an error (status = %d)\n", status);
        return -1;
    }

    // Calculate humidity and temperature
    unsigned int humidity_raw = ((buffer[0] & 0x3F) << 8) | buffer[1];
    unsigned int temperature_raw = (buffer[2] << 6) | (buffer[3] >> 2);

    *humidity = ((float)humidity_raw / 16383) * 100;
    *temperature = ((float)temperature_raw / 16383) * 165 - 40;

    return 0;
}

// Function to log data to a file
int log_data(const char *timestamp, float temperature, float humidity) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1;
    }

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
    fclose(fp);
    return 0;
}

// Function to rotate the log file if it exceeds the size limit
int rotate_log_file() {
    FILE *fp = fopen(LOG_FILE, "r");
    if (fp == NULL) {
        perror("Error opening log file for size check");
        return -1;
    }

    fseek(fp, 0, SEEK_END);
    long file_size = ftell(fp);
    fclose(fp);

    if (file_size > LOG_SIZE_LIMIT) {
        if (remove(LOG_FILE) == 0) {
            printf("Log file rotated (size exceeded limit).\n");
        } else {
            perror("Error rotating log file");
            return -1;
        }
    }
    return 0;
}

int main() {
    float temperature, humidity;
    char *timestamp;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, HIH6130_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);

    printf("Starting data logging...\n");

    while (program_running) {
        // Read sensor data
        if (read_hih6130(&temperature, &humidity) == 0) {
            // Get timestamp
            timestamp = get_iso8601_timestamp();
            if (timestamp != NULL) {
                // Log data
                if (log_data(timestamp, temperature, humidity) != 0) {
                    fprintf(stderr, "Error logging data.\n");
                }
                free(timestamp); // Free the allocated memory
            } else {
                fprintf(stderr, "Error getting timestamp.\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data.\n");
        }

        // Rotate log file
        if (rotate_log_file() != 0) {
            fprintf(stderr, "Error rotating log file.\n");
        }

        // Wait 5 seconds
        sleep(5);
    }

    // Close I2C bus
    i2cClose(i2c_handle);

    // Terminate pigpio
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

