// Function to initialize the pigpio library and GPIO pin
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);
    state.running = 1;
    return 0;
}

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, shutting down...\n", signal);
    state.running = 0;
}

// Function to read SENT data from the GPIO pin
int read_sent_data(int *status, int *data, int *checksum) {
    int i;
    unsigned int start_tick, end_tick, pulse_width;
    int nibble;

    // Wait for the start of the sync pulse
    start_tick = gpioTick();
    while (gpioRead(GPIO_PIN) == 1 && (gpioTick() - start_tick) < TIMEOUT_US && state.running);
    if (gpioRead(GPIO_PIN) == 1) {
        fprintf(stderr, "Timeout waiting for sync pulse\n");
        return 1;
    }

    start_tick = gpioTick();
    while (gpioRead(GPIO_PIN) == 0 && (gpioTick() - start_tick) < TIMEOUT_US && state.running);
    if (gpioRead(GPIO_PIN) == 0) {
        fprintf(stderr, "Timeout waiting for sync pulse end\n");
        return 1;
    }

    end_tick = gpioTick();
    pulse_width = end_tick - start_tick;

    if (pulse_width < SYNC_PULSE_MIN || pulse_width > SYNC_PULSE_MAX) {
        fprintf(stderr, "Invalid sync pulse width: %d ticks\n", pulse_width);
        return 1;
    }

    // Read the 4 data nibbles
    for (i = 0; i < 4; i++) {
        start_tick = gpioTick();
        while (gpioRead(GPIO_PIN) == 1 && (gpioTick() - start_tick) < TIMEOUT_US && state.running);
        if (gpioRead(GPIO_PIN) == 1) {
            fprintf(stderr, "Timeout waiting for data pulse start\n");
            return 1;
        }

        start_tick = gpioTick();
        while (gpioRead(GPIO_PIN) == 0 && (gpioTick() - start_tick) < TIMEOUT_US && state.running);
        if (gpioRead(GPIO_PIN) == 0) {
            fprintf(stderr, "Timeout waiting for data pulse end\n");
            return 1;
        }

        end_tick = gpioTick();
        pulse_width = end_tick - start_tick;

        if (pulse_width < DATA_PULSE_MIN || pulse_width > DATA_PULSE_MAX) {
            fprintf(stderr, "Invalid data pulse width: %d ticks\n", pulse_width);
            return 1;
        }

        // Determine the nibble value based on the pulse width
        if (pulse_width < 20) nibble = 0;
        else if (pulse_width < 40) nibble = 1;
        else if (pulse_width < 60) nibble = 2;
        else if (pulse_width < 80) nibble = 3;
        else if (pulse_width < 100) nibble = 4;
        else if (pulse_width < 120) nibble = 5;
        else if (pulse_width < 140) nibble = 6;
        else if (pulse_width < 160) nibble = 7;
        else if (pulse_width < 180) nibble = 8;
        else if (pulse_width < 200) nibble = 9;
        else if (pulse_width < 220) nibble = 10;
        else if (pulse_width < 240) nibble = 11;
        else if (pulse_width < 260) nibble = 12;
        else if (pulse_width < 280) nibble = 13;
        else if (pulse_width < 300) nibble = 14;
        else if (pulse_width < 320) nibble = 15;
        else nibble = 15; // Max value

        if (i == 0) *status = nibble;
        else if (i == 1) data[0] = nibble;
        else if (i == 2) data[1] = nibble;
        else data[2] = nibble;
    }

    // Read the checksum nibble
    start_tick = gpioTick();
    while (gpioRead(GPIO_PIN) == 1 && (gpioTick() - start_tick) < TIMEOUT_US && state.running);
    if (gpioRead(GPIO_PIN) == 1) {
        fprintf(stderr, "Timeout waiting for checksum pulse start\n");
        return 1;
    }

    start_tick = gpioTick();
    while (gpioRead(GPIO_PIN) == 0 && (gpioTick() - start_tick) < TIMEOUT_US && state.running);
    if (gpioRead(GPIO_PIN) == 0) {
        fprintf(stderr, "Timeout waiting for checksum pulse end\n");
        return 1;
    }

    end_tick = gpioTick();
    pulse_width = end_tick - start_tick;

    if (pulse_width < DATA_PULSE_MIN || pulse_width > DATA_PULSE_MAX) {
        fprintf(stderr, "Invalid checksum pulse width: %d ticks\n", pulse_width);
        return 1;
    }

    // Determine the checksum value based on the pulse width
    if (pulse_width < 20) *checksum = 0;
    else if (pulse_width < 40) *checksum = 1;
    else if (pulse_width < 60) *checksum = 2;
    else if (pulse_width < 80) *checksum = 3;
    else if (pulse_width < 100) *checksum = 4;
    else if (pulse_width < 120) *checksum = 5;
    else if (pulse_width < 140) *checksum = 6;
    else if (pulse_width < 160) *checksum = 7;
    else if (pulse_width < 180) *checksum = 8;
    else if (pulse_width < 200) *checksum = 9;
    else if (pulse_width < 220) *checksum = 10;
    else if (pulse_width < 240) *checksum = 11;
    else if (pulse_width < 260) *checksum = 12;
    else if (pulse_width < 280) *checksum = 13;
    else if (pulse_width < 300) *checksum = 14;
    else *checksum = 15; // Max value

    return 0;
}

