    // Implement the pressure calculation based on the MLX90824 datasheet
    // This is a placeholder, replace with the actual calculation
    float pressure = (float)(status * 100 + data1 * 10 + data2 + data3 / 10.0); // Example calculation
    return pressure;
}

// Function to log the pressure data to a file
void log_pressure(float pressure) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(state.log_file, "%s, Pressure: %.2f Pa\n", timestamp, pressure);
    fflush(state.log_file); // Ensure data is written to the file immediately
}

// Function to clean up resources before exiting
void cleanup() {
    if (state.log_file != NULL) {
        fclose(state.log_file);
    }
    gpioTerminate();
}

int main() {
    int status, data[3], checksum;
    float pressure;

    // Initialize the program state
    state.log_file = fopen("pressure_log.txt", "a");
    if (state.log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (initialize()) {
        fclose(state.log_file);
        return 1;
    }

    // Main loop
    while (state.running) {
        if (read_sent_data(&status, data, &checksum) == 0) {
