// Constants
#define I2C_BUS 1
#define TMP117_ADDR 0x48
#define TEMP_REG 0x00
#define BUFFER_SIZE 60
#define SAMPLE_INTERVAL 5 // seconds

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Circular buffer
float temperature_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
