// Structure to hold program state
typedef struct {
    int i2c_handle;
    float temperature_buffer[BUFFER_SIZE];
    int buffer_index;
} ProgramState;

ProgramState state;

// Function to initialize I2C
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, TMP117_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read temperature from TMP117
float read_temperature() {
    int raw_temp;
    float temperature;

    raw_temp = i2cReadWordData(i2c_handle, TEMP_REG);
    if (raw_temp < 0) {
        fprintf(stderr, "Error reading temperature: %s\n", strerror(errno));
        return -1000.0; // Indicate error with a very low temperature
    }

    // Convert raw temperature to Celsius (see TMP117 datasheet)
    temperature = (float)((int16_t)raw_temp) * 0.0078125;
    return temperature;
}

// Function to store temperature in the circular buffer
void store_temperature(float temperature) {
    temperature_buffer[buffer_index] = temperature;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

