#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// SHTC3 I2C address
#define SHTC3_ADDR 0x70

// SHTC3 commands
#define SHTC3_MEASURE_NORMAL 0x7866

// CRC-8 polynomial and initial value
#define CRC_POLYNOMIAL 0x31
#define CRC_INITIAL_VALUE 0xFF

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Function prototypes
int init_i2c();
int read_shtc3(sensor_data_t *data);
unsigned char calculate_crc(unsigned char data[], int nbrOfBytes);
int validate_data(sensor_data_t data);
int log_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// CRC-8 calculation function
unsigned char calculate_crc(unsigned char data[], int nbrOfBytes) {
    unsigned char crc = CRC_INITIAL_VALUE;
    for (int i = 0; i < nbrOfBytes; i++) {
        crc ^= data[i];
        for (int bit = 8; bit > 0; --bit) {
            if (crc & 0x80)
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            else
                crc = (crc << 1);
        }
    }
    return crc;
}

// Initialize I2C communication
int init_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(1, SHTC3_ADDR, 0); // I2C bus 1
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Read temperature and humidity from SHTC3
int read_shtc3(sensor_data_t *data) {
    unsigned char cmd[2] = {(SHTC3_MEASURE_NORMAL >> 8) & 0xFF, SHTC3_MEASURE_NORMAL & 0xFF};
    unsigned char buffer[6];

    if (i2cWriteDevice(i2c_handle, (char *)cmd, 2) != 2) {
        fprintf(stderr, "Failed to write command to SHTC3\n");
        return -1;
    }

    gpioDelay(15); // Wait for measurement (datasheet specifies 12.1ms for normal mode)

    if (i2cReadDevice(i2c_handle, (char *)buffer, 6) != 6) {
        fprintf(stderr, "Failed to read data from SHTC3\n");
        return -1;
    }

    // CRC validation
    unsigned char temp_data[2] = {buffer[0], buffer[1]};
    unsigned char hum_data[2] = {buffer[3], buffer[4]};

    if (calculate_crc(temp_data, 2) != buffer[2]) {
        fprintf(stderr, "Temperature CRC check failed\n");
        return -1;
    }

    if (calculate_crc(hum_data, 2) != buffer[5]) {
        fprintf(stderr, "Humidity CRC check failed\n");
        return -1;
    }

    // Convert raw data to temperature and humidity
    int temp_raw = (buffer[0] << 8) | buffer[1];
    int hum_raw = (buffer[3] << 8) | buffer[4];

    data->temperature = 175.0 * temp_raw / 65535.0 - 45.0;
    data->humidity = 100.0 * hum_raw / 65535.0;

    return 0;
}

// Validate temperature and humidity values
int validate_data(sensor_data_t data) {
    if (data.temperature < -40.0 || data.temperature > 125.0) {
        fprintf(stderr, "Temperature out of range: %.2f\n", data.temperature);
        return -1;
    }

    if (data.humidity < 0.0 || data.humidity > 100.0) {
        fprintf(stderr, "Humidity out of range: %.2f\n", data.humidity);
        return -1;
    }

    return 0;
}

// Log data to file
int log_data(sensor_data_t data) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, data.temperature, data.humidity);
    fflush(log_file); // Ensure data is written to file immediately

    return 0;
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("shtc3_environment.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        if (read_shtc3(&sensor_data) == 0) {
            if (validate_data(sensor_data) == 0) {
                printf("Temperature: %.2f C, Humidity: %.2f %%\n", sensor_data.temperature, sensor_data.humidity);
                log_data(sensor_data);
            }
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        sleep(5);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

