#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <math.h>

// Constants
#define I2C_BUS 1
#define SI7202_ADDR 0x40
#define MAG_DATA_REG 0x01
#define TEMP_DATA_REG 0x03
#define LOG_FILE "mag_temp_log.csv"
#define SAMPLE_INTERVAL_US 1000000 // 1 second

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float rotational_speed;
    float temperature;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int read_sensor_data(sensor_data_t *data);
int log_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// Function to initialize the I2C bus
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SI7202_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read data from the Si7202 sensor
int read_sensor_data(sensor_data_t *data) {
    char buf[4];
    int bytes_read;

    // Read magnetic data
    bytes_read = i2cReadI2CBlockData(i2c_handle, MAG_DATA_REG, buf, 2);
    if (bytes_read != 2) {
        fprintf(stderr, "Error reading magnetic data: %d\n", bytes_read);
        data->rotational_speed = NAN;
        return -1;
    }
    int16_t mag_raw = (buf[0] << 8) | buf[1];

    // Read temperature data
    bytes_read = i2cReadI2CBlockData(i2c_handle, TEMP_DATA_REG, buf, 2);
    if (bytes_read != 2) {
        fprintf(stderr, "Error reading temperature data: %d\n", bytes_read);
        data->temperature = NAN;
        return -1;
    }
    int16_t temp_raw = (buf[0] << 8) | buf[1];

    // Convert raw data to physical units (example conversions, adjust as needed)
    data->rotational_speed = (float)mag_raw; // Placeholder conversion
    data->temperature = (float)temp_raw / 10.0; // Placeholder conversion

    return 0;
}

// Function to log data to a CSV file
int log_data(sensor_data_t data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (isnan(data.rotational_speed) || isnan(data.temperature)) {
        fprintf(log_file, "%s,NaN,NaN\n", timestamp);
    } else {
        fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, data.rotational_speed, data.temperature);
    }
    fflush(log_file);
    return 0;
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Cleanup function to close resources
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Rotational Speed,Temperature\n");
    }
    fflush(log_file);

    // Set up signal handler
    signal(SIGINT, signal_handler);

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        if (read_sensor_data(&sensor_data) == 0) {
            log_data(sensor_data);
        } else {
            // Log NaN values if read fails
            sensor_data.rotational_speed = NAN;
            sensor_data.temperature = NAN;
            log_data(sensor_data);
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

