// Constants
#define I2C_BUS 1
#define TMP117_ADDR 0x48
#define TEMP_REG 0x00
#define TEMP_SCALE 0.0078125
#define LOG_FILE "temperature_log.txt"
#define MAX_REINIT_ATTEMPTS 3

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c();
double read_temperature();
char* format_log_entry(double temperature);
int write_to_log(const char* log_entry);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        terminate = 1;
        printf("\nCaught SIGINT, exiting gracefully...\n");
    }
}

// I2C initialization function
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, TMP117_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Temperature reading function
double read_temperature() {
    int raw_temp;
    double temperature;

    raw_temp = i2cReadWordData(i2c_handle, TEMP_REG);
    if (raw_temp < 0) {
        fprintf(stderr, "Error reading temperature data: %d\n", raw_temp);
        return -1000.0; // Indicate error with a very low temperature
    }

    // Convert raw temperature to Celsius
    temperature = (double)raw_temp * TEMP_SCALE;

    return temperature;
}

// Log entry formatting function
char* format_log_entry(double temperature) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    static char log_entry[100]; // Static buffer to hold the log entry

    strftime(log_entry, sizeof(log_entry), "%Y-%m-%d %H:%M:%S, Temperature: %.2f C\n", t);
    return log_entry;
}

// Log writing function
int write_to_log(const char* log_entry) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        return -1;
    }

    if (fputs(log_entry, fp) == EOF) {
        fprintf(stderr, "Error writing to log file: %s\n", LOG_FILE);
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

// Cleanup function
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
}

int main() {
    int reinit_attempts = 0;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        fprintf(stderr, "I2C initialization failed. Exiting.\n");
        cleanup();
        return 1;
    }

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        double temperature = read_temperature();

        if (temperature > -999.0) { // Check for valid temperature reading
            char* log_entry = format_log_entry(temperature);
            if (write_to_log(log_entry) != 0) {
                fprintf(stderr, "Error writing to log. Attempting re-initialization.\n");
                i2cClose(i2c_handle);
                i2c_handle = -1; // Reset handle to trigger re-initialization
                reinit_attempts = 0; // Reset re-initialization attempts
            }
        } else {
            fprintf(stderr, "Error reading temperature. Attempting re-initialization.\n");
            i2cClose(i2c_handle);
            i2c_handle = -1; // Reset handle to trigger re-initialization
            reinit_attempts = 0; // Reset re-initialization attempts
        }

        if (i2c_handle < 0) {
            reinit_attempts++;
            if (reinit_attempts <= MAX_REINIT_ATTEMPTS) {
                fprintf(stderr, "Re-initializing I2C (attempt %d/%d)...\n", reinit_attempts, MAX_REINIT_ATTEMPTS);
                if (initialize_i2c() == 0) {
                    fprintf(stderr, "I2C re-initialization successful.\n");
                    reinit_attempts = 0; // Reset attempts after success
                } else {
                    fprintf(stderr, "I2C re-initialization failed.\n");
                }
            } else {
                fprintf(stderr, "Max I2C re-initialization attempts reached. Exiting.\n");
                terminate = 1; // Exit loop after max attempts
            }
        }

        gpioDelay(1000); // Wait 1 second
    }

    // Cleanup and exit
    cleanup();
    printf("Temperature monitoring stopped.\n");
    return 0;
}

