#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x28
#define FLOW_SCALE_FACTOR 0.0625 // SLPM per unit
#define TEMP_SCALE_FACTOR 0.1875 // °C per unit
#define TEMP_OFFSET 20.0         // °C offset
#define NUM_STALE_READS 2
#define LOG_FILE "flow_log.txt"

// Global variables
int i2c_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float flow_slpm;
    float temperature_c;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int read_sensor_data(uint8_t *data);
sensor_data_t process_sensor_data(const uint8_t *data);
int log_data(const sensor_data_t *data);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// I2C initialization function
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read sensor data
int read_sensor_data(uint8_t *data) {
    int bytes_read = i2cReadDevice(i2c_handle, (char *)data, 4);
    if (bytes_read != 4) {
        fprintf(stderr, "Error reading from I2C device: %d\n", bytes_read);
        return -1;
    }
    return 0;
}

// Function to process sensor data
sensor_data_t process_sensor_data(const uint8_t *data) {
    sensor_data_t sensor_data;

    // Extract flow value (14-bit)
    int16_t raw_flow = (data[0] << 8) | data[1];
    raw_flow = raw_flow >> 2; // Shift right by 2 bits

    // Extract temperature value (12-bit)
    int16_t raw_temp = (data[2] << 4) | (data[3] >> 4);

    // Convert to SLPM and °C
    sensor_data.flow_slpm = (float)raw_flow * FLOW_SCALE_FACTOR;
    sensor_data.temperature_c = (float)raw_temp * TEMP_SCALE_FACTOR + TEMP_OFFSET;

    return sensor_data;
}

// Function to log data to file
int log_data(const sensor_data_t *data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
            return -1;
        }
    }

    fprintf(log_file, "%s, %.2f SLPM, %.2f °C\n", timestamp, data->flow_slpm, data->temperature_c);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        cleanup();
        return 1;
    }

    uint8_t stale_data[NUM_STALE_READS][4];
    int stale_index = 0;

    // Discard initial stale readings
    for (int i = 0; i < NUM_STALE_READS; i++) {
        if (read_sensor_data(stale_data[i]) != 0) {
            fprintf(stderr, "Error reading stale data, attempting re-initialization...\n");
            i2cClose(i2c_handle);
            if (initialize_i2c() != 0) {
                fprintf(stderr, "Failed to re-initialize I2C, exiting.\n");
                cleanup();
                return 1;
            }
        }
        gpioDelay(100); // Small delay between reads
    }

    // Main loop
    while (!terminate) {
        uint8_t data[4];
        if (read_sensor_data(data) == 0) {
            sensor_data_t sensor_data = process_sensor_data(data);
            if (log_data(&sensor_data) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data, attempting re-initialization...\n");
            i2cClose(i2c_handle);
            if (initialize_i2c() != 0) {
                fprintf(stderr, "Failed to re-initialize I2C, continuing.\n");
            }
        }
        gpioDelay(1000); // Sample every 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

