#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SHT31_ADDR 0x44
#define MEASUREMENT_COMMAND 0x2C06
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INITIAL_VALUE 0xFF
#define LOG_FILE "sht31d_data.log"
#define MAX_RETRIES 3

// Global variables
int i2c_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_sensor_data(float *temperature, float *humidity);
unsigned char calculate_crc(unsigned char data[], int nbrOfBytes);
int validate_crc(unsigned char data[], int nbrOfBytes);
int log_data(float temperature, float humidity);
void signal_handler(int signal);
void cleanup();

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Function to initialize the I2C interface
int init_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SHT31_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to read data from the SHT31-D sensor
int read_sensor_data(float *temperature, float *humidity) {
    unsigned char data[6];
    int retries = 0;
    int result;

    while (retries < MAX_RETRIES) {
        // Send measurement command
        char cmd[2] = {(MEASUREMENT_COMMAND >> 8) & 0xFF, MEASUREMENT_COMMAND & 0xFF};
        result = i2cWriteDevice(i2c_handle, cmd, 2);
        if (result != 0) {
            fprintf(stderr, "I2C write failed (command): %d, retry %d\n", result, retries + 1);
            gpioDelay(10); // Small delay before retry
            retries++;
            continue;
        }

        gpioDelay(15); // Wait for measurement (at least 15ms)

        // Read 6 bytes of data
        result = i2cReadDevice(i2c_handle, (char *)data, 6);
        if (result != 6) {
            fprintf(stderr, "I2C read failed: %d, retry %d\n", result, retries + 1);
            gpioDelay(10); // Small delay before retry
            retries++;
            continue;
        }

        // Validate CRC for temperature
        if (validate_crc(data, 2) != 0) {
            fprintf(stderr, "Temperature CRC validation failed, retry %d\n", retries + 1);
            retries++;
            continue;
        }

        // Validate CRC for humidity
        if (validate_crc(data + 3, 2) != 0) {
            fprintf(stderr, "Humidity CRC validation failed, retry %d\n", retries + 1);
            retries++;
            continue;
        }

        // Convert data to temperature and humidity
        int temperature_raw = (data[0] << 8) | data[1];
        int humidity_raw = (data[3] << 8) | data[4];

        *temperature = -45.0 + (175.0 * (float)temperature_raw / 65535.0);
        *humidity = 100.0 * (float)humidity_raw / 65535.0;

        return 0; // Success
    }

    fprintf(stderr, "Failed to read sensor data after %d retries\n", MAX_RETRIES);
    return -1; // Failure
}

// Function to calculate CRC-8 checksum
unsigned char calculate_crc(unsigned char data[], int nbrOfBytes) {
    unsigned char crc = CRC8_INITIAL_VALUE;
    for (int i = 0; i < nbrOfBytes; i++) {
        crc ^= data[i];
        for (int bit = 8; bit > 0; --bit) {
            if (crc & 0x80)
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            else
                crc = (crc << 1);
        }
    }
    return crc;
}

// Function to validate CRC checksum
int validate_crc(unsigned char data[], int nbrOfBytes) {
    unsigned char crc_calculated = calculate_crc(data, nbrOfBytes - 1);
    return (crc_calculated != data[nbrOfBytes - 1]);
}

// Function to log data to file
int log_data(float temperature, float humidity) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
        fflush(log_file); // Ensure data is written to disk immediately
        return 0;
    } else {
        fprintf(stderr, "Log file is not open\n");
        return -1;
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function to close resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialization failed, exiting\n");
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file, exiting\n");
        cleanup();
        return 1;
    }

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        if (read_sensor_data(&sensor_data.temperature, &sensor_data.humidity) == 0) {
            if (log_data(sensor_data.temperature, sensor_data.humidity) != 0) {
                fprintf(stderr, "Failed to log data\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        gpioDelay(5000); // Wait 5 seconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

