#define TEMPERATURE_REG 0x02

// Global variables for I2C handle and log file
int i2c_handle = -1;
FILE *log_file = NULL;

// Function prototypes
int read_pressure(int i2c_handle);
int read_temperature(int i2c_handle);
char* get_iso8601_timestamp();
int log_data(const char *timestamp, int pressure, int temperature, FILE *log_file);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);

    // Close I2C handle if it's open
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }

    // Close log file if it's open
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio library
    gpioTerminate();

    exit(0);
}

// Function to read pressure from the sensor
int read_pressure(int i2c_handle) {
    char buf[2];
    int result = i2cReadI2CBlockData(i2c_handle, PRESSURE_REG, buf, 2);

    if (result < 0) {
        fprintf(stderr, "Error reading pressure data: %d\n", result);
        return -1; // Indicate error
    }

    // Combine the two bytes into a 16-bit value
    int pressure = (buf[0] << 8) | buf[1];
    return pressure;
}

// Function to read temperature from the sensor
int read_temperature(int i2c_handle) {
    char buf[2];
    int result = i2cReadI2CBlockData(i2c_handle, TEMPERATURE_REG, buf, 2);

    if (result < 0) {
        fprintf(stderr, "Error reading temperature data: %d\n", result);
        return -1; // Indicate error
    }

    // Combine the two bytes into a 16-bit value
    int temperature = (buf[0] << 8) | buf[1];
    return temperature;
}

