    while (1) {
        // Read pressure and temperature
        int pressure = read_pressure(i2c_handle);
        int temperature = read_temperature(i2c_handle);

        // Get timestamp
        char *timestamp = get_iso8601_timestamp();
        if (timestamp == NULL) {
            fprintf(stderr, "Error getting timestamp\n");
            continue; // Skip to the next iteration
