        // Log data
        if (pressure != -1 && temperature != -1) {
            if (log_data(timestamp, pressure, temperature, log_file) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
        } else {
            // Log error if read failed
            fprintf(log_file, "%s, ERROR: Failed to read sensor data\n", timestamp);
            fflush(log_file);
        }

        free(timestamp); // Free the allocated memory for the timestamp

        // Wait for 2 seconds
        gpioDelay(2000); // pigpio's delay function (milliseconds)
    }

