#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <sys/time.h>

// Constants
#define I2C_ADDR 0x48
#define GPIO_FAN 18
#define TEMP_THRESHOLD_ON 28.0
#define TEMP_THRESHOLD_OFF 26.0
#define BUFFER_SIZE 60

// Global variables
int i2c_handle;
volatile sig_atomic_t program_running = 1;

// Circular buffer
float temperature_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
float read_temperature();
void update_circular_buffer(float temperature);
float calculate_running_average();
void control_fan(float average_temperature);
void signal_handler(int signal);

// Function to read temperature from LM75B sensor
float read_temperature() {
    int raw_data;
    float temperature;

    raw_data = i2cReadWordData(i2c_handle, 0x00); // Read temperature register
    if (raw_data < 0) {
        fprintf(stderr, "Error reading temperature: %d\n", raw_data);
        return -100.0; // Indicate error
    }

    // Convert raw data to temperature (LM75B format)
    raw_data = ((raw_data >> 8) & 0xFF) | ((raw_data & 0xFF) << 8); // Swap bytes
    temperature = (float)(raw_data >> 5) * 0.125; // Shift right by 5 bits and multiply by 0.125

    return temperature;
}

// Function to update the circular buffer
void update_circular_buffer(float temperature) {
    temperature_buffer[buffer_index] = temperature;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Function to calculate the running average
float calculate_running_average() {
    float sum = 0.0;
    for (int i = 0; i < BUFFER_SIZE; i++) {
        sum += temperature_buffer[i];
    }
    return sum / BUFFER_SIZE;
}

// Function to control the cooling fan
void control_fan(float average_temperature) {
    static int fan_on = 0; // Keep track of fan state

    if (average_temperature > TEMP_THRESHOLD_ON && !fan_on) {
        if (gpioWrite(GPIO_FAN, 1) != 0) {
            fprintf(stderr, "Error turning fan ON\n");
        } else {
            fan_on = 1;
            printf("Fan turned ON\n");
        }
    } else if (average_temperature < TEMP_THRESHOLD_OFF && fan_on) {
