#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define STTS2004_ADDR 0x4A
#define TEMP_REG 0x00
#define GPIO_LED 17
#define TEMP_THRESHOLD_HIGH 28.0
#define TEMP_THRESHOLD_LOW 27.0
#define I2C_RETRY_COUNT 3

// Global variables
int i2c_handle;
volatile int running = 1;

// Function prototypes
int read_temperature(int i2c_handle, float *temperature);
void control_led(int gpio_pin, float temperature, float high_threshold, float low_threshold);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    running = 0;
    gpioWrite(GPIO_LED, 0); // Turn off LED
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

// Function to read temperature from STTS2004 sensor
int read_temperature(int i2c_handle, float *temperature) {
    char buf[2];
    int result;
    int retries = 0;

    while (retries < I2C_RETRY_COUNT) {
        result = i2cReadDevice(i2c_handle, buf, 2);
        if (result == 2) {
            // Success
            int16_t raw_temp = (buf[0] << 8) | buf[1];
            *temperature = (float)raw_temp / 16.0;
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read failed (attempt %d): %s\n", retries + 1, strerror(errno));
            retries++;
            gpioDelay(10000); // Wait 10ms before retrying
        }
    }

    fprintf(stderr, "I2C read failed after %d retries.\n", I2C_RETRY_COUNT);
    return -1; // Failure
}

// Function to control the LED with hysteresis
void control_led(int gpio_pin, float temperature, float high_threshold, float low_threshold) {
    static int led_state = 0; // 0 = off, 1 = on

    if (temperature > high_threshold && led_state == 0) {
        gpioWrite(gpio_pin, 1); // Turn LED on
        led_state = 1;
        printf("Temperature: %.2f°C, LED ON\n", temperature);
    } else if (temperature < low_threshold && led_state == 1) {
        gpioWrite(gpio_pin, 0); // Turn LED off
        led_state = 0;
        printf("Temperature: %.2f°C, LED OFF\n", temperature);
    }
}

int main() {
    float temperature;

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, STTS2004_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Set GPIO17 as output
    gpioSetMode(GPIO_LED, PI_OUTPUT);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        if (read_temperature(i2c_handle, &temperature) == 0) {
            printf("Temperature: %.2f°C\n", temperature);
            control_led(GPIO_LED, temperature, TEMP_THRESHOLD_HIGH, TEMP_THRESHOLD_LOW);
        } else {
            fprintf(stderr, "Failed to read temperature.\n");
        }

        gpioDelay(1000000); // Wait 1 second
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpioWrite(GPIO_LED, 0); // Turn off LED
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

