#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SI7021_ADDR 0x40
#define MEASURE_HUMIDITY 0xE5
#define MEASURE_TEMPERATURE 0xE3
#define RETRY_COUNT 3
#define SLEEP_INTERVAL 60 // seconds

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_sensor_data(unsigned char command, float *temperature, float *humidity);
int log_data(float temperature, float humidity);
void signal_handler(int signal);
void cleanup();

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Function to initialize the I2C bus
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SI7021_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read sensor data with retries
int read_sensor_data(unsigned char command, float *temperature, float *humidity) {
    char buf[2];
    int result, retries = 0;

    while (retries < RETRY_COUNT) {
        result = i2cWriteByte(i2c_handle, command);
        if (result != 0) {
            fprintf(stderr, "Error writing command: %d, retry %d\n", result, retries + 1);
            gpioDelay(10); // Small delay before retry
            retries++;
            continue;
        }

        gpioDelay(20); // Wait for measurement (at least 20ms)

        result = i2cReadDevice(i2c_handle, buf, 2);
        if (result != 2) {
            fprintf(stderr, "Error reading data: %d, retry %d\n", result, retries + 1);
            gpioDelay(10); // Small delay before retry
            retries++;
            continue;
        }

        // Convert raw data to temperature and humidity
        unsigned int raw_humidity = (buf[0] << 8) | buf[1];
        unsigned int raw_temperature = (buf[0] << 8) | buf[1];

        *humidity = (125.0 * raw_humidity / 65536.0) - 6.0;
        *temperature = (175.72 * raw_temperature / 65536.0) - 46.85;

        return 0; // Success
    }

    fprintf(stderr, "Failed to read sensor data after %d retries\n", RETRY_COUNT);
    return -1; // Failure
}

// Function to log data to file and stdout
int log_data(float temperature, float humidity) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
    fflush(log_file); // Ensure data is written immediately

    printf("%s,%.2f,%.2f\n", timestamp, temperature, humidity);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function to close I2C and file
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen("environment.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        gpioTerminate();
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialization failed\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        // Read temperature and humidity
        if (read_sensor_data(MEASURE_HUMIDITY, &sensor_data.temperature, &sensor_data.humidity) == 0) {
            // Log the data
            log_data(sensor_data.temperature, sensor_data.humidity);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
            fprintf(log_file, "Failed to read sensor data\n");
            fflush(log_file);
        }

        // Sleep for the specified interval
        sleep(SLEEP_INTERVAL);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

