#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// HDC1080 I2C address
#define HDC1080_ADDR 0x40

// HDC1080 register addresses
#define TEMPERATURE_REG 0x00
#define HUMIDITY_REG 0x01
#define CONFIGURATION_REG 0x02

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Function to initialize the HDC1080 sensor
int init_hdc1080() {
    // Configure the sensor (optional, using default settings)
    // Example: Set temperature and humidity resolution to 14 bits
    // uint16_t config_value = 0x0000; // Default configuration
    // if (i2cWriteWordData(i2c_handle, CONFIGURATION_REG, config_value) < 0) {
    //     fprintf(stderr, "Error writing to configuration register\n");
    //     return -1;
    // }
    return 0; // Initialization successful
}

// Function to read temperature and humidity from the HDC1080
int read_hdc1080(sensor_data_t *data) {
    // Trigger temperature and humidity measurement
    if (i2cWriteByteData(i2c_handle, CONFIGURATION_REG, 0x00) < 0) {
        fprintf(stderr, "Error triggering measurement\n");
        return -1;
    }

    // Wait for at least 20 ms for conversion
    gpioDelay(20000); // 20 ms

    // Read temperature data
    int raw_temperature = i2cReadWordData(i2c_handle, TEMPERATURE_REG);
    if (raw_temperature < 0) {
        fprintf(stderr, "Error reading temperature data\n");
        return -1;
    }

    // Read humidity data
    int raw_humidity = i2cReadWordData(i2c_handle, HUMIDITY_REG);
    if (raw_humidity < 0) {
        fprintf(stderr, "Error reading humidity data\n");
        return -1;
    }

    // Convert raw data to temperature and humidity
    data->temperature = ((float)raw_temperature / 65536.0) * 165.0 - 40.0;
    data->humidity = ((float)raw_humidity / 65536.0) * 100.0;

    return 0;
}

// Function to log data to a file
int log_data(float temperature, float humidity) {
    FILE *fp = fopen("enviro_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file\n");
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
    fclose(fp);
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, HDC1080_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Initialize HDC1080 sensor
    if (init_hdc1080() < 0) {
        fprintf(stderr, "HDC1080 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        // Read temperature and humidity
        if (read_hdc1080(&sensor_data) == 0) {
            // Log the data
            if (log_data(sensor_data.temperature, sensor_data.humidity) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        // Wait 5 seconds
        sleep(5);
    }

    // Close I2C bus and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    printf("Program terminated gracefully.\n");
    return 0;
}

