        return -1;
    }

    // Read humidity data
    int raw_humidity = i2cReadWordData(i2c_handle, HUMIDITY_REG);
    if (raw_humidity < 0) {
        fprintf(stderr, "Error reading humidity data\n");
        return -1;
    }

    // Convert raw data to temperature and humidity
    data->temperature = ((float)raw_temperature / 65536.0) * 165.0 - 40.0;
    data->humidity = ((float)raw_humidity / 65536.0) * 100.0;

