#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define STS40_ADDR 0x44
#define MEASURE_HIGH_PRECISION 0xFD
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INIT 0xFF
#define LOG_FILE "temperature_log.txt"

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;

// Function prototypes
int read_sts40_temperature(int i2c_fd, float *temperature);
int log_temperature(const char *timestamp, float temperature);
void signal_handler(int signal);
int crc8(const unsigned char *data, int len);

// CRC8 calculation function
int crc8(const unsigned char *data, int len) {
    unsigned char crc = CRC8_INIT;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read temperature from STS40 sensor
int read_sts40_temperature(int i2c_fd, float *temperature) {
    unsigned char cmd[1] = {MEASURE_HIGH_PRECISION};
    unsigned char data[6];

    // Send measurement command
    if (i2cWriteDevice(i2c_fd, cmd, 1) != 1) {
        fprintf(stderr, "Error: Failed to write measurement command to I2C device.\n");
        return -1;
    }

    // Wait for conversion (at least 10 ms)
    gpioDelay(10000); // 10 ms

    // Read 6 bytes of data (2 bytes temperature, 2 bytes humidity, 2 bytes CRC)
    if (i2cReadDevice(i2c_fd, data, 6) != 6) {
        fprintf(stderr, "Error: Failed to read data from I2C device.\n");
        return -1;
    }

    // CRC check for temperature data
    unsigned char temp_data[2] = {data[0], data[1]};
    unsigned char temp_crc = data[2];
    if (crc8(temp_data, 2) != temp_crc) {
        fprintf(stderr, "Error: CRC check failed for temperature data.\n");
        return -1;
    }

    // Convert raw data to temperature (Celsius)
    unsigned int raw_temperature = (data[0] << 8) | data[1];
    *temperature = -45.0 + (175.0 * raw_temperature) / 65535.0;

    return 0;
}

// Function to log temperature with timestamp
int log_temperature(const char *timestamp, float temperature) {
    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s, %.2f\n", timestamp, temperature);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);

    if (i2c_fd != -1) {
        i2cClose(i2c_fd);
    }

    if (log_file != NULL) {
        fclose(log_file);
    }

    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    // Open I2C device
    i2c_fd = i2cOpen(I2C_BUS, STS40_ADDR, 0);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error: Failed to open I2C device. Error code: %d\n", i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file.\n");
        i2cClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        float temperature;
        time_t rawtime;
        struct tm *timeinfo;
        char timestamp[30];

        // Read temperature
        if (read_sts40_temperature(i2c_fd, &temperature) == 0) {
            // Get current timestamp
            time(&rawtime);
            timeinfo = gmtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

            // Log temperature
            if (log_temperature(timestamp, temperature) != 0) {
                fprintf(stderr, "Error: Failed to log temperature.\n");
            }
        } else {
            fprintf(stderr, "Error: Failed to read temperature.\n");
        }

        // Wait 5 seconds
        sleep(5);
    }

    return 0;
}

