void cleanup();

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, size_t len) {
    uint8_t crc = CRC8_INITIAL;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Initialize I2C
int init_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SDP810_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Initialize logging
int init_logging() {
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return -1;
    }
    return 0;
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Read sensor data
int read_sensor_data(sensor_data_t *data) {
    uint8_t cmd[2] = {(MEASURE_CMD >> 8) & 0xFF, MEASURE_CMD & 0xFF};
    uint8_t buffer[9];

    if (i2cWriteDevice(i2c_handle, (char *)cmd, 2) != 2) {
        fprintf(stderr, "I2C write failed\n");
        return -1;
    }

    gpioDelay(50); // Wait 50ms

    if (i2cReadDevice(i2c_handle, (char *)buffer, 9) != 9) {
        fprintf(stderr, "I2C read failed\n");
        return -1;
    }

    // Extract data
    data->pressure = (int16_t)((buffer[0] << 8) | buffer[1]);
    uint8_t pressure_crc = buffer[2];
    data->temperature = (int16_t)((buffer[3] << 8) | buffer[4]);
    uint8_t temperature_crc = buffer[5];
    data->scale_factor[0] = buffer[6];
    data->scale_factor[1] = buffer[7];
    data->scale_factor[2] = buffer[8];

    // CRC validation
    uint8_t pressure_data[2] = {buffer[0], buffer[1]};
    uint8_t temperature_data[2] = {buffer[3], buffer[4]};

    if (crc8(pressure_data, 2) != pressure_crc) {
        fprintf(stderr, "Pressure CRC check failed\n");
        return -1;
    }

    if (crc8(temperature_data, 2) != temperature_crc) {
        fprintf(stderr, "Temperature CRC check failed\n");
        return -1;
    }

    return 0;
}

// Validate sensor data
int validate_data(const sensor_data_t *data) {
    // Add validation logic here if needed
    // For example, check if pressure is within a reasonable range
    return 0;
}

// Log data to file
int log_data(const sensor_data_t *data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, (float)data->pressure, (float)data->temperature) < 0) {
        fprintf(stderr, "Failed to write to log file\n");
        return -1;
    }
    fflush(log_file);
    return 0;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialization failed, exiting\n");
        return 1;
    }

    // Initialize logging
    if (init_logging() != 0) {
        fprintf(stderr, "Logging initialization failed, exiting\n");
        cleanup();
        return 1;
    }

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        if (read_sensor_data(&sensor_data) == 0) {
            if (validate_data(&sensor_data) == 0) {
                if (log_data(&sensor_data) != 0) {
                    fprintf(stderr, "Failed to log data\n");
                }
            } else {
                fprintf(stderr, "Data validation failed\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        sleep(1);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

