#define SCD40_CMD_READ_MEASUREMENT 0xE4B8
#define SCD40_CMD_STOP_PERIODIC_MEASUREMENT 0x3F86

// CRC-8 polynomial and initial value
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INITIAL_VALUE 0xFF

// Circular buffer size
#define BUFFER_SIZE 100

// Data structure for sensor readings
typedef struct {
    time_t timestamp;
    float co2;
    float temperature;
    float humidity;
} sensor_data_t;

// Circular buffer structure
typedef struct {
    sensor_data_t buffer[BUFFER_SIZE];
    int head;
    int tail;
    int count;
    pthread_mutex_t mutex;
} circular_buffer_t;

// Global variables
static int i2c_handle;
static volatile sig_atomic_t running = 1;
static circular_buffer_t data_buffer;
static FILE *error_log_file = NULL;

// Function prototypes
int init_i2c();
int start_periodic_measurement();
int read_measurement(uint16_t *co2, uint16_t *temperature, uint16_t *humidity);
uint8_t calculate_crc8(const uint8_t *data, size_t len);
int validate_crc(uint16_t data, uint8_t crc);
int stop_periodic_measurement();
void buffer_init(circular_buffer_t *buffer);
