    int result = i2cWriteDevice(i2c_handle, (char *)cmd, 2);
    if (result != 0) {
        log_error("Failed to start periodic measurement");
        return -1;
    }
    return 0;
}

// Read measurement data
int read_measurement(uint16_t *co2, uint16_t *temperature, uint16_t *humidity) {
    uint8_t cmd[2] = {(SCD40_CMD_READ_MEASUREMENT >> 8) & 0xFF, SCD40_CMD_READ_MEASUREMENT & 0xFF};
    int result = i2cWriteDevice(i2c_handle, (char *)cmd, 2);
    if (result != 0) {
        log_error("Failed to send read measurement command");
        return -1;
    }

    uint8_t data[9];
    result = i2cReadDevice(i2c_handle, (char *)data, 9);
    if (result != 9) {
