#define ICP10110_PRESSURE_MSB 0x00
#define ICP10110_PRESSURE_CSB 0x01
#define ICP10110_PRESSURE_LSB 0x02
#define ICP10110_TEMP_MSB 0x03
#define ICP10110_TEMP_CSB 0x04
#define ICP10110_TEMP_LSB 0x05
#define ICP10110_RESET 0x80

// Global variables
int i2c_handle;
FILE *data_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_sensor();
int read_sensor_data(float *pressure, float *temperature);
void format_data(float pressure, float temperature, char *buffer, size_t buffer_size);
void write_to_file(const char *data);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Caught SIGINT, exiting...\n");
        program_running = 0;
    }
}

// Function to initialize the ICP-10110 sensor
int initialize_sensor() {
    // Reset the sensor
    if (i2cWriteByteData(i2c_handle, ICP10110_RESET, 0x80) < 0) {
        fprintf(stderr, "Error: Failed to reset sensor.\n");
        return -1;
    }
    gpioDelay(100); // Wait for reset to complete

    // Verify sensor ID (optional)
    int who_am_i = i2cReadByteData(i2c_handle, ICP10110_WHO_AM_I);
    if (who_am_i < 0) {
        fprintf(stderr, "Error: Failed to read WHO_AM_I register.\n");
        return -1;
    }
    // Add your sensor ID check here (replace with actual value)
    if (who_am_i != 0x41) {
        fprintf(stderr, "Error: Incorrect WHO_AM_I value: 0x%02X\n", who_am_i);
        return -1;
    }

    return 0;
}

// Function to read pressure and temperature data from the sensor
int read_sensor_data(float *pressure, float *temperature) {
    unsigned char data[6];

    // Read pressure data (3 bytes)
    if (i2cReadI2CBlockData(i2c_handle, ICP10110_PRESSURE_MSB, (char *)data, 3) != 3) {
        fprintf(stderr, "Error: Failed to read pressure data.\n");
        return -1;
    }

    // Read temperature data (3 bytes)
    if (i2cReadI2CBlockData(i2c_handle, ICP10110_TEMP_MSB, (char *)data + 3, 3) != 3) {
        fprintf(stderr, "Error: Failed to read temperature data.\n");
        return -1;
    }

    // Combine pressure data
    int32_t pressure_raw = (data[0] << 16) | (data[1] << 8) | data[2];
    pressure_raw = pressure_raw >> 4; // Shift right by 4 bits

    // Combine temperature data
    int32_t temperature_raw = (data[3] << 16) | (data[4] << 8) | data[5];
    temperature_raw = temperature_raw >> 4; // Shift right by 4 bits

    // Convert raw data to pressure (hPa) and temperature (degrees Celsius)
    // Replace with actual conversion formulas from the datasheet
    *pressure = (float)pressure_raw / 4096.0; // Example conversion
    *temperature = (float)temperature_raw / 4096.0; // Example conversion

    return 0;
}

