    time_t rawtime;
    struct tm *timeinfo;
    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(buffer, buffer_size, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    snprintf(buffer + strlen(buffer), buffer_size - strlen(buffer), ",%.2f,%.2f\n", pressure, temperature);
}

