    i2c_handle = i2cOpen(1, ICP10110_ADDR, 0); // Bus 1, address 0x69, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus. %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor() != 0) {
        fprintf(stderr, "Error: Sensor initialization failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open the data file in append mode
    data_file = fopen("environmental_data.txt", "a");
    if (data_file == NULL) {
        fprintf(stderr, "Error: Failed to open data file.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Install signal handler for SIGINT
    signal(SIGINT, signal_handler);

    float pressure, temperature;
    char data_buffer[100]; // Buffer for formatted data

    // Main loop
    while (program_running) {
        gpioDelay(10); // Wait 10 ms

        // Read sensor data
        if (read_sensor_data(&pressure, &temperature) == 0) {
            // Format the data
            format_data(pressure, temperature, data_buffer, sizeof(data_buffer));

            // Write to file
            write_to_file(data_buffer);

            // Print to stdout
            printf("%s", data_buffer);
        } else {
            fprintf(stderr, "Error: Failed to read sensor data. Skipping sample.\n");
        }

        sleep(5); // Wait 5 seconds
    }

    // Close I2C bus and file
    i2cClose(i2c_handle);
    fclose(data_file);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

