    gettimeofday(&current_time, NULL);

    if (pressure < PRESSURE_THRESHOLD) {
        // 5 Hz blinking
        if ((current_time.tv_sec - last_blink_time.tv_sec) * 1000 + (current_time.tv_usec - last_blink_time.tv_usec) / 1000 > LOW_PRESSURE_BLINK_ON_TIME) {
            led_state = !led_state;
            gpioWrite(LED_GPIO, led_state);
