#define MLX90614_ADDR 0x5A
#define AMBIENT_TEMP_REG 0x06
#define OBJECT_TEMP_REG 0x07
#define FAN_GPIO 18
#define TEMP_THRESHOLD_HIGH 30.0
#define TEMP_THRESHOLD_LOW 28.0
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10

// Global variables
int i2c_handle;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int init_i2c();
int read_temperature(int reg);
float convert_to_celsius(int raw_temp);
void control_fan(float object_temp);
void log_temperature(float ambient_temp, float object_temp);
void signal_handler(int signal);
void cleanup();

// Structure to hold sensor data
typedef struct {
    float ambient_temp;
    float object_temp;
} sensor_data_t;

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        cleanup();
        return 1;
    }

    // Set FAN_GPIO as output
    gpioSetMode(FAN_GPIO, PI_OUTPUT);

    // Main loop
    while (program_running) {
        sensor_data_t sensor_data;

        // Read ambient temperature
        int raw_ambient_temp = read_temperature(AMBIENT_TEMP_REG);
        if (raw_ambient_temp == -1) {
            fprintf(stderr, "Failed to read ambient temperature\n");
            continue; // Skip to the next iteration
        }
        sensor_data.ambient_temp = convert_to_celsius(raw_ambient_temp);

        // Read object temperature
        int raw_object_temp = read_temperature(OBJECT_TEMP_REG);
        if (raw_object_temp == -1) {
            fprintf(stderr, "Failed to read object temperature\n");
            continue; // Skip to the next iteration
        }
        sensor_data.object_temp = convert_to_celsius(raw_object_temp);

        // Log temperature data
        log_temperature(sensor_data.ambient_temp, sensor_data.object_temp);

        // Control fan
        control_fan(sensor_data.object_temp);

        // Wait for 2 seconds
        gpioDelay(2000000); // 2 seconds in microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, MLX90614_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read temperature from the sensor with retries
int read_temperature(int reg) {
    int raw_temp = -1;
    for (int i = 0; i < RETRY_COUNT; i++) {
        raw_temp = i2cReadWordData(i2c_handle, reg);
        if (raw_temp >= 0) {
            break; // Success, exit retry loop
        } else {
            fprintf(stderr, "I2C read failed (attempt %d): %d\n", i + 1, raw_temp);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
        }
    }
    return raw_temp;
}

// Convert raw temperature to Celsius
float convert_to_celsius(int raw_temp) {
    return (float)raw_temp * 0.02 - 273.15;
}

// Control the cooling fan with hysteresis
void control_fan(float object_temp) {
    static int fan_on = 0; // Keep track of fan state

    if (object_temp > TEMP_THRESHOLD_HIGH && !fan_on) {
        gpioWrite(FAN_GPIO, 1); // Turn fan on
        fan_on = 1;
        printf("Fan ON (Object Temp: %.2f°C)\n", object_temp);
    } else if (object_temp < TEMP_THRESHOLD_LOW && fan_on) {
        gpioWrite(FAN_GPIO, 0); // Turn fan off
        fan_on = 0;
        printf("Fan OFF (Object Temp: %.2f°C)\n", object_temp);
    }
}

// Log temperature data to a file
void log_temperature(float ambient_temp, float object_temp) {
    FILE *fp = fopen("temperature_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, Ambient: %.2f°C, Object: %.2f°C\n", timestamp, ambient_temp, object_temp);
    fclose(fp);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    program_running = 0;
}

// Cleanup function to release resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioWrite(FAN_GPIO, 0); // Turn off fan
    gpioTerminate();
}

