#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

#define SHT40_ADDR 0x44
#define MEASURE_CMD 0xFD
#define PORT 8080
#define MAX_RETRIES 3

int i2c_handle;
int server_fd, new_socket;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signum) {
    printf("Caught signal %d, cleaning up...\n", signum);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (server_fd >= 0) {
        close(server_fd);
    }
    if (new_socket >= 0) {
        close(new_socket);
    }
    gpioTerminate();
    exit(0);
}

// Function to read temperature and humidity from SHT40
int read_sht40(float *temperature, float *humidity) {
    char buf[6];
    int result, retries = 0;

    while (retries < MAX_RETRIES) {
        result = i2cWriteByteData(i2c_handle, MEASURE_CMD, 0);
        if (result != 0) {
            fprintf(stderr, "Error writing to I2C: %d, retry %d\n", result, retries + 1);
            retries++;
            gpioDelay(10000); // 10ms delay
            continue;
        }

        gpioDelay(10000); // Wait for measurement (10ms)

        result = i2cReadI2CBlockData(i2c_handle, 0, buf, 6);
        if (result != 6) {
            fprintf(stderr, "Error reading from I2C: %d, retry %d\n", result, retries + 1);
            retries++;
            gpioDelay(10000); // 10ms delay
            continue;
        }

        // Convert raw data to temperature and humidity
        unsigned int temp_raw = (buf[0] << 8) | buf[1];
        unsigned int hum_raw = (buf[3] << 8) | buf[4];

        *temperature = -45.0 + 175.0 * (float)temp_raw / 65535.0;
        *humidity = 100.0 * (float)hum_raw / 65535.0;

        // Clamp humidity to 0-100%
        if (*humidity < 0.0) *humidity = 0.0;
        if (*humidity > 100.0) *humidity = 100.0;

        return 0; // Success
    }

    fprintf(stderr, "Failed to read SHT40 after %d retries\n", MAX_RETRIES);
    return -1; // Failure
}

// Function to format temperature and humidity into an HTML page
char *format_html(float temperature, float humidity) {
    char *html_page = malloc(256); // Allocate memory for the HTML page
    if (html_page == NULL) {
        fprintf(stderr, "Failed to allocate memory for HTML page\n");
        return NULL;
    }
    sprintf(html_page, "HTTP/1.1 200 OK\r\nContent-Type: text/html\r\n\r\n<html><body><h1>Temperature: %.2f &deg;C, Humidity: %.2f %%</h1></body></html>", temperature, humidity);
    return html_page;
}

// Function to handle client connection
void handle_client(int client_socket) {
    float temperature, humidity;
    char *html_page;

    if (read_sht40(&temperature, &humidity) == 0) {
        html_page = format_html(temperature, humidity);
        if (html_page != NULL) {
            send(client_socket, html_page, strlen(html_page), 0);
            free(html_page);
        } else {
            const char *error_page = "HTTP/1.1 500 Internal Server Error\r\nContent-Type: text/html\r\n\r\n<html><body><h1>Internal Server Error</h1></body></html>";
            send(client_socket, error_page, strlen(error_page), 0);
        }
    } else {
        const char *error_page = "HTTP/1.1 500 Internal Server Error\r\nContent-Type: text/html\r\n\r\n<html><body><h1>Internal Server Error</h1></body></html>";
        send(client_socket, error_page, strlen(error_page), 0);
    }

    close(client_socket);
}

int main() {
    struct sockaddr_in address;
    int addrlen = sizeof(address);
    int opt = 1;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, SHT40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Create socket
    if ((server_fd = socket(AF_INET, SOCK_STREAM, 0)) == 0) {
        perror("socket failed");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set socket options
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR | SO_REUSEPORT, &opt, sizeof(opt))) {
        perror("setsockopt");
        close(server_fd);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    // Bind socket to address
    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("bind failed");
        close(server_fd);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Listen for connections
    if (listen(server_fd, 3) < 0) {
        perror("listen");
        close(server_fd);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("Server listening on port %d\n", PORT);

    // Accept connections in a loop
    while (1) {
        if ((new_socket = accept(server_fd, (struct sockaddr *)&address, (socklen_t*)&addrlen)) < 0) {
            perror("accept");
            close(server_fd);
            i2cClose(i2c_handle);
            gpioTerminate();
            return 1;
        }

        handle_client(new_socket);
    }

    return 0;
}

