    int result;

    result = i2cReadI2CBlockData(i2c_handle, TEMP_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading temperature: %s (errno: %d)\n", strerror(errno), errno);
        return -1;
    }

    // Convert raw data to temperature (Celsius)
    int16_t raw_temp = (buf[0] << 4) | (buf[1] >> 4);
    *temperature = raw_temp * 0.0625;

    return 0;
}

