// HDC2010 I2C address
#define HDC2010_ADDR 0x40

// HDC2010 register addresses
#define TEMP_REG 0x00
#define HUMID_REG 0x02
#define MEAS_CONFIG_REG 0x0F

// Measurement configuration value (temperature and humidity, single measurement)
#define MEAS_CONFIG_VALUE 0x00

// Global flag to signal program termination
volatile sig_atomic_t terminate = 0;

// I2C handle
int i2c_handle;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Function to read a 16-bit value from the I2C bus
int read_i2c_word(int handle, uint8_t reg, uint16_t *value) {
    char buf[2];
    if (i2cWriteByte(handle, reg) != 0) {
        fprintf(stderr, "Error writing register address.\n");
        return -1;
    }
    if (i2cReadDevice(handle, buf, 2) != 2) {
        fprintf(stderr, "Error reading data from I2C.\n");
        return -1;
    }
    *value = (buf[0] << 8) | buf[1];
    return 0;
}

// Function to write a 16-bit value to the I2C bus
int write_i2c_word(int handle, uint8_t reg, uint16_t value) {
    char buf[3];
    buf[0] = reg;
    buf[1] = (value >> 8) & 0xFF;
    buf[2] = value & 0xFF;
    if (i2cWriteDevice(handle, buf, 3) != 3) {
        fprintf(stderr, "Error writing data to I2C.\n");
        return -1;
    }
    return 0;
}

// Function to read temperature and humidity from the HDC2010 sensor
int read_hdc2010(int handle, float *temperature, float *humidity) {
    uint16_t raw_temp, raw_humidity;
    int retries = 0;
    int status;

    // Trigger measurement
    while (retries < 3) {
        if (write_i2c_word(handle, MEAS_CONFIG_REG, MEAS_CONFIG_VALUE) == 0) {
            break;
        } else {
            fprintf(stderr, "I2C write error (trigger measurement), retrying...\n");
            retries++;
            gpioDelay(10000); // 10ms delay
        }
    }
    if (retries >= 3) {
        fprintf(stderr, "Failed to trigger measurement after multiple retries.\n");
        return -1;
    }

    // Wait for measurement to complete (timeout after 500ms)
    time_t start_time = time(NULL);
    while (time(NULL) - start_time < 0.5) {
        uint16_t config_value;
        retries = 0;
        while (retries < 3) {
            if (read_i2c_word(handle, MEAS_CONFIG_REG, &config_value) == 0) {
                break;
            } else {
                fprintf(stderr, "I2C read error (check status), retrying...\n");
                retries++;
                gpioDelay(10000); // 10ms delay
            }
        }
        if (retries >= 3) {
            fprintf(stderr, "Failed to read status after multiple retries.\n");
            return -1;
        }

        if ((config_value & 0x01) == 0) {
            break;
        }
        gpioDelay(10000); // 10ms delay
    }

    if (time(NULL) - start_time >= 0.5) {
        fprintf(stderr, "Timeout waiting for measurement to complete.\n");
        return -1;
    }

    // Read temperature
    retries = 0;
    while (retries < 3) {
        status = read_i2c_word(handle, TEMP_REG, &raw_temp);
        if (status == 0) {
            break;
        } else {
            fprintf(stderr, "I2C read error (temperature), retrying...\n");
            retries++;
            gpioDelay(10000); // 10ms delay
        }
    }
    if (retries >= 3) {
        fprintf(stderr, "Failed to read temperature after multiple retries.\n");
        return -1;
    }

    // Read humidity
    retries = 0;
    while (retries < 3) {
        status = read_i2c_word(handle, HUMID_REG, &raw_humidity);
        if (status == 0) {
            break;
        } else {
            fprintf(stderr, "I2C read error (humidity), retrying...\n");
            retries++;
            gpioDelay(10000); // 10ms delay
        }
    }
    if (retries >= 3) {
        fprintf(stderr, "Failed to read humidity after multiple retries.\n");
        return -1;
    }

    // Convert raw values to temperature and humidity
    *temperature = ((float)raw_temp / 65536.0) * 165.0 - 40.0;
    *humidity = ((float)raw_humidity / 65536.0) * 100.0;

    return 0;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, HDC2010_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    float temperature, humidity;

    // Main loop
    while (!terminate) {
        if (read_hdc2010(i2c_handle, &temperature, &humidity) == 0) {
            printf("Temperature: %.2f °C, Humidity: %.2f %%\n", temperature, humidity);
        } else {
            fprintf(stderr, "Failed to read sensor data.\n");
        }

        gpioDelay(5000000); // 5 seconds
    }

    // Close I2C bus and terminate pigpio library
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

