#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define SDP800_I2C_ADDRESS 0x25
#define MEASUREMENT_INTERVAL_MS 500
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INITIAL_VALUE 0xFF

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int16_t pressure;
    int16_t temperature;
} sensor_data_t;

// Function prototypes
int init_i2c();
int read_sdp800(sensor_data_t *data);
uint8_t calculate_crc(const uint8_t *data, size_t len);
int validate_crc(const uint8_t *data, size_t len);
void log_data(const sensor_data_t *data);
void signal_handler(int signal);
void cleanup();

// CRC-8 calculation function
uint8_t calculate_crc(const uint8_t *data, size_t len) {
    uint8_t crc = CRC8_INITIAL_VALUE;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// CRC-8 validation function
int validate_crc(const uint8_t *data, size_t len) {
    uint8_t crc = calculate_crc(data, len - 1);
    return (crc == data[len - 1]);
}

// Initialize I2C bus
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SDP800_I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Read data from SDP800 sensor
int read_sdp800(sensor_data_t *data) {
    uint8_t command[2] = {0x36, 0x2F}; // Trigger measurement command
    uint8_t buffer[6];

    // Send measurement command
    int write_result = i2cWriteDevice(i2c_handle, (char *)command, 2);
    if (write_result != 2) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }

    // Wait for measurement to complete
    gpioDelay(45000); // 45 ms

    // Read 6 bytes of data
    int read_result = i2cReadDevice(i2c_handle, (char *)buffer, 6);
    if (read_result != 6) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        return -1;
    }

    // Validate CRC for pressure data
    if (!validate_crc(buffer, 3)) {
        fprintf(stderr, "CRC check failed for pressure data\n");
        return -1;
    }

    // Validate CRC for temperature data
    if (!validate_crc(buffer + 3, 3)) {
        fprintf(stderr, "CRC check failed for temperature data\n");
