// Constants
#define I2C_BUS 1
#define SDP800_I2C_ADDRESS 0x25
#define MEASUREMENT_INTERVAL_MS 500
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INITIAL_VALUE 0xFF

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int16_t pressure;
    int16_t temperature;
} sensor_data_t;

