#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define GPIO_PIN 17
#define LOG_FILE "reflow_log.csv"
#define PROFILE_FILE "profile.txt"
#define SAMPLE_INTERVAL 1 // seconds

// PID Constants (Tune these values)
#define Kp 1.0
#define Ki 0.1
#define Kd 0.01

// Global Variables
static volatile int running = 1;
static int spi_handle;
static FILE *log_file;
static FILE *profile_file;
static float target_temperature = 0.0;
static int current_time = 0;

// Structure for PID controller
typedef struct {
    float Kp;
    float Ki;
    float Kd;
    float integral;
    float previous_error;
} PIDController;

PIDController pid;

// Function Prototypes
int read_max6675(int spi_handle);
float calculate_pid(float setpoint, float actual_temperature, PIDController *pid);
void set_relay_state(int gpio_pin, float duty_cycle);
void log_temperature(float temperature);
void load_profile();
void signal_handler(int signal);
void cleanup();

// Function to read temperature from MAX6675
int read_max6675(int spi_handle) {
    unsigned char data[2];
    int raw_data;
    float temperature = -1.0; // Initialize to an invalid value

    if (spiRead(spi_handle, data, 2) != 2) {
        fprintf(stderr, "Error reading from SPI.\n");
        return -1; // Indicate error
    }

    raw_data = (data[0] << 8) | data[1];

    // Check for fault bit (bit 2 of byte 1)
    if (raw_data & 0x00000004) {
        fprintf(stderr, "Thermocouple fault detected!\n");
        return -1; // Indicate error
    }

    // Extract temperature (bits 3-14, signed)
    raw_data >>= 3; // Shift right to remove fault bits and unused bits
    temperature = raw_data * 0.25;

    return (int)(temperature * 100); // Return temperature in 0.01 degree Celsius
}

// Function to calculate PID output
float calculate_pid(float setpoint, float actual_temperature, PIDController *pid) {
    float error = setpoint - actual_temperature;
    pid->integral += error * SAMPLE_INTERVAL;
    float derivative = (error - pid->previous_error) / SAMPLE_INTERVAL;
    float output = pid->Kp * error + pid->Ki * pid->integral + pid->Kd * derivative;
    pid->previous_error = error;
    return output;
}

// Function to set the relay state using PWM
void set_relay_state(int gpio_pin, float duty_cycle) {
    if (duty_cycle < 0.0) duty_cycle = 0.0;
    if (duty_cycle > 1.0) duty_cycle = 1.0;

    int pulse_width = (int)(duty_cycle * 1000000); // Convert duty cycle to microseconds
    gpioPWM(gpio_pin, pulse_width); // Set PWM duty cycle
}

// Function to log temperature to file
void log_temperature(float temperature) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp)-1, "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f\n", timestamp, temperature);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Function to load the temperature profile from file
void load_profile() {
    char line[256];
    float time_seconds, target_temp_celsius;

    // Read the first line to get the target temperature and time
    if (fgets(line, sizeof(line), profile_file) != NULL) {
        if (sscanf(line, "%f,%f", &time_seconds, &target_temp_celsius) == 2) {
            target_temperature = target_temp_celsius;
            current_time = (int)time_seconds;
            printf("Initial target temperature: %.2f C\n", target_temperature);
        } else {
            fprintf(stderr, "Error reading target temperature from profile file.\n");
            target_temperature = 0.0; // Set to a default value
        }
    } else {
        fprintf(stderr, "Error reading profile file or file is empty.\n");
        target_temperature = 0.0; // Set to a default value
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    running = 0;
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up resources...\n");
    gpioWrite(GPIO_PIN, 0); // Turn off relay
    gpioPWM(GPIO_PIN, 0); // Stop PWM
    spiClose(spi_handle);
    fclose(log_file);
    fclose(profile_file);
    gpioTerminate();
    printf("Cleanup complete. Exiting.\n");
}

int main() {
    int raw_temperature;
    float temperature_celsius;
    float pid_output;
    float duty_cycle;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as output
    gpioSetMode(GPIO_PIN, PI_OUTPUT);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 1MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open profile file
    profile_file = fopen(PROFILE_FILE, "r");
    if (profile_file == NULL) {
        fprintf(stderr, "Error opening profile file\n");
        fclose(log_file);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Load the temperature profile
    load_profile();

    // Initialize PID controller
    pid.Kp = Kp;
    pid.Ki = Ki;
    pid.Kd = Kd;
    pid.integral = 0.0;
    pid.previous_error = 0.0;

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (running) {
        // Read temperature from MAX6675
        raw_temperature = read_max6675(spi_handle);
        if (raw_temperature < 0) {
            fprintf(stderr, "Error reading temperature, using previous value.\n");
            // Consider using a default temperature or previous valid reading here
        } else {
            temperature_celsius = (float)raw_temperature / 100.0;
            printf("Temperature: %.2f C\n", temperature_celsius);

            // Calculate PID output
            pid_output = calculate_pid(target_temperature, temperature_celsius, &pid);

            // Scale PID output to duty cycle (0.0 to 1.0)
            duty_cycle = pid_output; // Assuming PID output is already in the correct range
            if (duty_cycle < 0.0) duty_cycle = 0.0;
            if (duty_cycle > 1.0) duty_cycle = 1.0;

            // Set relay state
            set_relay_state(GPIO_PIN, duty_cycle);

            // Log temperature
            log_temperature(temperature_celsius);

            // Update target temperature from profile
            char line[256];
            float time_seconds, target_temp_celsius;
            if (fgets(line, sizeof(line), profile_file) != NULL) {
                if (sscanf(line, "%f,%f", &time_seconds, &target_temp_celsius) == 2) {
                    if ((int)time_seconds == current_time) {
                        target_temperature = target_temp_celsius;
                        printf("Updated target temperature: %.2f C\n", target_temperature);
                    } else {
                        // Rewind the file pointer to the beginning
                        fseek(profile_file, 0, SEEK_SET);
                        // Read the first line again to reset the file pointer
                        fgets(line, sizeof(line), profile_file);
                        if (sscanf(line, "%f,%f", &time_seconds, &target_temp_celsius) == 2) {
                            target_temperature = target_temp_celsius;
                            current_time = (int)time_seconds;
                        }
                    }
                } else {
                    fprintf(stderr, "Error reading target temperature from profile file.\n");
                    target_temperature = 0.0; // Set to a default value
                }
            } else {
                fprintf(stderr, "End of profile file reached.\n");
                running = 0; // Exit the loop after reaching the end of the profile
            }

            // Wait for 1 second
            sleep(SAMPLE_INTERVAL);
        }
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

