#include <sys/stat.h>
#include <sys/types.h>
#include <pigpio.h>

// Constants
#define GPIO_HEATER 17
#define GPIO_PWM 18
#define PWM_FREQUENCY 1000 // Hz
#define LOG_FILE "greenhouse.log"
#define SENSOR_READ_INTERVAL 5 // seconds
#define LOG_WRITE_INTERVAL 5 // seconds

// PID Gains
float Kp = 1.0;
float Ki = 0.1;
float Kd = 0.01;

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;
static float setpoint = 25.0; // Default setpoint

// Function prototypes
float read_temperature(const char *sensor_id);
float calculate_pid(float setpoint, float actual_temperature, float *integral, float *previous_error);
void set_heater_state(int state);
void log_data(float average_temperature, float setpoint, float pid_output, int pwm_duty_cycle);
void signal_handler(int signal);
int discover_sensors(char sensor_ids[][20], int max_sensors);

// Signal handler
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    running = 0;
}

// Read temperature from DS18B20 sensor
float read_temperature(const char *sensor_id) {
    char filepath[100];
    snprintf(filepath, sizeof(filepath), "/sys/bus/w1/devices/%s/w1_slave", sensor_id);

    int fd = open(filepath, O_RDONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", filepath, strerror(errno));
        return -1000.0; // Indicate error
    }

    char buffer[256];
    ssize_t bytes_read = read(fd, buffer, sizeof(buffer) - 1);
    close(fd);

    if (bytes_read < 0) {
        fprintf(stderr, "Error reading %s: %s\n", filepath, strerror(errno));
        return -1000.0; // Indicate error
    }
    buffer[bytes_read] = '\0';

    // Check CRC
    char *crc_start = strstr(buffer, "YES");
    if (crc_start == NULL) {
        fprintf(stderr, "CRC check failed for sensor %s\n", sensor_id);
        return -1000.0; // Indicate error
    }

    char *temp_start = strstr(buffer, "t=");
