#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define AHT20_ADDR 0x38
#define GPIO_DEHUMIDIFIER 17
#define HUMIDITY_THRESHOLD_HIGH 60.0
#define HUMIDITY_THRESHOLD_LOW 55.0
#define MEASUREMENT_DELAY_MS 80
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10
#define POLL_INTERVAL_S 5

// Global variables
int i2c_fd = -1;
int dehumidifier_state = 0; // 0: off, 1: on

// Function prototypes
int aht20_init(int i2c_fd);
int aht20_trigger_measurement(int i2c_fd);
int aht20_read_data(int i2c_fd, uint8_t *data);
float aht20_convert_humidity(uint8_t *data);
void control_dehumidifier(float humidity);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, cleaning up...\n", signal);

    // Deactivate dehumidifier
    gpioWrite(GPIO_DEHUMIDIFIER, 0);

    // Close I2C connection
    if (i2c_fd != -1) {
        i2cClose(i2c_fd);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

// AHT20 initialization function
int aht20_init(int i2c_fd) {
    uint8_t init_cmd[3] = {0xBE, 0x08, 0x00};
    int result;

    result = i2cWriteDevice(i2c_fd, (char *)init_cmd, 3);
    if (result != 0) {
        fprintf(stderr, "Error: AHT20 initialization failed (error code %d)\n", result);
        return -1;
    }

    gpioDelay(10); // Wait for initialization to complete
    return 0;
}

// AHT20 trigger measurement function
int aht20_trigger_measurement(int i2c_fd) {
    uint8_t trigger_cmd[3] = {0xAC, 0x33, 0x00};
    int result;

    result = i2cWriteDevice(i2c_fd, (char *)trigger_cmd, 3);
    if (result != 0) {
        fprintf(stderr, "Error: AHT20 trigger measurement failed (error code %d)\n", result);
        return -1;
    }

    gpioDelay(MEASUREMENT_DELAY_MS); // Wait for measurement to complete
    return 0;
}

// AHT20 read data function
int aht20_read_data(int i2c_fd, uint8_t *data) {
    int result = i2cReadDevice(i2c_fd, (char *)data, 6);
    if (result != 6) {
        fprintf(stderr, "Error: AHT20 read data failed (read %d bytes, expected 6)\n", result);
        return -1;
    }
    return 0;
}

// AHT20 convert humidity function
float aht20_convert_humidity(uint8_t *data) {
    uint32_t humidity_raw = ((uint32_t)data[1] << 12) | ((uint32_t)data[2] << 4) | (data[3] >> 4);
    float humidity = ((float)humidity_raw / 0x100000) * 100;
    return humidity;
}

// Control dehumidifier function
void control_dehumidifier(float humidity) {
    if (humidity > HUMIDITY_THRESHOLD_HIGH && dehumidifier_state == 0) {
        gpioWrite(GPIO_DEHUMIDIFIER, 1); // Activate dehumidifier
        dehumidifier_state = 1;
        printf("Dehumidifier activated (Humidity: %.2f%%)\n", humidity);
    } else if (humidity < HUMIDITY_THRESHOLD_LOW && dehumidifier_state == 1) {
        gpioWrite(GPIO_DEHUMIDIFIER, 0); // Deactivate dehumidifier
        dehumidifier_state = 0;
        printf("Dehumidifier deactivated (Humidity: %.2f%%)\n", humidity);
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO17 as output
    gpioSetMode(GPIO_DEHUMIDIFIER, PI_OUTPUT);
    gpioWrite(GPIO_DEHUMIDIFIER, 0); // Ensure dehumidifier is off initially

    // Open I2C connection
    i2c_fd = i2cOpen(I2C_BUS, AHT20_ADDR, 0);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error: Could not open I2C device (error code %d)\n", i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Initialize AHT20 sensor
    if (aht20_init(i2c_fd) != 0) {
        fprintf(stderr, "Error: AHT20 initialization failed\n");
        i2cClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        uint8_t data[6];
        float humidity;
        time_t rawtime;
        struct tm *timeinfo;
        char timestamp[80];

        // Trigger measurement
        if (aht20_trigger_measurement(i2c_fd) != 0) {
            fprintf(stderr, "Error: Failed to trigger measurement\n");
            continue; // Skip to the next iteration
        }

        // Read data with retries
        int retry = 0;
        while (retry < RETRY_COUNT) {
            if (aht20_read_data(i2c_fd, data) == 0) {
                // Verify status byte
                if ((data[0] & 0x80) == 0) {
                    // Convert humidity
                    humidity = aht20_convert_humidity(data);

                    // Get current timestamp
                    time(&rawtime);
                    timeinfo = localtime(&rawtime);
                    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

                    // Log humidity reading
                    printf("%s - Humidity: %.2f%%\n", timestamp, humidity);

                    // Control dehumidifier
                    control_dehumidifier(humidity);

                    break; // Exit retry loop on success
                } else {
                    fprintf(stderr, "Error: AHT20 not calibrated or busy\n");
                    break; // Exit retry loop if sensor is busy
                }
            } else {
                fprintf(stderr, "Error: Failed to read data, retry %d\n", retry + 1);
                retry++;
                gpioDelay(RETRY_DELAY_MS);
            }
        }

        if (retry == RETRY_COUNT) {
            fprintf(stderr, "Error: Failed to read AHT20 data after %d retries\n", RETRY_COUNT);
        }

        gpioDelay(POLL_INTERVAL_S * 1000); // Wait for the next poll interval
    }

    return 0;
}

