// Constants
#define HTU21D_ADDR 0x40
#define TRIGGER_HUMIDITY_HOLD 0xE5
#define SERVER_URL "http://api.example.com/humidity"
#define SERVER_PORT 80
#define POLL_INTERVAL 60 // seconds

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_humidity();
char* format_json(float humidity);
int send_http_post(const char* json_data);
void signal_handler(int signal);
int setup();
void cleanup();

// Structure to hold sensor data and configuration
typedef struct {
    int i2c_address;
    char* server_url;
    int poll_interval;
} sensor_config_t;

// Function to read humidity from HTU21D sensor
int read_humidity() {
    unsigned char buf[3];
    int result;
    unsigned int raw_humidity;
    float humidity;

    // Send trigger humidity measurement command
    result = i2cWriteByte(i2c_handle, TRIGGER_HUMIDITY_HOLD);
    if (result != 0) {
        syslog(LOG_ERR, "I2C write error: %s", strerror(errno));
        return -1;
    }

    // Wait for measurement (at least 50ms)
    gpioDelay(50000); // 50ms

    // Read 3 bytes of data
    result = i2cReadDevice(i2c_handle, (char *)buf, 3);
    if (result != 3) {
        syslog(LOG_ERR, "I2C read error: %s", strerror(errno));
        return -1;
    }

    // Convert raw data to humidity
    raw_humidity = ((unsigned int)buf[0] << 8) | (unsigned int)buf[1];
    humidity = -6.0 + 125.0 * (raw_humidity / 65536.0);

    // CRC check
    unsigned char checksum = buf[2];
    unsigned char calculated_checksum = 0;
    unsigned char data[2] = {buf[0], buf[1]};

    for (int i = 0; i < 2; i++) {
        calculated_checksum ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (calculated_checksum & 0x80) {
                calculated_checksum = (calculated_checksum << 1) ^ 0x131; // Polynomial X^8 + X^5 + X^4 + 1
            } else {
                calculated_checksum <<= 1;
            }
        }
    }

    calculated_checksum ^= 0xFF; // Invert the checksum

    if (calculated_checksum != checksum) {
        syslog(LOG_ERR, "CRC check failed. Received: 0x%02X, Calculated: 0x%02X", checksum, calculated_checksum);
        return -1;
    }

    return (int)humidity;
}

// Function to format humidity data into a JSON string
char* format_json(float humidity) {
    char* json_string = (char*)malloc(100 * sizeof(char)); // Allocate memory for the JSON string
    if (json_string == NULL) {
        syslog(LOG_ERR, "Failed to allocate memory for JSON string");
        return NULL;
    }
    snprintf(json_string, 100, "{\"humidity\": %.2f}", humidity);
    return json_string;
}

// Function to send HTTP POST request
int send_http_post(const char* json_data) {
    int sock = 0, valread;
    struct sockaddr_in serv_addr;
    char buffer[1024] = {0};

    if ((sock = socket(AF_INET, SOCK_STREAM, 0)) < 0) {
        syslog(LOG_ERR, "Socket creation error: %s", strerror(errno));
        return -1;
    }

    serv_addr.sin_family = AF_INET;
    serv_addr.sin_port = htons(SERVER_PORT);

    // Convert IPv4 and IPv6 addresses from text to binary form
    if (inet_pton(AF_INET, "127.0.0.1", &serv_addr.sin_addr) <= 0) {
        syslog(LOG_ERR, "Invalid address/ Address not supported: %s", strerror(errno));
        close(sock);
        return -1;
    }

    if (connect(sock, (struct sockaddr *)&serv_addr, sizeof(serv_addr)) < 0) {
        syslog(LOG_ERR, "Connection Failed: %s", strerror(errno));
        close(sock);
        return -1;
    }

    char request[512];
    snprintf(request, sizeof(request), 
             "POST /humidity HTTP/1.1\r\n" 
             "Host: 127.0.0.1\r\n" 
             "Content-Type: application/json\r\n" 
             "Content-Length: %ld\r\n" 
             "\r\n" 
             "%s", strlen(json_data), json_data);

    if (send(sock, request, strlen(request), 0) < 0) {
        syslog(LOG_ERR, "Send failed: %s", strerror(errno));
        close(sock);
        return -1;
    }

    valread = recv(sock, buffer, sizeof(buffer) - 1, 0);
    if (valread < 0) {
        syslog(LOG_ERR, "Receive failed: %s", strerror(errno));
        close(sock);
        return -1;
    }
    buffer[valread] = '\0';

    syslog(LOG_INFO, "HTTP Response: %s", buffer);
    close(sock);
    return 0;
}

// Signal handler function
void signal_handler(int signal) {
    syslog(LOG_INFO, "Received signal %d, terminating...", signal);
    terminate = 1;
}

// Setup function to initialize pigpio and I2C
int setup() {
    openlog("humidity_sensor", LOG_PID | LOG_CONS, LOG_USER);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(1, HTU21D_ADDR, 0); // Bus 1, address 0x40, no flags
    if (i2c_handle < 0) {
        syslog(LOG_ERR, "Failed to open I2C device: %s", strerror(errno));
        gpioTerminate();
        return -1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    return 0;
}

// Cleanup function to close I2C and terminate pigpio
void cleanup() {
    syslog(LOG_INFO, "Cleaning up...");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    closelog();
}

int main() {
    if (setup() != 0) {
        return 1;
    }

    while (!terminate) {
        int humidity = read_humidity();
        if (humidity >= 0) {
            char* json_data = format_json((float)humidity);
            if (json_data != NULL) {
                if (send_http_post(json_data) != 0) {
                    syslog(LOG_ERR, "Failed to send HTTP POST");
                }
                free(json_data);
            } else {
                syslog(LOG_ERR, "Failed to format JSON data");
            }
        } else {
            syslog(LOG_ERR, "Failed to read humidity");
        }

        sleep(POLL_INTERVAL);
    }

    cleanup();
    return 0;
}

