#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// BMP280 I2C address
#define BMP280_I2C_ADDR 0x76

// BMP280 register addresses
#define BMP280_REG_CHIPID 0xD0
#define BMP280_REG_RESET 0xE0
#define BMP280_REG_CTRL_MEAS 0xF4
#define BMP280_REG_CONFIG 0xF5
#define BMP280_REG_PRESS_MSB 0xF7
#define BMP280_REG_PRESS_LSB 0xF8
#define BMP280_REG_PRESS_XLSB 0xF9
#define BMP280_REG_TEMP_MSB 0xFA
#define BMP280_REG_TEMP_LSB 0xFB
#define BMP280_REG_TEMP_XLSB 0xFC

// BMP280 calibration data registers
#define BMP280_REG_CALIB_00 0x88

// BMP280 chip ID
#define BMP280_CHIP_ID 0x58

// Oversampling settings
#define BMP280_OVERSAMPLING_TEMP 2 // x2
#define BMP280_OVERSAMPLING_PRESS 5 // x16
#define BMP280_MODE_NORMAL 3

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Calibration data structure
typedef struct {
    uint16_t dig_T1;
    int16_t dig_T2;
    int16_t dig_T3;
    uint16_t dig_P1;
    int16_t dig_P2;
    int16_t dig_P3;
    int16_t dig_P4;
    int16_t dig_P5;
    int16_t dig_P6;
    int16_t dig_P7;
    int16_t dig_P8;
    int16_t dig_P9;
} bmp280_calib_data;

bmp280_calib_data calib;

// Function prototypes
int init_bmp280();
int read_calibration_data();
int read_raw_data(int32_t *temperature, int32_t *pressure);
double compensate_temperature(int32_t raw_temperature);
double compensate_pressure(int32_t raw_pressure, int32_t raw_temperature);
void log_pressure(double pressure);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

// Initialize BMP280 sensor
int init_bmp280() {
    int retries = 3;
    int result = -1;

    while (retries > 0) {
        i2c_handle = i2cOpen(1, BMP280_I2C_ADDR, 0);
        if (i2c_handle < 0) {
            fprintf(stderr, "Error opening I2C device: %d. Retrying...\n", i2c_handle);
            gpioDelay(100000); // 100ms delay
            retries--;
            continue;
        }

        // Verify chip ID
        char chip_id;
        result = i2cReadI2CBlockData(i2c_handle, BMP280_REG_CHIPID, &chip_id, 1);
        if (result != 1) {
            fprintf(stderr, "Error reading chip ID: %d. Retrying...\n", result);
            i2cClose(i2c_handle);
            i2c_handle = -1;
            gpioDelay(100000); // 100ms delay
            retries--;
            continue;
        }

        if (chip_id != BMP280_CHIP_ID) {
            fprintf(stderr, "Incorrect chip ID: 0x%02X. Expected 0x%02X. Retrying...\n", chip_id, BMP280_CHIP_ID);
            i2cClose(i2c_handle);
            i2c_handle = -1;
            gpioDelay(100000); // 100ms delay
            retries--;
            continue;
        }

        // Read calibration data
        if (read_calibration_data() != 0) {
            fprintf(stderr, "Error reading calibration data. Retrying...\n");
            i2cClose(i2c_handle);
            i2c_handle = -1;
            gpioDelay(100000); // 100ms delay
            retries--;
            continue;
        }

        // Set oversampling and mode
        char ctrl_meas = (BMP280_OVERSAMPLING_TEMP << 5) | (BMP280_OVERSAMPLING_PRESS << 2) | BMP280_MODE_NORMAL;
        result = i2cWriteI2CBlockData(i2c_handle, BMP280_REG_CTRL_MEAS, &ctrl_meas, 1);
        if (result != 1) {
            fprintf(stderr, "Error writing control register: %d. Retrying...\n", result);
            i2cClose(i2c_handle);
            i2c_handle = -1;
            gpioDelay(100000); // 100ms delay
            retries--;
            continue;
        }

        printf("BMP280 initialized successfully.\n");
        return 0; // Success
    }

    fprintf(stderr, "Failed to initialize BMP280 after multiple retries.\n");
    return -1; // Failure
}

// Read calibration data from the sensor
int read_calibration_data() {
    char data[24];
    int result = i2cReadI2CBlockData(i2c_handle, BMP280_REG_CALIB_00, data, 24);
    if (result != 24) {
        fprintf(stderr, "Error reading calibration data: %d\n", result);
        return -1;
    }

    calib.dig_T1 = (uint16_t)data[0] | ((uint16_t)data[1] << 8);
    calib.dig_T2 = (int16_t)data[2] | ((int16_t)data[3] << 8);
    calib.dig_T3 = (int16_t)data[4] | ((int16_t)data[5] << 8);
    calib.dig_P1 = (uint16_t)data[6] | ((uint16_t)data[7] << 8);
    calib.dig_P2 = (int16_t)data[8] | ((int16_t)data[9] << 8);
    calib.dig_P3 = (int16_t)data[10] | ((int16_t)data[11] << 8);
    calib.dig_P4 = (int16_t)data[12] | ((int16_t)data[13] << 8);
    calib.dig_P5 = (int16_t)data[14] | ((int16_t)data[15] << 8);
    calib.dig_P6 = (int16_t)data[16] | ((int16_t)data[17] << 8);
    calib.dig_P7 = (int16_t)data[18] | ((int16_t)data[19] << 8);
    calib.dig_P8 = (int16_t)data[20] | ((int16_t)data[21] << 8);
    calib.dig_P9 = (int16_t)data[22] | ((int16_t)data[23] << 8);

    return 0;
}

// Read raw temperature and pressure data from the sensor
int read_raw_data(int32_t *temperature, int32_t *pressure) {
    char data[6];
    int result = i2cReadI2CBlockData(i2c_handle, BMP280_REG_PRESS_MSB, data, 6);
    if (result != 6) {
        fprintf(stderr, "Error reading raw data: %d\n", result);
        return -1;
    }

    *pressure = ((int32_t)data[0] << 12) | ((int32_t)data[1] << 4) | ((int32_t)data[2] >> 4);
    *temperature = ((int32_t)data[3] << 12) | ((int32_t)data[4] << 4) | ((int32_t)data[5] >> 4);

    return 0;
}

// Compensate temperature using Bosch formula
double compensate_temperature(int32_t raw_temperature) {
    double var1, var2, T;
    double T1 = (double)calib.dig_T1;
    double T2 = (double)calib.dig_T2;
    double T3 = (double)calib.dig_T3;
    double t_fine;

    var1 = (((double)raw_temperature)/16384.0 - T1/1024.0) * T2;
    var2 = ((((double)raw_temperature)/131072.0 - T1/8192.0) * (((double)raw_temperature)/131072.0 - T1/8192.0)) * T3;
    t_fine = var1 + var2;
    T = (t_fine / 5120.0);
    return T;
}

// Compensate pressure using Bosch formula
double compensate_pressure(int32_t raw_pressure, int32_t raw_temperature) {
    double var1, var2, p;
    double T1 = (double)calib.dig_T1;
    double T2 = (double)calib.dig_T2;
    double T3 = (double)calib.dig_T3;
    double P1 = (double)calib.dig_P1;
    double P2 = (double)calib.dig_P2;
    double P3 = (double)calib.dig_P3;
    double P4 = (double)calib.dig_P4;
    double P5 = (double)calib.dig_P5;
    double P6 = (double)calib.dig_P6;
    double P7 = (double)calib.dig_P7;
    double P8 = (double)calib.dig_P8;
    double P9 = (double)calib.dig_P9;
    double t_fine;

    var1 = (((double)raw_temperature)/16384.0 - T1/1024.0) * T2;
    var2 = ((((double)raw_temperature)/131072.0 - T1/8192.0) * (((double)raw_temperature)/131072.0 - T1/8192.0)) * T3;
    t_fine = var1 + var2;

    var1 = (t_fine/2.0) - 64000.0;
    var2 = var1 * var1 * P6 / 32768.0;
    var2 = var2 + var1 * P5 * 2.0;
    var2 = (var2/4.0)+(P4 * 65536.0);
    var1 = (P3 * var1 * var1 / 524288.0 + P2 * var1) / 524288.0;
    var1 = (1.0 + var1 / 32768.0)*P1;

    if (var1 == 0)
    {
        return 0;
    }

    p = 1048576.0 - (double)raw_pressure;
    p = (p - (var2 / 4096.0)) * 6250.0 / var1;
    var1 = P9 * p * p / 2147483648.0;
    var2 = p * P8 / 32768.0;
    p = p + (var1 + var2 + P7) / 16.0;

    return p/100.0; // in hPa
}

// Log pressure to file
void log_pressure(double pressure) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s, %.2f hPa\n", timestamp, pressure);
    fflush(log_file); // Ensure data is written to file immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open log file
    log_file = fopen("pressure_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    // Initialize BMP280 sensor
    if (init_bmp280() != 0) {
        fprintf(stderr, "BMP280 initialization failed!\n");
        cleanup();
