            fprintf(stderr, "Error initializing AHT20 (attempt %d): %s\n", retries + 1, strerror(errno));
            gpioDelay(RETRY_DELAY * 1000); // Delay in microseconds
            retries++;
        }
    }
    if (retries == MAX_RETRIES) {
        fprintf(stderr, "Failed to initialize AHT20 after %d retries.\n", MAX_RETRIES);
        return -1;
    }

    // Trigger measurement
    retries = 0;
    while (retries < MAX_RETRIES) {
        result = i2cWriteDevice(handle, measure_cmd, 3);
        if (result == 0) {
            gpioDelay(80000); // Wait for measurement (80ms)
            break;
        } else {
            fprintf(stderr, "Error triggering measurement (attempt %d): %s\n", retries + 1, strerror(errno));
            gpioDelay(RETRY_DELAY * 1000); // Delay in microseconds
            retries++;
        }
    }
    if (retries == MAX_RETRIES) {
        fprintf(stderr, "Failed to trigger measurement after %d retries.\n", MAX_RETRIES);
        return -1;
    }

    // Read measurement data
    retries = 0;
    while (retries < MAX_RETRIES) {
        result = i2cReadDevice(handle, buf, 6);
        if (result == 6) {
            // Check status bit (bit 7 of byte 0)
            if (buf[0] & 0x80) {
                fprintf(stderr, "AHT20 busy.\n");
                return -1;
            }

            // Convert raw data to humidity
            unsigned long humidity_raw = ((unsigned long)buf[1] << 12) | ((unsigned long)buf[2] << 4) | (buf[3] >> 4);
            *humidity = (float)humidity_raw / 0x100000 * 100;
            return 0;
        } else {
            fprintf(stderr, "Error reading humidity (attempt %d): %s\n", retries + 1, strerror(errno));
            gpioDelay(RETRY_DELAY * 1000); // Delay in microseconds
            retries++;
        }
    }
    fprintf(stderr, "Failed to read humidity after %d retries.\n", MAX_RETRIES);
    return -1;
}

// Function to read motion from PIR sensor
int read_motion(int gpio) {
    return gpioRead(gpio);
}

// Function to log data to CSV file
int log_data(FILE *fp, float temperature, float humidity, int motion_detected) {
    char *timestamp = get_timestamp();
    if (timestamp == NULL) {
        fprintf(stderr, "Failed to get timestamp.\n");
        return -1;
    }

    int result = fprintf(fp, "%s,%.2f,%.2f,%d\n", timestamp, temperature, humidity, motion_detected);
    free(timestamp);

    if (result < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    if (i2c_handle_tmp117 >= 0) {
        i2cClose(i2c_handle_tmp117);
    }
    if (i2c_handle_aht20 >= 0) {
        i2cClose(i2c_handle_aht20);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

// Function to get the current timestamp
char* get_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(21 * sizeof(char)); // YYYY-MM-DDTHH:MM:SSZ\0

    if (timestamp == NULL) {
        perror("Failed to allocate memory for timestamp");
        return NULL;
    }

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, 21, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set PIR GPIO as input
    gpioSetMode(PIR_GPIO, PI_INPUT);

    // Initialize I2C
    i2c_handle_tmp117 = init_i2c(I2C_BUS, TMP117_ADDR);
    i2c_handle_aht20 = init_i2c(I2C_BUS, AHT20_ADDR);

    // Open log file
    char filename[50];
    time_t t = time(NULL);
    struct tm tm = *gmtime(&t);
    sprintf(filename, "log_%04d%02d%02d.csv", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday);
    log_file = fopen(filename, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, CSV_HEADER);
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    float temperature, humidity;
    int motion_detected;
    int aht20_init_failed = 0;

    while (!terminate) {
        // Read sensor data
        temperature = read_temperature(i2c_handle_tmp117);
        if (read_humidity(i2c_handle_aht20, &humidity) != 0) {
            if (!aht20_init_failed) {
                fprintf(stderr, "AHT20 sensor not responding. Continuing without humidity data.\n");
                aht20_init_failed = 1;
            }
            humidity = -1.0; // Indicate error
        }
        motion_detected = read_motion(PIR_GPIO);

        // Log data
        if (temperature > -999.0 && humidity > -1.0) { // Check for valid sensor readings
            if (log_data(log_file, temperature, humidity, motion_detected) != 0) {
                fprintf(stderr, "Error logging data.\n");
            }
        } else {
            fprintf(stderr, "Skipping logging due to invalid sensor readings.\n");
        }

        fflush(log_file); // Flush the buffer to ensure data is written to the file

        // Check for midnight to create a new log file
        time(&t);
        timeinfo = gmtime(&t);
        char *current_date = (char*)malloc(11 * sizeof(char));
        strftime(current_date, 11, "%Y-%m-%d", timeinfo);

        char *log_date = (char*)malloc(11 * sizeof(char));
        strftime(log_date, 11, "%Y-%m-%d", gmtime(&t));

        if (strcmp(log_date, current_date) != 0) {
            fclose(log_file);
            free(filename);
            sprintf(filename, "log_%04d%02d%02d.csv", timeinfo->tm_year + 1900, timeinfo->tm_mon + 1, timeinfo->tm_mday);
            log_file = fopen(filename, "a");
            if (log_file == NULL) {
                fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
                cleanup();
                return 1;
            }
            fprintf(log_file, CSV_HEADER);
        }
        free(current_date);
        free(log_date);

        gpioDelay(SAMPLE_INTERVAL * 1000000); // Delay in microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

