// Define GPIO pins
#define RAIN_SENSOR_PIN 17
#define MOTOR_ENA_PIN 22
#define MOTOR_IN1_PIN 23
#define MOTOR_IN2_PIN 24

// Define motor run time (seconds)
#define MOTOR_RUN_TIME 5

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_rain_sensor();
void control_motor(int run_time);
void log_event(const char *message);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    log_event("Received signal, stopping motor and exiting...");
    control_motor(0); // Stop the motor
    gpioTerminate(); // Release GPIO resources
    exit(0);
}

// Function to read the rain sensor
int read_rain_sensor() {
    int sensor_value = gpioRead(RAIN_SENSOR_PIN);
    if (sensor_value < 0) {
        log_event("Error reading rain sensor");
        return -1; // Indicate an error
    }
    return sensor_value;
}

// Function to control the motor
void control_motor(int run_time) {
    if (run_time > 0) {
        // Drive motor forward
        gpioWrite(MOTOR_IN1_PIN, 1);
        gpioWrite(MOTOR_IN2_PIN, 0);
        gpioPWM(MOTOR_ENA_PIN, 255); // Full speed
        log_event("Motor started");
        gpioDelay(run_time * 1000000); // Run for specified time (microseconds)
        gpioPWM(MOTOR_ENA_PIN, 0); // Stop motor
        log_event("Motor stopped");
    } else {
        // Stop motor
        gpioWrite(MOTOR_IN1_PIN, 0);
        gpioWrite(MOTOR_IN2_PIN, 0);
        gpioPWM(MOTOR_ENA_PIN, 0);
        log_event("Motor stopped (manual stop)");
    }
}

// Function to log events with timestamps
void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    printf("[%s] %s\n", timestamp, message);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(RAIN_SENSOR_PIN, PI_INPUT);
    gpioSetMode(MOTOR_ENA_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_IN1_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_IN2_PIN, PI_OUTPUT);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_event("Program started");

    // Main loop
    while (program_running) {
        int rain_detected = (read_rain_sensor() == 0); // Rain detected if sensor reads LOW

        if (rain_detected) {
            log_event("Rain detected!");
            control_motor(MOTOR_RUN_TIME);
        }

        gpioDelay(2000000); // Poll every 2 seconds (microseconds)
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpioTerminate();
    return 0;
}

