#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for RGB LED
#define RED_PIN   17
#define GREEN_PIN 22
#define BLUE_PIN  27

// Define PWM frequency
#define PWM_FREQUENCY 1000

// Define CPU stats file
#define CPU_STATS_FILE "/proc/stat"

// Global variables for signal handling
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_cpu_stats(unsigned long long *user, unsigned long long *nice, unsigned long long *system, unsigned long long *idle, unsigned long long *iowait, unsigned long long *irq, unsigned long long *softirq);
float calculate_cpu_load(unsigned long long prev_user, unsigned long long prev_nice, unsigned long long prev_system, unsigned long long prev_idle, unsigned long long prev_iowait, unsigned long long prev_irq, unsigned long long prev_softirq, unsigned long long user, unsigned long long nice, unsigned long long system, unsigned long long idle, unsigned long long iowait, unsigned long long irq, unsigned long long softirq);
void map_load_to_color(float load, unsigned char *red, unsigned char *green, unsigned char *blue);
int set_led_color(unsigned char red, unsigned char green, unsigned char blue);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, turning off LED and exiting.\n");
    program_running = 0;
    set_led_color(0, 0, 0); // Turn off LED
    gpioTerminate();       // Terminate pigpio
    exit(0);
}

// Function to read CPU statistics from /proc/stat
int read_cpu_stats(unsigned long long *user, unsigned long long *nice, unsigned long long *system, unsigned long long *idle, unsigned long long *iowait, unsigned long long *irq, unsigned long long *softirq) {
    FILE *fp;
    char line[256];

    fp = fopen(CPU_STATS_FILE, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open %s\n", CPU_STATS_FILE);
        return -1;
    }

    // Read the first line of the file
    if (fgets(line, sizeof(line), fp) == NULL) {
        fprintf(stderr, "Error: Could not read from %s\n", CPU_STATS_FILE);
        fclose(fp);
        return -1;
    }

    // Parse the CPU statistics
    if (sscanf(line, "cpu  %llu %llu %llu %llu %llu %llu %llu",
               user, nice, system, idle, iowait, irq, softirq) != 7) {
        fprintf(stderr, "Error: Could not parse CPU stats from %s\n", CPU_STATS_FILE);
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

// Function to calculate CPU load
float calculate_cpu_load(unsigned long long prev_user, unsigned long long prev_nice, unsigned long long prev_system, unsigned long long prev_idle, unsigned long long prev_iowait, unsigned long long prev_irq, unsigned long long prev_softirq, unsigned long long user, unsigned long long nice, unsigned long long system, unsigned long long idle, unsigned long long iowait, unsigned long long irq, unsigned long long softirq) {
    unsigned long long prev_total = prev_user + prev_nice + prev_system + prev_idle + prev_iowait + prev_irq + prev_softirq;
    unsigned long long total = user + nice + system + idle + iowait + irq + softirq;

    unsigned long long prev_idle_all = prev_idle + prev_iowait;
    unsigned long long idle_all = idle + iowait;

    unsigned long long delta_total = total - prev_total;
    unsigned long long delta_idle = idle_all - prev_idle_all;

    float load = (float)(delta_total - delta_idle) / (float)delta_total;

    // Clamp load to 0-100%
    if (load < 0.0) load = 0.0;
    if (load > 1.0) load = 1.0;

    return load * 100.0;
}

// Function to map CPU load to RGB color values
void map_load_to_color(float load, unsigned char *red, unsigned char *green, unsigned char *blue) {
    if (load <= 50.0) {
        // Green to Yellow
        *red = (unsigned char)(255.0 * (load / 50.0));
        *green = 255;
        *blue = 0;
    } else {
        // Yellow to Red
        *red = 255;
        *green = (unsigned char)(255.0 * (1.0 - (load - 50.0) / 50.0));
        *blue = 0;
    }
}

// Function to set the LED color using PWM
int set_led_color(unsigned char red, unsigned char green, unsigned char blue) {
    if (gpioPWM(RED_PIN, red) != 0) {
        fprintf(stderr, "Error: Failed to set red PWM.\n");
        return -1;
    }
    if (gpioPWM(GREEN_PIN, green) != 0) {
        fprintf(stderr, "Error: Failed to set green PWM.\n");
        return -1;
    }
    if (gpioPWM(BLUE_PIN, blue) != 0) {
        fprintf(stderr, "Error: Failed to set blue PWM.\n");
        return -1;
    }
    return 0;
}

int main() {
    unsigned long long prev_user, prev_nice, prev_system, prev_idle, prev_iowait, prev_irq, prev_softirq;
    unsigned long long user, nice, system, idle, iowait, irq, softirq;
    float load;
    unsigned char red, green, blue;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins to output mode
    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(RED_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(GREEN_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(BLUE_PIN, PWM_FREQUENCY);

    // Read initial CPU stats
    if (read_cpu_stats(&prev_user, &prev_nice, &prev_system, &prev_idle, &prev_iowait, &prev_irq, &prev_softirq) != 0) {
        gpioTerminate();
        return 1;
    }

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (program_running) {
        // Read CPU stats
        if (read_cpu_stats(&user, &nice, &system, &idle, &iowait, &irq, &softirq) != 0) {
            break; // Exit loop on error
        }

        // Calculate CPU load
        load = calculate_cpu_load(prev_user, prev_nice, prev_system, prev_idle, prev_iowait, prev_irq, prev_softirq, user, nice, system, idle, iowait, irq, softirq);

        // Map CPU load to color
        map_load_to_color(load, &red, &green, &blue);

        // Set LED color
        if (set_led_color(red, green, blue) != 0) {
            break; // Exit loop on error
        }

        // Update previous CPU stats
        prev_user = user;
        prev_nice = nice;
        prev_system = system;
        prev_idle = idle;
        prev_iowait = iowait;
        prev_irq = irq;
        prev_softirq = softirq;

        // Wait for 500ms
        usleep(500000); // 500ms = 500000 microseconds
    }

    // Turn off LED and terminate pigpio
    set_led_color(0, 0, 0);
    gpioTerminate();

    return 0;
}

