#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define LOG_FILE "rtd_log.csv"
#define SAMPLE_INTERVAL 5 // seconds

// MAX31865 Registers
#define MAX31865_CONFIG_REG 0x00
#define MAX31865_RTD_MSB_REG 0x01
#define MAX31865_RTD_LSB_REG 0x02
#define MAX31865_FAULT_REG 0x03

// RTD Constants (PT100)
#define RREF 430.0  // Reference resistor value
#define A 0.0039083
#define B -0.0000005775

// Global Variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function Prototypes
int init_spi();
int read_max31865_register(uint8_t reg, uint8_t *data, int len);
int write_max31865_register(uint8_t reg, uint8_t data);
float read_temperature();
int check_faults();
int log_temperature(float temperature);
void signal_handler(int signal);
void cleanup();

// Structure for configuration (optional)
typedef struct {
    int spi_channel;
    int spi_speed;
    char *log_file;
    int sample_interval;
} config_t;

// Initialize SPI
int init_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Read from MAX31865 register
int read_max31865_register(uint8_t reg, uint8_t *data, int len) {
    char tx_buf[1];
    char rx_buf[len];

    tx_buf[0] = reg | 0x80; // Set MSB for read

    if (spiXfer(spi_handle, tx_buf, rx_buf, len + 1) != len + 1) {
        fprintf(stderr, "SPI read error\n");
        return -1;
    }

    memcpy(data, rx_buf + 1, len);
    return 0;
}

// Write to MAX31865 register
int write_max31865_register(uint8_t reg, uint8_t data) {
    char tx_buf[2];

    tx_buf[0] = reg & 0x7F; // Clear MSB for write
    tx_buf[1] = data;

    if (spiWrite(spi_handle, tx_buf, 2) != 2) {
        fprintf(stderr, "SPI write error\n");
        return -1;
    }
    return 0;
}

// Read temperature from MAX31865
float read_temperature() {
    uint8_t rtd_data[2];
    uint16_t rtd_raw;
    float rtd_resistance, temperature;

    if (read_max31865_register(MAX31865_RTD_MSB_REG, rtd_data, 2) != 0) {
        fprintf(stderr, "Error reading RTD data\n");
        return -1000.0; // Indicate error
    }

    rtd_raw = (rtd_data[0] << 8) | rtd_data[1];
    rtd_raw = rtd_raw >> 1; // Remove fault bit

    rtd_resistance = ((float)rtd_raw / 32768.0) * RREF;

    // Callendar-Van Dusen equation
    temperature = (A * rtd_resistance) + (B * rtd_resistance * rtd_resistance);

    return temperature;
}

// Check for faults
int check_faults() {
    uint8_t fault_data;

    if (read_max31865_register(MAX31865_FAULT_REG, &fault_data, 1) != 0) {
        fprintf(stderr, "Error reading fault register\n");
        return -1;
    }

    if (fault_data != 0) {
        fprintf(stderr, "Fault detected: 0x%02X\n", fault_data);
        return -1;
    }

    return 0;
}

// Log temperature to file
int log_temperature(float temperature) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open\n");
        return -1;
    }

    fprintf(log_file, "%s,%.2f\n", timestamp, temperature);
    fflush(log_file); // Ensure data is written immediately

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    config_t config = {SPI_CHANNEL, SPI_SPEED, LOG_FILE, SAMPLE_INTERVAL};

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize SPI
    if (init_spi() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(config.log_file, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Temperature (C)\n");
    }
    rewind(log_file);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Configure MAX31865 (3-wire, bias enabled, auto conversion)
    if (write_max31865_register(MAX31865_CONFIG_REG, 0xC2) != 0) {
        fprintf(stderr, "Error configuring MAX31865\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        float temperature = read_temperature();

        if (temperature > -999.0) { // Check for valid temperature reading
            if (check_faults() == 0) {
                if (log_temperature(temperature) != 0) {
                    fprintf(stderr, "Error logging temperature\n");
                }
            } else {
                fprintf(stderr, "Fault detected, skipping logging\n");
            }
        } else {
            fprintf(stderr, "Error reading temperature, skipping logging\n");
        }

        sleep(config.sample_interval);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

