#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// BME280 I2C address
#define BME280_I2C_ADDR 0x76

// BME280 register addresses
#define BME280_REG_CHIPID 0xD0
#define BME280_REG_RESET 0xE0
#define BME280_REG_CTRL_MEAS 0xF4
#define BME280_REG_CTRL_HUM 0xF2
#define BME280_REG_CONFIG 0xF5
#define BME280_REG_DATA_PRESS_MSB 0xF7
#define BME280_REG_DATA_PRESS_LSB 0xF8
#define BME280_REG_DATA_PRESS_XLSB 0xF9
#define BME280_REG_DATA_TEMP_MSB 0xFA
#define BME280_REG_DATA_TEMP_LSB 0xFB
#define BME280_REG_DATA_TEMP_XLSB 0xFC
#define BME280_REG_DATA_HUM_MSB 0xFD
#define BME280_REG_DATA_HUM_LSB 0xFE

// Calibration data registers
#define BME280_REG_CALIB_00 0x88
#define BME280_REG_CALIB_26 0xE1

// BME280 chip ID
#define BME280_CHIP_ID 0x60

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Calibration data structure
struct bme280_calib_data {
    uint16_t dig_T1;
    int16_t dig_T2;
    int16_t dig_T3;
    uint16_t dig_P1;
    int16_t dig_P2;
    int16_t dig_P3;
    int16_t dig_P4;
    int16_t dig_P5;
    int16_t dig_P6;
    int16_t dig_P7;
    int16_t dig_P8;
    int16_t dig_P9;
    uint8_t dig_H1;
    int16_t dig_H2;
    uint8_t dig_H3;
    int16_t dig_H4;
    int16_t dig_H5;
    int8_t dig_H6;
};

struct bme280_calib_data calib;

// Function prototypes
int init_bme280();
int read_calibration_data();
int read_raw_data(int32_t *temperature, int32_t *pressure, int32_t *humidity);
double compensate_temperature(int32_t raw_temperature);
double compensate_pressure(int32_t raw_pressure, double t_fine);
double compensate_humidity(int32_t raw_humidity, double t_fine);
int log_data(double temperature, double humidity, double pressure);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Function to initialize the BME280 sensor
int init_bme280() {
    // Check if pigpio is initialized
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, BME280_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    // Check the chip ID
    int chip_id = i2cReadByteData(i2c_handle, BME280_REG_CHIPID);
    if (chip_id < 0) {
        fprintf(stderr, "Failed to read chip ID: %d\n", chip_id);
        i2cClose(i2c_handle);
        gpioTerminate();
        return -1;
    }

    if (chip_id != BME280_CHIP_ID) {
        fprintf(stderr, "Incorrect chip ID: 0x%X (expected 0x%X)\n", chip_id, BME280_CHIP_ID);
        i2cClose(i2c_handle);
        gpioTerminate();
        return -1;
    }

    // Read calibration data
    if (read_calibration_data() != 0) {
        fprintf(stderr, "Failed to read calibration data\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return -1;
    }

    // Set humidity oversampling to 1x
    if (i2cWriteByteData(i2c_handle, BME280_REG_CTRL_HUM, 0x01) < 0) {
        fprintf(stderr, "Failed to write to CTRL_HUM register\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return -1;
    }

    // Set temperature and pressure oversampling to 1x and normal mode
    if (i2cWriteByteData(i2c_handle, BME280_REG_CTRL_MEAS, 0x27) < 0) {
        fprintf(stderr, "Failed to write to CTRL_MEAS register\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return -1;
    }

    // Set inactive duration to 0.5ms
    if (i2cWriteByteData(i2c_handle, BME280_REG_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Failed to write to CONFIG register\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to read calibration data from the sensor
int read_calibration_data() {
    uint8_t buffer[26];
    int result = i2cReadI2CBlockData(i2c_handle, BME280_REG_CALIB_00, (char *)buffer, 26);
    if (result < 0) {
        fprintf(stderr, "Failed to read calibration data (0x88-0xA1): %d\n", result);
        return -1;
    }

    calib.dig_T1 = (uint16_t)buffer[0] | ((uint16_t)buffer[1] << 8);
    calib.dig_T2 = (int16_t)buffer[2] | ((int16_t)buffer[3] << 8);
    calib.dig_T3 = (int16_t)buffer[4] | ((int16_t)buffer[5] << 8);
    calib.dig_P1 = (uint16_t)buffer[6] | ((uint16_t)buffer[7] << 8);
    calib.dig_P2 = (int16_t)buffer[8] | ((int16_t)buffer[9] << 8);
    calib.dig_P3 = (int16_t)buffer[10] | ((int16_t)buffer[11] << 8);
    calib.dig_P4 = (int16_t)buffer[12] | ((int16_t)buffer[13] << 8);
    calib.dig_P5 = (int16_t)buffer[14] | ((int16_t)buffer[15] << 8);
    calib.dig_P6 = (int16_t)buffer[16] | ((int16_t)buffer[17] << 8);
    calib.dig_P7 = (int16_t)buffer[18] | ((int16_t)buffer[19] << 8);
    calib.dig_P8 = (int16_t)buffer[20] | ((int16_t)buffer[21] << 8);
    calib.dig_P9 = (int16_t)buffer[22] | ((int16_t)buffer[23] << 8);
    calib.dig_H1 = buffer[25];

    uint8_t buffer2[7];
    result = i2cReadI2CBlockData(i2c_handle, BME280_REG_CALIB_26, (char *)buffer2, 7);
    if (result < 0) {
        fprintf(stderr, "Failed to read calibration data (0xE1-0xE7): %d\n", result);
        return -1;
    }

    calib.dig_H2 = (int16_t)buffer2[0] | ((int16_t)buffer2[1] << 8);
    calib.dig_H3 = buffer2[2];
    calib.dig_H4 = (int16_t)((buffer2[3] << 4) | (buffer2[4] & 0x0F));
    calib.dig_H5 = (int16_t)((buffer2[5] << 4) | ((buffer2[4] >> 4) & 0x0F));
    calib.dig_H6 = (int8_t)buffer2[6];

    return 0;
}

// Function to read raw temperature, pressure, and humidity data
int read_raw_data(int32_t *temperature, int32_t *pressure, int32_t *humidity) {
    uint8_t buffer[8];
    int result = i2cReadI2CBlockData(i2c_handle, BME280_REG_DATA_PRESS_MSB, (char *)buffer, 8);
    if (result < 0) {
