// BMP180 I2C address
#define BMP180_ADDR 0x77

// BMP180 registers
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8

// BMP180 calibration data registers
#define BMP180_REG_CAL_AC1 0xAA
#define BMP180_REG_CAL_AC2 0xAC
#define BMP180_REG_CAL_AC3 0xAE
#define BMP180_REG_CAL_AC4 0xB0
#define BMP180_REG_CAL_AC5 0xB2
#define BMP180_REG_CAL_AC6 0xB4
#define BMP180_REG_CAL_B1 0xB6
#define BMP180_REG_CAL_B2 0xB8
#define BMP180_REG_CAL_MB 0xBA
#define BMP180_REG_CAL_MC 0xBC
#define BMP180_REG_CAL_MD 0xBE

// BMP180 commands
#define BMP180_CMD_TEMP 0x2E
#define BMP180_CMD_PRESSURE0 0x34 // Oss = 0
#define BMP180_CMD_PRESSURE1 0x74 // Oss = 1
#define BMP180_CMD_PRESSURE2 0xB4 // Oss = 2
#define BMP180_CMD_PRESSURE3 0xF4 // Oss = 3

// GPIO pin for alert
#define ALERT_PIN 24

// Circular buffer size (60 seconds at 50ms intervals)
#define BUFFER_SIZE (60 * 1000 / 50)

// Deviation threshold (hPa)
#define DEVIATION_THRESHOLD 5.0

// Server address and port
#define SERVER_IP "127.0.0.1" // Replace with your server IP
#define SERVER_PORT 12345

// Global variables
static int i2c_fd;
static volatile bool running = true;
static float pressure_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static float calibration_data[11];

// Function prototypes
int bmp180_init();
int bmp180_read_raw_temperature(int *raw_temperature);
int bmp180_read_raw_pressure(int oss, int *raw_pressure);
float bmp180_calculate_pressure(int raw_temperature, int raw_pressure, float *temperature);
float calculate_rolling_average();
void set_alert(bool alert);
void send_alert_to_server(float current_pressure, float rolling_average);
void signal_handler(int signal);
void cleanup();

// Function to read a 16-bit value from the BMP180
int16_t read_int16(int reg)
{
    int16_t msb = wiringPiI2CReadReg8(i2c_fd, reg);
    int16_t lsb = wiringPiI2CReadReg8(i2c_fd, reg + 1);
    return (msb << 8) | lsb;
}

// Function to read an unsigned 16-bit value from the BMP180
uint16_t read_uint16(int reg)
{
    uint16_t msb = wiringPiI2CReadReg8(i2c_fd, reg);
    uint16_t lsb = wiringPiI2CReadReg8(i2c_fd, reg + 1);
    return (msb << 8) | lsb;
}

// Function to initialize the BMP180 sensor
int bmp180_init()
{
    // Read calibration data
    calibration_data[0] = (float)read_int16(BMP180_REG_CAL_AC1);
    calibration_data[1] = (float)read_int16(BMP180_REG_CAL_AC2);
    calibration_data[2] = (float)read_int16(BMP180_REG_CAL_AC3);
    calibration_data[3] = (float)read_uint16(BMP180_REG_CAL_AC4);
    calibration_data[4] = (float)read_uint16(BMP180_REG_CAL_AC5);
    calibration_data[5] = (float)read_uint16(BMP180_REG_CAL_AC6);
    calibration_data[6] = (float)read_int16(BMP180_REG_CAL_B1);
    calibration_data[7] = (float)read_int16(BMP180_REG_CAL_B2);
    calibration_data[8] = (float)read_int16(BMP180_REG_CAL_MB);
    calibration_data[9] = (float)read_int16(BMP180_REG_CAL_MC);
    calibration_data[10] = (float)read_int16(BMP180_REG_CAL_MD);

    return 0;
}

// Function to read the raw temperature value from the BMP180
int bmp180_read_raw_temperature(int *raw_temperature)
{
    wiringPiI2CWriteReg8(i2c_fd, BMP180_REG_CONTROL, BMP180_CMD_TEMP);
    delay(5); // Wait for measurement
    int msb = wiringPiI2CReadReg8(i2c_fd, BMP180_REG_MSB);
    int lsb = wiringPiI2CReadReg8(i2c_fd, BMP180_REG_LSB);
    *raw_temperature = (msb << 8) | lsb;
    return 0;
}

// Function to read the raw pressure value from the BMP180
int bmp180_read_raw_pressure(int oss, int *raw_pressure)
{
    uint8_t command;
    switch (oss)
    {
    case 0:
        command = BMP180_CMD_PRESSURE0;
        break;
    case 1:
        command = BMP180_CMD_PRESSURE1;
        break;
    case 2:
        command = BMP180_CMD_PRESSURE2;
        break;
    case 3:
        command = BMP180_CMD_PRESSURE3;
        break;
    default:
        fprintf(stderr, "Error: Invalid OSS value\n");
        return -1;
    }

    wiringPiI2CWriteReg8(i2c_fd, BMP180_REG_CONTROL, command);
    delay(2 + (3 << oss)); // Wait for measurement

    int msb = wiringPiI2CReadReg8(i2c_fd, BMP180_REG_MSB);
    int lsb = wiringPiI2CReadReg8(i2c_fd, BMP180_REG_LSB);
    int xlsb = wiringPiI2CReadReg8(i2c_fd, BMP180_REG_XLSB);

    *raw_pressure = (msb << 16 | lsb << 8 | xlsb) >> (8 - oss);
    return 0;
}

// Function to calculate the compensated pressure and temperature
float bmp180_calculate_pressure(int raw_temperature, int raw_pressure, float *temperature)
{
    float X1 = (raw_temperature - calibration_data[5]) * (calibration_data[4] / pow(2, 15));
    float X2 = (calibration_data[9] / pow(2, 11)) * (1 << 15);
    float B5 = X1 + X2;
    *temperature = (B5 + 8) / pow(2, 4) / 10.0;

    float B6 = B5 - 4000;
    float X3 = (calibration_data[1] * (B6 * B6 / pow(2, 12))) / pow(2, 11);
    float X4 = (calibration_data[0] * B6) / pow(2, 15);
    float B3 = (((calibration_data[3] * 4 + X3) << 0) + 2) / 4; // OSS = 0

    uint32_t B4 = (calibration_data[2] * (B6 * B6 / pow(2, 12))) / pow(2, 16);
    uint32_t B7 = ((uint32_t)raw_pressure - B3) * (50000 >> 0); // OSS = 0

    float p;
    if (B7 < 0x80000000)
    {
        p = (B7 * 2) / B4;
    }
    else
    {
        p = (B7 / B4) * 2;
    }

    X1 = (p / pow(2, 8)) * (p / pow(2, 8));
    X1 = (X1 * 3038) / pow(2, 16);
    X2 = (-7357 * p) / pow(2, 16);
    float pressure = p + (X1 + X2 + 3791) / pow(2, 4);

    return pressure;
}

// Function to calculate the rolling average of the pressure values
float calculate_rolling_average()
{
    float sum = 0.0;
    for (int i = 0; i < BUFFER_SIZE; i++)
    {
        sum += pressure_buffer[i];
    }
    return sum / BUFFER_SIZE;
}

// Function to set the alert GPIO pin
void set_alert(bool alert)
{
    digitalWrite(ALERT_PIN, alert ? HIGH : LOW);
}

// Function to send the alert to the server
void send_alert_to_server(float current_pressure, float rolling_average)
{
    int sockfd;
