    char message[256];

    sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sockfd < 0)
    {
        fprintf(stderr, "Error: Socket creation failed\n");
        return;
    }

    memset(&servaddr, 0, sizeof(servaddr));
    servaddr.sin_family = AF_INET;
    servaddr.sin_port = htons(SERVER_PORT);
    if (inet_pton(AF_INET, SERVER_IP, &servaddr.sin_addr) <= 0)
    {
        fprintf(stderr, "Error: Invalid address/ Address not supported \n");
        close(sockfd);
        return;
    }

    snprintf(message, sizeof(message), "ALERT: Current Pressure = %.2f hPa, Rolling Average = %.2f hPa", current_pressure, rolling_average);
    sendto(sockfd, (const char *)message, strlen(message), 0, (const struct sockaddr *)&servaddr, sizeof(servaddr));

    close(sockfd);
}

// Signal handler for SIGINT
void signal_handler(int signal)
{
    if (signal == SIGINT)
    {
        printf("Caught SIGINT, exiting...\n");
        running = false;
    }
}

// Cleanup function to release resources
void cleanup()
{
    set_alert(false); // Reset alert pin
    close(i2c_fd);     // Close I2C interface
    wiringPiSetup(); // Reset GPIO
    printf("Cleanup complete.\n");
}

int main()
