#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// BMP180 I2C address
#define BMP180_ADDR 0x77

// BMP180 registers
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8

// Calibration data registers
#define BMP180_REG_CAL_AC1 0xAA
#define BMP180_REG_CAL_AC2 0xAC
#define BMP180_REG_CAL_AC3 0xAE
#define BMP180_REG_CAL_AC4 0xB0
#define BMP180_REG_CAL_AC5 0xB2
#define BMP180_REG_CAL_AC6 0xB4
#define BMP180_REG_CAL_B1 0xB6
#define BMP180_REG_CAL_B2 0xB8
#define BMP180_REG_CAL_MB 0xBA
#define BMP180_REG_CAL_MC 0xBC
#define BMP180_REG_CAL_MD 0xBE

// Oversampling setting (0 = ultra low power)
#define BMP180_OSS 0

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Calibration data
int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
uint16_t ac4, ac5, ac6;

// Function prototypes
int init_i2c();
int read_calibration_data();
int read_raw_temperature(int32_t *raw_temperature);
int read_raw_pressure(int32_t *raw_pressure);
double calculate_temperature(int32_t raw_temperature);
double calculate_pressure(int32_t raw_pressure, int32_t raw_temperature);
void log_data(double temperature, double pressure);
void timer_interrupt_handler();
void signal_handler(int signal);
void cleanup();

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(1, BMP180_ADDR, 0); // I2C bus 1, BMP180 address
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read calibration data
int read_calibration_data() {
    uint8_t buffer[22];
    int result = i2cReadI2CBlockData(i2c_handle, BMP180_REG_CAL_AC1, (char *)buffer, 22);
    if (result < 0) {
        fprintf(stderr, "Error reading calibration data: %d\n", result);
        return -1;
    }

    ac1 = (buffer[0] << 8) | buffer[1];
    ac2 = (buffer[2] << 8) | buffer[3];
    ac3 = (buffer[4] << 8) | buffer[5];
    ac4 = (buffer[6] << 8) | buffer[7];
    ac5 = (buffer[8] << 8) | buffer[9];
    ac6 = (buffer[10] << 8) | buffer[11];
    b1 = (buffer[12] << 8) | buffer[13];
    b2 = (buffer[14] << 8) | buffer[15];
    mb = (buffer[16] << 8) | buffer[17];
    mc = (buffer[18] << 8) | buffer[19];
    md = (buffer[20] << 8) | buffer[21];

    // Basic validation (check if values are within reasonable ranges)
    if (ac1 == 0 || ac2 == 0 || ac3 == 0 || ac4 == 0 || ac5 == 0 || ac6 == 0) {
        fprintf(stderr, "Error: Calibration data is invalid (zero value).\n");
        return -1;
    }

    return 0;
}

// Function to read raw temperature data
int read_raw_temperature(int32_t *raw_temperature) {
    char buf[1];
    buf[0] = 0x2E; // Temperature measurement command
    int result = i2cWriteI2CBlockData(i2c_handle, BMP180_REG_CONTROL, buf, 1);
    if (result < 0) {
        fprintf(stderr, "Error writing temperature command: %d\n", result);
        return -1;
    }
    gpioDelay(5); // Wait 4.5ms (minimum)

    uint8_t buffer[2];
    result = i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, (char *)buffer, 2);
    if (result < 0) {
        fprintf(stderr, "Error reading raw temperature: %d\n", result);
        return -1;
    }

    *raw_temperature = (buffer[0] << 8) | buffer[1];
    return 0;
}

// Function to read raw pressure data
int read_raw_pressure(int32_t *raw_pressure) {
    char buf[1];
    buf[0] = 0x34 + (BMP180_OSS << 6); // Pressure measurement command
    int result = i2cWriteI2CBlockData(i2c_handle, BMP180_REG_CONTROL, buf, 1);
    if (result < 0) {
        fprintf(stderr, "Error writing pressure command: %d\n", result);
        return -1;
    }

    gpioDelay(2 + (3 << BMP180_OSS)); // Wait for conversion (datasheet)

    uint8_t buffer[3];
    result = i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, (char *)buffer, 3);
    if (result < 0) {
        fprintf(stderr, "Error reading raw pressure: %d\n", result);
        return -1;
    }

    *raw_pressure = ((uint32_t)buffer[0] << 16 | (uint32_t)buffer[1] << 8 | (uint32_t)buffer[2]) >> (8 - BMP180_OSS);
    return 0;
}

// Function to calculate temperature in degrees Celsius
double calculate_temperature(int32_t raw_temperature) {
    int32_t X1 = ((int32_t)raw_temperature - (int32_t)ac6) * ((int32_t)ac5) / pow(2, 15);
    int32_t X2 = ((int32_t)mc * pow(2, 11)) / (X1 + md);
    int32_t B5 = X1 + X2;
    double temperature = (B5 + 8) / pow(2, 4) / 10.0;
    return temperature;
}

// Function to calculate pressure in pascals
double calculate_pressure(int32_t raw_pressure, int32_t raw_temperature) {
    int32_t X1 = ((int32_t)raw_temperature - (int32_t)ac6) * ((int32_t)ac5) / pow(2, 15);
    int32_t X2 = ((int32_t)mc * pow(2, 11)) / (X1 + md);
    int32_t B5 = X1 + X2;

    int32_t B6 = B5 - 4000;
    int32_t X3 = ((int32_t)b2 * (B6 * B6) / pow(2, 12)) / pow(2, 11);
    int32_t X4 = ((int32_t)ac2 * B6) / pow(2, 11);
    int32_t B3 = (((((int32_t)ac1) * 4 + X3) << BMP180_OSS) + 2) / 4;

    uint32_t X1_pressure = ((uint32_t)ac3 * B6) / pow(2, 13);
    uint32_t X2_pressure = ((uint32_t)b1 * (B6 * B6) / pow(2, 12)) / pow(2, 16);
    uint32_t X3_pressure = ((X1_pressure + X2_pressure + 2) / 4);
    uint32_t B4 = ((uint32_t)ac4 * (X3_pressure + 32768)) / pow(2, 15);
    uint32_t B7 = ((uint32_t)raw_pressure - B3) * (50000 >> BMP180_OSS);

    int32_t pressure;
    if (B7 < 0x80000000) {
        pressure = (B7 * 2) / B4;
    } else {
        pressure = (B7 / B4) * 2;
    }

    X1_pressure = (pressure / pow(2, 8)) * (pressure / pow(2, 8));
    X1_pressure = (X1_pressure * 3038) / pow(2, 16);
    X2_pressure = (-7357 * pressure) / pow(2, 16);
    pressure = pressure + (X1_pressure + X2_pressure + 3791) / pow(2, 4);

    return pressure;
}

// Function to log data to file
void log_data(double temperature, double pressure) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, pressure);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Timer interrupt handler
void timer_interrupt_handler() {
    int32_t raw_temperature, raw_pressure;
    double temperature, pressure;

    if (read_raw_temperature(&raw_temperature) == 0 && read_raw_pressure(&raw_pressure) == 0) {
        temperature = calculate_temperature(raw_temperature);
        pressure = calculate_pressure(raw_pressure, raw_temperature);
        log_data(temperature, pressure);
    } else {
        fprintf(stderr, "Error reading sensor data in interrupt handler.\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
