#include <pigpio.h>

#define GPIO_PIN 18
#define PWM_FREQUENCY 25000
#define TEMP_MIN 40.0
#define TEMP_MAX 70.0
#define DUTY_MIN 0
#define DUTY_MAX 255
#define LOG_FILE "fan_log.txt"

static volatile int running = 1;
static FILE *log_file = NULL;

// Function to read CPU temperature from file
float read_cpu_temp() {
    FILE *fp;
    char buffer[10];
    float temp = -1.0;

    fp = fopen("/sys/class/thermal/thermal_zone0/temp", "r");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open temperature file.\n");
        return -1.0;
    }

    if (fgets(buffer, sizeof(buffer), fp) != NULL) {
        temp = atoi(buffer) / 1000.0;
    } else {
        fprintf(stderr, "Error: Could not read temperature from file.\n");
        fclose(fp);
        return -1.0;
    }

    fclose(fp);
    return temp;
}

// Function to map temperature to duty cycle
int map_temp_to_duty(float temp) {
    int duty_cycle;

    if (temp <= TEMP_MIN) {
        duty_cycle = DUTY_MIN;
    } else if (temp >= TEMP_MAX) {
        duty_cycle = DUTY_MAX;
    } else {
        duty_cycle = (int)(((temp - TEMP_MIN) / (TEMP_MAX - TEMP_MIN)) * (DUTY_MAX - DUTY_MIN) + DUTY_MIN);
    }

    return duty_cycle;
}

// Function to set PWM duty cycle
int set_fan_speed(int duty_cycle) {
    if (gpioPWM(GPIO_PIN, duty_cycle) != 0) {
        fprintf(stderr, "Error: Could not set PWM duty cycle.\n");
        return -1;
    }
    return 0;
}

// Function to log data to file
int log_data(float temp, int duty_cycle) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }

    if (fprintf(log_file, "%s, %.2f, %d\n", timestamp, temp, duty_cycle) < 0) {
        fprintf(stderr, "Error: Could not write to log file.\n");
        return -1;
    }

    fflush(log_file);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, stopping fan...\n", signal);
    running = 0;
}

int main() {
    float temperature;
    int duty_cycle;

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    // Set GPIO pin to output mode
    gpioSetMode(GPIO_PIN, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(GPIO_PIN, PWM_FREQUENCY);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file.\n");
        gpioTerminate();
        return 1;
    }

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Fan control started. Press Ctrl+C to stop.\n");

    while (running) {
        // Read CPU temperature
        temperature = read_cpu_temp();
        if (temperature < 0) {
            fprintf(stderr, "Error: Could not read temperature. Retrying in 5 seconds.\n");
            gpioDelay(5000000); // 5 seconds
            continue;
        }

        // Map temperature to duty cycle
        duty_cycle = map_temp_to_duty(temperature);

        // Set fan speed
        if (set_fan_speed(duty_cycle) != 0) {
            fprintf(stderr, "Error: Could not set fan speed. Retrying in 5 seconds.\n");
            gpioDelay(5000000); // 5 seconds
            continue;
        }

        // Log data
        if (log_data(temperature, duty_cycle) != 0) {
            fprintf(stderr, "Error: Could not log data. Retrying in 5 seconds.\n");
            gpioDelay(5000000); // 5 seconds
            continue;
        }

        printf("Temperature: %.2f°C, Duty Cycle: %d\n", temperature, duty_cycle);

        gpioDelay(5000000); // 5 seconds
    }

    // Stop fan
    set_fan_speed(0);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio library
    gpioTerminate();

    printf("Fan control stopped.\n");

    return 0;
}

