#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <pthread.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define LM75_ADDR 0x48
#define ALERT_GPIO 18
#define BUFFER_SIZE 60
#define TEMP_THRESHOLD 28.0
#define TEMP_SCALE 0.125
#define TEMP_OFFSET 0.0

// Global variables
int i2c_fd = -1;
pthread_mutex_t buffer_mutex = PTHREAD_MUTEX_INITIALIZER;
float temperature_buffer[BUFFER_SIZE];
int buffer_index = 0;
float running_average = 0.0;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_temperature();
void update_circular_buffer(float temperature);
float calculate_running_average();
void *alert_led_thread(void *arg);
void signal_handler(int signal);
int initialize();
void cleanup();

// Function to read temperature from LM75 sensor
int read_temperature() {
    int raw_temp;
    float temperature;

    raw_temp = i2cReadWordData(i2c_fd, 0x00); // Read temperature register
    if (raw_temp < 0) {
        fprintf(stderr, "Error reading temperature: %s\n", strerror(errno));
        return -1; // Indicate error
    }

    // Convert raw temperature to Celsius
    temperature = (float)((raw_temp >> 8) | (raw_temp << 8)) * TEMP_SCALE + TEMP_OFFSET;

    return (int)(temperature * 100); // Return temperature in hundredths of a degree Celsius
}

// Function to update the circular buffer
void update_circular_buffer(float temperature) {
    pthread_mutex_lock(&buffer_mutex);
    temperature_buffer[buffer_index] = temperature;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    pthread_mutex_unlock(&buffer_mutex);
}

// Function to calculate the running average
float calculate_running_average() {
    float sum = 0.0;
    pthread_mutex_lock(&buffer_mutex);
    for (int i = 0; i < BUFFER_SIZE; i++) {
        sum += temperature_buffer[i];
    }
    pthread_mutex_unlock(&buffer_mutex);
    return sum / BUFFER_SIZE;
}

// Thread function for the alert LED
void *alert_led_thread(void *arg) {
    (void)arg; // Suppress unused parameter warning
    while (program_running) {
        float avg_temp;
        pthread_mutex_lock(&buffer_mutex);
        avg_temp = running_average;
        pthread_mutex_unlock(&buffer_mutex);

        if (avg_temp > TEMP_THRESHOLD) {
            gpioWrite(ALERT_GPIO, 1); // Turn LED on
        } else {
            gpioWrite(ALERT_GPIO, 0); // Turn LED off
        }
        gpioDelay(100); // Delay for 100ms
    }
    pthread_exit(NULL);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Caught SIGINT, exiting gracefully.\n");
        program_running = 0;
    }
}

// Initialization function
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return -1;
    }

    // Open I2C bus
    i2c_fd = i2cOpen(I2C_BUS, LM75_ADDR, 0);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return -1;
    }

    // Set GPIO mode for alert LED
    gpioSetMode(ALERT_GPIO, PI_OUTPUT);

    // Initialize circular buffer with 0.0
    pthread_mutex_lock(&buffer_mutex);
    for (int i = 0; i < BUFFER_SIZE; i++) {
        temperature_buffer[i] = 0.0;
    }
    pthread_mutex_unlock(&buffer_mutex);

    return 0;
}

// Cleanup function
void cleanup() {
    printf("Cleaning up resources...\n");

    // Close I2C bus
    if (i2c_fd >= 0) {
        i2cClose(i2c_fd);
    }

    // Release GPIO line
    gpioWrite(ALERT_GPIO, 0); // Turn off LED
    gpioSetMode(ALERT_GPIO, PI_INPUT); // Set back to input mode

    // Destroy mutex
    pthread_mutex_destroy(&buffer_mutex);

    // Terminate pigpio
    gpioTerminate();

    printf("Cleanup complete.\n");
}

int main() {
    pthread_t led_thread;
    int temperature_raw;
    float temperature_celsius;

    // Set up signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize
    if (initialize() != 0) {
        fprintf(stderr, "Initialization failed, exiting.\n");
        return 1;
    }

    // Create alert LED thread
    if (pthread_create(&led_thread, NULL, alert_led_thread, NULL) != 0) {
        fprintf(stderr, "Failed to create alert LED thread: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Main loop
    while (program_running) {
        temperature_raw = read_temperature();
        if (temperature_raw >= 0) {
            temperature_celsius = (float)temperature_raw / 100.0;
            update_circular_buffer(temperature_celsius);
            pthread_mutex_lock(&buffer_mutex);
            running_average = calculate_running_average();
            pthread_mutex_unlock(&buffer_mutex);
            printf("Temperature: %.2f °C, Running Average: %.2f °C\n", temperature_celsius, running_average);
        } else {
            fprintf(stderr, "Failed to read temperature, attempting re-initialization.\n");
            cleanup();
            if (initialize() != 0) {
                fprintf(stderr, "Re-initialization failed, exiting.\n");
                program_running = 0; // Exit the loop if re-initialization fails
            }
        }

        sleep(1); // Read temperature every 1 second
    }

    // Join alert LED thread
    pthread_join(led_thread, NULL);

    // Cleanup resources
    cleanup();

    return 0;
}

