                program_running = 0; // Exit the loop if re-initialization fails
            }
        }

        sleep(1); // Read temperature every 1 second
    }

    // Join alert LED thread
    pthread_join(led_thread, NULL);

    // Cleanup resources
    cleanup();

    return 0;
}

