#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <jansson.h>
#include <time.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 500000 // 500 kHz
#define HEATER_GPIO 18
#define PWM_FREQUENCY 1000
#define PWM_RANGE 1000
#define TARGET_TEMP 50.0
#define MAX_TEMP 80.0
#define LOG_FILE "heater_log.txt"

// MAX31865 Registers
#define MAX31865_CONFIG_REG 0x00
#define MAX31865_RTD_MSB_REG 0x01
#define MAX31865_RTD_LSB_REG 0x02
#define MAX31865_FAULT_REG 0x07

// RTD Constants
#define RTD_NOMINAL 100.0
#define REF_RESISTOR 430.0

// Global Variables
static int spi_handle;
static volatile int running = 1;
static FILE *log_file;

// PID Gains
static double Kp = 1.0;
static double Ki = 0.1;
static double Kd = 0.01;

// PID Variables
static double integral = 0.0;
static double previous_error = 0.0;

// Function Prototypes
double read_rtd();
double calculate_pid(double setpoint, double actual_temperature);
void set_pwm_duty(int duty_cycle);
void load_configuration(const char *filename);
void signal_handler(int signal);
void log_message(const char *message);

// Function to read the RTD value from the MAX31865
double read_rtd() {
    unsigned char tx_buffer[3];
    unsigned char rx_buffer[3];
    int rtd_raw;
    double rtd_resistance;

    // Configure MAX31865 for single-shot mode
    tx_buffer[0] = MAX31865_CONFIG_REG | 0x80; // Write enable
    tx_buffer[1] = 0xC2; // Enable bias, auto conversion, 50/60 Hz filter, 1-shot

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 2) != 0) {
        log_message("SPI write error (config)");
        return -1.0;
    }

    // Read RTD MSB and LSB
    tx_buffer[0] = MAX31865_RTD_MSB_REG | 0x00; // Read enable
    tx_buffer[1] = 0x00;
    tx_buffer[2] = 0x00;

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) != 0) {
        log_message("SPI read error (RTD)");
        return -1.0;
    }

    rtd_raw = ((rx_buffer[1] << 8) | rx_buffer[2]) >> 1; // Remove fault bit

    // Convert RTD raw value to resistance
    rtd_resistance = ((double)rtd_raw / 32768.0) * REF_RESISTOR;

    return rtd_resistance;
}

// Function to calculate the PID output
double calculate_pid(double setpoint, double actual_temperature) {
    double error = setpoint - actual_temperature;
    integral += error;
    double derivative = error - previous_error;
    double output = Kp * error + Ki * integral + Kd * derivative;
    previous_error = error;
    return output;
}

// Function to set the PWM duty cycle
void set_pwm_duty(int duty_cycle) {
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > PWM_RANGE) duty_cycle = PWM_RANGE;
    gpioPWM(HEATER_GPIO, duty_cycle);
}

// Function to load configuration from JSON file
void load_configuration(const char *filename) {
    json_t *root;
    json_error_t error;

    root = json_load_file(filename, 0, &error);
    if (!root) {
        fprintf(stderr, "Error: Could not load configuration file: %s\n", error.text);
        log_message("Error: Could not load configuration file");
        return;
    }

    json_t *kp = json_object_get(root, "Kp");
    json_t *ki = json_object_get(root, "Ki");
    json_t *kd = json_object_get(root, "Kd");

    if (kp && json_is_real(kp)) Kp = json_real_value(kp);
    if (ki && json_is_real(ki)) Ki = json_real_value(ki);
    if (kd && json_is_real(kd)) Kd = json_real_value(kd);

    json_decref(root);

    printf("Configuration loaded: Kp=%.2f, Ki=%.2f, Kd=%.2f\n", Kp, Ki, Kd);
    char log_message_buffer[256];
    snprintf(log_message_buffer, sizeof(log_message_buffer), "Configuration loaded: Kp=%.2f, Ki=%.2f, Kd=%.2f", Kp, Ki, Kd);
    log_message(log_message_buffer);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Signal received (%d). Shutting down...\n", signal);
    log_message("Signal received. Shutting down...");
    running = 0;
    set_pwm_duty(0); // Turn off heater
    gpioTerminate(); // Terminate pigpio
    if (spi_handle >= 0) spiClose(spi_handle);
    if (log_file != NULL) fclose(log_file);
    exit(0);
}

// Function to log messages with timestamps
void log_message(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "[%s] %s\n", timestamp, message);
    fflush(log_file);
    fprintf(stderr, "[%s] %s\n", timestamp, message);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file\n");
        gpioTerminate();
        return 1;
    }

    // Load configuration
    load_configuration("heater_config.json");

    // Set GPIO mode for heater control
    gpioSetMode(HEATER_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(HEATER_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(HEATER_GPIO, PWM_RANGE);

    // Initialize SPI
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 500kHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI initialisation failed\n");
        log_message("Error: SPI initialisation failed");
        gpioTerminate();
        fclose(log_file);
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        double rtd_resistance = read_rtd();
        if (rtd_resistance < 0) {
            log_message("Error reading RTD, exiting");
            running = 0;
            continue;
        }

        // Convert RTD resistance to temperature (PT100 approximation)
        double temperature = (rtd_resistance / RTD_NOMINAL) * 100.0;

        // Check for MAX31865 faults
        unsigned char fault_reg;
        unsigned char tx_buffer[2];
        unsigned char rx_buffer[2];

        tx_buffer[0] = MAX31865_FAULT_REG | 0x00; // Read enable
        tx_buffer[1] = 0x00;

        if (spiXfer(spi_handle, tx_buffer, rx_buffer, 2) != 0) {
            log_message("SPI read error (fault)");
            running = 0;
            continue;
        }

        fault_reg = rx_buffer[1];

        if (fault_reg != 0x00) {
            fprintf(stderr, "Error: MAX31865 Fault detected (0x%02X)\n", fault_reg);
            log_message("Error: MAX31865 Fault detected");
            running = 0;
            continue;
        }

        // PID control
        double pid_output = calculate_pid(TARGET_TEMP, temperature);

        // Limit PID output to prevent excessive heating
        if (pid_output > PWM_RANGE) pid_output = PWM_RANGE;
        if (pid_output < 0) pid_output = 0;

        // Set PWM duty cycle
        set_pwm_duty((int)pid_output);

        // Failsafe: Check for temperature limit
        if (temperature > MAX_TEMP) {
            fprintf(stderr, "Error: Temperature exceeds limit (%.2f > %.2f). Shutting down.\n", temperature, MAX_TEMP);
            log_message("Error: Temperature exceeds limit");
            running = 0;
            set_pwm_duty(0);
            continue;
        }

        printf("Temperature: %.2f C, PID Output: %.2f\n", temperature, pid_output);
        char log_message_buffer[256];
        snprintf(log_message_buffer, sizeof(log_message_buffer), "Temperature: %.2f C, PID Output: %.2f", temperature, pid_output);
        log_message(log_message_buffer);

        gpioDelay(100); // 100ms delay
    }

    // Cleanup
    set_pwm_duty(0); // Turn off heater
    spiClose(spi_handle);
    gpioTerminate();
    fclose(log_file);

    return 0;
}

