    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }

    char buf[1];
    buf[0] = 0x2E; // Temperature measurement command
    if (i2cWriteDevice(i2c_handle, buf, 1) != 0) {
