// Function to read calibration data from the BMP180
int read_calibration_data(int i2c_handle, bmp180_calibration_data_t *calibration_data) {
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Invalid I2C handle in read_calibration_data\n");
        return -1;
    }

    calibration_data->ac1 = i2cReadWordData(i2c_handle, BMP180_REG_CAL_AC1);
    calibration_data->ac2 = i2cReadWordData(i2c_handle, BMP180_REG_CAL_AC2);
