    gpioDelay(5000); // Wait 5ms

    int msb = i2cReadByteData(i2c_handle, BMP180_REG_MSB);
    int lsb = i2cReadByteData(i2c_handle, BMP180_REG_LSB);

    if (msb < 0 || lsb < 0) {
        fprintf(stderr, "Error: Failed to read raw temperature data\n");
        return -1;
    }

    return (msb << 8) | lsb;
}

// Function to read raw pressure data from the BMP180
int read_raw_pressure(int i2c_handle) {
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Invalid I2C handle in read_raw_pressure\n");
        return -1;
    }

    if (i2cWriteByteData(i2c_handle, BMP180_REG_CONTROL, 0x34 + (BMP180_OSS << 6)) < 0) {
        fprintf(stderr, "Error: Failed to write pressure conversion command\n");
        return -1;
    }

    gpioDelay(2 + (3 << BMP180_OSS)); // Wait for conversion

    int msb = i2cReadByteData(i2c_handle, BMP180_REG_MSB);
    int lsb = i2cReadByteData(i2c_handle, BMP180_REG_LSB);
    int xlsb = i2cReadByteData(i2c_handle, BMP180_REG_XLSB);

    if (msb < 0 || lsb < 0 || xlsb < 0) {
        fprintf(stderr, "Error: Failed to read raw pressure data\n");
        return -1;
    }

    return ((msb << 16) | (lsb << 8) | xlsb) >> (8 - BMP180_OSS);
