// Function to calculate temperature in degrees Celsius
float calculate_temperature(int raw_temperature, const bmp180_calibration_data_t *calibration_data) {
    long x1 = (((long)raw_temperature - (long)calibration_data->ac6) * (long)calibration_data->ac5) >> 15;
    long x2 = ((long)calibration_data->mc << 11) / (x1 + calibration_data->md);
