#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// BMP180 I2C address
#define BMP180_ADDR 0x77

// BMP180 registers
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8

// Calibration data registers
#define BMP180_REG_CAL_AC1 0xAA
#define BMP180_REG_CAL_AC2 0xAC
#define BMP180_REG_CAL_AC3 0xAE
#define BMP180_REG_CAL_AC4 0xB0
#define BMP180_REG_CAL_AC5 0xB2
#define BMP180_REG_CAL_AC6 0xB4
#define BMP180_REG_CAL_B1 0xB6
#define BMP180_REG_CAL_B2 0xB8
#define BMP180_REG_CAL_MB 0xBA
#define BMP180_REG_CAL_MC 0xBC
#define BMP180_REG_CAL_MD 0xBE

// Oversampling setting (0, 1, 2, or 3)
#define BMP180_OSS 0

// GPIO pin for interrupt
#define INTERRUPT_GPIO 27

// Debounce time in milliseconds
#define DEBOUNCE_TIME 200

// Global variables
int i2c_handle;
volatile int logging_enabled = 0;
volatile unsigned long last_interrupt_time = 0;

// Calibration data
int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
uint16_t ac4, ac5, ac6;

// Function prototypes
int read_calibration_data();
int read_raw_temperature(int *raw_temperature);
int read_raw_pressure(int *raw_pressure);
double calculate_pressure(int raw_temperature, int raw_pressure);
void log_pressure(double pressure);
void interrupt_handler(int gpio, int level, unsigned int tick, void *user_data);
void signal_handler(int signal);

// Function to read a 16-bit value from the BMP180
int16_t read_16(int reg)
{
    char buf[2];
    if (i2cReadI2CBlockData(i2c_handle, reg, buf, 2) != 2) {
        fprintf(stderr, "Error reading 16-bit value from register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return (int16_t)((buf[0] << 8) | buf[1]);
}

// Function to read an unsigned 16-bit value from the BMP180
uint16_t read_u16(int reg)
{
    char buf[2];
    if (i2cReadI2CBlockData(i2c_handle, reg, buf, 2) != 2) {
        fprintf(stderr, "Error reading unsigned 16-bit value from register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return (uint16_t)((buf[0] << 8) | buf[1]);
}

// Function to read calibration data from the BMP180
int read_calibration_data()
{
    ac1 = read_16(BMP180_REG_CAL_AC1);
    ac2 = read_16(BMP180_REG_CAL_AC2);
    ac3 = read_16(BMP180_REG_CAL_AC3);
    ac4 = read_u16(BMP180_REG_CAL_AC4);
    ac5 = read_u16(BMP180_REG_CAL_AC5);
    ac6 = read_u16(BMP180_REG_CAL_AC6);
    b1 = read_16(BMP180_REG_CAL_B1);
    b2 = read_16(BMP180_REG_CAL_B2);
    mb = read_16(BMP180_REG_CAL_MB);
    mc = read_16(BMP180_REG_CAL_MC);
    md = read_16(BMP180_REG_CAL_MD);

    if (ac1 == -1 || ac2 == -1 || ac3 == -1 || ac4 == -1 || ac5 == -1 || ac6 == -1 ||
        b1 == -1 || b2 == -1 || mb == -1 || mc == -1 || md == -1) {
        fprintf(stderr, "Error reading calibration data\n");
        return -1;
    }

    return 0;
}

// Function to read raw temperature data from the BMP180
int read_raw_temperature(int *raw_temperature)
{
    char buf[1];
    buf[0] = 0x2E; // Temperature measurement command
    if (i2cWriteI2CBlockData(i2c_handle, BMP180_REG_CONTROL, buf, 1) != 1) {
        fprintf(stderr, "Error writing temperature measurement command: %s\n", strerror(errno));
        return -1;
    }
    gpioDelay(5000); // Wait 4.5ms (minimum)

    int msb = read_16(BMP180_REG_MSB);
    if (msb == -1) return -1;

    *raw_temperature = msb;
    return 0;
}

// Function to read raw pressure data from the BMP180
int read_raw_pressure(int *raw_pressure)
{
    char buf[1];
    buf[0] = 0x34 + (BMP180_OSS << 6); // Pressure measurement command
    if (i2cWriteI2CBlockData(i2c_handle, BMP180_REG_CONTROL, buf, 1) != 1) {
        fprintf(stderr, "Error writing pressure measurement command: %s\n", strerror(errno));
        return -1;
    }

    gpioDelay(26000); // Wait 25.5ms (OSS = 3)

    int msb = read_16(BMP180_REG_MSB);
    int lsb = read_16(BMP180_REG_LSB);
    int xlsb = read_16(BMP180_REG_XLSB);

    if (msb == -1 || lsb == -1 || xlsb == -1) return -1;

    *raw_pressure = (msb << 16 | lsb << 8 | xlsb) >> (8 - BMP180_OSS);
    return 0;
}

// Function to calculate pressure in pascals
double calculate_pressure(int raw_temperature, int raw_pressure)
{
    long x1, x2, x3, b3, b5, b6, p;
    unsigned long b4, b7;

    b5 = (((long)raw_temperature - (long)ac6) * (long)ac5) >> 15;
    x1 = ((long)mc << 11) / (b5 + md);
    b6 = b5 + x1;
    x2 = ((b6 >> 2) * (b6 >> 2)) >> 11;
    x3 = ((x2 * (long)b2) >> 13);
    b3 = (((((long)ac1) * 4 + x3) << BMP180_OSS) + 2) >> 2;

    x1 = ((long)ac3 * b6) >> 13;
    x2 = ((b1 * ((b6 >> 2) * (b6 >> 2)) >> 13) >> 12);
    b4 = ((unsigned long)ac4 * (unsigned long)(x1 + x2 + 32768)) >> 15;
    b7 = ((unsigned long)raw_pressure - b3) * (50000 >> BMP180_OSS);

    if (b7 < 0x80000000)
    {
        p = (b7 * 2) / b4;
    }
    else
    {
        p = (b7 / b4) * 2;
    }

    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    p = p + ((x1 + x2 + 3791) >> 4);

    return (double)p;
}

// Function to log pressure data to a file
void log_pressure(double pressure)
{
    FILE *fp = fopen("pressure_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening pressure_log.txt: %s\n", strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, %.2f\n", timestamp, pressure);
    fclose(fp);
}

// Interrupt handler function
void interrupt_handler(int gpio, int level, unsigned int tick, void *user_data)
{
    unsigned long current_time = gpioTick();

    if (current_time - last_interrupt_time > DEBOUNCE_TIME * 1000) {
        logging_enabled = !logging_enabled;
        printf("Logging %s\n", logging_enabled ? "enabled" : "disabled");
        last_interrupt_time = current_time;
    }
}

// Signal handler function
void signal_handler(int signal)
{
    printf("Caught signal %d, cleaning up...\n", signal);
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

int main()
{
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, BMP180_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Read calibration data
    if (read_calibration_data() != 0) {
        fprintf(stderr, "Failed to read calibration data. Exiting.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO27 as input with pull-up resistor
    gpioSetMode(INTERRUPT_GPIO, PI_INPUT);
    gpioSetPullUpDown(INTERRUPT_GPIO, PI_PUD_UP);

    // Set interrupt handler
    gpioSetISRFuncEx(INTERRUPT_GPIO, FALLING_EDGE, 0, interrupt_handler, NULL);

    // Set signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int raw_temperature, raw_pressure;
    double pressure;

    // Main loop
    while (1) {
        if (logging_enabled) {
            // Read raw temperature and pressure
            if (read_raw_temperature(&raw_temperature) == 0 && read_raw_pressure(&raw_pressure) == 0) {
                // Calculate pressure
                pressure = calculate_pressure(raw_temperature, raw_pressure);

                // Log pressure
                log_pressure(pressure);
            } else {
                fprintf(stderr, "Error reading temperature or pressure. Retrying...\n");
            }
        }

        gpioDelay(2000000); // Wait 2 seconds
    }

    return 0;
}

