#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define HEATER_PIN 17
#define SPI_CE0 8
#define SPI_MISO 9
#define SPI_MOSI 10
#define SPI_SCLK 11

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 2000000 // 2 MHz
#define SPI_MODE 0

// Define target temperature and maximum duty cycle
#define TARGET_TEMPERATURE 25.0
#define MAX_DUTY_CYCLE 80.0

// Define PI controller parameters
#define KP 1.0
#define KI 0.1
#define INTEGRAL_LIMIT 100.0

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_max31855(float *temperature);
void set_heater_duty_cycle(float duty_cycle);
float calculate_pi_control(float current_temperature, float target_temperature, float *integral);
void log_data(float temperature, float duty_cycle);
void signal_handler(int signal);

// Function to read temperature from MAX31855
int read_max31855(float *temperature) {
    unsigned char data[4];
    int result = spiRead(spi_handle, data, 4);

    if (result != 4) {
        fprintf(stderr, "Error reading SPI data: %d\n", result);
        return -1;
    }

    // Check for fault conditions
    if (data[3] & 0x01) {
        fprintf(stderr, "MAX31855 Fault: Open circuit\n");
        return -1;
    }
    if (data[3] & 0x02) {
        fprintf(stderr, "MAX31855 Fault: Short to ground\n");
        return -1;
    }
    if (data[3] & 0x04) {
        fprintf(stderr, "MAX31855 Fault: Short to VCC\n");
        return -1;
    }

    // Extract temperature data
    int16_t raw_temp = ((data[0] << 8) | data[1]) >> 2;
    *temperature = (float)raw_temp * 0.25;

    return 0;
}

// Function to set heater duty cycle using PWM
void set_heater_duty_cycle(float duty_cycle) {
    if (duty_cycle < 0.0) {
        duty_cycle = 0.0;
    } else if (duty_cycle > 100.0) {
        duty_cycle = 100.0;
    }

    int pwm_value = (int)(duty_cycle * 10000.0 / 100.0); // pigpio range is 0-10000
    gpioPWM(HEATER_PIN, pwm_value);
}

// Function to calculate PI control output
float calculate_pi_control(float current_temperature, float target_temperature, float *integral) {
    float error = target_temperature - current_temperature;
    *integral += error;

    // Anti-windup
    if (*integral > INTEGRAL_LIMIT) {
        *integral = INTEGRAL_LIMIT;
    } else if (*integral < -INTEGRAL_LIMIT) {
        *integral = -INTEGRAL_LIMIT;
    }

    float output = KP * error + KI * (*integral);

    // Limit output to 0-100
    if (output < 0.0) {
        output = 0.0;
    } else if (output > 100.0) {
        output = 100.0;
    }

    return output;
}

// Function to log data to file
void log_data(float temperature, float duty_cycle) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, duty_cycle);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, shutting down...\n", signal);
    program_running = 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(HEATER_PIN, PI_OUTPUT);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("heater_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float temperature, duty_cycle, pi_output;
    float integral = 0.0;

    // Main loop
    while (program_running) {
        // Read temperature
        if (read_max31855(&temperature) == 0) {
            // Calculate PI control
            pi_output = calculate_pi_control(temperature, TARGET_TEMPERATURE, &integral);

            // Set heater duty cycle
            set_heater_duty_cycle(pi_output);

            // Log data
            log_data(temperature, pi_output);
        } else {
            // Error reading temperature, set duty cycle to 0
            set_heater_duty_cycle(0.0);
            log_data(-999.0, 0.0); // Log error value
        }

        // Wait for 1 second
        time_sleep(1.0);
    }

    // Shutdown sequence
    printf("Shutting down...\n");
    set_heater_duty_cycle(0.0); // Turn off heater
    spiClose(spi_handle);       // Close SPI
    fclose(log_file);           // Close log file
    gpioTerminate();            // Terminate pigpio

    return 0;
}

