#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

// Define GPIO pins for RGB LED
#define RED_PIN   17
#define GREEN_PIN 18
#define BLUE_PIN  27

// Define I2C address for BH1750
#define BH1750_ADDR 0x23

// Define I2C device file
#define I2C_DEVICE "/dev/i2c-1"

// Define temperature file path
#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"

// Global variables
volatile sig_atomic_t terminate = 0;
int i2c_fd = -1;

// Function prototypes
int read_cpu_temp();
int read_bh1750();
void set_led_color(int red, int green, int blue);
void signal_handler(int signal);
int initialize_i2c();
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Function to initialize I2C
int initialize_i2c() {
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    return 0;
}

// Function to read CPU temperature from file
int read_cpu_temp() {
    FILE *fp;
    int temp = -1;

    fp = fopen(TEMP_FILE, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error opening temperature file: %s\n", strerror(errno));
        return -1;
    }

    if (fscanf(fp, "%d", &temp) != 1) {
        fprintf(stderr, "Error reading temperature from file\n");
        fclose(fp);
        return -1;
    }

    if (ferror(fp)) {
        fprintf(stderr, "Error reading temperature from file\n");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return temp;
}

// Function to read light level from BH1750 sensor
int read_bh1750() {
    unsigned char buf[2];
    int lux = -1;

    // Send start measurement command (High Resolution Mode)
    buf[0] = 0x10; // High Resolution Mode
    if (write(i2c_fd, buf, 1) != 1) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }

    // Wait for measurement (at least 180ms)
    usleep(200000); // 200ms

    // Read 2 bytes of data
    if (read(i2c_fd, buf, 2) != 2) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        return -1;
    }

    lux = (buf[0] << 8) | buf[1];

    return lux;
}

// Function to set RGB LED color using PWM
void set_led_color(int red, int green, int blue) {
    gpioPWM(RED_PIN, 255 - red);
    gpioPWM(GREEN_PIN, 255 - green);
    gpioPWM(BLUE_PIN, 255 - blue);
}

// Function to cleanup GPIO and I2C
void cleanup() {
    printf("Cleaning up...\n");
    gpioPWM(RED_PIN, 255);
    gpioPWM(GREEN_PIN, 255);
    gpioPWM(BLUE_PIN, 255);

    if (i2c_fd != -1) {
        close(i2c_fd);
    }

    gpioTerminate();
}

int main() {
    int cpu_temp, lux;
    int red, green, blue;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins to output mode
    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read CPU temperature
        cpu_temp = read_cpu_temp();
        if (cpu_temp == -1) {
            fprintf(stderr, "Error reading CPU temperature, skipping update\n");
            usleep(500000); // Wait 0.5 seconds
            continue;
        }

        // Read light level
        lux = read_bh1750();
        if (lux == -1) {
            fprintf(stderr, "Error reading light level, skipping update\n");
            usleep(500000); // Wait 0.5 seconds
            continue;
        }

        // Determine LED color based on temperature
        if (cpu_temp < 40000) {
            red = 0;
            green = 0;
            blue = 255;
        } else if (cpu_temp < 60000) {
            red = 0;
            green = 255;
            blue = 0;
        } else {
            red = 255;
            green = 0;
            blue = 0;
        }

        // Set LED color
        set_led_color(red, green, blue);

        // Print temperature, light level, and PWM values
        printf("CPU Temp: %d m°C, Light: %d lux, Red: %d, Green: %d, Blue: %d\n", cpu_temp, lux, red, green, blue);

        // Wait 0.5 seconds
        usleep(500000);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

