#define MAX_RETRIES 3
#define RETRY_DELAY 1 // seconds

// Structure to hold DHT22 data
typedef struct {
    float temperature;
    float humidity;
} DHT22Data;

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    program_running = 0;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read DHT22 data using pigpio
int read_dht22(DHT22Data *data) {
    int i, j;
    int bit_count = 0;
    int data_bits[40] = {0};
    int checksum = 0;
    int data_valid = 0;

    // Send start signal
    gpioSetMode(DHT22_GPIO, PI_OUTPUT);
    gpioWrite(DHT22_GPIO, 0);
    gpioDelay(1); // 1ms
    gpioWrite(DHT22_GPIO, 1);
    gpioDelay(30); // 30us

    // Switch to input mode
    gpioSetMode(DHT22_GPIO, PI_INPUT);

    // Wait for response (low for ~80us, high for ~80us)
    int timeout = 0;
    while (gpioRead(DHT22_GPIO) == 1) {
        gpioDelay(1); // 1us delay
        timeout++;
        if (timeout > 100) return -1; // Timeout
    }

    timeout = 0;
    while (gpioRead(DHT22_GPIO) == 0) {
        gpioDelay(1); // 1us delay
        timeout++;
        if (timeout > 100) return -1; // Timeout
    }

    timeout = 0;
    while (gpioRead(DHT22_GPIO) == 1) {
        gpioDelay(1); // 1us delay
        timeout++;
        if (timeout > 100) return -1; // Timeout
    }

    // Read 40 bits of data
    for (i = 0; i < 40; i++) {
        timeout = 0;
        while (gpioRead(DHT22_GPIO) == 0) {
            gpioDelay(1); // 1us delay
            timeout++;
            if (timeout > 100) return -1; // Timeout
        }

        long start = gpioTick();
        timeout = 0;
        while (gpioRead(DHT22_GPIO) == 1) {
            gpioDelay(1); // 1us delay
            timeout++;
            if (timeout > 100) return -1; // Timeout
        }
        long end = gpioTick();

        if ((end - start) > 40) { // Check for valid pulse length
            data_bits[i] = 1; // Long pulse indicates '1'
        } else {
            data_bits[i] = 0; // Short pulse indicates '0'
        }
    }

    // Convert bits to bytes
    int bytes[5] = {0};
    for (i = 0; i < 40; i++) {
        bytes[i / 8] <<= 1;
        bytes[i / 8] |= data_bits[i];
    }

    // Calculate checksum
    checksum = bytes[0] + bytes[1] + bytes[2] + bytes[3];

    // Validate checksum
    if (checksum == bytes[4]) {
        data_valid = 1;
    }

    if (!data_valid) {
        fprintf(stderr, "Checksum mismatch!\n");
        return -1;
    }

    // Convert data to temperature and humidity
    data->humidity = (float)((bytes[0] << 8) + bytes[1]) / 10.0;
    data->temperature = (float)(((bytes[2] & 0x7F) << 8) + bytes[3]) / 10.0;
    if (bytes[2] & 0x80) {
        data->temperature *= -1;
    }

    return 0;
}

// Function to format data as JSON
char* format_json(float temperature, float humidity) {
    char *json_string = malloc(100 * sizeof(char)); // Allocate memory for the JSON string
    if (json_string == NULL) {
        fprintf(stderr, "Memory allocation failed!\n");
        return NULL;
    }
    sprintf(json_string, "{\"temperature\": %.2f, \"humidity\": %.2f}", temperature, humidity);
    return json_string;
}

// Function to post data to the server
int post_data(const char *json_data) {
    CURL *curl;
    CURLcode res;
    struct curl_slist *headers = NULL;

    curl_global_init(CURL_GLOBAL_DEFAULT);
    curl = curl_easy_init();
    if (curl) {
        curl_easy_setopt(curl, CURLOPT_URL, SERVER_URL);
        curl_easy_setopt(curl, CURLOPT_POST, 1L);
        curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json_data);

        headers = curl_slist_append(headers, "Content-Type: application/json");
        curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);

        res = curl_easy_perform(curl);
        if (res != CURLE_OK) {
            fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
        }

        curl_easy_cleanup(curl);
        curl_slist_free_all(headers);
    }
    curl_global_cleanup();
    return (res == CURLE_OK) ? 0 : -1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    DHT22Data dht22_data;
    char *json_data;
    int retries = 0;
    int read_result;

    while (program_running) {
        read_result = read_dht22(&dht22_data);

        if (read_result == 0) {
            json_data = format_json(dht22_data.temperature, dht22_data.humidity);
            if (json_data != NULL) {
                if (post_data(json_data) != 0) {
                    fprintf(stderr, "Failed to post data. Retrying...\n");
                    retries = 0;
                    while (retries < MAX_RETRIES) {
                        sleep(RETRY_DELAY);
                        if (post_data(json_data) == 0) {
                            break;
                        } else {
                            retries++;
                            fprintf(stderr, "Retry %d failed. Retrying in %d seconds...\n", retries, RETRY_DELAY);
                        }
                    }
                    if (retries == MAX_RETRIES) {
                        fprintf(stderr, "Max retries reached. Data not posted.\n");
                    }
                }
                free(json_data);
            } else {
                fprintf(stderr, "Failed to format JSON data.\n");
            }
        } else {
            fprintf(stderr, "Failed to read DHT22 data. Retrying...\n");
            retries = 0;
            while (retries < MAX_RETRIES) {
                sleep(RETRY_DELAY);
                if (read_dht22(&dht22_data) == 0) {
                    break;
                } else {
                    retries++;
                    fprintf(stderr, "Retry %d failed. Retrying in %d seconds...\n", retries, RETRY_DELAY);
                }
            }
            if (retries == MAX_RETRIES) {
                fprintf(stderr, "Max retries reached. DHT22 data not read.\n");
            }
        }

        sleep(5); // Read every 5 seconds
    }

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

