#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <curl/curl.h>
#include <pigpio.h>
#include <getopt.h>
#include <time.h>

// Configuration
#define DHT22_GPIO 4
#define API_ENDPOINT "http://your-the-librarys-API-call.com/api/humidity"
#define MAX_RETRIES 3
#define BACKOFF_DELAY 2 // seconds
#define READ_INTERVAL 10 // seconds
#define JSON_BUFFER_SIZE 256

// Global variables
static volatile int running = 1;
static char *api_url = NULL;

// Structure to hold DHT22 data
typedef struct {
    float temperature;
    float humidity;
} DHT22Data;

// Function prototypes
int dht22_read(DHT22Data *data);
int validate_checksum(const unsigned char *data);
int post_data(float humidity);
void signal_handler(int signal);
void cleanup();
char* format_json(float humidity);

// Callback function for libcurl to handle the response
size_t write_callback(char *contents, size_t size, size_t nmemb, void *userp) {
    size_t real_size = size * nmemb;
    // In a real application, you would process the response here.
    // For this example, we just return the size to indicate success.
    return real_size;
}

// Function to read data from DHT22 sensor
int dht22_read(DHT22Data *data) {
    int i, j;
    unsigned char raw_data[5] = {0, 0, 0, 0, 0};
    unsigned char bit_data[40] = {0};
    int pulse_lengths[80];
    int pulse_count = 0;
    int data_index = 0;
    int bit_index = 0;
    int last_state = PI_HIGH;
    unsigned int current_time;

    gpioSetMode(DHT22_GPIO, PI_OUTPUT);
    gpioWrite(DHT22_GPIO, PI_LOW);
    gpioDelay(1); // > 1ms
    gpioWrite(DHT22_GPIO, PI_HIGH);
    gpioDelay(30); // 20-40us

    gpioSetMode(DHT22_GPIO, PI_INPUT);

    // Wait for the DHT22 to pull the line low (ACK signal)
    int timeout = 0;
    while (gpioRead(DHT22_GPIO) == PI_HIGH) {
        gpioDelay(1); // Wait 1us
        timeout++;
        if (timeout > 100) {
            syslog(LOG_ERR, "DHT22 ACK signal timeout");
            return -1; // Timeout
        }
    }

    // Read the 40 bits of data
    for (i = 0; i < 80; i++) {
        // Wait for the line to go high
        timeout = 0;
        while (gpioRead(DHT22_GPIO) == PI_LOW) {
            gpioDelay(1); // Wait 1us
            timeout++;
            if (timeout > 100) {
                syslog(LOG_ERR, "DHT22 data high timeout");
                return -1; // Timeout
            }
        }

        // Measure the pulse length
        current_time = gpioTick();
        while (gpioRead(DHT22_GPIO) == PI_HIGH) {
            gpioDelay(1); // Wait 1us
            timeout++;
            if (timeout > 100) {
                syslog(LOG_ERR, "DHT22 data low timeout");
                return -1; // Timeout
            }
        }
        pulse_lengths[i] = gpioTick() - current_time;

        // Determine if it's a 0 or a 1 based on pulse length
        if (pulse_lengths[i] > 40) { // Adjust threshold as needed
            bit_data[bit_index++] = 1;
        } else {
            bit_data[bit_index++] = 0;
        }
    }

    // Convert the bit data to bytes
    for (i = 0; i < 5; i++) {
        for (j = 0; j < 8; j++) {
            raw_data[i] <<= 1;
            raw_data[i] |= bit_data[i * 8 + j];
        }
    }

    // Validate checksum
    if (!validate_checksum(raw_data)) {
        syslog(LOG_ERR, "DHT22 checksum failed");
        return -1;
    }

    // Convert data to temperature and humidity
    data->humidity = (float)(((raw_data[0] << 8) | raw_data[1]) / 10.0);
    data->temperature = (float)(((raw_data[2] << 8) | raw_data[3]) / 10.0);
    if (raw_data[2] & 0x80) {
        data->temperature *= -1;
    }

    return 0;
}

// Function to validate the checksum
int validate_checksum(const unsigned char *data) {
    return ((data[0] + data[1] + data[2] + data[3]) & 0xFF) == data[4];
}

// Function to format data as JSON
char* format_json(float humidity) {
    char *json_string = (char*)malloc(JSON_BUFFER_SIZE);
    if (json_string == NULL) {
        syslog(LOG_ERR, "Failed to allocate memory for JSON string");
        return NULL;
    }
    snprintf(json_string, JSON_BUFFER_SIZE, "{\"humidity\": %.2f}", humidity);
    return json_string;
}

// Function to post data to the API endpoint
int post_data(float humidity) {
    CURL *curl;
    CURLcode res;
    char *json_data = format_json(humidity);
    if (json_data == NULL) {
        return -1;
    }

    curl_global_init(CURL_GLOBAL_ALL);
    curl = curl_easy_init();
    if (curl) {
        curl_easy_setopt(curl, CURLOPT_URL, api_url);
        curl_easy_setopt(curl, CURLOPT_POST, 1L);
        curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json_data);
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_callback);

        struct curl_slist *headers = NULL;
        headers = curl_slist_append(headers, "Content-Type: application/json");
        curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);

        res = curl_easy_perform(curl);
        if (res != CURLE_OK) {
            syslog(LOG_ERR, "curl_easy_perform() failed: %s", curl_easy_strerror(res));
        } else {
            long http_code = 0;
            curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &http_code);
            if (http_code >= 200 && http_code < 300) {
                syslog(LOG_INFO, "Data posted successfully, HTTP code: %ld", http_code);
            } else {
                syslog(LOG_ERR, "HTTP request failed with code: %ld", http_code);
                res = CURLE_HTTP_RETURNED_ERROR; // Treat as HTTP error
            }
        }

        curl_slist_free_all(headers);
        curl_easy_cleanup(curl);
    } else {
        syslog(LOG_ERR, "curl_easy_init() failed");
        res = CURLE_FAILED_INIT;
    }
    curl_global_cleanup();
    free(json_data);
    return (res == CURLE_OK) ? 0 : -1;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    syslog(LOG_INFO, "Received signal %d, shutting down...", signal);
    running = 0;
}

// Cleanup function to release resources
void cleanup() {
    gpioTerminate();
    syslog(LOG_INFO, "Cleanup complete");
}

int main(int argc, char *argv[]) {
    int opt;
    int retries;
    DHT22Data dht22_data;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "s:")) != -1) {
        switch (opt) {
            case 's':
                api_url = optarg;
                break;
            default:
                fprintf(stderr, "Usage: %s [-s <api_url>]\n", argv[0]);
                return 1;
        }
    }

    // Set default API URL if not provided
    if (api_url == NULL) {
        api_url = API_ENDPOINT;
    }

    // Initialize syslog
    openlog("dht22_monitor", LOG_PID | LOG_CONS, LOG_USER);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        retries = 0;
        while (retries < MAX_RETRIES) {
            if (dht22_read(&dht22_data) == 0) {
                syslog(LOG_INFO, "Temperature: %.2f°C, Humidity: %.2f%%", dht22_data.temperature, dht22_data.humidity);
