#include <sys/types.h>

#define CPU_TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define FAN_SPEED_FILE "/sys/class/thermal/cooling_device0/cur_state"
#define MAX_FAN_SPEED_FILE "/sys/class/thermal/cooling_device0/max_state"
#define LOG_FILE "/var/log/fan_control.log"

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, shutting down...\n", signal);
}

// Function to read CPU temperature from file
int read_cpu_temp() {
    FILE *fp;
    int temp = -1;
    char buffer[10];

    fp = fopen(CPU_TEMP_FILE, "r");
    if (fp == NULL) {
        perror("Error opening CPU temperature file");
        return -1;
    }

    if (fgets(buffer, sizeof(buffer), fp) != NULL) {
        temp = atoi(buffer);
    } else {
        perror("Error reading CPU temperature");
    }

    fclose(fp);
    return temp;
}

// Function to read current fan speed from file
int read_fan_speed() {
    FILE *fp;
    int speed = -1;
    char buffer[10];

    fp = fopen(FAN_SPEED_FILE, "r");
    if (fp == NULL) {
        perror("Error opening fan speed file");
        return -1;
    }

    if (fgets(buffer, sizeof(buffer), fp) != NULL) {
        speed = atoi(buffer);
    } else {
        perror("Error reading fan speed");
    }

    fclose(fp);
    return speed;
}

// Function to read maximum fan speed from file
int read_max_fan_speed() {
    FILE *fp;
    int max_speed = -1;
    char buffer[10];

    fp = fopen(MAX_FAN_SPEED_FILE, "r");
    if (fp == NULL) {
        perror("Error opening max fan speed file");
        return -1;
    }

    if (fgets(buffer, sizeof(buffer), fp) != NULL) {
        max_speed = atoi(buffer);
    } else {
        perror("Error reading max fan speed");
    }

    fclose(fp);
    return max_speed;
}

// Function to set fan speed
int set_fan_speed(int speed) {
    FILE *fp;
    char buffer[10];

    fp = fopen(FAN_SPEED_FILE, "w");
    if (fp == NULL) {
        perror("Error opening fan speed file for writing");
        return -1;
    }

    snprintf(buffer, sizeof(buffer), "%d", speed);
    if (fwrite(buffer, 1, strlen(buffer), fp) != strlen(buffer)) {
        perror("Error writing to fan speed file");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

// Function to log fan speed changes
int log_fan_speed(int speed) {
    FILE *fp;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1;
    }

    fprintf(fp, "%s - Fan speed set to: %d\n", timestamp, speed);
    fclose(fp);
    return 0;
}

// Function to determine fan speed based on temperature
int determine_fan_speed(int temperature) {
    if (temperature < 45000) {
        return 0;
    } else if (temperature < 55000) {
        return 1;
    } else if (temperature < 65000) {
        return 2;
    } else {
        return 3;
    }
}

int main() {
    int current_temp, current_speed, max_speed, new_speed;

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (program_running) {
        // Read CPU temperature
        current_temp = read_cpu_temp();
        if (current_temp == -1) {
            fprintf(stderr, "Error reading CPU temperature, retrying in 5 seconds...\n");
            sleep(5);
            continue;
        }

        // Read current fan speed
        current_speed = read_fan_speed();
        if (current_speed == -1) {
            fprintf(stderr, "Error reading current fan speed, retrying in 5 seconds...\n");
            sleep(5);
            continue;
        }

        // Read maximum fan speed
        max_speed = read_max_fan_speed();
        if (max_speed == -1) {
            fprintf(stderr, "Error reading maximum fan speed, retrying in 5 seconds...\n");
            sleep(5);
            continue;
        }

        // Determine new fan speed
        new_speed = determine_fan_speed(current_temp);

        // Check if new speed is within the valid range
        if (new_speed < 0 || new_speed > max_speed) {
            fprintf(stderr, "Invalid fan speed: %d, max speed: %d.  Ignoring.\n", new_speed, max_speed);
            sleep(5);
            continue;
        }

        // Set fan speed if it has changed
        if (new_speed != current_speed) {
            if (set_fan_speed(new_speed) == 0) {
                log_fan_speed(new_speed);
            } else {
                fprintf(stderr, "Error setting fan speed to %d\n", new_speed);
            }
        }

        sleep(5);
    }

    // Shutdown sequence
    printf("Shutting down...\n");
    set_fan_speed(0);
    log_fan_speed(0);
    printf("Shutdown complete.\n");

    return 0;
}

