#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define HEATER_GPIO 18
#define SPI_CHANNEL 0
#define SPI_SPEED 500000 // 500 kHz
#define PWM_FREQUENCY 1000 // 1 kHz
#define TARGET_TEMPERATURE 50.0
#define MAX_TEMPERATURE 100.0
#define MIN_TEMPERATURE 0.0

// PID Gains
#define DEFAULT_KP 1.0
#define DEFAULT_KI 0.1
#define DEFAULT_KD 0.01

// Global Variables
static volatile int running = 1;
static int spi_handle;
static FILE *log_file;
static double Kp = DEFAULT_KP;
static double Ki = DEFAULT_KI;
static double Kd = DEFAULT_KD;

// PID Variables
static double integral = 0.0;
static double previous_error = 0.0;

// Function Prototypes
double read_temperature();
double calculate_pid(double setpoint, double actual_temperature);
void set_heater_pwm(double duty_cycle);
void log_data(double temperature, double duty_cycle, double pid_output);
void signal_handler(int signal);
void cleanup();
int parse_max31855_data(uint8_t *data, double *temperature);

// Function to read temperature from MAX31855
double read_temperature() {
    uint8_t data[4];
    int result = spiRead(spi_handle, (char *)data, 4);
    if (result != 4) {
        fprintf(stderr, "Error reading SPI data: %d\n", result);
        return -1000.0; // Indicate error
    }

    if (parse_max31855_data(data, NULL) != 0) {
        return -1000.0; // Indicate error
    }

    return (double)((data[0] << 8) | data[1]) / 4.0;
}

// Function to parse MAX31855 data and check for faults
int parse_max31855_data(uint8_t *data, double *temperature) {
    if (data == NULL) return -1;

    // Check for fault bits
    if (data[3] & 0x01) {
        fprintf(stderr, "MAX31855 Fault: Open Circuit\n");
        return -1;
    }
    if (data[3] & 0x02) {
        fprintf(stderr, "MAX31855 Fault: Short to GND\n");
        return -1;
    }
    if (data[3] & 0x04) {
        fprintf(stderr, "MAX31855 Fault: Short to VCC\n");
        return -1;
    }

    // Extract temperature data
    int16_t raw_temp = ((data[0] << 8) | data[1]) >> 2;
    if (temperature != NULL) {
        *temperature = (double)raw_temp / 4.0;
    }
    return 0;
}

// Function to calculate PID output
double calculate_pid(double setpoint, double actual_temperature) {
    double error = setpoint - actual_temperature;
    integral += error;
    double derivative = error - previous_error;
    double output = Kp * error + Ki * integral + Kd * derivative;
    previous_error = error;
    return output;
}

// Function to set heater PWM duty cycle
void set_heater_pwm(double duty_cycle) {
    if (duty_cycle < 0.0) duty_cycle = 0.0;
    if (duty_cycle > 100.0) duty_cycle = 100.0;

    int pwm_value = (int)(duty_cycle * 255.0 / 100.0); // pigpio range is 0-255
    gpioPWM(HEATER_GPIO, pwm_value);
}

// Function to log data to file
void log_data(double temperature, double duty_cycle, double pid_output) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp)-1, "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, %.2f, %.2f, %.2f\n", timestamp, temperature, duty_cycle, pid_output);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Received signal %d, shutting down...\n", signal);
    running = 0;
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");
    set_heater_pwm(0.0); // Turn off heater
    gpioTerminate(); // Terminate pigpio
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

