#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <wiringPi.h>
#include <wiringPiI2C.h>

// Constants
#define FAN_GPIO 18
#define DHT22_GPIO 4
#define CPU_TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define I2C_ADDR 0x48
#define I2C_REG 0x00
#define PWM_FREQUENCY 25000
#define PWM_RANGE 1000000 // Adjusted for percentage calculation
#define LOG_FILE "cooling_log.csv"
#define SERVER_IP "192.168.1.100"
#define SERVER_PORT 5000

// Global variables
static volatile int keepRunning = 1;
static int i2c_fd;
static FILE *log_fp = NULL;

// Function prototypes
float read_cpu_temp();
float read_dht22_temp();
float read_lm75_temp();
int calculate_duty_cycle(float cpu_temp, float dht22_temp, float lm75_temp);
int set_fan_speed(int duty_cycle);
int log_data(float cpu_temp, float dht22_temp, float lm75_temp, int duty_cycle);
int send_data_to_server(float cpu_temp, float dht22_temp, float lm75_temp, int duty_cycle);
void signal_handler(int signal);

// Function to read CPU temperature from file
float read_cpu_temp() {
    FILE *fp;
    int temp_milli_celsius;

    fp = fopen(CPU_TEMP_FILE, "r");
    if (fp == NULL) {
        perror("Failed to open CPU temperature file");
        return -1.0;
    }

    if (fscanf(fp, "%d", &temp_milli_celsius) != 1) {
        fprintf(stderr, "Failed to read CPU temperature\n");
        fclose(fp);
        return -1.0;
    }

    fclose(fp);
    return (float)temp_milli_celsius / 1000.0;
}

// Function to read DHT22 temperature (Dummy implementation)
float read_dht22_temp() {
    // Replace with actual DHT22 reading logic using wiringPi
    // This is a placeholder, as direct DHT22 reading is complex.
    // Consider using a library like 'dht11' or 'dht22' for reliable readings.
    // For now, return a dummy value.
    return 25.0; // Dummy temperature
}

// Function to read LM75 temperature
float read_lm75_temp() {
    int raw_temp;

    raw_temp = wiringPiI2CReadReg16(i2c_fd, I2C_REG);
    if (raw_temp == -1) {
        perror("Failed to read LM75 temperature");
        return -1.0;
    }

    // LM75 returns a 11-bit temperature value, left-aligned.
    // Shift right by 5 bits to get the 11-bit value.
    raw_temp = (raw_temp >> 5) & 0x3FF; // Keep only the 11 bits

    // Convert to Celsius (0.125 degrees per bit)
    float temperature = raw_temp * 0.125;

    return temperature;
}

// Function to calculate PWM duty cycle
int calculate_duty_cycle(float cpu_temp, float dht22_temp, float lm75_temp) {
    float max_temp = (cpu_temp > dht22_temp) ? cpu_temp : dht22_temp;
    max_temp = (max_temp > lm75_temp) ? max_temp : lm75_temp;

    if (max_temp <= 40.0) {
        return 0;
    } else if (max_temp >= 70.0) {
        return 100;
    } else {
        return (int)(((max_temp - 40.0) / (70.0 - 40.0)) * 100.0);
    }
}

// Function to set fan speed using PWM
int set_fan_speed(int duty_cycle) {
    if (duty_cycle < 0 || duty_cycle > 100) {
        fprintf(stderr, "Invalid duty cycle: %d\n", duty_cycle);
        return -1;
    }

    pwmWrite(FAN_GPIO, duty_cycle * (PWM_RANGE / 100.0)); // Map duty cycle to PWM range
    return 0;
}

// Function to log data to file
int log_data(float cpu_temp, float dht22_temp, float lm75_temp, int duty_cycle) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_fp == NULL) {
        log_fp = fopen(LOG_FILE, "a");
        if (log_fp == NULL) {
            perror("Failed to open log file");
            return -1;
        }
        fprintf(log_fp, "Timestamp,CPU Temp (C),DHT22 Temp (C),LM75 Temp (C),Duty Cycle (%)\n");
    }

    fprintf(log_fp, "%s,%.2f,%.2f,%.2f,%d\n", timestamp, cpu_temp, dht22_temp, lm75_temp, duty_cycle);
    fflush(log_fp); // Ensure data is written to disk
    return 0;
}

// Function to send data to server
int send_data_to_server(float cpu_temp, float dht22_temp, float lm75_temp, int duty_cycle) {
    int sockfd;
    struct sockaddr_in servaddr;
    char buffer[256];

    sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sockfd < 0) {
        perror("socket creation failed");
        return -1;
    }

    memset(&servaddr, 0, sizeof(servaddr));
    servaddr.sin_family = AF_INET;
    servaddr.sin_port = htons(SERVER_PORT);
    if (inet_pton(AF_INET, SERVER_IP, &servaddr.sin_addr) <= 0) {
        perror("Invalid address/ Address not supported");
        close(sockfd);
        return -1;
    }

    snprintf(buffer, sizeof(buffer), "CPU: %.2f, DHT22: %.2f, LM75: %.2f, Duty: %d",
             cpu_temp, dht22_temp, lm75_temp, duty_cycle);

    if (sendto(sockfd, (const char *)buffer, strlen(buffer), 0, (const struct sockaddr *)&servaddr, sizeof(servaddr)) < 0) {
        perror("sendto failed");
        close(sockfd);
        return -1;
    }

    close(sockfd);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    keepRunning = 0;
}

int main() {
    // Initialize wiringPi
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "wiringPiSetupGpio failed: %s\n", strerror(errno));
        return 1;
    }

    // Initialize I2C
    i2c_fd = wiringPiI2CSetup(I2C_ADDR);
    if (i2c_fd == -1) {
        fprintf(stderr, "wiringPiI2CSetup failed: %s\n", strerror(errno));
        return 1;
    }

    // Configure PWM
    pinMode(FAN_GPIO, PWM_OUTPUT);
    pwmSetMode(PWM_MODE_MS);
    pwmSetClock(192); // Adjust clock for 25kHz (19.2MHz / 192 = 100kHz, 100kHz / 4 = 25kHz)
    pwmSetRange(PWM_RANGE);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (keepRunning) {
        float cpu_temp = read_cpu_temp();
        float dht22_temp = read_dht22_temp();
        float lm75_temp = read_lm75_temp();
        int duty_cycle;

        if (cpu_temp == -1.0 || dht22_temp == -1.0 || lm75_temp == -1.0) {
            fprintf(stderr, "Error reading sensor data, skipping iteration.\n");
            sleep(5);
            continue;
        }

        duty_cycle = calculate_duty_cycle(cpu_temp, dht22_temp, lm75_temp);

        if (set_fan_speed(duty_cycle) == -1) {
            fprintf(stderr, "Failed to set fan speed.\n");
        }

        if (log_data(cpu_temp, dht22_temp, lm75_temp, duty_cycle) == -1) {
            fprintf(stderr, "Failed to log data.\n");
        }

        if (send_data_to_server(cpu_temp, dht22_temp, lm75_temp, duty_cycle) == -1) {
            fprintf(stderr, "Failed to send data to server.\n");
        }

        sleep(5);
    }

    // Cleanup
    set_fan_speed(0); // Turn off fan
    if (log_fp != NULL) {
        fclose(log_fp);
    }

    return 0;
}

