#define FLOW_LOG_FILE "flow_log.txt"
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INITIAL_VALUE 0xFF

// Global variables
