unsigned char calculate_crc(unsigned char data[], int length);
int log_flow_data(float flow1, float flow2);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Function to calculate CRC8 checksum
unsigned char calculate_crc(unsigned char data[], int length) {
    unsigned char crc = CRC8_INITIAL_VALUE;
    for (int i = 0; i < length; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read flow rate from a sensor
int read_sensor(int i2c_handle, float *flow_rate) {
    unsigned char buffer[3];
    int bytes_read;
    unsigned char crc;

    for (int retry = 0; retry < MAX_RETRIES; retry++) {
        bytes_read = i2cReadDevice(i2c_handle, buffer, 3);
        if (bytes_read == 3) {
            // Calculate CRC
            crc = calculate_crc(buffer, 2);

            // Validate CRC
            if (crc == buffer[2]) {
                // Convert data to flow rate (example conversion, adjust as needed)
                int raw_flow = (buffer[0] << 8) | buffer[1];
                *flow_rate = (float)raw_flow / 100.0; // Example scaling
                return 0; // Success
            } else {
