    i2c_handle1 = i2cOpen(I2C_BUS, SENSOR1_ADDR, 0);
    if (i2c_handle1 < 0) {
        fprintf(stderr, "Error opening I2C device for sensor 1: %d\n", i2c_handle1);
        gpioTerminate();
        return 1;
    }

    i2c_handle2 = i2cOpen(I2C_BUS, SENSOR2_ADDR, 0);
    if (i2c_handle2 < 0) {
        fprintf(stderr, "Error opening I2C device for sensor 2: %d\n", i2c_handle2);
        i2cClose(i2c_handle1);
        gpioTerminate();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float flow1, flow2;

    // Main loop
    while (!terminate) {
        // Read flow rates from sensors
        if (read_sensor(i2c_handle1, &flow1) == 0 && read_sensor(i2c_handle2, &flow2) == 0) {
            // Log the data
            if (log_flow_data(flow1, flow2) != 0) {
                fprintf(stderr, "Error logging flow data\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        gpioDelay(1000000); // Delay for 1 second (1000000 microseconds)
    }

    // Close I2C handles and terminate pigpio
    i2cClose(i2c_handle1);
    i2cClose(i2c_handle2);
    gpioTerminate();

    return 0;
}

