#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <string.h>

// Define GPIO pins for Channel A and Channel B
#define GPIO_A 17
#define GPIO_B 18

// Define the log file name
#define LOG_FILE "encoder_log.txt"

// Structure to hold the current state of the encoder
typedef struct {
    int a_state;
    int b_state;
    float angle;
} EncoderState;

// Global variable to store the current state of the encoder
EncoderState encoder_state = {0, 0, 0.0};

// Global variable to store the previous state of the encoder
EncoderState previous_state = {0, 0, 0.0};

// Function prototypes
int initialize_gpio();
int read_gpio(int gpio);
float calculate_angle(int a_state, int b_state, int a_prev, int b_prev);
int log_data(float angle);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    gpioTerminate();
    exit(0);
}

// Function to initialize the GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(GPIO_A, PI_INPUT);
    gpioSetMode(GPIO_B, PI_INPUT);
    gpioSetPullUpDown(GPIO_A, PI_PUD_UP);
    gpioSetPullUpDown(GPIO_B, PI_PUD_UP);

    return 0;
}

// Function to read the state of a GPIO pin
int read_gpio(int gpio) {
    return gpioRead(gpio);
}

// Function to calculate the angle based on the quadrature state
float calculate_angle(int a_state, int b_state, int a_prev, int b_prev) {
    float angle = encoder_state.angle;

    if (a_state != a_prev) {
        if (a_state == b_state) {
            angle += 120.0;
        } else {
            angle -= 120.0;
        }
    } else if (b_state != b_prev) {
        if (b_state == a_state) {
            angle += 120.0;
        } else {
            angle -= 120.0;
        }
    }

    // Normalize the angle to be within 0.00 to 360.00 degrees
    if (angle >= 360.0) {
        angle -= 360.0;
    } else if (angle < 0.0) {
        angle += 360.0;
    }

    return angle;
}

// Function to log the data to a file
int log_data(float angle) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return 1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s, %.2f\n", timestamp, angle);
    fclose(fp);

    return 0;
}

int main() {
    // Register signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the GPIO pins
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Encoder monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        // Read the current state of the GPIO pins
        int a_state = read_gpio(GPIO_A);
        int b_state = read_gpio(GPIO_B);

        // Calculate the angle
        float angle = calculate_angle(a_state, b_state, encoder_state.a_state, encoder_state.b_state);

        // Log the data
        if (log_data(angle) != 0) {
            fprintf(stderr, "Error logging data!\n");
        }

        // Update the previous state
        previous_state = encoder_state;

        // Update the current state
        encoder_state.a_state = a_state;
        encoder_state.b_state = b_state;
        encoder_state.angle = angle;

        // Delay to avoid excessive CPU usage
        gpioDelay(1000); // 1 millisecond
    }

    return 0;
}

