#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define ADPD144RI_ADDR 0x38
#define RED_REG 0x00
#define IR_REG 0x02
#define GPIO_LED 17
#define IR_THRESHOLD 2000
#define SAMPLE_INTERVAL_MS 100

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c();
int read_sensor_data(uint16_t *red, uint16_t *ir);
void log_data(uint16_t red, uint16_t ir);
void control_led(uint16_t ir);
void signal_handler(int signal);
void cleanup();

// Structure to hold sensor data
typedef struct {
    uint16_t red;
    uint16_t ir;
} sensor_data_t;

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        cleanup();
        return 1;
    }

    // Set GPIO17 as output
    gpioSetMode(GPIO_LED, PI_OUTPUT);

    // Main loop
    sensor_data_t sensor_data;
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&sensor_data.red, &sensor_data.ir) == 0) {
            // Log data
            log_data(sensor_data.red, sensor_data.ir);

            // Control LED
            control_led(sensor_data.ir);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // pigpioDelay takes microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize I2C
int initialize_i2c() {
    i2c_fd = i2cOpen(I2C_BUS, ADPD144RI_ADDR, 0);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Read sensor data
int read_sensor_data(uint16_t *red, uint16_t *ir) {
    char buf[4];
    int bytes_read;

    // Read red and IR values in a single transaction
    bytes_read = i2cReadI2CBlockData(i2c_fd, RED_REG, buf, 4);

    if (bytes_read != 4) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }

    // Combine the bytes to form 16-bit values
    *red = (uint16_t)((buf[1] << 8) | buf[0]);
    *ir = (uint16_t)((buf[3] << 8) | buf[2]);

    return 0;
}

// Log data to CSV file
void log_data(uint16_t red, uint16_t ir) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    log_file = fopen("adpd144ri_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return;
    }

    fprintf(log_file, "%s,%u,%u\n", timestamp, red, ir);
    fclose(log_file);
}

// Control LED based on IR value
void control_led(uint16_t ir) {
    if (ir > IR_THRESHOLD) {
        gpioWrite(GPIO_LED, 1); // Turn LED on
    } else {
        gpioWrite(GPIO_LED, 0); // Turn LED off
    }
}

// Signal handler
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_fd >= 0) {
        i2cClose(i2c_fd);
    }
    gpioWrite(GPIO_LED, 0); // Turn off LED
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }
}

