#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define AUDIO_INPUT_PIN 17
#define GAIN_SELECT_PIN 18

// Define gain level
#define GAIN_LEVEL 0 // LOW for 60dB gain

// Define sampling rate
#define SAMPLING_RATE 10000 // 10 kHz

// Define log file name
#define LOG_FILE "audio_log.txt"

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int set_gain(int gain_level);
int sample_audio();
int detect_rising_edge(int current_sample, int previous_sample);
int log_event(int level);
void signal_handler(int signal);
void cleanup();

// Structure to hold GPIO configuration
typedef struct {
    int audio_pin;
    int gain_pin;
} gpio_config_t;

// Structure to hold program state
typedef struct {
    int previous_sample;
} program_state_t;

// Initialize GPIO
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(AUDIO_INPUT_PIN, PI_INPUT);
    gpioSetMode(GAIN_SELECT_PIN, PI_OUTPUT);

    return 0;
}

// Set gain level
int set_gain(int gain_level) {
    gpioWrite(GAIN_SELECT_PIN, gain_level);
    return 0;
}

// Sample audio
int sample_audio() {
    return gpioRead(AUDIO_INPUT_PIN);
}

// Detect rising edge
int detect_rising_edge(int current_sample, int previous_sample) {
    return (previous_sample == 0 && current_sample == 1);
}

// Log event
int log_event(int level) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s %d\n", timestamp, level);
        fflush(log_file); // Ensure data is written to file immediately
        return 0;
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
        return 1;
    }
}

// Signal handler
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Set gain
    set_gain(GAIN_LEVEL);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    // Print startup message
    printf("Audio event detection started. Logging to %s\n", LOG_FILE);

    program_state_t state = {0}; // Initialize previous sample to 0

    // Main loop
    while (running) {
        int current_sample = sample_audio();

        if (detect_rising_edge(current_sample, state.previous_sample)) {
            log_event(1); // Log rising edge
        }

        state.previous_sample = current_sample;

        // Delay to achieve desired sampling rate
        gpioDelay(1000000 / SAMPLING_RATE); // Delay in microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

