#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

#define GPIO_PIN 17
#define DEBOUNCE_DELAY_MS 50
#define INTRUSION_DURATION_S 5

static volatile int running = 1;

// Structure to hold program state
typedef struct {
    int gpio_initialized;
} ProgramState;

ProgramState state = {0};

void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return -1;
    }
    state.gpio_initialized = 1;

    if (gpioSetMode(GPIO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input: %s\n", GPIO_PIN, strerror(errno));
        gpioTerminate();
        state.gpio_initialized = 0;
        return -1;
    }

    if (gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Failed to set pull-down resistor on GPIO %d: %s\n", GPIO_PIN, strerror(errno));
        gpioTerminate();
        state.gpio_initialized = 0;
        return -1;
    }

    return 0;
}

void cleanup_gpio() {
    if (state.gpio_initialized) {
        gpioTerminate();
        state.gpio_initialized = 0;
    }
}

int main() {
    struct timespec start_time, current_time;
    int touch_detected = 0;
    int intrusion_active = 0;

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    printf("Monitoring GPIO %d for touch events...\n", GPIO_PIN);

    while (running) {
        int sensor_value = gpioRead(GPIO_PIN);

        if (sensor_value < 0) {
            fprintf(stderr, "Error reading GPIO %d: %s\n", GPIO_PIN, strerror(errno));
            cleanup_gpio();
            return EXIT_FAILURE;
        }

        if (sensor_value == 1) {
            if (!touch_detected) {
                // Debounce delay
                gpioDelay(DEBOUNCE_DELAY_MS * 1000); // Convert ms to microseconds
                sensor_value = gpioRead(GPIO_PIN);
                if (sensor_value == 1) {
                    clock_gettime(CLOCK_MONOTONIC, &start_time);
                    touch_detected = 1;
                    intrusion_active = 1;
                    printf("Touch detected on GPIO %d\n", GPIO_PIN);
                }
            } else {
                if (intrusion_active) {
                    clock_gettime(CLOCK_MONOTONIC, &current_time);
                    double elapsed_time = (current_time.tv_sec - start_time.tv_sec) + (current_time.tv_nsec - start_time.tv_nsec) / 1e9;

                    if (elapsed_time > INTRUSION_DURATION_S) {
                        printf("INTRUSION ALERT: Touch event on GPIO %d detected for %f seconds!\n", GPIO_PIN, elapsed_time);
                        intrusion_active = 0; // Reset intrusion flag
                    }
                }
            }
        } else {
            touch_detected = 0;
            intrusion_active = 0; // Reset intrusion flag when released
        }

        gpioDelay(100 * 1000); // Poll every 100ms
    }

    cleanup_gpio();
    printf("Program terminated.\n");
    return EXIT_SUCCESS;
}

