                if (intrusion_active) {
                    clock_gettime(CLOCK_MONOTONIC, &current_time);
                    double elapsed_time = (current_time.tv_sec - start_time.tv_sec) + (current_time.tv_nsec - start_time.tv_nsec) / 1e9;

                    if (elapsed_time > INTRUSION_DURATION_S) {
                        printf("INTRUSION ALERT: Touch event on GPIO %d detected for %f seconds!\n", GPIO_PIN, elapsed_time);
                        intrusion_active = 0; // Reset intrusion flag
                    }
                }
            }
        } else {
            touch_detected = 0;
            intrusion_active = 0; // Reset intrusion flag when released
        }

        gpioDelay(100 * 1000); // Poll every 100ms
    }

    cleanup_gpio();
    printf("Program terminated.\n");
    return EXIT_SUCCESS;
}

