// Constants
#define GPIO_PIN 17
#define SAMPLE_RATE 44100
#define NUM_CHANNELS 2
#define SAMPLE_SIZE 2 // Bytes per sample (16-bit)
#define PCM_FILE "audio_capture.pcm"
#define BUFFER_SIZE 1024 // Adjust as needed

// Global variables
static volatile int running = 1;
static snd_pcm_t *pcm_handle = NULL;
static FILE *pcm_file = NULL;

// Function prototypes
int initialize_alsa(snd_pcm_t **pcm_handle);
int initialize_gpio(int gpio_pin);
int select_left_channel(int gpio_pin);
int capture_audio(snd_pcm_t *pcm_handle, FILE *pcm_file);
int write_to_file(FILE *pcm_file, short *buffer, int frames);
void signal_handler(int sig);
void cleanup(snd_pcm_t *pcm_handle, FILE *pcm_file);

// Signal handler for graceful termination
void signal_handler(int sig) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", sig);
}

// Initialize ALSA for I2S audio capture
int initialize_alsa(snd_pcm_t **pcm_handle) {
    snd_pcm_hw_params_t *hw_params;
    int err;

    if ((err = snd_pcm_open(pcm_handle, "default", SND_PCM_STREAM_CAPTURE, 0)) < 0) {
        fprintf(stderr, "Error opening PCM device: %s\n", snd_strerror(err));
        return -1;
    }

    snd_pcm_hw_params_alloca(&hw_params);

    if ((err = snd_pcm_hw_params_any(*pcm_handle, hw_params)) < 0) {
        fprintf(stderr, "Error setting HW params: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    if ((err = snd_pcm_hw_params_set_access(*pcm_handle, hw_params, SND_PCM_ACCESS_RW_INTERLEAVED)) < 0) {
        fprintf(stderr, "Error setting access: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    if ((err = snd_pcm_hw_params_set_format(*pcm_handle, hw_params, SND_PCM_FORMAT_S16_LE)) < 0) {
        fprintf(stderr, "Error setting format: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    if ((err = snd_pcm_hw_params_set_channels(*pcm_handle, hw_params, NUM_CHANNELS)) < 0) {
        fprintf(stderr, "Error setting channels: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    unsigned int rate = SAMPLE_RATE;
    if ((err = snd_pcm_hw_params_set_rate_near(*pcm_handle, hw_params, &rate, 0)) < 0) {
        fprintf(stderr, "Error setting rate: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    if ((err = snd_pcm_hw_params(*pcm_handle, hw_params)) < 0) {
        fprintf(stderr, "Error setting HW params: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    return 0;
}

// Initialize GPIO using pigpio
int initialize_gpio(int gpio_pin) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(gpio_pin, PI_OUTPUT);
    return 0;
}

// Select the left channel by setting GPIO high
int select_left_channel(int gpio_pin) {
    gpioWrite(gpio_pin, 1); // Set GPIO high
    return 0;
}

// Capture audio data from the I2S microphone
int capture_audio(snd_pcm_t *pcm_handle, FILE *pcm_file) {
    short buffer[BUFFER_SIZE * NUM_CHANNELS]; // Allocate buffer for interleaved data
    int frames = BUFFER_SIZE;
    int err;

    while (running) {
        if ((err = snd_pcm_readi(pcm_handle, buffer, frames)) != frames) {
            fprintf(stderr, "Error reading PCM data: %s\n", snd_strerror(err));
            return -1;
        }

        // Write the left channel data to the file
        if (write_to_file(pcm_file, buffer, frames) != 0) {
            fprintf(stderr, "Error writing to file\n");
            return -1;
        }
    }

    return 0;
}

// Write audio data to the file
int write_to_file(FILE *pcm_file, short *buffer, int frames) {
    size_t bytes_to_write = frames * NUM_CHANNELS * SAMPLE_SIZE;
    size_t bytes_written = fwrite(buffer, 1, bytes_to_write, pcm_file);

    if (bytes_written != bytes_to_write) {
        fprintf(stderr, "Error writing to file: wrote %zu bytes, expected %zu\n", bytes_written, bytes_to_write);
        return -1;
    }

    return 0;
}

// Cleanup resources before exiting
void cleanup(snd_pcm_t *pcm_handle, FILE *pcm_file) {
    printf("Cleaning up...\n");

    if (pcm_handle) {
        snd_pcm_drain(pcm_handle);
        snd_pcm_close(pcm_handle);
    }

    if (pcm_file) {
        fclose(pcm_file);
    }

    gpioWrite(GPIO_PIN, 0); // Set GPIO low
    gpioTerminate();
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize ALSA
    if (initialize_alsa(&pcm_handle) != 0) {
        fprintf(stderr, "ALSA initialization failed\n");
        return 1;
    }

    // Initialize GPIO
    if (initialize_gpio(GPIO_PIN) != 0) {
        fprintf(stderr, "GPIO initialization failed\n");
        cleanup(pcm_handle, pcm_file);
        return 1;
    }

    // Select the left channel
    if (select_left_channel(GPIO_PIN) != 0) {
        fprintf(stderr, "Failed to select left channel\n");
        cleanup(pcm_handle, pcm_file);
        return 1;
    }

    // Open PCM file for writing
    pcm_file = fopen(PCM_FILE, "wb");
    if (!pcm_file) {
        fprintf(stderr, "Error opening PCM file for writing\n");
        cleanup(pcm_handle, pcm_file);
        return 1;
    }

    // Capture audio
    printf("Capturing audio... Press Ctrl+C to stop.\n");
    if (capture_audio(pcm_handle, pcm_file) != 0) {
        fprintf(stderr, "Audio capture failed\n");
        cleanup(pcm_handle, pcm_file);
        return 1;
    }

    // Cleanup and exit
    cleanup(pcm_handle, pcm_file);
    printf("Audio capture complete. File saved as %s\n", PCM_FILE);
    return 0;
}

