#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define FLAME_SENSOR_PIN 4
#define FAN_PIN 18

// Define PWM frequency
#define PWM_FREQUENCY 100

// Define debounce time (in milliseconds)
#define DEBOUNCE_TIME 50

// Define timeout time (in milliseconds)
#define TIMEOUT_TIME 5000

// Global variables
FILE *log_file;
int running = 1;

// Function prototypes
int initialize_gpio();
int read_flame_sensor();
void control_fan(int flame_detected);
void log_event(const char *event_type, const char *timestamp);
void signal_handler(int signal);
char* get_iso8601_timestamp();

// Function to get ISO 8601 timestamp
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Function to initialize GPIO
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT);
    gpioSetMode(FAN_PIN, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(FAN_PIN, PWM_FREQUENCY);
    gpioPWM(FAN_PIN, 0); // Initially turn off the fan

    return 0;
}

// Function to read the flame sensor with debouncing
int read_flame_sensor() {
    int i;
    int low_count = 0;

    for (i = 0; i < 10; i++) { // Read 10 times for debouncing
        int value = gpioRead(FLAME_SENSOR_PIN);
        if (value == 0) {
            low_count++;
        }
        gpioDelay(DEBOUNCE_TIME / 10); // Divide debounce time for multiple reads
    }

    return (low_count >= 5) ? 1 : 0; // Flame detected if LOW is read most of the time
}

// Function to control the fan using PWM
void control_fan(int flame_detected) {
    if (flame_detected) {
        gpioPWM(FAN_PIN, 128); // 50% duty cycle (128/255)
    } else {
        gpioPWM(FAN_PIN, 0);   // Turn off the fan
    }
}

// Function to log events to a file
void log_event(const char *event_type, const char *timestamp) {
    if (log_file != NULL) {
        fprintf(log_file, "%s: %s\n", timestamp, event_type);
        fflush(log_file); // Ensure the log is written immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("flame_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Log program start
    char* timestamp = get_iso8601_timestamp();
    log_event("Program Start", timestamp);
    free(timestamp);

    int last_flame_state = 0; // 0: no flame, 1: flame detected
    int timeout_counter = 0;

    // Main loop
    while (running) {
        int flame_detected = read_flame_sensor();

        if (flame_detected) {
            timeout_counter = 0; // Reset timeout counter
            if (!last_flame_state) {
                // Flame detected
                last_flame_state = 1;
                timestamp = get_iso8601_timestamp();
                log_event("Flame Detected", timestamp);
                free(timestamp);
                control_fan(1);
            }
        } else {
            timeout_counter += DEBOUNCE_TIME;
            if (timeout_counter >= TIMEOUT_TIME) {
                // Sensor absent
                timeout_counter = 0;
                fprintf(stderr, "Warning: Sensor absent or not functioning properly.\n");
            }
            if (last_flame_state) {
                // Flame ended
                last_flame_state = 0;
                timestamp = get_iso8601_timestamp();
                log_event("Flame Ended", timestamp);
                free(timestamp);
                control_fan(0);
            }
        }

        gpioDelay(DEBOUNCE_TIME);
    }

    // Cleanup
    printf("Cleaning up...\n");
    gpioPWM(FAN_PIN, 0); // Turn off the fan
    gpioTerminate();      // Terminate pigpio
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Log program shutdown
    timestamp = get_iso8601_timestamp();
    log_event("Program Shutdown", timestamp);
    free(timestamp);

    return 0;
}

