// Function Prototypes
int initialize_spi();
int initialize_gpio();
int initialize_logging();
void cleanup();
void signal_handler(int signal);
void frame_trigger_callback(int gpio, int level, uint32_t tick);
void data_ready_callback(int gpio, int level, uint32_t tick);
