#include <signal.h>
#include <string.h>
#include <unistd.h>

#define FLAME_SENSOR_GPIO 20
#define LOG_FILE "flame_log.txt"

static volatile int running = 1;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to get the current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp string

    if (timestamp == NULL) {
        perror("Failed to allocate memory for timestamp");
        return NULL;
    }

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    return timestamp;
}

// Function to log the flame state to a file
int log_flame_state(const char *timestamp, int flame_detected) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1;
    }

    if (flame_detected) {
        fprintf(fp, "%s Flame Detected\n", timestamp);
    } else {
        fprintf(fp, "%s Flame Cleared\n", timestamp);
    }

    if (fclose(fp) != 0) {
        perror("Error closing log file");
        return -1;
    }

    return 0;
}

int main() {
    int flame_state = 0; // 0: cleared, 1: detected
    int current_state;
    char *timestamp;

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO20 as an input
    gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT);

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        current_state = gpioRead(FLAME_SENSOR_GPIO);

        if (current_state < 0) {
            fprintf(stderr, "Error reading GPIO state\n");
            break; // Exit the loop on error
        }

        if (current_state != flame_state) {
            flame_state = current_state;

            timestamp = get_iso8601_timestamp();
            if (timestamp != NULL) {
                if (log_flame_state(timestamp, flame_state) != 0) {
                    fprintf(stderr, "Error logging flame state\n");
                }
                free(timestamp); // Free the allocated memory
            } else {
                fprintf(stderr, "Failed to get timestamp\n");
            }
        }

        gpioDelay(100); // Wait 100ms
    }

    // Terminate pigpio
    gpioTerminate();

    printf("Flame sensor monitoring stopped.\n");

    return 0;
}

