#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define OPT3001_ADDR 0x44
#define CONFIG_REG 0x01
#define RESULT_REG 0x00
#define LUX_SCALE 0.01
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10
#define LOG_FILE "light_data.txt"

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int configure_sensor();
int read_sensor_data(unsigned int *raw_data);
float convert_to_lux(unsigned int raw_data);
char* get_iso8601_timestamp();
int log_data(float lux_value);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize I2C bus
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, OPT3001_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Configure OPT3001 sensor
int configure_sensor() {
    unsigned char config_data[2] = {0x00, 0x10}; // Continuous conversion mode, auto range
    int result = i2cWriteI2CBlockData(i2c_handle, CONFIG_REG, config_data, 2);
    if (result < 0) {
        fprintf(stderr, "Error writing to config register: %d\n", result);
        return -1;
    }
    return 0;
}

// Read sensor data
int read_sensor_data(unsigned int *raw_data) {
    int result = i2cReadI2CBlockData(i2c_handle, RESULT_REG, (char*)raw_data, 2);
    if (result < 0) {
        fprintf(stderr, "Error reading from result register: %d\n", result);
        return -1;
    }
    return 0;
}

// Convert raw data to lux
float convert_to_lux(unsigned int raw_data) {
    unsigned int exponent = (raw_data >> 12) & 0x0F;
    unsigned int result = raw_data & 0x0FFF;
    return result * LUX_SCALE * (1 << exponent);
}

// Get ISO-8601 timestamp
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for timestamp

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Log data to file
int log_data(float lux_value) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return -1;
    }

    char *timestamp = get_iso8601_timestamp();
    fprintf(fp, "%s, %.4f\n", timestamp, lux_value);
    free(timestamp); // Free the allocated memory
    fclose(fp);
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Configure sensor
    if (configure_sensor() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("OPT3001 sensor initialized and configured. Logging data to %s\n", LOG_FILE);

    // Main loop
    while (!terminate) {
        unsigned int raw_data;
        int retries = 0;

        // Retry loop for reading sensor data
        while (retries < MAX_RETRIES) {
            if (read_sensor_data(&raw_data) == 0) {
                break; // Success, exit retry loop
            } else {
                retries++;
                gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            }
        }

        if (retries == MAX_RETRIES) {
            fprintf(stderr, "Failed to read sensor data after %d retries. Retrying I2C initialization.\n", MAX_RETRIES);
            i2cClose(i2c_handle);
            if (init_i2c() != 0) {
                fprintf(stderr, "Failed to re-initialize I2C. Exiting.\n");
                break; // Exit main loop if re-initialization fails
            }
            if (configure_sensor() != 0) {
                fprintf(stderr, "Failed to re-configure sensor. Exiting.\n");
                break;
            }
            continue; // Skip to the next iteration
        }

        // Convert to lux
        float lux_value = convert_to_lux(raw_data);

        // Log data
        if (log_data(lux_value) != 0) {
            fprintf(stderr, "Failed to log data.\n");
        }

        // Delay for approximately 100ms conversion time
        gpioDelay(100 * 1000); // Delay in microseconds
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

