    }
    return 0;
}

// Convert raw data to lux
float convert_to_lux(unsigned int raw_data) {
    unsigned int exponent = (raw_data >> 12) & 0x0F;
    unsigned int result = raw_data & 0x0FFF;
    return result * LUX_SCALE * (1 << exponent);
}

// Get ISO-8601 timestamp
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for timestamp

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Log data to file
int log_data(float lux_value) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return -1;
    }

    char *timestamp = get_iso8601_timestamp();
    fprintf(fp, "%s, %.4f\n", timestamp, lux_value);
    free(timestamp); // Free the allocated memory
    fclose(fp);
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Configure sensor
    if (configure_sensor() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("OPT3001 sensor initialized and configured. Logging data to %s\n", LOG_FILE);

    // Main loop
    while (!terminate) {
        unsigned int raw_data;
        int retries = 0;

        // Retry loop for reading sensor data
        while (retries < MAX_RETRIES) {
            if (read_sensor_data(&raw_data) == 0) {
                break; // Success, exit retry loop
            } else {
                retries++;
                gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            }
        }

        if (retries == MAX_RETRIES) {
            fprintf(stderr, "Failed to read sensor data after %d retries. Retrying I2C initialization.\n", MAX_RETRIES);
            i2cClose(i2c_handle);
            if (init_i2c() != 0) {
                fprintf(stderr, "Failed to re-initialize I2C. Exiting.\n");
                break; // Exit main loop if re-initialization fails
            }
            if (configure_sensor() != 0) {
                fprintf(stderr, "Failed to re-configure sensor. Exiting.\n");
                break;
            }
            continue; // Skip to the next iteration
        }

        // Convert to lux
        float lux_value = convert_to_lux(raw_data);

        // Log data
        if (log_data(lux_value) != 0) {
            fprintf(stderr, "Failed to log data.\n");
        }

        // Delay for approximately 100ms conversion time
        gpioDelay(100 * 1000); // Delay in microseconds
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

