#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins for the sensors
#define LEFT_SENSOR_PIN 17
#define CENTER_SENSOR_PIN 18
#define RIGHT_SENSOR_PIN 27

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

int main() {
    int left_value, center_value, right_value;

    // Register signal handlers for SIGINT and SIGTERM
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Error: Could not register SIGINT handler\n");
        return 1;
    }
    if (signal(SIGTERM, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Error: Could not register SIGTERM handler\n");
        return 1;
    }

    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs
    if (gpioSetMode(LEFT_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: Could not set GPIO%d as input\n", LEFT_SENSOR_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(CENTER_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: Could not set GPIO%d as input\n", CENTER_SENSOR_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(RIGHT_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: Could not set GPIO%d as input\n", RIGHT_SENSOR_PIN);
        gpioTerminate();
        return 1;
    }

    // Main loop to read sensor values
    while (program_running) {
        // Read the left sensor value
        left_value = gpioRead(LEFT_SENSOR_PIN);
        if (left_value < 0) {
            fprintf(stderr, "Error: Could not read GPIO%d\n", LEFT_SENSOR_PIN);
            program_running = 0; // Exit loop on error
            continue; // Skip to next iteration
        }

        // Read the center sensor value
        center_value = gpioRead(CENTER_SENSOR_PIN);
        if (center_value < 0) {
            fprintf(stderr, "Error: Could not read GPIO%d\n", CENTER_SENSOR_PIN);
            program_running = 0; // Exit loop on error
            continue; // Skip to next iteration
        }

        // Read the right sensor value
        right_value = gpioRead(RIGHT_SENSOR_PIN);
        if (right_value < 0) {
            fprintf(stderr, "Error: Could not read GPIO%d\n", RIGHT_SENSOR_PIN);
            program_running = 0; // Exit loop on error
            continue; // Skip to next iteration
        }

        // Print the sensor values to the console
        printf("Left: %d, Center: %d, Right: %d\n", left_value, center_value, right_value);

        // Wait for 50 milliseconds
        usleep(50000);
    }

    // Terminate the pigpio library before exiting
    gpioTerminate();

    return 0;
}

