// Define the GPIO pins connected to the TTP226 channels
const int gpio_pins[] = {2, 3, 4, 5, 6, 7, 8, 9};
const int num_channels = sizeof(gpio_pins) / sizeof(gpio_pins[0]);

// Structure to hold program state
typedef struct {
    int running;
} ProgramState;

ProgramState state = {1}; // Initialize running to 1

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    if (signal == SIGINT) {
        fprintf(stderr, "\nCaught SIGINT, exiting gracefully...\n");
        state.running = 0; // Set running to 0 to exit the main loop
    }
}

// Function to read the state of a single channel
int read_channel(int gpio_pin) {
    int value = gpioRead(gpio_pin);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO pin %d: %d\n", gpio_pin, value);
        return -1; // Indicate an error
    }
    return value;
}

// Function to log the sensor data with a timestamp
void log_sensor_data(int *channel_states) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s ", timestamp);
    for (int i = 0; i < num_channels; i++) {
        printf("%d", channel_states[i]);
    }
    printf("\n");
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set the GPIO pins as inputs
    for (int i = 0; i < num_channels; i++) {
        if (gpioSetMode(gpio_pins[i], PI_INPUT) != 0) {
            fprintf(stderr, "Failed to set GPIO %d as input\n", gpio_pins[i]);
            gpioTerminate();
            return 1;
        }
    }

    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Main loop to read and log sensor data
    while (state.running) {
        int channel_states[num_channels];

        // Read the state of each channel
        for (int i = 0; i < num_channels; i++) {
            int state = read_channel(gpio_pins[i]);
            if (state == -1) {
                // Error reading channel, exit the loop
                break;
            }
            channel_states[i] = state;
        }

        // Log the sensor data if no errors occurred
        if (channel_states[0] != -1) {
            log_sensor_data(channel_states);
        }

        // Wait for 100 milliseconds
        gpioDelay(100000); // 100 ms = 100000 microseconds
    }

    // Terminate the pigpio library before exiting
    gpioTerminate();
    fprintf(stderr, "pigpio terminated.\n");
    return 0;
}

