void signal_handler(int signal) {
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
    program_running = 0;
}

// Function to read the touch sensor data
int read_touch_sensor(int *channel_values) {
    int result = 0; // Initialize result to 0 (success)
    result |= (gpioRead(CH1_PIN) << 0);
    result |= (gpioRead(CH2_PIN) << 1);
    result |= (gpioRead(CH3_PIN) << 2);
    result |= (gpioRead(CH4_PIN) << 3);
    result |= (gpioRead(CH5_PIN) << 4);
    result |= (gpioRead(CH6_PIN) << 5);
    result |= (gpioRead(CH7_PIN) << 6);
    result |= (gpioRead(CH8_PIN) << 7);

    // Validate the return value (optional, but good practice)
    if (result < 0) {
        fprintf(stderr, "Error reading touch sensor data: %d\n", result);
        return -1; // Indicate an error
    }

    return result;
}

int main() {
    // Register signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Configure GPIO pins as inputs with pull-down resistors
    gpioSetMode(CH1_PIN, PI_INPUT);
    gpioSetPullUpDown(CH1_PIN, PI_PUD_DOWN);
    gpioSetMode(CH2_PIN, PI_INPUT);
    gpioSetPullUpDown(CH2_PIN, PI_PUD_DOWN);
    gpioSetMode(CH3_PIN, PI_INPUT);
    gpioSetPullUpDown(CH3_PIN, PI_PUD_DOWN);
