    gpioSetPullUpDown(CH6_PIN, PI_PUD_DOWN);
    gpioSetMode(CH7_PIN, PI_INPUT);
    gpioSetPullUpDown(CH7_PIN, PI_PUD_DOWN);
    gpioSetMode(CH8_PIN, PI_INPUT);
    gpioSetPullUpDown(CH8_PIN, PI_PUD_DOWN);

    // Main loop
    while (program_running) {
        // Read the touch sensor data
        int sensor_data = read_touch_sensor(NULL);

        // Check for errors during sensor reading
        if (sensor_data < 0) {
            fprintf(stderr, "Error reading sensor data, exiting...\n");
            break; // Exit the loop on error
        }

        // Print the sensor data
        printf("[+%ld ms] CH1=%d CH2=%d CH3=%d CH4=%d CH5=%d CH6=%d CH7=%d CH8=%d\n",
               time(NULL) * 1000, // Approximate time in milliseconds
               (sensor_data >> 0) & 1,
               (sensor_data >> 1) & 1,
               (sensor_data >> 2) & 1,
