#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define the GPIO pins for the touch sensor channels
const int touch_pins[] = {2, 3, 4, 17, 27, 22, 10, 9};
const int num_channels = 8;

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nCaught SIGINT, exiting gracefully...\n");
}

// Function to get the current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp string

    if (timestamp == NULL) {
        fprintf(stderr, "Error: Failed to allocate memory for timestamp.\n");
        return NULL; // Return NULL to indicate failure
    }

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    return timestamp;
}

// Function to read the state of all touch sensor channels
int read_touch_sensors(int *channel_states) {
    for (int i = 0; i < num_channels; i++) {
        channel_states[i] = gpioRead(touch_pins[i]);
        if (channel_states[i] < 0) {
            fprintf(stderr, "Error reading pin %d: %d\n", touch_pins[i], channel_states[i]);
            return -1; // Indicate an error
        }
    }
    return 0; // Indicate success
}

// Function to print the sensor data to the console in CSV format
void print_sensor_data(const char *timestamp, const int *channel_states) {
    printf("%s", timestamp);
    for (int i = 0; i < num_channels; i++) {
        printf(",%d", channel_states[i]);
    }
    printf("\n");
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Configure the GPIO pins as inputs with pull-up resistors disabled
    for (int i = 0; i < num_channels; i++) {
        if (gpioSetMode(touch_pins[i], PI_INPUT) != 0) {
            fprintf(stderr, "Error setting mode for pin %d\n", touch_pins[i]);
            gpioTerminate();
            return 1;
        }
        if (gpioSetPullUpDown(touch_pins[i], PI_PUD_OFF) != 0) {
            fprintf(stderr, "Error setting pull-up for pin %d\n", touch_pins[i]);
            gpioTerminate();
            return 1;
        }
    }

    // Main loop to read and print sensor data
    while (program_running) {
        int channel_states[num_channels];
        char *timestamp = get_iso8601_timestamp();

        if (timestamp != NULL) {
            if (read_touch_sensors(channel_states) == 0) {
                print_sensor_data(timestamp, channel_states);
            } else {
                fprintf(stderr, "Error reading touch sensors.\n");
            }
            free(timestamp); // Free the allocated memory
        } else {
            fprintf(stderr, "Error getting timestamp.\n");
        }

        gpioDelay(50); // Delay for 50 milliseconds
    }

    // Terminate the pigpio library before exiting
    gpioTerminate();

    return 0;
}

