volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
    gpioTerminate();
    exit(0);
}

int main() {
    int tilt_state = -1; // Initialize to an invalid state
    int current_state;

    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Configure GPIO pin as input with pull-up resistor
    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP);

    printf("Tilt sensor monitoring started. Press Ctrl+C to exit.\n");

    while (program_running) {
        current_state = gpioRead(GPIO_PIN);

        if (current_state == PI_BAD_GPIO) {
            fprintf(stderr, "Error reading GPIO pin %d\n", GPIO_PIN);
            gpioTerminate();
            return 1;
        }

        if (current_state != tilt_state) {
            tilt_state = current_state;
            if (tilt_state == 0) {
                printf("Tilted\n");
            } else {
                printf("Not Tilted\n");
            }
            fflush(stdout); // Ensure immediate output
        }

        gpioDelay(100); // Wait 100ms
    }

    // Terminate pigpio library before exiting
    gpioTerminate();
    return 0;
}

