#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define SI1145_ADDR 0x60
#define UV_INDEX_REG 0x2C
#define ALS_VISIBLE_REG 0x22
#define CSV_FILE "uv_als_log.csv"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_sensor_data(int *uv_index, int *als_visible);
void log_data(int uv_index, int als_visible);
void signal_handler(int signal);
void cleanup();

// Structure to hold sensor data
typedef struct {
    int uv_index;
    int als_visible;
} sensor_data_t;

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SI1145_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read sensor data
int read_sensor_data(int *uv_index, int *als_visible) {
    int result;

    // Read UV Index
    result = i2cReadByteData(i2c_handle, UV_INDEX_REG);
    if (result < 0) {
        fprintf(stderr, "Error reading UV Index: %d\n", result);
        return -1;
    }
    *uv_index = result;

    // Read ALS Visible
    result = i2cReadByteData(i2c_handle, ALS_VISIBLE_REG);
    if (result < 0) {
        fprintf(stderr, "Error reading ALS Visible: %d\n", result);
        return -1;
    }
    *als_visible = result;

    return 0;
}

// Log data to CSV file
void log_data(int uv_index, int als_visible) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%d,%d\n", timestamp, uv_index, als_visible);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(CSV_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        if (read_sensor_data(&sensor_data.uv_index, &sensor_data.als_visible) == 0) {
            printf("UV Index: %d, ALS Visible: %d\n", sensor_data.uv_index, sensor_data.als_visible);
            log_data(sensor_data.uv_index, sensor_data.als_visible);
        } else {
            fprintf(stderr, "Error reading sensor data. Retrying...\n");
        }

        gpioSleep(PI_TIME_RELATIVE, 1, 0); // Sleep for 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

