#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SLF3S_ADDR 0x36
#define ALARM_GPIO 17
#define START_COMMAND 0x00
#define MEASUREMENT_COMMAND 0x3608
#define CRC_POLYNOMIAL 0x31
#define CRC_INITIAL_VALUE 0xFF
#define VALID_FLOW_RATE_MIN 0.0
#define VALID_FLOW_RATE_MAX 1000.0
#define ALARM_THRESHOLD 0.5

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int handle;
    int address;
} sensor_t;

// Function prototypes
int init_i2c();
int init_gpio();
int start_sensor(int handle);
int read_sensor(int handle, float *flow_rate);
uint8_t calculate_crc(uint8_t data[], int len);
int validate_crc(uint8_t data[], int len);
float convert_to_flow_rate(uint16_t raw_data);
void log_data(float flow_rate1, float flow_rate2, float avg_flow_rate);
void set_alarm(int state);
void signal_handler(int signal);
void cleanup();

// CRC calculation function
uint8_t calculate_crc(uint8_t data[], int len) {
    uint8_t crc = CRC_INITIAL_VALUE;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// CRC validation function
int validate_crc(uint8_t data[], int len) {
    uint8_t crc_calculated = calculate_crc(data, len - 1);
    return (crc_calculated == data[len - 1]);
}

