#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

#define GPIO_PIN 4
#define BUFFER_SIZE 100

// Structure to hold timestamp and sensor value
typedef struct {
    char timestamp[30];
    int sensor_value;
} SensorData;

// Circular buffer
SensorData circular_buffer[BUFFER_SIZE];
int buffer_index = 0;
int buffer_count = 0; // Number of elements in the buffer

// Function prototypes
int initialize_gpio();
int read_sensor();
void add_to_buffer(int sensor_value);
void print_buffer();
void signal_handler(int signal);

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

int main() {
    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize pigpio library
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Error initializing pigpio library.\n");
        return 1;
    }

    printf("Obstacle detection program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read sensor value
        int sensor_value = read_sensor();

        // Add data to circular buffer
        add_to_buffer(sensor_value);

        // Print alert if obstacle detected
        if (sensor_value == 0) {
            printf("Obstacle detected!\n");
        }

        // Wait for 50ms
        gpioDelay(50000); // 50ms = 50000 microseconds
    }

    // Print buffer before exiting
    print_buffer();

    // Terminate pigpio library
    gpioTerminate();

    printf("Program terminated cleanly.\n");
    return 0;
}

// Function to initialize the pigpio library and configure the GPIO pin
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP);

    return 0;
}

// Function to read the sensor value
int read_sensor() {
    return gpioRead(GPIO_PIN);
}

// Function to add data to the circular buffer
void add_to_buffer(int sensor_value) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    strcpy(circular_buffer[buffer_index].timestamp, timestamp);
    circular_buffer[buffer_index].sensor_value = sensor_value;

    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) {
        buffer_count++;
    }
}

// Function to print the contents of the circular buffer
void print_buffer() {
    printf("\n--- Sensor Data Log ---\n");
    int start_index = (buffer_index - buffer_count + BUFFER_SIZE) % BUFFER_SIZE;
    for (int i = 0; i < buffer_count; i++) {
        int index = (start_index + i) % BUFFER_SIZE;
        printf("Timestamp: %s, Sensor Value: %d\n", circular_buffer[index].timestamp, circular_buffer[index].sensor_value);
    }
    printf("--- End of Log ---\n");
}

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Received SIGINT. Exiting gracefully...\n");
        program_running = 0;
    }
}

