#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define D7S_ADDR 0x1D
#define SDA_PIN 2
#define SCL_PIN 3
#define ACCEL_X_LSB 0x28
#define ACCEL_X_MSB 0x29
#define ACCEL_Y_LSB 0x2A
#define ACCEL_Y_MSB 0x2B
#define ACCEL_Z_LSB 0x2C
#define ACCEL_Z_MSB 0x2D
#define MODE_REG 0x16
#define MODE_VALUE 0x01 // Example mode value
#define CSV_FILE "fan_health.csv"

// Global variables
int i2c_handle;
FILE *csv_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int set_sensor_mode(int mode);
int read_acceleration(int *x, int *y, int *z);
int write_data_to_csv(int x, int y, int z);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, D7S_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Set sensor mode
int set_sensor_mode(int mode) {
    int result = i2cWriteByteData(i2c_handle, MODE_REG, mode);
    if (result < 0) {
        fprintf(stderr, "Error writing to mode register: %d\n", result);
        return -1;
    }
    return 0;
}

// Read acceleration data
int read_acceleration(int *x, int *y, int *z) {
    char buf[6];
    int result = i2cReadI2CBlockData(i2c_handle, ACCEL_X_LSB, buf, 6);
    if (result < 0) {
        fprintf(stderr, "Error reading acceleration data: %d\n", result);
        return -1;
    }

    *x = (int16_t)((buf[1] << 8) | buf[0]);
    *y = (int16_t)((buf[3] << 8) | buf[2]);
    *z = (int16_t)((buf[5] << 8) | buf[4]);

    return 0;
}

