#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Define GPIO pins for the sensors
#define SENSOR1_PIN 17
#define SENSOR2_PIN 18

// Define the stall duration threshold (in seconds)
#define STALL_DURATION 2

// Define the log file name
#define LOG_FILE "stall_log.txt"

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int read_sensor(int pin);
int is_stall(int sensor1_value, int sensor2_value);
int log_stall_event();
void signal_handler(int signal);

// Structure to hold the last stall time
struct {
    time_t last_stall_time;
    int stall_detected;
} stall_state = {0, 0};

// Function to initialize the pigpio library and set GPIO modes
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    gpioSetMode(SENSOR1_PIN, PI_INPUT);
    gpioSetMode(SENSOR2_PIN, PI_INPUT);

    return 0; // Indicate success
}

// Function to read the value from a sensor
int read_sensor(int pin) {
    int value = gpioRead(pin);
    if (value != 0 && value != 1) {
        fprintf(stderr, "Invalid sensor reading: %d from pin %d\n", value, pin);
        return -1; // Indicate error
    }
    return value;
}

// Function to determine if a stall has occurred
int is_stall(int sensor1_value, int sensor2_value) {
    return (sensor1_value == 0 && sensor2_value == 0);
}

// Function to log a stall event to a file
int log_stall_event() {
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%d.%X", tstruct);

    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open\n");
        return 1; // Indicate error
    }

    if (stall_state.stall_detected == 0) {
        fprintf(log_file, "%s Stall detected\n", buf);
        fflush(log_file); // Ensure the data is written to the file immediately
        stall_state.last_stall_time = now;
        stall_state.stall_detected = 1;
        return 0;
    } else {
        double time_diff = difftime(now, stall_state.last_stall_time);
        if (time_diff >= STALL_DURATION) {
            fprintf(log_file, "%s Stall detected (duplicate)\n", buf);
            fflush(log_file);
            stall_state.last_stall_time = now;
            return 0;
        } else {
            return 1; // Stall already logged recently
        }
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Received signal %d, shutting down...\n", signal);

    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }

    gpioTerminate();
    exit(0);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    printf("Monitoring conveyor belt stall...\n");

    // Main loop
    while (running) {
        int sensor1_value = read_sensor(SENSOR1_PIN);
        int sensor2_value = read_sensor(SENSOR2_PIN);

        if (sensor1_value == -1 || sensor2_value == -1) {
            fprintf(stderr, "Error reading sensor values, retrying...\n");
            gpioDelay(100); // Wait 100ms before retrying
            continue;
        }

        if (is_stall(sensor1_value, sensor2_value)) {
            if (log_stall_event() != 0) {
                fprintf(stderr, "Error logging stall event\n");
            }
            stall_state.stall_detected = 1;
        } else {
            stall_state.stall_detected = 0;
        }

        gpioDelay(100); // Check every 100ms
    }

    // Cleanup (should not reach here if signal handler works correctly)
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    return 0;
}

