#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <pthread.h>
#include <unistd.h>

#define GPIO_PIN 4
#define PULSES_PER_REVOLUTION 1.0 // Adjust based on sensor specifications
#define LOG_FILE "rpm_log.txt"

// Global variables
volatile int pulse_count = 0;
FILE *log_file = NULL;
pthread_mutex_t pulse_mutex = PTHREAD_MUTEX_INITIALIZER;
int running = 1;

// Function prototypes
void pulse_callback(int gpio, int level, uint32_t tick, void *user);
void *timer_callback(void *arg);
void signal_handler(int signal);
int initialize();
void cleanup();

// Structure to pass data to the timer thread
typedef struct {
    int timer_id;
} timer_data_t;

int main() {
    if (initialize() != 0) {
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Create a timer thread
    pthread_t timer_thread;
    timer_data_t timer_data;
    timer_data.timer_id = 0; // Example timer ID

    if (pthread_create(&timer_thread, NULL, timer_callback, &timer_data) != 0) {
        perror("Failed to create timer thread");
        cleanup();
        return 1;
    }

    // Main loop (keep the program running until a signal is received)
    while (running) {
        sleep(1); // Sleep for 1 second
    }

    // Wait for the timer thread to finish
    pthread_join(timer_thread, NULL);

    cleanup();
    return 0;
}

// Interrupt callback function
void pulse_callback(int gpio, int level, uint32_t tick, void *user) {
    if (level == PI_HIGH) { // Rising edge
        pthread_mutex_lock(&pulse_mutex);
        pulse_count++;
        pthread_mutex_unlock(&pulse_mutex);
    }
}

// Timer callback function (runs in a separate thread)
void *timer_callback(void *arg) {
    (void)arg; // Suppress unused parameter warning
    while (running) {
        sleep(1); // Wait for 1 second

        pthread_mutex_lock(&pulse_mutex);
        int current_pulse_count = pulse_count;
        pulse_count = 0; // Reset pulse count
        pthread_mutex_unlock(&pulse_mutex);

        // Calculate RPM
        double rpm = (current_pulse_count / PULSES_PER_REVOLUTION) * 60.0;

        // Get current timestamp
        time_t rawtime;
        struct tm *timeinfo;
        char timestamp[20];
        time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        // Log data to file and stdout
        fprintf(log_file, "%s %.2f\n", timestamp, rpm);
        fflush(log_file); // Ensure data is written to disk immediately
        printf("%s %.2f\n", timestamp, rpm);

        if (rpm == 0) {
            fprintf(log_file, "%s Sensor not rotating\n", timestamp);
            fflush(log_file);
            printf("%s Sensor not rotating\n", timestamp);
        }
    }
    return NULL;
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

// Initialization function
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as input with pull-up resistor
    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP);

    // Set up interrupt callback
    if (gpioSetAlertFuncEx(GPIO_PIN, pulse_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set alert function\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");

    // Disable interrupt callback
    gpioSetAlertFuncEx(GPIO_PIN, NULL, NULL);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    pthread_mutex_destroy(&pulse_mutex);

    printf("Cleanup complete.\n");
}

