#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins for the Hall-effect sensors
#define SENSOR_A_GPIO 17
#define SENSOR_B_GPIO 27

// Define the log file name
#define LOG_FILE "rotation_log.txt"

// Define the timestamp format
#define TIMESTAMP_FORMAT "%Y-%m-%d %H:%M:%S.%03d"

// Define the number of milliseconds to sleep in the main loop
#define SLEEP_MS 10

// Define the number of milliseconds to wait for a signal before exiting
#define SHUTDOWN_TIMEOUT_MS 5000

// Define the maximum number of log entries to buffer
#define MAX_LOG_BUFFER_SIZE 100

// Define the log entry structure
typedef struct {
    char timestamp[30];
    char direction[10];
} log_entry_t;

// Define the log buffer structure
typedef struct {
    log_entry_t entries[MAX_LOG_BUFFER_SIZE];
    int head;
    int tail;
    int count;
    pthread_mutex_t mutex;
    pthread_cond_t cond;
} log_buffer_t;

// Global variables
static volatile int running = 1;
static log_buffer_t log_buffer;
static FILE *log_file = NULL;

// Function prototypes
void signal_handler(int signal);
void *log_thread(void *arg);
void log_rotation(const char *direction);
void update_log_buffer(const char *direction);
void flush_log_buffer();
void cleanup();
void init_log_buffer(log_buffer_t *buffer);
int is_log_buffer_empty(const log_buffer_t *buffer);
int is_log_buffer_full(const log_buffer_t *buffer);
int enqueue_log_entry(log_buffer_t *buffer, const char *direction);
int dequeue_log_entry(log_buffer_t *buffer, char *direction);

// Interrupt handler function
void isr_handler(int gpio, int level, uint32_t tick, void *user_data)
{
    static int previous_state = 0; // 0: A=0, B=0; 1: A=1, B=0; 2: A=1, B=1; 3: A=0, B=1
    int current_state = 0;

    // Read the current state of the sensors
    int sensor_a = gpioRead(SENSOR_A_GPIO);
    int sensor_b = gpioRead(SENSOR_B_GPIO);

    if (sensor_a) {
        current_state |= 1;
    }
    if (sensor_b) {
        current_state |= 2;
    }

    // Determine the direction of rotation based on the state transition
    char direction[10];
    if (previous_state == 0) {
        if (current_state == 1) {
            strcpy(direction, "clockwise");
        } else if (current_state == 3) {
            strcpy(direction, "counter-clockwise");
        } else {
            // Invalid state transition
            return;
        }
    } else if (previous_state == 1) {
        if (current_state == 0) {
            strcpy(direction, "clockwise");
        } else if (current_state == 2) {
            strcpy(direction, "counter-clockwise");
        } else {
            // Invalid state transition
            return;
        }
    } else if (previous_state == 2) {
        if (current_state == 3) {
            strcpy(direction, "clockwise");
        } else if (current_state == 1) {
            strcpy(direction, "counter-clockwise");
        } else {
            // Invalid state transition
            return;
        }
    } else if (previous_state == 3) {
        if (current_state == 2) {
            strcpy(direction, "clockwise");
        } else if (current_state == 0) {
            strcpy(direction, "counter-clockwise");
        } else {
            // Invalid state transition
            return;
        }
    } else {
        // Invalid previous state
        return;
    }

    // Update the previous state
    previous_state = current_state;

    // Log the rotation event
    log_rotation(direction);
}

// Function to log a rotation event
void log_rotation(const char *direction)
{
    // Get the current timestamp
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);

    // Format the timestamp
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), TIMESTAMP_FORMAT, &tm_info);
    snprintf(timestamp + strlen(timestamp), 4, ".%03ld", ts.tv_nsec / 1000000);

    // Update the log buffer
    update_log_buffer(direction);
}

// Function to update the log buffer
void update_log_buffer(const char *direction)
{
    pthread_mutex_lock(&log_buffer.mutex);
    enqueue_log_entry(&log_buffer, direction);
    pthread_cond_signal(&log_buffer.cond);
    pthread_mutex_unlock(&log_buffer.mutex);
}

// Function to flush the log buffer to the file
void flush_log_buffer()
{
    pthread_mutex_lock(&log_buffer.mutex);
    while (!is_log_buffer_empty(&log_buffer)) {
        char direction[10];
        dequeue_log_entry(&log_buffer, direction);

        // Get the current timestamp
        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);
        struct tm tm_info;
        localtime_r(&ts.tv_sec, &tm_info);

        // Format the timestamp
        char timestamp[30];
        strftime(timestamp, sizeof(timestamp), TIMESTAMP_FORMAT, &tm_info);
        snprintf(timestamp + strlen(timestamp), 4, ".%03ld", ts.tv_nsec / 1000000);

        // Write the log entry to the file
        fprintf(log_file, "%s %s\n", timestamp, direction);
        fflush(log_file);
    }
    pthread_mutex_unlock(&log_buffer.mutex);
}

// Function to initialize the log buffer
void init_log_buffer(log_buffer_t *buffer)
{
