#include <unistd.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 23
#define LED_PIN 18

// Global variable to track program state for signal handling
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    syslog(LOG_INFO, "Received signal %d, shutting down...", signal);
    program_running = 0;
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }

    // Set touch sensor pin as input
    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        syslog(LOG_ERR, "Failed to set GPIO%d as input", TOUCH_SENSOR_PIN);
        gpioTerminate();
        return -1;
    }

    // Set LED pin as output
    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "Failed to set GPIO%d as output", LED_PIN);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to read the touch sensor
int read_touch_sensor() {
    return gpioRead(TOUCH_SENSOR_PIN);
}

// Function to control the LED
void control_led(int state) {
    gpioWrite(LED_PIN, state);
}

int main() {
    // Open syslog for logging
    openlog("touch_led", LOG_PID | LOG_CONS, LOG_USER);

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        syslog(LOG_ERR, "GPIO initialization failed, exiting");
        closelog();
        return 1;
    }

    syslog(LOG_INFO, "Program started");

    // Main loop
    while (program_running) {
        int touch_detected = read_touch_sensor();

        if (touch_detected == 1) {
            control_led(1); // Turn LED on
            syslog(LOG_INFO, "Touch detected, LED ON");
        } else {
            control_led(0); // Turn LED off
        }

        gpioDelay(50); // Wait 50ms
    }

    // Cleanup before exiting
    syslog(LOG_INFO, "Shutting down...");
    control_led(0); // Turn LED off
    gpioTerminate(); // Release GPIO resources
    syslog(LOG_INFO, "Program terminated");
    closelog();

    return 0;
}

