#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define SENSOR_1_PIN 4
#define SENSOR_2_PIN 17
#define LED_1_PIN 27
#define LED_2_PIN 22

// Define log buffer size
#define LOG_BUFFER_SIZE 100

// Structure to store log entries
typedef struct {
    int sensor_pin;
    time_t timestamp;
    int state;
} LogEntry;

// Circular buffer for log entries
LogEntry log_buffer[LOG_BUFFER_SIZE];
int log_index = 0;
int log_overflow_count = 0;

// Function prototypes
int read_sensor(int pin);
void control_led(int pin, int state);
void log_event(int sensor_pin, int state);
void print_log_buffer();
void signal_handler(int signal);

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(SENSOR_1_PIN, PI_INPUT);
    gpioSetMode(SENSOR_2_PIN, PI_INPUT);
    gpioSetMode(LED_1_PIN, PI_OUTPUT);
    gpioSetMode(LED_2_PIN, PI_OUTPUT);

    // Set pull-down resistors for sensors
    gpioSetPullUpDown(SENSOR_1_PIN, PI_PUD_DOWN);
    gpioSetPullUpDown(SENSOR_2_PIN, PI_PUD_DOWN);

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (program_running) {
        // Read sensor values
        int sensor_1_value = read_sensor(SENSOR_1_PIN);
        int sensor_2_value = read_sensor(SENSOR_2_PIN);

        // Control LEDs based on sensor values
        control_led(LED_1_PIN, sensor_1_value);
        control_led(LED_2_PIN, sensor_2_value);

        // Log events
        log_event(SENSOR_1_PIN, sensor_1_value);
        log_event(SENSOR_2_PIN, sensor_2_value);

        // Delay for debouncing
        gpioDelay(50000); // 50 ms
    }

    // Print log buffer and overflow count before exiting
    print_log_buffer();

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

// Function to read sensor value
int read_sensor(int pin) {
    return gpioRead(pin);
}

// Function to control LED state
void control_led(int pin, int state) {
    gpioWrite(pin, state);
}

// Function to log events
void log_event(int sensor_pin, int state) {
    time_t current_time = time(NULL);

    log_buffer[log_index].sensor_pin = sensor_pin;
    log_buffer[log_index].timestamp = current_time;
    log_buffer[log_index].state = state;

    log_index = (log_index + 1) % LOG_BUFFER_SIZE;

    if (log_index == 0) {
        log_overflow_count++;
    }
}

// Function to print log buffer
void print_log_buffer() {
    printf("Log Buffer:\n");
    for (int i = 0; i < LOG_BUFFER_SIZE; i++) {
        int index = (log_index + i) % LOG_BUFFER_SIZE;
        printf("  Sensor: %d, Timestamp: %ld, State: %d\n", log_buffer[index].sensor_pin, log_buffer[index].timestamp, log_buffer[index].state);
    }
    printf("Log Overflow Count: %d\n", log_overflow_count);
}

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);

    // Turn off LEDs
    control_led(LED_1_PIN, 0);
    control_led(LED_2_PIN, 0);

    // Print log buffer and overflow count
    print_log_buffer();

    // Terminate pigpio library
    gpioTerminate();
}

