#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <pigpio.h>

// Define GPIO pins for the Hall-Effect sensors
#define SENSOR1_GPIO 17
#define SENSOR2_GPIO 18

// Debounce time in milliseconds
#define DEBOUNCE_TIME 5

// Global variables for signal handling and file pointer
volatile sig_atomic_t program_running = 1;
FILE *log_file = NULL;

// Structure to hold sensor states
typedef struct {
    int sensor1_state;
    int sensor2_state;
} SensorStates;

// Function prototypes
int initialize_gpio();
SensorStates read_sensor_states();
void log_data(SensorStates states);
double calculate_rpm(SensorStates current_states, SensorStates previous_states, double time_elapsed);
void signal_handler(int signal);
void cleanup();

// Function to initialize the pigpio library and set GPIO modes
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return -1;
    }

    gpioSetMode(SENSOR1_GPIO, PI_INPUT);
    gpioSetMode(SENSOR2_GPIO, PI_INPUT);

    return 0;
}

// Function to read the states of the Hall-Effect sensors
SensorStates read_sensor_states() {
    SensorStates states;
    states.sensor1_state = gpioRead(SENSOR1_GPIO);
    states.sensor2_state = gpioRead(SENSOR2_GPIO);
    return states;
}

// Function to log the sensor data to a CSV file
void log_data(SensorStates states) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s,%d,%d\n", timestamp, states.sensor1_state, states.sensor2_state);
        fflush(log_file); // Ensure data is written to the file immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Function to calculate the RPM based on sensor transitions
double calculate_rpm(SensorStates current_states, SensorStates previous_states, double time_elapsed) {
    // Define the valid transitions and their corresponding RPM values
    // This is a simplified example; a more robust implementation would
    // consider all possible transitions and their timing.
    if (previous_states.sensor1_state == 0 && current_states.sensor1_state == 1) {
        return 60.0 / time_elapsed; // Assuming one pulse per revolution
    } else if (previous_states.sensor2_state == 0 && current_states.sensor2_state == 1) {
        return 60.0 / time_elapsed; // Assuming one pulse per revolution
    } else {
        return 0.0; // No valid transition detected
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Caught SIGINT, exiting gracefully.\n");
        program_running = 0;
    }
}

// Cleanup function to release resources
void cleanup() {
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open the log file
    log_file = fopen("shaft_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Write the header row if the file is new
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,sensor1_state,sensor2_state\n");
    }
    rewind(log_file);

    SensorStates previous_states = {0, 0};
    SensorStates current_states;
    double start_time, end_time, time_elapsed;
    int last_sensor1_state = gpioRead(SENSOR1_GPIO);
    int last_sensor2_state = gpioRead(SENSOR2_GPIO);

    printf("Monitoring shaft RPM. Press Ctrl+C to exit.\n");

    while (program_running) {
        current_states = read_sensor_states();

        // Debounce sensor 1
        if (current_states.sensor1_state != last_sensor1_state) {
            gpioDelay(DEBOUNCE_TIME * 1000); // Convert ms to microseconds
            current_states.sensor1_state = gpioRead(SENSOR1_GPIO);
        }

        // Debounce sensor 2
        if (current_states.sensor2_state != last_sensor2_state) {
            gpioDelay(DEBOUNCE_TIME * 1000); // Convert ms to microseconds
            current_states.sensor2_state = gpioRead(SENSOR2_GPIO);
        }

        last_sensor1_state = current_states.sensor1_state;
        last_sensor2_state = current_states.sensor2_state;

        if (current_states.sensor1_state != previous_states.sensor1_state ||
            current_states.sensor2_state != previous_states.sensor2_state) {
            start_time = time(NULL);
            log_data(current_states);
            previous_states = current_states;
        }

        end_time = time(NULL);
        time_elapsed = end_time - start_time;

        if (time_elapsed > 0) {
            double rpm = calculate_rpm(current_states, previous_states, time_elapsed);
            printf("RPM: %.2f\n", rpm);
        }

        gpioDelay(10000); // Check every 10ms
    }

    cleanup();
    return 0;
}

