#include <string.h>

// Define GPIO pins
#define SENSOR_1_PIN 17
#define SENSOR_2_PIN 18
#define ALARM_PIN 27

// Define tilt threshold (in seconds)
#define TILT_THRESHOLD 2

// Global variables
FILE *log_file = NULL;
int alarm_active = 0;
time_t tilt_start_time = 0;

// Function prototypes
int initialize_gpio();
int read_sensor(int pin);
int log_event(const char *event_type, int sensor1_state, int sensor2_state);
int activate_alarm();
int deactivate_alarm();
void signal_handler(int signal);
int cleanup();

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(SENSOR_1_PIN, PI_INPUT);
    gpioSetPullUpDown(SENSOR_1_PIN, PI_PUD_DOWN);
    gpioSetMode(SENSOR_2_PIN, PI_INPUT);
    gpioSetPullUpDown(SENSOR_2_PIN, PI_PUD_DOWN);
    gpioSetMode(ALARM_PIN, PI_OUTPUT);
    gpioWrite(ALARM_PIN, 0); // Ensure alarm is initially off

    return 0;
}

// Function to read sensor value
int read_sensor(int pin) {
    return gpioRead(pin);
}

// Function to log events to file
int log_event(const char *event_type, int sensor1_state, int sensor2_state) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", t);

    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open\n");
        return 1;
    }

    fprintf(log_file, "%s - %s - Sensor 1: %d, Sensor 2: %d\n", timestamp, event_type, sensor1_state, sensor2_state);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Function to activate the alarm
int activate_alarm() {
    if (alarm_active) return 0; // Already active
    gpioWrite(ALARM_PIN, 1);
    alarm_active = 1;
    return 0;
}

// Function to deactivate the alarm
int deactivate_alarm() {
    if (!alarm_active) return 0; // Already inactive
    gpioWrite(ALARM_PIN, 0);
    alarm_active = 0;
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    cleanup();
    exit(0);
}

// Cleanup function to release resources
int cleanup() {
    deactivate_alarm();
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    return 0;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("bridge_integrity.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    int sensor1_state = 0;
    int sensor2_state = 0;
    int alarm_triggered = 0;

    printf("Monitoring bridge integrity...\n");

    while (1) {
        // Read sensor values
        int new_sensor1_state = read_sensor(SENSOR_1_PIN);
        int new_sensor2_state = read_sensor(SENSOR_2_PIN);

        // Check for tilt start
        if (new_sensor1_state == 1 || new_sensor2_state == 1) {
            if (alarm_triggered == 0) {
                time(&tilt_start_time);
                alarm_triggered = 1;
            }
        }

        // Check for tilt end
        if (new_sensor1_state == 0 && new_sensor2_state == 0) {
            alarm_triggered = 0;
        }

        // Check if alarm threshold is exceeded
        if (alarm_triggered && (time(NULL) - tilt_start_time >= TILT_THRESHOLD)) {
            if (!alarm_active) {
                activate_alarm();
                log_event("threshold-exceeded", new_sensor1_state, new_sensor2_state);
            }
        } else {
            if (alarm_active) {
                deactivate_alarm();
                log_event("tilt-end", new_sensor1_state, new_sensor2_state);
            }
        }

        // Update sensor states
        sensor1_state = new_sensor1_state;
        sensor2_state = new_sensor2_state;

        // Delay for 100ms
        gpioDelay(100000); // 100ms = 100000 microseconds
    }

    return 0;
}

