#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define D7S_ADDR 0x1D
#define CTRL1_REG 0x20
#define CTRL1_RESET 0x00
#define CTRL1_NORMAL 0x02
#define CTRL2_REG 0x21
#define CTRL2_RESET 0x00
#define CTRL2_CONTINUOUS 0x02
#define DATA_REG 0x28
#define LED_GPIO 17
#define THRESHOLD 500.0
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10
#define POLL_INTERVAL_MS 100

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_sensor();
int read_sensor_data(int16_t *x, int16_t *y, int16_t *z);
double calculate_magnitude(int16_t x, int16_t y, int16_t z);
int log_event(double magnitude);
void alert_led_on();
void alert_led_off();
void signal_handler(int signal);

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Initialize the sensor
int init_sensor() {
    int result;

    // Reset CTRL1 register
    result = i2cWriteByteData(i2c_handle, CTRL1_REG, CTRL1_RESET);
    if (result != 0) {
        fprintf(stderr, "Error resetting CTRL1 register: %d\n", result);
        return -1;
    }
    gpioDelay(1000); // Wait 1ms

    // Set CTRL1 register to normal mode
    result = i2cWriteByteData(i2c_handle, CTRL1_REG, CTRL1_NORMAL);
    if (result != 0) {
        fprintf(stderr, "Error setting CTRL1 register: %d\n", result);
        return -1;
    }
    gpioDelay(1000); // Wait 1ms

    // Reset CTRL2 register
    result = i2cWriteByteData(i2c_handle, CTRL2_REG, CTRL2_RESET);
    if (result != 0) {
        fprintf(stderr, "Error resetting CTRL2 register: %d\n", result);
        return -1;
    }
    gpioDelay(1000); // Wait 1ms

    // Set CTRL2 register to continuous mode
    result = i2cWriteByteData(i2c_handle, CTRL2_REG, CTRL2_CONTINUOUS);
    if (result != 0) {
        fprintf(stderr, "Error setting CTRL2 register: %d\n", result);
        return -1;
    }
    gpioDelay(1000); // Wait 1ms

    return 0;
}

// Read sensor data with retries
int read_sensor_data(int16_t *x, int16_t *y, int16_t *z) {
    char buf[6];
    int result;
    int retries = 0;

    while (retries < RETRY_COUNT) {
        result = i2cReadI2CBlockData(i2c_handle, DATA_REG, buf, 6);
        if (result == 6) {
            *x = (int16_t)((buf[0] << 8) | buf[1]);
            *y = (int16_t)((buf[2] << 8) | buf[3]);
            *z = (int16_t)((buf[4] << 8) | buf[5]);
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read error (attempt %d): %d\n", retries + 1, result);
            gpioDelay(RETRY_DELAY_MS * 1000); // Convert ms to us
            retries++;
        }
    }

    fprintf(stderr, "Failed to read sensor data after %d retries.\n", RETRY_COUNT);
    return -1; // Failure
}

// Calculate Euclidean magnitude
double calculate_magnitude(int16_t x, int16_t y, int16_t z) {
