#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <syslog.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define sensor pins
#define SENSOR_1_PIN 2
#define SENSOR_2_PIN 3
#define SENSOR_3_PIN 4
#define SENSOR_4_PIN 17
#define SENSOR_5_PIN 27

// Debounce time in milliseconds
#define DEBOUNCE_TIME 50

// Global flag for signal handling
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_sensor(int pin);
int debounce_sensor(int pin);
void log_event(int sensor_id, int pin);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    syslog(LOG_INFO, "Received signal %d, terminating...");
    terminate = 1;
}

// Function to read sensor value
int read_sensor(int pin) {
    int value = gpioRead(pin);
    if (value < 0) {
        syslog(LOG_ERR, "Error reading sensor on pin %d: %d", pin, value);
        return -1; // Indicate error
    }
    return value;
}

// Function to debounce sensor
int debounce_sensor(int pin) {
    int i;
    for (i = 0; i < 2; i++) {
        if (read_sensor(pin) == 0) {
            gpioDelay(DEBOUNCE_TIME * 1000); // Delay for debounce time
            if (read_sensor(pin) == 0) {
                return 0; // Flame detected after debounce
            }
        } else {
            return 1; // No flame detected
        }
    }
    return 1; // No flame detected after multiple reads
}

// Function to log flame event
void log_event(int sensor_id, int pin) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];
    FILE *fp;

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fp = fopen("/var/log/flame_events.log", "a");
    if (fp == NULL) {
        syslog(LOG_ERR, "Error opening log file!");
        return;
    }

    flock(fileno(fp), LOCK_EX); // Acquire exclusive lock

    fprintf(fp, "%s - Sensor ID: %d (GPIO %d) - Flame Detected\n", timestamp, sensor_id, pin);
    fflush(fp);

    flock(fileno(fp), LOCK_UN); // Release lock
    fclose(fp);
}

int main() {
    // Initialize syslog
    openlog("flame_monitor", LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_INFO, "Starting flame monitor...");

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set GPIO pins as inputs
    gpioSetMode(SENSOR_1_PIN, PI_INPUT);
    gpioSetMode(SENSOR_2_PIN, PI_INPUT);
    gpioSetMode(SENSOR_3_PIN, PI_INPUT);
    gpioSetMode(SENSOR_4_PIN, PI_INPUT);
    gpioSetMode(SENSOR_5_PIN, PI_INPUT);

    // Main loop
    while (!terminate) {
        if (debounce_sensor(SENSOR_1_PIN) == 0) {
            log_event(1, SENSOR_1_PIN);
        }
        if (debounce_sensor(SENSOR_2_PIN) == 0) {
            log_event(2, SENSOR_2_PIN);
        }
        if (debounce_sensor(SENSOR_3_PIN) == 0) {
            log_event(3, SENSOR_3_PIN);
        }
        if (debounce_sensor(SENSOR_4_PIN) == 0) {
            log_event(4, SENSOR_4_PIN);
        }
        if (debounce_sensor(SENSOR_5_PIN) == 0) {
            log_event(5, SENSOR_5_PIN);
        }

        gpioDelay(1000); // Poll every 1 second
    }

    // Cleanup
    syslog(LOG_INFO, "Terminating flame monitor...");
    gpioTerminate();
    closelog();

    return 0;
}

