#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Define the GPIO pins connected to the TTP226 sensor channels
const int gpio_pins[] = {5, 6, 13, 19, 26, 12, 16, 20};
const int num_pins = sizeof(gpio_pins) / sizeof(gpio_pins[0]);

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to get the current timestamp in ISO 8601 format
void get_iso8601_timestamp(char *timestamp) {
    time_t rawtime;
    struct tm *timeinfo;

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, 21, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
}

int main() {
    int i;
    int current_state[8];
    int previous_state[8];
    char timestamp[21];

    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return 1;
    }

    // Set the GPIO pins as inputs
    for (i = 0; i < num_pins; i++) {
        if (gpioSetMode(gpio_pins[i], PI_INPUT) != 0) {
            fprintf(stderr, "Failed to set GPIO %d as input: %s\n", gpio_pins[i], strerror(errno));
            gpioTerminate();
            return 1;
        }
    }

    // Initialize the previous states to 0 (no touch)
    for (i = 0; i < num_pins; i++) {
        previous_state[i] = 0;
    }

    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop to continuously monitor the sensor states
    while (program_running) {
        for (i = 0; i < num_pins; i++) {
            current_state[i] = gpioRead(gpio_pins[i]);
            if (current_state[i] < 0) {
                fprintf(stderr, "Failed to read GPIO %d: %s\n", gpio_pins[i], strerror(errno));
                gpioTerminate();
                return 1;
            }
        }

        // Check for state changes and log them
        for (i = 0; i < num_pins; i++) {
            if (current_state[i] != previous_state[i]) {
                get_iso8601_timestamp(timestamp);
                printf("%s Sensor %d (GPIO %d) %s\n", timestamp, i, gpio_pins[i], current_state[i] ? "TOUCHED" : "RELEASED");
                previous_state[i] = current_state[i];
            }
        }

        // Delay for 50 milliseconds
        gpioDelay(50000);
    }

    // Terminate the pigpio library before exiting
    gpioTerminate();
    return 0;
}

