// Constants
#define I2C_BUS 1
#define VEML7700_ADDR 0x48
#define GAIN 2  // 1x gain
#define INTEGRATION_TIME 2  // 100ms
#define PWM_FREQUENCY 1000
#define PWM_GPIO 18
#define LOG_FILE "grow_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c();
int configure_veml7700();
int read_lux(float *lux);
int map_lux_to_duty_cycle(float lux, int *duty_cycle);
int set_pwm_duty_cycle(int duty_cycle);
int log_data(float lux, int duty_cycle, int error_code);
void signal_handler(int signal);

// Function to initialize I2C
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, VEML7700_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to configure VEML7700
int configure_veml7700() {
    // Set gain and integration time
    int gain_reg = GAIN; // 0x00 for 1x gain
    int it_reg = INTEGRATION_TIME; // 0x00 for 100ms

    // Combine gain and integration time into a single register value
    int config_value = (it_reg << 4) | gain_reg;

    int result = i2cWriteByteData(i2c_handle, 0x00, config_value); // Configuration register address is 0x00
    if (result < 0) {
        fprintf(stderr, "Error configuring VEML7700: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to read lux value from VEML7700
int read_lux(float *lux) {
    int raw_data = i2cReadWordData(i2c_handle, 0x04); // Read data from register 0x04
    if (raw_data < 0) {
        fprintf(stderr, "Error reading lux data: %d\n", raw_data);
        return -1;
    }

    // Convert raw data to lux (example formula, adjust as needed)
    *lux = (float)raw_data * 0.0576; // Example conversion factor

    return 0;
}

// Function to map lux to duty cycle
int map_lux_to_duty_cycle(float lux, int *duty_cycle) {
    if (lux < 100) {
        *duty_cycle = 100;
    } else if (lux < 500) {
        *duty_cycle = 75;
    } else if (lux < 1000) {
        *duty_cycle = 50;
    } else {
        *duty_cycle = 25;
    }
    return 0;
}

