    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set PWM frequency
    gpioSetPWMfrequency(PWM_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(PWM_GPIO, 100); // Set PWM range to 0-100

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        gpioTerminate();
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Configure VEML7700
    if (configure_veml7700() != 0) {
        i2cClose(i2c_handle);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float lux;
    int duty_cycle;
    int error_code;

    // Main loop
    while (!terminate) {
        error_code = 0;
        if (read_lux(&lux) != 0) {
            error_code = 1;
            lux = -1.0; // Indicate error in log
        }

        if (map_lux_to_duty_cycle(lux, &duty_cycle) != 0) {
            error_code = 2;
        }

        if (set_pwm_duty_cycle(duty_cycle) != 0) {
            error_code = 3;
        }

        log_data(lux, duty_cycle, error_code);

        gpioDelay(1000); // Sample every 1 second
    }

    // Cleanup
    set_pwm_duty_cycle(0); // Turn off LED
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

