#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Define GPIO pins
#define TOUCH_SENSOR_1 2
#define TOUCH_SENSOR_2 3
#define TOUCH_SENSOR_3 4
#define TOUCH_SENSOR_4 5
#define TOUCH_SENSOR_5 6
#define TOUCH_SENSOR_6 7
#define TOUCH_SENSOR_7 8
#define TOUCH_SENSOR_8 9
#define ALERT_LED 17

// Debounce delay in milliseconds
#define DEBOUNCE_DELAY 50

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Structure to hold the last touch state for each channel
typedef struct {
    int last_state[8];
} TouchState;

TouchState touch_state = {{0}};

// Function prototypes
int initialize_gpio();
int read_touch_sensors(int *sensor_states);
int debounce(int channel, int current_state);
int log_touch_event(int channel);
int control_alert_led(int any_touched);
void signal_handler(int signal);
int cleanup();

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    // Set touch sensor pins as inputs with pull-down resistors
    gpioSetMode(TOUCH_SENSOR_1, PI_INPUT);
    gpioSetPullUpDown(TOUCH_SENSOR_1, PI_PUD_DOWN);
    gpioSetMode(TOUCH_SENSOR_2, PI_INPUT);
    gpioSetPullUpDown(TOUCH_SENSOR_2, PI_PUD_DOWN);
    gpioSetMode(TOUCH_SENSOR_3, PI_INPUT);
    gpioSetPullUpDown(TOUCH_SENSOR_3, PI_PUD_DOWN);
    gpioSetMode(TOUCH_SENSOR_4, PI_INPUT);
    gpioSetPullUpDown(TOUCH_SENSOR_4, PI_PUD_DOWN);
    gpioSetMode(TOUCH_SENSOR_5, PI_INPUT);
    gpioSetPullUpDown(TOUCH_SENSOR_5, PI_PUD_DOWN);
    gpioSetMode(TOUCH_SENSOR_6, PI_INPUT);
    gpioSetPullUpDown(TOUCH_SENSOR_6, PI_PUD_DOWN);
    gpioSetMode(TOUCH_SENSOR_7, PI_INPUT);
    gpioSetPullUpDown(TOUCH_SENSOR_7, PI_PUD_DOWN);
    gpioSetMode(TOUCH_SENSOR_8, PI_INPUT);
    gpioSetPullUpDown(TOUCH_SENSOR_8, PI_PUD_DOWN);

    // Set alert LED pin as output
    gpioSetMode(ALERT_LED, PI_OUTPUT);

    return 0;
}

// Function to read the state of the touch sensors
int read_touch_sensors(int *sensor_states) {
    sensor_states[0] = gpioRead(TOUCH_SENSOR_1);
    sensor_states[1] = gpioRead(TOUCH_SENSOR_2);
    sensor_states[2] = gpioRead(TOUCH_SENSOR_3);
    sensor_states[3] = gpioRead(TOUCH_SENSOR_4);
    sensor_states[4] = gpioRead(TOUCH_SENSOR_5);
    sensor_states[5] = gpioRead(TOUCH_SENSOR_6);
    sensor_states[6] = gpioRead(TOUCH_SENSOR_7);
    sensor_states[7] = gpioRead(TOUCH_SENSOR_8);
    return 0;
}

// Function to debounce the touch sensor readings
int debounce(int channel, int current_state) {
    static unsigned long last_debounce_time[8] = {0};
    unsigned long current_time = gpioTick();

    if (current_state != touch_state.last_state[channel - 1]) {
        if (current_time - last_debounce_time[channel - 1] > DEBOUNCE_DELAY * 1000) {
            touch_state.last_state[channel - 1] = current_state;
            return 1; // Valid touch
        }
    }
    return 0; // Invalid touch
}

// Function to log touch events to a file
int log_touch_event(int channel) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s - Channel %d Touched\n", timestamp, channel);
        fflush(log_file); // Ensure data is written to disk immediately
        return 0;
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }
}

// Function to control the alert LED
int control_alert_led(int any_touched) {
    static int led_state = 0; // 0 = off, 1 = on

    if (any_touched && !led_state) {
        gpioWrite(ALERT_LED, 1); // Turn LED on
        led_state = 1;
    } else if (!any_touched && led_state) {
        gpioWrite(ALERT_LED, 0); // Turn LED off
        led_state = 0;
    }
    return 0;
}

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    running = 0;
}

// Cleanup function to release resources
int cleanup() {
    printf("Cleaning up resources...\n");

    // Turn off the LED
    gpioWrite(ALERT_LED, 0);

    // Close the log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    printf("Cleanup complete. Exiting.\n");
    return 0;
}

int main() {
    int sensor_states[8];
    int any_touched;
    int i;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Open the log file
    log_file = fopen("touch_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    printf("Touch sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        // Read touch sensor states
        read_touch_sensors(sensor_states);

        any_touched = 0;
        for (i = 0; i < 8; i++) {
            // Debounce and log touch events
            if (debounce(i + 1, sensor_states[i])) {
                if (log_touch_event(i + 1) != 0) {
                    fprintf(stderr, "Error logging touch event for channel %d\n", i + 1);
                }
                any_touched = 1;
            }
        }

        // Control the alert LED
        control_alert_led(any_touched);

        gpioDelay(50); // Poll every 50ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

