#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define OPT3001_ADDR 0x44
#define CONFIG_REG 0x01
#define RESULT_REG 0x00
#define LUX_SCALE 0.01
#define LOG_FILE "light_data.txt"

// Global variables
int i2c_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure for configuration
typedef struct {
    int i2c_bus;
    int opt3001_address;
    const char *log_file_name;
} config_t;

// Function prototypes
int init_i2c(int bus, int addr);
int write_config(int handle, uint16_t config);
int read_result(int handle, uint16_t *result);
float convert_to_lux(uint16_t raw_data);
char* format_timestamp(char* buffer, size_t buf_size);
int log_data(const char *timestamp, float lux_value);
void signal_handler(int signal);
void cleanup();

// Function to initialize I2C
int init_i2c(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        return -1;
    }
    return handle;
}

// Function to write configuration to OPT3001
int write_config(int handle, uint16_t config) {
    char buf[3];
    buf[0] = CONFIG_REG;
    buf[1] = (config >> 8) & 0xFF; // MSB
    buf[2] = config & 0xFF;        // LSB

    int result = i2cWriteDevice(handle, buf, 3);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read result from OPT3001
int read_result(int handle, uint16_t *result) {
    char buf[2];
    int bytes_read = i2cReadDevice(handle, buf, 2);
    if (bytes_read != 2) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        return -1;
    }

    *result = (buf[0] << 8) | buf[1]; // Byte swap
    return 0;
}

// Function to convert raw data to lux
float convert_to_lux(uint16_t raw_data) {
    uint16_t exponent = (raw_data >> 12) & 0x0F;
    uint16_t result = raw_data & 0x0FFF;
    return LUX_SCALE * result * (1 << exponent);
}

// Function to format timestamp
char* format_timestamp(char* buffer, size_t buf_size) {
    time_t timer;
    struct tm* tm_info;

    time(&timer);
    tm_info = localtime(&timer);

    strftime(buffer, buf_size, "%Y-%m-%d %H:%M:%S", tm_info);
    return buffer;
}

