    if (result < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }
    fflush(log_file); // Ensure data is written immediately
    return 0;
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Caught SIGINT, exiting gracefully.\n");
        terminate = 1;
    }
}

// Cleanup function
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Configuration
    config_t config = {
        .i2c_bus = I2C_BUS,
        .opt3001_address = OPT3001_ADDR,
        .log_file_name = LOG_FILE
    };

    // Initialize I2C
    i2c_handle = init_i2c(config.i2c_bus, config.opt3001_address);
    if (i2c_handle < 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(config.log_file_name, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        uint16_t raw_data;
        float lux_value;
        char timestamp[20];

        // Write configuration
        if (write_config(i2c_handle, 0xC810) != 0) { // Continuous mode, 100ms conversion time
            fprintf(stderr, "Error writing configuration, retrying.\n");
            gpioDelay(1000); // Wait 1 second before retrying
            continue;
        }

        gpioDelay(100); // Wait 100ms for conversion

        // Read result
        if (read_result(i2c_handle, &raw_data) != 0) {
            fprintf(stderr, "Error reading result, retrying.\n");
            gpioDelay(1000); // Wait 1 second before retrying
            continue;
        }

        // Convert to lux
        lux_value = convert_to_lux(raw_data);

        // Format timestamp
        format_timestamp(timestamp, sizeof(timestamp));

        // Log data
        if (log_data(timestamp, lux_value) != 0) {
            fprintf(stderr, "Error logging data, retrying.\n");
        }

        // Print to stdout
        printf("%s, %.2f\n", timestamp, lux_value);

        gpioDelay(1000); // Wait 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

