#include <signal.h>
#include <string.h>

#define TOUCH_PIN 4
#define DEBOUNCE_MS 50

static volatile int running = 1;
static FILE *log_file = NULL;

// Function to get current timestamp
char* get_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    static char timestamp[20]; //YYYY-MM-DD HH:MM:SS\0

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    return timestamp;
}

// Function to log touch event
int log_touch_event(const char *event_type) {
    char *timestamp = get_timestamp();
    if (log_file != NULL) {
        fprintf(log_file, "%s: %s\n", timestamp, event_type);
        fflush(log_file);
        return 0; // Success
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1; // Failure
    }
}

// Function to read touch sensor with debouncing
int read_touch_sensor() {
    int current_state = gpioRead(TOUCH_PIN);
    gpioDelay(DEBOUNCE_MS * 1000); // Debounce
    return gpioRead(TOUCH_PIN);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    running = 0;
}

int main() {
    int last_state = 1; // Initialize to released state (assuming pull-down)

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO4 as input with pull-down resistor
    gpioSetMode(TOUCH_PIN, PI_INPUT);
    gpioSetPullUpDown(TOUCH_PIN, PI_PUD_DOWN);

    // Open log file
    log_file = fopen("touch_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Touch sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int current_state = read_touch_sensor();

        if (current_state != last_state) {
            if (current_state == 0) {
                if (log_touch_event("Touch Detected") != 0) {
                    fprintf(stderr, "Error logging touch detected event.\n");
                }
            } else {
                if (log_touch_event("Touch Released") != 0) {
                    fprintf(stderr, "Error logging touch released event.\n");
                }
            }
            last_state = current_state;
        }
    }

    // Cleanup
    printf("Cleaning up...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

