#define FLOW_MAX 100.0
#define LOG_FILE "cooling_log.csv"

// Global variables
int i2c_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int16_t flow_rate;
    uint8_t flags;
    uint8_t crc;
} sensor_data_t;

// Function prototypes
int init_i2c();
int read_sensor_data(sensor_data_t *data);
uint8_t calculate_crc(const uint8_t *data, int len);
int validate_crc(const sensor_data_t *data);
float convert_flow_rate(int16_t raw_flow);
const char *get_status(float flow_rate, int crc_valid);
int log_data(float flow_rate, int crc_valid, const char *status);
void signal_handler(int signal);
void cleanup();

// Function to initialize the I2C bus
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SLF3S_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read sensor data
int read_sensor_data(sensor_data_t *data) {
    char buf[3];
    int bytes_read = i2cReadDevice(i2c_handle, buf, 3);

    if (bytes_read != 3) {
        fprintf(stderr, "Error reading sensor data: %d\n", bytes_read);
        return -1;
    }

    data->flow_rate = (int16_t)((buf[0] << 8) | buf[1]);
    data->flags = buf[2];
    data->crc = 0; // Placeholder, will be calculated later

    return 0;
}

// Function to calculate CRC8
uint8_t calculate_crc(const uint8_t *data, int len) {
    uint8_t crc = CRC_INITIAL_VALUE;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to validate CRC
int validate_crc(const sensor_data_t *data) {
    uint8_t crc_calculated = calculate_crc((uint8_t *)data, 2);
    return (crc_calculated == data->crc);
}

// Function to convert raw flow rate to ml/min
float convert_flow_rate(int16_t raw_flow) {
    // Scaling factor from the datasheet (example value, check the datasheet)
    float scaling_factor = 0.05; // Example: 0.05 ml/min per unit
    return (float)raw_flow * scaling_factor;
}

