const char *get_status(float flow_rate, int crc_valid) {
    if (!crc_valid) {
        return "ERROR";
    } else if (flow_rate < FLOW_MIN || flow_rate > FLOW_MAX) {
        return "INVALID";
    } else {
        return "OK";
    }
}

