            if (init_i2c() != 0) {
                fprintf(stderr, "Failed to re-initialize I2C, exiting\n");
                break;
            }
            gpioDelay(1000); // Wait before retrying
            continue;
        }

        gpioDelay(2); // Wait for at least 2 ms

        // Read sensor data
        if (read_sensor_data(&sensor_data) == 0) {
            // Validate CRC
            crc_valid = validate_crc(&sensor_data);

            // Convert flow rate
            flow_rate = convert_flow_rate(sensor_data.flow_rate);

            // Get status
            status = get_status(flow_rate, crc_valid);
        }

        // Log data
        if (log_data(flow_rate, crc_valid, status) != 0) {
            fprintf(stderr, "Error logging data\n");
        }

        gpioDelay(1000); // Sample every 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
