#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <stdbool.h>
#include <pigpio.h>

// Define GPIO pins for the sensors
#define LEFT_SENSOR_PIN 17
#define MIDDLE_SENSOR_PIN 27
#define RIGHT_SENSOR_PIN 22

// Define the log file name
#define LOG_FILE "path_log.csv"

// Global variables
FILE *log_file = NULL;
bool running = true;

// Function prototypes
int read_sensor(int gpio_pin);
char *get_iso8601_timestamp();
int log_data(FILE *fp, char *timestamp, int left, int middle, int right);
void signal_handler(int signal);

// Function to read the sensor value from a given GPIO pin
int read_sensor(int gpio_pin) {
    int value = gpioRead(gpio_pin);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d: %d\n", gpio_pin, value);
        return -1; // Indicate an error
    }
    return value;
}

// Function to get the current timestamp in ISO 8601 format
char *get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char *)malloc(25 * sizeof(char)); // Allocate memory for the timestamp string

    if (timestamp == NULL) {
        perror("Failed to allocate memory for timestamp");
        return NULL;
    }

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    return timestamp;
}

// Function to log the data to the CSV file
int log_data(FILE *fp, char *timestamp, int left, int middle, int right) {
    if (fprintf(fp, "%s,%d,%d,%d\n", timestamp, left, middle, right) < 0) {
        perror("Error writing to log file");
        return -1;
    }
    return 0;
}

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Caught SIGINT, exiting gracefully...\n");
        running = false;
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs
    gpioSetMode(LEFT_SENSOR_PIN, PI_INPUT);
    gpioSetMode(MIDDLE_SENSOR_PIN, PI_INPUT);
    gpioSetMode(RIGHT_SENSOR_PIN, PI_INPUT);

    // Open the log file in append mode
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        gpioTerminate();
        return 1;
    }

    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Main loop
    while (running) {
        // Read sensor values
        int left_value = read_sensor(LEFT_SENSOR_PIN);
        int middle_value = read_sensor(MIDDLE_SENSOR_PIN);
        int right_value = read_sensor(RIGHT_SENSOR_PIN);

        // Get the current timestamp
        char *timestamp = get_iso8601_timestamp();
        if (timestamp == NULL) {
            fprintf(stderr, "Failed to get timestamp, skipping log entry\n");
            continue; // Skip to the next iteration if timestamp fails
        }

        // Log the data to the file
        if (log_data(log_file, timestamp, left_value, middle_value, right_value) != 0) {
            fprintf(stderr, "Failed to log data, skipping\n");
        }

        // Free the timestamp memory
        free(timestamp);

        // Flush the log file to ensure data is written
        fflush(log_file);

        // Wait for 50ms
        gpioDelay(50000); // pigpio's delay function takes microseconds
    }

    // Cleanup
    printf("Cleaning up...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

