#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

#define FLAME_SENSOR_GPIO 4
#define LOG_FILE "flame_events.txt"

// Global variables for signal handling
volatile sig_atomic_t program_running = 1;
FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int read_flame_sensor();
void log_event(const char *event_message);
void signal_handler(int signal);
void cleanup();

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio and GPIO pin
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Failed to initialize GPIO. Exiting.\n");
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file. Exiting.\n");
        cleanup();
        return 1;
    }

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        int flame_detected = read_flame_sensor();

        if (flame_detected == 0) {
            // Flame detected (active low)
            time_t now = time(NULL);
            struct tm *tstruct = localtime(&now);
            char timestamp[80];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tstruct);

            char event_message[256];
            snprintf(event_message, sizeof(event_message), "Flame detected at %s", timestamp);

            printf("%s\n", event_message);
            log_event(event_message);
        }

        gpioDelay(100); // Check every 100ms
    }

    // Cleanup and exit
    cleanup();
    printf("Flame sensor monitoring stopped.\n");
    return 0;
}

// Initializes the pigpio library and sets the GPIO pin mode.
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT);
    gpioSetPullUpDown(FLAME_SENSOR_GPIO, PI_PUD_UP); // Enable pull-up resistor

    return 0;
}

// Reads the flame sensor's digital output.
int read_flame_sensor() {
    return gpioRead(FLAME_SENSOR_GPIO);
}

// Logs an event to the log file with a timestamp.
void log_event(const char *event_message) {
    if (log_file != NULL) {
        fprintf(log_file, "%s\n", event_message);
        fflush(log_file); // Ensure the log is written immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Signal handler for SIGINT and SIGTERM.
void signal_handler(int signal) {
    program_running = 0;
    printf("Signal received (%d). Shutting down...\n", signal);
}

// Cleans up resources before exiting.
void cleanup() {
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

