#include <errno.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>

// Define GPIO pins
#define FLAME_SENSOR_PIN 17
#define BUZZER_PIN 18

// Define constants
#define BUZZER_DURATION 2 // seconds
#define POLL_INTERVAL 500  // milliseconds
#define DEBOUNCE_DELAY 100 // milliseconds

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int read_flame_sensor();
void activate_buzzer();
void log_event(const char *message);
void cleanup();
void signal_handler(int signal);

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return -1;
    }

    gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);
    gpioWrite(BUZZER_PIN, 0); // Ensure buzzer is off initially

    return 0;
}

// Function to read the flame sensor
int read_flame_sensor() {
    return gpioRead(FLAME_SENSOR_PIN);
}

// Function to activate the buzzer
void activate_buzzer() {
    gpioWrite(BUZZER_PIN, 1);
    gpioDelay(BUZZER_DURATION * 1000000); // Convert seconds to microseconds
    gpioWrite(BUZZER_PIN, 0);
}

// Function to log an event to the log file
void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file != NULL) {
        fprintf(log_file, "%s: %s\n", timestamp, message);
        fflush(log_file); // Ensure the log is written immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal) {
    running = 0;
    printf("Received signal %d, shutting down...\n", signal);
}

// Function to clean up resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    gpioWrite(BUZZER_PIN, 0); // Ensure buzzer is off
    gpioTerminate();          // Release GPIO resources
    if (log_file != NULL) {
        fclose(log_file);
    }
    printf("Cleanup complete. Exiting.\n");
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open the log file
    log_file = fopen("alert_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    log_event("System started");

    int last_state = 1; // Assume no flame initially (HIGH)
    int current_state;

    while (running) {
        current_state = read_flame_sensor();

        if (current_state == 0 && last_state == 1) {
            // Flame detected (LOW to HIGH transition)
            log_event("FLAME DETECTED");
            activate_buzzer();
            gpioDelay(DEBOUNCE_DELAY * 1000); // Debounce delay
        }

        last_state = current_state;
        gpioDelay(POLL_INTERVAL * 1000); // Poll interval
    }

    log_event("System stopped");
    cleanup();

    return 0;
}

