// Function prototypes
int initialize_gpio();
int read_sensor(int gpio);
int log_transition(sensor_data_t *sensor, int new_state);
void signal_handler(int signal);
void cleanup();

// Function to initialize the GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(SENSOR1_GPIO, PI_INPUT);
    gpioSetPullUpDown(SENSOR1_GPIO, PI_PUD_UP);
    gpioSetMode(SENSOR2_GPIO, PI_INPUT);
    gpioSetPullUpDown(SENSOR2_GPIO, PI_PUD_UP);
    gpioSetMode(SENSOR3_GPIO, PI_INPUT);
    gpioSetPullUpDown(SENSOR3_GPIO, PI_PUD_UP);

    return 0;
}

// Function to read the state of a sensor
int read_sensor(int gpio) {
    return gpioRead(gpio);
}

// Function to log a state transition
int log_transition(sensor_data_t *sensor, int new_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

    if (sensor->log_file != NULL) {
        fprintf(sensor->log_file, "%s Sensor%d: %s\n", timestamp, sensor->gpio, new_state == 0 ? "Magnet Present" : "Magnet Removed");
        fflush(sensor->log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
        return 1;
    }
    return 0;
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    cleanup();
    exit(0);
}

