    sensor1.gpio = SENSOR1_GPIO;
    sensor1.log_file = log_file;
    sensor1.initial_state = read_sensor(SENSOR1_GPIO);
    sensor1.current_state = sensor1.initial_state;

    sensor2.gpio = SENSOR2_GPIO;
    sensor2.log_file = log_file;
    sensor2.initial_state = read_sensor(SENSOR2_GPIO);
    sensor2.current_state = sensor2.initial_state;

    sensor3.gpio = SENSOR3_GPIO;
    sensor3.log_file = log_file;
    sensor3.initial_state = read_sensor(SENSOR3_GPIO);
    sensor3.current_state = sensor3.initial_state;

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        // Read sensor 1
        int new_state = read_sensor(SENSOR1_GPIO);
        if (new_state != sensor1.current_state) {
            if (log_transition(&sensor1, new_state) != 0) {
                fprintf(stderr, "Error logging transition for sensor 1\n");
            }
            sensor1.current_state = new_state;
        }

        // Read sensor 2
        new_state = read_sensor(SENSOR2_GPIO);
        if (new_state != sensor2.current_state) {
            if (log_transition(&sensor2, new_state) != 0) {
                fprintf(stderr, "Error logging transition for sensor 2\n");
            }
            sensor2.current_state = new_state;
        }

        // Read sensor 3
        new_state = read_sensor(SENSOR3_GPIO);
        if (new_state != sensor3.current_state) {
            if (log_transition(&sensor3, new_state) != 0) {
                fprintf(stderr, "Error logging transition for sensor 3\n");
            }
            sensor3.current_state = new_state;
        }

        // Delay for 100ms
        gpioDelay(100000); // 100ms = 100000 microseconds
    }

    return 0;
}

