    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to get the current timestamp
char* get_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    static char buffer[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", timeinfo);
    return buffer;
}

// Function to initialize the Si1182 sensor
int initialize_sensor(int i2c_handle, sensor_config_t *config) {
    uint8_t part_id, hw_rev;

    // Read PART_ID register
    int result = i2cReadByteData(i2c_handle, PART_ID_REG);
    if (result < 0) {
        fprintf(stderr, "Error reading PART_ID register: %d\n", result);
        return -1;
    }
    part_id = (uint8_t)result;

    // Read HW_REV register
    result = i2cReadByteData(i2c_handle, HW_REV_REG);
    if (result < 0) {
        fprintf(stderr, "Error reading HW_REV register: %d\n", result);
        return -1;
    }
    hw_rev = (uint8_t)result;

    // Validate sensor configuration
    if (part_id != 0x82) {
        fprintf(stderr, "Error: Invalid PART_ID (0x%02X, expected 0x82)\n", part_id);
        return -1;
    }
    if (hw_rev != 0x00) {
        fprintf(stderr, "Error: Invalid HW_REV (0x%02X, expected 0x00)\n", hw_rev);
        return -1;
    }

    config->part_id = part_id;
    config->hw_rev = hw_rev;

    printf("Sensor initialized successfully. PART_ID: 0x%02X, HW_REV: 0x%02X\n", part_id, hw_rev);
    return 0;
}

// Function to read the heart rate from the sensor
int read_heart_rate(int i2c_handle) {
    int result = i2cReadByteData(i2c_handle, HEART_RATE_REG);
    if (result < 0) {
        fprintf(stderr, "Error reading heart rate register: %d\n", result);
        return -1;
    }
    return result;
}

// Function to apply a moving average filter
float apply_moving_average(float new_value, float *buffer, int buffer_size, int *index) {
    buffer[*index] = new_value;
    *index = (*index + 1) % buffer_size;

    float sum = 0.0;
    for (int i = 0; i < buffer_size; i++) {
        sum += buffer[i];
    }
    return sum / buffer_size;
}

// Function to validate the BPM value
int validate_bpm(float bpm) {
    return (bpm >= BPM_MIN && bpm <= BPM_MAX);
}

// Function to log the data to a file
int log_data(const char *timestamp, float bpm) {
    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s,%.2f\n", timestamp, bpm);
    fflush(log_file); // Ensure data is written immediately
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SI1182_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("heart_rate.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize sensor configuration
    sensor_config_t sensor_config;

    // Initialize the sensor
    if (initialize_sensor(i2c_handle, &sensor_config) != 0) {
        fprintf(stderr, "Sensor initialization failed.\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);

    // Moving average buffer
    float heart_rate_buffer[MOVING_AVG_SIZE] = {0.0};
    int buffer_index = 0;

    // Main loop
    while (program_running) {
        // Read heart rate
        int raw_heart_rate = read_heart_rate(i2c_handle);
        if (raw_heart_rate < 0) {
            fprintf(stderr, "Error reading heart rate, retrying...\n");
            gpioDelay(1000); // Wait 1 second before retrying
            continue;
        }

        // Apply moving average filter
        float filtered_heart_rate = apply_moving_average((float)raw_heart_rate, heart_rate_buffer, MOVING_AVG_SIZE, &buffer_index);

        // Convert to BPM (assuming raw value is in Hz)
        float bpm = filtered_heart_rate * 60.0;

        // Validate BPM
        if (validate_bpm(bpm)) {
            // Get timestamp
            char* timestamp = get_timestamp();

            // Log data
            if (log_data(timestamp, bpm) != 0) {
                fprintf(stderr, "Error logging data.\n");
            }
            printf("Timestamp: %s, BPM: %.2f\n", timestamp, bpm);
        } else {
            fprintf(stderr, "Invalid BPM value: %.2f\n", bpm);
        }

        // Wait for 1 second
        gpioDelay(1000);
    }

    // Close I2C bus and log file
    i2cClose(i2c_handle);
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

