#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

// Define GPIO chip and lines
#define GPIOCHIP "gpiochip0"

// Input lines (BCM numbering)
const int input_lines[] = {5, 6, 7, 8, 9, 10, 11, 12};
const int num_channels = sizeof(input_lines) / sizeof(input_lines[0]);

// Output lines (BCM numbering)
const int output_lines[] = {17, 18, 19, 20, 21, 22, 23, 24};
const int num_outputs = sizeof(output_lines) / sizeof(output_lines[0]);

// Global variables
struct gpiod_chip *chip = NULL;
struct gpiod_line *input_gpios[8] = {NULL};
struct gpiod_line *output_gpios[8] = {NULL};
int counter = 0;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_sensor(int channel);
int update_counter(int increment);
int set_output(int channel, int value);
int log_event(int channel, int counter);
void signal_handler(int signal);
int setup_gpio();
void cleanup_gpio();

// Function to read sensor value
int read_sensor(int channel) {
    int value = gpiod_line_get_value(input_gpios[channel]);
    if (value < 0) {
        fprintf(stderr, "Error reading sensor %d: %s\n", channel, strerror(errno));
        return -1; // Indicate error
    }
    return value;
}

// Function to update the counter
int update_counter(int increment) {
    counter += increment;
    if (counter > 255) {
        counter = 0;
    } else if (counter < 0) {
        counter = 255;
    }
    return 0;
}

// Function to set output value
int set_output(int channel, int value) {
    int ret = gpiod_line_set_value(output_gpios[channel], value);
    if (ret < 0) {
        fprintf(stderr, "Error setting output %d: %s\n", channel, strerror(errno));
        return -1; // Indicate error
    }
    return 0;
}

// Function to log event
int log_event(int channel, int counter) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    FILE *fp = fopen("touch_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1; // Indicate error
    }

    fprintf(fp, "%s, Channel: %d, Counter: %d\n", timestamp, channel, counter);
    fclose(fp);
    return 0;
}

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Setup GPIO lines
int setup_gpio() {
    int i, ret;

    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    // Request input lines
    for (i = 0; i < num_channels; i++) {
        input_gpios[i] = gpiod_chip_get_line(chip, input_lines[i]);
        if (!input_gpios[i]) {
            fprintf(stderr, "Error getting input line %d: %s\n", input_lines[i], strerror(errno));
            goto cleanup;
        }

        ret = gpiod_line_request(input_gpios[i], NULL, GPIOD_LINE_REQUEST_DIRECTION_INPUT);
        if (ret < 0) {
            fprintf(stderr, "Error requesting input line %d: %s\n", input_lines[i], strerror(errno));
            goto cleanup;
        }
    }

    // Request output lines
    for (i = 0; i < num_outputs; i++) {
        output_gpios[i] = gpiod_chip_get_line(chip, output_lines[i]);
        if (!output_gpios[i]) {
            fprintf(stderr, "Error getting output line %d: %s\n", output_lines[i], strerror(errno));
            goto cleanup;
        }

        ret = gpiod_line_request(output_gpios[i], NULL, GPIOD_LINE_REQUEST_DIRECTION_OUTPUT);
        if (ret < 0) {
            fprintf(stderr, "Error requesting output line %d: %s\n", output_lines[i], strerror(errno));
            goto cleanup;
        }
    }

    return 0;

cleanup:
    cleanup_gpio();
    return -1;
}

// Cleanup GPIO lines
void cleanup_gpio() {
    int i;

    for (i = 0; i < num_channels; i++) {
        if (input_gpios[i]) {
            gpiod_line_release(input_gpios[i]);
            input_gpios[i] = NULL;
        }
    }

    for (i = 0; i < num_outputs; i++) {
        if (output_gpios[i]) {
            gpiod_line_release(output_gpios[i]);
            output_gpios[i] = NULL;
        }
    }

    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

int main() {
    int i, sensor_value, output_value;

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (setup_gpio() != 0) {
        fprintf(stderr, "GPIO setup failed, exiting.\n");
        return 1;
    }

    // Stabilization delay
    struct timespec delay = {0, 200000000}; // 200 ms
    nanosleep(&delay, NULL);

    printf("Touch counter started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        for (i = 0; i < num_channels; i++) {
            sensor_value = read_sensor(i);
            if (sensor_value < 0) continue; // Skip if read error

            if (sensor_value == 1) {
                update_counter(1);
                output_value = counter & (1 << i);
                if (set_output(i, output_value) != 0) {
                    fprintf(stderr, "Error setting output for channel %d\n", i);
                }
                log_event(i + 1, counter);
                printf("Touch on channel %d | Counter: %d\n", i + 1, counter);
            }
        }

        // Delay
        struct timespec delay = {0, 10000000}; // 10 ms
        nanosleep(&delay, NULL);
    }

    // Cleanup and exit
    cleanup_gpio();
    printf("Touch counter stopped.\n");
    return 0;
}

