#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins for the tilt sensors
#define SENSOR_1_GPIO 17
#define SENSOR_2_GPIO 18

// Debounce time in milliseconds
#define DEBOUNCE_TIME 50

// Log file path
#define LOG_FILE "/var/log/tilt_events.log"

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Structure to hold sensor state
typedef struct {
    int last_state;
    unsigned long last_change_time;
} sensor_state_t;

sensor_state_t sensor1_state = {1, 0}; // Initialize to inactive (1)
sensor_state_t sensor2_state = {1, 0}; // Initialize to inactive (1)

// Function prototypes
int initialize_gpio();
int read_sensor(int gpio);
int debounce(int gpio, int current_state);
int log_event(int sensor_number);
void signal_handler(int signal);
void cleanup();

// Function to initialize the pigpio library and configure GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    // Set GPIO pins as inputs with pull-up resistors
    gpioSetMode(SENSOR_1_GPIO, PI_INPUT);
    gpioSetPullUpDown(SENSOR_1_GPIO, PI_PUD_UP);
    gpioSetMode(SENSOR_2_GPIO, PI_INPUT);
    gpioSetPullUpDown(SENSOR_2_GPIO, PI_PUD_UP);

    return 0;
}

// Function to read the state of a sensor
int read_sensor(int gpio) {
    return gpioRead(gpio);
}

// Function to debounce the sensor readings
int debounce(int gpio, int current_state) {
    int new_state = read_sensor(gpio);
    unsigned long now = gpioTick();

    if (new_state != current_state) {
        if (now - sensor1_state.last_change_time > DEBOUNCE_TIME * 1000 || now - sensor2_state.last_change_time > DEBOUNCE_TIME * 1000) {
            return new_state;
        }
    }
    return current_state;
}

// Function to log a tilt event to the log file
int log_event(int sensor_number) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, Sensor %d tilted\n", timestamp, sensor_number);
        fflush(log_file); // Ensure the log is written immediately
        return 0;
    } else {
        fprintf(stderr, "Error: Log file is not open\n");
        return -1;
    }
}

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    running = 0;
    printf("Received signal %d, exiting gracefully...\n", signal);
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    printf("Cleanup complete.\n");
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        cleanup();
        return 1;
    }

    printf("Tilt sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        // Read and debounce sensor 1
        int new_sensor1_state = debounce(SENSOR_1_GPIO, sensor1_state.last_state);
        if (new_sensor1_state == 0 && sensor1_state.last_state == 1) {
            log_event(1);
        }
        sensor1_state.last_state = new_sensor1_state;
        sensor1_state.last_change_time = gpioTick();

        // Read and debounce sensor 2
        int new_sensor2_state = debounce(SENSOR_2_GPIO, sensor2_state.last_state);
        if (new_sensor2_state == 0 && sensor2_state.last_state == 1) {
            log_event(2);
        }
        sensor2_state.last_state = new_sensor2_state;
        sensor2_state.last_change_time = gpioTick();

        gpioDelay(100); // Poll every 100ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

