#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Si1175 I2C address
#define SI1175_ADDR 0x60

// Si1175 register addresses
#define REG_PART_ID 0x00
#define REG_ALS_VIS_DATA0 0x22
#define REG_ALS_VIS_DATA1 0x23

// I2C bus
#define I2C_BUS 1

// Global variable for I2C handle
int i2c_handle;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("\nCtrl+C pressed. Cleaning up and exiting...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    exit(0);
}

// Function to read a single byte from an I2C register
int read_register(int handle, int reg) {
    int value = i2cReadByteData(handle, reg);
    if (value < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, value);
        return -1;
    }
    return value;
}

// Function to write a single byte to an I2C register
int write_register(int handle, int reg, int value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Function to read the ALS data from the Si1175
int read_als_data(int handle) {
    int lsb = read_register(handle, REG_ALS_VIS_DATA0);
    int msb = read_register(handle, REG_ALS_VIS_DATA1);

    if (lsb < 0 || msb < 0) {
        return -1; // Indicate an error
    }

    return (msb << 8) | lsb; // Combine LSB and MSB into a 16-bit value
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SI1175_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        int als_data = read_als_data(i2c_handle);

        if (als_data >= 0) {
            printf("ALS Data: %d\n", als_data);
        } else {
            fprintf(stderr, "Error reading ALS data\n");
        }

        gpioDelay(100); // Wait 100ms
    }

    // The following lines will never be reached due to the infinite loop,
    // but are included for completeness.
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

