#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins for the touch sensor channels
#define CH1_PIN 5
#define CH2_PIN 6
#define CH3_PIN 13
#define CH4_PIN 19
#define CH5_PIN 26
#define CH6_PIN 12
#define CH7_PIN 16
#define CH8_PIN 20

// Structure to hold the state of the touch sensor channels
typedef struct {
    int ch1;
    int ch2;
    int ch3;
    int ch4;
    int ch5;
    int ch6;
    int ch7;
    int ch8;
} TouchState;

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to read the state of the touch sensor channels
TouchState read_touch_sensor() {
    TouchState state;
    state.ch1 = gpioRead(CH1_PIN);
    state.ch2 = gpioRead(CH2_PIN);
    state.ch3 = gpioRead(CH3_PIN);
    state.ch4 = gpioRead(CH4_PIN);
    state.ch5 = gpioRead(CH5_PIN);
    state.ch6 = gpioRead(CH6_PIN);
    state.ch7 = gpioRead(CH7_PIN);
    state.ch8 = gpioRead(CH8_PIN);
    return state;
}

// Function to format the timestamp and touch sensor state into a string
char* format_output(TouchState state) {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    double seconds = (double)ts.tv_sec + (double)ts.tv_nsec / 1000000000.0;

    char *output = malloc(256 * sizeof(char)); // Allocate memory for the output string
    if (output == NULL) {
        perror("malloc failed");
        exit(EXIT_FAILURE);
    }

    snprintf(output, 256, "[%.3fs] CH1=%d CH2=%d CH3=%d CH4=%d CH5=%d CH6=%d CH7=%d CH8=%d",
             seconds, state.ch1, state.ch2, state.ch3, state.ch4, state.ch5, state.ch6, state.ch7, state.ch8);
    return output;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs
    gpioSetMode(CH1_PIN, PI_INPUT);
    gpioSetMode(CH2_PIN, PI_INPUT);
    gpioSetMode(CH3_PIN, PI_INPUT);
    gpioSetMode(CH4_PIN, PI_INPUT);
    gpioSetMode(CH5_PIN, PI_INPUT);
    gpioSetMode(CH6_PIN, PI_INPUT);
    gpioSetMode(CH7_PIN, PI_INPUT);
    gpioSetMode(CH8_PIN, PI_INPUT);

    // Install signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (program_running) {
        // Read the touch sensor state
        TouchState state = read_touch_sensor();

        // Format the output string
        char *output = format_output(state);

        // Print the output string to the console
        printf("%s\n", output);

        // Free the allocated memory
        free(output);

        // Wait for 200ms
        gpioDelay(200000); // 200ms = 200000 microseconds
    }

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

