#include <stdint.h>
#include <signal.h>
#include <syslog.h>
#include <time.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for RGB LED
#define RED_PIN   17
#define GREEN_PIN 18
#define BLUE_PIN  27

// Define PWM frequency and range
#define PWM_FREQUENCY 1000
#define PWM_RANGE 255

// Define fade step count and duration
#define FADE_STEPS 50
#define FADE_DURATION 5 // seconds

// Global variables
volatile sig_atomic_t program_running = 1;

// Function prototypes
void signal_handler(int signal);
int initialize_gpio();
void set_led_color(int red, int green, int blue);
void fade_to_color(int red, int green, int blue);
void generate_random_color(int *red, int *green, int *blue);
void cleanup_gpio();

// Signal handler function
void signal_handler(int signal) {
    syslog(LOG_INFO, "Signal received, shutting down...");
    program_running = 0;
}

// Initialize GPIO using pigpio
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }

    // Set GPIO pins to output mode
    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);

    // Set PWM frequency and range
    gpioSetPWMfrequency(RED_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(GREEN_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(BLUE_PIN, PWM_FREQUENCY);
    gpioSetPWMrange(RED_PIN, PWM_RANGE);
    gpioSetPWMrange(GREEN_PIN, PWM_RANGE);
    gpioSetPWMrange(BLUE_PIN, PWM_RANGE);

    return 0;
}

// Set the color of the RGB LED using PWM
void set_led_color(int red, int green, int blue) {
    gpioPWM(RED_PIN, red);
    gpioPWM(GREEN_PIN, green);
    gpioPWM(BLUE_PIN, blue);
}

// Fade to a target color over a specified duration
void fade_to_color(int red, int green, int blue) {
    int current_red   = gpioGetPWMdutycycle(RED_PIN);
    int current_green = gpioGetPWMdutycycle(GREEN_PIN);
    int current_blue  = gpioGetPWMdutycycle(BLUE_PIN);

    float red_increment   = (float)(red - current_red)   / FADE_STEPS;
    float green_increment = (float)(green - current_green) / FADE_STEPS;
    float blue_increment  = (float)(blue - current_blue)  / FADE_STEPS;

    for (int i = 0; i < FADE_STEPS; i++) {
        current_red   += red_increment;
        current_green += green_increment;
        current_blue  += blue_increment;

        // Clamp values to the range 0-255
        if (current_red   < 0) current_red   = 0;
        if (current_green < 0) current_green = 0;
        if (current_blue  < 0) current_blue  = 0;
        if (current_red   > 255) current_red   = 255;
        if (current_green > 255) current_green = 255;
        if (current_blue  > 255) current_blue  = 255;

        set_led_color((int)current_red, (int)current_green, (int)current_blue);
        gpioDelay(FADE_DURATION * 1000000 / FADE_STEPS); // microseconds
    }
}

// Generate random RGB color values
void generate_random_color(int *red, int *green, int *blue) {
    *red   = rand() % 256;
    *green = rand() % 256;
    *blue  = rand() % 256;
}

// Cleanup GPIO resources
void cleanup_gpio() {
    set_led_color(0, 0, 0); // Turn off LED
    gpioTerminate();
    syslog(LOG_INFO, "pigpio terminated");
}

int main() {
    // Open syslog
    openlog("rgb_led_fader", LOG_PID | LOG_CONS, LOG_USER);

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Seed the random number generator
    FILE *urandom = fopen("/dev/urandom", "r");
    if (urandom) {
        unsigned char seed[4];
        fread(seed, 1, 4, urandom);
        fclose(urandom);
        unsigned int seed_value = (seed[0] << 24) | (seed[1] << 16) | (seed[2] << 8) | seed[3];
        srand(seed_value);
    } else {
        syslog(LOG_WARNING, "Failed to open /dev/urandom, using default seed");
        srand(time(NULL));
    }

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        syslog(LOG_ERR, "GPIO initialization failed, exiting");
        closelog();
        return 1;
    }

    syslog(LOG_INFO, "RGB LED fader started");

    int red, green, blue;

    while (program_running) {
        generate_random_color(&red, &green, &blue);
        fade_to_color(red, green, blue);
        sleep(1); // Wait for 1 second before changing color
    }

    // Cleanup and exit
    cleanup_gpio();
    closelog();
    return 0;
}

