#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <string.h>

// TCS34725 Registers
#define TCS34725_ADDRESS         (0x29)
#define TCS34725_COMMAND_BIT     (0x80)
#define TCS34725_ENABLE          (0x00)
#define TCS34725_ATIME           (0x01)
#define TCS34725_CONTROL         (0x0F)
#define TCS34725_CDATA           (0x14)
#define TCS34725_RDATA           (0x16)
#define TCS34725_GDATA           (0x18)
#define TCS34725_BDATA           (0x1A)

// Enable Register Values
#define TCS34725_PON             (0x01)
#define TCS34725_AEN             (0x02)

// Gain Values
#define TCS34725_GAIN_1X         (0x00)
#define TCS34725_GAIN_4X         (0x01)
#define TCS34725_GAIN_16X        (0x02)
#define TCS34725_GAIN_60X        (0x03)

// Integration Time Values
#define TCS34725_INTEGRATIONTIME_2_4MS  (0xFF)   // 2.4ms - 1 cycle    - Max Count: 1024
#define TCS34725_INTEGRATIONTIME_24MS   (0xF6)   // 24ms  - 10 cycles   - Max Count: 10240
#define TCS34725_INTEGRATIONTIME_101MS  (0xDB)   // 101ms - 42 cycles   - Max Count: 42496
#define TCS34725_INTEGRATIONTIME_154MS  (0xC0)   // 154ms - 64 cycles   - Max Count: 65535

// GPIO Pin for LED
#define LED_GPIO_PIN              (17)

// Red Threshold
#define RED_THRESHOLD             (200)

// I2C Bus
#define I2C_BUS                   (1)

// Global Variables
static int i2c_fd = -1;
static volatile sig_atomic_t terminate = 0;

// Function Prototypes
int tcs34725_init(int i2c_fd);
int tcs34725_read_raw_data(int i2c_fd, uint16_t *r, uint16_t *g, uint16_t *b, uint16_t *c);
void calibrate_color_data(uint16_t r, uint16_t g, uint16_t b, uint16_t c, float *calibrated_r, float *calibrated_g, float *calibrated_b, float *calibrated_c);
void control_led(int gpio_pin, int state);
void signal_handler(int signal);

// Function to initialize the TCS34725 sensor
int tcs34725_init(int i2c_fd) {
    uint8_t buf[2];

    // Enable power and RGBC
    buf[0] = TCS34725_COMMAND_BIT | TCS34725_ENABLE;
    buf[1] = TCS34725_PON | TCS34725_AEN;
    if (write(i2c_fd, buf, 2) != 2) {
        perror("Failed to write to enable register");
        return -1;
    }

    // Set integration time
    buf[0] = TCS34725_COMMAND_BIT | TCS34725_ATIME;
    buf[1] = TCS34725_INTEGRATIONTIME_154MS;
    if (write(i2c_fd, buf, 2) != 2) {
        perror("Failed to write to integration time register");
        return -1;
    }

    // Set gain
    buf[0] = TCS34725_COMMAND_BIT | TCS34725_CONTROL;
    buf[1] = TCS34725_GAIN_1X; // Adjust gain as needed
    if (write(i2c_fd, buf, 2) != 2) {
        perror("Failed to write to gain register");
        return -1;
    }

    return 0;
}

// Function to read raw RGBC data from the sensor
int tcs34725_read_raw_data(int i2c_fd, uint16_t *r, uint16_t *g, uint16_t *b, uint16_t *c) {
    uint8_t buf[1];
    uint8_t data[8];

    // Read clear data
    buf[0] = TCS34725_COMMAND_BIT | TCS34725_CDATA;
    if (write(i2c_fd, buf, 1) != 1) {
        perror("Failed to write to clear data register");
        return -1;
    }
    if (read(i2c_fd, data, 2) != 2) {
        perror("Failed to read clear data");
        return -1;
    }
    *c = (data[1] << 8) | data[0];

    // Read red data
    buf[0] = TCS34725_COMMAND_BIT | TCS34725_RDATA;
    if (write(i2c_fd, buf, 1) != 1) {
        perror("Failed to write to red data register");
        return -1;
    }
    if (read(i2c_fd, data, 2) != 2) {
        perror("Failed to read red data");
        return -1;
    }
    *r = (data[1] << 8) | data[0];

    // Read green data
    buf[0] = TCS34725_COMMAND_BIT | TCS34725_GDATA;
    if (write(i2c_fd, buf, 1) != 1) {
        perror("Failed to write to green data register");
        return -1;
    }
    if (read(i2c_fd, data, 2) != 2) {
        perror("Failed to read green data");
        return -1;
    }
    *g = (data[1] << 8) | data[0];

    // Read blue data
    buf[0] = TCS34725_COMMAND_BIT | TCS34725_BDATA;
    if (write(i2c_fd, buf, 1) != 1) {
        perror("Failed to write to blue data register");
        return -1;
    }
    if (read(i2c_fd, data, 2) != 2) {
        perror("Failed to read blue data");
        return -1;
    }
    *b = (data[1] << 8) | data[0];

    return 0;
}

// Function to calibrate the raw RGBC data
void calibrate_color_data(uint16_t r, uint16_t g, uint16_t b, uint16_t c, float *calibrated_r, float *calibrated_g, float *calibrated_b, float *calibrated_c) {
    // Simple calibration (adjust as needed)
    *calibrated_r = (float)r; // / (float)c; // Normalize by clear value
    *calibrated_g = (float)g; // / (float)c;
    *calibrated_b = (float)b; // / (float)c;
    *calibrated_c = (float)c;
}

// Function to control the LED
void control_led(int gpio_pin, int state) {
    gpioWrite(gpio_pin, state);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    uint16_t r, g, b, c;
    float calibrated_r, calibrated_g, calibrated_b, calibrated_c;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set LED GPIO pin as output
    gpioSetMode(LED_GPIO_PIN, PI_OUTPUT);

    // Open I2C bus
    char i2c_device[20];
    snprintf(i2c_device, sizeof(i2c_device), "/dev/i2c-%d", I2C_BUS);
    i2c_fd = open(i2c_device, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        gpioTerminate();
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, TCS34725_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Initialize TCS34725 sensor
    if (tcs34725_init(i2c_fd) < 0) {
        fprintf(stderr, "TCS34725 initialization failed\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    printf("TCS34725 sensor initialized successfully\n");

    // Main loop
    while (!terminate) {
        // Read raw RGBC data
        if (tcs34725_read_raw_data(i2c_fd, &r, &g, &b, &c) < 0) {
            fprintf(stderr, "Failed to read raw data, re-initializing...\n");
            close(i2c_fd);
            char i2c_device[20];
            snprintf(i2c_device, sizeof(i2c_device), "/dev/i2c-%d", I2C_BUS);
            i2c_fd = open(i2c_device, O_RDWR);
            if (i2c_fd < 0) {
                perror("Failed to open I2C bus");
                gpioTerminate();
                return 1;
            }
            if (ioctl(i2c_fd, I2C_SLAVE, TCS34725_ADDRESS) < 0) {
                perror("Failed to set I2C slave address");
                close(i2c_fd);
                gpioTerminate();
                return 1;
            }
            if (tcs34725_init(i2c_fd) < 0) {
                fprintf(stderr, "TCS34725 re-initialization failed\n");
                close(i2c_fd);
                gpioTerminate();
                return 1;
            }
            continue; // Skip to the next iteration
        }

        // Calibrate color data
        calibrate_color_data(r, g, b, c, &calibrated_r, &calibrated_g, &calibrated_b, &calibrated_c);

        // Control LED based on red value
        if (calibrated_r > RED_THRESHOLD) {
            control_led(LED_GPIO_PIN, 1); // Turn LED on
        } else {
            control_led(LED_GPIO_PIN, 0); // Turn LED off
        }

        // Print calibrated color data
        printf("Calibrated R: %.2f, G: %.2f, B: %.2f, C: %.2f\n", calibrated_r, calibrated_g, calibrated_b, calibrated_c);

        // Wait 200ms
        usleep(200000); // 200ms
    }

    // Cleanup
    close(i2c_fd);
    gpioWrite(LED_GPIO_PIN, 0); // Turn off LED
    gpioTerminate();

    printf("Program terminated gracefully\n");

    return 0;
}

