#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <wiringPi.h>
#include <wiringPiI2C.h>
#include <wiringPiSPI.h>

// Constants
#define BH1750_ADDR 0x23
#define CONTINUOUS_HIGH_RES_MODE 0x10
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define NUM_LEDS 10

// Global variables
int bh1750_fd;
int spi_fd;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int init_bh1750();
int read_light_level();
int init_apa102();
void set_led_brightness(int brightness);
void send_apa102_frame(uint32_t frame);
void send_end_frame();
void signal_handler(int signal);

// Signal handler
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Caught SIGINT, shutting down...\n");
        program_running = 0;
    }
}

// Initialize BH1750 sensor
int init_bh1750() {
    bh1750_fd = wiringPiI2CSetup(BH1750_ADDR);
    if (bh1750_fd == -1) {
        fprintf(stderr, "Error initializing BH1750: %s\n", strerror(errno));
        return -1;
    }

    // Set to continuous high-resolution mode
    if (wiringPiI2CWrite(bh1750_fd, CONTINUOUS_HIGH_RES_MODE) == -1) {
        fprintf(stderr, "Error setting BH1750 mode: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Read light level from BH1750
int read_light_level() {
    int msb, lsb;

    msb = wiringPiI2CReadReg8(bh1750_fd, 0x00); // Dummy register address
    if (msb == -1) {
        fprintf(stderr, "Error reading MSB from BH1750: %s\n", strerror(errno));
        return -1;
    }

    lsb = wiringPiI2CReadReg8(bh1750_fd, 0x01); // Dummy register address
    if (lsb == -1) {
        fprintf(stderr, "Error reading LSB from BH1750: %s\n", strerror(errno));
        return -1;
    }

    return (msb << 8) | lsb;
}

// Initialize APA102 LED strip
int init_apa102() {
    spi_fd = wiringPiSPISetup(SPI_CHANNEL, SPI_SPEED);
    if (spi_fd == -1) {
        fprintf(stderr, "Error initializing SPI: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Set the brightness of all LEDs
void set_led_brightness(int brightness) {
    uint8_t data[4];
    data[0] = 0xE0 | (brightness & 0x1F); // Global brightness (5 bits)
    data[1] = 0x00; // Blue
    data[2] = 0x00; // Green
    data[3] = 0x00; // Red

    for (int i = 0; i < NUM_LEDS; i++) {
        send_apa102_frame((uint32_t)((data[0] << 24) | (data[1] << 16) | (data[2] << 8) | data[3]));
    }
}

// Send a single APA102 LED frame
void send_apa102_frame(uint32_t frame) {
    uint8_t data[4];
    data[0] = (frame >> 24) & 0xFF;
    data[1] = (frame >> 16) & 0xFF;
    data[2] = (frame >> 8) & 0xFF;
    data[3] = frame & 0xFF;

    wiringPiSPIDataRW(SPI_CHANNEL, data, 4);
}

// Send the end frame
void send_end_frame() {
    uint8_t end_frame[4] = {0xFF, 0xFF, 0xFF, 0xFF};
    wiringPiSPIDataRW(SPI_CHANNEL, end_frame, 4);
}

int main() {
    // Initialize wiringPi
    if (wiringPiSetup() == -1) {
        fprintf(stderr, "Error initializing wiringPi: %s\n", strerror(errno));
        return 1;
    }

    // Initialize BH1750
    if (init_bh1750() == -1) {
        return 1;
    }

    // Initialize APA102
    if (init_apa102() == -1) {
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Program started. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Read light level
        int light_level = read_light_level();
        if (light_level == -1) {
            fprintf(stderr, "Error reading light level, retrying...\n");
            delay(100); // Small delay before retrying
            continue;
        }

        // Scale light level to brightness (0-255)
        int brightness = (int)(((float)light_level / 65535.0) * 255.0);
        if (brightness < 0) brightness = 0;
        if (brightness > 255) brightness = 255;

        // Set LED brightness
        set_led_brightness(brightness);

        // Send start frame
        uint8_t start_frame[4] = {0x00, 0x00, 0x00, 0x00};
        wiringPiSPIDataRW(SPI_CHANNEL, start_frame, 4);

        // Send end frame
        send_end_frame();

        // Wait 120ms
        delay(120);
    }

    // Turn off LEDs
    set_led_brightness(0);

    // Send end frame one last time
    send_end_frame();

    printf("Program finished.\n");

    return 0;
}

