#define NUM_SENSORS 3
#define NUM_LEDS 10
#define I2C_BUS 1
#define I2C_DELAY_MS 180
#define SPI_DELAY_US 1000 // 1ms
#define FADE_TIME_MS 500
#define TARGET_BRIGHTNESS 50 // Example target brightness

// Global variables
int i2c_handles[NUM_SENSORS];
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int init_spi();
int read_sensor(int handle);
float average_readings(int readings[], int num_sensors);
int set_led_brightness(int brightness);
int fade_brightness(int current_brightness, int target_brightness);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    terminate = 1;
}

// Initialize I2C
int init_i2c() {
    for (int i = 0; i < NUM_SENSORS; i++) {
        i2c_handles[i] = i2cOpen(I2C_BUS, (i == 0) ? BH1750_ADDR1 : (i == 1 ? BH1750_ADDR2 : BH1750_ADDR3), 0);
        if (i2c_handles[i] < 0) {
            fprintf(stderr, "Error opening I2C device %d: %d\n", i, i2c_handles[i]);
            // Attempt to close any previously opened handles
            for (int j = 0; j < i; j++) {
                i2cClose(i2c_handles[j]);
            }
            return -1;
        }
        // Send power on and continuous high resolution mode command
        if (i2cWriteByteData(i2c_handles[i], 0x00, 0x10) < 0) {
            fprintf(stderr, "Error writing to I2C device %d\n", i);
            i2cClose(i2c_handles[i]);
            // Attempt to close any previously opened handles
            for (int j = 0; j < i; j++) {
                i2cClose(i2c_handles[j]);
            }
            return -1;
        }
        gpioDelay(I2C_DELAY_MS * 1000); // Delay for conversion
    }
    return 0;
}

// Initialize SPI
int init_spi() {
    spi_handle = spiOpen(0, 1000000, 0); // SPI channel 0, 1MHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI device: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

