    float sum = 0.0;
    int count = 0;
    for (int i = 0; i < num_sensors; i++) {
        if (readings[i] >= 0) {
            sum += readings[i];
            count++;
        }
    }
    if (count > 0) {
        return sum / count;
    } else {
        return 0.0;
    }
}

