    // 0x00: Start frame
    // 0xFF: Global brightness (0-255)
    // 0xFF: Blue, Green, Red (all 0xFF for white)
    // 0x00: End frame

    unsigned char start_frame[1] = {0x00};
    unsigned char led_frame[NUM_LEDS * 4 + 2];
    led_frame[0] = 0xFF; // Global brightness
    led_frame[1] = 0xFF; // Blue
    led_frame[2] = 0xFF; // Green
    led_frame[3] = 0xFF; // Red

    for (int i = 0; i < NUM_LEDS; i++) {
        led_frame[i * 4 + 4] = 0xFF; // Blue
        led_frame[i * 4 + 5] = 0xFF; // Green
        led_frame[i * 4 + 6] = 0xFF; // Red
        led_frame[i * 4 + 7] = 0xFF; // White
    }

