    if (spiWrite(spi_handle, start_frame, 1) < 0) {
        fprintf(stderr, "Error writing start frame to SPI\n");
        return -1;
    }

    if (spiWrite(spi_handle, led_frame, sizeof(led_frame)) < 0) {
        fprintf(stderr, "Error writing LED frame to SPI\n");
        return -1;
    }

    if (spiWrite(spi_handle, end_frame, 1) < 0) {
        fprintf(stderr, "Error writing end frame to SPI\n");
        return -1;
    }

    return 0;
}

// Fade brightness
int fade_brightness(int current_brightness, int target_brightness) {
    int diff = target_brightness - current_brightness;
    int step = (diff > 0) ? 1 : -1;
    int num_steps = abs(diff);
    int increment = (num_steps > FADE_TIME_MS) ? 1 : num_steps / FADE_TIME_MS;

    for (int i = 0; i < num_steps; i += increment) {
        current_brightness += step * increment;
        if (set_led_brightness(current_brightness) < 0) {
            return -1;
        }
