#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <math.h>

// Constants
#define I2C_ADDR 0x48
#define GPIO_PIN 18
#define NUM_LEDS 1
#define GAMMA 2.2
#define MAX_LUX 1000.0 // Maximum expected lux value
#define MAX_BRIGHTNESS 255 // Maximum brightness value for WS2812B

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure for RGB color data
typedef struct {
    uint8_t r;
    uint8_t g;
    uint8_t b;
} RGB;

// Function prototypes
int init_i2c();
int read_veml7700(uint16_t *red, uint16_t *green, uint16_t *blue);
float calculate_lux(uint16_t red, uint16_t green, uint16_t blue);
uint8_t gamma_correct(float lux);
int set_led_brightness(uint8_t brightness);
void signal_handler(int signal);
void cleanup();

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(1, I2C_ADDR, 0); // Bus 1, address 0x48, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read data from VEML7700
int read_veml7700(uint16_t *red, uint16_t *green, uint16_t *blue) {
    char buf[6];
    int result;

    result = i2cReadI2CBlockData(i2c_handle, 0x04, buf, 6); // Read Red, Green, Blue (0x04, 0x06, 0x08)
    if (result != 6) {
        fprintf(stderr, "Error reading VEML7700 data: %d\n", result);
        return -1;
    }

    *red = (buf[1] << 8) | buf[0];
    *green = (buf[3] << 8) | buf[2];
    *blue = (buf[5] << 8) | buf[4];

    return 0;
}

// Function to calculate lux value
float calculate_lux(uint16_t red, uint16_t green, uint16_t blue) {
    // Simplified lux calculation (adjust coefficients as needed)
    float lux = 0.2126 * red + 0.7152 * green + 0.0722 * blue;
    return lux;
}

// Function to apply gamma correction
uint8_t gamma_correct(float lux) {
    float normalized_lux = lux / MAX_LUX;
    if (normalized_lux > 1.0) normalized_lux = 1.0;
    float gamma_corrected = pow(normalized_lux, GAMMA);
    uint8_t brightness = (uint8_t)(gamma_corrected * MAX_BRIGHTNESS);
    return brightness;
}

// Function to set LED brightness using bit-banging
int set_led_brightness(uint8_t brightness) {
    // WS2812B timing (approximate, adjust as needed)
    // 0: 0.4us low, 0.85us high
    // 1: 0.8us low, 0.45us high

    // Simplified approach: set all LEDs to the same brightness
    // This is a placeholder; a real implementation would send
    // the correct bit sequence for each color channel.

    // For now, just set the GPIO high or low based on brightness
    if (brightness > 128) {
        gpioWrite(GPIO_PIN, 1); // High
    } else {
        gpioWrite(GPIO_PIN, 0); // Low
    }

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    set_led_brightness(0); // Turn off LED
    gpioWrite(GPIO_PIN, 0); // Ensure GPIO is low
    i2cClose(i2c_handle);
    gpioTerminate();
    fprintf(stderr, "Cleanup complete.\n");
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as output
    gpioSetMode(GPIO_PIN, PI_OUTPUT);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uint16_t red, green, blue;
    float lux;
    uint8_t brightness;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_veml7700(&red, &green, &blue) == 0) {
            // Calculate lux value
            lux = calculate_lux(red, green, blue);

            // Apply gamma correction
            brightness = gamma_correct(lux);

            // Set LED brightness
            set_led_brightness(brightness);

            // Print data
            printf("Lux: %.2f, Brightness: %d\n", lux, brightness);
        } else {
            fprintf(stderr, "Failed to read sensor data.\n");
        }

        // Pause for 200ms
        gpioDelay(200000); // 200ms = 200000 us
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

