#include <signal.h>
#include <string.h>

// Define GPIO pins
#define FLAME_SENSOR_PIN 4
#define BUZZER_PIN 17
#define LED_PIN 18

// Function prototypes
int read_flame_sensor();
void activate_buzzer();
void deactivate_buzzer();
void activate_led();
void deactivate_led();
void log_event(const char *event_type, int sensor_value);
void signal_handler(int signal);

// Global variable for program termination
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("\nCaught SIGINT, exiting gracefully...\n");
        program_running = 0;
    }
}

// Function to read the flame sensor
int read_flame_sensor() {
    int value = gpioRead(FLAME_SENSOR_PIN);
    if (value < 0) {
        fprintf(stderr, "Error reading flame sensor: %d\n", value);
        return -1; // Indicate an error
    }
    return value;
}

// Function to activate the buzzer
void activate_buzzer() {
    int result = gpioWrite(BUZZER_PIN, 1);
    if (result < 0) {
        fprintf(stderr, "Error activating buzzer: %d\n", result);
    }
}

// Function to deactivate the buzzer
void deactivate_buzzer() {
    int result = gpioWrite(BUZZER_PIN, 0);
    if (result < 0) {
        fprintf(stderr, "Error deactivating buzzer: %d\n", result);
    }
}

// Function to activate the LED
void activate_led() {
    int result = gpioWrite(LED_PIN, 1);
    if (result < 0) {
        fprintf(stderr, "Error activating LED: %d\n", result);
    }
}

// Function to deactivate the LED
void deactivate_led() {
    int result = gpioWrite(LED_PIN, 0);
    if (result < 0) {
        fprintf(stderr, "Error deactivating LED: %d\n", result);
    }
}

// Function to log events with timestamps
void log_event(const char *event_type, int sensor_value) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("[%s] %s: Sensor Value = %d\n", timestamp, event_type, sensor_value);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    if (gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error setting flame sensor pin mode\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting buzzer pin mode\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting LED pin mode\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Startup self-test
    printf("Starting self-test...\n");
    for (int i = 0; i < 2; i++) {
        activate_led();
        gpioDelay(500);
        deactivate_led();
        gpioDelay(500);
    }

    int flame_detected_count = 0;
    for (int i = 0; i < 5; i++) {
        int sensor_value = read_flame_sensor();
        if (sensor_value == 0) {
            flame_detected_count++;
        }
        gpioDelay(100);
    }

    if (flame_detected_count == 5) {
        printf("Error: Persistent flame detected during self-test!\n");
        log_event("ERROR", 0);
        // Rapid LED blinking
        for (int i = 0; i < 5; i++) {
            activate_led();
            gpioDelay(100);
            deactivate_led();
            gpioDelay(100);
        }

        // Buzzer pattern
        for (int i = 0; i < 3; i++) {
            activate_buzzer();
            gpioDelay(200);
            deactivate_buzzer();
            gpioDelay(200);
            activate_buzzer();
            gpioDelay(200);
            deactivate_buzzer();
            gpioDelay(600);
            activate_buzzer();
            gpioDelay(200);
            deactivate_buzzer();
        }

        gpioTerminate();
        return 1;
    }

    printf("Self-test complete. Starting main loop...\n");

    // Main loop
    while (program_running) {
        int sensor_value = read_flame_sensor();
        if (sensor_value == 0) {
            // Flame detected
            activate_buzzer();
            activate_led();
            log_event("FLAME DETECTED", 0);
            gpioDelay(50);
            while (program_running && read_flame_sensor() == 0) {
                gpioDelay(50);
            }
            deactivate_buzzer();
            deactivate_led();
            log_event("FLAME CLEARED", 1);
        } else if (sensor_value == 1) {
            // No flame detected
            gpioDelay(50);
        } else {
            // Error reading sensor
            log_event("ERROR", -1);
            gpioDelay(50);
        }
    }

    // Cleanup GPIO lines before exiting
    gpioTerminate();
    printf("Program terminated gracefully.\n");
    return 0;
}

