#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <wiringPi.h>
#include <wiringPiI2C.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>

// Constants
#define BH1750_ADDR 0x23
#define CONTINUOUS_HIGH_RES_MODE 0x10
#define GPIO_LED 17
#define BUFFER_SIZE 60

// Global variables
int i2c_fd;
volatile sig_atomic_t program_running = 1;

// Circular buffer
float lux_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int read_bh1750(int fd);
float calculate_average_lux(float buffer[], int size);
void set_led_frequency(float average_lux);
void signal_handler(int signal);
void cleanup();

// Function to read light intensity from BH1750 sensor
int read_bh1750(int fd) {
    int lux = -1; // Initialize to an invalid value
    int retries = 3; // Number of retries

    while (retries > 0) {
        if (wiringPiI2CWrite(fd, CONTINUOUS_HIGH_RES_MODE) < 0) {
            fprintf(stderr, "Error: Failed to set BH1750 mode: %s\n", strerror(errno));
            delay(100); // Wait before retrying
            retries--;
            continue;
        }

        delay(200); // Wait for measurement (at least 180ms)

        int msb = wiringPiI2CReadReg8(fd, 0x00);
        int lsb = wiringPiI2CReadReg8(fd, 0x01);

        if (msb >= 0 && lsb >= 0) {
            lux = (msb << 8 | lsb) / 1.2; // Convert to lux
            break; // Exit retry loop on success
        } else {
            fprintf(stderr, "Error: Failed to read BH1750 data: %s\n", strerror(errno));
            delay(100); // Wait before retrying
            retries--;
        }
    }

    if (lux == -1) {
        fprintf(stderr, "Error: Failed to read BH1750 after multiple retries.\n");
    }

    return lux;
}

// Function to calculate the average lux value
float calculate_average_lux(float buffer[], int size) {
    float sum = 0.0;
    int count = 0;
    for (int i = 0; i < size; i++) {
        if (buffer[i] >= 0) { // Only include valid readings
            sum += buffer[i];
            count++;
        }
    }
    if (count > 0) {
        return sum / count;
    } else {
        return -1.0; // Indicate no valid readings
    }
}

// Function to set the LED frequency based on average lux
void set_led_frequency(float average_lux) {
    float frequency = 0.5; // Default frequency (darkness)
    if (average_lux > 0) {
        frequency = 0.5 + (average_lux / 1000.0) * 4.5; // Linear mapping to 0.5-5 Hz
        if (frequency > 5.0) {
            frequency = 5.0;
        }
    }

    // Calculate the period in milliseconds
    int period_ms = (int)(1000.0 / frequency);

    // Calculate the on and off durations for 50% duty cycle
    int on_duration = period_ms / 2;
    int off_duration = period_ms / 2;

    digitalWrite(GPIO_LED, HIGH); // Turn LED on
    delay(on_duration);
    digitalWrite(GPIO_LED, LOW);  // Turn LED off
    delay(off_duration);
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Cleanup function to release resources
void cleanup() {
    digitalWrite(GPIO_LED, LOW); // Turn off LED
    // No need to unexport GPIO using wiringPi, it's handled internally.
    if (i2c_fd > 0) {
        close(i2c_fd);
    }
    printf("Cleanup complete.\n");
}

int main() {
    // Initialize wiringPi
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "Error: Failed to initialize wiringPi: %s\n", strerror(errno));
        return 1;
    }

    // Initialize I2C
    i2c_fd = wiringPiI2CSetup(BH1750_ADDR);
    if (i2c_fd == -1) {
        fprintf(stderr, "Error: Failed to initialize I2C: %s\n", strerror(errno));
        return 1;
    }

    // Set GPIO pin as output
    pinMode(GPIO_LED, OUTPUT);
    digitalWrite(GPIO_LED, LOW); // Initially turn the LED off

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize circular buffer with -1 (invalid value)
    for (int i = 0; i < BUFFER_SIZE; i++) {
        lux_buffer[i] = -1.0;
    }

    printf("Program started. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Read light intensity
        int lux = read_bh1750(i2c_fd);

        if (lux >= 0) {
            // Store reading in circular buffer
            lux_buffer[buffer_index] = (float)lux;
            buffer_index = (buffer_index + 1) % BUFFER_SIZE;

            // Calculate average lux
            float average_lux = calculate_average_lux(lux_buffer, BUFFER_SIZE);

            if (average_lux >= 0) {
                // Set LED frequency
                set_led_frequency(average_lux);
                printf("Average Lux: %.2f\n", average_lux);
            } else {
                fprintf(stderr, "Error: No valid readings to calculate average.\n");
            }
        } else {
            fprintf(stderr, "Error: Failed to read light intensity.\n");
        }

        delay(1000); // Wait 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

