    exit(0);
}

// Function to shift out 8 bits of data
void shift_out(unsigned char data) {
    for (int i = 0; i < 8; i++) {
        // Set data pin based on the current bit
        gpioWrite(DATA_PIN, (data >> (7 - i)) & 0x01);

        // Clock the data in
        gpioWrite(CLOCK_PIN, 1);
        gpioDelay(1); // Small delay for clock stability
        gpioWrite(CLOCK_PIN, 0);
        gpioDelay(1);
    }
}

// Function to set the segment pattern for a given digit
void set_segment(unsigned char digit) {
    if (digit >= 0 && digit <= 9) {
        shift_out(segment_patterns[digit]);
    } else {
        fprintf(stderr, "Error: Invalid digit %d\n", digit);
    }
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(DATA_PIN, PI_OUTPUT);
    gpioSetMode(CLOCK_PIN, PI_OUTPUT);
    gpioSetMode(LATCH_PIN, PI_OUTPUT);

    // Register signal handler for Ctrl+C
    signal(SIGINT, cleanup);

    // Main loop
    while (program_running) {
        // Set segment pattern for digit 5
        set_segment(5);

        // Latch the data
        gpioWrite(LATCH_PIN, 1);
        gpioDelay(1); // Small delay for latch stability
        gpioWrite(LATCH_PIN, 0);
        gpioDelay(1);

        // Blink the digit (on for 500ms, off for 500ms)
        gpioDelay(500); // On time

        // Turn off the digit
        set_segment(0); // Use 0 to turn off all segments

        // Latch the data
        gpioWrite(LATCH_PIN, 1);
        gpioDelay(1); // Small delay for latch stability
        gpioWrite(LATCH_PIN, 0);
        gpioDelay(1);

        gpioDelay(500); // Off time
    }

    // Cleanup (should not reach here if signal handler works)
    gpioTerminate();
    return 0;
}

