void signal_handler(int signal) {
    if (signal == SIGINT) {
        fprintf(stderr, "\nCaught SIGINT, exiting gracefully...\n");
        program_running = 0;
    }
}

// Function to blink the LED
void blink_led() {
    if (gpioWrite(LED_PIN, 1) != 0) {
        fprintf(stderr, "Error setting LED high\n");
        program_running = 0;
        return;
    }
    gpioDelay(1000); // 1 second
    if (gpioWrite(LED_PIN, 0) != 0) {
        fprintf(stderr, "Error setting LED low\n");
        program_running = 0;
        return;
    }
    gpioDelay(1000); // 1 second
}

// Function to handle button press
void button_pressed() {
    if (gpioWrite(LED_PIN, 0) != 0) {
        fprintf(stderr, "Error setting LED low\n");
        program_running = 0;
        return;
    }
    printf("Button pressed!\n");
    program_running = 0; // Exit the main loop
}

int main() {
    // Register signal handler for SIGINT
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("signal");
        return 1;
    }

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set LED pin as output
    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting LED pin as output\n");
        gpioTerminate();
        return 1;
    }
    gpioWrite(LED_PIN, 0); // Initially turn LED off

    // Set button pin as input with pull-up resistor
    if (gpioSetMode(BUTTON_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error setting button pin as input\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetPullUpDown(BUTTON_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error setting pull-up resistor on button pin\n");
        gpioTerminate();
        return 1;
    }

    // Request falling edge detection on the button pin
    if (gpioSetAlertFunc(BUTTON_PIN, button_pressed) != 0) {
        fprintf(stderr, "Error requesting falling edge detection on button pin\n");
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (program_running) {
        blink_led();
    }

    // Cleanup
    gpioWrite(LED_PIN, 0); // Ensure LED is off
    gpioSetAlertFunc(BUTTON_PIN, NULL); // Disable alert function
    gpioTerminate();

    return 0;
}

