#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define LED_PIN 24
#define BUTTON_PIN 22

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    // Set LED pin as output
    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set LED pin as output\n");
        gpioTerminate();
        return -1;
    }

    // Set button pin as input with pull-down resistor
    if (gpioSetMode(BUTTON_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set button pin as input\n");
        gpioTerminate();
        return -1;
    }

    if (gpioSetPullUpDown(BUTTON_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Failed to set pull-down resistor on button pin\n");
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to control the LED
void control_led(int button_state) {
    static int led_state = 0; // 0: off, 1: on
    static int button_pressed = 0;

    if (button_state == 1 && !button_pressed) {
        // Button pressed
        button_pressed = 1;
        while (gpioRead(BUTTON_PIN) == 1 && program_running) {
            // Blink LED
            gpioWrite(LED_PIN, led_state);
            led_state = !led_state;
            gpioDelay(500000); // 500ms
        }
        // Button released
        gpioWrite(LED_PIN, 0); // Turn LED off
        button_pressed = 0;
    } else if (button_state == 0) {
        // Button released
        button_pressed = 0;
        gpioWrite(LED_PIN, 0); // Ensure LED is off
    }
}

// Function to cleanup GPIO resources
void cleanup_gpio() {
    gpioWrite(LED_PIN, 0); // Turn off LED
    gpioTerminate();
    fprintf(stderr, "GPIO resources released.\n");
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    fprintf(stderr, "Program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        int button_state = gpioRead(BUTTON_PIN);
        if (button_state < 0) {
            fprintf(stderr, "Error reading button state\n");
            cleanup_gpio();
            return 1;
        }
        control_led(button_state);
        gpioDelay(10000); // Small delay to prevent busy-waiting
    }

    // Cleanup and exit
    cleanup_gpio();
    return 0;
}

