#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins for RGB LED
#define RED_PIN   24
#define GREEN_PIN 23
#define BLUE_PIN  18

// Define PWM frequency and period
#define PWM_FREQUENCY 100 // Hz
#define PWM_PERIOD_US (1000000 / PWM_FREQUENCY) // microseconds

// Define PWM resolution
#define PWM_RESOLUTION 100 // 0-100

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    if (signal == SIGINT) {
        fprintf(stderr, "\nCaught SIGINT, exiting gracefully...\n");
        program_running = 0;
    }
}

// Function to set the PWM duty cycle for a given GPIO pin
int set_pwm_duty_cycle(int gpio_pin, int duty_cycle) {
    if (gpioPWM(gpio_pin, duty_cycle) != 0) {
        fprintf(stderr, "Error: Failed to set PWM duty cycle for GPIO %d\n", gpio_pin);
        return -1;
    }
    return 0;
}

// Function to generate a random duty cycle value between 0 and PWM_RESOLUTION
int generate_random_duty_cycle() {
    return rand() % (PWM_RESOLUTION + 1);
}

// Function to generate a random RGB color
void generate_random_color(int *red, int *green, int *blue) {
    *red   = generate_random_duty_cycle();
    *green = generate_random_duty_cycle();
    *blue  = generate_random_duty_cycle();
}

// Function to update the RGB LED with the given color values
int update_led(int red, int green, int blue) {
    if (set_pwm_duty_cycle(RED_PIN, red) != 0)   return -1;
    if (set_pwm_duty_cycle(GREEN_PIN, green) != 0) return -1;
    if (set_pwm_duty_cycle(BLUE_PIN, blue) != 0)  return -1;
    return 0;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);

    // Seed the random number generator
    srand(time(NULL));

    // Install signal handler for SIGINT
    signal(SIGINT, signal_handler);

    int red, green, blue;

    // Main loop
    while (program_running) {
        // Generate a random color
        generate_random_color(&red, &green, &blue);

        // Update the LED
        if (update_led(red, green, blue) != 0) {
            fprintf(stderr, "Error: Failed to update LED\n");
            break; // Exit loop on error
        }

        // Wait for 100ms
        struct timespec sleep_time;
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = 100000000; // 100 milliseconds
        nanosleep(&sleep_time, NULL);
    }

    // Clean up GPIO resources before exiting
    gpioTerminate();

    return 0;
}

