#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define ADPD188BI_ADDR 0x39
#define ALS_LSB_REG 0x00
#define ALS_MSB_REG 0x01
#define RED_LSB_REG 0x02
#define RED_MSB_REG 0x03
#define GREEN_LSB_REG 0x04
#define GREEN_MSB_REG 0x05
#define BLUE_LSB_REG 0x06
#define BLUE_MSB_REG 0x07
#define LED_GPIO 18
#define PWM_FREQUENCY 1000 // Hz
#define PWM_RANGE 1000      // PWM range for 0-100% duty cycle
#define SAMPLE_INTERVAL_MS 500

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c();
int read_sensor_data(uint16_t *als, uint16_t *red, uint16_t *green, uint16_t *blue);
void control_led(uint16_t als_value);
void log_data(uint16_t als, uint16_t red, uint16_t green, uint16_t blue);
void signal_handler(int signal);
void cleanup();

// Structure to hold sensor data
typedef struct {
    uint16_t als;
    uint16_t red;
    uint16_t green;
    uint16_t blue;
} sensor_data_t;

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("color_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,ALS,Red,Green,Blue\n");
    }
    rewind(log_file);

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&sensor_data.als, &sensor_data.red, &sensor_data.green, &sensor_data.blue) == 0) {
            // Log data
            log_data(sensor_data.als, sensor_data.red, sensor_data.green, sensor_data.blue);

            // Control LED
            control_led(sensor_data.als);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Convert ms to microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize I2C
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ADPD188BI_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Read sensor data
int read_sensor_data(uint16_t *als, uint16_t *red, uint16_t *green, uint16_t *blue) {
    char buf[2];
    int result;

    // Read ALS data
    result = i2cReadI2CBlockData(i2c_handle, ALS_LSB_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to read ALS data: %s\n", strerror(errno));
        return -1;
    }
    *als = (uint16_t)buf[1] << 8 | (uint16_t)buf[0];

    // Read Red data
    result = i2cReadI2CBlockData(i2c_handle, RED_LSB_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to read Red data: %s\n", strerror(errno));
        return -1;
    }
    *red = (uint16_t)buf[1] << 8 | (uint16_t)buf[0];

    // Read Green data
    result = i2cReadI2CBlockData(i2c_handle, GREEN_LSB_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to read Green data: %s\n", strerror(errno));
        return -1;
    }
    *green = (uint16_t)buf[1] << 8 | (uint16_t)buf[0];

    // Read Blue data
    result = i2cReadI2CBlockData(i2c_handle, BLUE_LSB_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to read Blue data: %s\n", strerror(errno));
        return -1;
    }
    *blue = (uint16_t)buf[1] << 8 | (uint16_t)buf[0];

    return 0;
}

// Control LED brightness using PWM
void control_led(uint16_t als_value) {
    // Map ALS value to PWM duty cycle (0-1000)
    int duty_cycle = (int)(((float)als_value / 65535.0) * PWM_RANGE);

    // Ensure duty cycle is within valid range
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > PWM_RANGE) duty_cycle = PWM_RANGE;

    gpioPWM(LED_GPIO, duty_cycle);
}

// Log data to CSV file
void log_data(uint16_t als, uint16_t red, uint16_t green, uint16_t blue) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%u,%u,%u,%u\n", timestamp, als, red, green, blue);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioPWM(LED_GPIO, 0); // Turn off LED
    gpioTerminate();
}

