#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// GY-50 L3G4200D I2C address
#define GYRO_ADDRESS 0x69

// GY-50 L3G4200D register addresses
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define OUT_X_L 0x28
#define OUT_X_H 0x29
#define OUT_Y_L 0x2A
#define OUT_Y_H 0x2B
#define OUT_Z_L 0x2C
#define OUT_Z_H 0x2D
#define WHO_AM_I 0x0F

// Calibration parameters
#define NUM_CALIBRATION_SAMPLES 100
#define ALERT_THRESHOLD 50.0f // dps

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold gyroscope data
typedef struct {
    float x;
    float y;
    float z;
} gyro_data_t;

// Function prototypes
int initialize_gyro();
gyro_data_t read_gyro_data();
gyro_data_t calibrate_gyro(gyro_data_t raw_data, float x_offset, float y_offset, float z_offset);
void log_data(gyro_data_t calibrated_data);
void check_alert(gyro_data_t calibrated_data);
void signal_handler(int signal);
char* iso8601_timestamp();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
}

// Function to get ISO 8601 timestamp
char* iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Function to initialize the gyroscope
int initialize_gyro() {
    // Set CTRL_REG1 to 0x0F (normal mode, all axes enabled, 100 Hz ODR)
    if (i2cWriteByteData(i2c_handle, CTRL_REG1, 0x0F) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1: %s\n", strerror(errno));
        return -1;
    }

    // Set CTRL_REG4 to 0x00 (250 dps full scale)
    if (i2cWriteByteData(i2c_handle, CTRL_REG4, 0x00) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG4: %s\n", strerror(errno));
        return -1;
    }

    // Verify WHO_AM_I register
    int who_am_i = i2cReadByteData(i2c_handle, WHO_AM_I);
    if (who_am_i < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %s\n", strerror(errno));
        return -1;
    }

    if (who_am_i != 0xD3) {
        fprintf(stderr, "Error: Incorrect WHO_AM_I value: 0x%X\n", who_am_i);
        return -1;
    }

    return 0;
}

// Function to read raw gyroscope data
gyro_data_t read_gyro_data() {
    gyro_data_t raw_data;
    int16_t x, y, z;

    // Read X axis data
    int x_l = i2cReadByteData(i2c_handle, OUT_X_L);
    int x_h = i2cReadByteData(i2c_handle, OUT_X_H);
    if (x_l < 0 || x_h < 0) {
        fprintf(stderr, "Error reading X axis data: %s\n", strerror(errno));
        raw_data.x = 0.0f; // Set to 0 to avoid further issues
    } else {
        x = (int16_t)((x_h << 8) | x_l);
        raw_data.x = (float)x;
    }

    // Read Y axis data
    int y_l = i2cReadByteData(i2c_handle, OUT_Y_L);
    int y_h = i2cReadByteData(i2c_handle, OUT_Y_H);
    if (y_l < 0 || y_h < 0) {
        fprintf(stderr, "Error reading Y axis data: %s\n", strerror(errno));
        raw_data.y = 0.0f; // Set to 0 to avoid further issues
    } else {
        y = (int16_t)((y_h << 8) | y_l);
        raw_data.y = (float)y;
    }

    // Read Z axis data
    int z_l = i2cReadByteData(i2c_handle, OUT_Z_L);
    int z_h = i2cReadByteData(i2c_handle, OUT_Z_H);
    if (z_l < 0 || z_h < 0) {
        fprintf(stderr, "Error reading Z axis data: %s\n", strerror(errno));
        raw_data.z = 0.0f; // Set to 0 to avoid further issues
    } else {
        z = (int16_t)((z_h << 8) | z_l);
        raw_data.z = (float)z;
    }

    return raw_data;
}

// Function to calibrate the gyroscope
gyro_data_t calibrate_gyro(gyro_data_t raw_data, float x_offset, float y_offset, float z_offset) {
    gyro_data_t calibrated_data;
    calibrated_data.x = raw_data.x - x_offset;
    calibrated_data.y = raw_data.y - y_offset;
    calibrated_data.z = raw_data.z - z_offset;
    return calibrated_data;
}

// Function to log the data to a file
void log_data(gyro_data_t calibrated_data) {
    char* timestamp = iso8601_timestamp();
    fprintf(log_file, "%s,%.2f,%.2f,%.2f\n", timestamp, calibrated_data.x, calibrated_data.y, calibrated_data.z);
    fflush(log_file); // Ensure data is written to disk immediately
    free(timestamp);
}

// Function to check for alerts
void check_alert(gyro_data_t calibrated_data) {
    if (fabs(calibrated_data.x) > ALERT_THRESHOLD ||
        fabs(calibrated_data.y) > ALERT_THRESHOLD ||
        fabs(calibrated_data.z) > ALERT_THRESHOLD) {
        char* timestamp = iso8601_timestamp();
        fprintf(log_file, "%s,ALERT: High angular velocity detected!\n", timestamp);
        fflush(log_file);
        fprintf(stderr, "%s,ALERT: High angular velocity detected!\n", timestamp);
        free(timestamp);
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, GYRO_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Initialize the gyroscope
    if (initialize_gyro() < 0) {
        fprintf(stderr, "Gyroscope initialization failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("gyro_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Calibration loop
    float x_offset = 0.0f;
    float y_offset = 0.0f;
    float z_offset = 0.0f;
    float x_sum = 0.0f;
    float y_sum = 0.0f;
    float z_sum = 0.0f;

    printf("Calibrating gyroscope for 100 samples...\n");
    for (int i = 0; i < NUM_CALIBRATION_SAMPLES; i++) {
        gyro_data_t raw_data = read_gyro_data();
        x_sum += raw_data.x;
        y_sum += raw_data.y;
        z_sum += raw_data.z;
        gpioDelay(10); // Small delay between samples
    }

    x_offset = x_sum / NUM_CALIBRATION_SAMPLES;
    y_offset = y_sum / NUM_CALIBRATION_SAMPLES;
    z_offset = z_sum / NUM_CALIBRATION_SAMPLES;

    printf("Calibration complete. Offsets: X=%.2f, Y=%.2f, Z=%.2f\n", x_offset, y_offset, z_offset);

    // Main loop
    while (!terminate) {
        gyro_data_t raw_data = read_gyro_data();
        gyro_data_t calibrated_data = calibrate_gyro(raw_data, x_offset, y_offset, z_offset);
        log_data(calibrated_data);
        check_alert(calibrated_data);
        gpioDelay(50); // 20 Hz sampling rate
    }

    // Close I2C bus and log file
    i2cClose(i2c_handle);
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

