#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <math.h>
#include <string.h>

// ADXL345 I2C address
#define ADXL345_ADDR 0x53

// ADXL345 registers
#define ADXL345_REG_DEVID 0x00
#define ADXL345_REG_DATAX0 0x32
#define ADXL345_REG_POWER_CTL 0x2D
#define ADXL345_REG_DATA_FORMAT 0x31

// Full resolution, ±2g range
#define ADXL345_RANGE_2G 0x08

// LED GPIO pin
#define LED_PIN 17

// I2C handle
int i2c_handle;

// File pointer for logging
FILE *log_file;

// Function prototypes
int adxl345_init();
int read_acceleration(float *x, float *y, float *z);
void log_data(float x, float y, float z);
void control_led(float x, float y, float z);
void signal_handler(int signal);

// Structure to hold accelerometer data
typedef struct {
    float x;
    float y;
    float z;
} accelerometer_data_t;

// Global flag to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize the ADXL345
int adxl345_init() {
    // Verify device ID
    int devid = i2cReadByteData(i2c_handle, ADXL345_REG_DEVID);
    if (devid < 0) {
        fprintf(stderr, "Error reading device ID: %d\n", devid);
        return -1;
    }
    if (devid != 0xE5) {
        fprintf(stderr, "Incorrect device ID: 0x%02X\n", devid);
        return -1;
    }

    // Set data format to full resolution, ±2g range
    int result = i2cWriteByteData(i2c_handle, ADXL345_REG_DATA_FORMAT, ADXL345_RANGE_2G);
    if (result < 0) {
        fprintf(stderr, "Error writing to data format register: %d\n", result);
        return -1;
    }

    // Start measurement
    result = i2cWriteByteData(i2c_handle, ADXL345_REG_POWER_CTL, 0x08);
    if (result < 0) {
        fprintf(stderr, "Error writing to power control register: %d\n", result);
        return -1;
    }

    return 0;
}

// Read acceleration data from the ADXL345
int read_acceleration(float *x, float *y, float *z) {
    char raw_data[6];
    int result = i2cReadI2CBlockData(i2c_handle, ADXL345_REG_DATAX0, raw_data, 6);
    if (result < 0) {
        fprintf(stderr, "Error reading acceleration data: %d\n", result);
        return -1;
    }

    // Combine high and low bytes, convert to g units
    int16_t x_raw = (int16_t)((raw_data[1] << 8) | raw_data[0]);
    int16_t y_raw = (int16_t)((raw_data[3] << 8) | raw_data[2]);
    int16_t z_raw = (int16_t)((raw_data[5] << 8) | raw_data[4]);

    *x = (float)x_raw / 256.0;
    *y = (float)y_raw / 256.0;
    *z = (float)z_raw / 256.0;

    return 0;
}

// Log data to file
void log_data(float x, float y, float z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.3f,%.3f,%.3f\n", timestamp, x, y, z);
    fflush(log_file); // Ensure data is written to file immediately
}

// Control the LED based on acceleration values
void control_led(float x, float y, float z) {
    if (fabs(x) > 2.0 || fabs(y) > 2.0 || fabs(z) > 2.0) {
        gpioWrite(LED_PIN, 1); // Turn LED on
    } else {
        gpioWrite(LED_PIN, 0); // Turn LED off
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, ADXL345_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize ADXL345
    if (adxl345_init() != 0) {
        fprintf(stderr, "ADXL345 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set LED pin as output
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Open log file
    log_file = fopen("accel_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    accelerometer_data_t accel_data;

    // Main loop
    while (program_running) {
        if (read_acceleration(&accel_data.x, &accel_data.y, &accel_data.z) == 0) {
            log_data(accel_data.x, accel_data.y, accel_data.z);
            control_led(accel_data.x, accel_data.y, accel_data.z);
        } else {
            fprintf(stderr, "Error reading acceleration data, skipping logging and LED control\n");
        }

        gpioDelay(100); // 100 ms delay
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(LED_PIN, 0); // Turn off LED
    fclose(log_file);
    gpioTerminate();

    return 0;
}

