#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <string.h>

// LSM303DLHC I2C addresses
#define ACCEL_ADDR 0x19
#define MAG_ADDR 0x1E

// LSM303DLHC register addresses
#define ACCEL_CTRL_REG1_A 0x20
#define ACCEL_OUT_X_L_A 0x28
#define MAG_MR_REG_M 0x02
#define MAG_OUT_X_H_M 0x03

// Global variables for I2C handles and file pointer
int accel_handle = -1;
int mag_handle = -1;
FILE *log_file = NULL;

// Function prototypes
int init_accelerometer(int handle);
int init_magnetometer(int handle);
int read_accelerometer_data(int handle, float *x, float *y, float *z);
int read_magnetometer_data(int handle, float *x, float *y, float *z);
float calculate_heading(float accel_x, float accel_y, float accel_z, float mag_x, float mag_y, float mag_z);
int log_data(FILE *fp, float heading, float accel_x, float accel_y, float accel_z, float mag_x, float mag_y, float mag_z);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    if (accel_handle >= 0) {
        i2cClose(accel_handle);
    }
    if (mag_handle >= 0) {
        i2cClose(mag_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

// Initialize accelerometer
int init_accelerometer(int handle) {
    // Enable accelerometer, 50 Hz data rate
    if (i2cWriteByteData(handle, ACCEL_CTRL_REG1_A, 0x27) < 0) {
        fprintf(stderr, "Error writing to accelerometer control register.\n");
        return -1;
    }
    return 0;
}

// Initialize magnetometer
int init_magnetometer(int handle) {
    // Set magnetometer to continuous conversion mode
    if (i2cWriteByteData(handle, MAG_MR_REG_M, 0x00) < 0) {
        fprintf(stderr, "Error writing to magnetometer mode register.\n");
        return -1;
    }
    return 0;
}

// Read accelerometer data
int read_accelerometer_data(int handle, float *x, float *y, float *z) {
    char buffer[6];
    if (i2cReadI2CBlockData(handle, ACCEL_OUT_X_L_A | 0x80, buffer, 6) < 0) {
        fprintf(stderr, "Error reading accelerometer data.\n");
        return -1;
    }

    // Combine high and low bytes, convert to g
    int16_t raw_x = (int16_t)((buffer[1] << 8) | buffer[0]);
    int16_t raw_y = (int16_t)((buffer[3] << 8) | buffer[2]);
    int16_t raw_z = (int16_t)((buffer[5] << 8) | buffer[4]);

    *x = (float)raw_x / 16384.0f; // Assuming +/- 2g range
    *y = (float)raw_y / 16384.0f;
    *z = (float)raw_z / 16384.0f;

    return 0;
}

// Read magnetometer data
int read_magnetometer_data(int handle, float *x, float *y, float *z) {
    char buffer[6];
    if (i2cReadI2CBlockData(handle, MAG_OUT_X_H_M, buffer, 6) < 0) {
        fprintf(stderr, "Error reading magnetometer data.\n");
        return -1;
    }

    // Combine high and low bytes, convert to gauss
    int16_t raw_x = (int16_t)((buffer[0] << 8) | buffer[1]);
    int16_t raw_y = (int16_t)((buffer[2] << 8) | buffer[3]);
    int16_t raw_z = (int16_t)((buffer[4] << 8) | buffer[5]);

    *x = (float)raw_x / 1100.0f; // Assuming +/- 1.3 Gauss range
    *y = (float)raw_y / 1100.0f;
    *z = (float)raw_z / 1100.0f;

    return 0;
}

// Calculate tilt-compensated heading
float calculate_heading(float accel_x, float accel_y, float accel_z, float mag_x, float mag_y, float mag_z) {
    float roll = atan2(accel_y, accel_z);
    float pitch = atan2(-accel_x, sqrt(accel_y * accel_y + accel_z * accel_z));

    float cos_roll = cos(roll);
    float sin_roll = sin(roll);
    float cos_pitch = cos(pitch);
    float sin_pitch = sin(pitch);

    float x_h = mag_x * cos_pitch + mag_z * sin_pitch;
    float y_h = mag_x * sin_roll * sin_pitch + mag_y * cos_roll - mag_z * sin_roll * cos_pitch;

    float heading = atan2(y_h, x_h) * 180 / M_PI;
    if (heading < 0) {
        heading += 360;
    }
    return heading;
}

// Log data to file
int log_data(FILE *fp, float heading, float accel_x, float accel_y, float accel_z, float mag_x, float mag_y, float mag_z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f\n", timestamp, heading, accel_x, accel_y, accel_z, mag_x, mag_y, mag_z);
    fflush(fp); // Ensure data is written to file immediately
    return 0;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C handles
    accel_handle = i2cOpen(1, ACCEL_ADDR, 0);
    if (accel_handle < 0) {
        fprintf(stderr, "Error opening accelerometer I2C device: %d\n", accel_handle);
        gpioTerminate();
        return 1;
    }

    mag_handle = i2cOpen(1, MAG_ADDR, 0);
    if (mag_handle < 0) {
        fprintf(stderr, "Error opening magnetometer I2C device: %d\n", mag_handle);
        i2cClose(accel_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize sensors
    if (init_accelerometer(accel_handle) < 0) {
        fprintf(stderr, "Accelerometer initialization failed\n");
        i2cClose(accel_handle);
        i2cClose(mag_handle);
        gpioTerminate();
        return 1;
    }

    if (init_magnetometer(mag_handle) < 0) {
        fprintf(stderr, "Magnetometer initialization failed\n");
        i2cClose(accel_handle);
        i2cClose(mag_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("compass_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(accel_handle);
        i2cClose(mag_handle);
        gpioTerminate();
        return 1;
    }

    // Write CSV header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Heading,AccelX,AccelY,AccelZ,MagX,MagY,MagZ\n");
    }

    // Main loop
    float accel_x, accel_y, accel_z;
    float mag_x, mag_y, mag_z;
    float heading;

    while (1) {
        // Read sensor data
        if (read_accelerometer_data(accel_handle, &accel_x, &accel_y, &accel_z) < 0) {
            fprintf(stderr, "Error reading accelerometer data, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        if (read_magnetometer_data(mag_handle, &mag_x, &mag_y, &mag_z) < 0) {
            fprintf(stderr, "Error reading magnetometer data, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Calculate heading
        heading = calculate_heading(accel_x, accel_y, accel_z, mag_x, mag_y, mag_z);

        // Log data
        if (log_data(log_file, heading, accel_x, accel_y, accel_z, mag_x, mag_y, mag_z) < 0) {
            fprintf(stderr, "Error logging data\n");
        }

        // Wait 100 ms
        gpioDelay(100);
    }

    // Cleanup (should not reach here in normal operation due to signal handler)
    i2cClose(accel_handle);
    i2cClose(mag_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

