#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define SENSOR1_ADDR 0x68
#define SENSOR2_ADDR 0x69
#define SAMPLE_RATE_MS 10
#define SAMPLE_SIZE 2 // 16-bit samples
#define NUM_SAMPLES 100 // Number of samples to read from each sensor in a block
#define TDOA_THRESHOLD_US 500 // TDOA threshold in microseconds

// Global variables
int i2c_handle1 = -1;
int i2c_handle2 = -1;
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Structure to hold sensor data
typedef struct {
    int16_t *data;
    int index;
    int size;
} sensor_data_t;

// Function prototypes
int initialize_i2c(int bus, int addr);
int read_sensor_data(int i2c_handle, int16_t *data, int num_samples);
void process_sensor_data(sensor_data_t *sensor1, sensor_data_t *sensor2, struct timespec timestamp, FILE *log_file);
void calculate_tdoa(int16_t *sensor1_data, int16_t *sensor2_data, int num_samples, struct timespec timestamp, FILE *log_file);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Cleanup function to release resources
void cleanup() {
    if (i2c_handle1 >= 0) {
        i2cClose(i2c_handle1);
    }
    if (i2c_handle2 >= 0) {
        i2cClose(i2c_handle2);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

// Function to initialize I2C
int initialize_i2c(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C device at address 0x%02x: %s\n", addr, strerror(errno));
        return -1;
    }
    return handle;
}

// Function to read sensor data
int read_sensor_data(int i2c_handle, int16_t *data, int num_samples) {
    char buffer[num_samples * SAMPLE_SIZE];
    int bytes_read = i2cReadDevice(i2c_handle, buffer, num_samples * SAMPLE_SIZE);

    if (bytes_read != num_samples * SAMPLE_SIZE) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        return -1;
    }

    // Convert bytes to 16-bit signed integers
    for (int i = 0; i < num_samples; i++) {
        data[i] = (int16_t)((buffer[i * 2 + 1] << 8) | buffer[i * 2]);
    }

    return 0;
}

// Function to process sensor data and calculate TDOA
void process_sensor_data(sensor_data_t *sensor1, sensor_data_t *sensor2, struct timespec timestamp, FILE *log_file) {
    if (sensor1->index == sensor2->index && sensor1->index < NUM_SAMPLES) {
        calculate_tdoa(sensor1->data, sensor2->data, NUM_SAMPLES, timestamp, log_file);
        sensor1->index = 0;
        sensor2->index = 0;
    }
}

// Function to calculate TDOA
void calculate_tdoa(int16_t *sensor1_data, int16_t *sensor2_data, int num_samples, struct timespec timestamp, FILE *log_file) {
    // Simple cross-correlation (replace with a more robust algorithm for real-world use)
    int max_correlation = 0;
    int delay = 0;
    int correlation;

    for (int d = -num_samples / 2; d <= num_samples / 2; d++) {
        correlation = 0;
        for (int i = 0; i < num_samples; i++) {
            int j = i + d;
            if (j >= 0 && j < num_samples) {
                correlation += abs(sensor1_data[i] - sensor2_data[j]);
            }
        }
        if (correlation > max_correlation) {
            max_correlation = correlation;
            delay = d;
        }
    }

    // Convert delay to microseconds (approximation)
    int tdoa_us = delay * (1000000 / SAMPLE_RATE_MS); // Assuming 10ms sampling rate

    // Validate TDOA
    if (abs(tdoa_us) < TDOA_THRESHOLD_US) {
        fprintf(log_file, "%ld,%ld,%d,%d,%d\n", timestamp.tv_sec, timestamp.tv_nsec, sensor1_data[0], sensor2_data[0], tdoa_us);
        fflush(log_file); // Ensure data is written to file immediately
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen("audio_log.dat", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Initialize I2C
    i2c_handle1 = initialize_i2c(I2C_BUS, SENSOR1_ADDR);
    i2c_handle2 = initialize_i2c(I2C_BUS, SENSOR2_ADDR);

    if (i2c_handle1 < 0 || i2c_handle2 < 0) {
        fprintf(stderr, "Failed to initialize one or more I2C sensors. Exiting.\n");
        cleanup();
        return 1;
    }

    // Allocate memory for sensor data
    int16_t *sensor1_data = (int16_t *)malloc(NUM_SAMPLES * sizeof(int16_t));
    int16_t *sensor2_data = (int16_t *)malloc(NUM_SAMPLES * sizeof(int16_t));

    if (sensor1_data == NULL || sensor2_data == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        cleanup();
        return 1;
    }

    sensor_data_t sensor1 = {sensor1_data, 0, NUM_SAMPLES};
    sensor_data_t sensor2 = {sensor2_data, 0, NUM_SAMPLES};

    // Set up signal handler
    signal(SIGINT, signal_handler);

    struct timespec ts;
    int read_result1, read_result2;

    // Main loop
    while (program_running) {
        // Read sensor data
        read_result1 = read_sensor_data(i2c_handle1, sensor1_data, NUM_SAMPLES);
        read_result2 = read_sensor_data(i2c_handle2, sensor2_data, NUM_SAMPLES);

        // Get timestamp
        if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
            fprintf(stderr, "Error getting timestamp: %s\n", strerror(errno));
            continue; // Continue to the next iteration
        }

        // Process sensor data and calculate TDOA
        process_sensor_data(&sensor1, &sensor2, ts, log_file);

        // Delay for the specified sampling interval
        gpioDelay(SAMPLE_RATE_MS * 1000); // Delay in microseconds
    }

    // Free allocated memory
    free(sensor1_data);
    free(sensor2_data);

    // Cleanup and exit
    cleanup();
    return 0;
}

