#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// ADIS16488A Register Addresses
#define ADIS16488A_REG_GYRO_XOUT 0x04
#define ADIS16488A_REG_GYRO_YOUT 0x06
#define ADIS16488A_REG_GYRO_ZOUT 0x08
#define ADIS16488A_REG_ACCEL_XOUT 0x0A
#define ADIS16488A_REG_ACCEL_YOUT 0x0C
#define ADIS16488A_REG_ACCEL_ZOUT 0x0E

// Sensitivity values
#define GYRO_SENSITIVITY 0.005f  // deg/sec/LSB
#define ACCEL_SENSITIVITY 0.00025f // g/LSB

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_CE 8
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 3

// Global variables
static int spi_handle = -1;
static FILE *fp = NULL;
static volatile int running = 1;

// Function prototypes
int spi_read_register(int handle, uint8_t reg_addr, int16_t *data);
int spi_write_register(int handle, uint8_t reg_addr, int16_t data);
int read_imu_data(int handle, float *gyro_x, float *gyro_y, float *gyro_z, float *accel_x, float *accel_y, float *accel_z);
int log_data(FILE *fp, float gyro_x, float gyro_y, float gyro_z, float accel_x, float accel_y, float accel_z);
void cleanup();
void signal_handler(int signal);

// Function to read a register from the ADIS16488A
int spi_read_register(int handle, uint8_t reg_addr, int16_t *data) {
    char tx_buf[2];
    char rx_buf[2];

    tx_buf[0] = (0x00 << 7) | (reg_addr & 0x7F); // Command word: MSB=0, register address
    tx_buf[1] = 0x00; // Dummy byte for reading data

    if (spiXfer(handle, tx_buf, rx_buf, 2) != 0) {
        fprintf(stderr, "Error: SPI transfer failed in spi_read_register\n");
        return -1;
    }

    *data = (rx_buf[0] << 8) | rx_buf[1]; // Combine the two bytes into a 16-bit value
    return 0;
}

// Function to write a register in the ADIS16488A
int spi_write_register(int handle, uint8_t reg_addr, int16_t data) {
    char tx_buf[2];
    char rx_buf[2];

    tx_buf[0] = (0x80 << 7) | (reg_addr & 0x7F); // Command word: MSB=1, register address
    tx_buf[1] = data & 0xFF; // Lower byte

    if (spiXfer(handle, tx_buf, rx_buf, 2) != 0) {
        fprintf(stderr, "Error: SPI transfer failed in spi_write_register (lower byte)\n");
        return -1;
    }

    tx_buf[0] = (0x80 << 7) | (reg_addr & 0x7F); // Command word: MSB=1, register address
    tx_buf[1] = (data >> 8) & 0xFF; // Upper byte

    if (spiXfer(handle, tx_buf, rx_buf, 2) != 0) {
        fprintf(stderr, "Error: SPI transfer failed in spi_write_register (upper byte)\n");
        return -1;
    }

    return 0;
}

// Function to read IMU data
int read_imu_data(int handle, float *gyro_x, float *gyro_y, float *gyro_z, float *accel_x, float *accel_y, float *accel_z) {
    int16_t raw_gyro_x, raw_gyro_y, raw_gyro_z, raw_accel_x, raw_accel_y, raw_accel_z;

    if (spi_read_register(handle, ADIS16488A_REG_GYRO_XOUT, &raw_gyro_x) != 0) return -1;
    if (spi_read_register(handle, ADIS16488A_REG_GYRO_YOUT, &raw_gyro_y) != 0) return -1;
    if (spi_read_register(handle, ADIS16488A_REG_GYRO_ZOUT, &raw_gyro_z) != 0) return -1;
    if (spi_read_register(handle, ADIS16488A_REG_ACCEL_XOUT, &raw_accel_x) != 0) return -1;
    if (spi_read_register(handle, ADIS16488A_REG_ACCEL_YOUT, &raw_accel_y) != 0) return -1;
    if (spi_read_register(handle, ADIS16488A_REG_ACCEL_ZOUT, &raw_accel_z) != 0) return -1;

    *gyro_x = (float)raw_gyro_x * GYRO_SENSITIVITY;
    *gyro_y = (float)raw_gyro_y * GYRO_SENSITIVITY;
    *gyro_z = (float)raw_gyro_z * GYRO_SENSITIVITY;
    *accel_x = (float)raw_accel_x * ACCEL_SENSITIVITY;
    *accel_y = (float)raw_accel_y * ACCEL_SENSITIVITY;
    *accel_z = (float)raw_accel_z * ACCEL_SENSITIVITY;

    return 0;
}

// Function to log data to a CSV file
int log_data(FILE *fp, float gyro_x, float gyro_y, float gyro_z, float accel_x, float accel_y, float accel_z) {
    struct timespec ts;
