int spi_read_register(int handle, uint8_t reg_addr, int16_t *data) {
    char tx_buf[2];
    char rx_buf[2];

    tx_buf[0] = (0x00 << 7) | (reg_addr & 0x7F); // Command word: MSB=0, register address
    tx_buf[1] = 0x00; // Dummy byte for reading data

    if (spiXfer(handle, tx_buf, rx_buf, 2) != 0) {
        fprintf(stderr, "Error: SPI transfer failed in spi_read_register\n");
        return -1;
    }

    *data = (rx_buf[0] << 8) | rx_buf[1]; // Combine the two bytes into a 16-bit value
    return 0;
