#include <errno.h>
#include <string.h>

// MPU-6886 I2C address
#define MPU6886_ADDR 0x68

// MPU-6886 register addresses
#define ACCEL_XOUT_H 0x3B
#define GYRO_XOUT_H 0x43

// I2C bus
#define I2C_BUS 1

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler for Ctrl+C
void sigint_handler(int signal)
{
    terminate = 1;
}

// Function to read a 16-bit value from the IMU
int16_t read_imu_value(int handle, uint8_t reg)
{
    char buf[2];
    int result;

    result = i2cReadI2CBlockData(handle, reg, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading register 0x%02X: %s\n", reg, strerror(errno));
        return 0; // Return 0 on error
    }

    return (int16_t)((buf[0] << 8) | buf[1]);
}

int main()
{
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, MPU6886_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, sigint_handler);

    // Main loop
    while (!terminate) {
        int16_t accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z;

        // Read accelerometer values
        accel_x = read_imu_value(i2c_handle, ACCEL_XOUT_H);
        accel_y = read_imu_value(i2c_handle, ACCEL_XOUT_H + 2);
        accel_z = read_imu_value(i2c_handle, ACCEL_XOUT_H + 4);

        // Read gyroscope values
        gyro_x = read_imu_value(i2c_handle, GYRO_XOUT_H);
        gyro_y = read_imu_value(i2c_handle, GYRO_XOUT_H + 2);
        gyro_z = read_imu_value(i2c_handle, GYRO_XOUT_H + 4);

        // Print the values
        printf("Accel: X=%6d, Y=%6d, Z=%6d  Gyro: X=%6d, Y=%6d, Z=%6d\n",
               accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z);

        // Delay for 50ms
        gpioDelay(50000);
    }

    // Close I2C bus
    i2cClose(i2c_handle);

    // Terminate pigpio
    gpioTerminate();

    printf("Program terminated gracefully.\n");
    return 0;
}

