#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define ADXL345_ADDR 0x53
#define ADXL345_REG_POWER_CTL 0x2D
#define ADXL345_REG_DATAX0 0x32
#define ADXL345_REG_BW_RATE 0x2C
#define ADXL345_REG_DATA_FORMAT 0x31
#define ADXL345_REG_ID 0x00
#define LED_GPIO 17
#define IMPACT_THRESHOLD 2.5
#define LED_ON_TIME 500 // milliseconds

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold accelerometer data
typedef struct {
    float x;
    float y;
    float z;
} accelerometer_data_t;

// Function prototypes
int initialize_i2c();
int initialize_adxl345();
accelerometer_data_t read_accelerometer_data();
float calculate_magnitude(accelerometer_data_t data);
void control_led(int on);
void log_impact(accelerometer_data_t data, float magnitude);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Signal received, cleaning up...\n");
}

// Initialize I2C
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ADXL345_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Initialize ADXL345
int initialize_adxl345() {
    // Verify device ID
    int device_id = i2cReadByteData(i2c_handle, ADXL345_REG_ID);
    if (device_id < 0) {
        fprintf(stderr, "Error reading device ID: %d\n", device_id);
        return -1;
    }
    if (device_id != 0xE5) {
        fprintf(stderr, "Incorrect device ID: 0x%02X\n", device_id);
        return -1;
    }

    // Set data format to full resolution, ±2g range
    int status = i2cWriteByteData(i2c_handle, ADXL345_REG_DATA_FORMAT, 0x0B);
    if (status < 0) {
        fprintf(stderr, "Error writing to data format register: %d\n", status);
        return -1;
    }

    // Set bandwidth rate to 100 Hz
    status = i2cWriteByteData(i2c_handle, ADXL345_REG_BW_RATE, 0x0A);
    if (status < 0) {
        fprintf(stderr, "Error writing to bandwidth rate register: %d\n", status);
        return -1;
    }

    // Enable measurement mode
    status = i2cWriteByteData(i2c_handle, ADXL345_REG_POWER_CTL, 0x08);
    if (status < 0) {
        fprintf(stderr, "Error writing to power control register: %d\n", status);
        return -1;
    }

    return 0;
}

// Read accelerometer data
accelerometer_data_t read_accelerometer_data() {
    accelerometer_data_t data;
    char raw_data[6];

    int status = i2cReadI2CBlockData(i2c_handle, ADXL345_REG_DATAX0, raw_data, 6);
    if (status < 0) {
        fprintf(stderr, "Error reading accelerometer data: %d\n", status);
        data.x = 0.0; data.y = 0.0; data.z = 0.0; // Return zeroed data on error
        return data;
    }

    // Combine high and low bytes, convert to g
    data.x = (float)((int16_t)((raw_data[1] << 8) | raw_data[0])) / 256.0;
    data.y = (float)((int16_t)((raw_data[3] << 8) | raw_data[2])) / 256.0;
    data.z = (float)((int16_t)((raw_data[5] << 8) | raw_data[4])) / 256.0;

    return data;
}

// Calculate magnitude of acceleration vector
float calculate_magnitude(accelerometer_data_t data) {
    return sqrt(data.x * data.x + data.y * data.y + data.z * data.z);
}

// Control LED
void control_led(int on) {
    gpioWrite(LED_GPIO, on);
    if (on) {
        gpioDelay(LED_ON_TIME * 1000); // Delay in microseconds
        gpioWrite(LED_GPIO, 0);
    }
}

// Log impact event
void log_impact(accelerometer_data_t data, float magnitude) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, X: %.3f g, Y: %.3f g, Z: %.3f g, Magnitude: %.3f g\n",
            timestamp, data.x, data.y, data.z, magnitude);
    fflush(log_file); // Ensure data is written to file immediately
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up resources...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(LED_GPIO, 0); // Turn off LED
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Open log file
    log_file = fopen("impact_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Initialize ADXL345
    if (initialize_adxl345() != 0) {
        cleanup();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("ADXL345 impact detection started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        accelerometer_data_t data = read_accelerometer_data();
        float magnitude = calculate_magnitude(data);

        if (magnitude > IMPACT_THRESHOLD) {
            printf("Impact detected! Magnitude: %.3f g\n", magnitude);
            control_led(1);
            log_impact(data, magnitude);
        }

        gpioDelay(10000); // 10 ms delay
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

