#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// ICM-20602 I2C address
#define ICM20602_ADDR 0x68

// ICM-20602 register addresses
#define ACCEL_XOUT_H 0x3B
#define GYRO_XOUT_H 0x43

// Scaling factors (adjust based on your configuration)
#define ACCEL_SCALE 16384.0f // For +/- 2g range
#define GYRO_SCALE 131.0f    // For +/- 250 dps range

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float accel_x, accel_y, accel_z;
    float gyro_x, gyro_y, gyro_z;
} sensor_data_t;

// Function prototypes
int init_i2c();
int read_sensor_data(sensor_data_t *data);
int log_data(const sensor_data_t *data);
void signal_handler(int signal);
void cleanup();

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(1, ICM20602_ADDR, 0); // Bus 1, address 0x68, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read sensor data from ICM-20602
int read_sensor_data(sensor_data_t *data) {
    char buf[12];
    int result;

    result = i2cReadI2CBlockData(i2c_handle, ACCEL_XOUT_H, buf, 12);
    if (result != 12) {
        fprintf(stderr, "Error reading sensor data: %d\n", result);
        return -1;
    }

    // Combine high and low bytes for accelerometer
    int16_t accel_x = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t accel_y = (int16_t)((buf[2] << 8) | buf[3]);
    int16_t accel_z = (int16_t)((buf[4] << 8) | buf[5]);

    // Combine high and low bytes for gyroscope
    int16_t gyro_x = (int16_t)((buf[6] << 8) | buf[7]);
    int16_t gyro_y = (int16_t)((buf[8] << 8) | buf[9]);
    int16_t gyro_z = (int16_t)((buf[10] << 8) | buf[11]);

    // Convert to g and degrees per second
    data->accel_x = (float)accel_x / ACCEL_SCALE;
    data->accel_y = (float)accel_y / ACCEL_SCALE;
    data->accel_z = (float)accel_z / ACCEL_SCALE;
    data->gyro_x = (float)gyro_x / GYRO_SCALE;
    data->gyro_y = (float)gyro_y / GYRO_SCALE;
    data->gyro_z = (float)gyro_z / GYRO_SCALE;

    return 0;
}

