#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/select.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

// ADXL345 I2C address
#define ADXL345_ADDR 0x53

// ADXL345 registers
#define ADXL345_REG_DEVID 0x00
#define ADXL345_REG_POWER_CTL 0x2D
#define ADXL345_REG_INT_ENABLE 0x2E
#define ADXL345_REG_INT_MAP 0x2F
#define ADXL345_REG_DATAX0 0x32
#define ADXL345_REG_DATAX1 0x33
#define ADXL345_REG_DATAY0 0x34
#define ADXL345_REG_DATAY1 0x35
#define ADXL345_REG_DATAZ0 0x36
#define ADXL345_REG_DATAZ1 0x37
#define ADXL345_REG_BW_RATE 0x2C
#define ADXL345_REG_FREEFALL_ELE 0x1D
#define ADXL345_REG_FREEFALL_EAV 0x1E

// GPIO pin for ADXL345 INT1
#define ADXL345_INT1_GPIO 17

// Free-fall threshold (in g)
#define FREEFALL_THRESHOLD 0.3

// Free-fall time (in seconds)
#define FREEFALL_TIME 0.2

// Global variables
int i2c_fd;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Structure to hold accelerometer data
typedef struct {
    float x;
    float y;
    float z;
} accelerometer_data_t;

// Function prototypes
int adxl345_init();
int adxl345_read_data(accelerometer_data_t *data);
int adxl345_enable_interrupt();
int adxl345_disable_interrupt();
void interrupt_handler(int gpio, int level, uint32_t tick);
void signal_handler(int signal);
char* get_timestamp();

// Function to get the current timestamp
char* get_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    struct timespec ts;
    static char buffer[30];

    clock_gettime(CLOCK_REALTIME, &ts);
    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", timeinfo);
    snprintf(buffer + strlen(buffer), sizeof(buffer) - strlen(buffer), ".%03ld", ts.tv_nsec / 1000000);

    return buffer;
}

// Function to initialize the ADXL345
int adxl345_init() {
    uint8_t devid;
    int retries = 3;

    // Check device ID
    while (retries > 0) {
        if (i2cReadByteData(i2c_fd, ADXL345_REG_DEVID) == 0xE5) {
            break;
        } else {
            fprintf(stderr, "Error: ADXL345 not found. Retrying...\n");
            retries--;
            gpioDelay(100000); // 100ms delay
        }
    }

    if (retries == 0) {
        fprintf(stderr, "Error: ADXL345 not found after multiple retries.\n");
        return -1;
    }

    // Set data rate to 100 Hz
    if (i2cWriteByteData(i2c_fd, ADXL345_REG_BW_RATE, 0x0A) < 0) {
        perror("Error writing to BW_RATE register");
        return -1;
    }

    // Set free-fall threshold
    if (i2cWriteByteData(i2c_fd, ADXL345_REG_FREEFALL_ELE, (uint8_t)(FREEFALL_THRESHOLD * 100)) < 0) {
        perror("Error writing to FREEFALL_ELE register");
        return -1;
    }

    // Set free-fall time
    if (i2cWriteByteData(i2c_fd, ADXL345_REG_FREEFALL_EAV, (uint8_t)(FREEFALL_TIME * 100)) < 0) {
        perror("Error writing to FREEFALL_EAV register");
        return -1;
    }

    // Set power control to measure mode
    if (i2cWriteByteData(i2c_fd, ADXL345_REG_POWER_CTL, 0x08) < 0) {
        perror("Error writing to POWER_CTL register");
        return -1;
    }

    // Enable free-fall interrupt
    if (adxl345_enable_interrupt() < 0) {
        fprintf(stderr, "Error enabling interrupt.\n");
        return -1;
    }

    return 0;
}

// Function to read accelerometer data
int adxl345_read_data(accelerometer_data_t *data) {
    uint8_t x0, x1, y0, y1, z0, z1;
    int16_t x, y, z;

    x0 = i2cReadByteData(i2c_fd, ADXL345_REG_DATAX0);
    x1 = i2cReadByteData(i2c_fd, ADXL345_REG_DATAX1);
    y0 = i2cReadByteData(i2c_fd, ADXL345_REG_DATAY0);
    y1 = i2cReadByteData(i2c_fd, ADXL345_REG_DATAY1);
    z0 = i2cReadByteData(i2c_fd, ADXL345_REG_DATAZ0);
    z1 = i2cReadByteData(i2c_fd, ADXL345_REG_DATAZ1);

    if (x0 == -1 || x1 == -1 || y0 == -1 || y1 == -1 || z0 == -1 || z1 == -1) {
        perror("Error reading accelerometer data");
        return -1;
    }

    x = (int16_t)((x1 << 8) | x0);
    y = (int16_t)((y1 << 8) | y0);
    z = (int16_t)((z1 << 8) | z0);

    // Convert to g (assuming +/- 2g range and 10-bit resolution)
    data->x = (float)x / 256.0;
    data->y = (float)y / 256.0;
    data->z = (float)z / 256.0;

    return 0;
}

// Function to enable the free-fall interrupt
int adxl345_enable_interrupt() {
    // Enable free-fall interrupt
    if (i2cWriteByteData(i2c_fd, ADXL345_REG_INT_ENABLE, 0x40) < 0) {
        perror("Error writing to INT_ENABLE register");
        return -1;
    }

    // Map free-fall interrupt to INT1 pin
    if (i2cWriteByteData(i2c_fd, ADXL345_REG_INT_MAP, 0x40) < 0) {
        perror("Error writing to INT_MAP register");
        return -1;
    }

    return 0;
}

// Function to disable the free-fall interrupt
int adxl345_disable_interrupt() {
    // Disable free-fall interrupt
    if (i2cWriteByteData(i2c_fd, ADXL345_REG_INT_ENABLE, 0x00) < 0) {
        perror("Error writing to INT_ENABLE register");
        return -1;
    }

    return 0;
}

// Interrupt handler function
void interrupt_handler(int gpio, int level, uint32_t tick) {
    accelerometer_data_t data;
    char *timestamp;

    if (adxl345_read_data(&data) == 0) {
        timestamp = get_timestamp();
        fprintf(log_file, "%s,%.3f,%.3f,%.3f\n", timestamp, data.x, data.y, data.z);
        fflush(log_file);
    } else {
        fprintf(stderr, "Error reading data in interrupt handler.\n");
    }
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    program_running = 0;

    // Disable interrupt
    adxl345_disable_interrupt();

    // Close I2C device
    close(i2c_fd);

    // Release GPIO pin
    gpioSetMode(ADXL345_INT1_GPIO, PI_INPUT); // Set back to input
    gpioSetISRFuncEx(ADXL345_INT1_GPIO, RISING_EDGE, 0, NULL, NULL); // Disable ISR

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C device");
        gpioTerminate();
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, ADXL345_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Initialize ADXL345
    if (adxl345_init() < 0) {
        fprintf(stderr, "ADXL345 initialization failed\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("freefall_log.csv", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Write header row if the file is new
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,X,Y,Z\n");
    }
    fflush(log_file);

    // Set GPIO pin as input
    gpioSetMode(ADXL345_INT1_GPIO, PI_INPUT);

    // Set interrupt handler
    if (gpioSetISRFuncEx(ADXL345_INT1_GPIO, RISING_EDGE, 0, interrupt_handler, NULL) != 0) {
        fprintf(stderr, "Error setting interrupt handler\n");
        fclose(log_file);
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Free-fall detection started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Poll the I2C device file descriptor using select()
        fd_set readfds;
        FD_ZERO(&readfds);
        FD_SET(i2c_fd, &readfds);

        struct timeval timeout;
        timeout.tv_sec = 1; // Timeout after 1 second
        timeout.tv_usec = 0;

        int select_result = select(i2c_fd + 1, &readfds, NULL, NULL, &timeout);

        if (select_result < 0) {
            perror("Error in select()");
            break;
        } else if (select_result == 0) {
            // Timeout occurred, do nothing
        } else {
            // Data is available on the I2C bus, but we don't need to read it here.
            // The interrupt handler will take care of it.
        }
    }

    return 0;
}

