        fprintf(stderr, "Error reading data in interrupt handler.\n");
    }
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    program_running = 0;

    // Disable interrupt
    adxl345_disable_interrupt();

    // Close I2C device
    close(i2c_fd);

    // Release GPIO pin
    gpioSetMode(ADXL345_INT1_GPIO, PI_INPUT); // Set back to input
    gpioSetISRFuncEx(ADXL345_INT1_GPIO, RISING_EDGE, 0, NULL, NULL); // Disable ISR

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C device");
        gpioTerminate();
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, ADXL345_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Initialize ADXL345
    if (adxl345_init() < 0) {
        fprintf(stderr, "ADXL345 initialization failed\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("freefall_log.csv", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Write header row if the file is new
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,X,Y,Z\n");
    }
    fflush(log_file);

    // Set GPIO pin as input
    gpioSetMode(ADXL345_INT1_GPIO, PI_INPUT);

    // Set interrupt handler
    if (gpioSetISRFuncEx(ADXL345_INT1_GPIO, RISING_EDGE, 0, interrupt_handler, NULL) != 0) {
        fprintf(stderr, "Error setting interrupt handler\n");
        fclose(log_file);
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Free-fall detection started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Poll the I2C device file descriptor using select()
        fd_set readfds;
        FD_ZERO(&readfds);
        FD_SET(i2c_fd, &readfds);

        struct timeval timeout;
        timeout.tv_sec = 1; // Timeout after 1 second
        timeout.tv_usec = 0;

        int select_result = select(i2c_fd + 1, &readfds, NULL, NULL, &timeout);

        if (select_result < 0) {
            perror("Error in select()");
            break;
        } else if (select_result == 0) {
            // Timeout occurred, do nothing
        } else {
            // Data is available on the I2C bus, but we don't need to read it here.
            // The interrupt handler will take care of it.
        }
    }

    return 0;
}

