#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// LSM6DSR I2C address
#define LSM6DSR_ADDR 0x6A

// LSM6DSR register addresses
#define CTRL1_XL 0x10
#define CTRL2_G 0x11
#define OUTX_L_G 0x22
#define OUTX_L_XL 0x28

// Scaling factors
#define ACCEL_SCALE 0.000061 // 2g range, 16-bit
#define GYRO_SCALE 0.00875  // 250dps range, 16-bit

// Fall detection thresholds
#define FREEFALL_THRESHOLD 0.2
#define IMPACT_THRESHOLD 2.5

// Fall detection window (seconds)
#define FALL_WINDOW 1.0

// Data rate
#define DATA_RATE 104 // Hz

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    double accel_x;
    double accel_y;
    double accel_z;
    double gyro_x;
    double gyro_y;
    double gyro_z;
} sensor_data_t;

// Structure to hold fall detection state
typedef struct {
    time_t freefall_start_time;
    int in_freefall;
    int in_impact;
} fall_detection_state_t;

// Function prototypes
int init_i2c();
int config_sensor();
sensor_data_t read_sensor_data();
double calculate_acceleration_magnitude(sensor_data_t data);
void log_data(sensor_data_t data);
void detect_fall(sensor_data_t data, fall_detection_state_t *state);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(1, LSM6DSR_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Configure the LSM6DSR sensor
int config_sensor() {
    // Configure accelerometer: ±2g range, 104 Hz ODR
    if (i2cWriteByteData(i2c_handle, CTRL1_XL, 0x80) < 0) {
        fprintf(stderr, "Error writing to CTRL1_XL\n");
        return -1;
    }

    // Configure gyroscope: ±250 dps range, 104 Hz ODR
    if (i2cWriteByteData(i2c_handle, CTRL2_G, 0x80) < 0) {
        fprintf(stderr, "Error writing to CTRL2_G\n");
        return -1;
    }

    return 0;
}

// Read raw sensor data from the LSM6DSR
sensor_data_t read_sensor_data() {
    sensor_data_t data;
    char buffer[12];

    // Read accelerometer and gyroscope data
    if (i2cReadI2CBlockData(i2c_handle, OUTX_L_G, buffer, 12) < 0) {
        fprintf(stderr, "Error reading sensor data\n");
        data.accel_x = 0.0;
        data.accel_y = 0.0;
        data.accel_z = 0.0;
        data.gyro_x = 0.0;
        data.gyro_y = 0.0;
        data.gyro_z = 0.0;
        return data;
    }

    // Combine high and low bytes for accelerometer data
    int16_t raw_accel_x = (int16_t)((buffer[1] << 8) | buffer[0]);
    int16_t raw_accel_y = (int16_t)((buffer[3] << 8) | buffer[2]);
    int16_t raw_accel_z = (int16_t)((buffer[5] << 8) | buffer[4]);

    // Combine high and low bytes for gyroscope data
    int16_t raw_gyro_x = (int16_t)((buffer[7] << 8) | buffer[6]);
    int16_t raw_gyro_y = (int16_t)((buffer[9] << 8) | buffer[8]);
    int16_t raw_gyro_z = (int16_t)((buffer[11] << 8) | buffer[10]);

    // Convert raw data to g and dps
    data.accel_x = (double)raw_accel_x * ACCEL_SCALE;
    data.accel_y = (double)raw_accel_y * ACCEL_SCALE;
    data.accel_z = (double)raw_accel_z * ACCEL_SCALE;
    data.gyro_x = (double)raw_gyro_x * GYRO_SCALE;
    data.gyro_y = (double)raw_gyro_y * GYRO_SCALE;
    data.gyro_z = (double)raw_gyro_z * GYRO_SCALE;

    return data;
}

// Calculate the magnitude of the acceleration vector
double calculate_acceleration_magnitude(sensor_data_t data) {
    return sqrt(data.accel_x * data.accel_x + data.accel_y * data.accel_y + data.accel_z * data.accel_z);
}

// Log sensor data to a CSV file
void log_data(sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.6f,%.6f,%.6f,%.6f,%.6f,%.6f\n",
            timestamp, data.accel_x, data.accel_y, data.accel_z, data.gyro_x, data.gyro_y, data.gyro_z);
    fflush(log_file);
}

// Detect fall events
void detect_fall(sensor_data_t data, fall_detection_state_t *state) {
    double magnitude = calculate_acceleration_magnitude(data);

    time_t now = time(NULL);

    if (magnitude < FREEFALL_THRESHOLD && !state->in_freefall) {
        state->freefall_start_time = now;
        state->in_freefall = 1;
        printf("Freefall detected\n");
    } else if (magnitude > IMPACT_THRESHOLD && state->in_freefall) {
        if (difftime(now, state->freefall_start_time) <= FALL_WINDOW) {
            state->in_impact = 1;
            printf("Impact detected\n");
        }
        state->in_freefall = 0;
    } else if (magnitude > FREEFALL_THRESHOLD) {
        state->in_freefall = 0;
    }

    if (state->in_impact) {
        time_t impact_end_time = now + 1; // Impact lasts for 1 second
        if (difftime(now, state->freefall_start_time) >= FALL_WINDOW) {
            state->in_impact = 0;
            printf("Fall detected and logged\n");
        }
    }
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Configure the sensor
    if (config_sensor() != 0) {
        cleanup();
        return 1;
    }

    // Open the log file
    log_file = fopen("motion_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return 1;
    }

    // Write header to log file
    fprintf(log_file, "Timestamp,Accel_X,Accel_Y,Accel_Z,Gyro_X,Gyro_Y,Gyro_Z\n");

    fall_detection_state_t fall_state = {0, 0, 0};

    // Main loop
    while (!terminate) {
        sensor_data_t data = read_sensor_data();
        log_data(data);
        detect_fall(data, &fall_state);
        gpioDelay(1000000 / DATA_RATE); // Delay to achieve 104 Hz data rate
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

