#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// ADIS16266 Register Addresses
#define ADIS16266_WHO_AM_I 0x02
#define ADIS16266_GYRO_OUT 0x04

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_CE 8 // GPIO8 (BCM)
#define SPI_MODE 3 // CPOL=1, CPHA=1
#define SPI_SPEED 1000000 // 1 MHz

// Global Variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function Prototypes
int spi_read_register(int handle, uint8_t reg_addr, int16_t *data);
int spi_write_register(int handle, uint8_t reg_addr, int16_t data);
int verify_who_am_i(int handle);
float convert_to_degrees_per_second(int16_t raw_value);
void log_data(FILE *fp, float angular_rate);
void signal_handler(int signal);

// SPI Read Register Function
int spi_read_register(int handle, uint8_t reg_addr, int16_t *data) {
    char tx_buf[2];
    char rx_buf[2];

    // Set MSB to 1 for read operation
    tx_buf[0] = reg_addr | 0x80;
    tx_buf[1] = 0x00; // Dummy byte

    if (spiXfer(handle, tx_buf, rx_buf, 2) != 0) {
        fprintf(stderr, "Error: SPI read failed for register 0x%02X\n", reg_addr);
        return -1;
    }

    *data = (rx_buf[0] << 8) | rx_buf[1];
    return 0;
}

// SPI Write Register Function
int spi_write_register(int handle, uint8_t reg_addr, int16_t data) {
    char tx_buf[2];
    char rx_buf[2];

    tx_buf[0] = reg_addr & 0x7F; // Clear MSB for write operation
    tx_buf[1] = data & 0xFF; //LSB

    if (spiXfer(handle, tx_buf, rx_buf, 2) != 0) {
        fprintf(stderr, "Error: SPI write failed for register 0x%02X\n", reg_addr);
        return -1;
    }

    tx_buf[0] = (reg_addr & 0x7F) + 1; // Increment address for second byte
    tx_buf[1] = (data >> 8) & 0xFF; //MSB

    if (spiXfer(handle, tx_buf, rx_buf, 2) != 0) {
        fprintf(stderr, "Error: SPI write failed for register 0x%02X\n", reg_addr);
        return -1;
    }

    return 0;
}

// Verify WHO_AM_I Register Function
int verify_who_am_i(int handle) {
    int16_t who_am_i;
    if (spi_read_register(handle, ADIS16266_WHO_AM_I, &who_am_i) != 0) {
        fprintf(stderr, "Error: Failed to read WHO_AM_I register\n");
        return -1;
    }

    if (who_am_i != 0x4052) {
        fprintf(stderr, "Error: WHO_AM_I value mismatch. Expected 0x4052, got 0x%04X\n", who_am_i);
        return -1;
    }

    printf("WHO_AM_I register value: 0x%04X (Verified)\n", who_am_i);
    return 0;
}

// Convert Raw Value to Degrees per Second
float convert_to_degrees_per_second(int16_t raw_value) {
    return raw_value * 0.0305;
}

// Log Data to CSV File
void log_data(FILE *fp, float angular_rate) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s,%.4f\n", timestamp, angular_rate);
    fflush(fp); // Ensure data is written to file immediately
}

// Signal Handler Function
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Verify WHO_AM_I register
    if (verify_who_am_i(spi_handle) != 0) {
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file in append mode
    log_file = fopen("gyro_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open gyro_log.csv\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write header to log file if it's a new file
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Angular Rate (deg/s)\n");
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        int16_t raw_angular_rate;
        if (spi_read_register(spi_handle, ADIS16266_GYRO_OUT, &raw_angular_rate) != 0) {
            fprintf(stderr, "Error: Failed to read angular rate\n");
            break; // Exit loop on error
        }

        float angular_rate = convert_to_degrees_per_second(raw_angular_rate);
        log_data(log_file, angular_rate);

        gpioDelay(10); // 10 ms delay
    }

    // Cleanup
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

