#include <time.h>
#include <signal.h>
#include <string.h>

#define GPIO_PIN 17
#define LOG_FILE "flame_events.log"

volatile sig_atomic_t program_running = 1; // Flag to control the main loop
FILE *log_file = NULL;

// Function to handle SIGINT (Ctrl+C)
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to get the current timestamp as a string
char* get_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    static char timestamp[20]; //YYYY-MM-DD HH:MM:SS\0

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    return timestamp;
}

// Function to log an event to the file
int log_event(const char *message) {
    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }

    char *timestamp = get_timestamp();
    fprintf(log_file, "%s - %s\n", timestamp, message);
    fflush(log_file); // Ensure the log is written immediately
    return 0;
}

// Function to read the flame sensor
int read_flame_sensor() {
    int value = gpioRead(GPIO_PIN);
    if (value == PI_BAD_GPIO) {
        fprintf(stderr, "Error: Invalid GPIO pin.\n");
        return -1;
    } else if (value == PI_INIT_FAILED) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }
    return value;
}

int main() {
    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    // Set GPIO17 as an input with pull-up resistor
    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP);

    // Open the log file in append mode
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file %s.\n", LOG_FILE);
        gpioTerminate();
        return 1;
    }

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        int sensor_value = read_flame_sensor();
        if (sensor_value == 0) { // Flame detected (LOW)
            if (log_event("Flame detected: YES") == 0) {
                printf("FLAME DETECTED!\n");
            } else {
                fprintf(stderr, "Error: Failed to log flame detection.\n");
            }
        } else if (sensor_value == 1) { // No flame (HIGH)
            if (log_event("Flame detected: NO") != 0) {
                fprintf(stderr, "Error: Failed to log no flame.\n");
            }
        } else {
            fprintf(stderr, "Error: Failed to read sensor value.\n");
        }

        gpioDelay(500); // Wait 500ms
    }

    // Cleanup
    printf("Cleaning up...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

