#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins for the Hall-Effect sensors
#define HALL_SENSOR_1 17
#define HALL_SENSOR_2 27

// Define the log file name
#define LOG_FILE "conveyor_log.txt"

// Global variables
FILE *log_file = NULL;
int running = 1;

// Function prototypes
int read_sensor(int gpio_pin);
int log_sensor_data(FILE *fp, int sensor1_state, int sensor2_state);
void halt_conveyor();
void signal_handler(int signal);

// Function to read the state of a Hall-Effect sensor
int read_sensor(int gpio_pin) {
    int state = gpioRead(gpio_pin);
    if (state < 0) {
        fprintf(stderr, "Error reading GPIO %d: %d\n", gpio_pin, state);
        return -1; // Indicate an error
    }
    return state;
}

// Function to log sensor data to a file
int log_sensor_data(FILE *fp, int sensor1_state, int sensor2_state) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));
    snprintf(timestamp + strlen(timestamp), sizeof(timestamp) - strlen(timestamp), ".%03ld", ts.tv_nsec / 1000000);

    if (fprintf(fp, "%s Sensor1: %d, Sensor2: %d\n", timestamp, sensor1_state, sensor2_state) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        return -1; // Indicate an error
    }
    fflush(fp); // Ensure data is written to disk immediately
    return 0;
}

// Function to simulate halting the conveyor
void halt_conveyor() {
    printf("Conveyor Halted!\n");
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs with pull-up resistors
    gpioSetMode(HALL_SENSOR_1, PI_INPUT);
    gpioSetPullUpDown(HALL_SENSOR_1, PI_PUD_UP);
    gpioSetMode(HALL_SENSOR_2, PI_INPUT);
    gpioSetPullUpDown(HALL_SENSOR_2, PI_PUD_UP);

    // Open the log file in append mode
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        // Read sensor states
        int sensor1_state = read_sensor(HALL_SENSOR_1);
        int sensor2_state = read_sensor(HALL_SENSOR_2);

        // Check for errors during sensor reading
        if (sensor1_state == -1 || sensor2_state == -1) {
            fprintf(stderr, "Error reading sensors, exiting...\n");
            break;
        }

        // Log sensor data
        if (log_sensor_data(log_file, sensor1_state, sensor2_state) != 0) {
            fprintf(stderr, "Error logging data, exiting...\n");
            break;
        }

        // Check if both sensors are active
        if (sensor1_state == 1 && sensor2_state == 1) {
            halt_conveyor();
        }

        // Delay for 50 milliseconds
        gpioDelay(50000); // 50 milliseconds
    }

    // Close the log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

