#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

// MMA8452Q I2C address
#define MMA8452Q_ADDR 0x1D

// MMA8452Q registers
#define MMA8452Q_REG_WHO_AM_I 0x0D
#define MMA8452Q_REG_CTRL_REG1 0x2A
#define MMA8452Q_REG_OUT_X_MSB 0x01

// Data rate definitions
#define MMA8452Q_DATA_RATE_100HZ 0x0A

// File to log tilt events
#define LOG_FILE "fall_log.txt"

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int i2c_read_reg(int fd, uint8_t reg);
int i2c_write_reg(int fd, uint8_t reg, uint8_t value);
int init_mma8452q(int fd);
int read_accelerometer_data(int fd, int16_t *x, int16_t *y, int16_t *z);
double calculate_tilt(int16_t x, int16_t y, int16_t z);
void log_tilt_event(int16_t x, int16_t y, int16_t z);
void signal_handler(int signal);

// I2C read function
int i2c_read_reg(int fd, uint8_t reg) {
    uint8_t buf[1];
    buf[0] = reg;
    if (write(fd, buf, 1) != 1) {
        perror("I2C write (register select) failed");
        return -1;
    }
    if (read(fd, buf, 1) != 1) {
        perror("I2C read failed");
        return -1;
    }
    return buf[0];
}

// I2C write function
int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

// Initialize MMA8452Q
int init_mma8452q(int fd) {
    int who_am_i = i2c_read_reg(fd, MMA8452Q_REG_WHO_AM_I);
    if (who_am_i != 0x2A) {
        fprintf(stderr, "Error: Incorrect WHO_AM_I value: 0x%02X\n", who_am_i);
        return -1;
    }

    // Set to standby mode
    if (i2c_write_reg(fd, MMA8452Q_REG_CTRL_REG1, 0x00) != 0) {
        return -1;
    }

    // Set data rate to 100 Hz
    if (i2c_write_reg(fd, MMA8452Q_REG_CTRL_REG1, MMA8452Q_DATA_RATE_100HZ | 0x01) != 0) {
        return -1;
    }

    return 0;
}

// Read accelerometer data
int read_accelerometer_data(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buf[6];

    if (i2c_read_reg(fd, MMA8452Q_REG_OUT_X_MSB) != 0x01) {
        return -1;
    }

    if (read(fd, buf, 6) != 6) {
        perror("I2C read (accelerometer data) failed");
        return -1;
    }

    *x = ((int16_t)buf[0] << 8 | buf[1]) >> 4;
    *y = ((int16_t)buf[2] << 8 | buf[3]) >> 4;
    *z = ((int16_t)buf[4] << 8 | buf[5]) >> 4;

    return 0;
}

// Calculate tilt angle
double calculate_tilt(int16_t x, int16_t y, int16_t z) {
    double x_g = (double)x / 2048.0; // Assuming +/- 2g range
    double y_g = (double)y / 2048.0;
    double z_g = (double)z / 2048.0;

    double tilt = atan2(y_g, sqrt(x_g * x_g + z_g * z_g)) * 180 / M_PI;
    return tilt;
}

// Log tilt event
void log_tilt_event(int16_t x, int16_t y, int16_t z) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, %d, %d, %d\n", timestamp, x, y, z);
    fflush(log_file);
}

// Signal handler
void signal_handler(int signal) {
    program_running = 0;
    fprintf(stderr, "Caught signal %d, exiting...\n", signal);
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, MMA8452Q_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Initialize MMA8452Q
    if (init_mma8452q(i2c_fd) != 0) {
        fprintf(stderr, "Failed to initialize MMA8452Q\n");
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        return 1;
    }

    int16_t x, y, z;
    double tilt;

    // Main loop
    while (program_running) {
        if (read_accelerometer_data(i2c_fd, &x, &y, &z) == 0) {
            tilt = calculate_tilt(x, y, z);
            if (fabs(tilt) > 45.0) {
                log_tilt_event(x, y, z);
            }
        } else {
            fprintf(stderr, "Failed to read accelerometer data\n");
        }

        usleep(10000); // 10 ms delay
    }

    // Close I2C device and log file
    close(i2c_fd);
    fclose(log_file);

    return 0;
}

