#include <stdint.h>
#include <pigpio.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>

// LIS3MDL I2C address
#define LIS3MDL_ADDR 0x1E

// LIS3MDL register addresses
#define LIS3MDL_CTRL_REG1 0x20
#define LIS3MDL_CTRL_REG3 0x22
#define LIS3MDL_OUT_X_L 0x28
#define LIS3MDL_OUT_X_H 0x29
#define LIS3MDL_OUT_Y_L 0x2A
#define LIS3MDL_OUT_Y_H 0x2B
#define LIS3MDL_OUT_Z_L 0x2C
#define LIS3MDL_OUT_Z_H 0x2D

// Calibration constants
#define X_OFFSET 0.0
#define Y_OFFSET 0.0
#define Z_OFFSET 0.0
#define X_SCALE 1.0
#define Y_SCALE 1.0
#define Z_SCALE 1.0

// Sensitivity
#define SENSITIVITY 0.146 // mG/LSB

// Metal detector threshold
#define METAL_THRESHOLD 800.0 // mG

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold magnetometer data
typedef struct {
    float x;
    float y;
    float z;
} magnetometer_data_t;

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Function to initialize the LIS3MDL sensor
int init_lis3mdl() {
    int retries = 3;
    int status = -1;

    while (retries > 0) {
        // Set continuous mode and 10 Hz data rate
        status = i2cWriteByteData(i2c_handle, LIS3MDL_CTRL_REG1, 0x70); // 01110000
        if (status < 0) {
            fprintf(stderr, "Error writing to CTRL_REG1: %d, retrying...\n", status);
            gpioDelay(10000); // 10ms delay
            retries--;
            continue;
        }

        // Enable continuous conversion mode
        status = i2cWriteByteData(i2c_handle, LIS3MDL_CTRL_REG3, 0x00); // 00000000
        if (status < 0) {
            fprintf(stderr, "Error writing to CTRL_REG3: %d, retrying...\n", status);
            gpioDelay(10000); // 10ms delay
            retries--;
            continue;
        }

        fprintf(stderr, "LIS3MDL initialized successfully.\n");
        return 0; // Success
    }

    fprintf(stderr, "LIS3MDL initialization failed after multiple retries.\n");
    return -1; // Failure
}

// Function to read raw magnetometer data
int read_raw_data(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];
    int status = i2cReadI2CBlockData(i2c_handle, LIS3MDL_OUT_X_L | 0x80, buffer, 6); // Read multiple bytes

    if (status < 0) {
        fprintf(stderr, "Error reading magnetometer data: %d\n", status);
        return -1;
    }

    *x = (int16_t)((buffer[1] << 8) | buffer[0]);
    *y = (int16_t)((buffer[3] << 8) | buffer[2]);
    *z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return 0;
}

// Function to calibrate magnetometer data
magnetometer_data_t calibrate_data(int16_t x_raw, int16_t y_raw, int16_t z_raw) {
    magnetometer_data_t calibrated_data;

    calibrated_data.x = ((float)x_raw * SENSITIVITY) + X_OFFSET * SENSITIVITY;
    calibrated_data.y = ((float)y_raw * SENSITIVITY) + Y_OFFSET * SENSITIVITY;
    calibrated_data.z = ((float)z_raw * SENSITIVITY) + Z_OFFSET * SENSITIVITY;

    return calibrated_data;
}

// Function to calculate the magnitude of the magnetic field
float calculate_magnitude(magnetometer_data_t data) {
    return sqrt(data.x * data.x + data.y * data.y + data.z * data.z);
}

// Function to log magnetometer data to a file
int log_data(magnetometer_data_t data) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%f,%f,%f\n", data.x, data.y, data.z);
    fflush(log_file); // Flush the buffer to ensure data is written to the file

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(1, LIS3MDL_ADDR, 0); // Bus 1, address 0x1E, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize LIS3MDL sensor
    if (init_lis3mdl() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("magnetic_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int16_t x_raw, y_raw, z_raw;
    magnetometer_data_t calibrated_data;
    float magnitude;

    // Main loop
    while (!terminate) {
        // Read raw data
        if (read_raw_data(&x_raw, &y_raw, &z_raw) == 0) {
            // Calibrate data
            calibrated_data = calibrate_data(x_raw, y_raw, z_raw);

            // Calculate magnitude
            magnitude = calculate_magnitude(calibrated_data);

            // Log data
            if (log_data(calibrated_data) != 0) {
                fprintf(stderr, "Error logging data.\n");
            }

            // Metal detector alert
            if (magnitude > METAL_THRESHOLD) {
                fprintf(stderr, "METAL DETECTED! Magnitude: %f mG\n", magnitude);
            }
        } else {
            fprintf(stderr, "Error reading magnetometer data. Retrying initialization...\n");
            i2cClose(i2c_handle);
            gpioDelay(100000); // 100ms delay
            i2c_handle = i2cOpen(1, LIS3MDL_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Error re-opening I2C: %d\n", i2c_handle);
                terminate = 1; // Exit loop if re-initialization fails
            } else {
                if (init_lis3mdl() != 0) {
                    fprintf(stderr, "LIS3MDL re-initialization failed.\n");
                    terminate = 1; // Exit loop if re-initialization fails
                }
            }
        }

        gpioDelay(100000); // 100ms delay (10 Hz)
    }

    // Close I2C connection and log file
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    fprintf(stderr, "Program terminated cleanly.\n");
    return 0;
}

