#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// ADXL354B Register Addresses
#define ADXL354B_REG_PARTID 0x00
#define ADXL354B_REG_POWER_CTL 0x04
#define ADXL354B_REG_STATUS 0x0B
#define ADXL354B_REG_XDATA_L 0x0E
#define ADXL354B_REG_XDATA_M 0x0F
#define ADXL354B_REG_XDATA_H 0x10
#define ADXL354B_REG_YDATA_L 0x11
#define ADXL354B_REG_YDATA_M 0x12
#define ADXL354B_REG_YDATA_H 0x13
#define ADXL354B_REG_ZDATA_L 0x14
#define ADXL354B_REG_ZDATA_M 0x15
#define ADXL354B_REG_ZDATA_H 0x16

// ADXL354B Configuration
#define ADXL354B_SPI_CHANNEL 0
#define ADXL354B_SPI_CE 8 // GPIO8 (BCM)
#define ADXL354B_SPI_MODE 0
#define ADXL354B_SPI_CLOCK 1000000 // 1 MHz
#define ADXL354B_PARTID_VALUE 0x54

// Global Variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function Prototypes
int spi_read_register(int handle, uint8_t reg_addr, uint8_t *data, int len);
int spi_write_register(int handle, uint8_t reg_addr, uint8_t data);
int adxl354b_reset(int handle);
int adxl354b_verify_partid(int handle);
int adxl354b_read_acceleration(int handle, int16_t *x, int16_t *y, int16_t *z);
void log_data(FILE *fp, int16_t x, int16_t y, int16_t z);
void signal_handler(int signal);

// SPI Read Function
int spi_read_register(int handle, uint8_t reg_addr, uint8_t *data, int len) {
    char tx_buf[1];
    char rx_buf[len];
    tx_buf[0] = reg_addr | 0x80; // Set MSB for read

    if (spiXfer(handle, tx_buf, rx_buf, len + 1) != len + 1) {
        fprintf(stderr, "SPI read error: %d\n", handle);
        return -1;
    }

    memcpy(data, rx_buf + 1, len);
    return 0;
}

// SPI Write Function
int spi_write_register(int handle, uint8_t reg_addr, uint8_t data) {
    char tx_buf[2];
    tx_buf[0] = reg_addr & 0x7F; // Clear MSB for write
    tx_buf[1] = data;

    if (spiWrite(handle, tx_buf, 2) != 2) {
        fprintf(stderr, "SPI write error: %d\n", handle);
        return -1;
    }
    return 0;
}

// ADXL354B Reset Function
int adxl354b_reset(int handle) {
    if (spi_write_register(handle, ADXL354B_REG_POWER_CTL, 0x80) != 0) {
        fprintf(stderr, "Failed to reset ADXL354B\n");
        return -1;
    }
    gpioDelay(1000); // 1 ms delay
    return 0;
}

// ADXL354B Verify PARTID Function
int adxl354b_verify_partid(int handle) {
    uint8_t partid;
    if (spi_read_register(handle, ADXL354B_REG_PARTID, &partid, 1) != 0) {
        fprintf(stderr, "Failed to read PARTID\n");
        return -1;
    }

    if (partid != ADXL354B_PARTID_VALUE) {
        fprintf(stderr, "Incorrect PARTID: 0x%02X (expected 0x%02X)\n", partid, ADXL354B_PARTID_VALUE);
        return -1;
    }

    printf("ADXL354B PARTID verified: 0x%02X\n", partid);
    return 0;
}

// ADXL354B Read Acceleration Function
int adxl354b_read_acceleration(int handle, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t x_l, x_m, x_h, y_l, y_m, y_h, z_l, z_m, z_h;

    if (spi_read_register(handle, ADXL354B_REG_XDATA_L, &x_l, 1) != 0) return -1;
    if (spi_read_register(handle, ADXL354B_REG_XDATA_M, &x_m, 1) != 0) return -1;
    if (spi_read_register(handle, ADXL354B_REG_XDATA_H, &x_h, 1) != 0) return -1;
    if (spi_read_register(handle, ADXL354B_REG_YDATA_L, &y_l, 1) != 0) return -1;
    if (spi_read_register(handle, ADXL354B_REG_YDATA_M, &y_m, 1) != 0) return -1;
    if (spi_read_register(handle, ADXL354B_REG_YDATA_H, &y_h, 1) != 0) return -1;
    if (spi_read_register(handle, ADXL354B_REG_ZDATA_L, &z_l, 1) != 0) return -1;
    if (spi_read_register(handle, ADXL354B_REG_ZDATA_M, &z_m, 1) != 0) return -1;
    if (spi_read_register(handle, ADXL354B_REG_ZDATA_H, &z_h, 1) != 0) return -1;

    *x = (int16_t)((x_h << 8) | x_l);
    *y = (int16_t)((y_h << 8) | y_l);
    *z = (int16_t)((z_h << 8) | z_l);

    return 0;
}

