#define ADXL354B_REG_ZDATA_L 0x14
#define ADXL354B_REG_ZDATA_M 0x15
#define ADXL354B_REG_ZDATA_H 0x16

// ADXL354B Configuration
#define ADXL354B_SPI_CHANNEL 0
#define ADXL354B_SPI_CE 8 // GPIO8 (BCM)
#define ADXL354B_SPI_MODE 0
#define ADXL354B_SPI_CLOCK 1000000 // 1 MHz
#define ADXL354B_PARTID_VALUE 0x54

// Global Variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function Prototypes
int spi_read_register(int handle, uint8_t reg_addr, uint8_t *data, int len);
int spi_write_register(int handle, uint8_t reg_addr, uint8_t data);
int adxl354b_reset(int handle);
int adxl354b_verify_partid(int handle);
int adxl354b_read_acceleration(int handle, int16_t *x, int16_t *y, int16_t *z);
void log_data(FILE *fp, int16_t x, int16_t y, int16_t z);
