// SPI Read Function
int spi_read_register(int handle, uint8_t reg_addr, uint8_t *data, int len) {
    char tx_buf[1];
    char rx_buf[len];
    tx_buf[0] = reg_addr | 0x80; // Set MSB for read

    if (spiXfer(handle, tx_buf, rx_buf, len + 1) != len + 1) {
        fprintf(stderr, "SPI read error: %d\n", handle);
        return -1;
    }

    memcpy(data, rx_buf + 1, len);
    return 0;
}

// SPI Write Function
int spi_write_register(int handle, uint8_t reg_addr, uint8_t data) {
    char tx_buf[2];
    tx_buf[0] = reg_addr & 0x7F; // Clear MSB for write
    tx_buf[1] = data;

    if (spiWrite(handle, tx_buf, 2) != 2) {
        fprintf(stderr, "SPI write error: %d\n", handle);
        return -1;
