    if (partid != ADXL354B_PARTID_VALUE) {
        fprintf(stderr, "Incorrect PARTID: 0x%02X (expected 0x%02X)\n", partid, ADXL354B_PARTID_VALUE);
        return -1;
    }

    printf("ADXL354B PARTID verified: 0x%02X\n", partid);
    return 0;
}

