#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// ADIS16362 Register Addresses
#define X_GYRO_OUT 0x04
#define Y_GYRO_OUT 0x06
#define Z_GYRO_OUT 0x08
#define X_ACCL_OUT 0x0A
#define Y_ACCL_OUT 0x0C
#define Z_ACCL_OUT 0x0E

// Scaling factors
#define GYRO_SCALE 0.05f  // deg/sec/LSB
#define ACCEL_SCALE 0.0025f // g/LSB

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_CE 8 // GPIO 8 (CE0)
#define SPI_BAUD 1000000 // 1 MHz
#define SPI_MODE 3

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold IMU data
typedef struct {
    double timestamp_sec;
    double timestamp_nsec;
    float x_gyro;
    float y_gyro;
    float z_gyro;
    float x_accel;
    float y_accel;
    float z_accel;
} imu_data_t;

// Function prototypes
int spi_read_register(int handle, uint8_t address, int16_t *data);
int spi_write_register(int handle, uint8_t address, uint8_t data);
int initialize_imu(int handle);
int read_imu_data(int handle, imu_data_t *data);
void log_imu_data(FILE *fp, const imu_data_t *data);
void signal_handler(int signal);

// Function to read a register from the IMU
int spi_read_register(int handle, uint8_t address, int16_t *data) {
    char tx_buf[2];
    char rx_buf[2];

    tx_buf[0] = address | 0x80; // Set MSB for read
    tx_buf[1] = 0x00; // Dummy byte

    if (spiXfer(handle, tx_buf, rx_buf, 2) != 0) {
        fprintf(stderr, "Error: SPI read failed for address 0x%02X\n", address);
        return -1;
    }

    *data = (rx_buf[0] << 8) | rx_buf[1];
    return 0;
}

// Function to write a register to the IMU
int spi_write_register(int handle, uint8_t address, uint8_t data) {
    char tx_buf[2];
    char rx_buf[2];

    tx_buf[0] = address & 0x7F; // Clear MSB for write
    tx_buf[1] = data;

    if (spiXfer(handle, tx_buf, rx_buf, 2) != 0) {
        fprintf(stderr, "Error: SPI write failed for address 0x%02X\n", address);
        return -1;
    }

    return 0;
}

// Function to initialize the IMU
int initialize_imu(int handle) {
    // Reset the device (example initialization sequence)
    if (spi_write_register(handle, 0x02, 0x04) != 0) { // Software Reset
        fprintf(stderr, "Error: Failed to reset IMU\n");
        return -1;
    }
    gpioDelay(100); // Wait for reset to complete

    // Configure other registers as needed (example: set sample rate)
    if (spi_write_register(handle, 0x36, 0x0A) != 0) { // Sample rate configuration
        fprintf(stderr, "Error: Failed to configure sample rate\n");
        return -1;
    }

    return 0;
}

// Function to read IMU data
int read_imu_data(int handle, imu_data_t *data) {
    int16_t raw_x_gyro, raw_y_gyro, raw_z_gyro, raw_x_accel, raw_y_accel, raw_z_accel;

    if (spi_read_register(handle, X_GYRO_OUT, &raw_x_gyro) != 0) return -1;
    if (spi_read_register(handle, Y_GYRO_OUT, &raw_y_gyro) != 0) return -1;
    if (spi_read_register(handle, Z_GYRO_OUT, &raw_z_gyro) != 0) return -1;
    if (spi_read_register(handle, X_ACCL_OUT, &raw_x_accel) != 0) return -1;
    if (spi_read_register(handle, Y_ACCL_OUT, &raw_y_accel) != 0) return -1;
    if (spi_read_register(handle, Z_ACCL_OUT, &raw_z_accel) != 0) return -1;

    data->x_gyro = (float)raw_x_gyro * GYRO_SCALE;
    data->y_gyro = (float)raw_y_gyro * GYRO_SCALE;
    data->z_gyro = (float)raw_z_gyro * GYRO_SCALE;
    data->x_accel = (float)raw_x_accel * ACCEL_SCALE;
    data->y_accel = (float)raw_y_accel * ACCEL_SCALE;
    data->z_accel = (float)raw_z_accel * ACCEL_SCALE;

    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    data->timestamp_sec = ts.tv_sec;
    data->timestamp_nsec = ts.tv_nsec;

    return 0;
}

// Function to log IMU data to a file
void log_imu_data(FILE *fp, const imu_data_t *data) {
    fprintf(fp, "%ld.%09ld,%.6f,%.6f,%.6f,%.6f,%.6f,%.6f\n",
            (long)data->timestamp_sec, data->timestamp_nsec,
            data->x_gyro, data->y_gyro, data->z_gyro,
            data->x_accel, data->y_accel, data->z_accel);
    fflush(fp); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Initialize IMU
    if (initialize_imu(spi_handle) != 0) {
        fprintf(stderr, "Error: IMU initialization failed\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("imu_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write header to log file if it's a new file
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,X_Gyro,Y_Gyro,Z_Gyro,X_Accel,Y_Accel,Z_Accel\n");
    }
    rewind(log_file);

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    imu_data_t imu_data;

    // Main loop
    while (!terminate) {
        if (read_imu_data(spi_handle, &imu_data) == 0) {
            log_imu_data(log_file, &imu_data);
        } else {
            fprintf(stderr, "Error: Failed to read IMU data\n");
        }

        gpioDelay(10); // 10 ms delay
    }

    // Cleanup
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

