#define GPIO_CHIP "gpiochip4"

static volatile int running = 1;

void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    int gpio_handle;
    int level;
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open GPIO chip
    gpio_handle = gpiochipOpen(GPIO_CHIP);
    if (gpio_handle < 0) {
        fprintf(stderr, "Failed to open GPIO chip %s: %d\n", GPIO_CHIP, gpio_handle);
        gpioTerminate();
        return 1;
    }

    // Request GPIO line for input
    if (gpioSetMode(GPIO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", GPIO_PIN);
        gpiochipClose(gpio_handle);
        gpioTerminate();
        return 1;
    }

    printf("Monitoring GPIO %d on %s for obstacle detection...\n", GPIO_PIN, GPIO_CHIP);

    while (running) {
        // Read GPIO level
        level = gpioRead(GPIO_PIN);

        if (level == 0) { // Obstacle detected (LOW signal)
            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            printf("[%s] Self-parking sequence started\n", timestamp);

            // Simulate self-parking routine (sleep for 5 seconds)
            sleep(5);

            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            printf("[%s] Self-parking sequence completed\n", timestamp);
        }

        sleep(1); // Poll every 1 second
    }

    // Release GPIO line and close chip
    gpioSetMode(GPIO_PIN, PI_INPUT); // Set back to input before closing
    gpiochipClose(gpio_handle);
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

