#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins for the sensors
#define SENSOR_1_GPIO 17
#define SENSOR_2_GPIO 27

// Structure to hold sensor data
typedef struct {
    int sensor1_value;
    int sensor2_value;
} sensor_data_t;

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to read sensor data
int read_sensors(sensor_data_t *data) {
    int sensor1_value = gpioRead(SENSOR_1_GPIO);
    int sensor2_value = gpioRead(SENSOR_2_GPIO);

    if (sensor1_value < 0 || sensor2_value < 0) {
        fprintf(stderr, "Error reading sensor values.\n");
        return -1; // Indicate an error
    }

    data->sensor1_value = sensor1_value;
    data->sensor2_value = sensor2_value;

    return 0; // Indicate success
}

// Function to log sensor data with timestamp
void log_sensor_data(sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s - Sensor 1: %s, Sensor 2: %s\n", timestamp,
           data.sensor1_value == 0 ? "Obstacle Detected" : "Path Clear",
           data.sensor2_value == 0 ? "Obstacle Detected" : "Path Clear");
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs
    gpioSetMode(SENSOR_1_GPIO, PI_INPUT);
    gpioSetMode(SENSOR_2_GPIO, PI_INPUT);

    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    sensor_data_t sensor_data;

    // Main loop
    while (program_running) {
        // Read sensor data
        if (read_sensors(&sensor_data) == 0) {
            // Log sensor data
            log_sensor_data(sensor_data);
        } else {
            fprintf(stderr, "Failed to read sensors. Retrying...\n");
        }

        // Delay for 100 milliseconds
        gpioDelay(100000); // 100 ms = 100000 microseconds
    }

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

