#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// SPI device and settings
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_3
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz

// ADIS16266 register addresses
#define XGYRO_OUT 0x04
#define YGYRO_OUT 0x06
#define ZGYRO_OUT 0x08

// Scale factor
#define SCALE_FACTOR 0.02 // deg/sec per LSB

// Global variables
int spi_fd = -1;
volatile sig_atomic_t stop_flag = 0;

// Structure to hold gyroscope data
typedef struct {
    float x;
    float y;
    float z;
} gyro_data_t;

// Function prototypes
int spi_init(void);
int spi_transfer(uint8_t address, uint8_t *data, int len);
int16_t read_gyro_register(uint8_t address);
gyro_data_t process_gyro_data(int16_t x_raw, int16_t y_raw, int16_t z_raw);
void log_gyro_data(gyro_data_t data);
void signal_handler(int sig);

// SPI initialization function
int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Set SPI mode
    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Error setting SPI mode");
        close(spi_fd);
        return -1;
    }

    // Set bits per word
    uint8_t bits = SPI_BITS_PER_WORD;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) == -1) {
        perror("Error setting bits per word");
        close(spi_fd);
        return -1;
    }

    // Set SPI speed
    uint32_t speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Error setting SPI speed");
        close(spi_fd);
        return -1;
    }

    return 0;
}

// SPI transfer function
int spi_transfer(uint8_t address, uint8_t *data, int len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long) &address,
        .rx_buf = (unsigned long) data,
        .len = len,
        .delay_usecs = 0,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 1) {
        perror("Error during SPI transfer");
        return -1;
    }

    return 0;
}

// Function to read a single register from ADIS16266
int16_t read_gyro_register(uint8_t address) {
    uint8_t data[2];
    address |= 0x80; // Set MSB for read operation

    if (spi_transfer(address, data, 2) != 0) {
        fprintf(stderr, "Error reading register 0x%02X\n", address);
        return 0; // Return 0 on error
    }

    return (int16_t)((data[0] << 8) | data[1]);
}

// Function to process raw gyroscope data
gyro_data_t process_gyro_data(int16_t x_raw, int16_t y_raw, int16_t z_raw) {
    gyro_data_t data;
    data.x = (float)x_raw * SCALE_FACTOR;
    data.y = (float)y_raw * SCALE_FACTOR;
    data.z = (float)z_raw * SCALE_FACTOR;
    return data;
}

// Function to log gyroscope data with timestamp
void log_gyro_data(gyro_data_t data) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    printf("%ld.%09ld, X: %.2f deg/sec, Y: %.2f deg/sec, Z: %.2f deg/sec\n",
           ts.tv_sec, ts.tv_nsec, data.x, data.y, data.z);
}

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("Caught signal %d, exiting...\n", sig);
    stop_flag = 1;
}

int main(void) {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize SPI
    if (spi_init() != 0) {
        fprintf(stderr, "SPI initialization failed. Exiting.\n");
        return 1;
    }

    printf("SPI initialized successfully.\n");

    // Main loop
    while (!stop_flag) {
        // Read raw gyroscope data
        int16_t x_raw = read_gyro_register(XGYRO_OUT);
        int16_t y_raw = read_gyro_register(YGYRO_OUT);
        int16_t z_raw = read_gyro_register(ZGYRO_OUT);

        // Process gyroscope data
        gyro_data_t gyro_data = process_gyro_data(x_raw, y_raw, z_raw);

        // Log gyroscope data
        log_gyro_data(gyro_data);

        // Wait 100 ms
        usleep(100000); // 100 ms
    }

    // Close SPI device
    close(spi_fd);
    printf("SPI device closed.\n");

    return 0;
}

