#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// LSM6DSR I2C address
#define LSM6DSR_ADDR 0x6A

// LSM6DSR register addresses
#define CTRL1_XL 0x10
#define CTRL2_G 0x11
#define OUTX_L_G 0x22
#define OUTX_H_G 0x23
#define OUTY_L_G 0x24
#define OUTY_H_G 0x25
#define OUTZ_L_G 0x26
#define OUTZ_H_G 0x27
#define OUTX_L_XL 0x28
#define OUTX_H_XL 0x29
#define OUTY_L_XL 0x2A
#define OUTY_H_XL 0x2B
#define OUTZ_L_XL 0x2C
#define OUTZ_H_XL 0x2D
#define WHO_AM_I 0x0F

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
}

// Function to read a single byte from an I2C register
int i2c_read_register(int handle, uint8_t reg) {
    int value = i2cReadByteData(handle, reg);
    if (value < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, value);
        return -1;
    }
    return value;
}

// Function to write a single byte to an I2C register
int i2c_write_register(int handle, uint8_t reg, uint8_t value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Function to read multiple bytes from an I2C register
int i2c_read_registers(int handle, uint8_t reg, char *buf, int count) {
    int result = i2cReadI2CBlockData(handle, reg, buf, count);
    if (result < 0) {
        fprintf(stderr, "Error reading block from register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return result;
}

// Function to initialize the LSM6DSR
int lsm6dsr_init(int handle) {
    // Check WHO_AM_I register
    int who_am_i = i2c_read_register(handle, WHO_AM_I);
    if (who_am_i < 0) {
        return -1;
    }
    if (who_am_i != 0x69) {
        fprintf(stderr, "WHO_AM_I check failed: 0x%02X (expected 0x69)\n", who_am_i);
        return -1;
    }

    // Configure accelerometer: 104 Hz, +/- 2g
    if (i2c_write_register(handle, CTRL1_XL, 0x80) < 0) {
        return -1;
    }

    // Configure gyroscope: 104 Hz, 250 dps
    if (i2c_write_register(handle, CTRL2_G, 0x80) < 0) {
        return -1;
    }

    return 0;
}

// Function to read accelerometer and gyroscope data
int read_sensor_data(int handle, int16_t *accel_x, int16_t *accel_y, int16_t *accel_z, int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z) {
    char buffer[12];

    if (i2c_read_registers(handle, OUTX_L_G, buffer, 12) < 0) {
        return -1;
    }

    *gyro_x = (int16_t)((buffer[1] << 8) | buffer[0]);
    *gyro_y = (int16_t)((buffer[3] << 8) | buffer[2]);
    *gyro_z = (int16_t)((buffer[5] << 8) | buffer[4]);
    *accel_x = (int16_t)((buffer[7] << 8) | buffer[6]);
    *accel_y = (int16_t)((buffer[9] << 8) | buffer[8]);
    *accel_z = (int16_t)((buffer[11] << 8) | buffer[10]);

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(1, LSM6DSR_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize LSM6DSR
    if (lsm6dsr_init(i2c_handle) < 0) {
        fprintf(stderr, "LSM6DSR initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

