#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// ADXL345 I2C address
#define ADXL345_ADDRESS 0x53

// ADXL345 registers
#define ADXL345_POWER_CTL 0x2D
#define ADXL345_DATAX0 0x32
#define ADXL345_DATAX1 0x33
#define ADXL345_DATAY0 0x34
#define ADXL345_DATAY1 0x35
#define ADXL345_DATAZ0 0x36
#define ADXL345_DATAZ1 0x37

// Scaling factor for +/- 2g range
#define SCALE_FACTOR 0.0039 // 3.9mg/LSB

// Tilt threshold (degrees)
#define TILT_THRESHOLD 30.0

// I2C handle
int i2c_handle;

// Function prototypes
int initialize_adxl345();
int read_acceleration(float *x, float *y, float *z);
float calculate_tilt_angle(float x, float y, float z);
int log_tilt_event(float x, float y, float z, float angle);
void signal_handler(int signal);

// Structure to hold accelerometer data
typedef struct {
    float x;
    float y;
    float z;
} accelerometer_data_t;

// Global flag to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        program_running = 0;
        printf("\nCtrl+C detected. Exiting gracefully...\n");
    }
}

// Function to initialize the ADXL345
int initialize_adxl345() {
    // Set the POWER_CTL register to enable measurement mode
    if (i2cWriteByteData(i2c_handle, ADXL345_POWER_CTL, 0x08) < 0) {
        fprintf(stderr, "Error: Could not set POWER_CTL register.\n");
        return -1;
    }
    return 0;
}

// Function to read acceleration data from the ADXL345
int read_acceleration(float *x, float *y, float *z) {
    char raw_data[6];
    int16_t x_raw, y_raw, z_raw;

    // Read 6 bytes of data starting from DATAX0
    if (i2cReadI2CBlockData(i2c_handle, ADXL345_DATAX0, raw_data, 6) < 0) {
        fprintf(stderr, "Error: Could not read acceleration data.\n");
        return -1;
    }

    // Combine high and low bytes for each axis
    x_raw = (int16_t)((raw_data[1] << 8) | raw_data[0]);
    y_raw = (int16_t)((raw_data[3] << 8) | raw_data[2]);
    z_raw = (int16_t)((raw_data[5] << 8) | raw_data[4]);

    // Convert raw values to g-force units
    *x = (float)x_raw * SCALE_FACTOR;
    *y = (float)y_raw * SCALE_FACTOR;
    *z = (float)z_raw * SCALE_FACTOR;

    return 0;
}

// Function to calculate the tilt angle
float calculate_tilt_angle(float x, float y, float z) {
    float angle = atan2(x, sqrt(y * y + z * z)) * 180 / M_PI;
    return angle;
}

// Function to log a tilt event
int log_tilt_event(float x, float y, float z, float angle) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    FILE *fp = fopen("/var/log/tilt_events.log", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open log file.\n");
        return -1;
    }

    fprintf(fp, "%s - Tilt angle: %.2f degrees, X: %.3f g, Y: %.3f g, Z: %.3f g\n", timestamp, angle, x, y, z);
    fclose(fp);

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, ADXL345_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus. %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize ADXL345
    if (initialize_adxl345() < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    accelerometer_data_t accel_data;
    float angle;

    // Main loop
    while (program_running) {
        // Read acceleration data
        if (read_acceleration(&accel_data.x, &accel_data.y, &accel_data.z) == 0) {
            // Calculate tilt angle
            angle = calculate_tilt_angle(accel_data.x, accel_data.y, accel_data.z);

            // Check if tilt angle exceeds threshold
            if (fabs(angle) > TILT_THRESHOLD) {
                // Log the event
                if (log_tilt_event(accel_data.x, accel_data.y, accel_data.z, angle) != 0) {
                    fprintf(stderr, "Error: Could not log tilt event.\n");
                }
            }
        } else {
            fprintf(stderr, "Error: Could not read acceleration data. Retrying...\n");
        }

        // Delay for 100ms
        gpioDelay(100000); // 100ms = 100000 microseconds
    }

    // Close I2C bus and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

