#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <string.h>

#define GPIO_PIN 17
#define SAMPLE_INTERVAL_MS 1
#define WINDOW_SIZE_SEC 5
#define PAUSE_INTERVAL_SEC 1

static volatile int terminate = 0;

void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", sig);
    terminate = 1;
}

int main(int argc, char *argv[]) {
    int threshold;
    int high_count;
    int i;
    int rc;
    struct timespec start_time, current_time;
    double elapsed_time;

    // Parse command-line argument
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <threshold>\n", argv[0]);
        return 1;
    }

    char *endptr;
    threshold = strtol(argv[1], &endptr, 10);

    if (*endptr != '\0' || threshold <= 0) {
        fprintf(stderr, "Error: Invalid threshold value.  Must be a positive integer.\n");
        return 1;
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as input
    gpioSetMode(GPIO_PIN, PI_INPUT);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    fprintf(stderr, "Monitoring sound sensor on GPIO%d...\n", GPIO_PIN);

    while (!terminate) {
        high_count = 0;
        clock_gettime(CLOCK_MONOTONIC, &start_time);

        // Sample the GPIO pin for 5 seconds
        while (1) {
            clock_gettime(CLOCK_MONOTONIC, &current_time);
            elapsed_time = (current_time.tv_sec - start_time.tv_sec) + (current_time.tv_nsec - start_time.tv_nsec) / 1000000000.0;

            if (elapsed_time >= WINDOW_SIZE_SEC) {
                break;
            }

            if (gpioRead(GPIO_PIN) == 1) {
                high_count++;
            }
            gpioDelay(SAMPLE_INTERVAL_MS);
        }

        // Print timestamped line based on threshold
        time_t rawtime;
        struct tm *timeinfo;
        char timestamp[80];

        time(&rawtime);
        timeinfo = localtime(&rawtime);

        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        if (high_count > threshold) {
            printf("%s ALERT\n", timestamp);
        } else {
            printf("%s Status: %d high readings (threshold: %d)\n", timestamp, high_count, threshold);
        }

        // Pause for 1 second
        gpioDelay(PAUSE_INTERVAL_SEC * 1000);
    }

    // Terminate pigpio
    gpioTerminate();

    fprintf(stderr, "Program terminated.\n");
    return 0;
}

