#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

// Define GPIO pins for Door A and Door B
#define DOOR_A_PIN 17
#define DOOR_B_PIN 27

// Define the GPIO chip name
#define GPIO_CHIP "gpiochip0"

// Define the log file name
#define LOG_FILE "access_log.txt"

// Global variables
static volatile sig_atomic_t terminate = 0;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *door_a_line = NULL;
static struct gpiod_line *door_b_line = NULL;
static FILE *log_file = NULL;

// Function prototypes
int generate_code();
int read_code();
int validate_code(int generated_code, int entered_code);
int unlock_door(int door_pin, int duration_ms);
int log_access(int code);
void signal_handler(int sig);
int setup_gpio();
void cleanup_gpio();

// Signal handler function
void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", sig);
}

// Function to generate a random six-digit security code
int generate_code() {
    return (rand() % 900000) + 100000; // Generates a number between 100000 and 999999
}

// Function to read the security code from stdin
int read_code() {
    char input[7]; // Buffer to store the input (6 digits + null terminator)
    int entered_code;

    printf("Enter the security code: ");
    if (fgets(input, sizeof(input), stdin) == NULL) {
        fprintf(stderr, "Error reading input: %s\n", strerror(errno));
        return -1; // Indicate an error
    }

    // Remove trailing newline character, if present
    size_t len = strlen(input);
    if (len > 0 && input[len - 1] == '\n') {
        input[len - 1] = '\0';
    }

    // Validate input: check if it consists only of digits
    if (strspn(input, "0123456789") != strlen(input)) {
        fprintf(stderr, "Invalid input: Only numeric characters are allowed.\n");
        return -1; // Indicate an error
    }

    // Convert the input string to an integer
    entered_code = atoi(input);

    // Basic validation: check if the entered code is within the expected range
    if (entered_code < 100000 || entered_code > 999999) {
        fprintf(stderr, "Invalid input: The code must be a six-digit number.\n");
        return -1; // Indicate an error
    }

    return entered_code;
}

// Function to validate the entered code against the generated code
int validate_code(int generated_code, int entered_code) {
    return (generated_code == entered_code) ? 0 : -1; // 0 for success, -1 for failure
}

// Function to unlock a door for a specified duration
int unlock_door(int door_pin, int duration_ms) {
    struct gpiod_line *line;
    int ret;

    if (door_pin == DOOR_A_PIN) {
        line = door_a_line;
    } else if (door_pin == DOOR_B_PIN) {
        line = door_b_line;
    } else {
        fprintf(stderr, "Error: Invalid door pin: %d\n", door_pin);
        return -1;
    }

    if (!line) {
        fprintf(stderr, "Error: Line not initialized for pin %d\n", door_pin);
        return -1;
    }

    // Set the line to HIGH to unlock the door
    ret = gpiod_line_set_value(line, 1);
    if (ret < 0) {
        fprintf(stderr, "Error setting line value for pin %d: %s\n", door_pin, strerror(-ret));
        return -1;
    }

    // Wait for the specified duration
    usleep(duration_ms * 1000); // Convert milliseconds to microseconds

    // Set the line to LOW to re-energize the relay and lock the door
    ret = gpiod_line_set_value(line, 0);
    if (ret < 0) {
        fprintf(stderr, "Error setting line value for pin %d: %s\n", door_pin, strerror(-ret));
        return -1;
    }

    return 0;
}

// Function to log access to the file
int log_access(int code) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s,%d\n", timestamp, code);
    fflush(log_file); // Ensure the data is written to the file immediately

    return 0;
}

// Function to setup GPIO pins
int setup_gpio() {
    int ret;

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip %s: %s\n", GPIO_CHIP, strerror(errno));
        return -1;
    }

    // Get the line for Door A
    door_a_line = gpiod_chip_get_line(chip, DOOR_A_PIN);
    if (!door_a_line) {
        fprintf(stderr, "Error getting line for GPIO %d: %s\n", DOOR_A_PIN, strerror(errno));
        goto cleanup_chip;
    }

    // Get the line for Door B
    door_b_line = gpiod_chip_get_line(chip, DOOR_B_PIN);
    if (!door_b_line) {
        fprintf(stderr, "Error getting line for GPIO %d: %s\n", DOOR_B_PIN, strerror(errno));
        goto cleanup_line_a;
    }

    // Request the lines as output
    ret = gpiod_line_request_output(door_a_line, "door_access", 0); // Initial value LOW
    if (ret < 0) {
        fprintf(stderr, "Error requesting line for GPIO %d as output: %s\n", DOOR_A_PIN, strerror(-ret));
        goto cleanup_line_b;
    }

    ret = gpiod_line_request_output(door_b_line, "door_access", 0); // Initial value LOW
    if (ret < 0) {
        fprintf(stderr, "Error requesting line for GPIO %d as output: %s\n", DOOR_B_PIN, strerror(-ret));
        goto cleanup_line_a_output;
    }

    return 0;

cleanup_line_a_output:
    gpiod_line_release(door_a_line);
cleanup_line_b:
    gpiod_line_release(door_b_line);
cleanup_line_a:
    gpiod_line_release(door_a_line);
cleanup_chip:
    gpiod_chip_close(chip);
    return -1;
}

// Function to cleanup GPIO pins
void cleanup_gpio() {
    if (door_a_line) {
        gpiod_line_set_value(door_a_line, 0); // Ensure door is locked
        gpiod_line_release(door_a_line);
    }
    if (door_b_line) {
        gpiod_line_set_value(door_b_line, 0); // Ensure door is locked
        gpiod_line_release(door_b_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }
}

int main() {
    int generated_code, entered_code, validation_result;

    // Seed the random number generator
    srand(time(NULL));

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Setup GPIO
    if (setup_gpio() != 0) {
        fprintf(stderr, "GPIO setup failed. Exiting.\n");
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        cleanup_gpio();
        return 1;
    }

    printf("Door access control system started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Generate a random security code
        generated_code = generate_code();
        printf("Generated code: %d\n", generated_code);

        // Read the entered code from stdin
        entered_code = read_code();
        if (entered_code == -1) {
            // Clear the input buffer if the input was invalid
            while (getchar() != '\n'); // Read and discard characters until a newline is found
            continue; // Skip to the next iteration of the loop
        }

        // Validate the entered code
        validation_result = validate_code(generated_code, entered_code);

        if (validation_result == 0) {
            // Code is valid, unlock the door
            printf("Access granted!\n");
            if (unlock_door(DOOR_A_PIN, 5000) != 0) {
                fprintf(stderr, "Error unlocking door A.\n");
            }
            // Log the access attempt
            if (log_access(generated_code) != 0) {
                fprintf(stderr, "Error logging access.\n");
            }
        } else {
            // Code is invalid
            printf("Access denied.\n");
        }

        // Simulate a successful entry (e.g., by setting a flag or performing other actions)
        // In a real-world scenario, this would be triggered by a biometric sensor or other authentication method.
        // For this example, we'll just wait for a short period before the next iteration.
        sleep(2); // Wait for 2 seconds before the next iteration
    }

    // Cleanup GPIO and close the log file before exiting
    cleanup_gpio();

    printf("Door access control system stopped.\n");

    return 0;
}

