#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define BH1750_ADDR 0x23
#define CONTINUOUS_HIGH_RES_MODE 0x10
#define LUX_CONVERSION_TIME_MS 180
#define LOG_FILE "light_log.txt"
#define SLEEP_INTERVAL_SEC 5

// Global variables
int i2c_handle;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_i2c();
int read_illuminance(float *lux);
int log_data(float lux);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("\nCaught SIGINT, exiting gracefully...\n");
        program_running = 0;
    }
}

// I2C initialization function
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read illuminance from the sensor
int read_illuminance(float *lux) {
    char config_cmd = CONTINUOUS_HIGH_RES_MODE;
    char buffer[2];
    int result;

    // Send configuration command
    result = i2cWriteByteData(i2c_handle, 0x00, config_cmd);
    if (result < 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        return -1;
    }

    // Wait for conversion time
    gpioDelay(LUX_CONVERSION_TIME_MS * 1000); // Convert ms to microseconds

    // Read two bytes of data
    result = i2cReadI2CBlockData(i2c_handle, 0x00, buffer, 2);
    if (result < 0) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1;
    }

    // Convert data to lux
    unsigned int raw_value = (buffer[0] << 8) | buffer[1];
    *lux = (float)raw_value / 1.2;

    return 0;
}

// Function to log data to a file
int log_data(float lux) {
    FILE *fp;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];

    // Format timestamp
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    // Open log file in append mode
    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return -1;
    }

    // Write data to log file
    fprintf(fp, "Timestamp: %s, Lux: %.2f\n", timestamp, lux);

    // Close log file
    fclose(fp);
    return 0;
}

int main() {
    float lux;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    printf("Light sensor data logging started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read illuminance
        if (read_illuminance(&lux) == 0) {
            // Log data
            if (log_data(lux) != 0) {
                fprintf(stderr, "Error logging data.\n");
            }
        } else {
            fprintf(stderr, "Error reading illuminance.\n");
        }

        // Sleep for 5 seconds
        gpioDelay(SLEEP_INTERVAL_SEC * 1000000); // Convert seconds to microseconds
    }

    // Close I2C connection
    i2cClose(i2c_handle);

    // Terminate pigpio
    gpioTerminate();

    printf("Light sensor data logging stopped.\n");

    return 0;
}

