#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

// Constants
#define I2C_ADDR 0x5A
#define PWM_PIN 18
#define PWM_FREQ 440
#define PWM_RANGE 1000
#define TCP_PORT 12345
#define SECRET_KEY "MySecretKey"
#define LOG_FILE "frequency_log.txt"

// Global variables
int i2c_handle;
int server_fd, new_socket;
FILE *log_file;

// Function prototypes
int mpr121_init();
int read_touch_data(int *touch_data);
float calculate_frequency(int *touch_data);
void play_tone(float frequency);
void log_frequency(float frequency);
void handle_tcp_connection();
void signal_handler(int signum);

// MPR121 Initialization
int mpr121_init() {
    // Soft reset
    if (i2cWriteByteData(i2c_handle, 0x80, 0x63) < 0) {
        fprintf(stderr, "Error: MPR121 soft reset failed\n");
        return -1;
    }
    gpioDelay(100); // Wait for reset

    // Electrode configuration (enable all 12 electrodes)
    if (i2cWriteByteData(i2c_handle, 0x5E, 0x0C) < 0) {
        fprintf(stderr, "Error: MPR121 electrode config failed\n");
        return -1;
    }

    // Touch and release thresholds (example values)
    for (int i = 0; i < 12; i++) {
        if (i2cWriteByteData(i2c_handle, 0x41 + 2 * i, 0x30) < 0) { // Touch threshold
            fprintf(stderr, "Error: MPR121 touch threshold config failed\n");
            return -1;
        }
        if (i2cWriteByteData(i2c_handle, 0x42 + 2 * i, 0x10) < 0) { // Release threshold
            fprintf(stderr, "Error: MPR121 release threshold config failed\n");
            return -1;
        }
    }

    // Enable all electrodes
    if (i2cWriteByteData(i2c_handle, 0x5B, 0x01) < 0) {
        fprintf(stderr, "Error: MPR121 enable electrodes failed\n");
        return -1;
    }

    return 0;
}

// Read Touch Data
int read_touch_data(int *touch_data) {
    char buf[2];
    if (i2cReadI2CBlockData(i2c_handle, 0x00, buf, 2) != 2) {
        fprintf(stderr, "Error: Failed to read touch data\n");
        return -1;
    }
    *touch_data = ((buf[1] << 8) | buf[0]) & 0x0FFF; // Mask to 12 bits
    return 0;
}

// Calculate Frequency
float calculate_frequency(int *touch_data) {
    // Simple frequency mapping based on touch data
    // Adjust these values to fine-tune the frequency mapping
    int touch_count = 0;
    for (int i = 0; i < 12; i++) {
        if ((*touch_data >> i) & 1) {
            touch_count++;
        }
    }

    // Map touch count to frequency range (e.g., 200Hz - 1000Hz)
    float frequency = 200.0 + (float)touch_count * (1000.0 - 200.0) / 12.0;
    return frequency;
}

// Play Tone
void play_tone(float frequency) {
    gpioSetPWMfrequency(PWM_PIN, frequency);
    gpioPWM(PWM_PIN, PWM_RANGE / 2); // 50% duty cycle
}

// Log Frequency
void log_frequency(float frequency) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "%d-%02d-%02d %02d:%02d:%02d, Frequency: %.2f Hz\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, frequency);
    fflush(log_file);
}

// Handle TCP Connection
void handle_tcp_connection() {
    char buffer[1024] = {0};
    ssize_t valread = recv(new_socket, buffer, sizeof(buffer) - 1, 0);
    if (valread > 0) {
        buffer[valread] = '\0';
        printf("Received: %s\n", buffer);

        // Authentication
        char *start = strstr(buffer, SECRET_KEY);
        if (start != NULL && start == buffer + strlen("MOTION_DETECTED:") && strlen(buffer) == strlen("MOTION_DETECTED:") + strlen(SECRET_KEY)) {
            printf("Authentication successful\n");

            // Play tone for 5 seconds
            int touch_data;
            for (int i = 0; i < 500; i++) { // 5 seconds * 20ms samples
                if (read_touch_data(&touch_data) == 0) {
                    float frequency = calculate_frequency(&touch_data);
                    play_tone(frequency);
                    log_frequency(frequency);
                } else {
                    fprintf(stderr, "Error reading touch data during tone playback\n");
                    break;
                }
                gpioDelay(20); // 20ms delay
            }
            gpioPWM(PWM_PIN, 0); // Stop PWM
        } else {
            fprintf(stderr, "Authentication failed\n");
        }
    } else {
        fprintf(stderr, "Error receiving data\n");
    }
    close(new_socket);
}

// Signal Handler
void signal_handler(int signum) {
    printf("Caught signal %d, cleaning up...\n", signum);
    gpioPWM(PWM_PIN, 0); // Stop PWM
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (server_fd >= 0) {
        close(server_fd);
    }
    if (new_socket >= 0) {
        close(new_socket);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(1, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed\n");
        gpioTerminate();
        return 1;
    }

    // Initialize MPR121
    if (mpr121_init() != 0) {
        fprintf(stderr, "Error: MPR121 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set PWM pin as output
    gpioSetMode(PWM_PIN, PI_OUTPUT);
    gpioSetPWMrange(PWM_PIN, PWM_RANGE);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Create socket
    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd == 0) {
        perror("socket failed");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Bind socket to port
    struct sockaddr_in address;
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(TCP_PORT);

    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("bind failed");
        close(server_fd);
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Listen for connections
    if (listen(server_fd, 3) < 0) {
        perror("listen");
        close(server_fd);
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("Listening on port %d...\n", TCP_PORT);

    // Accept connections in a loop
    while (1) {
        struct sockaddr_in client_address;
        int addrlen = sizeof(client_address);
        new_socket = accept(server_fd, (struct sockaddr *)&client_address, (socklen_t*)&addrlen);
        if (new_socket < 0) {
            perror("accept");
            continue; // Continue listening
        }

        printf("Connection accepted\n");
        handle_tcp_connection();
    }

    return 0;
}

