// LSM303DLHC Magnetometer I2C address
#define LSM303_ADDRESS 0x1E

// LSM303DLHC Magnetometer Registers
#define CRA_REG_M 0x00
#define CRB_REG_M 0x01
#define MR_REG_M 0x02
#define OUT_X_H_M 0x03
#define OUT_X_L_M 0x04
#define OUT_Z_H_M 0x05
#define OUT_Z_L_M 0x06
#define OUT_Y_H_M 0x07
#define OUT_Y_L_M 0x08

// GPIO pin for LED PWM control
#define LED_PIN 17

// I2C bus number
#define I2C_BUS 1

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
    terminate = 1;
}

// Function to initialize the LSM303DLHC magnetometer
int init_magnetometer() {
    // Set CRA_REG_M (0x00) to 0x18 for 75 Hz output rate
    if (i2cWriteByteData(i2c_handle, CRA_REG_M, 0x18) < 0) {
        fprintf(log_file, "Error writing to CRA_REG_M\n");
        return -1;
    }

    // Set CRB_REG_M (0x01) to 0x20 for +/- 1.3 Gauss full scale
    if (i2cWriteByteData(i2c_handle, CRB_REG_M, 0x20) < 0) {
        fprintf(log_file, "Error writing to CRB_REG_M\n");
        return -1;
    }

    // Set MR_REG_M (0x02) to 0x00 for continuous conversion mode
    if (i2cWriteByteData(i2c_handle, MR_REG_M, 0x00) < 0) {
        fprintf(log_file, "Error writing to MR_REG_M\n");
        return -1;
    }

    return 0;
}

// Function to read magnetometer data
int read_magnetometer(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];

    if (i2cReadI2CBlockData(i2c_handle, OUT_X_H_M, buffer, 6) != 6) {
        fprintf(log_file, "Error reading magnetometer data\n");
        return -1;
    }

    *x = (int16_t)((buffer[0] << 8) | buffer[1]);
    *z = (int16_t)((buffer[2] << 8) | buffer[3]);
    *y = (int16_t)((buffer[4] << 8) | buffer[5]);

    return 0;
}

// Function to calculate the magnitude of the Z-axis field
double calculate_magnitude(int16_t z) {
    return (double)z;
}

// Function to set the LED brightness using PWM
void set_led_brightness(double magnitude) {
    // Map the magnitude to a PWM duty cycle (0-1000000)
    int duty_cycle = (int)(magnitude * 1000.0); // Scale magnitude to 0-1000
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > 1000000) duty_cycle = 1000000;

    gpioPWM(LED_PIN, duty_cycle);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen("magnetometer.log", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, LSM303_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(log_file, "Error opening I2C bus: %d\n", i2c_handle);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Initialize magnetometer
    if (init_magnetometer() < 0) {
        fprintf(log_file, "Magnetometer initialization failed\n");
        i2cClose(i2c_handle);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Set LED pin as output
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Set PWM range
    gpioSetPWMrange(LED_PIN, 1000000);

    // Set PWM frequency
    gpioSetPWMfrequency(LED_PIN, 1000); // 1 kHz

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int16_t x, y, z;
    double magnitude;

    // Main loop
    while (!terminate) {
        // Read magnetometer data
        if (read_magnetometer(&x, &y, &z) == 0) {
            // Calculate magnitude
            magnitude = calculate_magnitude(z);

            // Set LED brightness
            set_led_brightness(magnitude);
        } else {
            fprintf(log_file, "Error reading magnetometer data, skipping sample\n");
        }

        // Delay for 100 ms
        gpioDelay(100000); // 100 ms
    }

    // Cleanup
    gpioPWM(LED_PIN, 0); // Turn off LED
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

