#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <sys/time.h>

// HMC5883L I2C address
#define HMC5883L_ADDR 0x1E

// HMC5883L register addresses
#define HMC5883L_CONFIG_A 0x00
#define HMC5883L_CONFIG_B 0x01
#define HMC5883L_MODE 0x02
#define HMC5883L_DATA_X_MSB 0x03
#define HMC5883L_DATA_X_LSB 0x04
#define HMC5883L_DATA_Z_MSB 0x05
#define HMC5883L_DATA_Z_LSB 0x06
#define HMC5883L_DATA_Y_MSB 0x07
#define HMC5883L_DATA_Y_LSB 0x08

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Hard-iron offsets
float x_offset = 0.0;
float y_offset = 0.0;
float z_offset = 0.0;

// Circular buffer for running average
#define BUFFER_SIZE 100
int16_t x_buffer[BUFFER_SIZE];
int16_t y_buffer[BUFFER_SIZE];
int16_t z_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int init_hmc5883l();
int read_hmc5883l(int16_t *x, int16_t *y, int16_t *z);
void update_running_average(int16_t x, int16_t y, int16_t z);
void apply_hard_iron_offsets(int16_t x, int16_t y, int16_t z, float *x_corrected, float *y_corrected, float *z_corrected);
void print_data(float x, float y, float z);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating program...\n");
    terminate = 1;
}

// Initialize HMC5883L
int init_hmc5883l() {
    // Set configuration register A (0x00): 8-average, 15 Hz, normal measurement
    if (i2cWriteByteData(i2c_handle, HMC5883L_CONFIG_A, 0x70) < 0) {
        fprintf(stderr, "Error writing to config register A\n");
        return -1;
    }

    // Set configuration register B (0x01): Gain = 1.3 Ga
    if (i2cWriteByteData(i2c_handle, HMC5883L_CONFIG_B, 0xA0) < 0) {
        fprintf(stderr, "Error writing to config register B\n");
        return -1;
    }

    // Set mode register (0x02): Continuous measurement mode
    if (i2cWriteByteData(i2c_handle, HMC5883L_MODE, 0x00) < 0) {
        fprintf(stderr, "Error writing to mode register\n");
        return -1;
    }

    return 0;
}

// Read magnetometer data
int read_hmc5883l(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];

    if (i2cReadI2CBlockData(i2c_handle, HMC5883L_DATA_X_MSB, buffer, 6) != 6) {
        fprintf(stderr, "Error reading magnetometer data\n");
        return -1;
    }

    *x = (int16_t)((buffer[0] << 8) | buffer[1]);
    *z = (int16_t)((buffer[2] << 8) | buffer[3]);
    *y = (int16_t)((buffer[4] << 8) | buffer[5]);

    return 0;
}

// Update running average
void update_running_average(int16_t x, int16_t y, int16_t z) {
    x_buffer[buffer_index] = x;
    y_buffer[buffer_index] = y;
    z_buffer[buffer_index] = z;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;

    // Calculate running average
    int32_t x_sum = 0, y_sum = 0, z_sum = 0;
    for (int i = 0; i < BUFFER_SIZE; i++) {
        x_sum += x_buffer[i];
        y_sum += y_buffer[i];
        z_sum += z_buffer[i];
    }

    x_offset = (float)x_sum / BUFFER_SIZE;
    y_offset = (float)y_sum / BUFFER_SIZE;
    z_offset = (float)z_sum / BUFFER_SIZE;
}

// Apply hard-iron offsets
void apply_hard_iron_offsets(int16_t x, int16_t y, int16_t z, float *x_corrected, float *y_corrected, float *z_corrected) {
    *x_corrected = (float)x - x_offset;
    *y_corrected = (float)y - y_offset;
    *z_corrected = (float)z - z_offset;
}

// Print data with timestamp
void print_data(float x, float y, float z) {
    struct timeval tv;
    gettimeofday(&tv, NULL);
    time_t nowtime = tv.tv_sec;
    struct tm *nowtm = localtime(&nowtime);
    char tmbuf[64], buf[64];
    strftime(tmbuf, sizeof(tmbuf), "%Y-%m-%d %H:%M:%S", nowtm);
    snprintf(buf, sizeof(buf), "%s.%06ld", tmbuf, tv.tv_usec);

    printf("%s, X: %.2f, Y: %.2f, Z: %.2f\n", buf, x, y, z);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, HMC5883L_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Initialize HMC5883L
    if (init_hmc5883l() < 0) {
        fprintf(stderr, "HMC5883L initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int16_t x, y, z;
    float x_corrected, y_corrected, z_corrected;

    // Main loop
    while (!terminate) {
        // Read magnetometer data
        if (read_hmc5883l(&x, &y, &z) == 0) {
            // Update running average
            update_running_average(x, y, z);

            // Apply hard-iron offsets
            apply_hard_iron_offsets(x, y, z, &x_corrected, &y_corrected, &z_corrected);

            // Print data
            print_data(x_corrected, y_corrected, z_corrected);
        } else {
            fprintf(stderr, "Error reading magnetometer data, retrying...\n");
        }

        // Wait 500 ms
        gpioDelay(500000); // 500 ms
    }

    // Close I2C bus
    i2cClose(i2c_handle);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

