    signal(SIGTERM, signal_handler);

    int16_t x, y, z;
    float x_corrected, y_corrected, z_corrected;

    // Main loop
    while (!terminate) {
        // Read magnetometer data
        if (read_hmc5883l(&x, &y, &z) == 0) {
