#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// LSM303D I2C address
#define LSM303D_ADDR 0x1D

// LSM303D register addresses
#define CTRL_REG1_A 0x20
#define OUT_X_L_A 0x28
#define OUT_X_H_A 0x29
#define OUT_Y_L_A 0x2A
#define OUT_Y_H_A 0x2B
#define OUT_Z_L_A 0x2C
#define OUT_Z_H_A 0x2D
#define INT1_CFG 0x30
#define INT1_THS_L 0x32
#define INT1_THS_H 0x33
#define INT1_DURATION 0x34

// GPIO pin for INT1
#define INT1_GPIO 23

// Circular buffer size
#define BUFFER_SIZE 64

// Accelerometer sensitivity (mg/LSB)
#define ACCEL_SENSITIVITY 0.061

// Interrupt threshold (mg)
#define INTERRUPT_THRESHOLD 2000

// Structure to hold accelerometer data
typedef struct {
    float x;
    float y;
    float z;
} accelerometer_data_t;

// Circular buffer structure
typedef struct {
    accelerometer_data_t data[BUFFER_SIZE];
    int head;
    int tail;
    int count;
} circular_buffer_t;

// Global variables
int i2c_handle;
circular_buffer_t buffer;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int init_lsm303d();
int read_accelerometer_data(accelerometer_data_t *data);
void buffer_init(circular_buffer_t *buffer);
void buffer_add(circular_buffer_t *buffer, accelerometer_data_t data);
int buffer_get_last_n(circular_buffer_t *buffer, int n, accelerometer_data_t *output);
void dump_buffer(circular_buffer_t *buffer);
void interrupt_handler(int gpio, int level, uint32_t tick);
void signal_handler(int signal);

// Function to initialize the LSM303D
int init_lsm303d() {
    // Verify device identity
    int who_am_i = i2cReadByteData(i2c_handle, CTRL_REG1_A);
    if (who_am_i < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %s\n", strerror(errno));
        return -1;
    }
    if (who_am_i != 0x49) {
        fprintf(stderr, "Incorrect WHO_AM_I value: 0x%02X\n", who_am_i);
        return -1;
    }

    // Configure accelerometer: 100 Hz, enable all axes
    if (i2cWriteByteData(i2c_handle, CTRL_REG1_A, 0x57) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1_A: %s\n", strerror(errno));
        return -1;
    }

    // Configure interrupt threshold and duration
    if (i2cWriteByteData(i2c_handle, INT1_THS_L, (int)(INTERRUPT_THRESHOLD * ACCEL_SENSITIVITY / 0.061)) < 0) {
        fprintf(stderr, "Error writing to INT1_THS_L: %s\n", strerror(errno));
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, INT1_THS_H, 0) < 0) {
        fprintf(stderr, "Error writing to INT1_THS_H: %s\n", strerror(errno));
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, INT1_DURATION, 0) < 0) {
        fprintf(stderr, "Error writing to INT1_DURATION: %s\n", strerror(errno));
        return -1;
    }

    // Configure INT1_CFG to trigger on X, Y, and Z high
    if (i2cWriteByteData(i2c_handle, INT1_CFG, 0x3F) < 0) {
        fprintf(stderr, "Error writing to INT1_CFG: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Function to read accelerometer data
int read_accelerometer_data(accelerometer_data_t *data) {
    char raw_data[6];
    int16_t x, y, z;

    if (i2cReadI2CBlockData(i2c_handle, OUT_X_L_A, raw_data, 6) < 0) {
        fprintf(stderr, "Error reading accelerometer data: %s\n", strerror(errno));
        return -1;
    }

    x = (int16_t)((raw_data[1] << 8) | raw_data[0]);
    y = (int16_t)((raw_data[3] << 8) | raw_data[2]);
    z = (int16_t)((raw_data[5] << 8) | raw_data[4]);

    data->x = (float)x * ACCEL_SENSITIVITY;
    data->y = (float)y * ACCEL_SENSITIVITY;
    data->z = (float)z * ACCEL_SENSITIVITY;

    return 0;
}

// Function to initialize the circular buffer
void buffer_init(circular_buffer_t *buffer) {
    buffer->head = 0;
    buffer->tail = 0;
    buffer->count = 0;
}

// Function to add data to the circular buffer
void buffer_add(circular_buffer_t *buffer, accelerometer_data_t data) {
    buffer->data[buffer->head] = data;
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count == BUFFER_SIZE) {
        buffer->tail = (buffer->tail + 1) % BUFFER_SIZE;
    } else {
        buffer->count++;
    }
}

// Function to get the last n samples from the circular buffer
int buffer_get_last_n(circular_buffer_t *buffer, int n, accelerometer_data_t *output) {
    if (n > buffer->count) {
        return -1; // Not enough data in the buffer
    }

    int start_index = (buffer->head - n + BUFFER_SIZE) % BUFFER_SIZE;
    for (int i = 0; i < n; i++) {
        output[i] = buffer->data[(start_index + i) % BUFFER_SIZE];
    }
    return 0;
}

// Function to dump the contents of the circular buffer
void dump_buffer(circular_buffer_t *buffer) {
    time_t rawtime;
    struct tm *timeinfo;
    time(&rawtime);
    timeinfo = localtime(&rawtime);

    char timestamp[80];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s: Last %d samples:\n", timestamp, 10);

    accelerometer_data_t last_samples[10];
    if (buffer_get_last_n(buffer, 10, last_samples) == 0) {
        for (int i = 0; i < 10; i++) {
            printf("  Sample %d: X=%.2f mg, Y=%.2f mg, Z=%.2f mg\n", i + 1, last_samples[i].x, last_samples[i].y, last_samples[i].z);
        }
    } else {
        printf("  Not enough data in buffer.\n");
    }
}

// Interrupt handler function
void interrupt_handler(int gpio, int level, uint32_t tick) {
    if (level == 1) { // Rising edge
        dump_buffer(&buffer);
    }
}

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);

    // Disable accelerometer
    i2cWriteByteData(i2c_handle, CTRL_REG1_A, 0x00);

    // Close I2C connection
    i2cClose(i2c_handle);

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(1, LSM303D_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C connection: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Initialize LSM303D
    if (init_lsm303d() < 0) {
        fprintf(stderr, "LSM303D initialisation failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize circular buffer
    buffer_init(&buffer);

    // Set GPIO mode for INT1
    gpioSetMode(INT1_GPIO, PI_INPUT);
    gpioSetPullUpDown(INT1_GPIO, PI_PUD_UP); // Enable pull-up resistor

    // Set interrupt handler
    gpioSetAlertFunc(INT1_GPIO, interrupt_handler);

    // Set signal handler for SIGINT
    signal(SIGINT, signal_handler);

    accelerometer_data_t data;
    struct timespec sleep_time;
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = 10000000; // 10 ms

    // Main loop
    while (program_running) {
        if (read_accelerometer_data(&data) == 0) {
            buffer_add(&buffer, data);
        }
        nanosleep(&sleep_time, NULL);
    }

    return 0;
}

