// Define GPIO pins for solenoids
#define SOLENOID_1_GPIO 17
#define SOLENOID_2_GPIO 27

// Global variable to track the current solenoid state
int current_solenoid = 0; // 0 for solenoid 1, 1 for solenoid 2

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, cleaning up...\n", signal);

    // Set both GPIO pins LOW
    gpioWrite(SOLENOID_1_GPIO, 0);
    gpioWrite(SOLENOID_2_GPIO, 0);

    // Terminate the pigpio library
    gpioTerminate();

    // Exit the program
    exit(0);
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(SOLENOID_1_GPIO, PI_OUTPUT);
    gpioSetMode(SOLENOID_2_GPIO, PI_OUTPUT);

    // Set both GPIO pins LOW initially
    gpioWrite(SOLENOID_1_GPIO, 0);
    gpioWrite(SOLENOID_2_GPIO, 0);

    // Install signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        // Activate solenoid 1
        if (current_solenoid == 0) {
            gpioWrite(SOLENOID_1_GPIO, 1);
            gpioWrite(SOLENOID_2_GPIO, 0);
            current_solenoid = 1;
        } else {
            // Activate solenoid 2
            gpioWrite(SOLENOID_1_GPIO, 0);
            gpioWrite(SOLENOID_2_GPIO, 1);
            current_solenoid = 0;
        }

        // Delay for 500 milliseconds
        struct timespec delay;
        delay.tv_sec = 0;
        delay.tv_nsec = 500000000; // 500 milliseconds
        nanosleep(&delay, NULL);
    }

    // The program should never reach here, but include cleanup for safety
    gpioWrite(SOLENOID_1_GPIO, 0);
    gpioWrite(SOLENOID_2_GPIO, 0);
    gpioTerminate();

    return 0;
}

