#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <termios.h>
#include <fcntl.h>
#include <unistd.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Constants
#define PRIMARY_UART_DEVICE "/dev/serial0"
#define SECONDARY_UART_DEVICE "/dev/serial1"
#define BAUD_RATE 9600
#define CODE_LENGTH 6
#define LOCK_DURATION_MS 2000
#define TIMEOUT_SEC 5
#define RELAY1_GPIO 17
#define RELAY2_GPIO 27

// Global variables
volatile sig_atomic_t program_running = 1;
int primary_uart_fd = -1;
int secondary_uart_fd = -1;

// Function prototypes
int initialize_uart(const char *device);
int read_code(int fd, char *buffer, int timeout_sec);
int validate_code(const char *code);
int control_relay(int gpio, int state);
void log_error(const char *message);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    program_running = 0;
    printf("Signal received, cleaning up...\n");
}

// Initialize UART
int initialize_uart(const char *device) {
    int fd = open(device, O_RDWR | O_NOCTTY | O_NDELAY);
    if (fd == -1) {
        log_error("Failed to open UART port");
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        log_error("Failed to get termios attributes");
        close(fd);
        return -1;
    }

    tty.c_cflag = (tty.c_cflag & ~CSIZE) | CS8;    // 8-bit chars
    tty.c_iflag &= ~IGNBRK;         // disable break processing
    tty.c_lflag = 0;                // no signaling chars, no echo, no canonical processing
    tty.c_oflag = 0;                // no remapping, no delays
    tty.c_cc[VMIN] = 0;              // read doesn't block
    tty.c_cc[VTIME] = timeout_sec * 10; // 0.1 seconds read timeout

    tty.c_iflag &= ~(IXON | IXOFF | IXANY); // shut off xon/xoff ctrl

    tty.c_cflag |= (CLOCAL | CREAD);   // ignore modem controls, enable reading
    tty.c_cflag &= ~(PARENB | PARODD); // shut off parity
    tty.c_cflag &= ~CSTOPB;
    tty.c_cflag &= ~CRTSCTS;

    if (cfsetospeed(&tty, B9600) != 0 || cfsetispeed(&tty, B9600) != 0) {
        log_error("Failed to set baud rate");
        close(fd);
        return -1;
    }

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        log_error("Failed to set termios attributes");
        close(fd);
        return -1;
    }

