#include <syslog.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/gpio.h>
#include <errno.h>

// Define GPIO pins
#define PIR_SENSOR_PIN 4
#define RELAY_PIN 17

// Define GPIO chip
#define GPIO_CHIP "gpiochip0"

// Global variables
static int gpio_fd = -1;
static int relay_state = 0; // 0: OFF, 1: ON
static int running = 1;

// Function prototypes
int gpio_export(int pin);
int gpio_unexport(int pin);
int gpio_set_direction(int pin, const char *direction);
int gpio_set_value(int pin, int value);
int gpio_get_value(int pin);
void log_event(const char *message);
void activate_relay();
void deactivate_relay();
void failsafe();
void signal_handler(int sig);

// Function to export a GPIO pin
int gpio_export(int pin) {
    char buffer[64];
    int fd;

    fd = open("/sys/class/gpio/export", O_WRONLY);
    if (fd < 0) {
        syslog(LOG_ERR, "Failed to open /sys/class/gpio/export: %s", strerror(errno));
        return -1;
    }
    snprintf(buffer, sizeof(buffer), "%d", pin);
    if (write(fd, buffer, strlen(buffer)) < 0) {
        syslog(LOG_ERR, "Failed to write to /sys/class/gpio/export: %s", strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

// Function to unexport a GPIO pin
int gpio_unexport(int pin) {
    char buffer[64];
    int fd;

    fd = open("/sys/class/gpio/unexport", O_WRONLY);
    if (fd < 0) {
        syslog(LOG_ERR, "Failed to open /sys/class/gpio/unexport: %s", strerror(errno));
        return -1;
    }
    snprintf(buffer, sizeof(buffer), "%d", pin);
    if (write(fd, buffer, strlen(buffer)) < 0) {
        syslog(LOG_ERR, "Failed to write to /sys/class/gpio/unexport: %s", strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

// Function to set the direction of a GPIO pin (in or out)
int gpio_set_direction(int pin, const char *direction) {
    char path[64];
    int fd;

    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/direction", pin);
    fd = open(path, O_WRONLY);
    if (fd < 0) {
        syslog(LOG_ERR, "Failed to open %s: %s", path, strerror(errno));
        return -1;
    }
    if (write(fd, direction, strlen(direction)) < 0) {
        syslog(LOG_ERR, "Failed to write to %s: %s", path, strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

// Function to set the value of a GPIO pin (0 or 1)
int gpio_set_value(int pin, int value) {
    char path[64];
    int fd;

    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/value", pin);
    fd = open(path, O_WRONLY);
    if (fd < 0) {
        syslog(LOG_ERR, "Failed to open %s: %s", path, strerror(errno));
        return -1;
    }
    if (write(fd, value ? "1" : "0", 1) < 0) {
        syslog(LOG_ERR, "Failed to write to %s: %s", path, strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

// Function to get the value of a GPIO pin
int gpio_get_value(int pin) {
    char path[64];
    char value_str[3];
    int fd;

    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/value", pin);
    fd = open(path, O_RDONLY);
    if (fd < 0) {
        syslog(LOG_ERR, "Failed to open %s: %s", path, strerror(errno));
        return -1;
    }
    if (read(fd, value_str, 3) < 0) {
        syslog(LOG_ERR, "Failed to read from %s: %s", path, strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    return atoi(value_str);
}

// Function to log an event to syslog
void log_event(const char *message) {
    time_t now;
    struct tm *timeinfo;
    char timestamp[20];

    time(&now);
    timeinfo = localtime(&now);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    syslog(LOG_INFO, "%s: %s", timestamp, message);
}

// Function to activate the relay
void activate_relay() {
    if (gpio_set_value(RELAY_PIN, 1) == 0) {
        relay_state = 1;
        log_event("Relay activated");
    } else {
        syslog(LOG_ERR, "Failed to activate relay");
    }
}

// Function to deactivate the relay
void deactivate_relay() {
    if (gpio_set_value(RELAY_PIN, 0) == 0) {
        relay_state = 0;
        log_event("Relay deactivated");
    } else {
        syslog(LOG_ERR, "Failed to deactivate relay");
    }
}

// Failsafe function
void failsafe() {
    syslog(LOG_WARNING, "Potential malfunction detected: PIR signal continuously HIGH for 10 seconds or more.");
    deactivate_relay();
    log_event("System shutdown initiated due to failsafe.");
    running = 0; // Stop the main loop
    exit(1); // Exit the program
}

// Signal handler function
void signal_handler(int sig) {
    syslog(LOG_INFO, "Signal received: %d. Shutting down...", sig);
    running = 0; // Stop the main loop

    // Deactivate the relay
    deactivate_relay();

    // Unexport GPIO pins
    gpio_unexport(PIR_SENSOR_PIN);
    gpio_unexport(RELAY_PIN);

    // Close syslog
    closelog();

    exit(0);
}

int main() {
    time_t start_time = 0;
    int pir_value;

    // Open syslog
    openlog("motion_detector", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Export GPIO pins
    if (gpio_export(PIR_SENSOR_PIN) != 0) {
        syslog(LOG_ERR, "Failed to export PIR sensor pin");
        goto cleanup;
    }
    if (gpio_export(RELAY_PIN) != 0) {
        syslog(LOG_ERR, "Failed to export relay pin");
        goto cleanup;
    }

    // Set GPIO directions
    if (gpio_set_direction(PIR_SENSOR_PIN, "in") != 0) {
        syslog(LOG_ERR, "Failed to set PIR sensor pin direction");
        goto cleanup;
    }
    if (gpio_set_direction(RELAY_PIN, "out") != 0) {
        syslog(LOG_ERR, "Failed to set relay pin direction");
        goto cleanup;
    }

    // Main loop
    while (running) {
        pir_value = gpio_get_value(PIR_SENSOR_PIN);
        if (pir_value < 0) {
            syslog(LOG_ERR, "Failed to read PIR sensor value");
            goto cleanup;
        }

        if (pir_value == 1) {
            if (start_time == 0) {
                start_time = time(NULL);
            } else {
                time_t current_time = time(NULL);
                if (difftime(current_time, start_time) > 10) {
                    failsafe();
                }
            }

            // Activate relay for 1 second
            activate_relay();
            sleep(1);
            deactivate_relay();

            // Wait for PIR signal to go LOW
            while (gpio_get_value(PIR_SENSOR_PIN) == 1 && running) {
                usleep(50000); // 50ms
            }
            start_time = 0; // Reset start time
        } else {
            start_time = 0; // Reset start time if PIR is LOW
        }

        usleep(50000); // 50ms delay
    }

cleanup:
    // Unexport GPIO pins
    gpio_unexport(PIR_SENSOR_PIN);
    gpio_unexport(RELAY_PIN);

    // Close syslog
    closelog();

    return 0;
}

