#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <syslog.h>
#include <time.h>
#include <pigpio.h>
#include <string.h>

// Define GPIO pins for the relays
#define RELAY1_PIN 4
#define RELAY2_PIN 17
#define RELAY3_PIN 27
#define RELAY4_PIN 22

// Define the irrigation cycle parameters
#define IRRIGATION_DURATION 300 // seconds
#define PAUSE_DURATION 60      // seconds
#define TIMER_INTERVAL 60      // seconds

// Define the number of relays
#define NUM_RELAYS 4

// Global variables
volatile sig_atomic_t program_running = 1;
int current_relay = 0;

// Function prototypes
int initialize_gpio();
int set_relay_state(int relay, int state);
int activate_relay(int relay);
int deactivate_relay(int relay);
void irrigation_cycle();
void timer_callback();
void signal_handler(int signal);
void cleanup();

int main() {
    // Open syslog for logging
    openlog("irrigation_system", LOG_PID | LOG_CONS, LOG_USER);

    // Initialize pigpio
    if (initialize_gpio() != 0) {
        syslog(LOG_ERR, "Failed to initialize pigpio. Exiting.");
        closelog();
        return 1;
    }

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up the timer callback function
    gpioSetTimerFuncEx(0, TIMER_INTERVAL, timer_callback, NULL);

    // Main loop
    while (program_running) {
        irrigation_cycle();
        gpioDelay(1000); // Sleep for 1 second
    }

    // Cleanup and exit
    cleanup();
    closelog();
    return 0;
}

// Function to initialize the pigpio library and set GPIO pins as outputs
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return 1;
    }

    // Set all relay pins as outputs
    gpioSetMode(RELAY1_PIN, PI_OUTPUT);
    gpioSetMode(RELAY2_PIN, PI_OUTPUT);
    gpioSetMode(RELAY3_PIN, PI_OUTPUT);
    gpioSetMode(RELAY4_PIN, PI_OUTPUT);

    // Initialize all relays to OFF (HIGH)
    if (set_relay_state(1, 1) != 0) return 1;
    if (set_relay_state(2, 1) != 0) return 1;
    if (set_relay_state(3, 1) != 0) return 1;
    if (set_relay_state(4, 1) != 0) return 1;

    return 0;
}

// Function to set the state of a relay (HIGH or LOW)
int set_relay_state(int relay, int state) {
    int pin;

    switch (relay) {
        case 1:
            pin = RELAY1_PIN;
            break;
        case 2:
            pin = RELAY2_PIN;
            break;
        case 3:
            pin = RELAY3_PIN;
            break;
        case 4:
            pin = RELAY4_PIN;
            break;
        default:
            syslog(LOG_ERR, "Invalid relay number: %d", relay);
            return 1;
    }

    gpioWrite(pin, state);
    return 0;
}

// Function to activate a relay (set LOW)
int activate_relay(int relay) {
    return set_relay_state(relay, 0);
}

// Function to deactivate a relay (set HIGH)
int deactivate_relay(int relay) {
    return set_relay_state(relay, 1);
}

// Function to perform the irrigation cycle
void irrigation_cycle() {
    // Activate the current relay
    if (activate_relay(current_relay) != 0) {
        syslog(LOG_ERR, "Failed to activate relay %d", current_relay);
    }

    // Wait for the irrigation duration
    gpioDelay(IRRIGATION_DURATION * 1000); // Convert seconds to milliseconds

    // Deactivate the current relay
    if (deactivate_relay(current_relay) != 0) {
        syslog(LOG_ERR, "Failed to deactivate relay %d", current_relay);
    }

    // Increment the relay index (wrap around if necessary)
    current_relay = (current_relay + 1) % NUM_RELAYS;

    // Wait for the pause duration
    gpioDelay(PAUSE_DURATION * 1000); // Convert seconds to milliseconds
}

// Timer callback function
void timer_callback() {
    // This function is called every TIMER_INTERVAL seconds.
    // It is not used in this implementation, but it is kept for future expansion.
    // For example, you could add a sensor reading here and adjust the irrigation cycle accordingly.
    syslog(LOG_INFO, "Timer callback triggered (not used in this implementation).");
}

// Signal handler function
void signal_handler(int signal) {
    syslog(LOG_INFO, "Signal received: %d. Shutting down gracefully.", signal);
    program_running = 0;
}

// Cleanup function to deactivate all relays and terminate pigpio
void cleanup() {
    // Deactivate all relays
    deactivate_relay(1);
    deactivate_relay(2);
    deactivate_relay(3);
    deactivate_relay(4);

    // Terminate pigpio
    gpioTerminate();
    syslog(LOG_INFO, "pigpio terminated.");
}

