#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <sys/stat.h>
#include <sys/types.h>

// MPU6050 I2C address
#define MPU6050_ADDR 0x68

// MPU6050 registers
#define MPU6050_REG_PWR_MGMT_1 0x6B
#define MPU6050_REG_ACCEL_XOUT_H 0x3B
#define MPU6050_REG_ACCEL_YOUT_H 0x3D
#define MPU6050_REG_ACCEL_ZOUT_H 0x3F

// Circular buffer size
#define BUFFER_SIZE 100

// Sampling rate (Hz)
#define SAMPLING_RATE 100

// I2C device file
#define I2C_DEVICE "/dev/i2c-1"

// Signal file path
#define SIGNAL_FILE "/sys/kernel/mpu6050_accel/latest"

// Global variables
static int i2c_fd = -1;
static volatile sig_atomic_t terminate = 0;
static int current_index = 0;

// Structure to hold acceleration data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} accel_data_t;

// Circular buffer
static accel_data_t accel_buffer[BUFFER_SIZE];

// Function prototypes
int i2c_read_bytes(int fd, uint8_t reg, uint8_t *data, int len);
int i2c_write_byte(int fd, uint8_t reg, uint8_t value);
int read_acceleration(int fd, int16_t *x, int16_t *y, int16_t *z);
void store_data(accel_data_t data);
int get_latest_data(accel_data_t *data);
void signal_handler(int sig);
int create_signal_file();
void cleanup();

// I2C read function
int i2c_read_bytes(int fd, uint8_t reg, uint8_t *data, int len) {
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }
    if (read(fd, data, len) != len) {
        perror("Failed to read data");
        return -1;
    }
    return 0;
}

// I2C write function
int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("Failed to write data");
        return -1;
    }
    return 0;
}

// Read acceleration data from MPU6050
int read_acceleration(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t data[6];

    if (i2c_read_bytes(fd, MPU6050_REG_ACCEL_XOUT_H, data, 6) != 0) {
        fprintf(stderr, "Error reading acceleration data\n");
        return -1;
    }

    *x = (int16_t)((data[0] << 8) | data[1]);
    *y = (int16_t)((data[2] << 8) | data[3]);
    *z = (int16_t)((data[4] << 8) | data[5]);

    return 0;
}

// Store data in circular buffer
void store_data(accel_data_t data) {
    accel_buffer[current_index] = data;
    current_index = (current_index + 1) % BUFFER_SIZE;
}

// Get the most recent data from the circular buffer
int get_latest_data(accel_data_t *data) {
    if (i2c_fd == -1) {
        fprintf(stderr, "I2C device not initialized\n");
        return -1;
    }

    int16_t x, y, z;
    if (read_acceleration(i2c_fd, &x, &y, &z) != 0) {
        fprintf(stderr, "Error reading acceleration data\n");
        return -1;
    }

    data->x = x;
    data->y = y;
    data->z = z;

    return 0;
}

// Signal handler
void signal_handler(int sig) {
    fprintf(stderr, "Signal received: %d. Terminating...\n", sig);
    terminate = 1;
}

// Create signal file
int create_signal_file() {
    int fd = open(SIGNAL_FILE, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (fd == -1) {
        perror("Failed to create signal file");
        return -1;
    }
    close(fd);
    return 0;
}

// Cleanup function
void cleanup() {
    fprintf(stderr, "Cleaning up...\n");
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    // No need to delete the signal file, it's automatically removed on process exit
    fprintf(stderr, "Cleanup complete.\n");
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Wake up MPU6050
    if (i2c_write_byte(i2c_fd, MPU6050_REG_PWR_MGMT_1, 0) != 0) {
        fprintf(stderr, "Failed to wake up MPU6050\n");
        close(i2c_fd);
        return 1;
    }

    // Create signal file
    if (create_signal_file() != 0) {
        fprintf(stderr, "Failed to create signal file\n");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    struct timespec sleep_time;
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = 10000000; // 10ms (100Hz)

    accel_data_t latest_data;

    while (!terminate) {
        if (get_latest_data(&latest_data) == 0) {
            store_data(latest_data);
        } else {
            fprintf(stderr, "Failed to read latest data\n");
        }

        nanosleep(&sleep_time, NULL);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

