    int result;
    struct timespec ts;

    // Get current time
    if (clock_gettime(CLOCK_MONOTONIC, &ts) == -1) {
        perror("clock_gettime");
        return -1;
    }

    // Calculate the time to toggle the relay
    ts.tv_sec += interval;

    // Toggle the relay state
