        return -1;
    }

    // Wait for the specified interval
    while (program_running) {
        struct timespec current_time;
        if (clock_gettime(CLOCK_MONOTONIC, &current_time) == -1) {
            perror("clock_gettime");
            return -1;
        }

        if (current_time.tv_sec > ts.tv_sec) {
            break;
        }
    }

    return 0;
}

