#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define SOUND_SENSOR_PIN 17
#define RELAY_PIN 27

// Define debounce time (in milliseconds)
#define DEBOUNCE_TIME 500

// Define relay activation time (in seconds)
#define RELAY_ACTIVATION_TIME 3

// Global variables
static volatile int running = 1;
static volatile unsigned long last_activation_time = 0;

// Function prototypes
int initialize_gpio();
int read_sound_sensor();
void activate_relay();
void log_alarm();
void cleanup_gpio();
void signal_handler(int signal);

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    gpioSetMode(SOUND_SENSOR_PIN, PI_INPUT);
    gpioSetMode(RELAY_PIN, PI_OUTPUT);
    gpioWrite(RELAY_PIN, 0); // Ensure relay is initially off

    return 0; // Indicate success
}

// Function to read the sound sensor
int read_sound_sensor() {
    return gpioRead(SOUND_SENSOR_PIN);
}

// Function to activate the relay
void activate_relay() {
    gpioWrite(RELAY_PIN, 1); // Turn relay on
    gpioDelay(RELAY_ACTIVATION_TIME * 1000000); // Wait for 3 seconds
    gpioWrite(RELAY_PIN, 0); // Turn relay off
}

// Function to log the alarm event
void log_alarm() {
    FILE *fp = fopen("alarm_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening alarm_log.txt for writing\n");
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char s[64];
    strftime(s, sizeof(s), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s: Sound event detected\n", s);
    fclose(fp);
}

// Function to cleanup GPIO pins
void cleanup_gpio() {
    gpioWrite(RELAY_PIN, 0); // Ensure relay is off
    gpioTerminate();
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    running = 0;
    cleanup_gpio();
    exit(0);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1; // Exit if initialization fails
    }

    printf("Sound sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        // Read sound sensor
        int sound_detected = read_sound_sensor();

        // Debounce and activate relay if sound is detected
        if (sound_detected == 0) { // Assuming sound sensor outputs 0 when sound is detected
            unsigned long current_time = gpioTick();
            if (current_time - last_activation_time > DEBOUNCE_TIME * 1000) {
                printf("Sound event detected! Activating relay.\n");
                activate_relay();
                log_alarm();
                last_activation_time = current_time;
            }
        }

        gpioDelay(100000); // Poll every 100ms
    }

    return 0;
}

