#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define PWR_MGMT_1   0x6B
#define GYRO_XOUT_H  0x43
#define GYRO_YOUT_H  0x45
#define GYRO_ZOUT_H  0x47

// Circular buffer size
#define BUFFER_SIZE 100

// Structure to hold gyroscope data
typedef struct {
    float x;
    float y;
    float z;
} gyro_data_t;

// Circular buffer structure
typedef struct {
    gyro_data_t data[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

// Global variables
int i2c_handle;
circular_buffer_t gyro_buffer;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int init_mpu6050();
int read_gyro_data(gyro_data_t *data);
void add_to_buffer(circular_buffer_t *buffer, gyro_data_t data);
gyro_data_t get_average(circular_buffer_t *buffer);
float calculate_magnitude(gyro_data_t data);
void check_threshold(gyro_data_t data, void (*callback)(gyro_data_t));
void threshold_exceeded_callback(gyro_data_t data);
void signal_handler(int signal);

// Initialize the circular buffer
void init_circular_buffer(circular_buffer_t *buffer) {
    buffer->head = 0;
    buffer->count = 0;
}

// Initialize MPU-6050
int init_mpu6050() {
    // Wake up the MPU-6050 (clear sleep bit)
    if (i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0) < 0) {
        fprintf(stderr, "Error: Could not wake up MPU-6050\n");
        return -1;
    }
    return 0;
}

// Read gyroscope data
int read_gyro_data(gyro_data_t *data) {
    char buf[6];
    int16_t gyro_x, gyro_y, gyro_z;

    if (i2cReadI2CBlockData(i2c_handle, GYRO_XOUT_H, buf, 6) != 6) {
        fprintf(stderr, "Error: Could not read gyroscope data\n");
        return -1;
    }

    gyro_x = (buf[0] << 8) | buf[1];
    gyro_y = (buf[2] << 8) | buf[3];
    gyro_z = (buf[4] << 8) | buf[5];

    // Convert to degrees/second (assuming sensitivity of 131 LSB/deg/s)
    data->x = (float)gyro_x / 131.0;
    data->y = (float)gyro_y / 131.0;
    data->z = (float)gyro_z / 131.0;

    return 0;
}

// Add data to the circular buffer
void add_to_buffer(circular_buffer_t *buffer, gyro_data_t data) {
    buffer->data[buffer->head] = data;
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count < BUFFER_SIZE) {
        buffer->count++;
    }
}

// Get the average of the data in the circular buffer
gyro_data_t get_average(circular_buffer_t *buffer) {
    gyro_data_t avg = {0, 0, 0};
    if (buffer->count == 0) return avg; // Avoid division by zero

    for (int i = 0; i < buffer->count; i++) {
        avg.x += buffer->data[i].x;
        avg.y += buffer->data[i].y;
        avg.z += buffer->data[i].z;
    }

    avg.x /= buffer->count;
    avg.y /= buffer->count;
    avg.z /= buffer->count;

    return avg;
}

// Calculate the magnitude of the gyroscope data
float calculate_magnitude(gyro_data_t data) {
    return sqrt(data.x * data.x + data.y * data.y + data.z * data.z);
}

// Check if the magnitude exceeds the threshold
void check_threshold(gyro_data_t data, void (*callback)(gyro_data_t)) {
    float magnitude = calculate_magnitude(data);
    if (magnitude > 50.0) {
        callback(data);
    }
}

// Threshold exceeded callback function
void threshold_exceeded_callback(gyro_data_t data) {
    printf("Threshold exceeded! Magnitude: %.2f deg/s\n", calculate_magnitude(data));
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C device\n");
        gpioTerminate();
        return 1;
    }

    // Initialize MPU-6050
    if (init_mpu6050() < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize circular buffer
    init_circular_buffer(&gyro_buffer);

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    gyro_data_t gyro_data;
    gyro_data_t avg_data;

    // Main loop
    while (program_running) {
        // Read gyroscope data
        if (read_gyro_data(&gyro_data) == 0) {
            // Add data to the circular buffer
            add_to_buffer(&gyro_buffer, gyro_data);

            // Calculate average
            avg_data = get_average(&gyro_buffer);

            // Check threshold
            check_threshold(avg_data, threshold_exceeded_callback);
        } else {
            fprintf(stderr, "Error reading gyro data, retrying...\n");
        }

        // Delay for 10ms (100Hz sampling rate)
        gpioDelay(10000); // 10000 microseconds = 10 milliseconds
    }

    // Close I2C device
    i2cClose(i2c_handle);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

