    gyro_data_t avg_data;

    // Main loop
    while (program_running) {
        // Read gyroscope data
        if (read_gyro_data(&gyro_data) == 0) {
            // Add data to the circular buffer
            add_to_buffer(&gyro_buffer, gyro_data);

            // Calculate average
            avg_data = get_average(&gyro_buffer);

            // Check threshold
            check_threshold(avg_data, threshold_exceeded_callback);
        } else {
            fprintf(stderr, "Error reading gyro data, retrying...\n");
        }

        // Delay for 10ms (100Hz sampling rate)
        gpioDelay(10000); // 10000 microseconds = 10 milliseconds
    }

    // Close I2C device
    i2cClose(i2c_handle);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

