#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <errno.h>
#include <sys/select.h>
#include <sys/time.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <pigpio.h>

// Define constants
#define UART_DEVICE "/dev/serial0"
#define BAUD_RATE 9600
#define MHZ19B_COMMAND {0xFF, 0x01, 0x86, 0x00, 0x00, 0x00, 0x00, 0x00, 0x79}
#define CHECKSUM_ERROR -1
#define TIMEOUT_ERROR -2
#define INVALID_DATA_ERROR -3
#define MAX_RETRIES 3
#define SAMPLE_INTERVAL 5 // seconds

// Global variables
int uart_handle;
FILE *co2_log_file;
FILE *co2_error_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    long long timestamp;
    int ppm;
    int error;
} sensor_data_t;

// Function prototypes
int init_uart();
int send_command(int uart_handle, const unsigned char *command, int command_len);
int read_response(int uart_handle, unsigned char *response, int response_len, int timeout_ms);
int calculate_checksum(const unsigned char *data, int len);
int validate_checksum(const unsigned char *data, int len);
int parse_co2_data(const unsigned char *response, int *ppm);
int log_data(sensor_data_t data);
int log_error(const char *message);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize UART
int init_uart() {
    uart_handle = serOpen(UART_DEVICE, BAUD_RATE, 0); //0 for no flags
    if (uart_handle < 0) {
        fprintf(stderr, "Error opening UART: %s\n", UART_DEVICE);
        return -1;
    }
    return 0;
}

// Send command to MH-Z19B sensor
int send_command(int uart_handle, const unsigned char *command, int command_len) {
    int bytes_written = serWrite(uart_handle, (char *)command, command_len);
    if (bytes_written != command_len) {
        fprintf(stderr, "Error writing to UART: %d bytes written, expected %d\n", bytes_written, command_len);
        return -1;
    }
    return 0;
}

// Read response from MH-Z19B sensor with timeout
int read_response(int uart_handle, unsigned char *response, int response_len, int timeout_ms) {
    fd_set readfds;
    struct timeval timeout;
    int bytes_read = 0;
    int total_bytes_read = 0;

    while (total_bytes_read < response_len) {
        FD_ZERO(&readfds);
        FD_SET(uart_handle, &readfds);

        timeout.tv_sec = timeout_ms / 1000;
        timeout.tv_usec = (timeout_ms % 1000) * 1000;

        int select_result = select(uart_handle + 1, &readfds, NULL, NULL, &timeout);

        if (select_result == -1) {
            perror("select");
            return -1;
        } else if (select_result == 0) {
            // Timeout occurred
            return TIMEOUT_ERROR;
        } else {
            bytes_read = serRead(uart_handle, (char *)(response + total_bytes_read), response_len - total_bytes_read);
            if (bytes_read > 0) {
                total_bytes_read += bytes_read;
            } else if (bytes_read < 0) {
                fprintf(stderr, "Error reading from UART: %s\n", strerror(errno));
                return -1;
            }
        }
    }

    return 0;
}

// Calculate checksum
int calculate_checksum(const unsigned char *data, int len) {
    int checksum = 0;
    for (int i = 1; i < len; i++) {
        checksum += data[i];
    }
    checksum = 0xFF - checksum + 1;
    return checksum;
}

// Validate checksum
int validate_checksum(const unsigned char *data, int len) {
    int calculated_checksum = calculate_checksum(data, len);
    if (calculated_checksum != data[len - 1]) {
        return CHECKSUM_ERROR;
    }
    return 0;
}

// Parse CO2 data
int parse_co2_data(const unsigned char *response, int *ppm) {
    if (response[0] != 0xFF || response[1] != 0x86) {
        return INVALID_DATA_ERROR;
    }

    *ppm = (response[2] << 8) | response[3];
    return 0;
}

// Log data to file
int log_data(sensor_data_t data) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    long long timestamp = (long long)ts.tv_sec * 1000000 + ts.tv_nsec / 1000;

    if (co2_log_file == NULL) {
        co2_log_file = fopen("co2_log.json", "a");
        if (co2_log_file == NULL) {
            fprintf(stderr, "Error opening co2_log.json: %s\n", strerror(errno));
            return -1;
        }
    }

    fprintf(co2_log_file, "{\"timestamp\":%lld,\"ppm\":%d,\"error\":%d}\n", timestamp, data.ppm, data.error);
    fflush(co2_log_file); // Ensure data is written immediately
    printf("{\"timestamp\":%lld,\"ppm\":%d,\"error\":%d}\n", timestamp, data.ppm, data.error);
    return 0;
}

// Log error to file
int log_error(const char *message) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    long long timestamp = (long long)ts.tv_sec * 1000000 + ts.tv_nsec / 1000;

    if (co2_error_file == NULL) {
        co2_error_file = fopen("co2_error.log", "a");
        if (co2_error_file == NULL) {
            fprintf(stderr, "Error opening co2_error.log: %s\n", strerror(errno));
            return -1;
        }
    }

    fprintf(co2_error_file, "{\"timestamp\":%lld,\"message\":\"%s\"}\n", timestamp, message);
    fflush(co2_error_file);
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize UART
    if (init_uart() != 0) {
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        unsigned char command[] = MHZ19B_COMMAND;
        unsigned char response[9];
        int ppm;
        int error = 0;
        int retries = 0;

        // Send command
        if (send_command(uart_handle, command, sizeof(command)) != 0) {
            log_error("Failed to send command");
            error = -1;
            goto log_data_section;
        }

        // Read response with retries and timeout
        while (retries < MAX_RETRIES) {
            int result = read_response(uart_handle, response, sizeof(response), 100); // 100ms timeout
            if (result == 0) {
                break; // Success
            } else if (result == TIMEOUT_ERROR) {
                log_error("Timeout reading response");
                error = -1;
                goto log_data_section;
            } else {
                log_error("Error reading response");
                retries++;
                usleep(100000); // 100ms delay
            }
        }

        if (retries == MAX_RETRIES) {
            log_error("Max retries reached, skipping reading");
            error = -1;
            goto log_data_section;
        }

        // Validate checksum
        if (validate_checksum(response, sizeof(response)) != 0) {
            log_error("Checksum mismatch");
            error = CHECKSUM_ERROR;
            goto log_data_section;
        }

        // Parse CO2 data
        if (parse_co2_data(response, &ppm) != 0) {
            log_error("Invalid data received");
            error = INVALID_DATA_ERROR;
            goto log_data_section;
        }

    log_data_section:
        // Log data
        sensor_data_t data = {0};
        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);
        data.timestamp = (long long)ts.tv_sec * 1000000 + ts.tv_nsec / 1000;
        data.ppm = ppm;
        data.error = error;
        if (log_data(data) != 0) {
            fprintf(stderr, "Error logging data\n");
        }

        sleep(SAMPLE_INTERVAL);
    }

    // Cleanup
    serClose(uart_handle);
    if (co2_log_file != NULL) {
        fclose(co2_log_file);
    }
    if (co2_error_file != NULL) {
        fclose(co2_error_file);
    }
    gpioTerminate();

    return 0;
}

