#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <wiringPi.h>
#include <wiringPiI2C.h>
#include <math.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// HMC5883L I2C address
#define HMC5883L_ADDR 0x1E

// HMC5883L register addresses
#define HMC5883L_CONFIG_A 0x00
#define HMC5883L_CONFIG_B 0x01
#define HMC5883L_MODE 0x02
#define HMC5883L_DATA_X_MSB 0x03
#define HMC5883L_DATA_X_LSB 0x04
#define HMC5883L_DATA_Z_MSB 0x05
#define HMC5883L_DATA_Z_LSB 0x06
#define HMC5883L_DATA_Y_MSB 0x07
#define HMC5883L_DATA_Y_LSB 0x08

// GPIO pin for output
#define GPIO_PIN 17

// Hard-iron compensation offsets
#define HARD_IRON_X 100
#define HARD_IRON_Y -50

// Target heading
#define TARGET_HEADING 90.0

// Deviation threshold
#define DEVIATION_THRESHOLD 10.0

// Circular buffer size
#define BUFFER_SIZE 100

// Global variables
int i2c_fd;
volatile sig_atomic_t program_running = 1;

// Circular buffer
float heading_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int init_hmc5883l();
int read_magnetometer(int16_t *x, int16_t *y, int16_t *z);
float calculate_heading(int16_t x, int16_t y);
float apply_hard_iron(float x, float y);
void update_circular_buffer(float heading);
float get_average_heading();
void set_gpio_output(bool high);
void signal_handler(int signal);

// Function to initialize the HMC5883L
int init_hmc5883l() {
    // Set configuration register A (0x00) to 0x70 (8-average, 15 Hz, normal measurement)
    if (wiringPiI2CWriteReg8(i2c_fd, HMC5883L_CONFIG_A, 0x70) < 0) {
        fprintf(stderr, "Error writing to config register A: %s\n", strerror(errno));
        return -1;
    }

    // Set configuration register B (0x01) to 0xA0 (Gain = 5)
    if (wiringPiI2CWriteReg8(i2c_fd, HMC5883L_CONFIG_B, 0xA0) < 0) {
        fprintf(stderr, "Error writing to config register B: %s\n", strerror(errno));
        return -1;
    }

    // Set mode register (0x02) to 0x00 (Continuous measurement mode)
    if (wiringPiI2CWriteReg8(i2c_fd, HMC5883L_MODE, 0x00) < 0) {
        fprintf(stderr, "Error writing to mode register: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Function to read magnetometer data
int read_magnetometer(int16_t *x, int16_t *y, int16_t *z) {
    int x_msb, x_lsb, y_msb, y_lsb, z_msb, z_lsb;

    x_msb = wiringPiI2CReadReg8(i2c_fd, HMC5883L_DATA_X_MSB);
    x_lsb = wiringPiI2CReadReg8(i2c_fd, HMC5883L_DATA_X_LSB);
    z_msb = wiringPiI2CReadReg8(i2c_fd, HMC5883L_DATA_Z_MSB);
    z_lsb = wiringPiI2CReadReg8(i2c_fd, HMC5883L_DATA_Z_LSB);
    y_msb = wiringPiI2CReadReg8(i2c_fd, HMC5883L_DATA_Y_MSB);
    y_lsb = wiringPiI2CReadReg8(i2c_fd, HMC5883L_DATA_Y_LSB);

    if (x_msb < 0 || x_lsb < 0 || y_msb < 0 || y_lsb < 0 || z_msb < 0 || z_lsb < 0) {
        fprintf(stderr, "Error reading magnetometer data: %s\n", strerror(errno));
        return -1;
    }

    *x = (int16_t)((x_msb << 8) | x_lsb);
    *y = (int16_t)((y_msb << 8) | y_lsb);
    *z = (int16_t)((z_msb << 8) | z_lsb);

    return 0;
}

// Function to calculate heading in degrees
float calculate_heading(int16_t x, int16_t y) {
    float heading = atan2(y, x) * 180 / M_PI;
    if (heading < 0) {
        heading += 360;
    }
    return heading;
}

// Function to apply hard-iron compensation
float apply_hard_iron(float x, float y) {
    return x - HARD_IRON_X, y - HARD_IRON_Y;
}

// Function to update the circular buffer
void update_circular_buffer(float heading) {
    heading_buffer[buffer_index] = heading;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Function to get the average heading from the circular buffer
float get_average_heading() {
    float sum = 0.0;
    for (int i = 0; i < BUFFER_SIZE; i++) {
        sum += heading_buffer[i];
    }
    return sum / BUFFER_SIZE;
}

// Function to set the GPIO output
void set_gpio_output(bool high) {
    digitalWrite(GPIO_PIN, high ? HIGH : LOW);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

int main() {
    // Initialize wiringPi
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "Error initializing wiringPi: %s\n", strerror(errno));
        return 1;
    }

    // Initialize I2C
    i2c_fd = wiringPiI2CSetup(HMC5883L_ADDR);
    if (i2c_fd == -1) {
        fprintf(stderr, "Error initializing I2C: %s\n", strerror(errno));
        return 1;
    }

    // Initialize HMC5883L
    if (init_hmc5883l() == -1) {
        fprintf(stderr, "Error initializing HMC5883L.\n");
        return 1;
    }

    // Set GPIO pin as output
    pinMode(GPIO_PIN, OUTPUT);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int16_t x, y, z;
    float heading, compensated_heading, average_heading;
    bool deviation;

    printf("Starting heading monitoring...\n");

    while (program_running) {
        // Read magnetometer data
        if (read_magnetometer(&x, &y, &z) == -1) {
            fprintf(stderr, "Error reading magnetometer data. Retrying...\n");
            delay(10); // Small delay before retrying
            continue;
        }

        // Calculate heading
        heading = calculate_heading(x, y);

        // Apply hard-iron compensation
        compensated_heading = apply_hard_iron(heading, heading);

        // Update circular buffer
        update_circular_buffer(compensated_heading);

        // Calculate average heading
        average_heading = get_average_heading();

        // Check for deviation
        deviation = (fabs(average_heading - TARGET_HEADING) > DEVIATION_THRESHOLD);

        // Set GPIO output
        set_gpio_output(deviation);

        // Print heading and deviation status
        printf("Heading: %.2f, Deviation: %s\n", average_heading, deviation ? "HIGH" : "LOW");

        // Delay for 100ms
        delay(100);
    }

    // Clean up GPIO
