#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define BH1750_ADDR 0x23
#define CONTINUOUS_HIGH_RES_MODE 0x10
#define RED_GPIO 17
#define GREEN_GPIO 27
#define BLUE_GPIO 22
#define LOG_FILE "lighting_log.txt"

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_bh1750(int i2c_fd);
void control_rgb_lamp(int lux);
void log_data(FILE *log_file, int lux);
void signal_handler(int signal);
int setup_gpio(int gpio, int mode);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read lux value from BH1750 sensor
int read_bh1750(int i2c_fd) {
    if (i2cWriteByteData(i2c_fd, 0x00, CONTINUOUS_HIGH_RES_MODE) != 0) {
        fprintf(stderr, "Error: Failed to set BH1750 to continuous high-res mode.\n");
        return -1;
    }
    gpioDelay(120); // Wait for measurement (at least 120ms)

    int raw_value = i2cReadWordData(i2c_fd, 0x00);
    if (raw_value < 0) {
        fprintf(stderr, "Error: Failed to read data from BH1750.\n");
        return -1;
    }

    // BH1750 returns big-endian, pigpio returns little-endian
    raw_value = ((raw_value & 0xFF00) >> 8) | ((raw_value & 0x00FF) << 8);

    return raw_value / 1.2; // Convert to lux
}

// Function to control RGB lamp based on lux value
void control_rgb_lamp(int lux) {
    if (lux < 50) {
        setup_gpio(RED_GPIO, PI_OUTPUT);
        setup_gpio(GREEN_GPIO, PI_INPUT); // Ensure GREEN is input
        setup_gpio(BLUE_GPIO, PI_INPUT);  // Ensure BLUE is input
        gpioWrite(RED_GPIO, 1); // Turn on RED
    } else if (lux >= 50 && lux < 150) {
        setup_gpio(RED_GPIO, PI_INPUT); // Ensure RED is input
        setup_gpio(GREEN_GPIO, PI_OUTPUT);
        setup_gpio(BLUE_GPIO, PI_INPUT);  // Ensure BLUE is input
        gpioWrite(GREEN_GPIO, 1); // Turn on GREEN
    } else if (lux >= 150 && lux < 300) {
        setup_gpio(RED_GPIO, PI_INPUT); // Ensure RED is input
        setup_gpio(GREEN_GPIO, PI_INPUT); // Ensure GREEN is input
        setup_gpio(BLUE_GPIO, PI_OUTPUT);
        gpioWrite(BLUE_GPIO, 1); // Turn on BLUE
    } else {
        setup_gpio(RED_GPIO, PI_OUTPUT);
        setup_gpio(GREEN_GPIO, PI_OUTPUT);
        setup_gpio(BLUE_GPIO, PI_OUTPUT);
        gpioWrite(RED_GPIO, 1);   // Turn on RED
        gpioWrite(GREEN_GPIO, 1); // Turn on GREEN
        gpioWrite(BLUE_GPIO, 1);  // Turn on BLUE
    }
}

// Function to log data to file
void log_data(FILE *log_file, int lux) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %d\n", timestamp, lux);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Function to set up GPIO pin
int setup_gpio(int gpio, int mode) {
    if (gpioSetMode(gpio, mode) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d to mode %d.\n", gpio, mode);
        return -1;
    }
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    // Open I2C bus
    i2c_fd = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus. Check if the sensor is connected and the address is correct.\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file.\n");
        i2cClose(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        int lux = read_bh1750(i2c_fd);
        if (lux >= 0) {
            control_rgb_lamp(lux);
            log_data(log_file, lux);
        } else {
            fprintf(stderr, "Error: Failed to read lux value. Retrying...\n");
        }

        gpioDelay(1000); // Wait 1 second
    }

    // Cleanup
    i2cClose(i2c_fd);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

