#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define MOTOR_A_IN1 17
#define MOTOR_A_IN2 18
#define MOTOR_B_IN3 22
#define MOTOR_B_IN4 23

// Define PWM frequency
#define PWM_FREQUENCY 1000

// Define proportional gain
#define Kp 2.0

// Global variables for graceful shutdown
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, stopping motors and exiting...\n", signal);
    program_running = 0;
}

// Function to set motor direction and speed
void set_motor_speed(int motor, int direction, int speed) {
    int in1, in2;

    if (motor == 'A') {
        in1 = MOTOR_A_IN1;
        in2 = MOTOR_A_IN2;
    } else if (motor == 'B') {
        in1 = MOTOR_B_IN3;
        in2 = MOTOR_B_IN4;
    } else {
        fprintf(stderr, "Error: Invalid motor identifier: %c\n", motor);
        return;
    }

    // Set direction
    if (direction == 1) { // Forward
        gpioWrite(in1, 1);
        gpioWrite(in2, 0);
    } else if (direction == -1) { // Backward
        gpioWrite(in1, 0);
        gpioWrite(in2, 1);
    } else { // Stop
        gpioWrite(in1, 0);
        gpioWrite(in2, 0);
    }

    // Set speed (PWM duty cycle)
    gpioPWM(in2, speed);
}

// Function to calculate proportional speed
int calculate_proportional_speed(int distance) {
    int speed = (int)(Kp * (50.0 - distance));
    if (speed < 0) {
        speed = 0;
    } else if (speed > 255) {
        speed = 255;
    }
    return speed;
}

int main(int argc, char *argv[]) {
    int distance_a, distance_b;

    // Check command-line arguments
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <distance_a> <distance_b>\n", argv[0]);
        return 1;
    }

    // Parse command-line arguments
    distance_a = atoi(argv[1]);
    distance_b = atoi(argv[2]);

    // Validate distance values
    if (distance_a < 10 || distance_a > 100 || distance_b < 10 || distance_b > 100) {
        fprintf(stderr, "Error: Distance values must be between 10 and 100 cm.\n");
        return 1;
    }

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(MOTOR_A_IN1, PI_OUTPUT);
    gpioSetMode(MOTOR_A_IN2, PI_OUTPUT);
    gpioSetMode(MOTOR_B_IN3, PI_OUTPUT);
    gpioSetMode(MOTOR_B_IN4, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(MOTOR_A_IN2, PWM_FREQUENCY);
    gpioSetPWMfrequency(MOTOR_B_IN4, PWM_FREQUENCY);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main control loop
    while (program_running) {
        // Calculate proportional speeds
        int speed_a = calculate_proportional_speed(distance_a);
        int speed_b = calculate_proportional_speed(distance_b);

        // Set motor speeds
        set_motor_speed('A', 1, speed_a); // Motor A forward
        set_motor_speed('B', 1, speed_b); // Motor B forward

        // Print current distances and speeds
        printf("Distance A: %d cm, Speed A: %d\n", distance_a, speed_a);
        printf("Distance B: %d cm, Speed B: %d\n", distance_b, speed_b);

        // Simulate distance readings (replace with actual sensor readings)
        distance_a = (distance_a + 1) % 91 + 10; // Cycle between 10 and 100
        distance_b = (distance_b + 2) % 91 + 10; // Cycle between 10 and 100

        // Wait for 100 ms
        gpioDelay(100000); // 100 ms
    }

    // Stop motors
    set_motor_speed('A', 0, 0); // Motor A stop
    set_motor_speed('B', 0, 0); // Motor B stop

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

