#define LOCK_BUTTON 24
#define UNLOCK_BUTTON 23

// Define the number of steps for a full rotation (28BYJ-48)
#define STEPS_PER_ROTATION 2048.0

// Define the number of steps to lock/unlock the door (quarter turn)
#define LOCK_UNLOCK_STEPS 512

