#define SERVO_PIN 18
#define PWM_CHIP 2
#define PWM_NUM 0
#define PWM_PERIOD 20000 // 20ms
#define LOG_FILE "solar_tracker.log"

// Global variables
static volatile bool running = true;
static int i2c_fd;
static FILE *log_file;

// Function prototypes
int init_i2c(int addr);
int read_raw_data(int fd, int reg);
void read_sensor_data(int fd, int *accel_x, int *accel_y, int *accel_z, int *gyro_x, int *gyro_y, int *gyro_z);
void calculate_pitch_roll(int accel_x, int accel_y, int accel_z, float *pitch, float *roll);
int set_servo_angle(int angle);
void log_data(float pitch, float roll, int angle);
void signal_handler(int sig);

// I2C initialization function
int init_i2c(int addr) {
    int fd = wiringPiI2CSetup(addr);
    if (fd == -1) {
        fprintf(stderr, "Error initializing I2C: %s\n", strerror(errno));
        return -1;
    }

    // Wake up the MPU6050
    if (wiringPiI2CWriteReg8(fd, PWR_MGMT_1, 0) < 0) {
        fprintf(stderr, "Error writing to PWR_MGMT_1: %s\n", strerror(errno));
        return -1;
    }

    // Configure accelerometer range to +/- 2g
    if (wiringPiI2CWriteReg8(fd, ACCEL_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error writing to ACCEL_CONFIG: %s\n", strerror(errno));
        return -1;
    }

    // Configure gyroscope range to +/- 250 degrees/sec
    if (wiringPiI2CWriteReg8(fd, GYRO_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error writing to GYRO_CONFIG: %s\n", strerror(errno));
        return -1;
    }

    return fd;
}

// Function to read raw sensor data with retry mechanism
int read_raw_data(int fd, int reg) {
    int retries = 0;
    int data = 0;
    while (retries < 3) {
        data = wiringPiI2CReadReg8(fd, reg);
        if (data >= 0) {
            return data;
        } else {
            fprintf(stderr, "I2C read error (reg 0x%02X), retrying...\n", reg);
            retries++;
            usleep(10000 * (1 << retries)); // Exponential backoff
        }
    }
    fprintf(stderr, "Failed to read register 0x%02X after multiple retries.\n", reg);
    return -1; // Indicate failure
}

// Function to read sensor data
void read_sensor_data(int fd, int *accel_x, int *accel_y, int *accel_z, int *gyro_x, int *gyro_y, int *gyro_z) {
    *accel_x = (read_raw_data(fd, ACCEL_XOUT_H) << 8) | read_raw_data(fd, ACCEL_XOUT_H + 1);
    *accel_y = (read_raw_data(fd, ACCEL_XOUT_H + 2) << 8) | read_raw_data(fd, ACCEL_XOUT_H + 3);
    *accel_z = (read_raw_data(fd, ACCEL_XOUT_H + 4) << 8) | read_raw_data(fd, ACCEL_XOUT_H + 5);
    *gyro_x = (read_raw_data(fd, GYRO_XOUT_H) << 8) | read_raw_data(fd, GYRO_XOUT_H + 1);
    *gyro_y = (read_raw_data(fd, GYRO_XOUT_H + 2) << 8) | read_raw_data(fd, GYRO_XOUT_H + 3);
    *gyro_z = (read_raw_data(fd, GYRO_XOUT_H + 4) << 8) | read_raw_data(fd, GYRO_XOUT_H + 5);
}

// Function to calculate pitch and roll
void calculate_pitch_roll(int accel_x, int accel_y, int accel_z, float *pitch, float *roll) {
    *pitch = atan2(accel_x, sqrt(accel_y * accel_y + accel_z * accel_z)) * 180 / M_PI;
    *roll = atan2(accel_y, sqrt(accel_x * accel_x + accel_z * accel_z)) * 180 / M_PI;
}

// Function to set servo angle using sysfs
int set_servo_angle(int angle) {
    char path[64];
    char value_str[4];
    int fd;

    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip%d/pwm%d/period", PWM_CHIP, PWM_NUM);
    fd = open(path, O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening PWM period file: %s\n", strerror(errno));
        return -1;
    }
    if (write(fd, "20000", strlen("20000")) < 0) {
        fprintf(stderr, "Error writing to PWM period file: %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);

    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip%d/pwm%d/duty_cycle", PWM_CHIP, PWM_NUM);
    fd = open(path, O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening PWM duty_cycle file: %s\n", strerror(errno));
        return -1;
    }

    snprintf(value_str, sizeof(value_str), "%d", (int)((angle / 180.0) * PWM_PERIOD));
    if (write(fd, value_str, strlen(value_str)) < 0) {
        fprintf(stderr, "Error writing to PWM duty_cycle file: %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);

    return 0;
}

// Function to log data to file
void log_data(float pitch, float roll, int angle) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "%d-%02d-%02d %02d:%02d:%02d,%.2f,%.2f,%d\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec,
            pitch, roll, angle);
    fflush(log_file);
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    running = false;
    printf("Received signal %d, shutting down...\n", sig);
}

int main() {
    int accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z;
    float pitch, roll;
    int servo_angle;

    // Initialize wiringPi
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "Error initializing wiringPi: %s\n", strerror(errno));
        return 1;
    }

    // Initialize I2C
    i2c_fd = init_i2c(MPU6050_ADDR);
    if (i2c_fd == -1) {
        return 1;
    }

    // Initialize PWM
    char export_path[64];
    snprintf(export_path, sizeof(export_path), "/sys/class/pwm/pwmchip%d/export", PWM_CHIP);
    int export_fd = open(export_path, O_WRONLY);
    if (export_fd < 0 && errno == ENOENT) {
        // PWM chip not exported, try to export it
        FILE *export_file = fopen("/sys/class/pwm/export", "w");
        if (export_file) {
            fprintf(export_file, "%d", PWM_CHIP);
            fclose(export_file);
            usleep(100000); // Wait for the chip to be exported
        } else {
            fprintf(stderr, "Error opening /sys/class/pwm/export: %s\n", strerror(errno));
            return 1;
        }
    } else if (export_fd < 0) {
        fprintf(stderr, "Error opening PWM export file: %s\n", strerror(errno));
        return 1;
    }
    close(export_fd);

    char enable_path[64];
    snprintf(enable_path, sizeof(enable_path), "/sys/class/pwm/pwmchip%d/pwm%d/enable", PWM_CHIP, PWM_NUM);
    int enable_fd = open(enable_path, O_WRONLY);
    if (enable_fd < 0) {
        fprintf(stderr, "Error opening PWM enable file: %s\n", strerror(errno));
        return 1;
    }
    if (write(enable_fd, "0", 1) < 0) {
        fprintf(stderr, "Error writing to PWM enable file: %s\n", strerror(errno));
        close(enable_fd);
        return 1;
    }
    close(enable_fd);

    char period_path[64];
    snprintf(period_path, sizeof(period_path), "/sys/class/pwm/pwmchip%d/pwm%d/period", PWM_CHIP, PWM_NUM);
    int period_fd = open(period_path, O_WRONLY);
    if (period_fd < 0) {
        fprintf(stderr, "Error opening PWM period file: %s\n", strerror(errno));
        return 1;
    }
    if (write(period_fd, "20000", strlen("20000")) < 0) {
        fprintf(stderr, "Error writing to PWM period file: %s\n", strerror(errno));
        close(period_fd);
        return 1;
    }
    close(period_fd);

    snprintf(enable_path, sizeof(enable_path), "/sys/class/pwm/pwmchip%d/pwm%d/enable", PWM_CHIP, PWM_NUM);
    enable_fd = open(enable_path, O_WRONLY);
    if (enable_fd < 0) {
        fprintf(stderr, "Error opening PWM enable file: %s\n", strerror(errno));
        return 1;
    }
    if (write(enable_fd, "1", 1) < 0) {
        fprintf(stderr, "Error writing to PWM enable file: %s\n", strerror(errno));
        close(enable_fd);
        return 1;
    }
    close(enable_fd);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        // Read sensor data
        read_sensor_data(i2c_fd, &accel_x, &accel_y, &accel_z, &gyro_x, &gyro_y, &gyro_z);

        // Calculate pitch and roll
        calculate_pitch_roll(accel_x, accel_y, accel_z, &pitch, &roll);

        // Map pitch and roll to servo angle (example mapping)
        servo_angle = (int)((pitch + 90) * 180 / 180); // Assuming pitch range is -90 to 90
        if (servo_angle < 0) servo_angle = 0;
        if (servo_angle > 180) servo_angle = 180;

        // Set servo angle
        if (set_servo_angle(servo_angle) != 0) {
            fprintf(stderr, "Error setting servo angle.\n");
        }

        // Log data
        log_data(pitch, roll, servo_angle);

        // Delay
        usleep(100000); // 100ms
    }

    // Cleanup
    printf("Cleaning up...\n");
    fclose(log_file);

    // Disable PWM
    snprintf(enable_path, sizeof(enable_path), "/sys/class/pwm/pwmchip%d/pwm%d/enable", PWM_CHIP, PWM_NUM);
    enable_fd = open(enable_path, O_WRONLY);
    if (enable_fd >= 0) {
        write(enable_fd, "0", 1);
        close(enable_fd);
    }

    return 0;
}

