#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins for relays
#define RELAY1_PIN 4
#define RELAY2_PIN 17
#define RELAY3_PIN 27
#define RELAY4_PIN 22

// Define PWM frequency
#define PWM_FREQUENCY 100

// Define fade duration (seconds)
#define FADE_DURATION 1800

// Define schedule file name
#define SCHEDULE_FILE "lighting_schedule.txt"

// Structure to represent a schedule entry
typedef struct {
    int hour;
    int minute;
    int second;
    int relay_number;
    int on_off;
} schedule_entry_t;

// Global variables
static volatile int running = 1;
static int current_duties[4] = {0, 0, 0, 0}; // Current PWM duty cycles for each relay

// Function prototypes
int parse_schedule_entry(const char *line, schedule_entry_t *entry);
int load_schedule(const char *filename, schedule_entry_t **schedule, int *num_entries);
int get_current_time(struct tm *timeinfo);
int find_schedule_entry(const schedule_entry_t *schedule, int num_entries, struct tm *timeinfo, int *relay_number, int *on_off);
void set_relay_state(int relay_number, int state);
void fade_lamp(int relay_number, int target_duty_cycle);
void signal_handler(int signal);
void cleanup();

// Function to parse a schedule entry from a string
int parse_schedule_entry(const char *line, schedule_entry_t *entry) {
    if (sscanf(line, "%d:%d:%d,%d,%d", &entry->hour, &entry->minute, &entry->second, &entry->relay_number, &entry->on_off) != 5) {
        fprintf(stderr, "Error: Invalid schedule entry format: %s\n", line);
        return -1;
    }
    return 0;
}

// Function to load the schedule from a file
int load_schedule(const char *filename, schedule_entry_t **schedule, int *num_entries) {
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        perror("Error: Could not open schedule file");
        return -1;
    }

    char line[256];
    int count = 0;

    // Determine the number of lines in the file
    while (fgets(line, sizeof(line), fp) != NULL) {
        count++;
    }

    rewind(fp); // Reset file pointer to the beginning

    *schedule = (schedule_entry_t *)malloc(count * sizeof(schedule_entry_t));
    if (*schedule == NULL) {
        perror("Error: Could not allocate memory for schedule");
        fclose(fp);
        return -1;
    }

    int i = 0;
    while (fgets(line, sizeof(line), fp) != NULL) {
        if (parse_schedule_entry(line, &(*schedule)[i]) != 0) {
            free(*schedule);
            fclose(fp);
            return -1;
        }
        i++;
    }

    fclose(fp);
    *num_entries = count;
    return 0;
}

// Function to get the current time
int get_current_time(struct tm *timeinfo) {
    time_t rawtime;
    time(&rawtime);
    *timeinfo = *localtime(&rawtime);
    return 0;
}

// Function to find the schedule entry that applies to the current time
int find_schedule_entry(const schedule_entry_t *schedule, int num_entries, struct tm *timeinfo, int *relay_number, int *on_off) {
    for (int i = 0; i < num_entries; i++) {
        if (schedule[i].hour == timeinfo->tm_hour &&
            schedule[i].minute == timeinfo->tm_min &&
            schedule[i].second == timeinfo->tm_sec) {
            *relay_number = schedule[i].relay_number;
            *on_off = schedule[i].on_off;
            return 0;
        }
    }
    return -1; // No matching entry found
}

// Function to set the state of a relay
void set_relay_state(int relay_number, int state) {
    int pin;
    switch (relay_number) {
        case 1:
            pin = RELAY1_PIN;
            break;
        case 2:
            pin = RELAY2_PIN;
            break;
        case 3:
            pin = RELAY3_PIN;
            break;
        case 4:
            pin = RELAY4_PIN;
            break;
        default:
            fprintf(stderr, "Error: Invalid relay number: %d\n", relay_number);
            return;
    }

    gpioWrite(pin, state);
}

// Function to fade a lamp to a target duty cycle
void fade_lamp(int relay_number, int target_duty_cycle) {
    int pin;
    switch (relay_number) {
        case 1:
            pin = RELAY1_PIN;
            break;
        case 2:
            pin = RELAY2_PIN;
            break;
        case 3:
            pin = RELAY3_PIN;
            break;
        case 4:
            pin = RELAY4_PIN;
            break;
        default:
            fprintf(stderr, "Error: Invalid relay number: %d\n", relay_number);
            return;
    }

    int current_duty = current_duties[relay_number - 1];
    int direction = (target_duty_cycle > current_duty) ? 1 : -1;

    while (current_duty != target_duty_cycle) {
        current_duty += direction;
        if (current_duty < 0) current_duty = 0;
        if (current_duty > 100) current_duty = 100;

        gpioPWM(pin, current_duty * 10); // pigpio uses 0-1000 for PWM
        current_duties[relay_number - 1] = current_duty;
        gpioDelay(FADE_DURATION / 100); // Divide fade duration by 100 for 100Hz PWM
    }
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    running = 0;
}

// Cleanup function
void cleanup() {
    // Turn off all relays
    set_relay_state(1, 0);
    set_relay_state(2, 0);
    set_relay_state(3, 0);
    set_relay_state(4, 0);

    // Release GPIO resources
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(RELAY1_PIN, PI_OUTPUT);
    gpioSetMode(RELAY2_PIN, PI_OUTPUT);
    gpioSetMode(RELAY3_PIN, PI_OUTPUT);
    gpioSetMode(RELAY4_PIN, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(RELAY1_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(RELAY2_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(RELAY3_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(RELAY4_PIN, PWM_FREQUENCY);

    // Load the schedule
    schedule_entry_t *schedule = NULL;
    int num_entries = 0;
    if (load_schedule(SCHEDULE_FILE, &schedule, &num_entries) != 0) {
        cleanup();
        return 1;
    }

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    struct tm timeinfo;
    int relay_number, on_off;
    int last_relay_number = 0; // Store the last relay number to avoid unnecessary fades
    int last_on_off = 0;       // Store the last on/off state

    // Main loop
    while (running) {
        if (get_current_time(&timeinfo) != 0) {
            fprintf(stderr, "Error: Could not get current time\n");
            continue;
        }

        if (find_schedule_entry(schedule, num_entries, &timeinfo, &relay_number, &on_off) == 0) {
            if (relay_number != last_relay_number || on_off != last_on_off) {
                if (last_on_off == 1) {
                    // Fade out
                    fade_lamp(last_relay_number, 0);
                }

                // Set relay state
                set_relay_state(relay_number, on_off);

                if (on_off == 1) {
                    // Fade in
                    fade_lamp(relay_number, 100);
                }

                last_relay_number = relay_number;
                last_on_off = on_off;
            }
        } else {
            fprintf(stderr, "Warning: No schedule entry found for %02d:%02d:%02d\n", timeinfo.tm_hour, timeinfo.tm_min, timeinfo.tm_sec);
        }

        sleep(1); // Check every second
    }

    // Cleanup and exit
    free(schedule);
    cleanup();
    return 0;
}

