    gpioSetMode(RELAY3_PIN, PI_OUTPUT);
    gpioSetMode(RELAY4_PIN, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(RELAY1_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(RELAY2_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(RELAY3_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(RELAY4_PIN, PWM_FREQUENCY);

    // Load the schedule
    schedule_entry_t *schedule = NULL;
    int num_entries = 0;
    if (load_schedule(SCHEDULE_FILE, &schedule, &num_entries) != 0) {
        cleanup();
        return 1;
    }

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    struct tm timeinfo;
    int relay_number, on_off;
    int last_relay_number = 0; // Store the last relay number to avoid unnecessary fades
    int last_on_off = 0;       // Store the last on/off state

    // Main loop
    while (running) {
        if (get_current_time(&timeinfo) != 0) {
            fprintf(stderr, "Error: Could not get current time\n");
            continue;
        }

        if (find_schedule_entry(schedule, num_entries, &timeinfo, &relay_number, &on_off) == 0) {
            if (relay_number != last_relay_number || on_off != last_on_off) {
                if (last_on_off == 1) {
                    // Fade out
                    fade_lamp(last_relay_number, 0);
                }

                // Set relay state
                set_relay_state(relay_number, on_off);

                if (on_off == 1) {
                    // Fade in
                    fade_lamp(relay_number, 100);
                }

                last_relay_number = relay_number;
                last_on_off = on_off;
            }
        } else {
            fprintf(stderr, "Warning: No schedule entry found for %02d:%02d:%02d\n", timeinfo.tm_hour, timeinfo.tm_min, timeinfo.tm_sec);
        }

        sleep(1); // Check every second
    }

    // Cleanup and exit
    free(schedule);
    cleanup();
    return 0;
}

