#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define BUZZER_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define MIN_FREQUENCY 200.0   // Minimum frequency in Hz
#define MAX_FREQUENCY 2000.0  // Maximum frequency in Hz
#define MIN_DISTANCE 2.0      // Minimum distance in cm
#define MAX_DISTANCE 20.0     // Maximum distance in cm
#define TIMEOUT_US 50000       // Timeout in microseconds (50ms)
#define MIN_MEASUREMENT_INTERVAL_MS 60 // Minimum measurement interval in milliseconds

// Global variables
static volatile int running = 1;
static volatile unsigned long last_measurement_time = 0;

// Function prototypes
void signal_handler(int signal);
void trigger_pulse();
long measure_pulse_width();
double calculate_distance(long pulse_width);
double map_distance_to_frequency(double distance);
void set_buzzer_frequency(double frequency);
void log_error(const char *message);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Caught SIGINT, shutting down...\n");
        running = 0;
        set_buzzer_frequency(0.0); // Stop the buzzer
        gpioTerminate();           // Terminate pigpio
        exit(0);
    }
}

// Function to send a 10us trigger pulse
void trigger_pulse() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 microseconds
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to measure the pulse width of the echo signal
long measure_pulse_width() {
    long start_time = 0, end_time = 0;
    int timeout = 0;

    // Wait for the echo pin to go high
    while (gpioRead(ECHO_PIN) == 0) {
        start_time = gpioTick();
        if (start_time == 0) {
            log_error("gpioTick() returned 0, retrying...");
            gpioDelay(1); // Small delay to prevent busy-waiting
        }
    }

    // Wait for the echo pin to go low
    while (gpioRead(ECHO_PIN) == 1) {
        end_time = gpioTick();
        if (end_time == 0) {
            log_error("gpioTick() returned 0, retrying...");
            gpioDelay(1); // Small delay to prevent busy-waiting
        }
        if (end_time - start_time > TIMEOUT_US) {
            log_error("Timeout waiting for echo to go low");
            return -1; // Timeout
        }
    }

    return end_time - start_time;
}

// Function to calculate the distance in centimeters
double calculate_distance(long pulse_width) {
    if (pulse_width < 0) return -1.0; // Indicate error
    return (pulse_width / 1000000.0) * SPEED_OF_SOUND / 2.0;
}

// Function to map the distance to a frequency
double map_distance_to_frequency(double distance) {
    if (distance < 0) return -1.0; // Indicate error

    // Clamp distance to the valid range
    if (distance < MIN_DISTANCE) {
        distance = MIN_DISTANCE;
    } else if (distance > MAX_DISTANCE) {
        distance = MAX_DISTANCE;
    }

    // Map distance to frequency linearly
    double frequency = MIN_FREQUENCY + (distance - MIN_DISTANCE) * (MAX_FREQUENCY - MIN_FREQUENCY) / (MAX_DISTANCE - MIN_DISTANCE);
    return frequency;
}

// Function to set the buzzer frequency using PWM
void set_buzzer_frequency(double frequency) {
    if (frequency < 0) return; // Ignore errors

    // Clamp frequency to the valid range
    if (frequency < MIN_FREQUENCY) {
        frequency = MIN_FREQUENCY;
    } else if (frequency > MAX_FREQUENCY) {
        frequency = MAX_FREQUENCY;
    }

    // Calculate PWM range and duty cycle
    int range = 1000; // Adjust for desired resolution
    int duty_cycle = (int)(frequency / MAX_FREQUENCY * range); // Map frequency to duty cycle

    gpioSetPWMfrequency(BUZZER_PIN, (int)frequency); // Set PWM frequency
    gpioPWM(BUZZER_PIN, duty_cycle);                 // Set PWM duty cycle
}

// Function to log errors to stderr
void log_error(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    // Set PWM range
    gpioSetPWMrange(BUZZER_PIN, 1000);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Theremin started. Press Ctrl+C to exit.\n");

    while (running) {
        // Check if the minimum measurement interval has passed
        unsigned long current_time = gpioTick();
        if (current_time - last_measurement_time < MIN_MEASUREMENT_INTERVAL_MS * 1000) {
            gpioDelay(MIN_MEASUREMENT_INTERVAL_MS * 1000 - (current_time - last_measurement_time)); // Delay to meet minimum interval
            current_time = gpioTick();
        }

        // Trigger the ultrasonic sensor
        trigger_pulse();

        // Measure the pulse width
        long pulse_width = measure_pulse_width();

        // Calculate the distance
        double distance = calculate_distance(pulse_width);

        // Map the distance to a frequency
        double frequency = map_distance_to_frequency(distance);

        // Set the buzzer frequency
        set_buzzer_frequency(frequency);

        // Update last measurement time
        last_measurement_time = current_time;

        // Delay to achieve approximately 50Hz loop rate
        gpioDelay(20000); // 20ms delay
    }

    // Clean up and exit
    set_buzzer_frequency(0.0); // Stop the buzzer
    gpioTerminate();           // Terminate pigpio
    return 0;
}

