#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <math.h>
#include <pigpio.h>

// Define GPIO pins for RGB LED
#define RED_PIN   17
#define GREEN_PIN 22
#define BLUE_PIN  27

// Define PWM frequency
#define PWM_FREQUENCY 1000

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to set the color of the RGB LED
void set_color(int red, int green, int blue) {
    gpioPWM(RED_PIN, red);
    gpioPWM(GREEN_PIN, green);
    gpioPWM(BLUE_PIN, blue);
}

// Function to calculate the proximity value based on time
float calculate_proximity(float time) {
    return 0.5 + 0.5 * sin(time * M_PI / 10.0); // Sine wave from 0.0 to 1.0
}

// Function to map proximity value to RGB color values
void proximity_to_rgb(float proximity, int *red, int *green, int *blue) {
    // Map proximity to grayscale (white to black)
    int brightness = (int)(255 * (1.0 - proximity)); // Invert proximity for grayscale

    *red   = brightness;
    *green = brightness;
    *blue  = brightness;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins to output mode
    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);

    // Set PWM frequency for all pins
    gpioSetPWMfrequency(RED_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(GREEN_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(BLUE_PIN, PWM_FREQUENCY);

    // Set PWM range (0-255)
    gpioSetPWMrange(RED_PIN, 255);
    gpioSetPWMrange(GREEN_PIN, 255);
    gpioSetPWMrange(BLUE_PIN, 255);

    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Main loop
    float time = 0.0;
    int red, green, blue;
    while (program_running) {
        // Calculate proximity value
        float proximity = calculate_proximity(time);

        // Map proximity to RGB color values
        proximity_to_rgb(proximity, &red, &green, &blue);

        // Set the color of the RGB LED
        set_color(red, green, blue);

        // Increment time
        time += 0.01;

        // Delay for a short period
        gpioDelay(10000); // 10ms delay
    }

    // Turn off the LED
    set_color(0, 0, 0);

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

