#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <fcntl.h>
#include <math.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define PWR_MGMT_1   0x6B
#define GYRO_CONFIG  0x1B
#define GYRO_XOUT_H  0x43
#define GYRO_XOUT_L  0x44
#define GYRO_YOUT_H  0x45
#define GYRO_YOUT_L  0x46
#define GYRO_ZOUT_H  0x47
#define GYRO_ZOUT_L  0x48

// Sensitivity scale factor (±250°/s)
#define GYRO_SCALE 131.0

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c(int address);
int read_gyro_data(int fd, int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z);
float convert_to_dps(int16_t raw_data);
int log_data(FILE *fp, float gyro_x, float gyro_y, float gyro_z);
void signal_handler(int sig);
void cleanup();

// Signal handler
void signal_handler(int sig) {
    terminate = 1;
    printf("Signal received, cleaning up...\n");
}

// Initialize I2C bus
int init_i2c(int address) {
    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, address) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// Read gyroscope data
int read_gyro_data(int fd, int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z) {
    uint8_t buffer[6];
    int result;

    // Read all six bytes at once
    result = read(fd, buffer, 6);
    if (result != 6) {
        perror("Error reading gyroscope data");
        return -1;
    }

    *gyro_x = (int16_t)((buffer[0] << 8) | buffer[1]);
    *gyro_y = (int16_t)((buffer[2] << 8) | buffer[3]);
    *gyro_z = (int16_t)((buffer[4] << 8) | buffer[5]);

    return 0;
}

// Convert raw data to degrees per second
float convert_to_dps(int16_t raw_data) {
    return (float)raw_data / GYRO_SCALE;
}

// Log data to file
int log_data(FILE *fp, float gyro_x, float gyro_y, float gyro_z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(fp, "%s,%.2f,%.2f,%.2f\n", timestamp, gyro_x, gyro_y, gyro_z) < 0) {
        perror("Error writing to log file");
        return -1;
    }

    return 0;
}

// Cleanup resources
void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main() {
    int16_t gyro_x_raw, gyro_y_raw, gyro_z_raw;
    float gyro_x_dps, gyro_y_dps, gyro_z_dps;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_fd = init_i2c(MPU6050_ADDR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to initialize I2C. Exiting.\n");
        return 1;
    }

    // Configure MPU-6050 (wake up and set gyro range)
    uint8_t config_data[2];
    config_data[0] = PWR_MGMT_1;
    config_data[1] = 0x00; // Wake up the MPU-6050
    if (write(i2c_fd, config_data, 2) != 2) {
        perror("Error writing to PWR_MGMT_1");
        cleanup();
        return 1;
    }

    config_data[0] = GYRO_CONFIG;
    config_data[1] = 0x00; // Set gyro range to ±250°/s
    if (write(i2c_fd, config_data, 2) != 2) {
        perror("Error writing to GYRO_CONFIG");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("gyro_log.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read gyroscope data
        if (read_gyro_data(i2c_fd, &gyro_x_raw, &gyro_y_raw, &gyro_z_raw) == 0) {
            // Convert to degrees per second
            gyro_x_dps = convert_to_dps(gyro_x_raw);
            gyro_y_dps = convert_to_dps(gyro_y_raw);
            gyro_z_dps = convert_to_dps(gyro_z_raw);

            // Log data
            if (log_data(log_file, gyro_x_dps, gyro_y_dps, gyro_z_dps) != 0) {
                fprintf(stderr, "Error logging data. Continuing...\n");
            }
        } else {
            fprintf(stderr, "Error reading gyroscope data. Continuing...\n");
        }

        // Sleep for 100ms
        usleep(100000);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

