#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define BUTTON_GPIO 17
#define BUZZER_GPIO 18

// Define PWM frequency
#define PWM_FREQUENCY 440

// Define melody structure
typedef struct {
    int frequency;
    int duration_ms;
} Note;

// Define melody lookup table
const Note melody[] = {
    {440, 200},   // A4
    {494, 200},   // B4
    {523, 200},   // C5
    {587, 200},   // D5
    {659, 200},   // E5
    {0, 100}      // Rest
};

const int melody_length = sizeof(melody) / sizeof(melody[0]);

// Debounce time in milliseconds
#define DEBOUNCE_TIME 50

// Global variables
volatile int button_pressed = 0;
volatile int melody_playing = 0;
volatile int melody_index = 0;
volatile unsigned long last_interrupt_time = 0;

// Function prototypes
void button_isr(int gpio, int level, uint32_t tick, void *user_data);
void play_melody();
void stop_melody();
void signal_handler(int signal);

// Function to play a tone
void play_tone(int frequency, int duration_ms) {
    if (frequency > 0) {
        gpioPWM(BUZZER_GPIO, 128); // 50% duty cycle
        gpioSetPWMfrequency(BUZZER_GPIO, frequency);
    } else {
        gpioPWM(BUZZER_GPIO, 0); // Stop the tone
    }
    gpioDelay(duration_ms * 1000); // Convert ms to microseconds
}

// Interrupt service routine for the button
void button_isr(int gpio, int level, uint32_t tick, void *user_data) {
    unsigned long current_time = gpioTick();

    if (level == 0 && (current_time - last_interrupt_time) > (DEBOUNCE_TIME * 1000)) { // Active low
        button_pressed = 1;
        last_interrupt_time = current_time;
    }
}

// Function to play the melody
void play_melody() {
    melody_playing = 1;
    melody_index = 0;
    while (melody_index < melody_length && melody_playing) {
        play_tone(melody[melody_index].frequency, melody[melody_index].duration_ms);
        melody_index++;
    }
    stop_melody();
}

// Function to stop the melody
void stop_melody() {
    melody_playing = 0;
    gpioPWM(BUZZER_GPIO, 0); // Stop the tone
    melody_index = 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    stop_melody();
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(BUTTON_GPIO, PI_INPUT);
    gpioSetMode(BUZZER_GPIO, PI_OUTPUT);

    // Enable internal pull-up resistor on the button pin
    gpioSetPullUpDown(BUTTON_GPIO, PI_PUD_UP);

    // Set PWM frequency for the buzzer
    gpioSetPWMfrequency(BUZZER_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(BUZZER_GPIO, 255); // Set PWM range to 255 for finer control

    // Register interrupt service routine for the button
    if (gpioSetISRFuncEx(BUTTON_GPIO, FALLING_EDGE, 0, button_isr, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR function\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Doorbell program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        if (button_pressed) {
            play_melody();
            button_pressed = 0; // Reset the flag
        }
        gpioDelay(1000); // Check every 1ms
    }

    return 0;
}

