#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>

#define GPIO_PIN 17
#define LOG_FILE "vibration_events.log"
#define WINDOW_SIZE 5

// Global variables
volatile sig_atomic_t program_running = 1;
FILE *log_file = NULL;

// Structure to hold the sliding window
typedef struct {
    int events[WINDOW_SIZE];
    int head;
    int count;
} EventWindow;

// Function prototypes
void signal_handler(int signal);
int initialize_gpio();
int open_log_file();
void close_log_file();
void log_event(int value);
void add_event_to_window(EventWindow *window, int value);
int check_earthquake_alert(const EventWindow *window);
char* get_iso8601_timestamp();
void print_earthquake_alert();

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize GPIO
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN); // Use pull-down resistor

    return 0;
}

// Open log file
int open_log_file() {
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        return 1;
    }
    return 0;
}

// Close log file
void close_log_file() {
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
}

// Log event to file
void log_event(int value) {
    char *timestamp = get_iso8601_timestamp();
    if (timestamp == NULL) {
        fprintf(stderr, "Error getting timestamp\n");
        return;
    }

    fprintf(log_file, "%s,%d\n", timestamp, value);
    fflush(log_file); // Ensure data is written immediately
    fsync(fileno(log_file)); // Ensure data is written to disk

    free(timestamp);
}

// Add event to sliding window
void add_event_to_window(EventWindow *window, int value) {
    window->events[window->head] = value;
    window->head = (window->head + 1) % WINDOW_SIZE;
    if (window->count < WINDOW_SIZE) {
        window->count++;
    }
}

// Check for earthquake alert
int check_earthquake_alert(const EventWindow *window) {
    int high_count = 0;
    for (int i = 0; i < window->count; i++) {
        if (window->events[i] == 1) {
            high_count++;
        }
    }
    return (high_count >= 3);
}

// Get current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *buffer = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp string

    if (buffer == NULL) {
        perror("Failed to allocate memory for timestamp");
        return NULL;
    }

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(buffer, 25, "%Y-%m-%dT%H:%M:%S%z", timeinfo);
    return buffer;
}

// Print earthquake alert message
void print_earthquake_alert() {
    char *timestamp = get_iso8601_timestamp();
    if (timestamp == NULL) {
        fprintf(stderr, "Error getting timestamp for alert\n");
        return;
    }

    printf("EARTHQUAKE ALERT: %s\n", timestamp);
    free(timestamp);
}

int main(int argc, char *argv[]) {
    int timeout_ms = 1000; // Default timeout
    if (argc > 1) {
        timeout_ms = atoi(argv[1]);
        if (timeout_ms <= 0) {
            fprintf(stderr, "Invalid timeout value. Using default: 1000ms\n");
            timeout_ms = 1000;
        }
    }

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    if (open_log_file() != 0) {
        gpioTerminate();
        return 1;
    }

    EventWindow event_window = {{0}, 0, 0};
    int current_value = gpioRead(GPIO_PIN);
    add_event_to_window(&event_window, current_value);
    log_event(current_value);

    // Main loop
    while (program_running) {
        int new_value = gpioRead(GPIO_PIN);

        if (new_value != current_value) {
            add_event_to_window(&event_window, new_value);
            log_event(new_value);
            current_value = new_value;

            if (check_earthquake_alert(&event_window)) {
                print_earthquake_alert();
            }
        }

        gpioDelay(timeout_ms * 1000); // pigpioDelay takes microseconds
    }

    // Cleanup
    gpioTerminate();
    close_log_file();

    return 0;
}

