    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// I2C initialization function
int initialize_i2c() {
    i2c_handle = i2cOpen(1, LSM303_ADDRESS, 0); // Bus 1, address 0x1E, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }

    // Configure magnetometer (example configuration)
    if (i2cWriteByteData(i2c_handle, CRA_REG_M, 0x18) < 0) { // 75 Hz output rate
        fprintf(stderr, "Error writing to CRA_REG_M\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, CRB_REG_M, 0x20) < 0) { // Gain +/- 1.3 Gauss
        fprintf(stderr, "Error writing to CRB_REG_M\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, MR_REG_M, 0x00) < 0) { // Continuous conversion mode
        fprintf(stderr, "Error writing to MR_REG_M\n");
        return -1;
    }

    return 0;
}

// Function to read raw magnetometer data
magnetometer_data_t read_magnetometer_data() {
    magnetometer_data_t raw_data;
    char buffer[6];

    if (i2cReadI2CBlockData(i2c_handle, OUT_X_H_M, buffer, 6) != 6) {
        fprintf(stderr, "Error reading magnetometer data\n");
        raw_data.x = 0.0; // Set to 0 to avoid using uninitialized values
        raw_data.y = 0.0;
        raw_data.z = 0.0;
        return raw_data;
    }

    // Combine high and low bytes, and convert to signed 16-bit integers
    raw_data.x = (float)((int16_t)((buffer[0] << 8) | buffer[1]));
    raw_data.z = (float)((int16_t)((buffer[2] << 8) | buffer[3]));
    raw_data.y = (float)((int16_t)((buffer[4] << 8) | buffer[5]));

    return raw_data;
}

// Function to apply hard-iron calibration
magnetometer_data_t apply_calibration(magnetometer_data_t raw_data) {
    magnetometer_data_t calibrated_data;

    calibrated_data.x = raw_data.x - X_OFFSET;
    calibrated_data.y = raw_data.y - Y_OFFSET;
    calibrated_data.z = raw_data.z - Z_OFFSET;

    return calibrated_data;
}

// Function to calculate heading in degrees
float calculate_heading(magnetometer_data_t calibrated_data) {
    float heading = atan2(calibrated_data.y, calibrated_data.x) * 180 / M_PI;

    // Adjust for declination (if needed)
    // heading += declination;

    // Normalize to 0-360 degrees
    if (heading < 0) {
        heading += 360;
    }

    return heading;
}

// Function to map heading to compass direction
char* map_heading_to_direction(float heading) {
    if (heading >= 337.5 || heading < 22.5) return "N";
    if (heading >= 22.5 && heading < 67.5) return "NE";
    if (heading >= 67.5 && heading < 112.5) return "E";
    if (heading >= 112.5 && heading < 157.5) return "SE";
    if (heading >= 157.5 && heading < 202.5) return "S";
    if (heading >= 202.5 && heading < 247.5) return "SW";
    if (heading >= 247.5 && heading < 292.5) return "W";
    if (heading >= 292.5 && heading < 337.5) return "NW";
    return "N"; // Should never happen
}

// Function to log data to file
int log_data(magnetometer_data_t raw_data, magnetometer_data_t calibrated_data, float heading, char* direction) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f,%.2f,%s\n", timestamp, raw_data.x, raw_data.y, raw_data.z, heading, direction);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
