        magnetometer_data_t calibrated_data = apply_calibration(raw_data);

        // Calculate heading
        float heading = calculate_heading(calibrated_data);

        // Map heading to compass direction
        char* direction = map_heading_to_direction(heading);

        // Log data
        log_data(raw_data, calibrated_data, heading, direction);

        // Print to console
        printf("Raw: X=%.2f, Y=%.2f, Z=%.2f | Calibrated: X=%.2f, Y=%.2f, Z=%.2f | Heading: %.2f (%s)\n",
               raw_data.x, raw_data.y, raw_data.z, calibrated_data.x, calibrated_data.y, calibrated_data.z, heading, direction);

        // Wait for 1 second
        sleep(1);
    }

