#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Define GPIO pins for the relays
#define RELAY1_PIN 17
#define RELAY2_PIN 23
#define RELAY3_PIN 24
#define RELAY4_PIN 25

// Define the moisture threshold
#define MOISTURE_THRESHOLD 30

// Define the irrigation duration and gap
#define IRRIGATION_DURATION 5
#define GAP_DURATION 1

// Global variables
FILE *log_file = NULL;
int running = 1;

// Function prototypes
int initialize_gpio();
int read_soil_moisture();
void activate_relay(int relay_number);
void deactivate_relay(int relay_number);
void log_event(int relay_number, int moisture_level);
void signal_handler(int signal);
void cleanup();

// Function to initialize the GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(RELAY1_PIN, PI_OUTPUT);
    gpioSetMode(RELAY2_PIN, PI_OUTPUT);
    gpioSetMode(RELAY3_PIN, PI_OUTPUT);
    gpioSetMode(RELAY4_PIN, PI_OUTPUT);

    return 0;
}

// Function to read the soil moisture value
int read_soil_moisture() {
    // Seed the random number generator with the current time
    unsigned int seed = time(NULL);
    srand(seed);

    // Generate a random moisture value between 0 and 100
    return rand() % 101;
}

// Function to activate a relay
void activate_relay(int relay_number) {
    int pin;

    switch (relay_number) {
        case 1:
            pin = RELAY1_PIN;
            break;
        case 2:
            pin = RELAY2_PIN;
            break;
        case 3:
            pin = RELAY3_PIN;
            break;
        case 4:
            pin = RELAY4_PIN;
            break;
        default:
            fprintf(stderr, "Invalid relay number: %d\n", relay_number);
            return;
    }

    gpioWrite(pin, 0); // Active low
    printf("Relay %d activated\n", relay_number);
}

// Function to deactivate a relay
void deactivate_relay(int relay_number) {
    int pin;

    switch (relay_number) {
        case 1:
            pin = RELAY1_PIN;
            break;
        case 2:
            pin = RELAY2_PIN;
            break;
        case 3:
            pin = RELAY3_PIN;
            break;
        case 4:
            pin = RELAY4_PIN;
            break;
        default:
            fprintf(stderr, "Invalid relay number: %d\n", relay_number);
            return;
    }

    gpioWrite(pin, 1); // High
    printf("Relay %d deactivated\n", relay_number);
}

// Function to log an event to the log file
void log_event(int relay_number, int moisture_level) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, Relay %d, Moisture: %d\n", timestamp, relay_number, moisture_level);
        fflush(log_file); // Ensure data is written to the file immediately
    } else {
        fprintf(stderr, "Error: Log file is not open\n");
    }
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    running = 0;
}

// Cleanup function to deactivate relays and close the log file
void cleanup() {
    deactivate_relay(1);
    deactivate_relay(2);
    deactivate_relay(3);
    deactivate_relay(4);

    if (log_file != NULL) {
        fclose(log_file);
        printf("Log file closed\n");
    }

    gpioTerminate();
    printf("pigpio terminated\n");
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open the log file
    log_file = fopen("irrigation_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

