        return 1;
    }

    gpioSetMode(RELAY1_PIN, PI_OUTPUT);
    gpioSetMode(RELAY2_PIN, PI_OUTPUT);
    gpioSetMode(RELAY3_PIN, PI_OUTPUT);
    gpioSetMode(RELAY4_PIN, PI_OUTPUT);

    return 0;
}

// Function to read the soil moisture value
int read_soil_moisture() {
    // Seed the random number generator with the current time
    unsigned int seed = time(NULL);
    srand(seed);

    // Generate a random moisture value between 0 and 100
    return rand() % 101;
}

// Function to activate a relay
void activate_relay(int relay_number) {
    int pin;

    switch (relay_number) {
        case 1:
            pin = RELAY1_PIN;
            break;
        case 2:
            pin = RELAY2_PIN;
            break;
        case 3:
            pin = RELAY3_PIN;
            break;
        case 4:
            pin = RELAY4_PIN;
            break;
