#include <time.h>
#include <pigpio.h>

// Define GPIO pins for servo motors
#define VALVE_SERVO_PIN 17
#define NOZZLE_SERVO_PIN 18

// Define moisture threshold
#define MOISTURE_THRESHOLD 50

// Define servo pulse width limits (microseconds)
#define SERVO_MIN_PULSE_WIDTH 500
#define SERVO_MAX_PULSE_WIDTH 2500

// Define watering cycle duration (seconds)
#define WATERING_CYCLE_DURATION 10

// Define nozzle sweep duration (seconds)
#define NOZZLE_SWEEP_DURATION 10

// Define nozzle spray duration (seconds)
#define NOZZLE_SPRAY_DURATION 5

// Define servo open and close pulse widths
#define SERVO_OPEN_PULSE_WIDTH 1500
#define SERVO_CLOSE_PULSE_WIDTH 500

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Function prototypes
int set_servo_pulse_width(int gpio, int pulse_width);
int get_soil_moisture();
void water_plant();
void signal_handler(int signal);

// Function to set the servo pulse width with retry mechanism
int set_servo_pulse_width(int gpio, int pulse_width) {
    int retries = 3;
    int result;

    while (retries > 0) {
        result = gpioServo(gpio, pulse_width);
        if (result == 0) {
            return 0; // Success
        } else {
            fprintf(stderr, "Error setting servo pulse width for GPIO %d: %d. Retrying...\n", gpio, result);
            gpioDelay(100); // Wait 100ms before retrying
            retries--;
        }
    }

    fprintf(stderr, "Failed to set servo pulse width for GPIO %d after multiple retries.\n", gpio);
    return -1; // Failure
}

// Function to simulate reading soil moisture
int get_soil_moisture() {
    static int moisture_values[] = {20, 40, 60, 80, 100};
    static int index = 0;
    int moisture = moisture_values[index];
    index = (index + 1) % 5;
    return moisture;
}

// Function to water the plant
void water_plant() {
    int moisture = get_soil_moisture();
    printf("Soil moisture: %d\n", moisture);

    if (moisture < MOISTURE_THRESHOLD) {
        printf("Moisture below threshold. Opening valve and spraying...\n");

        // Open valve
        if (set_servo_pulse_width(VALVE_SERVO_PIN, SERVO_OPEN_PULSE_WIDTH) != 0) {
            fprintf(stderr, "Failed to open valve. Aborting watering cycle.\n");
            return;
        }

        // Spray for 5 seconds
        gpioDelay(NOOZLE_SPRAY_DURATION * 1000000); // Convert seconds to microseconds

        // Sweep nozzle through angles
        int nozzle_angles[] = {0, 45, 90, 135, 180};
        int nozzle_pulse_widths[] = {500, 1000, 1500, 2000, 2500};
        int num_angles = sizeof(nozzle_angles) / sizeof(nozzle_angles[0]);

        for (int i = 0; i < num_angles; i++) {
            if (set_servo_pulse_width(NOZZLE_SERVO_PIN, nozzle_pulse_widths[i]) != 0) {
                fprintf(stderr, "Failed to set nozzle angle to %d degrees. Continuing to next angle.\n", nozzle_angles[i]);
            } else {
                printf("Nozzle angle: %d degrees\n", nozzle_angles[i]);
                gpioDelay(NOOZLE_SWEEP_DURATION * 1000000 / num_angles); // Distribute time evenly
            }
        }

        // Close valve
        if (set_servo_pulse_width(VALVE_SERVO_PIN, SERVO_CLOSE_PULSE_WIDTH) != 0) {
            fprintf(stderr, "Failed to close valve. Continuing to next cycle.\n");
        }

        gpioDelay(5000000); // Wait 5 seconds
    } else {
        printf("Moisture above threshold. Skipping watering cycle.\n");
    }
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d. Shutting down...\n", signal);
    program_running = 0;

    // Stop servos
    set_servo_pulse_width(VALVE_SERVO_PIN, 0);
    set_servo_pulse_width(NOZZLE_SERVO_PIN, 0);

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins to output mode
    gpioSetMode(VALVE_SERVO_PIN, PI_OUTPUT);
    gpioSetMode(NOZZLE_SERVO_PIN, PI_OUTPUT);

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Plant watering system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        water_plant();
        gpioDelay(WATERING_CYCLE_DURATION * 1000000); // Wait 10 seconds
    }

    return 0;
}

