#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define PWR_MGMT_1   0x6B
#define GYRO_XOUT_H  0x43
#define GYRO_YOUT_H  0x45
#define GYRO_ZOUT_H  0x47

// Sensitivity scale factor (LSB/deg/s)
#define GYRO_SCALE 131.0

// I2C bus
#define I2C_BUS 1

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_mpu6050();
int read_gyro_data(float *x, float *y, float *z);
void log_data(float x, float y, float z);
void signal_handler(int signal);
void cleanup();

// Structure to hold gyroscope data
typedef struct {
    float x;
    float y;
    float z;
} gyro_data_t;

// Initialize MPU-6050
int init_mpu6050() {
    // Wake up the MPU-6050 (clear sleep bit)
    if (i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0) != 0) {
        fprintf(stderr, "Error: Could not wake up MPU-6050. %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Read gyroscope data
int read_gyro_data(float *x, float *y, float *z) {
    char buf[6];
    int16_t raw_x, raw_y, raw_z;

    if (i2cReadI2CBlockData(i2c_handle, GYRO_XOUT_H, buf, 6) != 6) {
        fprintf(stderr, "Error: Could not read gyro data. %s\n", strerror(errno));
        return -1;
    }

    raw_x = (buf[0] << 8) | buf[1];
    raw_y = (buf[2] << 8) | buf[3];
    raw_z = (buf[4] << 8) | buf[5];

    *x = (float)raw_x / GYRO_SCALE;
    *y = (float)raw_y / GYRO_SCALE;
    *z = (float)raw_z / GYRO_SCALE;

    return 0;
}

// Log data to file
void log_data(float x, float y, float z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f\n", timestamp, x, y, z);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus. %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Initialize MPU-6050
    if (init_mpu6050() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("gyro_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file. %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Main loop
    float x, y, z;
    while (!terminate) {
        if (read_gyro_data(&x, &y, &z) == 0) {
            log_data(x, y, z);
        } else {
            fprintf(stderr, "Error reading gyro data. Retrying...\n");
        }
        gpioDelay(100); // 10 Hz sampling rate
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

