#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 18

// Define constants
#define TIMEOUT_US 50000 // 50ms timeout
#define TRIGGER_PULSE_US 10 // 10us trigger pulse
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define DISTANCE_THRESHOLD 100.0 // Distance threshold in cm

// Global variables
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Structure to hold echo pulse timestamps
typedef struct {
    uint32_t rising_edge;
    uint32_t falling_edge;
} EchoPulse;

// Function prototypes
void signal_handler(int signal);
int initialize_gpio();
void trigger_sensor();
int read_echo(EchoPulse *pulse);
double calculate_distance(EchoPulse pulse);
void log_distance(double distance);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Set pull-down resistor on echo pin to avoid floating input
    gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN);

    return 0;
}

// Trigger the ultrasonic sensor
void trigger_sensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(TRIGGER_PULSE_US);
    gpioWrite(TRIGGER_PIN, 0);
}

// Read the echo pulse duration
int read_echo(EchoPulse *pulse) {
    uint32_t start_tick, end_tick;

    // Wait for rising edge
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < TIMEOUT_US) {
        count++;
        gpioDelay(1); // Small delay to avoid busy-waiting
    }

    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Timeout waiting for rising edge\n");
        return -1;
    }

    pulse->rising_edge = gpioTick();

    // Wait for falling edge
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < TIMEOUT_US) {
        count++;
        gpioDelay(1);
    }

    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Timeout waiting for falling edge\n");
        return -1;
    }

    pulse->falling_edge = gpioTick();

    return 0;
}

// Calculate the distance in centimeters
double calculate_distance(EchoPulse pulse) {
    uint32_t pulse_width = pulse.falling_edge - pulse.rising_edge;
    if (pulse_width > TIMEOUT_US) {
        pulse_width = TIMEOUT_US; // Cap the pulse width to avoid overflow
    }
    double time_taken = (double)pulse_width / 1000000.0; // Time in seconds
    double distance = (time_taken * SPEED_OF_SOUND) / 2.0; // Distance in cm
    return distance;
}

// Log the distance to a file
void log_distance(double distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (distance < 0) {
        fprintf(log_file, "%s,-1\n", timestamp);
        fprintf(stderr, "%s,-1\n", timestamp);
    } else {
        fprintf(log_file, "%s,%.2f\n", timestamp, distance);
        fprintf(stderr, "%s,%.2f\n", timestamp, distance);
    }
    fflush(log_file); // Ensure data is written to disk immediately
}

// Cleanup function to release resources
void cleanup() {
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    EchoPulse pulse;

    // Main loop
    while (program_running) {
        trigger_sensor();
        gpioDelay(60); // Wait 60ms between measurements

        if (read_echo(&pulse) == 0) {
            double distance = calculate_distance(pulse);
            log_distance(distance);

            if (distance < DISTANCE_THRESHOLD) {
                fprintf(stderr, "Warning: Object detected within threshold!\n");
            }
        } else {
            log_distance(-1.0);
        }

        gpioDelay(1000); // Wait 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

