#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>

// MPU6050 I2C address
#define MPU6050_ADDR 0x68

// MPU6050 registers
#define PWR_MGMT_1   0x6B
#define GYRO_XOUT_H  0x43
#define GYRO_YOUT_H  0x45
#define GYRO_ZOUT_H  0x47

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler function
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    terminate = 1;
}

// Function to read a 16-bit value from the MPU6050
int16_t read_gyro_axis(int handle, uint8_t reg) {
    char buf[2];
    int result = i2cReadI2CBlockData(handle, reg, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading gyro axis %d: %s\n", reg, strerror(errno));
        return 0; // Return 0 on error
    }
    return (int16_t)((buf[0] << 8) | buf[1]);
}

// Function to read gyroscope data
void read_gyro_data(int handle, float *x, float *y, float *z) {
    int16_t raw_x = read_gyro_axis(handle, GYRO_XOUT_H);
    int16_t raw_y = read_gyro_axis(handle, GYRO_YOUT_H);
    int16_t raw_z = read_gyro_axis(handle, GYRO_ZOUT_H);

    // Convert raw values to degrees per second (DPS)
    *x = (float)raw_x / 131.0;
    *y = (float)raw_y / 131.0;
    *z = (float)raw_z / 131.0;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Wake up the MPU6050
    if (i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0) < 0) {
        fprintf(stderr, "Error writing to PWR_MGMT_1: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float x, y, z;

    // Main loop
    while (!terminate) {
        read_gyro_data(i2c_handle, &x, &y, &z);
        printf("X: %.2f, Y: %.2f, Z: %.2f\n", x, y, z);
        gpioDelay(100000); // 100ms delay
    }

    // Clean up
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

