#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins for the relays
#define RELAY1_PIN 17
#define RELAY2_PIN 18
#define RELAY3_PIN 27
#define RELAY4_PIN 22

// Define the log file name
#define LOG_FILE "watering_log.txt"

// Function prototypes
int initialize_gpio();
void activate_relay(int pin, int duration_seconds);
void deactivate_relay(int pin);
void log_watering_cycle();
void cleanup_gpio();
void signal_handler(int signal);

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

int main() {
    // Install signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the pigpio library and GPIO pins
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Failed to initialize GPIO. Exiting.\n");
        return 1;
    }

    // Main loop
    while (program_running) {
        // Log the start time of the watering cycle
        log_watering_cycle();

        // Activate each relay in sequence
        activate_relay(RELAY1_PIN, 5);
        activate_relay(RELAY2_PIN, 5);
        activate_relay(RELAY3_PIN, 5);
        activate_relay(RELAY4_PIN, 5);

        // Wait for 24 hours before repeating the cycle
        time_sleep(86400.0);
    }

    // Cleanup GPIO before exiting
    cleanup_gpio();

    return 0;
}

// Function to initialize the pigpio library and GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs with active-low semantics
    gpioSetMode(RELAY1_PIN, PI_OUTPUT);
    gpioSetMode(RELAY2_PIN, PI_OUTPUT);
    gpioSetMode(RELAY3_PIN, PI_OUTPUT);
    gpioSetMode(RELAY4_PIN, PI_OUTPUT);

    // Set all relays to inactive (HIGH)
    gpioWrite(RELAY1_PIN, 1);
    gpioWrite(RELAY2_PIN, 1);
    gpioWrite(RELAY3_PIN, 1);
    gpioWrite(RELAY4_PIN, 1);

    return 0;
}

// Function to activate a relay for a specified duration
void activate_relay(int pin, int duration_seconds) {
    // Activate the relay (set pin LOW)
    gpioWrite(pin, 0);
    printf("Relay on pin %d activated for %d seconds\n", pin, duration_seconds);

    // Wait for the specified duration
    time_sleep((double)duration_seconds);

    // Deactivate the relay (set pin HIGH)
    gpioWrite(pin, 1);
    printf("Relay on pin %d deactivated\n", pin);
}

// Function to deactivate a relay
void deactivate_relay(int pin) {
    gpioWrite(pin, 1);
}

// Function to log the watering cycle start time to a file
void log_watering_cycle() {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char s[64];
    strftime(s, sizeof(s), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s: Watering cycle started\n", s);
    fclose(fp);
}

// Function to cleanup GPIO pins and terminate the pigpio library
void cleanup_gpio() {
    // Set all relays to inactive (HIGH)
    gpioWrite(RELAY1_PIN, 1);
    gpioWrite(RELAY2_PIN, 1);
    gpioWrite(RELAY3_PIN, 1);
    gpioWrite(RELAY4_PIN, 1);

    gpioTerminate();
    printf("GPIO cleanup complete. Exiting.\n");
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d. Exiting gracefully.\n", signal);
    program_running = 0;
}

