#include <pigpio.h>

// Define GPIO pins for the relays
#define RELAY1_PIN 17
#define RELAY2_PIN 18
#define RELAY3_PIN 27
#define RELAY4_PIN 22

// Define PWM frequency
#define PWM_FREQUENCY 1000

// Define sunrise duration (in seconds)
#define SUNRISE_DURATION 1800

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int set_gpio_mode(int pin, int mode);
int set_pwm_range(int pin, int range);
int set_pwm_frequency(int pin, int frequency);
int set_pwm_dutycycle(int pin, int dutycycle);
int log_event(const char *message);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    log_event("Received signal, shutting down...");
    cleanup();
    exit(0);
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        log_event("pigpio initialisation failed");
        return -1;
    }

    // Set GPIO pins as outputs
    if (set_gpio_mode(RELAY1_PIN, PI_OUTPUT) != 0 ||
        set_gpio_mode(RELAY2_PIN, PI_OUTPUT) != 0 ||
        set_gpio_mode(RELAY3_PIN, PI_OUTPUT) != 0 ||
        set_gpio_mode(RELAY4_PIN, PI_OUTPUT) != 0) {
        return -1;
    }

    // Set PWM range
    if (set_pwm_range(RELAY1_PIN, 255) != 0 ||
        set_pwm_range(RELAY2_PIN, 255) != 0 ||
        set_pwm_range(RELAY3_PIN, 255) != 0 ||
        set_pwm_range(RELAY4_PIN, 255) != 0) {
        return -1;
    }

    // Set PWM frequency
    if (set_pwm_frequency(RELAY1_PIN, PWM_FREQUENCY) != 0 ||
        set_pwm_frequency(RELAY2_PIN, PWM_FREQUENCY) != 0 ||
        set_pwm_frequency(RELAY3_PIN, PWM_FREQUENCY) != 0 ||
        set_pwm_frequency(RELAY4_PIN, PWM_FREQUENCY) != 0) {
        return -1;
    }

    return 0;
}

// Function to set GPIO mode
int set_gpio_mode(int pin, int mode) {
    int result = gpioSetMode(pin, mode);
    if (result != 0) {
        char message[100];
        sprintf(message, "Failed to set GPIO %d mode to %d: %d", pin, mode, result);
        log_event(message);
        return -1;
    }
    return 0;
}

// Function to set PWM range
int set_pwm_range(int pin, int range) {
    int result = gpioSetPWMrange(pin, range);
    if (result != 0) {
        char message[100];
        sprintf(message, "Failed to set PWM range for GPIO %d to %d: %d", pin, range, result);
        log_event(message);
        return -1;
    }
    return 0;
}

// Function to set PWM frequency
int set_pwm_frequency(int pin, int frequency) {
    int result = gpioSetPWMfrequency(pin, frequency);
    if (result != 0) {
        char message[100];
        sprintf(message, "Failed to set PWM frequency for GPIO %d to %d: %d", pin, frequency, result);
        log_event(message);
        return -1;
    }
    return 0;
}

// Function to set PWM duty cycle
int set_pwm_dutycycle(int pin, int dutycycle) {
    int result = gpioPWM(pin, dutycycle);
    if (result != 0) {
        char message[100];
        sprintf(message, "Failed to set PWM duty cycle for GPIO %d to %d: %d", pin, dutycycle, result);
        log_event(message);
        return -1;
    }
    return 0;
}

// Function to log events to a file
int log_event(const char *message) {
    FILE *fp = fopen("smart_lighting.log", "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[100];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "[%s] %s\n", timestamp, message);
    fclose(fp);
    return 0;
}

// Function to cleanup GPIO resources
void cleanup() {
    // Turn off all relays
    set_pwm_dutycycle(RELAY1_PIN, 0);
    set_pwm_dutycycle(RELAY2_PIN, 0);
    set_pwm_dutycycle(RELAY3_PIN, 0);
    set_pwm_dutycycle(RELAY4_PIN, 0);

    gpioTerminate();
    log_event("GPIO resources released.");
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        log_event("GPIO initialization failed, exiting...");
        return 1;
    }

    log_event("Smart lighting system started.");

    // Sunrise effect
    for (int i = 0; i <= SUNRISE_DURATION && program_running; i++) {
        int dutycycle = (int)(((float)i / SUNRISE_DURATION) * 255);
        char message[100];
        sprintf(message, "Setting duty cycle to %d", dutycycle);
        log_event(message);

        if (set_pwm_dutycycle(RELAY1_PIN, dutycycle) != 0 ||
            set_pwm_dutycycle(RELAY2_PIN, dutycycle) != 0 ||
            set_pwm_dutycycle(RELAY3_PIN, dutycycle) != 0 ||
            set_pwm_dutycycle(RELAY4_PIN, dutycycle) != 0) {
            log_event("Failed to set duty cycle, exiting...");
            break;
        }

        gpioDelay(1000); // Wait for 1 second
    }

    log_event("Sunrise effect complete.");

    // Cleanup and exit
    cleanup();
    return 0;
}

