        char message[100];
        sprintf(message, "Failed to set PWM range for GPIO %d to %d: %d", pin, range, result);
        log_event(message);
        return -1;
    }
    return 0;
}

// Function to set PWM frequency
int set_pwm_frequency(int pin, int frequency) {
    int result = gpioSetPWMfrequency(pin, frequency);
    if (result != 0) {
        char message[100];
        sprintf(message, "Failed to set PWM frequency for GPIO %d to %d: %d", pin, frequency, result);
        log_event(message);
        return -1;
    }
    return 0;
}

// Function to set PWM duty cycle
int set_pwm_dutycycle(int pin, int dutycycle) {
    int result = gpioPWM(pin, dutycycle);
    if (result != 0) {
        char message[100];
        sprintf(message, "Failed to set PWM duty cycle for GPIO %d to %d: %d", pin, dutycycle, result);
        log_event(message);
        return -1;
    }
    return 0;
}

// Function to log events to a file
int log_event(const char *message) {
    FILE *fp = fopen("smart_lighting.log", "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[100];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "[%s] %s\n", timestamp, message);
    fclose(fp);
    return 0;
}

// Function to cleanup GPIO resources
void cleanup() {
    // Turn off all relays
    set_pwm_dutycycle(RELAY1_PIN, 0);
    set_pwm_dutycycle(RELAY2_PIN, 0);
    set_pwm_dutycycle(RELAY3_PIN, 0);
    set_pwm_dutycycle(RELAY4_PIN, 0);

    gpioTerminate();
    log_event("GPIO resources released.");
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        log_event("GPIO initialization failed, exiting...");
        return 1;
    }

    log_event("Smart lighting system started.");

    // Sunrise effect
    for (int i = 0; i <= SUNRISE_DURATION && program_running; i++) {
        int dutycycle = (int)(((float)i / SUNRISE_DURATION) * 255);
        char message[100];
        sprintf(message, "Setting duty cycle to %d", dutycycle);
        log_event(message);

        if (set_pwm_dutycycle(RELAY1_PIN, dutycycle) != 0 ||
            set_pwm_dutycycle(RELAY2_PIN, dutycycle) != 0 ||
            set_pwm_dutycycle(RELAY3_PIN, dutycycle) != 0 ||
            set_pwm_dutycycle(RELAY4_PIN, dutycycle) != 0) {
            log_event("Failed to set duty cycle, exiting...");
            break;
        }

        gpioDelay(1000); // Wait for 1 second
    }

    log_event("Sunrise effect complete.");

    // Cleanup and exit
    cleanup();
    return 0;
}

