#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <pigpio.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define CS_GPIO 8
#define GYRO_SENSITIVITY 131.0 // LSB/deg/s for +/- 250 deg/s range
#define LOG_FILE "gyro_log.txt"
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10
#define SAMPLE_INTERVAL_MS 10

// MPU9250 Registers
#define GYRO_XOUT_H 0x43
#define GYRO_YOUT_H 0x45
#define GYRO_ZOUT_H 0x47

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold gyroscope data
typedef struct {
    float x_rate;
    float y_rate;
    float z_rate;
} gyro_data_t;

// Function prototypes
int init_spi();
int init_gpio();
int read_gyro_data(gyro_data_t *data);
char* get_iso8601_timestamp(char* timestamp_str, size_t timestamp_str_size);
int log_data(const char *timestamp, float x_rate, float y_rate, float z_rate);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Initialize SPI
int init_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Initialize GPIO
int init_gpio() {
    if (gpioSetMode(CS_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", CS_GPIO);
        return -1;
    }
    gpioWrite(CS_GPIO, 1); // De-assert CS initially
    return 0;
}

// Read gyroscope data
int read_gyro_data(gyro_data_t *data) {
    char tx_buf[1];
    char rx_buf[6];
    int retries = 0;

    tx_buf[0] = GYRO_XOUT_H | 0x80; // Read multiple bytes starting from GYRO_XOUT_H

    gpioWrite(CS_GPIO, 0); // Assert CS
    while (retries < RETRY_COUNT) {
        int result = spiXfer(spi_handle, tx_buf, rx_buf, 7); // Read 6 bytes + register address
        gpioWrite(CS_GPIO, 1); // De-assert CS

        if (result == 7) {
            // Combine high and low bytes for each axis
            int16_t x = (rx_buf[1] << 8) | rx_buf[2];
            int16_t y = (rx_buf[3] << 8) | rx_buf[4];
            int16_t z = (rx_buf[5] << 8) | rx_buf[6];

            data->x_rate = (float)x / GYRO_SENSITIVITY;
            data->y_rate = (float)y / GYRO_SENSITIVITY;
            data->z_rate = (float)z / GYRO_SENSITIVITY;
            return 0; // Success
        } else {
            fprintf(stderr, "SPI read error (attempt %d): %d\n", retries + 1, result);
            retries++;
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            gpioWrite(CS_GPIO, 0); // Re-assert CS
        }
    }
    fprintf(stderr, "Failed to read gyro data after %d retries\n", RETRY_COUNT);
    return -1; // Failure
}

// Get ISO 8601 timestamp with nanosecond resolution
char* get_iso8601_timestamp(char* timestamp_str, size_t timestamp_str_size) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);

    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);

    strftime(timestamp_str, timestamp_str_size, "%Y-%m-%dT%H:%M:%S", &tm_info);
    snprintf(timestamp_str + strlen(timestamp_str), timestamp_str_size - strlen(timestamp_str), ".%09ldZ", ts.tv_nsec);
    return timestamp_str;
}

// Log data to file
int log_data(const char *timestamp, float x_rate, float y_rate, float z_rate) {
    if (fprintf(log_file, "%s,%.3f,%.3f,%.3f\n", timestamp, x_rate, y_rate, z_rate) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }
    fflush(log_file); // Ensure data is written immediately
    return 0;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(CS_GPIO, 1); // De-assert CS
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize SPI
    if (init_spi() != 0) {
        cleanup();
        return 1;
    }

    // Initialize GPIO
    if (init_gpio() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    gyro_data_t gyro_data;
    char timestamp_str[30];

    printf("Starting data acquisition...\n");

    while (!terminate) {
        // Read gyroscope data
        if (read_gyro_data(&gyro_data) == 0) {
            // Get timestamp
            get_iso8601_timestamp(timestamp_str, sizeof(timestamp_str));

            // Log data
            if (log_data(timestamp_str, gyro_data.x_rate, gyro_data.y_rate, gyro_data.z_rate) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
        } else {
            fprintf(stderr, "Error reading gyroscope data\n");
        }

        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Delay in microseconds
    }

    // Cleanup and exit
    cleanup();
    printf("Exiting.\n");
    return 0;
}

