#define GYRO_XOUT_L 0x44
#define GYRO_YOUT_H 0x45
#define GYRO_YOUT_L 0x46
#define GYRO_ZOUT_H 0x47
#define GYRO_ZOUT_L 0x48
#define LED_GPIO 17
#define THRESHOLD 200.0 // deg/s
#define BUFFER_SIZE 64

// Data structure for gyroscope readings
typedef struct {
    long long timestamp;
    int16_t x;
    int16_t y;
    int16_t z;
} gyro_data_t;

// Circular buffer
gyro_data_t gyro_buffer[BUFFER_SIZE];
int buffer_index = 0;

// SPI handle
int spi_handle;

// Function prototypes
