int read_gyro_data(int16_t *x, int16_t *y, int16_t *z);
void store_data(int16_t x, int16_t y, int16_t z);
void check_threshold(int16_t x, int16_t y, int16_t z);
void blink_led();
void signal_handler(int signal);
void print_buffer();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    spiClose(spi_handle);
    gpioWrite(LED_GPIO, 0); // Turn off LED
    gpioTerminate();
    exit(0);
}

// Initialize SPI
int init_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Read gyroscope data
int read_gyro_data(int16_t *x, int16_t *y, int16_t *z) {
    char tx_buf[1];
    char rx_buf[6];

    // Read X axis
    tx_buf[0] = GYRO_XOUT_H | 0x80; // Set MSB for read
    if (spiXfer(spi_handle, tx_buf, rx_buf, 1) != 0) {
        fprintf(stderr, "Error reading X axis\n");
        return -1;
    }
    *x = (int16_t)((rx_buf[0] << 8) | rx_buf[1]);

    // Read Y axis
    tx_buf[0] = GYRO_YOUT_H | 0x80;
    if (spiXfer(spi_handle, tx_buf, rx_buf, 1) != 0) {
