#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <string.h>

// MPU6050 I2C address
#define MPU6050_ADDR 0x68

// MPU6050 registers
#define PWR_MGMT_1 0x6B
#define ACCEL_XOUT_H 0x3B
#define GYRO_XOUT_H 0x43

// LED GPIO pin
#define LED_PIN 21

// I2C handle
int i2c_handle;

// File pointer for logging
FILE *log_file;

// Function prototypes
int init_mpu6050();
int read_raw_data(int16_t *accel_x, int16_t *accel_y, int16_t *accel_z, int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z);
void calculate_roll_pitch(int16_t accel_x, int16_t accel_y, int16_t accel_z, float *roll, float *pitch);
void log_data(float roll, float pitch);
void control_led(float roll, float pitch);
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    int16_t accel_x;
    int16_t accel_y;
    int16_t accel_z;
    int16_t gyro_x;
    int16_t gyro_y;
    int16_t gyro_z;
} sensor_data_t;

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize MPU6050
    if (init_mpu6050() != 0) {
        fprintf(stderr, "MPU6050 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set LED pin as output
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Open log file
    log_file = fopen("tilt_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    sensor_data_t sensor_data;
    float roll, pitch;

    // Main loop
    while (1) {
        // Read sensor data
        if (read_raw_data(&sensor_data.accel_x, &sensor_data.accel_y, &sensor_data.accel_z, &sensor_data.gyro_x, &sensor_data.gyro_y, &sensor_data.gyro_z) != 0) {
            fprintf(stderr, "Failed to read sensor data\n");
            continue; // Continue to the next iteration
        }

        // Calculate roll and pitch
        calculate_roll_pitch(sensor_data.accel_x, sensor_data.accel_y, sensor_data.accel_z, &roll, &pitch);

        // Print roll and pitch to console
        printf("Roll: %.2f, Pitch: %.2f\n", roll, pitch);

        // Log data to file
        log_data(roll, pitch);

        // Control LED
        control_led(roll, pitch);

        // Wait 100ms
        gpioDelay(100000); // 100ms = 100000 microseconds
    }

    return 0;
}

// Initialize MPU6050
int init_mpu6050() {
    // Wake up the MPU6050 (clear sleep bit)
    if (i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0) < 0) {
        fprintf(stderr, "Failed to write to PWR_MGMT_1\n");
        return -1;
    }
    gpioDelay(100000); // Wait 100ms
    return 0;
}

// Read raw accelerometer and gyroscope data
int read_raw_data(int16_t *accel_x, int16_t *accel_y, int16_t *accel_z, int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z) {
    char buf[14];
    if (i2cReadI2CBlockData(i2c_handle, ACCEL_XOUT_H, buf, 14) != 14) {
        fprintf(stderr, "Failed to read sensor data\n");
        return -1;
    }

    *accel_x = (int16_t)((buf[0] << 8) | buf[1]);
    *accel_y = (int16_t)((buf[2] << 8) | buf[3]);
    *accel_z = (int16_t)((buf[4] << 8) | buf[5]);
    *gyro_x = (int16_t)((buf[8] << 8) | buf[9]);
    *gyro_y = (int16_t)((buf[10] << 8) | buf[11]);
    *gyro_z = (int16_t)((buf[12] << 8) | buf[13]);

    return 0;
}

// Calculate roll and pitch from accelerometer data
void calculate_roll_pitch(int16_t accel_x, int16_t accel_y, int16_t accel_z, float *roll, float *pitch) {
    float ax = (float)accel_x;
    float ay = (float)accel_y;
    float az = (float)accel_z;

    *roll = atan2(ay, az) * 180 / M_PI;
    *pitch = atan2(-ax, sqrt(ay * ay + az * az)) * 180 / M_PI;
}

// Log data to file
void log_data(float roll, float pitch) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, roll, pitch);
    fflush(log_file); // Ensure data is written to file immediately
}

// Control LED based on roll and pitch
void control_led(float roll, float pitch) {
    if (fabs(roll) > 45 || fabs(pitch) > 45) {
        gpioWrite(LED_PIN, 1); // Turn LED on
    } else {
        gpioWrite(LED_PIN, 0); // Turn LED off
    }
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Ctrl+C pressed. Cleaning up...\n");

    // Turn off LED
    gpioWrite(LED_PIN, 0);

    // Close I2C bus
    i2cClose(i2c_handle);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

