#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// ADXRS290 Register Addresses
#define ADXRS290_REG_X_RATE 0x00
#define ADXRS290_REG_Y_RATE 0x02
#define ADXRS290_REG_TEMP   0x04
#define ADXRS290_REG_DIAG   0x06
#define ADXRS290_REG_ID     0x08

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_CE0 8
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0

// Global Variables
int spi_handle = -1;
FILE *fp = NULL;
volatile sig_atomic_t program_running = 1;

// Function Prototypes
int spi_init();
int read_register(uint8_t reg_addr, int16_t *data);
int write_register(uint8_t reg_addr, uint8_t data);
int16_t read_x_rate();
int16_t read_y_rate();
void log_data(int16_t x_rate, int16_t y_rate);
void signal_handler(int signal);
void cleanup();

// Structure for grouping gyroscope data
typedef struct {
    int16_t x_rate;
    int16_t y_rate;
} gyro_data_t;

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize SPI
    if (spi_init() != 0) {
        fprintf(stderr, "SPI initialisation failed\n");
        cleanup();
        return 1;
    }

    // Open CSV file for logging
    fp = fopen("gyro_data.csv", "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open gyro_data.csv\n");
        cleanup();
        return 1;
    }

    // Write CSV header if the file is newly created
    fseek(fp, 0, SEEK_END);
    long fsize = ftell(fp);
    if (fsize == 0) {
        fprintf(fp, "timestamp,x_rate,y_rate\n");
    }
    rewind(fp);

    // Main loop
    while (program_running) {
        gyro_data_t gyro_data;

        // Read gyroscope data
        gyro_data.x_rate = read_x_rate();
        gyro_data.y_rate = read_y_rate();

        // Log data to file
        log_data(gyro_data.x_rate, gyro_data.y_rate);

        // Delay for 10 ms
        gpioDelay(10000); // 10 ms = 10000 microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize SPI interface
int spi_init() {
    int retries = 3;
    while (retries > 0) {
        spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
        if (spi_handle >= 0) {
            return 0; // Success
        } else {
            fprintf(stderr, "SPI open failed, retrying... (%d retries left)\n", retries - 1);
            gpioDelay(100000); // Wait 100 ms before retrying
            retries--;
        }
    }
    fprintf(stderr, "SPI initialisation failed after multiple retries\n");
    return -1; // Failure
}

// Read data from a specific register
int read_register(uint8_t reg_addr, int16_t *data) {
    char tx_buf[2];
    char rx_buf[2];

    tx_buf[0] = reg_addr | 0x80; // Set read bit (MSB)
    tx_buf[1] = 0x00; // Dummy byte

    if (spiXfer(spi_handle, tx_buf, rx_buf, 2) != 0) {
        fprintf(stderr, "SPI transfer failed for register 0x%02X\n", reg_addr);
        return -1;
    }

    *data = (int16_t)((rx_buf[1] << 8) | rx_buf[0]); // Combine bytes to form 16-bit data
    return 0;
}

// Write data to a specific register
int write_register(uint8_t reg_addr, uint8_t data) {
    char tx_buf[2];
    char rx_buf[2];

    tx_buf[0] = reg_addr & 0x7F; // Clear read bit (MSB)
    tx_buf[1] = data;

    if (spiXfer(spi_handle, tx_buf, rx_buf, 2) != 0) {
        fprintf(stderr, "SPI transfer failed for register 0x%02X\n", reg_addr);
        return -1;
    }

    return 0;
}

// Read X-axis rate
int16_t read_x_rate() {
    int16_t x_rate;
    if (read_register(ADXRS290_REG_X_RATE, &x_rate) != 0) {
        fprintf(stderr, "Failed to read X-axis rate\n");
        return 0; // Return 0 on error
    }
    return x_rate;
}

// Read Y-axis rate
int16_t read_y_rate() {
    int16_t y_rate;
    if (read_register(ADXRS290_REG_Y_RATE, &y_rate) != 0) {
        fprintf(stderr, "Failed to read Y-axis rate\n");
        return 0; // Return 0 on error
    }
    return y_rate;
}

// Log data to CSV file
void log_data(int16_t x_rate, int16_t y_rate) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    double timestamp = (double)ts.tv_sec + (double)ts.tv_nsec / 1000000000.0;

    fprintf(fp, "%lf,%d,%d\n", timestamp, x_rate, y_rate);
    fflush(fp); // Flush the buffer to ensure data is written to file
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    program_running = 0;
    printf("Ctrl+C pressed, exiting...\n");
}

// Cleanup resources
void cleanup() {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (fp != NULL) {
        fclose(fp);
    }
    gpioTerminate();
}

