#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define SENSOR_1_PIN 23
#define SENSOR_2_PIN 24
#define ALERT_PIN 17

// Debounce time in milliseconds
#define DEBOUNCE_TIME 500

// Alert duration in milliseconds
#define ALERT_DURATION 2000

// Global variables
FILE *log_file = NULL;
volatile int running = 1;

// Function prototypes
void sensor_callback(int gpio, int level, uint32_t tick);
void signal_handler(int signal);
int initialize();
void cleanup();

// Structure to hold sensor state
typedef struct {
    uint32_t last_tick;
    int high_count;
} sensor_state_t;

sensor_state_t sensor1_state = {0, 0};
sensor_state_t sensor2_state = {0, 0};

// Function to get current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%S%z", timeinfo);
    return timestamp;
}

// Callback function for sensor 1
void sensor1_callback(int gpio, int level, uint32_t tick) {
    if (level == PI_HIGH) {
        if (tick - sensor1_state.last_tick > DEBOUNCE_TIME * 1000) { // Convert ms to microseconds
            sensor1_state.last_tick = tick;
            sensor1_state.high_count++;
            printf("Sensor 1 HIGH\n");
        }
    } else if (level == PI_LOW) {
        sensor1_state.high_count = 0; // Reset count on LOW
    }

    if (sensor1_state.high_count >= 2 && sensor2_state.high_count >= 2) {
        // Both sensors are HIGH for the debounce time
        gpioWrite(ALERT_PIN, 1); // Set alert pin HIGH
        gpioDelay(ALERT_DURATION); // Wait for alert duration
        gpioWrite(ALERT_PIN, 0); // Set alert pin LOW

        // Log seismic event
        char* timestamp = get_iso8601_timestamp();
        fprintf(log_file, "%s - Seismic event detected!\n", timestamp);
        fflush(log_file); // Flush the buffer to ensure immediate write
        free(timestamp); // Free the allocated memory
    }
}

// Callback function for sensor 2
void sensor2_callback(int gpio, int level, uint32_t tick) {
    if (level == PI_HIGH) {
        if (tick - sensor2_state.last_tick > DEBOUNCE_TIME * 1000) { // Convert ms to microseconds
            sensor2_state.last_tick = tick;
            sensor2_state.high_count++;
            printf("Sensor 2 HIGH\n");
        }
    } else if (level == PI_LOW) {
        sensor2_state.high_count = 0; // Reset count on LOW
    }

    if (sensor1_state.high_count >= 2 && sensor2_state.high_count >= 2) {
        // Both sensors are HIGH for the debounce time
        gpioWrite(ALERT_PIN, 1); // Set alert pin HIGH
        gpioDelay(ALERT_DURATION); // Wait for alert duration
        gpioWrite(ALERT_PIN, 0); // Set alert pin LOW

        // Log seismic event
        char* timestamp = get_iso8601_timestamp();
        fprintf(log_file, "%s - Seismic event detected!\n", timestamp);
        fflush(log_file); // Flush the buffer to ensure immediate write
        free(timestamp); // Free the allocated memory
    }
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    running = 0;
    cleanup();
    exit(0);
}

// Initialization function
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen("seismic_events.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(SENSOR_1_PIN, PI_INPUT);
    gpioSetMode(SENSOR_2_PIN, PI_INPUT);
    gpioSetMode(ALERT_PIN, PI_OUTPUT);

    // Set pull-down resistors
    gpioSetPullUpDown(SENSOR_1_PIN, PI_PUD_DOWN);
    gpioSetPullUpDown(SENSOR_2_PIN, PI_PUD_DOWN);

    // Register callbacks
    if (gpioSetAlertFuncEx(SENSOR_1_PIN, sensor1_callback, NULL) != 0) {
