typedef struct {
    uint32_t last_tick;
    int high_count;
} sensor_state_t;

sensor_state_t sensor1_state = {0, 0};
sensor_state_t sensor2_state = {0, 0};

// Function to get current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%S%z", timeinfo);
    return timestamp;
}

// Callback function for sensor 1
void sensor1_callback(int gpio, int level, uint32_t tick) {
    if (level == PI_HIGH) {
        if (tick - sensor1_state.last_tick > DEBOUNCE_TIME * 1000) { // Convert ms to microseconds
            sensor1_state.last_tick = tick;
            sensor1_state.high_count++;
            printf("Sensor 1 HIGH\n");
        }
    } else if (level == PI_LOW) {
        sensor1_state.high_count = 0; // Reset count on LOW
    }

