#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>

// Define constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0
#define CE0_GPIO 8
#define LED_GPIO 17
#define THRESHOLD 20.0  // deg/s
#define BUFFER_SIZE 100

// ADXRS290 Register Addresses
#define REG_X_RATE 0x00 // X-axis angular rate

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Structure for circular buffer entries
typedef struct {
    struct timespec timestamp;
    float rate;
} buffer_entry_t;

// Circular buffer
buffer_entry_t circular_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int spi_init();
int spi_read_register(uint8_t reg_addr, uint8_t *data, int len);
float convert_to_deg_per_sec(uint16_t raw_data);
void add_to_circular_buffer(float rate);
float get_latest_rate();
void control_led(int on);
void signal_handler(int signal);
void cleanup();

// SPI Initialization function
int spi_init() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI channel: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// SPI Read Register function
int spi_read_register(uint8_t reg_addr, uint8_t *data, int len) {
    char tx_buf[1];
    char rx_buf[len];
    int result;

    // Set MSB of register address to 1 for read operation
    tx_buf[0] = reg_addr | 0x80;

    result = spiXfer(spi_handle, tx_buf, rx_buf, len + 1);
    if (result != len + 1) {
        fprintf(stderr, "Error during SPI transfer: %d\n", result);
        return -1;
    }

    // Copy the received data to the output buffer
    for (int i = 0; i < len; i++) {
        data[i] = rx_buf[i + 1];
    }

    return 0;
}

// Convert raw data to degrees per second
float convert_to_deg_per_sec(uint16_t raw_data) {
    // The ADXRS290 outputs a 14-bit value, right-aligned.
    // The sensitivity is 0.03125 degrees per second per LSB.
    // The formula is: Rate = (Raw Data - 2^13) * Sensitivity
    // Where Raw Data is the 14-bit value from the register.
    // The 2^13 offset is due to the two's complement representation.

    int16_t signed_data = (int16_t)(raw_data << 2); // Left-align the 14-bit data
    signed_data = signed_data >> 2; // Right-align back to 14 bits

    return (float)signed_data * 0.03125; // Sensitivity
}

// Add data to circular buffer
void add_to_circular_buffer(float rate) {
    clock_gettime(CLOCK_MONOTONIC, &circular_buffer[buffer_index].timestamp);
    circular_buffer[buffer_index].rate = rate;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Get the latest rate from the circular buffer
float get_latest_rate() {
    int index = (buffer_index - 1 + BUFFER_SIZE) % BUFFER_SIZE; // Get the last index
    return circular_buffer[index].rate;
}

// Control the LED
void control_led(int on) {
    gpioWrite(LED_GPIO, on);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function
void cleanup() {
    spiClose(spi_handle);
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Initialize SPI
    if (spi_init() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uint8_t data[2];
    float rate;
    int led_state = 0;

    // Main loop
    while (!terminate) {
        // Read X-axis angular rate
        if (spi_read_register(REG_X_RATE, data, 2) == 0) {
            uint16_t raw_data = (data[0] << 8) | data[1];
            rate = convert_to_deg_per_sec(raw_data);

            // Add to circular buffer
            add_to_circular_buffer(rate);

            // Check threshold and control LED
            if (fabs(rate) > THRESHOLD) {
                if (led_state == 0) {
                    control_led(1);
                    led_state = 1;
                }
            } else {
                if (led_state == 1) {
                    control_led(0);
                    led_state = 0;
                }
            }

            // Print the rate (for debugging)
            printf("Rate: %.2f deg/s\n", rate);
        } else {
            fprintf(stderr, "Error reading gyroscope data\n");
        }

        gpioDelay(10000); // 10 ms delay
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

