#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for the lamps
#define LAMP1_GPIO 17
#define LAMP2_GPIO 18
#define LAMP3_GPIO 27

// Define PWM frequency
#define PWM_FREQUENCY 100

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    printf("\nCaught signal %d, terminating program...\n", signal);
    program_running = 0;
}

// Function to set the PWM duty cycle for a given GPIO pin
void set_pwm_duty_cycle(int gpio, int duty_cycle) {
    gpioPWM(gpio, duty_cycle);
}

// Function to fade a lamp from full brightness to off
void fade_lamp(int gpio, int duration_seconds) {
    int num_steps = duration_seconds * 100; // 100 steps per second
    int duty_cycle_step = 255 / num_steps;
    int current_duty_cycle = 255;

    printf("Fading lamp on GPIO %d for %d seconds...\n", gpio, duration_seconds);

    for (int i = 0; i < num_steps && program_running; ++i) {
        current_duty_cycle -= duty_cycle_step;
        if (current_duty_cycle < 0) {
            current_duty_cycle = 0;
        }
        set_pwm_duty_cycle(gpio, current_duty_cycle);
        gpioDelay(10000); // 10ms delay (10000 microseconds)
    }

    // Ensure the lamp is fully off after fading
    set_pwm_duty_cycle(gpio, 0);
    printf("Lamp on GPIO %d faded to off.\n", gpio);
}

int main(int argc, char *argv[]) {
    // Check for command-line argument
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <duration_seconds>\n", argv[0]);
        return 1;
    }

    // Parse the duration from the command-line argument
    int duration_seconds = atoi(argv[1]);

    // Validate the duration
    if (duration_seconds < 1 || duration_seconds > 3600) {
        fprintf(stderr, "Error: Duration must be between 1 and 3600 seconds.\n");
        return 1;
    }

    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(LAMP1_GPIO, PI_OUTPUT);
    gpioSetMode(LAMP2_GPIO, PI_OUTPUT);
    gpioSetMode(LAMP3_GPIO, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(LAMP1_GPIO, PWM_FREQUENCY);
    gpioSetPWMfrequency(LAMP2_GPIO, PWM_FREQUENCY);
    gpioSetPWMfrequency(LAMP3_GPIO, PWM_FREQUENCY);

    // Set PWM range (0-255)
    gpioSetPWMrange(LAMP1_GPIO, 255);
    gpioSetPWMrange(LAMP2_GPIO, 255);
    gpioSetPWMrange(LAMP3_GPIO, 255);

    // Register signal handlers for graceful termination
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Fade the lamps sequentially
    fade_lamp(LAMP1_GPIO, duration_seconds);
    fade_lamp(LAMP2_GPIO, duration_seconds);
    fade_lamp(LAMP3_GPIO, duration_seconds);

    // Turn off all lamps
    set_pwm_duty_cycle(LAMP1_GPIO, 0);
    set_pwm_duty_cycle(LAMP2_GPIO, 0);
    set_pwm_duty_cycle(LAMP3_GPIO, 0);

    printf("All lamps turned off. Program terminated.\n");

    // Terminate the pigpio library
    gpioTerminate();

    return 0;
}

