#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for the relays (BCM numbering)
#define RED_PIN   17
#define YELLOW_PIN 22
#define GREEN_PIN  23
#define YELLOW2_PIN 24

// Function prototypes
int initialize_gpio();
void set_relay_state(int pin, int state);
void cleanup_gpio();
void signal_handler(int signal);

// Global variable to track program state for signal handling
volatile sig_atomic_t program_running = 1;

int main() {
    // Install signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the pigpio library and GPIO pins
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Failed to initialize GPIO. Exiting.\n");
        return 1;
    }

    // Main loop to simulate the traffic light sequence
    while (program_running) {
        // Red light
        set_relay_state(RED_PIN, 0);   // Turn on red
        set_relay_state(YELLOW_PIN, 1);  // Turn off yellow
        set_relay_state(GREEN_PIN, 1);   // Turn off green
        set_relay_state(YELLOW2_PIN, 1); // Turn off yellow2
        printf("Red\n");
