#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define MPR121_ADDR 0x5A
#define ELECTRODE_0 0
#define GPIO_RELAY 17
#define DEBOUNCE_DELAY 100 // milliseconds
#define POLLING_INTERVAL 10 // milliseconds

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_mpr121();
int read_touch_status(uint16_t *touch_status);
int debounce_touch(uint16_t touch_status);
int toggle_relay();
void log_message(const char *message);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    log_message("Signal received, exiting...");
}

// Logging function
void log_message(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    fprintf(log_file, "%d-%02d-%02d %02d:%02d:%02d: %s\n",
            t->tm_year + 1900, t->tm_mon + 1, t->tm_mday, t->tm_hour, t->tm_min, t->tm_sec, message);
    fflush(log_file);
}

// Initialize MPR121
int init_mpr121() {
    // Stop mode
    if (i2cWriteByteData(i2c_handle, 0x80, 0x63) < 0) {
        log_message("Error: Failed to set MPR121 to stop mode.");
        return -1;
    }
    gpioDelay(10000); // 10ms delay

    // Electrode configuration
    if (i2cWriteByteData(i2c_handle, 0x5E, 0x0C) < 0) { // Set Electrode Configuration
        log_message("Error: Failed to set electrode configuration.");
        return -1;
    }

    // Touch and release thresholds (example values)
    for (int i = 0; i < 12; i++) {
        if (i2cWriteByteData(i2c_handle, 0x41 + 2 * i, 0x30) < 0) { // Touch threshold
            log_message("Error: Failed to set touch threshold.");
            return -1;
        }
        if (i2cWriteByteData(i2c_handle, 0x42 + 2 * i, 0x10) < 0) { // Release threshold
            log_message("Error: Failed to set release threshold.");
            return -1;
        }
    }

    // Configure and start the MPR121
    if (i2cWriteByteData(i2c_handle, 0x5B, 0x01) < 0) { // Enable all electrodes
        log_message("Error: Failed to enable electrodes.");
        return -1;
    }

    if (i2cWriteByteData(i2c_handle, 0x5C, 0x0F) < 0) { // Set operation mode
        log_message("Error: Failed to set operation mode.");
        return -1;
    }

    if (i2cWriteByteData(i2c_handle, 0x80, 0x10) < 0) { // Start the MPR121
        log_message("Error: Failed to start MPR121.");
        return -1;
    }

    gpioDelay(10000); // 10ms delay

    return 0;
}

// Read touch status from MPR121
int read_touch_status(uint16_t *touch_status) {
    char buf[2];
    if (i2cReadI2CBlockData(i2c_handle, 0x00, buf, 2) != 2) {
        log_message("Error: Failed to read touch status.");
        return -1;
    }
    *touch_status = ((uint16_t)buf[1] << 8) | (uint16_t)buf[0];
    return 0;
}

// Debounce touch event
int debounce_touch(uint16_t touch_status) {
    static uint16_t last_touch_status = 0;
    static uint32_t last_touch_time = 0;
    uint32_t current_time = gpioTick();

    if ((touch_status & (1 << ELECTRODE_0)) && !(last_touch_status & (1 << ELECTRODE_0))) {
        // Electrode 0 touched
        if (current_time - last_touch_time > DEBOUNCE_DELAY * 1000) { // Convert ms to us
            last_touch_status = touch_status;
            last_touch_time = current_time;
            return 1; // Valid touch
        }
    } else if (!(touch_status & (1 << ELECTRODE_0)) && (last_touch_status & (1 << ELECTRODE_0))) {
        // Electrode 0 released
        last_touch_status = touch_status;
        last_touch_time = current_time;
    } else {
        last_touch_status = touch_status;
    }

    return 0; // No valid touch
}

// Toggle relay state
int toggle_relay() {
    int current_level = gpioRead(GPIO_RELAY);
    int new_level = (current_level == 0) ? 1 : 0;
    if (gpioWrite(GPIO_RELAY, new_level) < 0) {
        log_message("Error: Failed to write to GPIO.");
        return -1;
    }
    char message[100];
    snprintf(message, sizeof(message), "Relay toggled to %d", new_level);
    log_message(message);
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen("touch_relay.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    log_message("Program started");

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        log_message("Error: Failed to open I2C bus.");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Initialize MPR121
    if (init_mpr121() < 0) {
        log_message("Error: MPR121 initialization failed.");
        i2cClose(i2c_handle);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Set GPIO17 as output
    gpioSetMode(GPIO_RELAY, PI_OUTPUT);
    gpioWrite(GPIO_RELAY, 0); // Initialize to LOW
    log_message("GPIO17 set as output and initialized to LOW");

    uint16_t touch_status;

    // Main loop
    while (!terminate) {
        if (read_touch_status(&touch_status) == 0) {
            if (debounce_touch(touch_status)) {
                if (toggle_relay() < 0) {
                    log_message("Error: Relay toggle failed.");
                }
            }
        } else {
            log_message("Error: Failed to read touch status.");
        }
        gpioDelay(POLLING_INTERVAL * 1000); // Convert ms to us
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(GPIO_RELAY, 0); // Set relay to LOW on exit
    gpioSetMode(GPIO_RELAY, PI_INPUT); // Release GPIO
    fclose(log_file);
    gpioTerminate();

    log_message("Program terminated");

    return 0;
}

