#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define FLAME_SENSOR_PIN 17
#define BUZZER_PIN 18
#define LED_PIN 23

// Define constants
#define DEBOUNCE_READS 3
#define DEBOUNCE_DELAY_MS 50
#define LOG_FILE "flame_log.txt"

// Global variables
FILE *log_file = NULL;
int running = 1;

// Function prototypes
int read_flame_sensor();
int debounce_flame_sensor();
void log_flame_detection();
void activate_alert();
void deactivate_alert();
void signal_handler(int signal);

// Function to read the flame sensor
int read_flame_sensor() {
    return gpioRead(FLAME_SENSOR_PIN);
}

// Function to debounce the flame sensor
int debounce_flame_sensor() {
    int low_count = 0;
    for (int i = 0; i < DEBOUNCE_READS; i++) {
        if (read_flame_sensor() == 0) {
            low_count++;
        }
        gpioDelay(DEBOUNCE_DELAY_MS * 1000); // Delay in microseconds
    }
    return (low_count == DEBOUNCE_READS);
}

// Function to log flame detection
void log_flame_detection() {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s Flame Detected\n", timestamp);
        fflush(log_file); // Ensure data is written to the file immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Function to activate the alert (buzzer and LED)
void activate_alert() {
    gpioWrite(BUZZER_PIN, 1); // Turn on buzzer
    gpioWrite(LED_PIN, 1);    // Turn on LED
}

// Function to deactivate the alert (buzzer and LED)
void deactivate_alert() {
    gpioWrite(BUZZER_PIN, 0); // Turn off buzzer
    gpioWrite(LED_PIN, 0);    // Turn off LED
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    running = 0;
    deactivate_alert();

    if (log_file != NULL) {
        fclose(log_file);
    }

    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        if (debounce_flame_sensor()) {
            log_flame_detection();
            activate_alert();
            // Wait for flame to clear
            while (debounce_flame_sensor() && running) {
                gpioDelay(100000); // Check every 100ms
            }
            deactivate_alert();
        }
        gpioDelay(100000); // Check every 100ms
    }

    // Cleanup (should not reach here if signal handler works correctly)
    deactivate_alert();
    fclose(log_file);
    gpioTerminate();

    return 0;
}

