#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Motor A
#define MOTOR_A_FORWARD 17
#define MOTOR_A_BACKWARD 18
#define ENA 24

// Motor B
#define MOTOR_B_FORWARD 22
#define MOTOR_B_BACKWARD 23
#define ENB 25

// Ultrasonic sensor
#define ULTRASONIC_DISTANCE 200

// PID constants
#define KP 0.5
#define KI 0.01
#define KD 0.1

// Obstacle avoidance threshold
#define OBSTACLE_THRESHOLD 20

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;
static float integral = 0.0;
static float previous_error = 0.0;

// Function prototypes
float generate_tilt_error();
float generate_distance();
void set_motor_speed(int motor, int speed);
void stop_motors();
void log_data(float tilt_error, float distance, int motor_a_speed, int motor_b_speed);
void signal_handler(int signal);
float pid_control(float tilt_error);

// Function to generate a random tilt error between -10 and 10 degrees
float generate_tilt_error() {
    return ((float)rand() / RAND_MAX) * 20.0 - 10.0;
}

// Function to generate a random distance between 2 and 400 cm
float generate_distance() {
    return ((float)rand() / RAND_MAX) * 398.0 + 2.0;
}

// Function to set the speed of a motor
void set_motor_speed(int motor, int speed) {
    if (speed > 255) speed = 255;
    if (speed < -255) speed = -255;

    if (motor == MOTOR_A_FORWARD) {
        gpioWrite(MOTOR_A_FORWARD, 1);
        gpioWrite(MOTOR_A_BACKWARD, 0);
        gpioPWM(ENA, abs(speed));
    } else if (motor == MOTOR_A_BACKWARD) {
        gpioWrite(MOTOR_A_FORWARD, 0);
        gpioWrite(MOTOR_A_BACKWARD, 1);
        gpioPWM(ENA, abs(speed));
    } else if (motor == MOTOR_B_FORWARD) {
        gpioWrite(MOTOR_B_FORWARD, 1);
        gpioWrite(MOTOR_B_BACKWARD, 0);
        gpioPWM(ENB, abs(speed));
    } else if (motor == MOTOR_B_BACKWARD) {
        gpioWrite(MOTOR_B_FORWARD, 0);
        gpioWrite(MOTOR_B_BACKWARD, 1);
        gpioPWM(ENB, abs(speed));
    } else {
        fprintf(stderr, "Invalid motor character: %d\n", motor);
    }
}

// Function to stop both motors
void stop_motors() {
    set_motor_speed(MOTOR_A_FORWARD, 0);
    set_motor_speed(MOTOR_A_BACKWARD, 0);
    set_motor_speed(MOTOR_B_FORWARD, 0);
    set_motor_speed(MOTOR_B_BACKWARD, 0);
}

// Function to log data to a file
void log_data(float tilt_error, float distance, int motor_a_speed, int motor_b_speed) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (log_file != NULL) {
        fprintf(log_file, "%s,%.2f,%.2f,%d,%d\n", timestamp, tilt_error, distance, motor_a_speed, motor_b_speed);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    running = 0;
    printf("Stopping motors and exiting...\n");
    stop_motors();
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

// PID control function
float pid_control(float tilt_error) {
    integral += tilt_error;
    float derivative = tilt_error - previous_error;
    float output = KP * tilt_error + KI * integral + KD * derivative;
    previous_error = tilt_error;
    return output;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(MOTOR_A_FORWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_A_BACKWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_B_FORWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_B_BACKWARD, PI_OUTPUT);
    gpioSetMode(ENA, PI_OUTPUT);
    gpioSetMode(ENB, PI_OUTPUT);

    // Set PWM range (0-255)
    gpioSetPWMrange(ENA, 255);
    gpioSetPWMrange(ENB, 255);

    // Open log file
    log_file = fopen("balance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Seed the random number generator
    srand(time(NULL));

    // Main loop
    while (running) {
        // Generate tilt error and distance
        float tilt_error = generate_tilt_error();
        float distance = generate_distance();

        // Obstacle avoidance
        if (distance < OBSTACLE_THRESHOLD) {
            set_motor_speed(MOTOR_A_FORWARD, 0);
            set_motor_speed(MOTOR_A_BACKWARD, 0);
            set_motor_speed(MOTOR_B_FORWARD, 0);
            set_motor_speed(MOTOR_B_BACKWARD, 0);
            set_motor_speed(MOTOR_A_FORWARD, -128);
            set_motor_speed(MOTOR_A_BACKWARD, -128);
            set_motor_speed(MOTOR_B_FORWARD, -128);
            set_motor_speed(MOTOR_B_BACKWARD, -128);
            gpioDelay(500); // Reverse for 500ms
            stop_motors();
        } else {
            // PID control
            float pid_output = pid_control(tilt_error);

            // Motor speeds
            int motor_a_speed = (int)pid_output;
            int motor_b_speed = (int)pid_output;

            // Clamp motor speeds
            if (motor_a_speed > 255) motor_a_speed = 255;
            if (motor_a_speed < -255) motor_a_speed = -255;
            if (motor_b_speed > 255) motor_b_speed = 255;
            if (motor_b_speed < -255) motor_b_speed = -255;

            // Set motor speeds
            set_motor_speed(MOTOR_A_FORWARD, motor_a_speed);
            set_motor_speed(MOTOR_A_BACKWARD, -motor_a_speed);
            set_motor_speed(MOTOR_B_FORWARD, motor_b_speed);
            set_motor_speed(MOTOR_B_BACKWARD, -motor_b_speed);

            // Log data
            log_data(tilt_error, distance, motor_a_speed, motor_b_speed);
        }

        // Delay
        gpioDelay(50); // 50ms
    }

    // Cleanup
    stop_motors();
    fclose(log_file);
    gpioTerminate();

    return 0;
}

