#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17

// Debounce delay in milliseconds
#define DEBOUNCE_DELAY 50

// Global variable to store the relay state
static volatile int relay_state = 0;

// Function prototypes
int initialize_gpio();
int read_touch_sensor();
void toggle_relay();
void cleanup_gpio();
void signal_handler(int signal);

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    // Set GPIO4 as input with pull-down resistor
    gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(TOUCH_SENSOR_PIN, PI_PUD_DOWN);

    // Set GPIO17 as output
    gpioSetMode(RELAY_PIN, PI_OUTPUT);

    return 0; // Indicate success
}

// Function to read the touch sensor
int read_touch_sensor() {
    return gpioRead(TOUCH_SENSOR_PIN);
}

// Function to toggle the relay state
void toggle_relay() {
    relay_state = !relay_state;
    gpioWrite(RELAY_PIN, relay_state);
    printf("Relay toggled to state: %d\n", relay_state);
}

// Function to cleanup GPIO resources
void cleanup_gpio() {
    printf("Cleaning up GPIO resources...\n");
    gpioWrite(RELAY_PIN, 0); // Deactivate relay
    gpioTerminate(); // Terminate pigpio
}

// Signal handler for SIGINT and SIGTERM
