#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <pigpio.h>
#include <alsa/asoundlib.h>

// Define GPIO pins for RGB LED
#define RED_PIN   17
#define GREEN_PIN 18
#define BLUE_PIN  27

// Default values
#define DEFAULT_SAMPLE_RATE 8000
#define DEFAULT_PERIOD_SIZE 1024
#define DEFAULT_SENSITIVITY 1.0

// Global variables
static volatile int running = 1;
static snd_pcm_t *pcm_handle = NULL;
static float sensitivity = DEFAULT_SENSITIVITY;

// Function prototypes
void signal_handler(int signal);
int initialize_alsa(snd_pcm_t **pcm_handle, int sample_rate, int period_size);
void capture_audio(snd_pcm_t *pcm_handle, float *audio_buffer, int period_size);
double calculate_rms(const short *audio_data, int num_frames);
void map_amplitude_to_color(double rms_amplitude, int *red, int *green, int *blue);
void set_led_color(int red, int green, int blue);
void cleanup(snd_pcm_t *pcm_handle);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, cleaning up...\n");
    running = 0;
}

// Initialize ALSA
int initialize_alsa(snd_pcm_t **pcm_handle, int sample_rate, int period_size) {
    snd_pcm_hw_params_t *hw_params;
    int err;

    // Open PCM device for capture
    if ((err = snd_pcm_open(pcm_handle, "default", SND_PCM_STREAM_CAPTURE, 0)) < 0) {
        fprintf(stderr, "Error opening PCM device: %s\n", snd_strerror(err));
        return -1;
    }

    // Allocate hardware parameters object
    snd_pcm_hw_params_alloca(&hw_params);

    // Initialize hardware parameters
    if ((err = snd_pcm_hw_params_any(*pcm_handle, hw_params)) < 0) {
        fprintf(stderr, "Error initializing hardware parameters: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    // Set access type to interleaved
    if ((err = snd_pcm_hw_params_set_access(*pcm_handle, hw_params, SND_PCM_ACCESS_RW_INTERLEAVED)) < 0) {
        fprintf(stderr, "Error setting access type: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    // Set format to 16-bit signed little-endian
    if ((err = snd_pcm_hw_params_set_format(*pcm_handle, hw_params, SND_PCM_FORMAT_S16_LE)) < 0) {
        fprintf(stderr, "Error setting format: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    // Set sample rate
    unsigned int exact_rate = sample_rate;
    if ((err = snd_pcm_hw_params_set_rate_near(*pcm_handle, hw_params, &exact_rate, 0)) < 0) {
        fprintf(stderr, "Error setting sample rate: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm_handle);
        return -1;
    }
    if (exact_rate != sample_rate) {
        fprintf(stderr, "Warning: Sample rate changed to %d\n", exact_rate);
    }

    // Set number of channels to 1 (mono)
    if ((err = snd_pcm_hw_params_set_channels(*pcm_handle, hw_params, 1)) < 0) {
        fprintf(stderr, "Error setting channels: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    // Set period size
    snd_pcm_uframes_t period_size_frames = period_size;
    if ((err = snd_pcm_hw_params_set_period_size_near(*pcm_handle, hw_params, &period_size_frames, 0)) < 0) {
        fprintf(stderr, "Error setting period size: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm_handle);
        return -1;
    }
    if (period_size_frames != period_size) {
        fprintf(stderr, "Warning: Period size changed to %d\n", period_size_frames);
    }

    // Apply hardware parameters
    if ((err = snd_pcm_hw_params(*pcm_handle, hw_params)) < 0) {
        fprintf(stderr, "Error setting hardware parameters: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    return 0;
}

// Capture audio data
void capture_audio(snd_pcm_t *pcm_handle, float *audio_buffer, int period_size) {
    int err;
    short *short_buffer = (short *)audio_buffer; // Cast to short for ALSA

    err = snd_pcm_readi(pcm_handle, short_buffer, period_size);
    if (err == -EPIPE) {
        // Overrun occurred
        fprintf(stderr, "Error: ALSA buffer overrun\n");
        snd_pcm_prepare(pcm_handle);
    } else if (err == -ESTRPIPE) {
        // Stream was suspended
        fprintf(stderr, "Error: ALSA stream suspended\n");
        while ((err = snd_pcm_resume(pcm_handle)) == -EAGAIN) {
            sleep(1); // Wait for the stream to resume
        }
        if (err < 0) {
            fprintf(stderr, "Error: Could not resume ALSA stream: %s\n", snd_strerror(err));
            snd_pcm_close(pcm_handle);
            exit(1);
        }
    } else if (err < 0) {
        fprintf(stderr, "Error reading from ALSA: %s\n", snd_strerror(err));
        snd_pcm_close(pcm_handle);
        exit(1);
    }
}

// Calculate RMS amplitude
double calculate_rms(const short *audio_data, int num_frames) {
    double sum_sq = 0.0;
    for (int i = 0; i < num_frames; i++) {
        sum_sq += (double)audio_data[i] * audio_data[i];
    }
    return sqrt(sum_sq / num_frames);
}

// Map amplitude to color (non-linear mapping)
void map_amplitude_to_color(double rms_amplitude, int *red, int *green, int *blue) {
    // Non-linear mapping (e.g., logarithmic)
    double log_amplitude = log10(rms_amplitude + 1); // Add 1 to avoid log(0)
    double normalized_amplitude = log_amplitude / log10(10000); // Scale to 0-1 (adjust 10000 as needed)

    // Clamp to 0-1 range
    if (normalized_amplitude < 0) normalized_amplitude = 0;
    if (normalized_amplitude > 1) normalized_amplitude = 1;

    // HSV to RGB conversion (example)
    double h = normalized_amplitude * 360; // Hue from 0 to 360
    double s = 1.0; // Saturation
    double v = 1.0; // Value (brightness)

    double C = v * s;
    double X = C * (1 - fabs(fmod(h / 60.0, 2) - 1));
    double m = v - C;

    double r = 0, g = 0, b = 0;
    if (h < 60) {
        r = C; g = X; b = 0;
    } else if (h < 120) {
        r = X; g = C; b = 0;
    } else if (h < 180) {
        r = 0; g = C; b = X;
    } else if (h < 240) {
        r = 0; g = X; b = C;
    } else if (h < 300) {
        r = X; g = 0; b = C;
    } else {
        r = C; g = 0; b = X;
    }

    r = (r + m) * 255;
    g = (g + m) * 255;
    b = (b + m) * 255;

    *red   = (int)r;
    *green = (int)g;
    *blue  = (int)b;
}

// Set LED color using software PWM
void set_led_color(int red, int green, int blue) {
    gpioPWM(RED_PIN, red);
    gpioPWM(GREEN_PIN, green);
    gpioPWM(BLUE_PIN, blue);
}

// Cleanup resources
void cleanup(snd_pcm_t *pcm_handle) {
    if (pcm_handle != NULL) {
        snd_pcm_drain(pcm_handle);
        snd_pcm_close(pcm_handle);
    }
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    int sample_rate = DEFAULT_SAMPLE_RATE;
    int period_size = DEFAULT_PERIOD_SIZE;
    float *audio_buffer = NULL;
    int red, green, blue;
    struct timespec sleep_time;
    int opt;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "s:p:")) != -1) {
        switch (opt) {
            case 's':
                sample_rate = atoi(optarg);
                break;
            case 'p':
                period_size = atoi(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-s sample_rate] [-p period_size]\n", argv[0]);
                return 1;
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error initializing pigpio\n");
        return 1;
    }

    // Set GPIO pins to output mode
    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);

    // Set PWM range (adjust as needed)
    gpioSetPWMrange(RED_PIN, 255);
    gpioSetPWMrange(GREEN_PIN, 255);
    gpioSetPWMrange(BLUE_PIN, 255);

    // Initialize ALSA
    if (initialize_alsa(&pcm_handle, sample_rate, period_size) != 0) {
        fprintf(stderr, "Error initializing ALSA\n");
        gpioTerminate();
        return 1;
    }

    // Allocate audio buffer
    audio_buffer = (float *)malloc(period_size * sizeof(float));
    if (audio_buffer == NULL) {
        fprintf(stderr, "Error allocating audio buffer\n");
        cleanup(pcm_handle);
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        // Capture audio
        capture_audio(pcm_handle, audio_buffer, period_size);

        // Calculate RMS amplitude
        double rms_amplitude = calculate_rms((const short *)audio_buffer, period_size);

        // Map amplitude to color
        map_amplitude_to_color(rms_amplitude, &red, &green, &blue);

        // Set LED color
        set_led_color(red, green, blue);

        // Sleep for 10 ms
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = 10 * 1000 * 1000; // 10 ms
        nanosleep(&sleep_time, NULL);
    }

    // Cleanup resources
    cleanup(pcm_handle);
    free(audio_buffer);

    return 0;
}

