#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins for the relays
#define RELAY1_PIN 17
#define RELAY2_PIN 27
#define RELAY3_PIN 22
#define RELAY4_PIN 23

// Define the duration of each phase in seconds
#define SUNRISE_DURATION 3600
#define DAYTIME_DURATION 21600
#define SUNSET_DURATION 3600
#define NIGHTTIME_DURATION 518400

// Define the PWM frequency (Hz)
#define PWM_FREQUENCY 100

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    printf("\nCaught signal, exiting gracefully...\n");
}

// Function to set the state of a relay (active low)
void set_relay_state(int pin, int state) {
    gpioWrite(pin, !state); // Active low
}

// Function to simulate sunrise
void simulate_sunrise() {
    printf("Simulating Sunrise...\n");
    for (int i = 0; i <= 100 && program_running; ++i) {
        // Calculate the duty cycle (0-100%)
        int duty_cycle = i;

        // Set the relay states based on the duty cycle
        set_relay_state(RELAY1_PIN, (duty_cycle > 0));
        set_relay_state(RELAY2_PIN, (duty_cycle > 0));
        set_relay_state(RELAY3_PIN, (duty_cycle > 0));
        set_relay_state(RELAY4_PIN, (duty_cycle > 0));

        // Delay to simulate the transition
        gpioDelay(3600000 / 100); // 3600000 ms / 100 = 36000 ms per 1% increment
    }
    printf("Sunrise complete.\n");
}

// Function to simulate sunset
void simulate_sunset() {
    printf("Simulating Sunset...\n");
    for (int i = 100; i >= 0 && program_running; --i) {
        // Calculate the duty cycle (0-100%)
        int duty_cycle = i;

        // Set the relay states based on the duty cycle
        set_relay_state(RELAY1_PIN, (duty_cycle > 0));
        set_relay_state(RELAY2_PIN, (duty_cycle > 0));
        set_relay_state(RELAY3_PIN, (duty_cycle > 0));
        set_relay_state(RELAY4_PIN, (duty_cycle > 0));

        // Delay to simulate the transition
        gpioDelay(3600000 / 100); // 3600000 ms / 100 = 36000 ms per 1% decrement
    }
    printf("Sunset complete.\n");
}

// Function to turn off all relays
void turn_off_relays() {
    printf("Turning off all relays...\n");
    set_relay_state(RELAY1_PIN, 0);
    set_relay_state(RELAY2_PIN, 0);
    set_relay_state(RELAY3_PIN, 0);
    set_relay_state(RELAY4_PIN, 0);
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set the GPIO pins as outputs
    gpioSetMode(RELAY1_PIN, PI_OUTPUT);
    gpioSetMode(RELAY2_PIN, PI_OUTPUT);
    gpioSetMode(RELAY3_PIN, PI_OUTPUT);
    gpioSetMode(RELAY4_PIN, PI_OUTPUT);

    // Set PWM frequency (not strictly needed for active-low relays, but good practice)
    gpioSetPWMfrequency(RELAY1_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(RELAY2_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(RELAY3_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(RELAY4_PIN, PWM_FREQUENCY);

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (program_running) {
        // Sunrise phase
        simulate_sunrise();
        if (!program_running) break;

        // Daytime phase
        gpioDelay(DAYTIME_DURATION);
        if (!program_running) break;

        // Sunset phase
        simulate_sunset();
        if (!program_running) break;

        // Nighttime phase
        gpioDelay(NIGHTTIME_DURATION);
        if (!program_running) break;
    }

    // Turn off all relays before exiting
    turn_off_relays();

    // Terminate the pigpio library
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

