#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR_PIN 17
#define DEBOUNCE_INTERVAL 200 // milliseconds
#define CAPTURE_DURATION 5      // seconds
#define LOG_FILE "/home/pi/logs/motion_log.txt"
#define VIDEO_DIR "/home/pi/videos/"

static volatile int running = 1;
static FILE *log_file = NULL;

// Function to generate ISO 8601 timestamp
char* iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp
    if (timestamp == NULL) {
        perror("Failed to allocate memory for timestamp");
        return NULL;
    }

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Function to capture video using raspivid
int capture_video(const char *filename) {
    char command[256];
    snprintf(command, sizeof(command), "raspivid -o %s -t %d", filename, CAPTURE_DURATION * 1000);
    int status = system(command);
    if (status == -1) {
        perror("Failed to execute raspivid command");
        return -1;
    }
    return status;
}

// Function to log motion event
int log_motion(const char *timestamp) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open.\n");
        return -1;
    }
    fprintf(log_file, "%s\n", timestamp);
    fflush(log_file); // Ensure the log is written immediately
    return 0;
}

// Function to handle motion detection
void handle_motion() {
    char *timestamp = iso8601_timestamp();
    if (timestamp == NULL) {
        fprintf(stderr, "Failed to generate timestamp.\n");
        return;
    }

    char filename[256];
    snprintf(filename, sizeof(filename), "%s%s.h264", VIDEO_DIR, timestamp);

    if (capture_video(filename) == 0) {
        if (log_motion(timestamp) != 0) {
            fprintf(stderr, "Failed to log motion event.\n");
        }
    } else {
        fprintf(stderr, "Failed to capture video.\n");
    }

    free(timestamp);
}

// Callback function for GPIO interrupt
void motion_callback(int gpio, int level, uint32_t tick) {
    static uint32_t last_tick = 0;
    uint32_t current_tick = gpioTick();

    if (level == 0) { // Falling edge (LOW level)
        if (current_tick - last_tick > DEBOUNCE_INTERVAL * 1000) { // Debounce
            handle_motion();
            last_tick = current_tick;
        }
    }
}

// Signal handler for SIGINT
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;

    if (log_file != NULL) {
        fclose(log_file);
    }

    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as input
    gpioSetMode(SENSOR_PIN, PI_INPUT);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Set up interrupt callback
    gpioSetAlertFunc(SENSOR_PIN, motion_callback);

    printf("Motion detection started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        sleep(1); // Reduce CPU usage
    }

    // Cleanup (should not reach here if signal handler works correctly)
    fclose(log_file);
    gpioTerminate();

    return 0;
}

