void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize MPU6050
int init_mpu6050(int i2c_handle) {
    int retries = 3;
    int status;

    while (retries > 0) {
        // Wake up the MPU6050 (clear sleep bit)
        status = i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0);
        if (status != 0) {
            fprintf(stderr, "Error: Could not wake up MPU6050 (attempt %d): %s\n", 4 - retries, strerror(errno));
            gpioDelay(10000); // Wait 10ms before retrying
            retries--;
            continue;
        }

        // Configure gyroscope range (+/- 250°/s)
        status = i2cWriteByteData(i2c_handle, GYRO_CONFIG, 0);
        if (status != 0) {
            fprintf(stderr, "Error: Could not configure gyroscope (attempt %d): %s\n", 4 - retries, strerror(errno));
            gpioDelay(10000); // Wait 10ms before retrying
            retries--;
            continue;
        }

        printf("MPU6050 initialized successfully.\n");
        return 0; // Success
    }

    fprintf(stderr, "Error: Failed to initialize MPU6050 after multiple retries.\n");
    return -1; // Failure
}

