// Define GPIO pins for the relays
#define RELAY1 4
#define RELAY2 17
#define RELAY3 27
#define RELAY4 22

// Define the log file name
#define LOG_FILE "irrigation_log.txt"

// Global variable for the log file pointer
FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int read_moisture_sensor();
void control_relay(int relay_pin, int state);
void log_data(int moisture_value, int relay1_state, int relay2_state, int relay3_state, int relay4_state);
void signal_handler(int signal);

// Structure to hold relay states
typedef struct {
    int relay1_state;
    int relay2_state;
    int relay3_state;
    int relay4_state;
} RelayStates;

// Function to initialize the pigpio library and set GPIO modes
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    gpioSetMode(RELAY1, PI_OUTPUT);
    gpioSetMode(RELAY2, PI_OUTPUT);
    gpioSetMode(RELAY3, PI_OUTPUT);
    gpioSetMode(RELAY4, PI_OUTPUT);

    // Initialize all relays to OFF (HIGH)
    control_relay(RELAY1, 1);
    control_relay(RELAY2, 1);
    control_relay(RELAY3, 1);
    control_relay(RELAY4, 1);

    return 0; // Indicate success
}

// Function to simulate reading the moisture sensor
int read_moisture_sensor() {
    // Seed the random number generator with the current time
    srand(time(NULL));

    // Generate a random number between 0 and 100
    int moisture_value = rand() % 101;

    return moisture_value;
}

// Function to control the relay state
void control_relay(int relay_pin, int state) {
    gpioWrite(relay_pin, state);
}

// Function to log the data to a file
void log_data(int moisture_value, int relay1_state, int relay2_state, int relay3_state, int relay4_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, Moisture: %d, Relay1: %s, Relay2: %s, Relay3: %s, Relay4: %s\n",
                timestamp,
                moisture_value,
                relay1_state ? "ON" : "OFF",
                relay2_state ? "ON" : "OFF",
                relay3_state ? "ON" : "OFF",
                relay4_state ? "ON" : "OFF");
        fflush(log_file); // Ensure data is written to the file immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);

    // Deactivate all relays
    control_relay(RELAY1, 1);
    control_relay(RELAY2, 1);
    control_relay(RELAY3, 1);
    control_relay(RELAY4, 1);

    // Close the log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate the pigpio library
    gpioTerminate();

    exit(0);
}

int main() {
    // Install signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize the pigpio library
    if (initialize_gpio() != 0) {
        return 1; // Exit if initialization fails
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        // Read the moisture sensor
        int moisture_value = read_moisture_sensor();

        // Determine relay states based on moisture value
        int relay1_state = (moisture_value < 30) ? 0 : 1;
        int relay2_state = (moisture_value < 30) ? 0 : 1;
        int relay3_state = (moisture_value < 30) ? 0 : 1;
        int relay4_state = (moisture_value < 30) ? 0 : 1;

        // Control the relays
        control_relay(RELAY1, relay1_state);
        control_relay(RELAY2, relay2_state);
        control_relay(RELAY3, relay3_state);
        control_relay(RELAY4, relay4_state);

        // Log the data
        log_data(moisture_value, relay1_state, relay2_state, relay3_state, relay4_state);

        // Wait for 5 seconds
        gpioDelay(5000); // pigpio's delay function is in milliseconds
    }

    return 0; // This line will never be reached due to the infinite loop
}

