#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <string.h>
#include <unistd.h>

// Define GPIO pins
#define TRIG_PIN 4
#define ECHO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define MAX_DISTANCE 400.0    // Maximum measurable distance in cm
#define TIMEOUT_US 100000      // Timeout in microseconds (100ms)
#define PULSE_WIDTH_MAX_US 23200 // Maximum pulse width in microseconds (4m)

// Global variables
static volatile uint32_t start_tick = 0;
static volatile uint32_t end_tick = 0;
static volatile int echo_received = 0;
static volatile int timeout_flag = 0;
static FILE *log_file = NULL;
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
static volatile int running = 1;

// Function prototypes
void trigger_pulse();
void echo_rising_edge(int gpio, int level, uint32_t tick);
void echo_falling_edge(int gpio, int level, uint32_t tick);
double calculate_distance(uint32_t pulse_width_us);
void log_distance(double distance_cm);
void signal_handler(int signal);
int initialize();
void cleanup();

// Function to generate a 10us trigger pulse
void trigger_pulse() {
    gpioWrite(TRIG_PIN, 1);
    gpioDelay(10); // 10us
    gpioWrite(TRIG_PIN, 0);
}

// Interrupt handler for rising edge of ECHO signal
void echo_rising_edge(int gpio, int level, uint32_t tick) {
    pthread_mutex_lock(&mutex);
    start_tick = tick;
    echo_received = 1; // Indicate rising edge received
    timeout_flag = 0;  // Reset timeout flag
    pthread_mutex_unlock(&mutex);
}

// Interrupt handler for falling edge of ECHO signal
void echo_falling_edge(int gpio, int level, uint32_t tick) {
    pthread_mutex_lock(&mutex);
    end_tick = tick;
    echo_received = 2; // Indicate falling edge received
    pthread_mutex_unlock(&mutex);
}

// Function to calculate distance in centimeters
double calculate_distance(uint32_t pulse_width_us) {
    return (double)pulse_width_us * SPEED_OF_SOUND / 2000000.0; // Convert us to s and divide by 2
}

// Function to log distance to file
void log_distance(double distance_cm) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    uint64_t timestamp_ns = (uint64_t)ts.tv_sec * 1000000000ULL + (uint64_t)ts.tv_nsec;

    if (log_file != NULL) {
        fprintf(log_file, "%llu,%.2f\n", timestamp_ns, distance_cm);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

// Initialization function
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(TRIG_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Set pull-down resistor for ECHO pin to avoid floating values
    gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN);

    // Set up interrupt handlers
    if (gpioSetISRFuncEx(ECHO_PIN, RISING_EDGE, 0, echo_rising_edge, NULL) != 0) {
        fprintf(stderr, "Error setting up rising edge interrupt\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetISRFuncEx(ECHO_PIN, FALLING_EDGE, 0, echo_falling_edge, NULL) != 0) {
        fprintf(stderr, "Error setting up falling edge interrupt\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    pthread_mutex_destroy(&mutex);
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    if (initialize()) {
        return 1;
    }

    printf("Ultrasonic sensor program started. Press Ctrl+C to exit.\n");

    while (running) {
        trigger_pulse();
        echo_received = 0; // Reset echo received flag
        timeout_flag = 0;  // Reset timeout flag

        // Wait for echo or timeout
        int timeout_count = 0;
        while (echo_received != 2 && timeout_count < TIMEOUT_US) {
            gpioDelay(1); // Check every 1us
            timeout_count++;
        }

        if (timeout_count >= TIMEOUT_US) {
            fprintf(stderr, "Timeout error: No echo received within %d us\n", TIMEOUT_US);
            timeout_flag = 1;
        }

        if (echo_received == 2) {
            uint32_t pulse_width_us = end_tick - start_tick;

            if (pulse_width_us > PULSE_WIDTH_MAX_US) {
                fprintf(stderr, "Invalid pulse width: %u us (exceeds max)\n", pulse_width_us);
            } else {
                double distance_cm = calculate_distance(pulse_width_us);
                if (distance_cm > MAX_DISTANCE) {
                    fprintf(stderr, "Invalid distance: %.2f cm (exceeds max)\n", distance_cm);
                } else {
                    log_distance(distance_cm);
                }
            }
        }

        gpioDelay(200); // Wait 200ms before next trigger
    }

    cleanup();
    return 0;
}

