#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// LIS3DH Register Addresses
#define LIS3DH_REG_CTRL1 0x20
#define LIS3DH_REG_CTRL4 0x23
#define LIS3DH_REG_OUT_X_L 0x28
#define LIS3DH_REG_OUT_X_H 0x29
#define LIS3DH_REG_OUT_Y_L 0x2A
#define LIS3DH_REG_OUT_Y_H 0x2B
#define LIS3DH_REG_OUT_Z_L 0x2C
#define LIS3DH_REG_OUT_Z_H 0x2D

// Default values
#define DEFAULT_I2C_ADDRESS 0x18
#define DEFAULT_THRESHOLD 2.0f

// Global variables
int i2c_handle;
int i2c_address;
float threshold;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_lis3dh(int i2c_handle);
int read_acceleration(int i2c_handle, float *x, float *y, float *z);
void log_data(float x, float y, float z);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    terminate = 1;
}

// Function to initialize the LIS3DH accelerometer
int initialize_lis3dh(int i2c_handle) {
    // Configure CTRL1: 100 Hz ODR, enable all axes
    if (i2cWriteByteData(i2c_handle, LIS3DH_REG_CTRL1, 0x77) < 0) {
        fprintf(stderr, "Error writing to CTRL1 register\n");
        return -1;
    }

    // Configure CTRL4: ±2g range, high-resolution 12-bit left-justified
    if (i2cWriteByteData(i2c_handle, LIS3DH_REG_CTRL4, 0x88) < 0) {
        fprintf(stderr, "Error writing to CTRL4 register\n");
        return -1;
    }

    return 0;
}

// Function to read acceleration data from the LIS3DH
int read_acceleration(int i2c_handle, float *x, float *y, float *z) {
    char buffer[6];
    int16_t raw_x, raw_y, raw_z;

    // Read all six registers at once
    if (i2cReadI2CBlockData(i2c_handle, LIS3DH_REG_OUT_X_L, buffer, 6) != 6) {
        fprintf(stderr, "Error reading acceleration data\n");
        *x = 0.0f;
        *y = 0.0f;
        *z = 0.0f;
        return -1;
    }

    // Combine high and low bytes for each axis
    raw_x = (int16_t)((buffer[1] << 8) | buffer[0]);
    raw_y = (int16_t)((buffer[3] << 8) | buffer[2]);
    raw_z = (int16_t)((buffer[5] << 8) | buffer[4]);

    // Convert to g-force units (assuming ±2g range and 12-bit resolution)
    *x = (float)raw_x / 16384.0f; // 2^15 = 32768 / 2 = 16384
    *y = (float)raw_y / 16384.0f;
    *z = (float)raw_z / 16384.0f;

    return 0;
}

// Function to log data to a file
void log_data(float x, float y, float z) {
    FILE *fp;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);

    fp = fopen("/var/log/high_acceleration.log", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file\n");
        return;
    }

    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d,%.3f,%.3f,%.3f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec,
            x, y, z);

    fclose(fp);
}

int main(int argc, char *argv[]) {
    int opt;
    float x, y, z;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "a:t:")) != -1) {
        switch (opt) {
            case 'a':
                i2c_address = strtol(optarg, NULL, 16);
                break;
            case 't':
                threshold = strtof(optarg, NULL);
                if (threshold <= 0.0f) {
                    fprintf(stderr, "Threshold must be greater than 0\n");
                    return 1;
                }
                break;
            default:
                fprintf(stderr, "Usage: %s [-a i2c_address] [-t threshold]\n", argv[0]);
                return 1;
        }
    }

    // Set default values if not provided
    if (i2c_address == 0) {
        i2c_address = DEFAULT_I2C_ADDRESS;
    }
    if (threshold == 0.0f) {
        threshold = DEFAULT_THRESHOLD;
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, i2c_address, 0); // Bus 1, address, flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize LIS3DH
    if (initialize_lis3dh(i2c_handle) < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read acceleration data
        if (read_acceleration(i2c_handle, &x, &y, &z) == 0) {
            // Check for threshold exceedance
            if (fabs(x) > threshold || fabs(y) > threshold || fabs(z) > threshold) {
                log_data(x, y, z);
                system("sudo shutdown -h now");
                break; // Exit loop after shutdown command
            }
