// Define GPIO pins
#define LEFT_SENSOR_PIN 4
#define CENTER_SENSOR_PIN 17
#define RIGHT_SENSOR_PIN 27
#define ALERT_LED_PIN 22

// Circular buffer size
#define BUFFER_SIZE 5

// Structure to hold sensor readings
typedef struct {
    int left;
    int center;
    int right;
} SensorReadings;

// Circular buffer structure
typedef struct {
    SensorReadings buffer[BUFFER_SIZE];
    int head;
    int tail;
    int count;
} CircularBuffer;

// Global variables
CircularBuffer sensor_buffer;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_sensor(int pin);
void add_to_buffer(CircularBuffer *buffer, SensorReadings readings);
SensorReadings get_from_buffer(CircularBuffer *buffer, int index);
int check_line_detection(CircularBuffer *buffer);
void move_forward();
void turn_left();
void turn_right();
void stop();
void alert();
void signal_handler(int signal);

// Function to read sensor value
int read_sensor(int pin) {
    return gpioRead(pin);
}

// Function to add readings to the circular buffer
void add_to_buffer(CircularBuffer *buffer, SensorReadings readings) {
    buffer->buffer[buffer->head] = readings;
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count < BUFFER_SIZE) {
        buffer->count++;
    } else {
        buffer->tail = (buffer->tail + 1) % BUFFER_SIZE;
    }
}

// Function to get readings from the circular buffer
SensorReadings get_from_buffer(CircularBuffer *buffer, int index) {
    return buffer->buffer[index];
}

// Function to check line detection
int check_line_detection(CircularBuffer *buffer) {
    if (buffer->count < 5) {
        return 0; // Not enough data yet
    }

    int no_line_count = 0;
    for (int i = 0; i < 5; i++) {
        if (buffer->buffer[(buffer->head - 1 - i + BUFFER_SIZE) % BUFFER_SIZE].center == 1) {
            no_line_count++;
        }
    }

    return (no_line_count == 5) ? 1 : 0;
}

