    gpioSetMode(LEFT_SENSOR_PIN, PI_INPUT);
    gpioSetMode(CENTER_SENSOR_PIN, PI_INPUT);
    gpioSetMode(RIGHT_SENSOR_PIN, PI_INPUT);
    gpioSetMode(ALERT_LED_PIN, PI_OUTPUT);

    // Initialize circular buffer
    sensor_buffer.head = 0;
    sensor_buffer.tail = 0;
    sensor_buffer.count = 0;

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Line-following robot started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read sensor values
        int left_value = read_sensor(LEFT_SENSOR_PIN);
        int center_value = read_sensor(CENTER_SENSOR_PIN);
        int right_value = read_sensor(RIGHT_SENSOR_PIN);

        // Create sensor readings struct
        SensorReadings readings = {left_value, center_value, right_value};

        // Add readings to the circular buffer
        add_to_buffer(&sensor_buffer, readings);

        // Check line detection
        if (check_line_detection(&sensor_buffer)) {
            alert();
        } else {
            // Determine motor control based on sensor values
            if (center_value == 0) {
                move_forward();
            } else if (left_value == 0) {
                turn_left();
            } else if (right_value == 0) {
                turn_right();
            } else {
                stop();
            }
        }

        gpioDelay(10); // Poll every 10 ms
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpioTerminate();
    return 0;
}

