#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SI7210_ADDR 0x40
#define HALL_REG 0x00
#define RELAY_GPIO 17
#define THRESHOLD 5.0 // mT
#define SAMPLE_INTERVAL 100 // ms
#define LOG_FILE "magnetic_events.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_si7210(int i2c_handle);
float convert_to_mT(int raw_value);
void control_relay(int gpio_pin, int state);
void log_event(const char *message);
void signal_handler(int signal);

// Function to read magnetic field data from Si7210
int read_si7210(int i2c_handle) {
    int raw_value = i2cReadWordData(i2c_handle, HALL_REG);
    if (raw_value < 0) {
        char error_message[100];
        snprintf(error_message, sizeof(error_message), "I2C read error: %d", raw_value);
        log_event(error_message);
        return -1; // Indicate error
    }
    return raw_value;
}

// Function to convert raw value to mT
float convert_to_mT(int raw_value) {
    // Assuming a linear relationship and a sensitivity of 0.1 mT/LSB
    return (float)raw_value * 0.1; // Example conversion
}

// Function to control the relay
void control_relay(int gpio_pin, int state) {
    gpioWrite(gpio_pin, state);
}

// Function to log events to file
void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s: %s\n", timestamp, message);
    fflush(log_file); // Ensure immediate write
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    log_event("Received signal, shutting down...");
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SI7210_ADDR, 0);
    if (i2c_handle < 0) {
        log_event("Failed to open I2C bus");
        gpioTerminate();
        return 1;
    }

    // Set relay GPIO as output
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    int relay_state = 0; // 0 = off, 1 = on
    float magnetic_field;

    log_event("Program started");

    while (program_running) {
        int raw_value = read_si7210(i2c_handle);
        if (raw_value >= 0) {
            magnetic_field = convert_to_mT(raw_value);

            // Check threshold and control relay
            if (magnetic_field > THRESHOLD) {
                if (relay_state == 0) {
                    control_relay(RELAY_GPIO, 1); // Activate relay
                    relay_state = 1;
                    log_event("Relay activated");
                }
            } else {
                if (relay_state == 1) {
                    control_relay(RELAY_GPIO, 0); // Deactivate relay
                    relay_state = 0;
                    log_event("Relay deactivated");
                }
            }

            // Log magnetic field reading
            char log_message[100];
            snprintf(log_message, sizeof(log_message), "Magnetic field: %.2f mT", magnetic_field);
            log_event(log_message);
        } else {
            // Retry after a delay
            gpioDelay(SAMPLE_INTERVAL * 1000); // Delay in microseconds
            continue;
        }

        gpioDelay(SAMPLE_INTERVAL * 1000); // Delay in microseconds
    }

    // Cleanup
    control_relay(RELAY_GPIO, 0); // Deactivate relay
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    log_event("Program terminated");

    return 0;
}

