#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SENSOR1_ADDR 0x70
#define SENSOR2_ADDR 0x71
#define RELAY_GPIO 18
#define FLOW_THRESHOLD 5.0
#define MEASUREMENT_COMMAND {0x36, 0x08}
#define CRC_POLYNOMIAL 0x31
#define CRC_INITIAL_VALUE 0xFF
#define LOG_FILE "flow_log.txt"

// Global variables
int i2c_handle1 = -1;
int i2c_handle2 = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_sensor(int i2c_handle, float *flow_rate);
int validate_crc(uint8_t data[], int len, uint8_t crc);
void control_relay(int gpio_pin, int state);
void log_data(float flow1, float flow2);
void signal_handler(int signal);
int initialize();
void cleanup();

// CRC-8 calculation function
uint8_t calculate_crc(uint8_t data[], int len) {
    uint8_t crc = CRC_INITIAL_VALUE;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read sensor data
int read_sensor(int i2c_handle, float *flow_rate) {
    uint8_t data[3];
    int bytes_read = i2cReadDevice(i2c_handle, (char *)data, 3);

    if (bytes_read != 3) {
        fprintf(stderr, "Error: Failed to read 3 bytes from sensor (read %d bytes)\n", bytes_read);
        return -1;
    }

    if (!validate_crc(data, 2, data[2])) {
        fprintf(stderr, "Error: CRC check failed for sensor data\n");
        return -1;
    }

    // Convert raw data to flow rate (ml/min)
    int16_t raw_flow = (data[0] << 8) | data[1];
    *flow_rate = (float)raw_flow / 120.0; // Scaling factor from datasheet

    return 0;
}

// Function to validate CRC
int validate_crc(uint8_t data[], int len, uint8_t crc) {
    uint8_t calculated_crc = calculate_crc(data, len);
    return (calculated_crc == crc);
}

// Function to control the relay
void control_relay(int gpio_pin, int state) {
    gpioWrite(gpio_pin, state);
}

// Function to log data to file
void log_data(float flow1, float flow2) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    char timestamp[100];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));
    snprintf(timestamp + strlen(timestamp), sizeof(timestamp) - strlen(timestamp), ".%03ld", ts.tv_nsec / 1000000);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, flow1, flow2);
    fflush(log_file);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Initialization function
int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle1 = i2cOpen(I2C_BUS, SENSOR1_ADDR, 0);
    if (i2c_handle1 < 0) {
        fprintf(stderr, "Error: Failed to open I2C device for sensor 1 (error code %d)\n", i2c_handle1);
        gpioTerminate();
        return -1;
    }

    i2c_handle2 = i2cOpen(I2C_BUS, SENSOR2_ADDR, 0);
    if (i2c_handle2 < 0) {
        fprintf(stderr, "Error: Failed to open I2C device for sensor 2 (error code %d)\n", i2c_handle2);
        i2cClose(i2c_handle1);
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO mode for relay\n");
        i2cClose(i2c_handle1);
        i2cClose(i2c_handle2);
        gpioTerminate();
        return -1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        i2cClose(i2c_handle1);
        i2cClose(i2c_handle2);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Cleanup function
void cleanup() {
    if (i2c_handle1 >= 0) i2cClose(i2c_handle1);
    if (i2c_handle2 >= 0) i2cClose(i2c_handle2);
    if (log_file != NULL) fclose(log_file);
    gpioWrite(RELAY_GPIO, 0); // De-energize relay
    gpioTerminate();
    fprintf(stderr, "Cleanup complete. Exiting.\n");
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (initialize() != 0) {
        return 1;
    }

    while (!terminate) {
        float flow1, flow2;

        // Read sensor data
        if (read_sensor(i2c_handle1, &flow1) != 0) {
            fprintf(stderr, "Error reading sensor 1, skipping cycle\n");
            continue;
        }
        if (read_sensor(i2c_handle2, &flow2) != 0) {
            fprintf(stderr, "Error reading sensor 2, skipping cycle\n");
            continue;
        }

        // Log data
        log_data(flow1, flow2);

        // Control relay
        if (flow1 < FLOW_THRESHOLD || flow2 < FLOW_THRESHOLD) {
            control_relay(RELAY_GPIO, 1); // Energize relay
        } else {
            control_relay(RELAY_GPIO, 0); // De-energize relay
        }

        gpioDelay(100); // 100ms delay
    }

    cleanup();
    return 0;
}

