#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define RAIN_SENSOR_PIN 17
#define MOTOR_ENA_PIN 22
#define MOTOR_IN1_PIN 23
#define MOTOR_IN2_PIN 24

// Define motor control parameters
#define MOTOR_DURATION_MS 5000

// Global variables
volatile sig_atomic_t program_running = 1;
int dry_count = 0;

// Function prototypes
int initialize_gpio();
int read_rain_sensor();
int control_motor(int start);
void signal_handler(int signal);
void cleanup();

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }

    gpioSetMode(RAIN_SENSOR_PIN, PI_INPUT);
    gpioSetMode(MOTOR_ENA_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_IN1_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_IN2_PIN, PI_OUTPUT);

    gpioSetPullUpDown(RAIN_SENSOR_PIN, PI_PUD_UP);

    gpioWrite(MOTOR_ENA_PIN, 0);
    gpioWrite(MOTOR_IN1_PIN, 0);
    gpioWrite(MOTOR_IN2_PIN, 0);

    syslog(LOG_INFO, "GPIO initialization complete");
    return 0;
}

// Function to read the rain sensor
int read_rain_sensor() {
    return gpioRead(RAIN_SENSOR_PIN);
}

// Function to control the motor
int control_motor(int start) {
    if (start) {
        gpioWrite(MOTOR_ENA_PIN, 1);
        gpioWrite(MOTOR_IN1_PIN, 1);
        gpioWrite(MOTOR_IN2_PIN, 0);
        syslog(LOG_INFO, "Motor started");
        usleep(MOTOR_DURATION_MS * 1000); // Convert ms to microseconds
        gpioWrite(MOTOR_ENA_PIN, 0);
        gpioWrite(MOTOR_IN1_PIN, 0);
        gpioWrite(MOTOR_IN2_PIN, 0);
        syslog(LOG_INFO, "Motor stopped");
    } else {
        gpioWrite(MOTOR_ENA_PIN, 0);
        gpioWrite(MOTOR_IN1_PIN, 0);
        gpioWrite(MOTOR_IN2_PIN, 0);
    }
    return 0;
}

// Signal handler function
void signal_handler(int signal) {
    syslog(LOG_INFO, "Signal received, shutting down...");
    program_running = 0;
}

