#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define SERVO_PIN 18
#define LOCK_BUTTON_PIN 21
#define UNLOCK_BUTTON_PIN 22

// Define pulse widths
#define LOCK_PULSE_WIDTH 2000
#define UNLOCK_PULSE_WIDTH 1000

// Debounce delay in milliseconds
#define DEBOUNCE_DELAY 50

// Global variable to track program state for signal handling
volatile sig_atomic_t program_running = 1;

// Function prototypes
int lock();
int unlock();
void signal_handler(int signal);

// Function to lock the door
int lock() {
    int result = gpioServo(SERVO_PIN, LOCK_PULSE_WIDTH);
    if (result != 0) {
        fprintf(stderr, "Error: Failed to lock door (pigpio error code: %d)\n", result);
        return -1;
    }
    printf("Door locked.\n");
    return 0;
}

// Function to unlock the door
int unlock() {
    int result = gpioServo(SERVO_PIN, UNLOCK_PULSE_WIDTH);
    if (result != 0) {
        fprintf(stderr, "Error: Failed to unlock door (pigpio error code: %d)\n", result);
        return -1;
    }
    printf("Door unlocked.\n");
    return 0;
}

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, shutting down...\n", signal);
    gpioServo(SERVO_PIN, 0); // Stop the servo
    gpioTerminate(); // Terminate pigpio
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(SERVO_PIN, PI_OUTPUT);
    gpioSetMode(LOCK_BUTTON_PIN, PI_INPUT);
    gpioSetMode(UNLOCK_BUTTON_PIN, PI_INPUT);

    // Enable pull-up resistors on button pins
    gpioSetPullUpDown(LOCK_BUTTON_PIN, PI_PUD_UP);
    gpioSetPullUpDown(UNLOCK_BUTTON_PIN, PI_PUD_UP);

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Door lock control program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Check lock button
        if (gpioRead(LOCK_BUTTON_PIN) == 0) {
            // Debounce
            gpioDelay(DEBOUNCE_DELAY * 1000); // Convert milliseconds to microseconds
            if (gpioRead(LOCK_BUTTON_PIN) == 0) {
                if (lock() != 0) {
                    fprintf(stderr, "Error: Failed to lock door.\n");
                }
                // Wait for button release
                while (gpioRead(LOCK_BUTTON_PIN) == 0) {
                    gpioDelay(1000); // Small delay to prevent busy-waiting
                }
            }
        }

        // Check unlock button
        if (gpioRead(UNLOCK_BUTTON_PIN) == 0) {
            // Debounce
            gpioDelay(DEBOUNCE_DELAY * 1000); // Convert milliseconds to microseconds
            if (gpioRead(UNLOCK_BUTTON_PIN) == 0) {
                if (unlock() != 0) {
                    fprintf(stderr, "Error: Failed to unlock door.\n");
                }
                // Wait for button release
                while (gpioRead(UNLOCK_BUTTON_PIN) == 0) {
                    gpioDelay(1000); // Small delay to prevent busy-waiting
                }
            }
        }

        // Small delay to reduce CPU usage
        gpioDelay(1000); // 1 millisecond
    }

    // This point should not be reached unless there's an error or signal
    fprintf(stderr, "Error: Program exited unexpectedly.\n");
    gpioTerminate(); // Terminate pigpio
    return 1;
}

