#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define PIR_PIN 4
#define LED_PIN 17

// Define log file name
#define LOG_FILE "security_log.txt"

// Global variables
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int read_pir_sensor();
void activate_led();
void deactivate_led();
void log_event(const char *event_type, const char *timestamp, int duration);
void cleanup();
void signal_handler(int signal);

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    gpioSetMode(PIR_PIN, PI_INPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0); // Ensure LED is off initially

    return 0; // Indicate success
}

// Function to read the PIR sensor
int read_pir_sensor() {
    return gpioRead(PIR_PIN);
}

// Function to activate the LED
void activate_led() {
    gpioWrite(LED_PIN, 1);
}

// Function to deactivate the LED
void deactivate_led() {
    gpioWrite(LED_PIN, 0);
}

// Function to log events to the file
void log_event(const char *event_type, const char *timestamp, int duration) {
    if (log_file != NULL) {
        fprintf(log_file, "%s,%s,%d\n", event_type, timestamp, duration);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, cleaning up...\n", signal);
    cleanup();
    exit(0);
}

// Function to perform cleanup tasks
void cleanup() {
    deactivate_led(); // Ensure LED is off

    if (log_file != NULL) {
        fclose(log_file);
    }

    gpioTerminate(); // Release pigpio resources
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        cleanup();
        return 1;
    }

    printf("Security system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        if (read_pir_sensor() == 1) {
            // Rising edge detected
            time_t rawtime;
            struct tm *timeinfo;
            char timestamp[20]; // ISO 8601 timestamp

            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

            activate_led();
            log_event("Activation", timestamp, 60);

            gpioDelay(60000); // Wait for 60 seconds

            deactivate_led();
            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);
            log_event("Deactivation", timestamp, 60);
        }
        gpioDelay(100); // Poll every 100ms
    }

    // Cleanup and exit (should not reach here if signal handler works)
    cleanup();
    return 0;
}

