#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>

// Define constants
#define MPR121_ADDR 0x5A
#define RELAY_GPIO 17
#define DEBOUNCE_TIME 200 // milliseconds

// MPR121 Registers
#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_ECR 0x5E
#define MPR121_CONFIG1 0x5B
#define MPR121_CONFIG2 0x5C
#define MPR121_MHD_R 0x2B
#define MPR121_NHD_R 0x2C
#define MPR121_NCL_R 0x2D
#define MPR121_FDL_R 0x2E
#define MPR121_MHD_T 0x2F
#define MPR121_NHD_T 0x30
#define MPR121_NCL_T 0x31
#define MPR121_FDL_T 0x32
#define MPR121_E0FDL 0x41
#define MPR121_E0FDR 0x42
#define MPR121_E0MHD 0x43
#define MPR121_E0NHD 0x44
#define MPR121_E0NCL 0x45
#define MPR121_E0FDL_MSB 0x46
#define MPR121_E0FDR_MSB 0x47
#define MPR121_E0MHD_MSB 0x48
#define MPR121_E0NHD_MSB 0x49
#define MPR121_E0NCL_MSB 0x4A
#define MPR121_AUTOCONFIG 0x7B

// Global variables
int i2c_handle;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int mpr121_init();
int read_touch_status(uint16_t *touch_status);
int control_relay(int state);
void signal_handler(int signal);

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the MPR121
int mpr121_init() {
    // Soft reset
    if (i2cWriteByteData(i2c_handle, MPR121_CONFIG1, 0x80) < 0) {
        fprintf(stderr, "Error: Soft reset failed\n");
        return -1;
    }
    gpioDelay(100); // Wait for reset to complete

    // Configure baseline filtering
    if (i2cWriteByteData(i2c_handle, MPR121_MHD_R, 0x01) < 0) return -1;
    if (i2cWriteByteData(i2c_handle, MPR121_NHD_R, 0x01) < 0) return -1;
    if (i2cWriteByteData(i2c_handle, MPR121_NCL_R, 0x00) < 0) return -1;
    if (i2cWriteByteData(i2c_handle, MPR121_FDL_R, 0x00) < 0) return -1;

    if (i2cWriteByteData(i2c_handle, MPR121_MHD_T, 0x01) < 0) return -1;
    if (i2cWriteByteData(i2c_handle, MPR121_NHD_T, 0x01) < 0) return -1;
    if (i2cWriteByteData(i2c_handle, MPR121_NCL_T, 0x00) < 0) return -1;
    if (i2cWriteByteData(i2c_handle, MPR121_FDL_T, 0x00) < 0) return -1;

    // Configure Electrode Filter
    if (i2cWriteByteData(i2c_handle, MPR121_E0FDL, 0x24) < 0) return -1;
    if (i2cWriteByteData(i2c_handle, MPR121_E0FDR, 0x10) < 0) return -1;
    if (i2cWriteByteData(i2c_handle, MPR121_E0MHD, 0x01) < 0) return -1;
    if (i2cWriteByteData(i2c_handle, MPR121_E0NHD, 0x01) < 0) return -1;
    if (i2cWriteByteData(i2c_handle, MPR121_E0NCL, 0x00) < 0) return -1;
    if (i2cWriteByteData(i2c_handle, MPR121_E0FDL_MSB, 0x00) < 0) return -1;
    if (i2cWriteByteData(i2c_handle, MPR121_E0FDR_MSB, 0x00) < 0) return -1;
    if (i2cWriteByteData(i2c_handle, MPR121_E0MHD_MSB, 0x00) < 0) return -1;
    if (i2cWriteByteData(i2c_handle, MPR121_E0NHD_MSB, 0x00) < 0) return -1;
    if (i2cWriteByteData(i2c_handle, MPR121_E0NCL_MSB, 0x00) < 0) return -1;

    // Configure Auto-Config
    if (i2cWriteByteData(i2c_handle, MPR121_AUTOCONFIG, 0x01) < 0) return -1;

    // Enable all 12 electrodes
    if (i2cWriteByteData(i2c_handle, MPR121_ECR, 0x3F) < 0) {
        fprintf(stderr, "Error: Failed to enable electrodes\n");
        return -1;
    }

    return 0;
}

// Function to read the touch status from the MPR121
int read_touch_status(uint16_t *touch_status) {
    char buf[2];
    if (i2cReadI2CBlockData(i2c_handle, MPR121_TOUCHSTATUS_L, buf, 2) != 2) {
        fprintf(stderr, "Error: Failed to read touch status\n");
        return -1;
    }
    *touch_status = (buf[1] << 8) | buf[0];
    return 0;
}

// Function to control the relay
int control_relay(int state) {
    if (gpioWrite(RELAY_GPIO, state) != 0) {
