// Function to initialize the MPR121
int mpr121_init() {
    // Soft reset
    if (i2cWriteByteData(i2c_handle, MPR121_CONFIG1, 0x80) < 0) {
        fprintf(stderr, "Error: Soft reset failed\n");
        return -1;
    }
    gpioDelay(100); // Wait for reset to complete

    // Configure baseline filtering
    if (i2cWriteByteData(i2c_handle, MPR121_MHD_R, 0x01) < 0) return -1;
