#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <signal.h>
#include <syslog.h>
#include <time.h>
#include <pigpio.h>
#include <stdarg.h>

#define SERVO_PIN 17
#define PIR_PIN 4
#define PORT 5000
#define LOG_FILE "security.log"

// Global variables for graceful shutdown
int server_fd = 0;
int client_fd = 0;
FILE *log_file = NULL;

// Function prototypes
void log_message(const char *format, ...);
void signal_handler(int signum);
int setup_gpio();
int setup_socket();
void handle_client(int client_socket);
void set_servo_angle(int angle);
int read_pir_sensor();
void cleanup();

// Function to log messages to both syslog and a file
void log_message(const char *format, ...) {
    va_list args;
    va_start(args, format);

    // Log to syslog
    vsyslog(LOG_USER, format, args);

    // Log to file
    if (log_file != NULL) {
        time_t now = time(NULL);
        struct tm *t = localtime(&now);
        char timestamp[30];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);
        fprintf(log_file, "%s ", timestamp);
        vfprintf(log_file, format, args);
        fflush(log_file);
    }

    va_end(args);
}

// Signal handler for graceful shutdown
void signal_handler(int signum) {
    log_message("Received signal %d, shutting down...\n", signum);
    cleanup();
    exit(0);
}

// Setup GPIO using pigpio
int setup_gpio() {
    if (gpioInitialise() < 0) {
        log_message("pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(SERVO_PIN, PI_OUTPUT);
    gpioSetMode(PIR_PIN, PI_INPUT);
    gpioSetPullUpDown(PIR_PIN, PI_PUD_DOWN); // Pull-down resistor

    log_message("GPIO setup complete\n");
    return 0;
}

// Setup TCP socket
int setup_socket() {
    struct sockaddr_in address;
    int opt = 1;

    // Create socket
    if ((server_fd = socket(AF_INET, SOCK_STREAM, 0)) == 0) {
        log_message("Socket creation failed\n");
        return -1;
    }

    // Set socket options
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR | SO_REUSEPORT, &opt, sizeof(opt))) {
        log_message("Setsockopt failed\n");
        return -1;
    }

    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    // Bind socket to address
    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        log_message("Bind failed\n");
        return -1;
    }

    // Listen for connections
    if (listen(server_fd, 3) < 0) {
        log_message("Listen failed\n");
        return -1;
    }

    log_message("Socket setup complete\n");
    return 0;
}

// Handle client connection
void handle_client(int client_socket) {
    char buffer[1024] = {0};
    int valread;

    while ((valread = read(client_socket, buffer, sizeof(buffer) - 1)) > 0) {
        buffer[valread] = '\0';
        log_message("Received command: %s\n", buffer);

        if (strncmp(buffer, "PIR", 3) == 0) {
            int pir_value = read_pir_sensor();
            char response[20];
            snprintf(response, sizeof(response), "PIR:%d\n", pir_value);
            send(client_socket, response, strlen(response), 0);
            log_message("Sent PIR value: %d\n", pir_value);
        } else if (strncmp(buffer, "set_servo_angle", 15) == 0) {
            int angle;
            if (sscanf(buffer, "set_servo_angle %d", &angle) == 1) {
                if (angle >= 0 && angle <= 180) {
                    set_servo_angle(angle);
                    log_message("Set servo angle to %d\n", angle);
                } else {
                    log_message("Invalid angle: %d\n", angle);
                    send(client_socket, "Invalid angle\n", strlen("Invalid angle\n"), 0);
                }
            } else {
                log_message("Invalid command format\n");
                send(client_socket, "Invalid command format\n", strlen("Invalid command format\n"), 0);
            }
        } else {
            log_message("Invalid command\n");
            send(client_socket, "Invalid command\n", strlen("Invalid command\n"), 0);
        }
    }

    if (valread == 0) {
        log_message("Client disconnected\n");
    } else if (valread < 0) {
        log_message("Error reading from socket\n");
    }

    close(client_socket);
}

// Set servo angle using software PWM
void set_servo_angle(int angle) {
    // Calculate pulse width (1ms - 2ms for 0-180 degrees)
    int pulse_width = 1000 + (angle * 1000 / 180);

    // Calculate on and off times for 50Hz (20ms period)
    int on_time = pulse_width;
    int off_time = 20000 - pulse_width;

    // Set GPIO level to 1 for on_time microseconds
    gpioWrite(SERVO_PIN, 1);
    gpioDelay(on_time);

    // Set GPIO level to 0 for off_time microseconds
    gpioWrite(SERVO_PIN, 0);
    gpioDelay(off_time);
}

// Read PIR sensor value
int read_pir_sensor() {
    return gpioRead(PIR_PIN);
}

// Cleanup resources before exiting
void cleanup() {
    log_message("Cleaning up resources...\n");

    // Close socket
    if (server_fd > 0) {
        close(server_fd);
    }
    if (client_fd > 0) {
        close(client_fd);
    }

    // Terminate pigpio
    gpioTerminate();

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    log_message("Cleanup complete\n");
}

int main() {
    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        return 1;
    }

    // Initialize syslog
    openlog("security_system", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Setup GPIO
    if (setup_gpio() != 0) {
        cleanup();
        return 1;
    }

    // Setup socket
    if (setup_socket() != 0) {
        cleanup();
        return 1;
    }

    log_message("Server listening on port %d\n", PORT);

    // Main loop
    while (1) {
        struct sockaddr_in client_address;
        int client_socket;
        int addrlen = sizeof(client_address);

        // Accept connection
        if ((client_socket = accept(server_fd, (struct sockaddr *)&client_address, (socklen_t*)&addrlen)) < 0) {
            log_message("Accept failed\n");
            continue; // Continue listening for connections
        }

        client_fd = client_socket; // Update global client_fd

        log_message("Client connected\n");

        // Handle client
        handle_client(client_socket);
    }

    return 0;
}

