#include <unistd.h>

// Constants
#define BH1750_ADDR 0x23
#define GROW_LIGHT_GPIO 23
#define LUX_THRESHOLD 150
#define I2C_BUS 1
#define I2C_FLAGS 0
#define I2C_RETRY_COUNT 3
#define I2C_RETRY_DELAY_MS 10
#define LOG_FILE "grow_log.txt"

// Global variables
int i2c_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_bh1750(int i2c_handle);
void control_relay(int gpio_pin, int state);
void log_data(FILE *log_file, int lux_value);
void signal_handler(int signal);
int initialize();
void cleanup();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Signal received, cleaning up...\n");
}

// Initialize function
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, I2C_FLAGS);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO mode for relay control
    gpioSetMode(GROW_LIGHT_GPIO, PI_OUTPUT);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Cleanup function
void cleanup() {
    // Close I2C device
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Deactivate relay
    control_relay(GROW_LIGHT_GPIO, 0);

    // Terminate pigpio
    gpioTerminate();
}

// Read BH1750 sensor
int read_bh1750(int i2c_handle) {
    unsigned char data[2];
    int lux = -1; // Initialize to an invalid value
    int retries = 0;

    while (retries < I2C_RETRY_COUNT) {
        // Send start measurement command (High Resolution Mode)
        if (i2cWriteByteData(i2c_handle, 0x00, 0x10) < 0) {
            fprintf(stderr, "I2C write failed (start measurement), retry %d\n", retries + 1);
            gpioDelay(I2C_RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries++;
            continue;
        }

        gpioDelay(120 * 1000); // Wait 120ms

        // Read 2 bytes of data
        if (i2cReadI2CBlockData(i2c_handle, 0x00, (char *)data, 2) == 2) {
            // Combine the bytes to form the lux value
            lux = (data[0] << 8) | data[1];
            break; // Exit retry loop on success
        } else {
            fprintf(stderr, "I2C read failed (data read), retry %d\n", retries + 1);
            retries++;
            gpioDelay(I2C_RETRY_DELAY_MS * 1000); // Delay in microseconds
        }
    }

    if (lux == -1) {
        fprintf(stderr, "Failed to read BH1750 after %d retries\n", I2C_RETRY_COUNT);
    }

    return lux;
}

// Control relay
void control_relay(int gpio_pin, int state) {
    gpioWrite(gpio_pin, state);
}

// Log data
void log_data(FILE *log_file, int lux_value) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %d\n", timestamp, lux_value);
    fflush(log_file); // Ensure data is written to file immediately
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (initialize() != 0) {
        return 1;
    }

    printf("Grow light control system started\n");

    while (!terminate) {
        int lux = read_bh1750(i2c_handle);

        if (lux != -1) {
            log_data(log_file, lux);

            if (lux < LUX_THRESHOLD) {
                control_relay(GROW_LIGHT_GPIO, 1); // Activate relay
                printf("Lux: %d, Relay: ON\n", lux);
            } else {
                control_relay(GROW_LIGHT_GPIO, 0); // Deactivate relay
                printf("Lux: %d, Relay: OFF\n", lux);
            }
        } else {
            fprintf(stderr, "Failed to read lux value\n");
        }

        gpioDelay(2000 * 1000); // Wait 2 seconds
    }

    cleanup();
    printf("Grow light control system stopped\n");

    return 0;
}

