#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define HX711_DOUT 23
#define HX711_SCK 24
#define SOLENOID_PIN 25

// Default values
#define DEFAULT_THRESHOLD 1000.0
#define DEFAULT_SCALE_FACTOR 1.0
#define DEFAULT_DURATION 200

// Global variables
static volatile int running = 1;
static double threshold = DEFAULT_THRESHOLD;
static double scale_factor = DEFAULT_SCALE_FACTOR;
static int duration_ms = DEFAULT_DURATION;

// Function prototypes
int read_hx711();
double tare_hx711();
double get_weight();
void activate_solenoid();
void deactivate_solenoid();
void signal_handler(int signal);
void log_message(int priority, const char *message);

// Signal handler function
void signal_handler(int signal) {
    log_message(LOG_INFO, "Signal received, shutting down...");
    running = 0;
}

// Function to log messages to syslog
void log_message(int priority, const char *message) {
    syslog(priority, message);
}

// Function to read data from HX711
int read_hx711() {
    int data = 0;
    int timeout = 1000; // Timeout in milliseconds
    int start_time = gpioTick();

    // Wait for DOUT to go low
    while (gpioRead(HX711_DOUT) == 1) {
        if (gpioTick() - start_time > timeout * 1000) {
            log_message(LOG_ERR, "HX711 DOUT timeout");
            return -1; // Indicate error
        }
        gpioDelay(1); // Small delay to avoid busy-waiting
    }

    // Clock out 24 bits
    for (int i = 0; i < 24; i++) {
        gpioWrite(HX711_SCK, 1);
        gpioDelay(1); // Small delay
        data = data << 1;
        if (gpioRead(HX711_DOUT)) {
            data++;
        }
        gpioWrite(HX711_SCK, 0);
        gpioDelay(1); // Small delay
    }

    // Clock out one more bit to select Channel A gain 128
    gpioWrite(HX711_SCK, 1);
    gpioDelay(1); // Small delay
    gpioWrite(HX711_SCK, 0);
    gpioDelay(1); // Small delay

    // Convert to signed 24-bit integer
    if (data & 0x800000) {
        data |= 0xFF000000;
    }

    return data;
}

// Function to tare HX711
double tare_hx711() {
    double sum = 0.0;
    for (int i = 0; i < 10; i++) {
        int raw_value = read_hx711();
        if (raw_value == -1) {
            log_message(LOG_ERR, "Error reading HX711 during tare");
            return -1.0; // Indicate error
        }
        sum += raw_value;
        gpioDelay(10); // Small delay between readings
    }
    return sum / 10.0;
}

// Function to get weight
double get_weight() {
    double sum = 0.0;
    for (int i = 0; i < 5; i++) {
        int raw_value = read_hx711();
        if (raw_value == -1) {
            log_message(LOG_ERR, "Error reading HX711 during weight measurement");
            return -1.0; // Indicate error
        }
        sum += raw_value;
        gpioDelay(10); // Small delay between readings
    }
    double average = sum / 5.0;
    return average * scale_factor;
}

// Function to activate solenoid
void activate_solenoid() {
    gpioWrite(SOLENOID_PIN, 1); // Set HIGH
    gpioDelay(duration_ms);      // Wait for specified duration
    deactivate_solenoid();       // Deactivate immediately after activation
}

// Function to deactivate solenoid
void deactivate_solenoid() {
    gpioWrite(SOLENOID_PIN, 0); // Set LOW
}

int main(int argc, char *argv[]) {
    // Initialize syslog
    openlog("weight_monitor", LOG_PID | LOG_CONS, LOG_USER);

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Parse command-line arguments
    int opt;
    while ((opt = getopt(argc, argv, "t:s:d:")) != -1) {
        switch (opt) {
            case 't':
                threshold = atof(optarg);
                break;
            case 's':
                scale_factor = atof(optarg);
                break;
            case 'd':
                duration_ms = atoi(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold] [-s scale_factor] [-d duration_ms]\n", argv[0]);
                closelog();
                return 1;
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        log_message(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(HX711_DOUT, PI_INPUT);
    gpioSetMode(HX711_SCK, PI_OUTPUT);
    gpioSetMode(SOLENOID_PIN, PI_OUTPUT);

    // Tare the HX711
    double tare_value = tare_hx711();
    if (tare_value < 0) {
        log_message(LOG_ERR, "Tare failed, exiting");
        gpioTerminate();
        closelog();
        return 1;
    }
    log_message(LOG_INFO, "Tare complete");

    // Main loop
    while (running) {
        double weight = get_weight();
        if (weight < 0) {
            log_message(LOG_ERR, "Weight measurement failed");
            gpioDelay(500); // Wait before retrying
            continue;
        }

        char message[100];
        snprintf(message, sizeof(message), "Weight: %.2f grams", weight);
        log_message(LOG_INFO, message);

        if (weight > threshold) {
            log_message(LOG_INFO, "Weight exceeds threshold, activating solenoid");
            activate_solenoid();
        }

        gpioDelay(500); // Wait 500ms
    }

    // Cleanup
    deactivate_solenoid(); // Ensure solenoid is off
    gpioTerminate();       // Terminate pigpio
    closelog();            // Close syslog

    return 0;
}

