#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <syslog.h>
#include <time.h>
#include <mosquitto.h>
#include <pigpio.h>

#define MQTT_BROKER "localhost"
#define MQTT_PORT 1883
#define MQTT_CLIENT_ID "relay_controller_1"
#define MQTT_TOPIC "home/lights/control"
#define GPIO_PIN 17

static struct mosquitto *mosq = NULL;
static volatile int running = 1;

// Function to set the relay state
int set_relay_state(int state) {
    if (gpioWrite(GPIO_PIN, state) != 0) {
        syslog(LOG_ERR, "Failed to write to GPIO %d", GPIO_PIN);
        return -1;
    }
    return 0;
}

// Callback function for MQTT messages
void message_callback(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message) {
    if (message->payloadlen > 0) {
        char *payload = (char *)message->payload;
        if (strcmp(payload, "ON") == 0) {
            syslog(LOG_INFO, "Received ON command");
            if (set_relay_state(1) != 0) {
                syslog(LOG_ERR, "Failed to set relay ON");
            }
        } else if (strcmp(payload, "OFF") == 0) {
            syslog(LOG_INFO, "Received OFF command");
            if (set_relay_state(0) != 0) {
                syslog(LOG_ERR, "Failed to set relay OFF");
            }
        } else {
            syslog(LOG_ERR, "Invalid payload: %s", payload);
        }
    } else {
        syslog(LOG_ERR, "Empty payload received");
    }
}

// Callback function for MQTT connection
void connect_callback(struct mosquitto *mosq, void *userdata, int result) {
    if (result == MOSQ_ERR_SUCCESS) {
        syslog(LOG_INFO, "Connected to MQTT broker");
        int subscribe_result = mosquitto_subscribe(mosq, NULL, MQTT_TOPIC, 0);
        if (subscribe_result != MOSQ_ERR_SUCCESS) {
            syslog(LOG_ERR, "Failed to subscribe to topic: %s", mosquitto_strerror(subscribe_result));
        }
    } else {
        syslog(LOG_ERR, "Connection failed: %s", mosquitto_strerror(result));
    }
}

// Callback function for MQTT disconnection
void disconnect_callback(struct mosquitto *mosq, void *userdata, int rc) {
    syslog(LOG_INFO, "Disconnected from MQTT broker (rc=%d)", rc);
}

// Callback function for MQTT errors
void error_callback(struct mosquitto *mosq, void *userdata, int rc) {
    syslog(LOG_ERR, "MQTT error: %s", mosquitto_strerror(rc));
}

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signum) {
    syslog(LOG_INFO, "Signal received, exiting...");
    running = 0;
}

int main() {
    // Initialize syslog
    openlog("mqtt_relay", LOG_PID | LOG_CONS, LOG_USER);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    // Set GPIO pin as output
    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    // Initialize relay to OFF state
    set_relay_state(0);

    // Initialize libmosquitto
    mosquitto_lib_init();

    // Create a new MQTT client instance
    mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!mosq) {
