// Define GPIO pins for the servos
#define SERVO1_PIN 7
#define SERVO2_PIN 8
#define SERVO3_PIN 9
#define SERVO4_PIN 10
#define SERVO5_PIN 11

// Define pulse widths for each servo (in microseconds)
#define SERVO1_PULSE_WIDTH 1000
#define SERVO2_PULSE_WIDTH 1500
#define SERVO3_PULSE_WIDTH 2000
#define SERVO4_PULSE_WIDTH 500
#define SERVO5_PULSE_WIDTH 2500

// Define the PWM frequency (50 Hz)
#define PWM_FREQUENCY 50

// Define the PWM range (20 ms period)
#define PWM_RANGE 20000

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nCtrl+C detected. Stopping PWM and exiting.\n");
}

// Function to set the pulse width for a servo
int set_servo_pulse_width(int gpio_pin, int pulse_width) {
    if (pulse_width < 500 || pulse_width > 2500) {
        fprintf(stderr, "Error: Pulse width out of range (500-2500 us).\n");
        return -1;
    }

    // Calculate the pulse width in microseconds
    int pulse_width_us = pulse_width;

    // Set the PWM pulse width
    gpioPWM(gpio_pin, pulse_width_us);

    return 0;
}

// Function to hold the servo at the specified pulse width for 3 seconds
void hold_servo(int gpio_pin, int pulse_width) {
    if (set_servo_pulse_width(gpio_pin, pulse_width) != 0) {
        fprintf(stderr, "Error setting pulse width for servo on GPIO %d.\n", gpio_pin);
        return;
    }

    printf("Servo on GPIO %d held at %d us for 3 seconds.\n", gpio_pin, pulse_width);
    sleep(3);
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set the PWM frequency for all servos
    gpioSetPWMfrequency(SERVO1_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(SERVO2_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(SERVO3_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(SERVO4_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(SERVO5_PIN, PWM_FREQUENCY);

    // Set the PWM range for all servos
    gpioSetPWMrange(SERVO1_PIN, PWM_RANGE);
    gpioSetPWMrange(SERVO2_PIN, PWM_RANGE);
    gpioSetPWMrange(SERVO3_PIN, PWM_RANGE);
    gpioSetPWMrange(SERVO4_PIN, PWM_RANGE);
    gpioSetPWMrange(SERVO5_PIN, PWM_RANGE);

    // Register the signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Move each servo to its predefined position and hold for 3 seconds
    hold_servo(SERVO1_PIN, SERVO1_PULSE_WIDTH);
    hold_servo(SERVO2_PIN, SERVO2_PULSE_WIDTH);
    hold_servo(SERVO3_PIN, SERVO3_PULSE_WIDTH);
    hold_servo(SERVO4_PIN, SERVO4_PULSE_WIDTH);
    hold_servo(SERVO5_PIN, SERVO5_PULSE_WIDTH);

    // Stop the PWM signal on all servos
    gpioPWM(SERVO1_PIN, 0);
    gpioPWM(SERVO2_PIN, 0);
    gpioPWM(SERVO3_PIN, 0);
    gpioPWM(SERVO4_PIN, 0);
    gpioPWM(SERVO5_PIN, 0);

    // Terminate the pigpio library
    gpioTerminate();

    printf("Program finished.\n");
    return 0;
}

