        encoder_a_count++;
        pthread_mutex_unlock(&encoder_mutex);
    } else if (!a && b) {
        pthread_mutex_lock(&encoder_mutex);
        encoder_a_count--;
        pthread_mutex_unlock(&encoder_mutex);
    }

    return NULL;
}

// Encoder B ISR
void *encoder_b_isr(void *arg) {
    int a = gpioRead(ENCODER_B_A);
    int b = gpioRead(ENCODER_B_B);

    if (a && !b) {
        pthread_mutex_lock(&encoder_mutex);
        encoder_b_count++;
        pthread_mutex_unlock(&encoder_mutex);
    } else if (!a && b) {
        pthread_mutex_lock(&encoder_mutex);
        encoder_b_count--;
        pthread_mutex_unlock(&encoder_mutex);
    }

    return NULL;
}

// Set Motor PWM
void set_motor_pwm(int motor, int pwm_value) {
    if (pwm_value < 0) pwm_value = 0;
    if (pwm_value > PWM_RANGE) pwm_value = PWM_RANGE;
    gpioPWM(motor, pwm_value);
}

// Set Motor Direction
void set_motor_direction(int motor, int direction) {
    gpioWrite(motor, direction);
}

// Calculate RPM
double calculate_rpm(int encoder_count) {
    return (double)encoder_count * 60.0 / ENCODER_TICKS_PER_REV / (0.1); // Assuming 0.1 seconds interval
}

// PI Controller
double pi_controller(double error, double *integral) {
    double output = KP * error + KI * (*integral);

    // Anti-windup
    if (output > PWM_RANGE) {
        output = PWM_RANGE;
        *integral = (PWM_RANGE - KP * error) / KI;
    } else if (output < 0) {
        output = 0;
        *integral = -KP * error / KI;
    } else {
        *integral += error;
    }

    return output;
}

// Control Loop
void *control_loop(void *arg) {
    while (1) {
        int encoder_a_count_local, encoder_b_count_local;
        double rpm_a, rpm_b, error_a, error_b, pwm_a, pwm_b;

        // Read Encoder Counts
        pthread_mutex_lock(&encoder_mutex);
        encoder_a_count_local = encoder_a_count;
        encoder_b_count_local = encoder_b_count;
        pthread_mutex_unlock(&encoder_mutex);

        // Calculate RPM
        rpm_a = calculate_rpm(encoder_a_count_local);
        rpm_b = calculate_rpm(encoder_b_count_local);

        // Calculate Errors
        error_a = TARGET_RPM - rpm_a;
        error_b = TARGET_RPM - rpm_b;

        // PI Control
        pwm_a = pi_controller(error_a, &integral_a);
        pwm_b = pi_controller(error_b, &integral_b);

        // Set Motor PWM
        set_motor_pwm(MOTOR_A_PWM, (int)pwm_a);
        set_motor_pwm(MOTOR_B_PWM, (int)pwm_b);

        // Stall Detection
        unsigned long current_time = gpioTick();
        if (encoder_a_count_local == 0 && (current_time - last_encoder_a_tick) > (STALL_TIME_MS * 1000)) {
            fprintf(stderr, "WARNING: Motor A stalled!\n");
        }
        if (encoder_b_count_local == 0 && (current_time - last_encoder_b_tick) > (STALL_TIME_MS * 1000)) {
            fprintf(stderr, "WARNING: Motor B stalled!\n");
        }

        last_encoder_a_tick = current_time;
        last_encoder_b_tick = current_time;

        // Print Status
        printf("Motor A: RPM = %.2f, PWM = %d, Encoder Count = %d\n", rpm_a, (int)pwm_a, encoder_a_count_local);
        printf("Motor B: RPM = %.2f, PWM = %d, Encoder Count = %d\n", rpm_b, (int)pwm_b, encoder_b_count_local);

        gpioDelay(100000); // 100 ms
    }
    return NULL;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO Modes
    gpioSetMode(MOTOR_A_PWM, PI_OUTPUT);
    gpioSetMode(MOTOR_A_DIR, PI_OUTPUT);
    gpioSetMode(MOTOR_B_PWM, PI_OUTPUT);
    gpioSetMode(MOTOR_B_DIR, PI_OUTPUT);
    gpioSetMode(ENCODER_A_A, PI_INPUT);
    gpioSetMode(ENCODER_A_B, PI_INPUT);
    gpioSetMode(ENCODER_B_A, PI_INPUT);
    gpioSetMode(ENCODER_B_B, PI_INPUT);

    // Set PWM Frequency
    gpioSetPWMfrequency(MOTOR_A_PWM, PWM_FREQUENCY);
    gpioSetPWMfrequency(MOTOR_B_PWM, PWM_FREQUENCY);
    gpioSetPWMrange(MOTOR_A_PWM, PWM_RANGE);
    gpioSetPWMrange(MOTOR_B_PWM, PWM_RANGE);

    // Set Motor Directions (Forward)
    set_motor_direction(MOTOR_A_DIR, 1);
    set_motor_direction(MOTOR_B_DIR, 1);

    // Register ISRs
    if (gpioSetISRFuncEx(ENCODER_A_A, RISING_EDGE, 0, encoder_a_isr, NULL) != 0) {
        fprintf(stderr, "Failed to register ISR for Encoder A A\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetISRFuncEx(ENCODER_A_B, RISING_EDGE, 0, encoder_a_isr, NULL) != 0) {
        fprintf(stderr, "Failed to register ISR for Encoder A B\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetISRFuncEx(ENCODER_B_A, RISING_EDGE, 0, encoder_b_isr, NULL) != 0) {
        fprintf(stderr, "Failed to register ISR for Encoder B A\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetISRFuncEx(ENCODER_B_B, RISING_EDGE, 0, encoder_b_isr, NULL) != 0) {
        fprintf(stderr, "Failed to register ISR for Encoder B B\n");
        gpioTerminate();
        return 1;
    }

    // Set Signal Handler
    signal(SIGINT, signal_handler);

    // Create Control Loop Thread
    pthread_t control_thread;
    if (pthread_create(&control_thread, NULL, control_loop, NULL) != 0) {
        fprintf(stderr, "Failed to create control loop thread\n");
        gpioTerminate();
        return 1;
    }

    // Wait for Control Loop Thread to finish (never happens in this example)
    pthread_join(control_thread, NULL);

    // Cleanup (should not reach here in normal operation)
    set_motor_pwm(MOTOR_A_PWM, 0);
    set_motor_pwm(MOTOR_B_PWM, 0);
    gpioTerminate();

    return 0;
}

