#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define BH1750_ADDR 0x23
#define GPIO_RELAY 17
#define LUX_THRESHOLD_DUSK 50
#define LUX_THRESHOLD_DAWN 200
#define HYSTERESIS 10
#define POLLING_INTERVAL 5 // seconds
#define I2C_READ_DELAY 180 // milliseconds

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize();
int read_bh1750(int handle);
int control_relay(int gpio, int state);
int log_data(float lux, int relay_state);
void signal_handler(int signal);
void cleanup();

// Structure to hold sensor data
typedef struct {
    float lux;
    int relay_state;
} SensorData;

int main() {
    SensorData current_data = {0.0, 0}; // Initialize sensor data

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the system
    if (initialize() != 0) {
        fprintf(stderr, "Initialization failed. Exiting.\n");
        return 1;
    }

    // Main loop
    while (program_running) {
        // Read light sensor data
        int lux = read_bh1750(i2c_handle);
        if (lux >= 0) {
            current_data.lux = (float)lux;

            // Control the relay based on light level
            if (lux < LUX_THRESHOLD_DUSK && current_data.relay_state == 0) {
                if (control_relay(GPIO_RELAY, 1) == 0) {
                    current_data.relay_state = 1;
                    log_data(current_data.lux, current_data.relay_state);
                }
            } else if (lux > LUX_THRESHOLD_DAWN + HYSTERESIS && current_data.relay_state == 1) {
                if (control_relay(GPIO_RELAY, 0) == 0) {
                    current_data.relay_state = 0;
                    log_data(current_data.lux, current_data.relay_state);
                }
            } else {
                // Log data even if relay state doesn't change
                log_data(current_data.lux, current_data.relay_state);
            }
        } else {
            fprintf(stderr, "Error reading light sensor. Check log file.\n");
        }

        // Wait before next reading
        gpioDelay(POLLING_INTERVAL * 1000); // Convert seconds to milliseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize the pigpio library, I2C, GPIO, and log file
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO mode for relay control
    gpioSetMode(GPIO_RELAY, PI_OUTPUT);
    gpioWrite(GPIO_RELAY, 0); // Ensure relay is initially off

    // Open log file
    log_file = fopen("chicken_coop_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Read light sensor data from BH1750
int read_bh1750(int handle) {
    char config_cmd = 0x10; // Continuous high-resolution mode
    char buffer[2];
    int lux = -1; // Initialize to an error value

    // Send configuration command
    if (i2cWriteByteData(handle, 0x00, config_cmd) != 0) {
        fprintf(stderr, "Failed to write to I2C device\n");
        return -1;
    }

    // Wait for measurement (180ms)
    gpioDelay(I2C_READ_DELAY);

    // Read data
    if (i2cReadDevice(handle, buffer, 2) == 2) {
        lux = (buffer[0] << 8) | buffer[1];
    } else {
        fprintf(stderr, "Failed to read from I2C device\n");
        return -1;
    }

    return lux;
}

// Control the relay (ON/OFF)
int control_relay(int gpio, int state) {
    if (gpioWrite(gpio, state) != 0) {
        fprintf(stderr, "Failed to write to GPIO %d\n", gpio);
        return 1;
    }
    return 0;
}

// Log data to file
int log_data(float lux, int relay_state) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s: Lux = %.2f, Relay = %s\n", timestamp, lux, relay_state ? "ON" : "OFF");
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    program_running = 0;
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up resources.\n");

    // Turn off the relay
    control_relay(GPIO_RELAY, 0);

    // Close I2C device
    i2cClose(i2c_handle);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    printf("Cleanup complete. Exiting.\n");
}

