    if (signal == SIGINT) {
        printf("\nCaught SIGINT, exiting gracefully...\n");
        gpioWrite(RELAY_PIN, 0); // Turn off the relay
        gpioTerminate(); // Release pigpio resources
        exit(0);
    }
}

// Function to read the touch sensor state with debouncing
int read_touch_sensor() {
    int touch_detected = gpioRead(TOUCH_SENSOR_PIN);
    if (touch_detected == 1) {
        gpioDelay(DEBOUNCE_DELAY * 1000); // Debounce delay
        if (gpioRead(TOUCH_SENSOR_PIN) == 1) {
            // Wait for release
            while (gpioRead(TOUCH_SENSOR_PIN) == 1) {
                gpioDelay(1000); // Small delay to avoid busy-waiting
            }
            return 1; // Valid touch detected
        }
    }
    return 0; // No valid touch detected
}

// Function to toggle the relay state
void toggle_relay() {
    relay_state = !relay_state; // Toggle the state
    gpioWrite(RELAY_PIN, relay_state); // Set the GPIO pin
    log_relay_state(relay_state); // Log the state
}

