#define LPM_THRESHOLD_CLOSE 4.5
#define LPM_HYSTERESIS 0.5
#define DEBOUNCE_TIMEOUT_US 100000 // 100ms

// Global variables
volatile int pulse_count = 0;
pthread_mutex_t pulse_mutex = PTHREAD_MUTEX_INITIALIZER;
FILE *log_file = NULL;
int running = 1;

