#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>
#include <jansson.h>

// Configuration
#define HX711_DATA_PIN 23
#define HX711_SCK_PIN 24
#define SERVO_PIN 18
#define TCP_PORT 12345
#define CONFIG_FILE "config.ini"
#define LOG_FILE "dispensing_log.json"

// Global variables
static volatile int running = 1;
static int socket_desc;
static FILE *log_file;

// Calibration parameters
static double calibration_factor = 1.0; // Default value
static double known_weight = 100.0; // Default value

// Function prototypes
int read_hx711();
double calculate_weight(int raw_value);
int dispense(double target_weight);
double get_actual_weight();
void log_event(const char *target_weight, const char *actual_weight, const char *error_message);
void signal_handler(int signal);
int setup();
void cleanup();

// HX711 read function
int read_hx711() {
    int data = 0;
    int timeout = 1000; // Timeout after 1000 attempts

    gpioSetMode(HX711_DATA_PIN, PI_INPUT);
    gpioSetMode(HX711_SCK_PIN, PI_OUTPUT);

    // Wait for DATA to go low
    int attempts = 0;
    while (gpioRead(HX711_DATA_PIN) == 1 && attempts < timeout) {
        gpioDelay(1); // Wait 1 us
        attempts++;
    }

    if (attempts >= timeout) {
        fprintf(stderr, "Error: HX711 timeout waiting for DATA low\n");
        return -1; // Indicate timeout error
    }

    // Read 24 bits of data
    for (int i = 0; i < 24; i++) {
        gpioWrite(HX711_SCK_PIN, 1);
        gpioDelay(1); // Clock high for 1 us
        data = data << 1;
        if (gpioRead(HX711_DATA_PIN)) {
            data++;
        }
        gpioWrite(HX711_SCK_PIN, 0);
        gpioDelay(1); // Clock low for 1 us
    }

    // Pulse SCK 25th time to set gain to 128
    gpioWrite(HX711_SCK_PIN, 1);
    gpioDelay(1);
    gpioWrite(HX711_SCK_PIN, 0);
    gpioDelay(1);

    // Convert to signed 2's complement
    if (data & 0x800000) {
        data |= 0xFF000000;
    }

    return data;
}

// Calculate weight from raw value
double calculate_weight(int raw_value) {
    return (double)raw_value / calibration_factor;
}

// Dispense function
int dispense(double target_weight) {
    // Map target weight to pulse width (1000-2000 us)
    int pulse_width = (int)(1000 + (target_weight / 100.0) * 1000); // Example mapping

    if (pulse_width < 1000) pulse_width = 1000;
    if (pulse_width > 2000) pulse_width = 2000;

    // Set servo pulse width
    gpioServo(SERVO_PIN, pulse_width);

    // Wait for 1 second
    sleep(1);

    return 0; // Indicate success
}

// Get actual weight from HX711
double get_actual_weight() {
    int raw_value = read_hx711();
    if (raw_value == -1) {
        return -1.0; // Indicate error
    }
    return calculate_weight(raw_value);
}

// Log event to JSON file
void log_event(const char *target_weight, const char *actual_weight, const char *error_message) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    json_t *root = json_object();
    json_object_set_new(root, "timestamp", json_string(timestamp));
    json_object_set_new(root, "target_weight", json_string(target_weight));
    json_object_set_new(root, "actual_weight", json_string(actual_weight));
    json_object_set_new(root, "error_message", json_string(error_message));

    char *json_str = json_dumps(root, JSON_INDENT(4));
    if (json_str) {
        fprintf(log_file, "%s\n", json_str);
        fflush(log_file);
        free(json_str);
    } else {
        fprintf(stderr, "Error: Failed to serialize JSON\n");
    }

    json_decref(root);
}

// Signal handler
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    running = 0;
    cleanup();
    exit(0);
}

// Setup function
int setup() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set servo pin to output mode
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error: Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    // Read configuration from file
    FILE *config_file = fopen(CONFIG_FILE, "r");
    if (config_file) {
        char line[256];
        while (fgets(line, sizeof(line), config_file)) {
            char *key = strtok(line, "=");
            char *value = strtok(NULL, "\n");
            if (key && value) {
                if (strcmp(key, "calibration_factor") == 0) {
                    calibration_factor = atof(value);
                } else if (strcmp(key, "known_weight") == 0) {
                    known_weight = atof(value);
                }
            }
        }
        fclose(config_file);
    } else {
        fprintf(stderr, "Warning: Config file not found, using default values\n");
    }

    // Create socket
    socket_desc = socket(AF_INET, SOCK_STREAM, 0);
    if (socket_desc < 0) {
        fprintf(stderr, "Error: Could not create socket\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Prepare the sockaddr_in structure
    struct sockaddr_in server;
    server.sin_family = AF_INET;
    server.sin_addr.s_addr = INADDR_ANY;
    server.sin_port = htons(TCP_PORT);

    // Bind
    if (bind(socket_desc, (struct sockaddr *)&server, sizeof(server)) < 0) {
        fprintf(stderr, "Error: Bind failed\n");
        fclose(log_file);
        gpioTerminate();
        close(socket_desc);
        return 1;
    }

    // Listen
    listen(socket_desc, 3);

    // Accept incoming connections
    struct sockaddr_in client;
    int client_size = sizeof(struct sockaddr_in);
    int client_sock = accept(socket_desc, (struct sockaddr *)&client, (socklen_t *)&client_size);
    if (client_sock < 0) {
        fprintf(stderr, "Error: Accept failed\n");
        fclose(log_file);
        gpioTerminate();
        close(socket_desc);
        return 1;
    }

    printf("Connection accepted\n");

    return 0;
}

// Cleanup function
void cleanup() {
    // Stop servo motor
    gpioServo(SERVO_PIN, 0);

    // Close socket
    close(socket_desc);

    // Close log file
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (setup() != 0) {
        return 1;
    }

    char buffer[256];
    int read_size;

    // Receive a message from client
    while (running) {
        read_size = recv(socket_desc, buffer, 255, 0);
        if (read_size > 0) {
            buffer[read_size] = '\0';
            printf("Received: %s\n", buffer);

            // Parse target weight
            double target_weight = atof(buffer);

            // Dispense
            if (dispense(target_weight) != 0) {
                log_event(buffer, "N/A", "Dispense failed");
                fprintf(stderr, "Error: Dispense failed\n");
                continue;
            }

            // Get actual weight
            double actual_weight = get_actual_weight();
            if (actual_weight < 0) {
                log_event(buffer, "N/A", "Failed to read actual weight");
                fprintf(stderr, "Error: Failed to read actual weight\n");
                continue;
            }

            // Log event
            char actual_weight_str[20];
            snprintf(actual_weight_str, sizeof(actual_weight_str), "%.2f", actual_weight);
            log_event(buffer, actual_weight_str, "N/A");

            // Send actual weight back to client
            char weight_str[20];
            snprintf(weight_str, sizeof(weight_str), "%.2f", actual_weight);
            send(socket_desc, weight_str, strlen(weight_str), 0);
        } else if (read_size == 0) {
            printf("Client disconnected\n");
            break;
        } else {
            fprintf(stderr, "Error: recv failed\n");
            break;
        }
    }

    cleanup();
    return 0;
}

