#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17

// Global variables
static volatile int running = 1;
static int debounce_delay = 50; // Default debounce delay in milliseconds

// Function prototypes
int initialize_gpio();
int read_touch_sensor();
int control_relay(int state);
int log_relay_state(int state);
void signal_handler(int signal);
void cleanup();

// Structure to hold GPIO configuration
typedef struct {
    int touch_pin;
    int relay_pin;
} gpio_config_t;

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT);
    gpioSetMode(RELAY_PIN, PI_OUTPUT);
    gpioWrite(RELAY_PIN, 0); // Initialize relay to OFF state

    return 0;
}

// Read the touch sensor state
int read_touch_sensor() {
    return gpioRead(TOUCH_SENSOR_PIN);
}

// Control the relay state
int control_relay(int state) {
    gpioWrite(RELAY_PIN, state);
    return 0;
}

// Log the relay state with timestamp
int log_relay_state(int state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (state == 1) {
        printf("%s Relay: ON\n", timestamp);
    } else {
        printf("%s Relay: OFF\n", timestamp);
    }

    return 0;
}

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Cleanup function to release resources
void cleanup() {
    control_relay(0); // Turn off relay
    gpioTerminate(); // Terminate pigpio
}

int main(int argc, char *argv[]) {
    int opt;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "d:")) != -1) {
        switch (opt) {
            case 'd':
                debounce_delay = atoi(optarg);
                if (debounce_delay <= 0) {
                    fprintf(stderr, "Invalid debounce delay. Using default value (50ms).\n");
                    debounce_delay = 50;
                }
                break;
            default:
                fprintf(stderr, "Usage: %s [-d <milliseconds>]\n", argv[0]);
                return 1;
        }
    }

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int last_touch_state = 0; // 0 = LOW, 1 = HIGH
    int current_touch_state;
    int relay_state = 0; // 0 = OFF, 1 = ON

    printf("Touch sensor monitoring started. Debounce delay: %d ms\n", debounce_delay);

    while (running) {
        current_touch_state = read_touch_sensor();

        if (current_touch_state == 1 && last_touch_state == 0) {
            // Rising edge detected
            gpioDelay(debounce_delay * 1000); // Debounce
            current_touch_state = read_touch_sensor(); // Re-read after debounce

            if (current_touch_state == 1) {
                // Valid rising edge
                relay_state = !relay_state; // Toggle relay state
                control_relay(relay_state);
                log_relay_state(relay_state);
            }
        }

        last_touch_state = current_touch_state;
        gpioDelay(1000); // Check every 1 ms
    }

    cleanup();
    return 0;
}

