#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <termios.h>
#include <pigpio.h>

#define SERVO_PIN 18
#define MIN_PULSE_WIDTH 500
#define MAX_PULSE_WIDTH 2500
#define MIN_ANGLE 0
#define MAX_ANGLE 180
#define DEFAULT_ANGLE 90

static struct termios original_termios;
static volatile int running = 1;

// Function to handle signals (e.g., Ctrl+C)
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the terminal for non-blocking keyboard input
int init_terminal() {
    struct termios new_termios;

    // Save the original terminal settings
    if (tcgetattr(STDIN_FILENO, &original_termios) != 0) {
        perror("tcgetattr");
        return -1;
    }

    // Set the new terminal settings
    new_termios = original_termios;
    new_termios.c_lflag &= ~(ICANON | ECHO); // Disable canonical mode and echo
    new_termios.c_cc[VMIN] = 0;              // Read non-blocking
    new_termios.c_cc[VTIME] = 0;             // No timeout

    if (tcsetattr(STDIN_FILENO, TCSANOW, &new_termios) != 0) {
        perror("tcsetattr");
        return -1;
    }

    return 0;
}

// Function to restore the original terminal settings
void restore_terminal() {
    if (tcsetattr(STDIN_FILENO, TCSANOW, &original_termios) != 0) {
        perror("tcsetattr (restore)");
    }
}

// Function to set the servo angle
int set_servo_angle(int angle) {
    if (angle < MIN_ANGLE || angle > MAX_ANGLE) {
        fprintf(stderr, "Error: Angle out of range (%d). Must be between %d and %d.\n", angle, MIN_ANGLE, MAX_ANGLE);
        return -1;
    }

    int pulse_width = (int)(((float)(angle) / (float)(MAX_ANGLE - MIN_ANGLE)) * (MAX_PULSE_WIDTH - MIN_PULSE_WIDTH) + MIN_PULSE_WIDTH);

    int result = gpioServo(SERVO_PIN, pulse_width);
    if (result != 0) {
        fprintf(stderr, "Error: gpioServo failed with code %d\n", result);
        return -1;
    }

    return 0;
}

// Function to get a single character from the keyboard without blocking
int getch() {
    struct termios oldt, newt;
    int ch;

    tcgetattr(STDIN_FILENO, &oldt);
    newt = oldt;
    newt.c_lflag &= ~(ICANON | ECHO);
    tcsetattr(STDIN_FILENO, TCSANOW, &newt);
    ch = getchar();
    tcsetattr(STDIN_FILENO, TCSANOW, &oldt);

    return ch;
}

int main() {
    int angle = DEFAULT_ANGLE;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO18 as an output
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Set PWM frequency (50Hz)
    gpioSetPWMfrequency(SERVO_PIN, 50);

    // Initialize the terminal
    if (init_terminal() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set the initial servo angle
    if (set_servo_angle(angle) != 0) {
        restore_terminal();
        gpioTerminate();
        return 1;
    }

    printf("Servo control program. Press '+' to increase angle, '-' to decrease, 'q' to quit.\n");

    // Main loop
    while (running) {
        int ch = getch();

        if (ch == '+') {
            angle += 10;
            if (angle > MAX_ANGLE) {
                angle = MAX_ANGLE;
            }
        } else if (ch == '-') {
            angle -= 10;
            if (angle < MIN_ANGLE) {
                angle = MIN_ANGLE;
            }
        } else if (ch == 'q') {
            running = 0;
        }

        if (set_servo_angle(angle) == 0) {
            printf("Angle: %d\n", angle);
        }
    }

    // Stop PWM pulses
    gpioServo(SERVO_PIN, 0);

    // Restore terminal settings
    restore_terminal();

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

