#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

#define GPIO_PIN 17
#define DEBOUNCE_MS 2
#define LOG_FILE "motor_rpm.log"
#define SAMPLE_INTERVAL_S 5

static volatile int running = 1;
static FILE *log_file = NULL;

// Structure to hold program state
typedef struct {
    int gpio_initialized;
    int log_file_open;
} ProgramState;

ProgramState state = {0, 0};

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal) {
    running = 0;
    fprintf(stderr, "\nCaught signal %d, stopping...\n", signal);
}

// Function to get current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp
    if (timestamp == NULL) {
        perror("Failed to allocate memory for timestamp");
        return NULL;
    }

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Function to calculate RPM
double calculate_rpm(unsigned int pulse_count, double time_interval) {
    return (double)pulse_count / time_interval * 60.0;
}

// Function to log RPM data to file
int log_rpm_data(const char *timestamp, double rpm) {
    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }

    int result = fprintf(log_file, "%s,%.2f\n", timestamp, rpm);
    if (result < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }

    fflush(log_file); // Flush the buffer to ensure data is written to disk
    return 0;
}

// Callback function for GPIO interrupt
void pulse_callback(int gpio, int level, uint32_t tick, void *user_data) {
    if (level == PI_HIGH) { // Rising edge detected
        // No need to implement debouncing here, pigpio handles it with the edge parameter
        // in gpioSetISRFuncEx.  We just increment the pulse count.
        // In a distributed system, this function could trigger a message to be sent
        // to a central monitoring system.
    }
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    state.gpio_initialized = 1;

    // Set GPIO pin as input with pull-up resistor
    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP);

    // Set up interrupt on rising edge with debouncing
    if (gpioSetISRFuncEx(GPIO_PIN, RISING_EDGE, DEBOUNCE_MS, pulse_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR function\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }
    state.log_file_open = 1;

    unsigned int pulse_count = 0;
    struct timespec start_time, current_time;
    double time_interval;

    // Main loop
    while (running) {
        // Reset pulse count
        pulse_count = 0;

        // Record start time
        if (clock_gettime(CLOCK_MONOTONIC, &start_time) == -1) {
            perror("clock_gettime");
            running = 0; // Exit loop on error
            continue;      // Skip the rest of the loop
        }

        // Wait for the sample interval
        sleep(SAMPLE_INTERVAL_S);

        // Record current time
        if (clock_gettime(CLOCK_MONOTONIC, &current_time) == -1) {
            perror("clock_gettime");
            running = 0; // Exit loop on error
            continue;      // Skip the rest of the loop
        }

        // Calculate time interval in seconds
        time_interval = (current_time.tv_sec - start_time.tv_sec) +
                        (current_time.tv_nsec - start_time.tv_nsec) / 1000000000.0;

        // Calculate RPM
        double rpm = calculate_rpm(pulse_count, time_interval);

        // Get ISO 8601 timestamp
        char *timestamp = get_iso8601_timestamp();
        if (timestamp == NULL) {
            running = 0; // Exit loop on error
            continue;      // Skip the rest of the loop
        }

        // Log RPM data
        if (log_rpm_data(timestamp, rpm) != 0) {
            running = 0; // Exit loop on error
        }

        // Print RPM to stdout
        printf("RPM: %.2f\n", rpm);

        free(timestamp); // Free the allocated memory
    }

    // Cleanup
    if (state.log_file_open) {
        fclose(log_file);
    }
    if (state.gpio_initialized) {
        gpioTerminate();
    }

    fprintf(stderr, "Program terminated cleanly.\n");
    return 0;
}

