    struct timespec start_time, current_time;
    double time_interval;

    // Main loop
    while (running) {
        // Reset pulse count
        pulse_count = 0;

        // Record start time
        if (clock_gettime(CLOCK_MONOTONIC, &start_time) == -1) {
            perror("clock_gettime");
            running = 0; // Exit loop on error
            continue;      // Skip the rest of the loop
        }

        // Wait for the sample interval
        sleep(SAMPLE_INTERVAL_S);

        // Record current time
        if (clock_gettime(CLOCK_MONOTONIC, &current_time) == -1) {
            perror("clock_gettime");
            running = 0; // Exit loop on error
            continue;      // Skip the rest of the loop
        }

        // Calculate time interval in seconds
        time_interval = (current_time.tv_sec - start_time.tv_sec) +
                        (current_time.tv_nsec - start_time.tv_nsec) / 1000000000.0;

        // Calculate RPM
        double rpm = calculate_rpm(pulse_count, time_interval);

        // Get ISO 8601 timestamp
        char *timestamp = get_iso8601_timestamp();
        if (timestamp == NULL) {
            running = 0; // Exit loop on error
            continue;      // Skip the rest of the loop
        }

        // Log RPM data
        if (log_rpm_data(timestamp, rpm) != 0) {
            running = 0; // Exit loop on error
        }

        // Print RPM to stdout
        printf("RPM: %.2f\n", rpm);

        free(timestamp); // Free the allocated memory
    }

    // Cleanup
    if (state.log_file_open) {
        fclose(log_file);
    }
    if (state.gpio_initialized) {
        gpioTerminate();
    }

    fprintf(stderr, "Program terminated cleanly.\n");
    return 0;
}

