#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17

// Debounce time in milliseconds
#define DEBOUNCE_TIME 50

// Relay activation time in seconds
#define RELAY_ACTIVATION_TIME 10

// Global flag to signal program termination
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_touch_sensor();
void control_relay(int state);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", signal);
        program_running = 0;
    }
}

// Function to read the touch sensor state
int read_touch_sensor() {
    return gpioRead(TOUCH_SENSOR_PIN);
}

// Function to control the relay
void control_relay(int state) {
    gpioWrite(RELAY_PIN, state);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT);
    gpioSetMode(RELAY_PIN, PI_OUTPUT);

    // Set initial relay state to OFF
    control_relay(0);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Variables for debouncing and relay activation
    int last_touch_state = 0;
    unsigned long last_touch_time = 0;
    int relay_active = 0;
    unsigned long relay_activation_start_time = 0;

    fprintf(stderr, "Program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        int touch_state = read_touch_sensor();

        if (touch_state == 1) {
            // Rising edge detected
            if (last_touch_state == 0) {
                last_touch_time = gpioTick();
            }

            // Debounce
            if (gpioTick() - last_touch_time >= DEBOUNCE_TIME * 1000) {
                if (!relay_active) {
                    // Toggle relay state
                    int current_relay_state = gpioRead(RELAY_PIN);
                    control_relay(!current_relay_state);

                    // Log relay state change
                    fprintf(stderr, "Relay toggled to state: %d\n", !current_relay_state);

                    // Start relay activation timer
                    relay_active = 1;
                    relay_activation_start_time = gpioTick();
                }
            }
        } else {
            // Falling edge detected
            last_touch_state = 0;
        }

        // Check if relay activation time has elapsed
        if (relay_active && (gpioTick() - relay_activation_start_time >= RELAY_ACTIVATION_TIME * 1000000)) {
            // Force relay OFF
            control_relay(0);
            relay_active = 0;
            fprintf(stderr, "Relay forced OFF due to prolonged activation.\n");
        }

        // Update last touch state
        if (touch_state == 1 && last_touch_state == 0) {
            last_touch_state = 1;
        } else if (touch_state == 0 && last_touch_state == 1) {
            last_touch_state = 0;
        }

        // Delay for 10 milliseconds
        gpioDelay(10000);
    }

    // Cleanup
    control_relay(0); // Ensure relay is OFF on exit
    gpioTerminate(); // Terminate pigpio

    fprintf(stderr, "Program terminated.\n");
    return 0;
}

