#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Constants
#define VALVE_GPIO 18
#define ENABLE_GPIO 23
#define FLOW_SENSOR_GPIO 24
#define PWM_FREQUENCY 1000 // Hz
#define TARGET_FLOW_RATE_MIN 0.0
#define TARGET_FLOW_RATE_MAX 10.0
#define FLOW_SENSOR_PPR 450.0 // Pulses per liter
#define LOG_FILE "flow_log.csv"

// Global variables
static volatile int pulse_count = 0;
static FILE *log_file = NULL;
static double target_flow_rate = 0.0;
static int running = 1;

// Function prototypes
void flow_sensor_isr(int gpio, int level, uint32_t tick, void *user_data);
double calculate_flow_rate(int pulse_count, double elapsed_time);
int calculate_pwm_duty_cycle(double flow_rate, double target_flow_rate);
void log_data(double flow_rate, int valve_position);
void signal_handler(int signal);

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal) {
    printf("Caught signal %d, shutting down...\n", signal);
    running = 0;
}

// Interrupt service routine for the flow sensor
void flow_sensor_isr(int gpio, int level, uint32_t tick, void *user_data) {
    pulse_count++;
}

// Function to calculate flow rate in L/min
double calculate_flow_rate(int pulse_count, double elapsed_time) {
    return (double)pulse_count / FLOW_SENSOR_PPR / elapsed_time * 60.0;
}

// Function to calculate PWM duty cycle
int calculate_pwm_duty_cycle(double flow_rate, double target_flow_rate) {
    double error = target_flow_rate - flow_rate;
    double duty_cycle = error * 1.0; // Kp = 1.0

    // Clamp the duty cycle to the range 0-255
    if (duty_cycle < 0) {
        duty_cycle = 0;
    } else if (duty_cycle > 255) {
        duty_cycle = 255;
    }

    return (int)duty_cycle;
}

// Function to log data to a CSV file
void log_data(double flow_rate, int valve_position) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    long timestamp_ms = (ts.tv_sec * 1000) + (ts.tv_nsec / 1000000);

    if (log_file != NULL) {
        fprintf(log_file, "%ld,%.2f,%d\n", timestamp_ms, flow_rate, valve_position);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    if (argc != 2) {
        fprintf(stderr, "Usage: %s -t <target_flow_rate_LPM>\n", argv[0]);
        return 1;
    }

    char *endptr;
    target_flow_rate = strtod(argv[1], &endptr);

    if (endptr == argv[1] || *endptr != '\0' || target_flow_rate < TARGET_FLOW_RATE_MIN || target_flow_rate > TARGET_FLOW_RATE_MAX) {
        fprintf(stderr, "Error: Invalid target flow rate. Must be between %.2f and %.2f L/min.\n", TARGET_FLOW_RATE_MIN, TARGET_FLOW_RATE_MAX);
        return 1;
    }

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(VALVE_GPIO, PI_OUTPUT);
    gpioSetMode(ENABLE_GPIO, PI_OUTPUT);
    gpioSetMode(FLOW_SENSOR_GPIO, PI_INPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(VALVE_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(VALVE_GPIO, 255);

    // Enable the valve
    gpioWrite(ENABLE_GPIO, 1);

    // Register interrupt service routine for the flow sensor
    if (gpioSetISRFuncEx(FLOW_SENSOR_GPIO, RISING_EDGE, 0, flow_sensor_isr, NULL) != 0) {
        fprintf(stderr, "Error: Failed to register interrupt service routine\n");
        gpioTerminate();
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        // Reset pulse count
        pulse_count = 0;

        // Wait for 100ms
        gpioDelay(100000); // 100ms = 100000 microseconds

        // Calculate flow rate
        double flow_rate = calculate_flow_rate(pulse_count, 0.1); // 0.1 seconds

        // Calculate PWM duty cycle
        int duty_cycle = calculate_pwm_duty_cycle(flow_rate, target_flow_rate);

        // Set PWM duty cycle
        gpioPWM(VALVE_GPIO, duty_cycle);

        // Log data
        log_data(flow_rate, duty_cycle);
    }

    // Shutdown sequence
    printf("Shutting down...\n");
    gpioPWM(VALVE_GPIO, 0); // Set PWM duty cycle to 0
    gpioWrite(ENABLE_GPIO, 0); // Drive GPIO 23 low
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate(); // Terminate pigpio library

    return 0;
}

