#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define LOCK1_PIN 17
#define LOCK2_PIN 27
#define BUTTON_PIN 22

// Define RFID tag
const unsigned char valid_tag[10] = {0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07, 0x08, 0x09, 0x0A};

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 100000 // 100 kHz

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_rfid(unsigned char *tag);
int verify_tag(const unsigned char *tag);
void control_locks(int lock1_state, int lock2_state);
void log_event(const char *message);
void button_interrupt_handler(int gpio, int level, uint32_t tick);
void signal_handler(int signal);

// Function to read RFID tag from SPI
int read_rfid(unsigned char *tag) {
    char tx_buf[1] = {0x00}; // Dummy byte to initiate SPI transfer
    char rx_buf[10];

    int result = spiXfer(spi_handle, tx_buf, rx_buf, 10);

    if (result != 0) {
        log_event("SPI read failed");
        return -1;
    }

    memcpy(tag, rx_buf, 10);

    return 0;
}

// Function to verify RFID tag
int verify_tag(const unsigned char *tag) {
    if (memcmp(tag, valid_tag, 10) == 0) {
        return 0; // Valid tag
    } else {
        return -1; // Invalid tag
    }
}

// Function to control the locks
void control_locks(int lock1_state, int lock2_state) {
    gpioWrite(LOCK1_PIN, lock1_state);
    gpioWrite(LOCK2_PIN, lock2_state);
}

// Function to log events to file
void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s: %s\n", timestamp, message);
    fflush(log_file); // Ensure immediate write to file
}

// Button interrupt handler
void button_interrupt_handler(int gpio, int level, uint32_t tick) {
    static uint32_t last_tick = 0;
    uint32_t current_tick = gpioTick();

    // Debounce the button (50ms)
    if (current_tick - last_tick < 50000) {
        return;
    }
    last_tick = current_tick;

    if (level == 0) { // Button pressed (active low)
        unsigned char tag[10];
        if (read_rfid(tag) == 0) {
            if (verify_tag(tag) == 0) {
                log_event("Valid tag read. Waiting for button press.");
                // Wait for button press to disengage locks
                while (gpioRead(BUTTON_PIN) == 1 && program_running) {
                    gpioDelay(10000); // 10ms delay
                }
                if (program_running) {
                    log_event("Button pressed. Disengaging locks.");
                    control_locks(0, 0); // Disengage locks
                    gpioDelay(5000000); // 5 seconds
                    control_locks(1, 1); // Engage locks
                    log_event("Locks re-engaged.");
                }
            } else {
                log_event("Invalid tag read.");
            }
        } else {
            log_event("RFID read failed.");
        }
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    log_event("Received signal. Shutting down...");

    // Disengage locks
    control_locks(1, 1);

    // Close SPI interface
    spiClose(spi_handle);

    // Close log file
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen("/var/log/door_access.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(LOCK1_PIN, PI_OUTPUT);
    gpioSetMode(LOCK2_PIN, PI_OUTPUT);
    gpioSetMode(BUTTON_PIN, PI_INPUT);
    gpioSetPullUpDown(BUTTON_PIN, PI_PUD_UP); // Enable pull-up resistor

    // Initialize locks to engaged state
    control_locks(1, 1);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // SPI channel 0, 100kHz, mode 0
    if (spi_handle < 0) {
        log_event("SPI open failed");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Set up interrupt handler for button press
    gpioSetAlertFunc(BUTTON_PIN, button_interrupt_handler);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_event("Door access control system started");

    // Main loop
    while (program_running) {
        // Non-blocking RFID read (handled in interrupt)
        gpioDelay(100000); // Check every 100ms
    }

    return 0;
}

