#include <pigpio.h>
#include <pthread.h>
#include <signal.h>
#include <time.h>
#include <string.h>
#include <unistd.h>

// Motor 1
#define MOTOR1_ENA 23
#define MOTOR1_IN1 24
#define MOTOR1_IN2 25

// Motor 2
#define MOTOR2_ENB 12
#define MOTOR2_IN3 16
#define MOTOR2_IN4 20

// Encoder 1
#define ENCODER1_A 5
#define ENCODER1_B 6

// Encoder 2
#define ENCODER2_A 26
#define ENCODER2_B 19

// PID Constants
#define KP 1.0
#define KI 0.1
#define KD 0.01

// Target Speed (RPM)
#define TARGET_SPEED 60.0

// PWM Frequency (Hz)
#define PWM_FREQUENCY 100.0

// PID Sample Time (ms)
#define SAMPLE_TIME 100

// Global Variables
volatile long encoder1_count = 0;
volatile long encoder2_count = 0;

FILE *log_file = NULL;
int running = 1;

pthread_mutex_t encoder1_mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_mutex_t encoder2_mutex = PTHREAD_MUTEX_INITIALIZER;

// Function Prototypes
void *encoder1_thread(void *arg);
void *encoder2_thread(void *arg);
void set_motor_speed(int motor, int speed);
double calculate_pid(double setpoint, double actual);
void log_data(double motor1_speed, double motor2_speed, double pid_output, double p, double i, double d);
void signal_handler(int signal);

// Encoder 1 Thread
void *encoder1_thread(void *arg) {
    int last_state = gpioRead(ENCODER1_B);
    int current_state;
    long count = 0;

    while (running) {
        current_state = gpioRead(ENCODER1_A);
        if (current_state != last_state) {
            if (gpioRead(ENCODER1_B) != last_state) {
                pthread_mutex_lock(&encoder1_mutex);
                count++;
                encoder1_count = count;
                pthread_mutex_unlock(&encoder1_mutex);
            } else {
                pthread_mutex_lock(&encoder1_mutex);
                count--;
                encoder1_count = count;
                pthread_mutex_unlock(&encoder1_mutex);
            }
        }
        last_state = current_state;
        gpioDelay(1); // Small delay to avoid busy-waiting
    }
    return NULL;
}

// Encoder 2 Thread
void *encoder2_thread(void *arg) {
    int last_state = gpioRead(ENCODER2_B);
    int current_state;
    long count = 0;

    while (running) {
        current_state = gpioRead(ENCODER2_A);
        if (current_state != last_state) {
            if (gpioRead(ENCODER2_B) != last_state) {
                pthread_mutex_lock(&encoder2_mutex);
                count++;
                encoder2_count = count;
                pthread_mutex_unlock(&encoder2_mutex);
            } else {
                pthread_mutex_lock(&encoder2_mutex);
                count--;
                encoder2_count = count;
                pthread_mutex_unlock(&encoder2_mutex);
            }
        }
        last_state = current_state;
        gpioDelay(1); // Small delay to avoid busy-waiting
    }
    return NULL;
}

// Set Motor Speed (PWM)
void set_motor_speed(int motor, int speed) {
    if (motor == 1) {
        gpioPWM(MOTOR1_ENA, speed);
    } else if (motor == 2) {
        gpioPWM(MOTOR2_ENB, speed);
    }
}

// Calculate PID Output
double calculate_pid(double setpoint, double actual) {
    static double integral = 0.0;
    static double previous_error = 0.0;

    double error = setpoint - actual;
    integral += error;
    double derivative = error - previous_error;
    double output = KP * error + KI * integral + KD * derivative;

    previous_error = error;
    return output;
}

// Log Data to File
void log_data(double motor1_speed, double motor2_speed, double pid_output, double p, double i, double d) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f\n", timestamp, motor1_speed, motor2_speed, p, i, d, pid_output);
    fflush(log_file);
}

// Signal Handler
void signal_handler(int signal) {
    printf("Caught signal %d, stopping motors and exiting...\n", signal);
    running = 0;

    // Stop Motors
    set_motor_speed(1, 0);
    set_motor_speed(2, 0);

    // Close Log File
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Release GPIO Lines
    gpioTerminate();

    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO Modes
    gpioSetMode(MOTOR1_ENA, PI_OUTPUT);
    gpioSetMode(MOTOR1_IN1, PI_OUTPUT);
    gpioSetMode(MOTOR1_IN2, PI_OUTPUT);
    gpioSetMode(MOTOR2_ENB, PI_OUTPUT);
    gpioSetMode(MOTOR2_IN3, PI_OUTPUT);
    gpioSetMode(MOTOR2_IN4, PI_OUTPUT);
    gpioSetMode(ENCODER1_A, PI_INPUT);
    gpioSetMode(ENCODER1_B, PI_INPUT);
    gpioSetMode(ENCODER2_A, PI_INPUT);
    gpioSetMode(ENCODER2_B, PI_INPUT);

    // Set PWM Frequency
    gpioSetPWMfrequency(MOTOR1_ENA, PWM_FREQUENCY);
    gpioSetPWMfrequency(MOTOR2_ENB, PWM_FREQUENCY);

    // Set PWM Range (0-255)
    gpioSetPWMrange(MOTOR1_ENA, 255);
    gpioSetPWMrange(MOTOR2_ENB, 255);

    // Set Motor Directions (Forward)
    gpioWrite(MOTOR1_IN1, 1);
    gpioWrite(MOTOR1_IN2, 0);
    gpioWrite(MOTOR2_IN3, 1);
    gpioWrite(MOTOR2_IN4, 0);

    // Open Log File
    log_file = fopen("motor_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Write Header Row
    fprintf(log_file, "Timestamp,Motor1_RPM,Motor2_RPM,P,I,D,PID_Output\n");

    // Create Threads
    pthread_t encoder1_thread_id, encoder2_thread_id;
    if (pthread_create(&encoder1_thread_id, NULL, encoder1_thread, NULL) != 0) {
        fprintf(stderr, "Error creating encoder 1 thread!\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }
    if (pthread_create(&encoder2_thread_id, NULL, encoder2_thread, NULL) != 0) {
        fprintf(stderr, "Error creating encoder 2 thread!\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Install Signal Handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main Loop
    while (running) {
        // Read Encoder Counts
        pthread_mutex_lock(&encoder1_mutex);
        long encoder1_count_local = encoder1_count;
        pthread_mutex_unlock(&encoder1_mutex);

        pthread_mutex_lock(&encoder2_mutex);
        long encoder2_count_local = encoder2_count;
        pthread_mutex_unlock(&encoder2_mutex);

        // Calculate RPM
        double motor1_rpm = (double)encoder1_count_local * 60.0 / SAMPLE_TIME;
        double motor2_rpm = (double)encoder2_count_local * 60.0 / SAMPLE_TIME;

        // Calculate PID Output
        double pid_output = calculate_pid(TARGET_SPEED, motor1_rpm);

        // Set Motor Speeds
        int motor1_speed = (int)pid_output;
        int motor2_speed = (int)pid_output;

        if (motor1_speed > 255) motor1_speed = 255;
        if (motor1_speed < 0) motor1_speed = 0;
        if (motor2_speed > 255) motor2_speed = 255;
        if (motor2_speed < 0) motor2_speed = 0;

        set_motor_speed(1, motor1_speed);
        set_motor_speed(2, motor2_speed);

        // Log Data
        log_data(motor1_rpm, motor2_rpm, pid_output, KP, KI, KD);

        // Delay
        gpioDelay(SAMPLE_TIME);
    }

    // Join Threads
    pthread_join(encoder1_thread_id, NULL);
    pthread_join(encoder2_thread_id, NULL);

    // Cleanup
    fclose(log_file);
    gpioTerminate();

    return 0;
}

