#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Define constants
#define I2C_BUS 1
#define MPR121_ADDR 0x5A
#define RELAY_GPIO 17
#define LOG_FILE "relay_log.txt"

// MPR121 Register Addresses
#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_ELECTRODE_CONFIG 0x5E
#define MPR121_TOUCHTH_0 0x41
#define MPR121_RELEASETH_0 0x42

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int mpr121_init();
int read_touch_status(uint16_t *touch_status);
void set_relay_state(int state);
void log_relay_state(int state);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Ctrl+C detected. Shutting down...\n");
        program_running = 0;
    }
}

// MPR121 Initialization function
int mpr121_init() {
    // Soft reset
    if (i2cWriteByteData(i2c_handle, 0x80, 0x63) < 0) {
        fprintf(stderr, "Error: Soft reset failed.\n");
        return -1;
    }
    gpioDelay(100); // Wait for reset to complete

    // Configure filtering parameters (example values)
    if (i2cWriteByteData(i2c_handle, 0x2B, 0x01) < 0) { // MHD_R
        fprintf(stderr, "Error: MHD_R config failed.\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x2C, 0x01) < 0) { // NHD_R
        fprintf(stderr, "Error: NHD_R config failed.\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x2D, 0x01) < 0) { // NCL_R
        fprintf(stderr, "Error: NCL_R config failed.\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x2E, 0x00) < 0) { // FDL_R
        fprintf(stderr, "Error: FDL_R config failed.\n");
        return -1;
    }

    // Set touch and release thresholds for each electrode (example values)
    for (int i = 0; i < 12; i++) {
        if (i2cWriteByteData(i2c_handle, MPR121_TOUCHTH_0 + 2 * i, 40) < 0) { // Touch threshold
            fprintf(stderr, "Error: Touch threshold config failed for electrode %d.\n", i);
            return -1;
        }
        if (i2cWriteByteData(i2c_handle, MPR121_RELEASETH_0 + 2 * i, 20) < 0) { // Release threshold
            fprintf(stderr, "Error: Release threshold config failed for electrode %d.\n", i);
            return -1;
        }
    }

    // Enable run mode
    if (i2cWriteByteData(i2c_handle, MPR121_ELECTRODE_CONFIG, 0x0C) < 0) {
        fprintf(stderr, "Error: Run mode config failed.\n");
        return -1;
    }

    return 0;
}

// Function to read touch status from MPR121
int read_touch_status(uint16_t *touch_status) {
    char buf[2];
    if (i2cReadI2CBlockData(i2c_handle, MPR121_TOUCHSTATUS_L, buf, 2) != 2) {
        fprintf(stderr, "Error: Failed to read touch status.\n");
        return -1;
    }
    *touch_status = ((uint16_t)buf[1] << 8) | (uint16_t)buf[0];
    return 0;
}

// Function to set the relay state
void set_relay_state(int state) {
