#define MPR121_E5FDF 0x4C
#define MPR121_E6FDL 0x4D
#define MPR121_E6FDF 0x4E
#define MPR121_E7FDL 0x4F
#define MPR121_E7FDF 0x50
#define MPR121_E8FDL 0x51
#define MPR121_E8FDF 0x52
#define MPR121_E9FDL 0x53
#define MPR121_E9FDF 0x54
#define MPR121_EAFDL 0x55
#define MPR121_EAFDF 0x56
#define MPR121_EBFDL 0x57
#define MPR121_EBFDF 0x58
#define MPR121_ECFDL 0x59
#define MPR121_ECFDF 0x5A
#define MPR121_EDFDL 0x5B
#define MPR121_EDFDF 0x5C

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int mpr121_init();
int read_touch_status(uint16_t *touch_status);
void toggle_relay();
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Function to initialize the MPR121
int mpr121_init() {
    // Stop mode
    if (i2cWriteByteData(i2c_handle, MPR121_ECR, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to set ECR to stop mode.\n");
        return -1;
    }

    // Configure touch and release thresholds
    for (int i = 0; i < 12; i++) {
        if (i2cWriteByteData(i2c_handle, MPR121_E0FDL + (i * 2), 0x0A) < 0) { // Touch threshold
            fprintf(stderr, "Error: Failed to set touch threshold for electrode %d.\n", i);
            return -1;
        }
        if (i2cWriteByteData(i2c_handle, MPR121_E0FDF + (i * 2), 0x05) < 0) { // Release threshold
            fprintf(stderr, "Error: Failed to set release threshold for electrode %d.\n", i);
            return -1;
        }
    }

    // Configure filter and charge time
    if (i2cWriteByteData(i2c_handle, MPR121_MHDR, 0x01) < 0) {
        fprintf(stderr, "Error: Failed to set MHDR.\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, MPR121_NHDR, 0x01) < 0) {
        fprintf(stderr, "Error: Failed to set NHDR.\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, MPR121_NCLR, 0x0E) < 0) {
        fprintf(stderr, "Error: Failed to set NCLR.\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, MPR121_FDLR, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to set FDLR.\n");
        return -1;
    }

    if (i2cWriteByteData(i2c_handle, MPR121_MHDF, 0x01) < 0) {
        fprintf(stderr, "Error: Failed to set MHDF.\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, MPR121_NHDF, 0x01) < 0) {
        fprintf(stderr, "Error: Failed to set NHDF.\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, MPR121_NCLF, 0x0E) < 0) {
        fprintf(stderr, "Error: Failed to set NCLF.\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, MPR121_FDLF, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to set FDLF.\n");
        return -1;
    }

    // Set electrode current (example value)
    if (i2cWriteByteData(i2c_handle, MPR121_CONFIG1, 0x20) < 0) { // Set Electrode Current
        fprintf(stderr, "Error: Failed to set electrode current.\n");
        return -1;
    }

    // Set sample configuration
    if (i2cWriteByteData(i2c_handle, MPR121_CONFIG2, 0x01) < 0) { // Set Sample Configuration
        fprintf(stderr, "Error: Failed to set sample configuration.\n");
        return -1;
    }

    // Run mode
    if (i2cWriteByteData(i2c_handle, MPR121_ECR, 0x8F) < 0) {
        fprintf(stderr, "Error: Failed to set ECR to run mode.\n");
        return -1;
    }

    return 0;
}

// Function to read the touch status
int read_touch_status(uint16_t *touch_status) {
    char buf[2];
    if (i2cReadI2CBlockData(i2c_handle, MPR121_TOUCHSTATUS_L, buf, 2) != 2) {
        fprintf(stderr, "Error: Failed to read touch status.\n");
        return -1;
    }
    *touch_status = (buf[1] << 8) | buf[0];
    return 0;
}

// Function to toggle the relay
void toggle_relay() {
    int current_level = gpioRead(RELAY_GPIO);
    gpioWrite(RELAY_GPIO, !current_level);
    printf("Relay toggled to %d\n", !current_level);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus. %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize MPR121
    if (mpr121_init() < 0) {
        fprintf(stderr, "Error: MPR121 initialisation failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set relay GPIO as output
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    uint16_t touch_status = 0;
    while (!terminate) {
        if (read_touch_status(&touch_status) == 0) {
            if (touch_status > 0) {
                toggle_relay();
            }
        } else {
            fprintf(stderr, "Error: Failed to read touch status in main loop.\n");
        }
        gpioDelay(100); // 100ms delay
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

