#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define PIR_SENSOR_PIN 17
#define RELAY_PIN 18

// Define constants
#define RELAY_ON_TIME_MS 500
#define RATE_LIMIT_TIME_MS 2000

// Global variables
FILE *log_file = NULL;
int running = 1;

// Function prototypes
int initialize_gpio();
int read_pir_sensor();
void control_relay(int state);
void log_event(const char *event_type);
void cleanup();
void signal_handler(int signal);

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(PIR_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(PIR_SENSOR_PIN, PI_PUD_DOWN);
    gpioSetMode(RELAY_PIN, PI_OUTPUT);
    gpioWrite(RELAY_PIN, 0); // Ensure relay is initially off

    return 0;
}

// Function to read the PIR sensor
int read_pir_sensor() {
    return gpioRead(PIR_SENSOR_PIN);
}

// Function to control the relay
void control_relay(int state) {
    gpioWrite(RELAY_PIN, state);
    gpioDelay(RELAY_ON_TIME_MS * 1000); // Convert ms to microseconds
    gpioWrite(RELAY_PIN, 0);
}

// Function to log events with millisecond precision
void log_event(const char *event_type) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));
    snprintf(timestamp + strlen(timestamp), sizeof(timestamp) - strlen(timestamp), ".%03ld", ts.tv_nsec / 1000000);

    if (log_file != NULL) {
        fprintf(log_file, "%s: %s\n", timestamp, event_type);
        fflush(log_file); // Ensure immediate write to file
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    running = 0;
}

// Function to perform cleanup tasks
void cleanup() {
    printf("Cleaning up resources...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(RELAY_PIN, 0); // Ensure relay is off
    gpioTerminate();
    printf("Cleanup complete. Exiting.\n");
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("door_events.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    int last_state = 0; // 0 = no motion, 1 = motion detected
    struct timespec last_rate_limit_time;
    clock_gettime(CLOCK_MONOTONIC, &last_rate_limit_time);

    printf("Monitoring PIR sensor... Press Ctrl+C to exit.\n");

    while (running) {
        int pir_value = read_pir_sensor();

        if (pir_value == 1 && last_state == 0) {
            // Rising edge detected
            log_event("Motion Detected");
            control_relay(1);
            log_event("Door Unlocked");

            // Rate limiting
            struct timespec current_time;
            clock_gettime(CLOCK_MONOTONIC, &current_time);
            long time_diff_ms = (current_time.tv_sec - last_rate_limit_time.tv_sec) * 1000 + (current_time.tv_nsec - last_rate_limit_time.tv_nsec) / 1000000;

            if (time_diff_ms < RATE_LIMIT_TIME_MS) {
                struct timespec sleep_time;
                sleep_time.tv_sec = 0;
                sleep_time.tv_nsec = (RATE_LIMIT_TIME_MS - time_diff_ms) * 1000000; // Convert ms to ns
                nanosleep(&sleep_time, NULL);
            }

            clock_gettime(CLOCK_MONOTONIC, &last_rate_limit_time);
        }

        last_state = pir_value;
        gpioDelay(50 * 1000); // 50ms delay
    }

    cleanup();
    return 0;
}

