#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins for the motors
#define MOTOR1_GPIO 17
#define MOTOR2_GPIO 27

// Define PWM frequency
#define PWM_FREQUENCY 1000 // 1 kHz

// Define minimum and maximum step duration (in milliseconds)
#define MIN_DURATION 50
#define MAX_DURATION 200

// Define minimum and maximum number of steps in a pattern
#define MIN_STEPS 5
#define MAX_STEPS 15

// Define minimum and maximum duty cycle
#define MIN_DUTY_CYCLE 0
#define MAX_DUTY_CYCLE 255

// Global variable to indicate program termination
volatile sig_atomic_t shutdown_flag = 0;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Caught SIGINT, shutting down...\n");
        shutdown_flag = 1;
    }
}

// Function to generate a random integer within a specified range
int generate_random_int(int min, int max) {
    return min + (rand() % (max - min + 1));
}

// Function to generate a random duty cycle
int generate_random_duty_cycle() {
    return generate_random_int(MIN_DUTY_CYCLE, MAX_DUTY_CYCLE);
}

// Function to generate a random step duration
int generate_random_duration() {
    return generate_random_int(MIN_DURATION, MAX_DURATION);
}

// Function to generate a random number of steps
int generate_random_steps() {
    return generate_random_int(MIN_STEPS, MAX_STEPS);
}

// Function to generate a random haptic feedback pattern
void generate_pattern(int *duty_cycles1, int *duty_cycles2, int *durations, int *num_steps) {
    *num_steps = generate_random_steps();
    for (int i = 0; i < *num_steps; i++) {
        duty_cycles1[i] = generate_random_duty_cycle();
        duty_cycles2[i] = generate_random_duty_cycle();
        durations[i] = generate_random_duration();
    }
}

// Function to play a haptic feedback pattern
void play_pattern(int *duty_cycles1, int *duty_cycles2, int *durations, int num_steps) {
    for (int i = 0; i < num_steps; i++) {
        gpioPWM(MOTOR1_GPIO, duty_cycles1[i]);
        gpioPWM(MOTOR2_GPIO, duty_cycles2[i]);
        gpioDelay(durations[i] * 1000); // Convert milliseconds to microseconds
    }
}

// Function to stop both motors
void stop_motors() {
    gpioPWM(MOTOR1_GPIO, 0);
    gpioPWM(MOTOR2_GPIO, 0);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes for the motors
    gpioSetMode(MOTOR1_GPIO, PI_OUTPUT);
    gpioSetMode(MOTOR2_GPIO, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(MOTOR1_GPIO, PWM_FREQUENCY);
    gpioSetPWMfrequency(MOTOR2_GPIO, PWM_FREQUENCY);

    // Seed the random number generator
    srand(time(NULL));

    // Install signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Allocate memory for the pattern
    int *duty_cycles1 = malloc(MAX_STEPS * sizeof(int));
    int *duty_cycles2 = malloc(MAX_STEPS * sizeof(int));
    int *durations = malloc(MAX_STEPS * sizeof(int));
    int num_steps;

    if (duty_cycles1 == NULL || duty_cycles2 == NULL || durations == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!shutdown_flag) {
        // Generate a random haptic feedback pattern
        generate_pattern(duty_cycles1, duty_cycles2, durations, &num_steps);

        // Play the pattern
        play_pattern(duty_cycles1, duty_cycles2, durations, num_steps);

        // Introduce a delay before generating the next pattern
        gpioDelay(generate_random_int(500, 1000) * 1000); // Delay between 500ms and 1000ms
    }

    // Stop the motors
    stop_motors();

    // Free allocated memory
    free(duty_cycles1);
    free(duty_cycles2);
    free(durations);

    // Terminate pigpio library
    gpioTerminate();

    printf("Program terminated gracefully.\n");
    return 0;
}

