#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define HX711_DATA_PIN 4
#define HX711_CLOCK_PIN 17
#define SOLENOID_PIN 27

// Define constants
#define CALIBRATION_FILE "calibration.txt"
#define LOG_FILE "weight_log.txt"
#define CALIBRATION_READINGS 100
#define WEIGHT_THRESHOLD 10.0
#define TIMEOUT_US 500000 // 0.5 seconds
#define READ_INTERVAL_MS 500

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;
static double scale_factor = 1.0;
static double offset = 0.0;

// Function prototypes
int read_hx711(int data_pin, int clock_pin);
double calculate_weight(int raw_value, double scale_factor, double offset);
void engage_solenoid(int solenoid_pin, int state);
void log_data(FILE *log_file, int raw_value, double weight);
int load_calibration(const char *filename, double *scale_factor, double *offset);
int save_calibration(const char *filename, double scale_factor, double offset);
void signal_handler(int signal);

// Function to read raw value from HX711
int read_hx711(int data_pin, int clock_pin) {
    int i;
    int data = 0;

    gpioSetMode(data_pin, PI_INPUT);
    gpioSetMode(clock_pin, PI_OUTPUT);

    // Wait for data pin to go low
    int timeout = 0;
    while (gpioRead(data_pin) == 1 && timeout < TIMEOUT_US) {
        gpioDelay(1); // Small delay to avoid busy-waiting
        timeout++;
    }

    if (timeout >= TIMEOUT_US) {
        fprintf(stderr, "Timeout waiting for HX711 data.\n");
        return -1; // Indicate timeout error
    }

    for (i = 0; i < 24; i++) {
        gpioWrite(clock_pin, 1);
        gpioDelay(1); // Clock pulse width
        data = data << 1;
        if (gpioRead(data_pin)) {
            data++;
        }
        gpioWrite(clock_pin, 0);
        gpioDelay(1); // Clock pulse width
    }

    // 25th pulse for gain selection (default gain = 128)
    gpioWrite(clock_pin, 1);
    gpioDelay(1);
    gpioWrite(clock_pin, 0);
    gpioDelay(1);

    // Sign extend if negative
    if (data & 0x800000) {
        data |= 0xFF000000;
    }

    return data;
}

// Function to calculate weight
double calculate_weight(int raw_value, double scale_factor, double offset) {
    return (raw_value - offset) / scale_factor;
}

// Function to engage/disengage the solenoid
void engage_solenoid(int solenoid_pin, int state) {
    gpioWrite(solenoid_pin, state);
}

// Function to log data to file
void log_data(FILE *log_file, int raw_value, double weight) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "%d-%02d-%02d %02d:%02d:%02d, Raw: %d, Weight: %.2f kg\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec,
            raw_value, weight);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Function to load calibration data from file
int load_calibration(const char *filename, double *scale_factor, double *offset) {
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        fprintf(stderr, "Calibration file not found. Using default values.\n");
        *scale_factor = 1.0;
        *offset = 0.0;
        return -1; // Indicate failure to load calibration
    }

    if (fscanf(fp, "%lf %lf", scale_factor, offset) != 2) {
        fprintf(stderr, "Invalid calibration file format. Using default values.\n");
        fclose(fp);
        *scale_factor = 1.0;
        *offset = 0.0;
        return -1; // Indicate failure to load calibration
    }

    fclose(fp);
    printf("Calibration loaded: scale_factor = %.2f, offset = %.2f\n", *scale_factor, *offset);
    return 0; // Indicate success
}

// Function to save calibration data to file
int save_calibration(const char *filename, double scale_factor, double offset) {
    FILE *fp = fopen(filename, "w");
