        fprintf(stderr, "Error opening calibration file for writing.\n");
        return -1; // Indicate failure
    }

    fprintf(fp, "%.6f %.6f", scale_factor, offset);
    fclose(fp);
    printf("Calibration saved: scale_factor = %.6f, offset = %.2f\n", scale_factor, offset);
    return 0; // Indicate success
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    running = 0;
}

int main() {
    int raw_value;
    double weight;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(SOLENOID_PIN, PI_OUTPUT);

    // Load calibration data
    if (load_calibration(CALIBRATION_FILE, &scale_factor, &offset) != 0) {
        printf("Using default calibration values: scale_factor = %.2f, offset = %.2f\n", scale_factor, offset);
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file.\n");
        gpioTerminate();
        return 1;
    }

