#include <signal.h>
#include <syslog.h>
#include <pigpio.h>

// Define GPIO pins
#define RAIN_SENSOR_PIN 4
#define MOTOR_IN1_PIN 17
#define MOTOR_IN2_PIN 18
#define MOTOR_PWM_PIN 27

// Define motor control parameters
#define MOTOR_FREQUENCY 1000
#define MOTOR_DUTY_CYCLE 150
#define MOTOR_DURATION 5 // seconds

// Define rain detection parameters
#define DEBOUNCE_READINGS 5
#define DEBOUNCE_DELAY 50 // milliseconds
#define RAIN_THRESHOLD 3

// Global variables
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_rain_sensor();
int debounce_rain_sensor();
void control_motor(int state);
void log_event(const char *message);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    log_event("Received signal, shutting down...");
    cleanup();
    exit(0);
}

// Cleanup function to stop motor and release GPIO resources
void cleanup() {
    control_motor(0); // Stop the motor
    gpioTerminate();   // Terminate pigpio
    closelog();        // Close syslog
}

// Function to read the rain sensor
int read_rain_sensor() {
    int value = gpioRead(RAIN_SENSOR_PIN);
    if (value < 0) {
        syslog(LOG_ERR, "Error reading rain sensor: %d", value);
        return -1; // Indicate an error
    }
    return value;
}

// Function to debounce the rain sensor
int debounce_rain_sensor() {
    int readings[DEBOUNCE_READINGS];
    int low_count = 0;

    for (int i = 0; i < DEBOUNCE_READINGS; i++) {
        readings[i] = read_rain_sensor();
        if (readings[i] < 0) return -1; // Propagate error
        gpioDelay(DEBOUNCE_DELAY * 1000); // Delay in microseconds
    }

    for (int i = 0; i < DEBOUNCE_READINGS; i++) {
        if (readings[i] == 0) {
            low_count++;
        }
    }

    return (low_count >= RAIN_THRESHOLD) ? 0 : 1; // Return 0 if rain detected, 1 otherwise
}

// Function to control the motor
void control_motor(int state) {
    if (state == 1) { // Close window
        gpioWrite(MOTOR_IN1_PIN, 1);
        gpioWrite(MOTOR_IN2_PIN, 0);
        gpioPWM(MOTOR_PWM_PIN, MOTOR_DUTY_CYCLE);
        log_event("Closing window...");
        gpioDelay(MOTOR_DURATION * 1000000); // Delay in microseconds
        gpioWrite(MOTOR_IN1_PIN, 0);
        gpioWrite(MOTOR_IN2_PIN, 0);
        gpioPWM(MOTOR_PWM_PIN, 0);
        log_event("Window closed.");
    } else { // Stop motor
        gpioWrite(MOTOR_IN1_PIN, 0);
        gpioWrite(MOTOR_IN2_PIN, 0);
        gpioPWM(MOTOR_PWM_PIN, 0);
        log_event("Stopping motor...");
    }
}

// Function to log events to syslog
void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    syslog(LOG_INFO, "%s: %s", timestamp, message);
}

int main() {
    // Initialize syslog
    openlog("window_control", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return 1; // Exit with error code
    }

    // Set GPIO modes
    gpioSetMode(RAIN_SENSOR_PIN, PI_INPUT);
    gpioSetMode(MOTOR_IN1_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_IN2_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_PWM_PIN, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(MOTOR_PWM_PIN, MOTOR_FREQUENCY);

    log_event("Program started");

    time_t last_check_time = 0;

    while (program_running) {
        time_t current_time = time(NULL);
        if (current_time - last_check_time >= 60) {
            int rain_detected = debounce_rain_sensor();
            if (rain_detected == 0) {
                log_event("Rain detected, closing window...");
                control_motor(1);
                last_check_time = current_time + 60; // Wait 60 seconds after closing
            } else if (rain_detected < 0) {
                log_event("Error reading rain sensor, skipping check.");
            } else {
                log_event("No rain detected.");
            }
        }
        gpioDelay(60000000); // Check every 60 seconds (60000000 microseconds)
    }

    cleanup();
    return 0;
}

