#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Define GPIO pins
#define DT_PIN 23
#define SCK_PIN 24
#define LOCK_PIN 17

// Define weight threshold (in grams)
#define WEIGHT_THRESHOLD 100

// Define lock activation time (in seconds)
#define LOCK_DURATION 5

// Define timeout duration (in milliseconds)
#define TIMEOUT_MS 100

// Global variables
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_hx711();
void activate_lock();
void deactivate_lock();
void log_event(const char *message);
void signal_handler(int signal);

// Function to read data from HX711
int read_hx711() {
    int data = 0;
    int timeout = 0;

    // Wait for DT pin to go low
    while (gpioRead(DT_PIN) == 1) {
        gpioDelay(1); // Small delay to prevent busy-waiting
        timeout++;
        if (timeout > TIMEOUT_MS) {
            log_event("Error: HX711 timeout waiting for DT low.");
            return -1; // Indicate timeout error
        }
    }

    // Read 24 bits of data
    for (int i = 0; i < 24; i++) {
        gpioWrite(SCK_PIN, 1);
        gpioDelay(1); // Clock pulse width
        data = data << 1;
        if (gpioRead(DT_PIN) == 1) {
            data++;
        }
        gpioWrite(SCK_PIN, 0);
        gpioDelay(1); // Clock pulse width
    }

    // Apply the 25th clock pulse for gain setting (channel A, gain 128)
    gpioWrite(SCK_PIN, 1);
    gpioDelay(1);
    gpioWrite(SCK_PIN, 0);
    gpioDelay(1);

    // Convert to signed 24-bit integer
    if (data & 0x800000) {
        data |= 0xFF000000;
    }

    return data;
}

// Function to activate the solenoid lock
void activate_lock() {
    gpioWrite(LOCK_PIN, 1); // Set GPIO HIGH
    log_event("Lock activated.");
}

// Function to deactivate the solenoid lock
void deactivate_lock() {
    gpioWrite(LOCK_PIN, 0); // Set GPIO LOW
    log_event("Lock deactivated.");
}

// Function to log events to a file
void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file != NULL) {
        fprintf(log_file, "%s: %s\n", timestamp, message);
        fflush(log_file); // Ensure immediate write to file
    } else {
        fprintf(stderr, "Error: Log file not opened. Message: %s\n", message);
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    log_event("Received signal, shutting down...");
    deactivate_lock(); // Ensure lock is deactivated on exit
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
