#define CALIBRATION_FILE "calibration.txt"

// Security log file
#define SECURITY_LOG "security.log"

// Timeout duration (ms)
#define TIMEOUT_DURATION 100

// Threshold weight (kg)
#define WEIGHT_THRESHOLD 5.0

// Solenoid activation duration (s)
#define SOLENOID_DURATION 5

// Global variables
static volatile int running = 1;
static double calibration_factor = 1.0; // Default calibration factor

// Function prototypes
int read_hx711();
double calibrate_weight();
double get_weight();
void activate_solenoid();
void log_event(double weight);
void signal_handler(int signal);
int initialize_gpio();
void cleanup_gpio();

// Function to read data from HX711
int read_hx711() {
    int data = 0;
    int timeout_count = 0;

    gpioSetMode(HX711_DATA_PIN, PI_INPUT);
    gpioSetMode(HX711_CLOCK_PIN, PI_OUTPUT);

    // Wait for data line to go low
    while (gpioRead(HX711_DATA_PIN) == 1) {
        gpioDelay(1); // 1 us delay
        timeout_count++;
        if (timeout_count > TIMEOUT_DURATION * 1000) { // Check for timeout
            fprintf(stderr, "Timeout reading HX711\n");
            return -1; // Indicate timeout error
        }
    }

    // Read 24 bits of data
    for (int i = 0; i < 24; i++) {
        gpioWrite(HX711_CLOCK_PIN, 1);
        gpioDelay(1); // 1 us delay
        data = data << 1;
        if (gpioRead(HX711_DATA_PIN) == 1) {
            data++;
        }
        gpioWrite(HX711_CLOCK_PIN, 0);
        gpioDelay(1); // 1 us delay
    }

    // Pulse the clock pin 1 more time to set the gain to 128
    gpioWrite(HX711_CLOCK_PIN, 1);
    gpioDelay(1); // 1 us delay
    gpioWrite(HX711_CLOCK_PIN, 0);
    gpioDelay(1); // 1 us delay

    // Convert to signed 24-bit integer
    if (data & 0x800000) {
        data |= 0xFF000000;
    }

    return data;
}

// Function to calibrate the weight
double calibrate_weight() {
    double known_weight;
    int raw_value;

    printf("Enter the known weight in grams: ");
    if (scanf("%lf", &known_weight) != 1) {
        fprintf(stderr, "Invalid input for known weight\n");
        return -1.0;
    }

    printf("Placing the known weight on the load cell...\n");
    gpioDelay(2000); // Allow time for the weight to stabilize

    raw_value = read_hx711();
    if (raw_value == -1) {
        fprintf(stderr, "Error reading HX711 during calibration\n");
        return -1.0;
    }

    calibration_factor = (double)raw_value / known_weight;
    printf("Calibration factor: %lf\n", calibration_factor);

