        fprintf(stderr, "Error opening security log file for writing\n");
        return;
    }
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, Weight: %.2lf kg\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, weight);
    fclose(fp);
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    running = 0;
    cleanup_gpio();
    exit(0);
}

// Function to initialize GPIO
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(SOLENOID_PIN, PI_OUTPUT);
    gpioWrite(SOLENOID_PIN, 0); // Ensure solenoid is initially off

    // Read calibration factor from file
    FILE *fp = fopen(CALIBRATION_FILE, "r");
    if (fp == NULL) {
        fprintf(stderr, "Calibration file not found. Calibrating...\n");
        if (calibrate_weight() < 0) {
            fprintf(stderr, "Calibration failed\n");
            cleanup_gpio();
            return 1;
        }
    } else {
        if (fscanf(fp, "%lf", &calibration_factor) != 1) {
            fprintf(stderr, "Error reading calibration factor from file. Calibrating...\n");
            fclose(fp);
            if (calibrate_weight() < 0) {
                fprintf(stderr, "Calibration failed\n");
                cleanup_gpio();
                return 1;
            }
        } else {
            printf("Calibration factor loaded from file: %lf\n", calibration_factor);
        }
        fclose(fp);
    }

    return 0;
}

// Function to cleanup GPIO
void cleanup_gpio() {
    gpioWrite(SOLENOID_PIN, 0); // Ensure solenoid is off
    gpioTerminate();
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Weight monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        double weight = get_weight();
        if (weight > 0) {
            printf("Weight: %.2lf kg\n", weight);

            if (weight > WEIGHT_THRESHOLD) {
                activate_solenoid();
                log_event(weight);
            }
        } else {
            fprintf(stderr, "Error getting weight\n");
        }

        gpioDelay(100); // Delay between readings
    }

    return 0;
}

