#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO_PIN 18
#define CONFIG_FILE "watering.conf"
#define LOG_FILE "watering.log"

volatile sig_atomic_t program_running = 1;

// Function to read the watering duration from the configuration file
int read_watering_duration(const char *filename) {
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open configuration file %s\n", filename);
        return -1;
    }

    char line[256];
    if (fgets(line, sizeof(line), fp) == NULL) {
        fprintf(stderr, "Error: Could not read from configuration file %s\n", filename);
        fclose(fp);
        return -1;
    }

    fclose(fp);

    char *token = strtok(line, "=");
    if (token == NULL || strtok(NULL, "=") == NULL) {
        fprintf(stderr, "Error: Malformed configuration file %s\n", filename);
        return -1;
    }

    char *duration_str = strtok(NULL, "=");
    if (duration_str == NULL) {
        fprintf(stderr, "Error: Malformed configuration file %s\n", filename);
        return -1;
    }

    char *endptr;
    long duration = strtol(duration_str, &endptr, 10);

    if (*endptr != '\0' || duration <= 0 || duration > 3600) {
        fprintf(stderr, "Error: Invalid watering duration in %s. Must be between 1 and 3600 seconds.\n", filename);
        return -1;
    }

    return (int)duration;
}

// Function to control the valve
void control_valve(int gpio_pin, int state) {
    gpioWrite(gpio_pin, state);
}

// Function to log the watering event
void log_watering_event(int duration) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open log file %s\n", LOG_FILE);
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d - Watering duration: %d seconds\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, duration);

    fclose(fp);
}

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    program_running = 0;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as output
    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    gpioWrite(GPIO_PIN, 0); // Initialize to LOW (valve off)

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Read watering duration from configuration file
    int duration = read_watering_duration(CONFIG_FILE);
    if (duration < 0) {
        gpioTerminate();
        return 1;
    }

    printf("Watering duration: %d seconds\n", duration);

    // Main loop
    while (program_running) {
        // Turn on the valve
        control_valve(GPIO_PIN, 1);
        printf("Valve ON\n");

        // Wait for the configured duration
        time_sleep(duration);

        // Turn off the valve
        control_valve(GPIO_PIN, 0);
        printf("Valve OFF\n");

        // Log the watering event
        log_watering_event(duration);

        // Exit the loop after one cycle
        program_running = 0;
    }

    // Ensure valve is off on exit
    control_valve(GPIO_PIN, 0);

    // Terminate pigpio
    gpioTerminate();

    printf("Program finished.\n");
    return 0;
}

