// Define GPIO pins
#define LEFT_SENSOR_PIN 4
#define MIDDLE_SENSOR_PIN 17
#define RIGHT_SENSOR_PIN 27
#define LEFT_MOTOR_PWM_PIN 22
#define LEFT_MOTOR_DIR_PIN 23
#define RIGHT_MOTOR_PWM_PIN 24
#define RIGHT_MOTOR_DIR_PIN 25

// Define motor speeds
#define BASE_SPEED 150
#define TURN_SPEED 75

// Define PWM frequency
#define PWM_FREQUENCY 1000

// Global variables
FILE *log_file;
int running = 1;

// Function prototypes
int read_sensor(int pin);
void set_motor_speed(int motor_pin, int dir_pin, int speed);
void control_robot(int left_sensor, int middle_sensor, int right_sensor);
void log_data(int left_sensor, int middle_sensor, int right_sensor, int left_speed, int right_speed);
void signal_handler(int signal);

// Function to read sensor value
int read_sensor(int pin) {
    return !gpioRead(pin); // Active low
}

// Function to set motor speed and direction
void set_motor_speed(int motor_pin, int dir_pin, int speed) {
    gpioPWM(motor_pin, speed);
    gpioWrite(dir_pin, 1); // Forward direction
}

// Function to control the robot based on sensor input
void control_robot(int left_sensor, int middle_sensor, int right_sensor) {
    int left_speed = 0;
    int right_speed = 0;

    if (middle_sensor == 0) {
        // Drive straight
        left_speed = BASE_SPEED;
        right_speed = BASE_SPEED;
    } else if (left_sensor == 0 && middle_sensor == 1 && right_sensor == 1) {
        // Turn right
        left_speed = TURN_SPEED;
        right_speed = BASE_SPEED;
    } else if (left_sensor == 1 && middle_sensor == 1 && right_sensor == 0) {
        // Turn left
        left_speed = BASE_SPEED;
        right_speed = TURN_SPEED;
    } else {
        // Stop
        left_speed = 0;
        right_speed = 0;
    }

    set_motor_speed(LEFT_MOTOR_PWM_PIN, LEFT_MOTOR_DIR_PIN, left_speed);
    set_motor_speed(RIGHT_MOTOR_PWM_PIN, RIGHT_MOTOR_DIR_PIN, right_speed);
}

// Function to log data to file
void log_data(int left_sensor, int middle_sensor, int right_sensor, int left_speed, int right_speed) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s,%d,%d,%d,%d,%d\n", timestamp, left_sensor, middle_sensor, right_sensor, left_speed, right_speed);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Ctrl+C pressed. Stopping motors and exiting.\n");
    running = 0;
    set_motor_speed(LEFT_MOTOR_PWM_PIN, LEFT_MOTOR_DIR_PIN, 0);
    set_motor_speed(RIGHT_MOTOR_PWM_PIN, RIGHT_MOTOR_DIR_PIN, 0);
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(LEFT_SENSOR_PIN, PI_INPUT);
    gpioSetMode(MIDDLE_SENSOR_PIN, PI_INPUT);
    gpioSetMode(RIGHT_SENSOR_PIN, PI_INPUT);
    gpioSetMode(LEFT_MOTOR_PWM_PIN, PI_OUTPUT);
    gpioSetMode(LEFT_MOTOR_DIR_PIN, PI_OUTPUT);
    gpioSetMode(RIGHT_MOTOR_PWM_PIN, PI_OUTPUT);
    gpioSetMode(RIGHT_MOTOR_DIR_PIN, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(LEFT_MOTOR_PWM_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(RIGHT_MOTOR_PWM_PIN, PWM_FREQUENCY);

    // Open log file
    log_file = fopen("trace_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Install signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (running) {
        // Read sensor values
        int left_sensor = read_sensor(LEFT_SENSOR_PIN);
        int middle_sensor = read_sensor(MIDDLE_SENSOR_PIN);
        int right_sensor = read_sensor(RIGHT_SENSOR_PIN);

        // Control robot
        control_robot(left_sensor, middle_sensor, right_sensor);

        // Log data
        log_data(left_sensor, middle_sensor, right_sensor, BASE_SPEED, BASE_SPEED); // Log base speed

        // Delay
        gpioDelay(10000); // 10 ms
    }

    // Cleanup (should not reach here if signal handler works correctly)
    set_motor_speed(LEFT_MOTOR_PWM_PIN, LEFT_MOTOR_DIR_PIN, 0);
    set_motor_speed(RIGHT_MOTOR_PWM_PIN, RIGHT_MOTOR_DIR_PIN, 0);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

