// Constants
#define I2C_BUS 1
#define BH1750_ADDR 0x23
#define GROW_LAMP_GPIO 23
#define LUX_THRESHOLD 150
#define MEASUREMENT_DELAY_MS 180
#define LOG_FILE "grow_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_bh1750(int i2c_handle);
void control_relay(int gpio_pin, int state);
void log_data(FILE *log_file, int lux_value, int relay_state);
void signal_handler(int signal);

// Function to read illuminance from BH1750 sensor
int read_bh1750(int i2c_handle) {
    char config_mode = 0x10; // Continuous high resolution mode
    char buffer[2];
    int lux_value;

    if (i2cWriteDevice(i2c_handle, &config_mode, 1) != 0) {
        fprintf(stderr, "Error: Failed to configure BH1750.\n");
        return -1;
    }

    gpioDelay(MEASUREMENT_DELAY_MS * 1000); // Delay for measurement

    if (i2cReadDevice(i2c_handle, buffer, 2) != 2) {
        fprintf(stderr, "Error: Failed to read data from BH1750.\n");
        return -1;
    }

    lux_value = (buffer[0] << 8) | buffer[1];
    return lux_value;
}

// Function to control the grow lamp relay
void control_relay(int gpio_pin, int state) {
    gpioWrite(gpio_pin, state);
}

// Function to log data to file
void log_data(FILE *log_file, int lux_value, int relay_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Lux: %d, Relay: %s\n", timestamp, lux_value, relay_state ? "ON" : "OFF");
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

