    int lux_value;
    int relay_state = 0; // 0 = OFF, 1 = ON

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus. %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO23 as output
    gpioSetMode(GROW_LAMP_GPIO, PI_OUTPUT);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    printf("Grow lamp control system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        lux_value = read_bh1750(i2c_handle);

        if (lux_value < 0) {
            fprintf(stderr, "Error: Failed to read lux value. Retrying...\n");
            log_data(log_file, -1, relay_state); // Log error
            gpioDelay(1000000); // Wait 1 second before retrying
            continue;
        }

        if (lux_value < LUX_THRESHOLD && relay_state == 0) {
            control_relay(GROW_LAMP_GPIO, 1);
            relay_state = 1;
            log_data(log_file, lux_value, relay_state);
            printf("Lux: %d, Relay: ON\n", lux_value);
        } else if (lux_value >= LUX_THRESHOLD && relay_state == 1) {
            control_relay(GROW_LAMP_GPIO, 0);
            relay_state = 0;
            log_data(log_file, lux_value, relay_state);
            printf("Lux: %d, Relay: OFF\n", lux_value);
        } else {
            log_data(log_file, lux_value, relay_state);
        }

        gpioDelay(500000); // Check every 0.5 seconds
    }

    // Cleanup
    control_relay(GROW_LAMP_GPIO, 0); // Turn off relay
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    printf("Grow lamp control system stopped.\n");
    return 0;
}

