#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define LOCK_BUTTON_PIN 21
#define UNLOCK_BUTTON_PIN 22
#define SERVO_PIN 18

// Define servo pulse width limits
#define SERVO_MIN_PULSE_WIDTH 500
#define SERVO_MAX_PULSE_WIDTH 2500

// Define servo positions
#define LOCK_POSITION 1000
#define UNLOCK_POSITION 2000

// Debounce delay in milliseconds
#define DEBOUNCE_DELAY 100

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    if (signal == SIGINT) {
        program_running = 0;
        printf("\nCaught SIGINT, exiting gracefully...\n");
    }
}

// Function to initialize the pigpio library and GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    // Set GPIO modes
    gpioSetMode(LOCK_BUTTON_PIN, PI_INPUT);
    gpioSetMode(UNLOCK_BUTTON_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Set pull-up resistors for buttons
    gpioSetPullUpDown(LOCK_BUTTON_PIN, PI_PUD_UP);
    gpioSetPullUpDown(UNLOCK_BUTTON_PIN, PI_PUD_UP);

    return 0;
}

// Function to read the state of a button with debouncing
int read_button(int pin) {
    int current_state = gpioRead(pin);
    gpioDelay(DEBOUNCE_DELAY * 1000); // Debounce delay
    if (gpioRead(pin) == current_state) {
        return current_state;
    } else {
        return -1; // Indicate no stable reading
    }
}

// Function to set the servo pulse width
int set_servo_position(int pulse_width) {
    if (pulse_width < SERVO_MIN_PULSE_WIDTH || pulse_width > SERVO_MAX_PULSE_WIDTH) {
        fprintf(stderr, "Error: Pulse width out of range (%d)\n", pulse_width);
        return -1;
    }

    gpioServo(SERVO_PIN, pulse_width);
    return 0;
}

// Function to handle the lock button press
void handle_lock_button() {
    if (set_servo_position(LOCK_POSITION) == 0) {
        printf("Door locked\n");
    }
}

// Function to handle the unlock button press
void handle_unlock_button() {
    if (set_servo_position(UNLOCK_POSITION) == 0) {
        printf("Door unlocked\n");
    }
}

int main() {
    // Install signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Door lock control program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        int lock_button_state = read_button(LOCK_BUTTON_PIN);
        int unlock_button_state = read_button(UNLOCK_BUTTON_PIN);

        if (lock_button_state == 0) {
            handle_lock_button();
        } else if (unlock_button_state == 0) {
            handle_unlock_button();
        }

        gpioDelay(10000); // Small delay to prevent busy-waiting
    }

    // Clean up GPIO resources before exiting
    gpioTerminate();
    printf("GPIO resources released. Exiting.\n");

    return 0;
}

