        return;
    }

    // Wait for the specified duration
    gpioDelay(duration_ms * 1000); // pigpioDelay takes microseconds

    // Deactivate the motor
    if (gpioWrite(gpio_pin, 0) != 0) {
        fprintf(stderr, "Failed to write LOW to GPIO%d\n", gpio_pin);
    }
}

