#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <sys/time.h>
#include <pigpio.h>
#include <zmq.h>

// Constants
#define SOUND_SENSOR_GPIO 17
#define ALARM_LED_GPIO 27
#define ZMQ_ENDPOINT "tcp://*:5555"
#define ZMQ_SUB_ENDPOINT "tcp://localhost:5555"
#define ZMQ_TOPIC "SOUND_ALERTS"
#define ALARM_DURATION_MS 1000
#define POLL_INTERVAL_MS 10

// Global variables
static volatile int running = 1;
static void *zmq_context = NULL;
static void *zmq_socket = NULL;

// Function prototypes
int initialize_gpio();
int initialize_zmq();
void cleanup();
void signal_handler(int signal);
int sound_sensor_mode();
int alarm_node_mode();
void publish_alert();
int subscribe_and_alert();

// Signal handler
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    running = 0;
    cleanup();
    exit(0);
}

// Initialize GPIO
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(SOUND_SENSOR_GPIO, PI_INPUT);
    gpioSetMode(ALARM_LED_GPIO, PI_OUTPUT);
    gpioWrite(ALARM_LED_GPIO, 0); // Ensure LED is off initially

    return 0;
}

// Initialize ZeroMQ
int initialize_zmq() {
    zmq_context = zmq_ctx_new();
    if (!zmq_context) {
        perror("zmq_ctx_new failed");
        return -1;
    }

    zmq_socket = zmq_socket(zmq_context, ZMQ_PUB);
    if (!zmq_socket) {
        perror("zmq_socket failed");
        zmq_ctx_destroy(zmq_context);
        return -1;
    }

    int rc = zmq_bind(zmq_socket, ZMQ_ENDPOINT);
    if (rc != 0) {
        perror("zmq_bind failed");
        zmq_close(zmq_socket);
        zmq_ctx_destroy(zmq_context);
        return -1;
    }

    return 0;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up resources...\n");

    if (zmq_socket) {
        zmq_close(zmq_socket);
    }
    if (zmq_context) {
        zmq_ctx_destroy(zmq_context);
    }

    gpioWrite(ALARM_LED_GPIO, 0); // Turn off LED
    gpioTerminate();
}

// Sound sensor mode
int sound_sensor_mode() {
    printf("Sound sensor mode started...\n");

