#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <time.h>
#include <mosquitto.h>
#include <pigpio.h>

// Configuration
#define GPIO_PIN 17
#define MQTT_BROKER "localhost"
#define MQTT_PORT 1883
#define MQTT_TOPIC "ir/decoded"
#define PULSE_BUFFER_SIZE 100

// NEC Protocol Constants
#define NEC_HEADER_MARK 9000  // 9 ms
#define NEC_HEADER_SPACE 4500 // 4.5 ms
#define NEC_BIT_MARK 560      // 560 us
#define NEC_ONE_SPACE 1690    // 1.69 ms
#define NEC_ZERO_SPACE 560    // 560 us
#define NEC_REPEAT_SPACE 2250 // 2.25 ms

// Global Variables
static volatile int running = 1;
static struct mosquitto *mosq = NULL;
static int pulse_buffer[PULSE_BUFFER_SIZE];
static int pulse_count = 0;
static int last_tick = 0;

// Function Prototypes
void signal_handler(int sig);
int init_gpio();
int init_mqtt();
void cleanup();
void ir_callback(int gpio, int level, uint32_t tick);
int decode_nec(int *pulse_buffer, int pulse_count, unsigned int *command, unsigned int *inverted_command);
int validate_command(unsigned int command, unsigned int inverted_command);
int publish_mqtt(unsigned int command);
void log_message(int priority, const char *message);

// Signal Handler
void signal_handler(int sig) {
    log_message(LOG_INFO, "Signal received, exiting...");
    running = 0;
}

// Initialize GPIO
int init_gpio() {
    if (gpioInitialise() < 0) {
        log_message(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP); // Enable pull-up resistor

    // Set alert function for falling edge
    gpioSetAlertFunc(GPIO_PIN, ir_callback);

    return 0;
}

// Initialize MQTT
int init_mqtt() {
    mosquitto_lib_init();

    mosq = mosquitto_new(NULL, true, NULL);
    if (!mosq) {
        log_message(LOG_ERR, "Failed to create mosquitto instance");
        return -1;
    }

    int rc = mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, 60);
    if (rc != MOSQ_ERR_SUCCESS) {
        log_message(LOG_ERR, "Failed to connect to MQTT broker");
        mosquitto_destroy(mosq);
        mosq = NULL;
        return -1;
    }

    rc = mosquitto_loop_start(mosq);
    if (rc != MOSQ_ERR_SUCCESS) {
        log_message(LOG_ERR, "Failed to start MQTT loop");
        mosquitto_destroy(mosq);
        mosq = NULL;
        return -1;
    }

    return 0;
}

// Cleanup resources
void cleanup() {
    log_message(LOG_INFO, "Cleaning up resources...");

    if (mosq) {
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
    }

    gpioSetAlertFunc(GPIO_PIN, NULL); // Disable callback
    gpioTerminate();

    closelog();
}

// IR callback function
void ir_callback(int gpio, int level, uint32_t tick) {
    if (level == 0) { // Falling edge
        int pulse_length = tick - last_tick;
        last_tick = tick;

        if (pulse_count < PULSE_BUFFER_SIZE) {
            pulse_buffer[pulse_count++] = pulse_length;
        } else {
            log_message(LOG_WARNING, "Pulse buffer overflow!");
            pulse_count = 0; // Reset buffer
        }
    }
}

// Decode NEC protocol
int decode_nec(int *pulse_buffer, int pulse_count, unsigned int *command, unsigned int *inverted_command) {
    if (pulse_count < 68) { // Minimum 68 pulses (9ms + 32 data bits + 16 bits of trailing space)
        log_message(LOG_WARNING, "Too few pulses received");
        return -1;
    }

    // Check for valid header
    if (pulse_buffer[0] < NEC_HEADER_MARK * 0.8 || pulse_buffer[0] > NEC_HEADER_MARK * 1.2 ||
        pulse_buffer[1] < NEC_HEADER_SPACE * 0.8 || pulse_buffer[1] > NEC_HEADER_SPACE * 1.2) {
        log_message(LOG_WARNING, "Invalid NEC header");
        return -1;
    }

    *command = 0;
    *inverted_command = 0;

    for (int i = 2; i < 34; i++) {
        if (pulse_buffer[2 * i] < NEC_BIT_MARK * 0.8 || pulse_buffer[2 * i] > NEC_BIT_MARK * 1.2) {
            log_message(LOG_WARNING, "Invalid bit mark");
            return -1;
        }

        if (pulse_buffer[2 * i + 1] > NEC_ONE_SPACE * 0.8) {
            if (pulse_buffer[2 * i + 1] < NEC_ONE_SPACE * 1.2) {
                *command = (*command << 1) | 1;
            } else if (pulse_buffer[2 * i + 1] < NEC_REPEAT_SPACE * 0.8) {
                *command = (*command << 1) | 0;
            } else {
                log_message(LOG_WARNING, "Invalid bit space");
                return -1;
            }
        } else {
            *command = (*command << 1) | 0;
        }
    }

    return 0;
}

// Validate command
int validate_command(unsigned int command, unsigned int inverted_command) {
    if ((command ^ inverted_command) != 0xFF) {
        log_message(LOG_WARNING, "Command validation failed");
        return -1;
    }
    return 0;
}

// Publish to MQTT
int publish_mqtt(unsigned int command) {
    char payload[50];
    snprintf(payload, sizeof(payload), "{\"command\": %u}", command);

    int rc = mosquitto_publish(mosq, NULL, MQTT_TOPIC, strlen(payload), payload, 0, false);
    if (rc != MOSQ_ERR_SUCCESS) {
        log_message(LOG_ERR, "Failed to publish MQTT message");
        return -1;
    }

    log_message(LOG_INFO, payload);
    return 0;
}

// Log messages to syslog
void log_message(int priority, const char *message) {
    syslog(priority, message);
}

int main() {
    // Initialize syslog
    openlog("ir_decoder", LOG_PID | LOG_CONS, LOG_USER);

    // Signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (init_gpio() != 0) {
        cleanup();
        return 1;
    }

    // Initialize MQTT
    if (init_mqtt() != 0) {
        cleanup();
        return 1;
    }

    log_message(LOG_INFO, "IR decoder started");

    // Main loop
    while (running) {
        if (pulse_count > 0) {
            unsigned int command, inverted_command;

            if (decode_nec(pulse_buffer, pulse_count, &command, &inverted_command) == 0) {
                if (validate_command(command, inverted_command) == 0) {
                    publish_mqtt(command);
                }
            }
            pulse_count = 0; // Reset pulse buffer
        }
        mosquitto_loop(mosq, 0, 1); // Non-blocking MQTT loop
        usleep(10000); // Sleep for 10ms
    }

    // Cleanup resources
    cleanup();

    return 0;
}

