#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <signal.h>
#include <errno.h>
#include <math.h>

#define I2C_BUS "/dev/i2c-1"
#define MULTICAST_ADDR "239.255.255.250"
#define MULTICAST_PORT 5005
#define BH1750_CONTINUOUS_HIGH_RES_MODE 0x10
#define SLEEP_MS 180
#define SLEEP_SEC 1

// Sensor addresses
const int sensor_addresses[] = {0x23, 0x24, 0x25, 0x26};
const int num_sensors = sizeof(sensor_addresses) / sizeof(sensor_addresses[0]);

// Global termination flag
volatile sig_atomic_t terminate = 0;

// Signal handler
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Function to read lux value from a single BH1750 sensor
float read_bh1750(int i2c_fd, int address) {
    unsigned char buf[2];
    int bytes_read;

    // Set the I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, address) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02x: %s\n", address, strerror(errno));
        return NAN;
    }

    // Send start conversion command
    if (write(i2c_fd, &BH1750_CONTINUOUS_HIGH_RES_MODE, 1) != 1) {
        fprintf(stderr, "Error writing to I2C device 0x%02x: %s\n", address, strerror(errno));
        return NAN;
    }

    // Wait for measurement (180ms)
    usleep(SLEEP_MS * 1000);

    // Read 2 bytes of data
    bytes_read = read(i2c_fd, buf, 2);
    if (bytes_read != 2) {
        fprintf(stderr, "Error reading from I2C device 0x%02x: %s (read %d bytes)\n", address, strerror(errno), bytes_read);
        return NAN;
    }

    // Convert data to lux value
    unsigned int raw_value = (buf[0] << 8) | buf[1];
    float lux = (float)raw_value / 1.2;

    return lux;
}

// Function to format sensor data into a semicolon-separated string
char* format_data(float lux_values[], int num_sensors) {
    char *data_string = malloc(256); // Allocate memory for the string
    if (data_string == NULL) {
        fprintf(stderr, "Error allocating memory for data string\n");
        return NULL;
    }
    data_string[0] = '\0'; // Initialize as an empty string

    for (int i = 0; i < num_sensors; i++) {
        char sensor_str[64];
        snprintf(sensor_str, sizeof(sensor_str), "%d,%.1f;", i + 1, lux_values[i]);
        strcat(data_string, sensor_str);
    }

    // Remove the trailing semicolon
    if (strlen(data_string) > 0) {
        data_string[strlen(data_string) - 1] = '\0';
    }

    return data_string;
}

// Function to send data via UDP multicast
int send_udp_multicast(const char *data) {
    int sockfd;
    struct sockaddr_in addr;
    int ttl = 1; // Time-to-live for multicast packets

    // Create socket
    if ((sockfd = socket(AF_INET, SOCK_DGRAM, 0)) < 0) {
        fprintf(stderr, "Error creating socket: %s\n", strerror(errno));
        return -1;
    }

    // Set multicast TTL
    if (setsockopt(sockfd, IPPROTO_IP, IP_MULTICAST_TTL, (void *)&ttl, sizeof(ttl)) < 0) {
        fprintf(stderr, "Error setting multicast TTL: %s\n", strerror(errno));
        close(sockfd);
        return -1;
    }

    // Configure destination address
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = inet_addr(MULTICAST_ADDR);
    addr.sin_port = htons(MULTICAST_PORT);

    // Send data
    if (sendto(sockfd, data, strlen(data), 0, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        fprintf(stderr, "Error sending data: %s\n", strerror(errno));
        close(sockfd);
        return -1;
    }

    // Close socket
    close(sockfd);
    return 0;
}

int main() {
    int i2c_fd;
    float lux_values[num_sensors];
    char *data_string;

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    if ((i2c_fd = open(I2C_BUS, O_RDWR)) < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read sensor data
        for (int i = 0; i < num_sensors; i++) {
            lux_values[i] = read_bh1750(i2c_fd, sensor_addresses[i]);
            if (isnan(lux_values[i])) {
                fprintf(stderr, "Error reading sensor %d\n", i + 1);
            }
        }

        // Format data
        data_string = format_data(lux_values, num_sensors);
        if (data_string != NULL) {
            // Send data
            if (send_udp_multicast(data_string) != 0) {
                fprintf(stderr, "Error sending UDP multicast\n");
            }

            // Free allocated memory
            free(data_string);
        }

        // Sleep for 1 second
        sleep(SLEEP_SEC);
    }

    // Close I2C bus
    close(i2c_fd);

    fprintf(stderr, "Program terminated cleanly.\n");
    return 0;
}

