#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define AWM7300V_ADDR 0x28
#define FLOW_RATE_FILE "airflow_log.txt"
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 100

// Global variables
int i2c_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure for sensor configuration (example)
typedef struct {
    int i2c_bus;
    int i2c_address;
    const char *log_file_name;
} sensor_config_t;

// Function prototypes
int initialize_i2c(int bus, int addr);
int read_sensor_data(int handle, uint8_t *data, int count);
float convert_to_slpm(uint16_t raw_value);
int log_flow_rate(const char *filename, float flow_rate);
void signal_handler(int signal);
void cleanup();

// Function to initialize the I2C bus
int initialize_i2c(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", handle);
        return -1;
    }
    return handle;
}

// Function to read data from the sensor with retries
int read_sensor_data(int handle, uint8_t *data, int count) {
    int result, retries = 0;
    while (retries < RETRY_COUNT) {
        result = i2cReadDevice(handle, (char *)data, count);
        if (result == count) {
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read failed (attempt %d): %d\n", retries + 1, result);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries++;
        }
    }
    fprintf(stderr, "I2C read failed after %d retries.\n", RETRY_COUNT);
    return -1; // Failure after retries
}

// Function to convert raw data to SLPM
float convert_to_slpm(uint16_t raw_value) {
    // Mask the 14-bit flow value
    uint16_t masked_value = raw_value & 0x3FFF;

    // Convert to SLPM (example formula, adjust based on datasheet)
    float slpm = (float)masked_value * 0.05; // Example conversion
    return slpm;
}

// Function to log the flow rate to a file
int log_flow_rate(const char *filename, float flow_rate) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    log_file = fopen(filename, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1;
    }

    fprintf(log_file, "%s, %.2f SLPM\n", timestamp, flow_rate);
    fclose(log_file);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function to close I2C and log file
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        fprintf(stderr, "I2C bus closed.\n");
    }
    if (log_file != NULL) {
        fclose(log_file);
        fprintf(stderr, "Log file closed.\n");
    }
    gpioTerminate();
    fprintf(stderr, "pigpio terminated.\n");
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    i2c_handle = initialize_i2c(I2C_BUS, AWM7300V_ADDR);
    if (i2c_handle < 0) {
        cleanup();
        return 1;
    }

    uint8_t sensor_data[2];
    uint16_t raw_flow_value;
    float flow_rate;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(i2c_handle, sensor_data, 2) == 0) {
            // Combine the two bytes into a 16-bit value
            raw_flow_value = (sensor_data[0] << 8) | sensor_data[1];

            // Convert to SLPM
            flow_rate = convert_to_slpm(raw_flow_value);

            // Log the flow rate
            if (log_flow_rate(FLOW_RATE_FILE, flow_rate) != 0) {
                fprintf(stderr, "Error logging flow rate.\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data.\n");
        }

        gpioDelay(1000000); // Delay for 1 second (1000000 microseconds)
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

