        return -1;
    }

    // Configure SMUX (e.g., set integration time)
    if (i2cWriteByteData(i2c_handle, AS7341_CFG6, 0x00) < 0) { // Example: Set integration time to default
        fprintf(stderr, "Error: Failed to configure SMUX.\n");
        return -1;
    }

    // Enable spectral measurement
    if (i2cWriteByteData(i2c_handle, AS7341_ENABLE, AS7341_PON | AS7341_SP_EN) < 0) {
