#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define DEFAULT_I2C_ADDRESS 0x1D
#define DEFAULT_SAMPLING_INTERVAL 1
#define DEFAULT_FILENAME "seismic_data.csv"
#define ERROR_LOG_FILENAME "seismic_error.log"
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10

// D7S Register Addresses
#define D7S_REG_X_LSB 0x28
#define D7S_REG_X_MSB 0x29
#define D7S_REG_Y_LSB 0x2A
#define D7S_REG_Y_MSB 0x2B
#define D7S_REG_Z_LSB 0x2C
#define D7S_REG_Z_MSB 0x2D

// Global variables
int i2c_handle;
FILE *data_file = NULL;
FILE *error_file = NULL;
int running = 1;
int i2c_address = DEFAULT_I2C_ADDRESS;
int sampling_interval = DEFAULT_SAMPLING_INTERVAL;
char *filename = DEFAULT_FILENAME;

// Structure to hold sensor data
typedef struct {
    float x_g;
    float y_g;
    float z_g;
} sensor_data_t;

// Function prototypes
int initialize_i2c(int address);
int read_sensor_data(sensor_data_t *data);
int write_data_to_csv(sensor_data_t data);
void log_error(const char *message);
void signal_handler(int signal);
void cleanup();

// Function to initialize the I2C bus
int initialize_i2c(int address) {
    i2c_handle = i2cOpen(1, address, 0); // Bus 1, address, flags
    if (i2c_handle < 0) {
        log_error("Failed to open I2C bus");
        return -1;
    }
    return 0;
}

// Function to read sensor data
int read_sensor_data(sensor_data_t *data) {
    char buffer[6];
    int retries = RETRY_COUNT;
    int bytes_read;

    while (retries > 0) {
        bytes_read = i2cReadI2CBlockData(i2c_handle, D7S_REG_X_LSB, buffer, 6);
        if (bytes_read == 6) {
            // Combine LSB and MSB, and convert to g (adjust scaling as needed)
            int16_t x = (int16_t)((buffer[1] << 8) | buffer[0]);
            int16_t y = (int16_t)((buffer[3] << 8) | buffer[2]);
            int16_t z = (int16_t)((buffer[5] << 8) | buffer[4]);

            data->x_g = (float)x / 1000.0; // Example scaling, adjust as needed
            data->y_g = (float)y / 1000.0;
            data->z_g = (float)z / 1000.0;
            return 0; // Success
        } else {
            log_error("I2C read failed, retrying...");
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries--;
        }
    }

    log_error("I2C read failed after multiple retries");
    return -1; // Failure
}

// Function to write data to CSV file
int write_data_to_csv(sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (data_file == NULL) {
        log_error("Data file is not open");
        return -1;
    }

    fprintf(data_file, "%s,%.3f,%.3f,%.3f\n", timestamp, data.x_g, data.y_g, data.z_g);
    fflush(data_file); // Ensure data is written immediately
    return 0;
}

// Function to log errors
void log_error(const char *message) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(error_file, "%s: %s\n", timestamp, message);
    fflush(error_file);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

// Cleanup function to close resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (data_file != NULL) {
        fclose(data_file);
    }
    if (error_file != NULL) {
        fclose(error_file);
    }
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    int opt;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "a:i:f:")) != -1) {
        switch (opt) {
            case 'a':
                i2c_address = strtol(optarg, NULL, 0);
                break;
            case 'i':
                sampling_interval = strtol(optarg, NULL, 0);
                break;
            case 'f':
                filename = optarg;
                break;
            default:
                fprintf(stderr, "Usage: %s [-a i2c_address] [-i sampling_interval] [-f filename]\n", argv[0]);
                return 1;
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open error log file
    error_file = fopen(ERROR_LOG_FILENAME, "a");
    if (error_file == NULL) {
        fprintf(stderr, "Failed to open error log file\n");
        gpioTerminate();
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c(i2c_address) != 0) {
        fclose(error_file);
        gpioTerminate();
        return 1;
    }

    // Open data file
    data_file = fopen(filename, "a");
    if (data_file == NULL) {
        log_error("Failed to open data file");
        cleanup();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    sensor_data_t sensor_data;

    // Main loop
    while (running) {
        if (read_sensor_data(&sensor_data) == 0) {
            if (write_data_to_csv(sensor_data) != 0) {
                log_error("Failed to write data to CSV");
            }
        } else {
            log_error("Failed to read sensor data");
        }

        gpioDelay(sampling_interval * 1000000); // Delay in microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

