#include <netinet/in.h>
#include <arpa/inet.h>
#include <signal.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <fcntl.h>
#include <sys/types.h>
#include <sys/stat.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define BH1750_ADDR 0x23
#define CONTINUOUS_HIGH_RES_MODE 0x10
#define MULTICAST_ADDR "239.255.255.250"
#define MULTICAST_PORT 5000
#define TTL 1

// Global variables
int i2c_fd = -1;
int udp_socket = -1;

// Function prototypes
int init_i2c(const char *bus);
int read_bh1750(int fd);
float convert_to_lux(uint16_t raw_value);
int send_udp_multicast(float lux_value);
void signal_handler(int signal);
void cleanup();

// Structure to hold configuration data
typedef struct {
    char i2c_bus[20];
    char multicast_address[20];
    int multicast_port;
    int ttl;
} config_t;

// Initialize I2C bus
int init_i2c(const char *bus) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// Read raw light value from BH1750
int read_bh1750(int fd) {
    uint8_t config_cmd = CONTINUOUS_HIGH_RES_MODE;
    uint8_t buffer[2];

    // Send configuration command
    if (write(fd, &config_cmd, 1) != 1) {
        perror("Error writing to I2C device");
        return -1;
    }

    // Wait for measurement (at least 180ms)
    usleep(200000); // 200ms

    // Read 2 bytes of data
    if (read(fd, buffer, 2) != 2) {
        perror("Error reading from I2C device");
        return -1;
    }

    // Combine bytes to form 16-bit value
    uint16_t raw_value = (buffer[0] << 8) | buffer[1];
    return raw_value;
}

// Convert raw value to lux
float convert_to_lux(uint16_t raw_value) {
    return (float)raw_value / 1.2;
}

// Send lux value via UDP multicast
int send_udp_multicast(float lux_value) {
    struct sockaddr_in addr;
    socklen_t addrlen = sizeof(addr);
    char buffer[32];

    // Format lux value to string
    snprintf(buffer, sizeof(buffer), "%.2f", lux_value);

    // Configure destination address
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = inet_addr(MULTICAST_ADDR);
    addr.sin_port = htons(MULTICAST_PORT);

    // Send data
    if (sendto(udp_socket, buffer, strlen(buffer), 0, (struct sockaddr *)&addr, addrlen) < 0) {
        perror("Error sending UDP multicast");
        return -1;
    }

    return 0;
}

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    cleanup();
    exit(0);
}

// Cleanup resources
void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (udp_socket != -1) {
        close(udp_socket);
    }
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_fd = init_i2c(I2C_BUS);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to initialize I2C. Exiting.\n");
        return 1;
    }

    // Create UDP socket
    udp_socket = socket(AF_INET, SOCK_DGRAM, 0);
    if (udp_socket < 0) {
        perror("Error creating socket");
        cleanup();
        return 1;
    }

    // Set TTL for multicast
    int ttl = TTL;
    if (setsockopt(udp_socket, IPPROTO_IP, IP_MULTICAST_TTL, &ttl, sizeof(ttl)) < 0) {
        perror("Error setting TTL");
        cleanup();
        return 1;
    }

    // Main loop
    while (1) {
        // Read light value
        int raw_value = read_bh1750(i2c_fd);
        if (raw_value < 0) {
            fprintf(stderr, "Failed to read BH1750. Retrying in 1 second.\n");
            sleep(1);
            continue;
        }

        // Convert to lux
        float lux_value = convert_to_lux(raw_value);

        // Send via UDP multicast
        if (send_udp_multicast(lux_value) < 0) {
            fprintf(stderr, "Failed to send UDP multicast. Retrying in 1 second.\n");
        }

        // Wait for 1 second
        sleep(1);
    }

    return 0;
}

