#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <errno.h>
#include <sys/select.h>
#include <sys/time.h>

// Configuration
#define UART_DEVICE "/dev/ttyS0"
#define BAUD_RATE 921600
#define MAGIC_WORD_SIZE 8
#define MAGIC_WORD "AWR1642_MagicWord"
#define TLV_TYPE_RANGE_VELOCITY 1 // Example TLV type
#define DATA_FILE "radar_data.csv"
#define MAX_FRAME_SIZE 65535 // Maximum frame size (adjust as needed)

// Global variables
volatile sig_atomic_t program_running = 1;
int uart_fd = -1;
FILE *data_file = NULL;

// Structure for TLV header
typedef struct {
    uint16_t type;
    uint16_t length;
} tlv_header_t;

// Function prototypes
int uart_init(const char *device, int baud_rate);
int uart_read(int fd, unsigned char *buffer, size_t size);
int uart_write(int fd, const unsigned char *buffer, size_t size);
int uart_close(int fd);
int parse_data(unsigned char *buffer, size_t size);
int validate_magic_word(unsigned char *buffer, size_t size);
int extract_range_velocity(unsigned char *buffer, size_t size, float *range, float *velocity);
int log_data(float range, float velocity);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    program_running = 0;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully.\n", signal);
}

// UART initialization function
int uart_init(const char *device, int baud_rate) {
    int fd = open(device, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd == -1) {
        fprintf(stderr, "Error opening UART %s: %s\n", device, strerror(errno));
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        fprintf(stderr, "Error getting termios attributes: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    cfsetospeed(&tty, baud_rate);
    cfsetispeed(&tty, baud_rate);

    tty.c_cflag |= (CLOCAL | CREAD);    /* ignore modem controls */
    tty.c_cflag &= ~CSIZE;             /* mask the character size bits */
    tty.c_cflag |= CS8;              /* 8-bit characters */
    tty.c_cflag &= ~(PARENB | PARODD); /* no parity */
    tty.c_cflag &= ~CSTOPB;            /* 1 stop bit */
    tty.c_cflag &= ~CRTSCTS;           /* no hardware flowcontrol */

    tty.c_iflag &= ~(IGNBRK | BRKINT | PARMRK | ISTRIP | INLCR | IGNCR | ICRNL | IXON);
    tty.c_lflag &= ~(ECHO | ECHONL | ICANON | ISIG | IEXTEN);
    tty.c_oflag &= ~OPOST;

    tty.c_cc[VMIN] = 0;  // read doesn't block
    tty.c_cc[VTIME] = 5; // 0.5 seconds read timeout

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        fprintf(stderr, "Error setting termios attributes: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

// UART read function with timeout
int uart_read(int fd, unsigned char *buffer, size_t size) {
    fd_set readfds;
    struct timeval timeout;

    FD_ZERO(&readfds);
    FD_SET(fd, &readfds);

    timeout.tv_sec = 1; // Timeout after 1 second
    timeout.tv_usec = 0;

    int retval = select(fd + 1, &readfds, NULL, NULL, &timeout);

    if (retval == -1) {
        fprintf(stderr, "Error in select(): %s\n", strerror(errno));
        return -1;
    } else if (retval == 0) {
        fprintf(stderr, "Timeout reading from UART.\n");
        return 0; // Timeout
    } else {
        ssize_t bytes_read = read(fd, buffer, size);
        if (bytes_read == -1) {
            fprintf(stderr, "Error reading from UART: %s\n", strerror(errno));
            return -1;
        }
        return (int)bytes_read;
    }
}

// UART write function
int uart_write(int fd, const unsigned char *buffer, size_t size) {
    ssize_t bytes_written = write(fd, buffer, size);
    if (bytes_written == -1) {
        fprintf(stderr, "Error writing to UART: %s\n", strerror(errno));
        return -1;
    }
    return (int)bytes_written;
}

// UART close function
int uart_close(int fd) {
    if (close(fd) == -1) {
        fprintf(stderr, "Error closing UART: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Magic word validation function
int validate_magic_word(unsigned char *buffer, size_t size) {
    if (size < MAGIC_WORD_SIZE) {
        return 0; // Not enough data
    }

    for (int i = 0; i < MAGIC_WORD_SIZE; i++) {
        if (buffer[i] != MAGIC_WORD[i]) {
            return 0; // Magic word mismatch
        }
    }
    return 1; // Magic word valid
}

// TLV parsing function
int parse_data(unsigned char *buffer, size_t size) {
    size_t offset = 0;
    while (offset < size) {
        if (offset + sizeof(tlv_header_t) > size) {
            fprintf(stderr, "Incomplete TLV header.\n");
            return -1; // Incomplete TLV header
        }

        tlv_header_t *header = (tlv_header_t *)(buffer + offset);
        uint16_t type = ntohs(header->type);
        uint16_t length = ntohs(header->length);

        if (offset + sizeof(tlv_header_t) + length > size) {
            fprintf(stderr, "TLV length exceeds buffer size.\n");
            return -1; // TLV length exceeds buffer size
        }

        if (type == TLV_TYPE_RANGE_VELOCITY) {
            float range, velocity;
            if (extract_range_velocity(buffer + offset + sizeof(tlv_header_t), length, &range, &velocity) == 0) {
                log_data(range, velocity);
            } else {
                fprintf(stderr, "Error extracting range and velocity.\n");
            }
        }

        offset += sizeof(tlv_header_t) + length;
    }
    return 0;
}

// Range and velocity extraction function
int extract_range_velocity(unsigned char *buffer, size_t size, float *range, float *velocity) {
    if (size < 8) { // Assuming 4 bytes for range and 4 bytes for velocity
        fprintf(stderr, "Insufficient data for range and velocity.\n");
        return -1;
    }

    memcpy(range, buffer, 4);
    memcpy(velocity, buffer + 4, 4);

    // Byte swap if needed (adjust based on sensor endianness)
    *range = ntohl(*(uint32_t *)range);
    *velocity = ntohl(*(uint32_t *)velocity);

    return 0;
}

// Data logging function
int log_data(float range, float velocity) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(data_file, "%s,%.2f,%.2f\n", timestamp, range, velocity);
    fflush(data_file); // Ensure data is written to file immediately

    return 0;
}

// Cleanup function
void cleanup() {
    if (uart_fd != -1) {
        uart_close(uart_fd);
    }
    if (data_file != NULL) {
        fclose(data_file);
    }
    // Add any other cleanup tasks here
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize UART
    uart_fd = uart_init(UART_DEVICE, BAUD_RATE);
    if (uart_fd == -1) {
        fprintf(stderr, "UART initialization failed.\n");
        return 1;
    }

    // Open data file
    data_file = fopen(DATA_FILE, "a");
    if (data_file == NULL) {
        fprintf(stderr, "Error opening data file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Write CSV header if the file is newly created
    fseek(data_file, 0, SEEK_END);
    long file_size = ftell(data_file);
    if (file_size == 0) {
        fprintf(data_file, "timestamp,object_index,range_m,velocity_mps\n");
    }

    unsigned char buffer[MAX_FRAME_SIZE];
    size_t buffer_index = 0;

    // Main loop
    while (program_running) {
        int bytes_read = uart_read(uart_fd, buffer + buffer_index, MAX_FRAME_SIZE - buffer_index);
        if (bytes_read > 0) {
            buffer_index += bytes_read;

            // Process complete frames
            while (buffer_index >= MAGIC_WORD_SIZE) {
                if (validate_magic_word(buffer, buffer_index)) {
                    // Find the end of the frame (assuming a maximum frame size)
                    size_t frame_size = MAGIC_WORD_SIZE;
                    for (size_t i = MAGIC_WORD_SIZE; i < buffer_index; i++) {
                        if (i + sizeof(tlv_header_t) + 8 <= buffer_index) { // Check for enough data for a TLV
                            tlv_header_t *header = (tlv_header_t *)(buffer + i);
                            uint16_t type = ntohs(header->type);
                            uint16_t length = ntohs(header->length);

                            if (i + sizeof(tlv_header_t) + length <= buffer_index) {
                                frame_size = i + sizeof(tlv_header_t) + length;
                                break;
                            }
                        }
                    }

                    if (parse_data(buffer, frame_size) == 0) {
                        // Shift the remaining data to the beginning of the buffer
                        memmove(buffer, buffer + frame_size, buffer_index - frame_size);
                        buffer_index -= frame_size;
                    } else {
                        fprintf(stderr, "Error parsing data.\n");
                    }
                } else {
                    // Shift the first byte to the beginning of the buffer
                    memmove(buffer, buffer + 1, buffer_index - 1);
                    buffer_index--;
                }
            }
        } else if (bytes_read < 0) {
            fprintf(stderr, "Error reading from UART, exiting.\n");
            break;
        }
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

