#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <pigpio.h>

// Define GPIO pins for the sensors
#define LEFT_SENSOR_PIN 4
#define MIDDLE_SENSOR_PIN 17
#define RIGHT_SENSOR_PIN 27

// Define UART device and baud rate
#define UART_DEVICE "/dev/ttyAMA0"
#define BAUD_RATE 115200

// Global variable for the UART handle
int uart_handle = -1;

// Function prototypes
int read_sensor(int pin);
void log_sensor_data(int left, int middle, int right);
void emergency_stop();
void signal_handler(int signal);

// Function to read the sensor value from a given GPIO pin
int read_sensor(int pin) {
    return gpioRead(pin);
}

// Function to log the sensor data with a timestamp
void log_sensor_data(int left, int middle, int right) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s - Left: %d, Middle: %d, Right: %d\n", timestamp, left, middle, right);
}

// Function to send the emergency stop message over UART
void emergency_stop() {
    const char *message = "EMERGENCY STOP!\n";
    int bytes_written = gpioSerialWrite(uart_handle, message, strlen(message));

    if (bytes_written < 0) {
        fprintf(stderr, "Error writing to UART: %s\n", strerror(errno));
    }
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);

    // Close the UART port if it's open
    if (uart_handle >= 0) {
        gpioSerialReadClose(uart_handle);
    }

    // Terminate the pigpio library
    gpioTerminate();

    exit(0);
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs with pull-up resistors
    gpioSetMode(LEFT_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(LEFT_SENSOR_PIN, PI_PUD_UP);
    gpioSetMode(MIDDLE_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(MIDDLE_SENSOR_PIN, PI_PUD_UP);
    gpioSetMode(RIGHT_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(RIGHT_SENSOR_PIN, PI_PUD_UP);

    // Open the UART port
    uart_handle = gpioSerialReadOpen(UART_DEVICE, BAUD_RATE, 0); // 0 for no flags
    if (uart_handle < 0) {
        fprintf(stderr, "Error opening UART: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        // Read sensor values
        int left = read_sensor(LEFT_SENSOR_PIN);
        int middle = read_sensor(MIDDLE_SENSOR_PIN);
        int right = read_sensor(RIGHT_SENSOR_PIN);

        // Log sensor data
        log_sensor_data(left, middle, right);

        // Check for emergency stop condition
        if (left == 0 && middle == 0 && right == 0) {
            emergency_stop();
        }

        // Delay for 100ms
        gpioDelay(100000); // 100ms = 100000 microseconds
    }

    return 0;
}

